-- ACA self-hosted baseline: the whole schema in one migration.
--
-- Generated by scripts/oss/build-baseline.py from production. Do not edit by
-- hand; change production, then rebuild.
--
-- After `supabase db reset`:
--   1. Set the Vault secrets in supabase/sql/vault_secrets.example.sql.
--   2. Optional: ALTER DATABASE postgres SET app.house_org_id = '<your org id>';
--      (the organization that owns public buying signals; leave unset if unused)
--   3. Deploy the edge functions, then run supabase/sql/cron_jobs.sql.

CREATE OR REPLACE FUNCTION public.aca_house_org_id()
RETURNS uuid
LANGUAGE sql
STABLE
AS $$ SELECT nullif(current_setting('app.house_org_id', true), '')::uuid $$;




SET statement_timeout = 0;
SET lock_timeout = 0;
SET idle_in_transaction_session_timeout = 0;
