CREATE OR REPLACE FUNCTION "public"."_public_signal_company_id"("p_key" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  SELECT substr(md5(COALESCE(p_key,'')), 1, 16);
$$;


ALTER FUNCTION "public"."_public_signal_company_id"("p_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_public_signal_mask_name"("p_name" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  SELECT CASE
    WHEN btrim(COALESCE(p_name,'')) = '' THEN 'Someone'
    WHEN strpos(btrim(p_name), ' ') = 0 THEN btrim(p_name)
    ELSE split_part(btrim(p_name), ' ', 1)
         || ' ' || upper(left(regexp_replace(btrim(p_name), '^.*\s', ''), 1)) || '.'
  END;
$$;


ALTER FUNCTION "public"."_public_signal_mask_name"("p_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_public_signal_person_card_is_eligible"("card" "jsonb") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
  SELECT COALESCE(card ->> 'has_linkedin', 'false') = 'true'
     AND public.signal_person_title_is_senior(card ->> 'title');
$$;


ALTER FUNCTION "public"."_public_signal_person_card_is_eligible"("card" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_public_signal_type_label"("p_type" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  SELECT CASE p_type
    WHEN 'funding'        THEN 'Funding'
    WHEN 'acquisition'    THEN 'Acquisition'
    WHEN 'hiring'         THEN 'Hiring'
    WHEN 'hiring_demand'  THEN 'Hiring demand'
    WHEN 'job_change'     THEN 'Job change'
    WHEN 'executive_hire' THEN 'Executive hire'
    WHEN 'customer_win'   THEN 'Customer win'
    WHEN 'award'          THEN 'Award'
    WHEN 'growth'         THEN 'Growth'
    ELSE initcap(replace(COALESCE(p_type,''), '_', ' '))
  END;
$$;


ALTER FUNCTION "public"."_public_signal_type_label"("p_type" "text") OWNER TO "postgres";


