CREATE OR REPLACE FUNCTION "public"."abandon_zombie_list_building_jobs"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  zombie RECORD;
  v_killed INT;
BEGIN
  FOR zombie IN
    SELECT id, updated_at
    FROM list_building_jobs
    WHERE status = 'running'
      AND updated_at < now() - interval '30 minutes'
    LIMIT 50
  LOOP
    UPDATE list_building_jobs
    SET status = 'failed',
        error_message = COALESCE(error_message, '')
                        || ' [zombie: no heartbeat for >30 min, abandoned by janitor]',
        completed_at = now(),
        updated_at = now()
    WHERE id = zombie.id;

    SELECT public.cancel_lb_job_work_items(zombie.id) INTO v_killed;

    RAISE LOG '[lb-zombie-janitor] abandoned job % (stale since %), drained % queue items',
      zombie.id, zombie.updated_at, v_killed;
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."abandon_zombie_list_building_jobs"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."aca_split_linkedin_display_name"("raw" "text") RETURNS TABLE("first_name" "text", "last_name" "text")
    LANGUAGE "plpgsql" IMMUTABLE
    AS $_$
DECLARE
  s text;
  tokens text[];
  tail text;
  -- Credentials, roles and generational suffixes that appear as trailing
  -- tokens, never as surnames.
  trailing_noise text[] := ARRAY[
    'md','phd','mba','cfa','cpa','esq','jd','rn','dds','dvm','csm',
    'mpa','msc','bsc','ba','ma','fca','cfei','rfc','mib','scmp','pmp',
    'cissp','cfp','pe','aia','lmft','lcsw','mph','edd','psyd','bfp',
    'hons','cma','cia','chre','cpm','clu','chfc',
    'ceo','cto','cfo','coo','cmo','cio','founder','cofounder',
    'co-founder','president','director','coach','author','expert',
    'consultant','speaker','investor','advisor','mentor',
    'jr','sr','ii','iii','iv','v'
  ];
  -- Round, curly, square and full-width bracket pairs.
  bracket_re text := '[([{' || chr(65288) || chr(65339) || '][^)\]}' || chr(65289) || chr(65341) || ']*[)\]}' || chr(65289) || chr(65341) || ']';
  sep_re text := '\s+[-' || chr(8211) || chr(8212) || '|' || chr(8226) || chr(183) || '/]\s+.*$';
  -- Keep only what a name is made of: letters (Unicode-aware, so accents and
  -- non-Latin scripts survive), space, period, apostrophe, hyphen.
  keep_re text := '[^[:alpha:][:space:].''' || chr(8217) || '-]';
BEGIN
  s := btrim(COALESCE(raw, ''));

  -- Bracketed asides first, so a comma or separator inside one can't strand
  -- its opening bracket.
  s := regexp_replace(s, bracket_re, ' ', 'g');
  -- A comma introduces credentials on LinkedIn; it is never "Last, First".
  s := split_part(s, ',', 1);
  -- A separator introduces a headline.
  s := regexp_replace(s, sep_re, '');
  s := regexp_replace(s, keep_re, '', 'g');
  s := btrim(regexp_replace(s, '\s+', ' ', 'g'));

  -- Trim edge punctuation BEFORE the honorific match: decoration is often glued
  -- to the title ("<emoji>Dr. Sirisha K."), which would otherwise defeat the
  -- leading anchor and leave first_name = 'Dr.'. A trailing period survives so
  -- truncated surnames stay natural ("Aaron C.").
  s := regexp_replace(s, '^[^[:alpha:]]+', '');
  s := regexp_replace(s, '[^[:alpha:].]+$', '');
  s := regexp_replace(s, '^(mr|mrs|ms|miss|dr|prof|sir|madam|mx|rev|fr|capt|lt|col)\.?\s+', '', 'i');

  IF s = '' THEN
    RETURN QUERY SELECT NULL::text, NULL::text;
    RETURN;
  END IF;

  tokens := regexp_split_to_array(s, '\s+');

  -- Never eat the whole name: the first token is always a candidate given name.
  WHILE array_length(tokens, 1) > 1 LOOP
    tail := lower(regexp_replace(tokens[array_length(tokens, 1)], '[.]', '', 'g'));
    -- A lone letter is an abbreviated surname, not noise. LinkedIn truncates
    -- surnames constantly ("Varshaa V."), and 'v'/'i' would otherwise collide
    -- with the Roman-numeral suffixes and collapse the name to one token.
    IF length(tail) < 2 THEN
      EXIT;
    END IF;
    IF tail = ANY(trailing_noise) THEN
      tokens := tokens[1:array_length(tokens, 1) - 1];
    ELSE
      EXIT;
    END IF;
  END LOOP;

  -- A lone token is overwhelmingly a brand account ("GojiberryAI"), not a
  -- mononymous person. No name is better than a wrong one in an email.
  IF array_length(tokens, 1) < 2 THEN
    RETURN QUERY SELECT NULL::text, NULL::text;
    RETURN;
  END IF;

  RETURN QUERY SELECT tokens[1], array_to_string(tokens[2:], ' ');
END;
$_$;


ALTER FUNCTION "public"."aca_split_linkedin_display_name"("raw" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."acquire_analysis_slot"("p_organization_id" "uuid", "p_slot_key" "text" DEFAULT 'analyze_company'::"text", "p_limit" integer DEFAULT 12, "p_lease_seconds" integer DEFAULT 300) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_live INTEGER;
  v_id UUID;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtextextended(p_organization_id::TEXT || ':' || p_slot_key, 0));

  DELETE FROM public.analysis_concurrency_slots
  WHERE organization_id = p_organization_id
    AND slot_key = p_slot_key
    AND expires_at < NOW();

  SELECT count(*) INTO v_live
  FROM public.analysis_concurrency_slots
  WHERE organization_id = p_organization_id
    AND slot_key = p_slot_key
    AND expires_at >= NOW();

  IF v_live >= p_limit THEN
    RETURN NULL;
  END IF;

  INSERT INTO public.analysis_concurrency_slots (organization_id, slot_key, expires_at)
  VALUES (p_organization_id, p_slot_key, NOW() + make_interval(secs => p_lease_seconds))
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;


ALTER FUNCTION "public"."acquire_analysis_slot"("p_organization_id" "uuid", "p_slot_key" "text", "p_limit" integer, "p_lease_seconds" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."acquire_openrouter_slot"("p_organization_id" "uuid", "p_max_requests" integer DEFAULT 60) RETURNS TABLE("acquired" boolean, "current_count" integer, "max_allowed" integer, "retry_after_ms" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_window_start TIMESTAMPTZ;
    v_current_count INTEGER;
    v_lock_key BIGINT;
BEGIN
    -- Current minute boundary
    v_window_start := date_trunc('minute', now());

    -- Advisory lock keyed on org UUID hash — serializes concurrent callers for same org
    v_lock_key := ('x' || left(replace(p_organization_id::text, '-', ''), 15))::bit(60)::bigint;
    PERFORM pg_advisory_xact_lock(v_lock_key);

    -- Upsert the window row
    INSERT INTO openrouter_rate_limits (organization_id, window_start, request_count, max_requests)
    VALUES (p_organization_id, v_window_start, 0, p_max_requests)
    ON CONFLICT (organization_id, window_start) DO NOTHING;

    -- Read current count
    SELECT ol.request_count INTO v_current_count
    FROM openrouter_rate_limits ol
    WHERE ol.organization_id = p_organization_id
      AND ol.window_start = v_window_start;

    -- Check limit
    IF v_current_count < p_max_requests THEN
        -- Increment and grant
        UPDATE openrouter_rate_limits
        SET request_count = request_count + 1
        WHERE organization_id = p_organization_id
          AND window_start = v_window_start;

        RETURN QUERY SELECT
            true,
            v_current_count + 1,
            p_max_requests,
            0;
    ELSE
        -- Over limit: calculate ms until window expires
        RETURN QUERY SELECT
            false,
            v_current_count,
            p_max_requests,
            GREATEST(0, (EXTRACT(EPOCH FROM (v_window_start + INTERVAL '60 seconds' - now())) * 1000)::INTEGER);
    END IF;
END;
$$;


ALTER FUNCTION "public"."acquire_openrouter_slot"("p_organization_id" "uuid", "p_max_requests" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."acquire_webhook_dispatcher_lease"("p_lease" interval DEFAULT '00:02:00'::interval) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_ok boolean;
BEGIN
  UPDATE webhook_dispatcher_state
     SET lease_until = clock_timestamp() + p_lease
   WHERE id = true
     AND lease_until < clock_timestamp()
  RETURNING true INTO v_ok;

  RETURN COALESCE(v_ok, false);
END;
$$;


ALTER FUNCTION "public"."acquire_webhook_dispatcher_lease"("p_lease" interval) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."add_existing_signal_leads_to_list"("p_contact_ids" "uuid"[], "p_list_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_org uuid; v_added integer;
BEGIN
  SELECT l.organization_id INTO v_org FROM public.lead_lists l JOIN public.organization_members m ON m.organization_id=l.organization_id WHERE l.id=p_list_id AND l.status='active' AND m.user_id=auth.uid();
  IF v_org IS NULL THEN RETURN jsonb_build_object('ok',false,'error','forbidden_or_inactive_list'); END IF;
  INSERT INTO public.lead_list_members(list_id,contact_id,source_data)
  SELECT p_list_id,c.id,jsonb_build_object('source','custom_signal') FROM public.crm_contacts c
  WHERE c.organization_id=v_org AND c.id=ANY(COALESCE(p_contact_ids,'{}'::uuid[]))
  ON CONFLICT (list_id,contact_id) DO NOTHING;
  GET DIAGNOSTICS v_added = ROW_COUNT;
  RETURN jsonb_build_object('ok',true,'added',v_added);
END; $$;


ALTER FUNCTION "public"."add_existing_signal_leads_to_list"("p_contact_ids" "uuid"[], "p_list_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."add_leads_to_campaign"("p_campaign_id" "uuid", "p_contact_ids" "uuid"[]) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_added INTEGER := 0;
BEGIN
  -- Disable per-row metrics trigger during bulk insert
  ALTER TABLE campaign_lead_progress DISABLE TRIGGER trg_update_campaign_metrics;

  INSERT INTO campaign_lead_progress (
    campaign_id,
    contact_id,
    status,
    current_node_id,
    next_action_at,
    variation_index,
    is_test_contact,
    created_at,
    updated_at
  )
  SELECT
    p_campaign_id,
    cid,
    'pending',
    NULL,
    NOW(),
    (ROW_NUMBER() OVER () % 2)::INTEGER,
    false,
    NOW(),
    NOW()
  FROM unnest(p_contact_ids) AS cid
  WHERE NOT EXISTS (
    SELECT 1 FROM campaign_lead_progress clp
    WHERE clp.campaign_id = p_campaign_id
      AND clp.contact_id = cid
  );

  GET DIAGNOSTICS v_added = ROW_COUNT;

  -- Re-enable the trigger
  ALTER TABLE campaign_lead_progress ENABLE TRIGGER trg_update_campaign_metrics;

  -- Update campaign total_leads count once
  UPDATE linkedin_campaigns
  SET
    total_leads = (
      SELECT COUNT(*) FROM campaign_lead_progress
      WHERE campaign_id = p_campaign_id
    ),
    updated_at = NOW()
  WHERE id = p_campaign_id;

  RETURN v_added;
END;
$$;


ALTER FUNCTION "public"."add_leads_to_campaign"("p_campaign_id" "uuid", "p_contact_ids" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."add_leads_to_campaign"("p_campaign_id" "uuid", "p_contact_ids" "uuid"[]) IS 'Adds specific contacts to a running campaign';



CREATE OR REPLACE FUNCTION "public"."add_list_members"("p_organization_id" "uuid", "p_list_id" "uuid", "p_contact_ids" "uuid"[]) RETURNS TABLE("added" integer, "skipped" integer, "not_found" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_unique uuid[];
  v_valid integer;
  v_added integer;
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM lead_lists WHERE id = p_list_id AND organization_id = p_organization_id
  ) THEN
    RAISE EXCEPTION 'List not found' USING ERRCODE = 'P0002';
  END IF;

  SELECT coalesce(array_agg(DISTINCT x), '{}') INTO v_unique
  FROM unnest(coalesce(p_contact_ids, '{}')) x
  WHERE x IS NOT NULL;

  -- Only contacts of the list's own organization can join it.
  SELECT count(*) INTO v_valid
  FROM crm_contacts c
  WHERE c.id = ANY(v_unique) AND c.organization_id = p_organization_id;

  WITH ins AS (
    INSERT INTO lead_list_members (list_id, contact_id)
    SELECT p_list_id, c.id
    FROM crm_contacts c
    WHERE c.id = ANY(v_unique) AND c.organization_id = p_organization_id
    -- No conflict target: skips a contact already in the list AND a second
    -- contact sharing an email already in the list, instead of failing.
    ON CONFLICT DO NOTHING
    RETURNING 1
  )
  SELECT count(*) INTO v_added FROM ins;

  -- lead_count is maintained by the statement-level count trigger from the
  -- rows actually inserted, so no resync is needed here.
  RETURN QUERY SELECT v_added, v_valid - v_added, cardinality(v_unique) - v_valid;
END;
$$;


ALTER FUNCTION "public"."add_list_members"("p_organization_id" "uuid", "p_list_id" "uuid", "p_contact_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."add_public_signal_lead_to_list"("p_signal_id" "uuid", "p_person_id" "uuid", "p_list_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_signal public.public_signals;
  v_person record;
  v_org uuid;
  v_company_id uuid;
  v_contact_id uuid;
  v_added boolean := false;
BEGIN
  SELECT l.organization_id INTO v_org
  FROM public.lead_lists l
  JOIN public.organization_members m ON m.organization_id = l.organization_id
  WHERE l.id = p_list_id
    AND l.status = 'active'
    AND m.user_id = auth.uid();

  IF v_org IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'forbidden_or_inactive_list');
  END IF;

  SELECT * INTO v_signal
  FROM public.public_signals
  WHERE id = p_signal_id AND published;

  IF v_signal.id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'public_signal_not_found');
  END IF;
  IF COALESCE(v_signal.domain, '') = '' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'missing_exact_company_domain');
  END IF;

  SELECT vp.person_id AS id, vp.full_name, vp.title, vp.linkedin_url, vp.email
    INTO v_person
  FROM public.public_signal_visible_people vp
  WHERE vp.person_id = p_person_id
    AND vp.company_key = lower(v_signal.company_name);

  IF v_person.id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'eligible_lead_not_found');
  END IF;

  INSERT INTO public.crm_companies (
    organization_id, name, domain, website_url, linkedin_url,
    last_signal_at, enrichment_source, enrichment_data
  ) VALUES (
    v_org, v_signal.company_name, v_signal.domain, 'https://' || v_signal.domain,
    v_signal.company_linkedin_url, now(), 'public_signal',
    jsonb_build_object('public_signal_id', v_signal.id, 'signal_type', v_signal.signal_type, 'source_url', v_signal.source_url)
  )
  ON CONFLICT (organization_id, normalized_domain) WHERE normalized_domain IS NOT NULL
  DO UPDATE SET
    last_signal_at = EXCLUDED.last_signal_at,
    enrichment_data = EXCLUDED.enrichment_data
  RETURNING id INTO v_company_id;

  SELECT id INTO v_contact_id
  FROM public.crm_contacts
  WHERE organization_id = v_org
    AND primary_linkedin_url = v_person.linkedin_url
  LIMIT 1;

  IF v_contact_id IS NULL THEN
    INSERT INTO public.crm_contacts (
      organization_id, display_name, company, company_id, job_title,
      primary_linkedin_url, source, source_details
    ) VALUES (
      v_org, v_person.full_name, v_signal.company_name, v_company_id, v_person.title,
      v_person.linkedin_url, 'public_signal',
      jsonb_build_object('public_signal_id', v_signal.id, 'source_url', v_signal.source_url)
    )
    RETURNING id INTO v_contact_id;
  END IF;

  INSERT INTO public.lead_list_members (list_id, contact_id, source_data)
  VALUES (
    p_list_id,
    v_contact_id,
    jsonb_build_object('source', 'public_signal', 'public_signal_id', v_signal.id, 'source_url', v_signal.source_url)
  )
  ON CONFLICT (list_id, contact_id) DO NOTHING;
  v_added := FOUND;

  RETURN jsonb_build_object(
    'ok', true,
    'added', v_added,
    'contact_id', v_contact_id,
    'lead_name', v_person.full_name
  );
END;
$$;


ALTER FUNCTION "public"."add_public_signal_lead_to_list"("p_signal_id" "uuid", "p_person_id" "uuid", "p_list_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."add_public_signal_to_list"("p_signal_id" "uuid", "p_list_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_signal public.public_signals;
  v_org uuid;
  v_company_id uuid;
  v_person record;
  v_contact_id uuid;
  v_added integer := 0;
  v_existing integer := 0;
BEGIN
  SELECT l.organization_id INTO v_org FROM public.lead_lists l
  JOIN public.organization_members m ON m.organization_id = l.organization_id
  WHERE l.id = p_list_id AND l.status = 'active' AND m.user_id = auth.uid();
  IF v_org IS NULL THEN RETURN jsonb_build_object('ok',false,'error','forbidden_or_inactive_list'); END IF;

  SELECT * INTO v_signal FROM public.public_signals WHERE id = p_signal_id AND published;
  IF v_signal.id IS NULL THEN RETURN jsonb_build_object('ok',false,'error','public_signal_not_found'); END IF;
  IF COALESCE(v_signal.domain,'') = '' THEN RETURN jsonb_build_object('ok',false,'error','missing_exact_company_domain'); END IF;

  INSERT INTO public.crm_companies (organization_id,name,domain,website_url,linkedin_url,last_signal_at,enrichment_source,enrichment_data)
  VALUES (v_org,v_signal.company_name,v_signal.domain,'https://' || v_signal.domain,v_signal.company_linkedin_url,now(),'public_signal',jsonb_build_object('public_signal_id',v_signal.id,'signal_type',v_signal.signal_type,'source_url',v_signal.source_url))
  ON CONFLICT (organization_id, normalized_domain) WHERE normalized_domain IS NOT NULL DO UPDATE
    SET last_signal_at = EXCLUDED.last_signal_at, enrichment_data = EXCLUDED.enrichment_data
  RETURNING id INTO v_company_id;

  FOR v_person IN
    SELECT vp.full_name, vp.title, vp.linkedin_url
    FROM public.public_signal_visible_people vp
    WHERE vp.company_key = lower(v_signal.company_name)
  LOOP
    SELECT id INTO v_contact_id FROM public.crm_contacts
      WHERE organization_id=v_org AND primary_linkedin_url=v_person.linkedin_url LIMIT 1;
    IF v_contact_id IS NULL THEN
      INSERT INTO public.crm_contacts (organization_id,display_name,company,company_id,job_title,primary_linkedin_url,source,source_details)
      VALUES (v_org,v_person.full_name,v_signal.company_name,v_company_id,v_person.title,v_person.linkedin_url,'public_signal',jsonb_build_object('public_signal_id',v_signal.id,'source_url',v_signal.source_url))
      RETURNING id INTO v_contact_id;
    END IF;
    INSERT INTO public.lead_list_members (list_id,contact_id,source_data)
    VALUES (p_list_id,v_contact_id,jsonb_build_object('source','public_signal','public_signal_id',v_signal.id,'source_url',v_signal.source_url))
    ON CONFLICT (list_id,contact_id) DO NOTHING;
    IF FOUND THEN v_added := v_added + 1; ELSE v_existing := v_existing + 1; END IF;
  END LOOP;
  RETURN jsonb_build_object('ok',true,'added',v_added,'already_in_list',v_existing);
END; $$;


ALTER FUNCTION "public"."add_public_signal_to_list"("p_signal_id" "uuid", "p_list_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_list_public_signals"("p_limit" integer DEFAULT 50, "p_offset" integer DEFAULT 0, "p_search" "text" DEFAULT NULL::"text", "p_include_unpublished" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_limit  integer := LEAST(GREATEST(COALESCE(p_limit, 50), 1), 500);
  v_offset integer := GREATEST(COALESCE(p_offset, 0), 0);
  v_search text    := NULL;
  v_total  bigint  := 0;
  v_rows   jsonb   := '[]'::jsonb;
BEGIN
  IF NOT public._public_signals_caller_is_admin() THEN
    RETURN jsonb_build_object('ok', false, 'error', 'forbidden');
  END IF;
  IF p_search IS NOT NULL AND btrim(p_search) <> '' THEN
    v_search := '%' || lower(btrim(p_search)) || '%';
  END IF;

  WITH base AS (
    SELECT s.* FROM public.public_signals s
    WHERE (p_include_unpublished OR s.published)
      AND (v_search IS NULL
           OR lower(s.company_name) LIKE v_search
           OR lower(COALESCE(s.domain,'')) LIKE v_search
           OR lower(COALESCE(s.summary,'')) LIKE v_search)
  ),
  counted AS (SELECT count(*) AS total FROM base),
  paged AS (
    SELECT * FROM base
    ORDER BY signal_date DESC, created_at DESC
    LIMIT v_limit OFFSET v_offset
  )
  SELECT (SELECT total FROM counted),
         COALESCE(jsonb_agg(jsonb_build_object(
           'id', id,
           'company_name', company_name,
           'domain', domain,
           'signal_type', signal_type,
           'title', title,
           'signal_date', signal_date,
           'source_label', source_label,
           'source_url', source_url,
           'verified', verified,
           'published', published,
           'quality_score', quality_score,
           'created_at', created_at
         ) ORDER BY signal_date DESC, created_at DESC), '[]'::jsonb)
  INTO v_total, v_rows FROM paged;

  RETURN jsonb_build_object('ok', true, 'total_count', COALESCE(v_total,0),
    'limit', v_limit, 'offset', v_offset, 'signals', v_rows);
END;
$$;


ALTER FUNCTION "public"."admin_list_public_signals"("p_limit" integer, "p_offset" integer, "p_search" "text", "p_include_unpublished" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_set_public_signal_published"("p_id" "uuid", "p_published" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_row public.public_signals;
BEGIN
  IF NOT public._public_signals_caller_is_admin() THEN
    RETURN jsonb_build_object('ok', false, 'error', 'forbidden');
  END IF;
  UPDATE public.public_signals
     SET published = p_published
   WHERE id = p_id
  RETURNING * INTO v_row;
  IF v_row.id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_found');
  END IF;
  RETURN jsonb_build_object('ok', true, 'id', v_row.id,
    'company_name', v_row.company_name, 'published', v_row.published);
END;
$$;


ALTER FUNCTION "public"."admin_set_public_signal_published"("p_id" "uuid", "p_published" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admit_campaign_trigger_event"("p_event_id" "uuid", "p_enroll" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  e campaign_trigger_events%ROWTYPE;
  c linkedin_campaigns%ROWTYPE;
  person crm_contacts%ROWTYPE;
  rule jsonb;
  eligible uuid[];
  list_ids uuid[];
  start_id text;
  progress_id uuid;
  bound_account uuid;
  channel_sender_ids uuid[];
  history_sender_ids uuid[];
  confirmed_connection boolean := false;
  conversation_id uuid;
  source_list_id uuid;
  source_member_id uuid;
BEGIN
  SELECT * INTO e FROM campaign_trigger_events WHERE id = p_event_id FOR UPDATE;
  IF NOT FOUND OR e.status <> 'processing' THEN RETURN jsonb_build_object('allowed',false,'reason','Event is not processing'); END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(e.organization_id::text || ':' || e.contact_id::text,0));
  SELECT * INTO c FROM linkedin_campaigns WHERE id = e.campaign_id AND organization_id = e.organization_id FOR SHARE;
  IF NOT FOUND OR c.status <> 'active' THEN RETURN jsonb_build_object('allowed',false,'reason','Campaign is not active'); END IF;
  SELECT value INTO rule FROM jsonb_array_elements(c.entry_triggers) WHERE value->>'id' = e.trigger_id AND value->>'enabled' = 'true' LIMIT 1;
  IF rule IS NULL OR rule <> e.trigger_snapshot THEN RETURN jsonb_build_object('allowed',false,'reason','Trigger was changed or disabled'); END IF;
  SELECT * INTO person FROM crm_contacts WHERE id = e.contact_id AND organization_id = e.organization_id FOR SHARE;
  IF NOT FOUND THEN RETURN jsonb_build_object('allowed',false,'reason','Contact is outside this organization'); END IF;
  -- List additions originate in the database. Recheck the exact insertion, list
  -- selection and tenancy after the queued event has been claimed.
  IF e.event_type = 'list_member_added' THEN
    IF rule->>'type' IS DISTINCT FROM 'list_member_added'
      OR rule->>'channel' IS DISTINCT FROM 'any'
      OR rule->'accountIds' IS DISTINCT FROM '[]'::jsonb
      OR jsonb_typeof(rule->'listIds') IS DISTINCT FROM 'array'
      OR e.context->>'native' IS DISTINCT FROM 'true'
      OR e.account_id IS NOT NULL OR e.channel IS NOT NULL
      OR coalesce(e.context->>'listId','') !~* '^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$'
      OR coalesce(e.context->>'memberId','') !~* '^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$' THEN
      RETURN jsonb_build_object('allowed',false,'reason','List addition source is invalid');
    END IF;
    IF jsonb_array_length(rule->'listIds') NOT BETWEEN 1 AND 100 OR EXISTS (
      SELECT 1 FROM jsonb_array_elements(rule->'listIds') chosen
      WHERE jsonb_typeof(chosen) <> 'string' OR coalesce(chosen #>> '{}','') !~* '^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$'
    ) THEN RETURN jsonb_build_object('allowed',false,'reason','Selected lead lists are invalid'); END IF;
    source_list_id := (e.context->>'listId')::uuid;
    source_member_id := (e.context->>'memberId')::uuid;
    IF e.source_event_id IS DISTINCT FROM 'list_member_added:' || source_member_id::text
      OR NOT EXISTS (SELECT 1 FROM jsonb_array_elements_text(rule->'listIds') selected WHERE selected::uuid=source_list_id) THEN
      RETURN jsonb_build_object('allowed',false,'reason','Trigger no longer selects the source list');
    END IF;
    PERFORM 1 FROM lead_lists l WHERE l.id=source_list_id AND l.organization_id=e.organization_id
      AND l.status='active' AND NOT coalesce(l.is_smart,false) AND coalesce(l.source_type,'manual')<>'smart' FOR SHARE;
    IF NOT FOUND THEN RETURN jsonb_build_object('allowed',false,'reason','Source list is unavailable'); END IF;
    PERFORM 1 FROM lead_list_members m WHERE m.id=source_member_id AND m.list_id=source_list_id AND m.contact_id=person.id FOR SHARE;
    IF NOT FOUND THEN RETURN jsonb_build_object('allowed',false,'reason','Contact was removed from the source list'); END IF;
  END IF;
  IF person.status IN ('unsubscribed','do_not_contact','bounced') OR person.outreach_status IN ('unsubscribed','do_not_contact','bounced') THEN
    RETURN jsonb_build_object('allowed',false,'reason','Contact is suppressed');
  END IF;
  IF EXISTS (SELECT 1 FROM campaign_lead_progress WHERE campaign_id = c.id AND contact_id = person.id AND NOT coalesce(is_test_contact,false)) THEN
    RETURN jsonb_build_object('allowed',false,'reason','Contact is already enrolled in this campaign');
  END IF;
  IF EXISTS (SELECT 1 FROM lead_list_members WHERE contact_id = person.id AND list_id = ANY(coalesce(c.exclusion_list_ids,'{}'::uuid[]))) THEN
    RETURN jsonb_build_object('allowed',false,'reason','Contact is on an exclusion list');
  END IF;
  SELECT coalesce(array_agg(DISTINCT sender.value::uuid),'{}'::uuid[]) INTO history_sender_ids
    FROM jsonb_each(coalesce(c.sender_accounts,'{}'::jsonb)) channel
    CROSS JOIN LATERAL jsonb_array_elements_text(CASE WHEN jsonb_typeof(channel.value)='array' THEN channel.value ELSE '[]'::jsonb END) sender
    WHERE sender.value ~* '^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$';
  history_sender_ids:=ARRAY(SELECT DISTINCT x FROM unnest(history_sender_ids || coalesce(c.sender_account_ids,'{}'::uuid[])) x);
  IF contact_excluded_by_campaign_history(e.organization_id,c.id,person.id,c.exclude_other_campaigns,c.exclude_same_sender,history_sender_ids) THEN
    RETURN jsonb_build_object('allowed',false,'reason','Campaign history excludes this contact');
  END IF;
  eligible := filter_contact_ids_by_criteria(e.organization_id,ARRAY[person.id],coalesce(c.enroll_filter_criteria,'{}'::jsonb));
  IF NOT person.id = ANY(coalesce(eligible,'{}'::uuid[])) THEN RETURN jsonb_build_object('allowed',false,'reason','Contact does not meet enrollment filters'); END IF;
  list_ids := coalesce(nullif(c.lead_list_ids,'{}'::uuid[]),CASE WHEN c.lead_list_id IS NOT NULL THEN ARRAY[c.lead_list_id] ELSE '{}'::uuid[] END);
  eligible := filter_contact_ids_by_pipeline_gate(e.organization_id,list_ids,'linkedin_campaign',c.id,ARRAY[person.id]);
  IF NOT person.id = ANY(coalesce(eligible,'{}'::uuid[])) THEN RETURN jsonb_build_object('allowed',false,'reason','Lead processing has not approved this contact'); END IF;
  -- An unrelated attached list must not bypass the triggering list's pipeline.
  IF source_list_id IS NOT NULL THEN
    eligible := filter_contact_ids_by_pipeline_gate(e.organization_id,ARRAY[source_list_id],'linkedin_campaign',c.id,ARRAY[person.id]);
    IF NOT person.id = ANY(coalesce(eligible,'{}'::uuid[])) THEN RETURN jsonb_build_object('allowed',false,'reason','Source list processing has not approved this contact'); END IF;
  END IF;
  IF EXISTS (SELECT 1 FROM campaign_trigger_events other WHERE other.organization_id=e.organization_id AND other.contact_id=e.contact_id AND other.id<>e.id AND other.status='processing' AND other.decision_state IN ('reserved','provider_completed','provider_unknown') AND other.lease_until>now()) THEN
    RETURN jsonb_build_object('allowed',false,'reason','Another campaign entry is processing this contact');
  END IF;
  SELECT n->>'id' INTO start_id FROM jsonb_array_elements(coalesce(c.sequence_nodes,'[]'::jsonb)) n WHERE n->>'type' = 'start' LIMIT 1;
  IF start_id IS NULL OR NOT EXISTS (SELECT 1 FROM jsonb_array_elements(coalesce(c.sequence_edges,'[]'::jsonb)) edge WHERE edge->>'source'=start_id) THEN
    RETURN jsonb_build_object('allowed',false,'reason','Campaign sequence has no connected start step');
  END IF;
  -- Incoming native events stay with the account that actually received them.
  SELECT coalesce(array_agg(value::uuid),'{}'::uuid[]) INTO channel_sender_ids
    FROM jsonb_array_elements_text(coalesce(c.sender_accounts->coalesce(e.channel,'linkedin'),'[]'::jsonb)) value
    WHERE value ~* '^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$';
  IF e.channel='linkedin' THEN channel_sender_ids:=ARRAY(SELECT DISTINCT x FROM unnest(channel_sender_ids || coalesce(c.sender_account_ids,'{}'::uuid[])) x); END IF;
  IF e.account_id IS NOT NULL AND (e.event_type IN ('connection_request','message_received','post_comment') OR e.channel='linkedin') THEN
    IF NOT e.account_id = ANY(channel_sender_ids) THEN
      RETURN jsonb_build_object('allowed',false,'reason','Receiving account must be selected as a campaign sender');
    END IF;
    bound_account := e.account_id;
  END IF;
  IF e.event_type = 'connection_request' AND e.account_id IS NULL THEN RETURN jsonb_build_object('allowed',false,'reason','Invitation account is missing'); END IF;
  IF bound_account IS NOT NULL AND NOT EXISTS (SELECT 1 FROM unipile_accounts a WHERE a.id=bound_account AND a.organization_id=e.organization_id AND a.status='active'
    AND lower(a.provider)=CASE WHEN e.channel='linkedin' THEN 'linkedin' WHEN e.channel='instagram' THEN 'instagram' WHEN e.channel='whatsapp' THEN 'whatsapp' WHEN e.channel='telegram' THEN 'telegram' ELSE lower(a.provider) END) THEN
    RETURN jsonb_build_object('allowed',false,'reason','Receiving account is disconnected');
  END IF;
  UPDATE campaign_trigger_events SET decision_state='reserved' WHERE id=e.id AND decision_state IS DISTINCT FROM 'provider_completed';
  IF NOT p_enroll THEN RETURN jsonb_build_object('allowed',true); END IF;
  IF e.event_type='connection_request' AND e.provider_decision IS DISTINCT FROM 'accept' THEN
    RETURN jsonb_build_object('allowed',false,'reason','Invitation has not been accepted');
  END IF;
  confirmed_connection := e.channel='linkedin' AND (e.provider_decision='accept' OR (e.context->>'native'='true' AND e.context->>'connected'='true'));
  IF (e.context->>'conversationId') ~* '^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$' THEN
    SELECT cv.id INTO conversation_id FROM crm_conversations cv WHERE cv.id=(e.context->>'conversationId')::uuid AND cv.organization_id=e.organization_id AND cv.contact_id=e.contact_id;
  END IF;
  INSERT INTO campaign_lead_progress(campaign_id,contact_id,status,current_node_id,next_action_at,is_test_contact,sender_account_id,channel_used,crm_conversation_id,connection_sent_at,connection_accepted_at,entry_context)
  VALUES(c.id,person.id,'pending',start_id,now(),false,bound_account,e.channel,conversation_id,CASE WHEN confirmed_connection THEN now() ELSE NULL END,CASE WHEN confirmed_connection THEN now() ELSE NULL END,jsonb_build_object('event_id',e.id,'trigger_id',e.trigger_id,'type',e.event_type,'account_id',bound_account,'channel',e.channel,'native',e.context->'native'))
  RETURNING id INTO progress_id;
  UPDATE campaign_trigger_events SET status='enrolled',reason='Qualified and enrolled',processed_at=now(),lease_until=NULL WHERE id=e.id;
  RETURN jsonb_build_object('allowed',true,'progress_id',progress_id);
END;
$_$;


ALTER FUNCTION "public"."admit_campaign_trigger_event"("p_event_id" "uuid", "p_enroll" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."advance_account_stage_on_inbound_message"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NEW.direction <> 'inbound' OR NEW.contact_id IS NULL THEN
    RETURN NEW;
  END IF;

  UPDATE public.crm_companies cc
     SET account_stage = 'active',
         account_stage_locked_at = NULL,
         last_contact_at = COALESCE(cc.last_contact_at, NOW()),
         updated_at = NOW()
   WHERE cc.id = (
     SELECT c.company_id
     FROM public.crm_contacts c
     WHERE c.id = NEW.contact_id
   )
     AND cc.account_stage = 'prospect'
     AND cc.account_stage_locked_at IS NULL;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."advance_account_stage_on_inbound_message"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."all_scenes_approved"("vid" "uuid") RETURNS boolean
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
DECLARE
    unapproved_count INTEGER;
BEGIN
    SELECT COUNT(*) INTO unapproved_count
    FROM scenes
    WHERE video_id = vid AND approved = false;
    RETURN unapproved_count = 0;
END;
$$;


