CREATE OR REPLACE FUNCTION "public"."apply_domain_probe_outcome"("p_domain_id" "uuid", "p_outcome" "text", "p_reason" "text" DEFAULT NULL::"text", "p_source" "text" DEFAULT 'probe'::"text", "p_rest_days" integer DEFAULT 56, "p_clean_probes_to_healthy" integer DEFAULT 3) RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_current   text;
  v_rest      timestamptz;
  v_streak    integer;
  v_next      text;
  v_now       timestamptz := now();
  v_probe_gap interval;
begin
  select health_status, rest_until, clean_probe_streak
    into v_current, v_rest, v_streak
  from email_sending_domains
  where id = p_domain_id
  for update;

  if not found then
    return null;
  end if;

  v_current := coalesce(v_current, 'unknown');
  v_streak  := coalesce(v_streak, 0);
  v_next    := v_current;

  if p_outcome = 'failed_550' then
    v_next := 'burned';
    v_streak := 0;
    v_rest := v_now + make_interval(days => p_rest_days);

    update email_sending_domains
       set health_status      = v_next,
           consecutive_550    = coalesce(consecutive_550, 0) + 1,
           last_550_at        = v_now,
           last_550_reason    = left(coalesce(p_reason, 'reputation rejection'), 1000),
           rest_until         = v_rest,
           clean_probe_streak = 0,
           domain_health      = 'burned',
           burned_at          = coalesce(burned_at, v_now),
           updated_at         = v_now
     where id = p_domain_id;

  elsif p_outcome = 'spam' then
    if v_current <> 'burned' then
      v_next := 'degrading';
      v_streak := 0;
      update email_sending_domains
         set health_status      = v_next,
             clean_probe_streak = 0,
             updated_at         = v_now
       where id = p_domain_id;
    end if;

  elsif p_outcome = 'delivered' then
    if v_current = 'burned' then
      if v_rest is not null and v_now < v_rest then
        v_next := 'burned';
      else
        v_next := 'recovering';
        v_streak := 1;
        update email_sending_domains
           set health_status      = v_next,
               clean_probe_streak = v_streak,
               updated_at         = v_now
         where id = p_domain_id;
      end if;

    elsif v_current in ('recovering', 'degrading') then
      v_streak := v_streak + 1;
      if v_streak >= p_clean_probes_to_healthy then
        v_next := 'healthy';
        update email_sending_domains
           set health_status           = v_next,
               clean_probe_streak      = v_streak,
               consecutive_550         = 0,
               rest_until              = null,
               reputation_blocked_at   = null,
               reputation_block_reason = null,
               domain_health           = 'healthy',
               burned_at               = null,
               updated_at              = v_now
         where id = p_domain_id;
      else
        update email_sending_domains
           set clean_probe_streak = v_streak,
               updated_at         = v_now
         where id = p_domain_id;
      end if;

    else
      v_next := 'healthy';
      v_streak := v_streak + 1;
      update email_sending_domains
         set health_status      = v_next,
             clean_probe_streak = v_streak,
             updated_at         = v_now
       where id = p_domain_id;
    end if;
  end if;

  if p_source = 'probe' then
    v_probe_gap := case
      when p_outcome = 'send_failed' then interval '1 day'
      when v_next in ('burned', 'recovering') then interval '14 days'
      else interval '7 days'
    end;

    update email_sending_domains
       set last_probe_at    = v_now,
           last_probe_result = p_outcome,
           next_probe_at     = date_trunc('day', v_now) + v_probe_gap,
           updated_at        = v_now
     where id = p_domain_id;
  end if;

  if v_next is distinct from v_current then
    insert into email_domain_health_log (domain_id, domain_health, notes)
    values (
      p_domain_id,
      v_next,
      format('health_status %s -> %s via %s (%s)%s',
             v_current, v_next, p_source, p_outcome,
             case when p_reason is null then '' else ': ' || left(p_reason, 500) end)
    );
  end if;

  return v_next;
end;
$$;


ALTER FUNCTION "public"."apply_domain_probe_outcome"("p_domain_id" "uuid", "p_outcome" "text", "p_reason" "text", "p_source" "text", "p_rest_days" integer, "p_clean_probes_to_healthy" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."apply_domain_probe_outcome"("p_domain_id" "uuid", "p_outcome" "text", "p_reason" "text", "p_source" "text", "p_rest_days" integer, "p_clean_probes_to_healthy" integer) IS 'Single source of truth for sending-domain health transitions. next_probe_at is date-anchored (not exact-timestamp) so the weekly send cron never races resolution-time drift.';



