CREATE OR REPLACE FUNCTION "public"."apply_mailbox_metadata_patch"("p_id" "uuid", "p_set" "jsonb" DEFAULT '{}'::"jsonb", "p_unset" "text"[] DEFAULT '{}'::"text"[]) RETURNS "void"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  UPDATE email_mailboxes
  SET metadata = (COALESCE(metadata, '{}'::jsonb) - p_unset) || COALESCE(p_set, '{}'::jsonb),
      updated_at = now()
  WHERE id = p_id;
$$;


