CREATE OR REPLACE FUNCTION "public"."apply_verification_cache_to_list"("p_list_id" "uuid", "p_org_id" "uuid") RETURNS integer
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
  WITH updated AS (
    UPDATE public.crm_contacts AS c
    SET
      email_verification_status   = v.status,
      email_is_deliverable        = v.is_deliverable,
      email_is_catch_all          = v.is_catch_all,
      email_is_role               = v.is_role,
      email_is_free               = v.is_free,
      email_is_disposable         = v.is_disposable,
      email_is_spamtrap           = v.is_spamtrap,
      email_verification_score    = v.overall_score,
      email_verified_at           = v.last_verified_at,
      email_verification_source   = v.last_source
    FROM public.pool_email_verifications AS v
    WHERE v.email_hash = extensions.digest(
            lower(coalesce(c.email, c.primary_email)),
            'sha256'::text
          )
      AND coalesce(c.email, c.primary_email) IS NOT NULL
      AND c.organization_id = p_org_id
      AND c.id IN (
        SELECT contact_id FROM public.lead_list_members
        WHERE list_id = p_list_id
      )
    RETURNING c.id
  )
  SELECT count(*)::integer FROM updated;
$$;


ALTER FUNCTION "public"."apply_verification_cache_to_list"("p_list_id" "uuid", "p_org_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."approve_signal_review_item"("p_review_id" "uuid") RETURNS TABLE("review_id" "uuid", "subscription_id" "uuid", "organization_id" "uuid", "discovered_company_id" "uuid", "activity_rows_flipped" integer, "dm_work_item_id" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_review RECORD;
  v_company RECORD;
  v_existing_dm BIGINT;
  v_new_dm BIGINT;
  v_flipped INTEGER;
  v_user UUID := auth.uid();
BEGIN
  -- Load the review row + verify the caller is in the same org
  SELECT srq.*
    INTO v_review
    FROM public.signal_review_queue srq
   WHERE srq.id = p_review_id;
  IF v_review IS NULL THEN
    RAISE EXCEPTION 'review item not found';
  END IF;

  IF v_user IS NOT NULL THEN
    PERFORM 1 FROM public.organization_members om
      WHERE om.organization_id = v_review.organization_id
        AND om.user_id = v_user
      LIMIT 1;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'not a member of this organization';
    END IF;
  END IF;

  -- 1. Approve the review row
  UPDATE public.signal_review_queue
     SET status = 'approved', decided_at = NOW()
   WHERE id = p_review_id;

  -- 2. Flip every matching activity_log row from review_pending to enrolled
  WITH updated AS (
    UPDATE public.signal_activity_log
       SET outcome = 'enrolled'
     WHERE subscription_id = v_review.subscription_id
       AND discovered_company_id = v_review.discovered_company_id
       AND outcome = 'review_pending'
     RETURNING 1
  )
  SELECT count(*)::INTEGER INTO v_flipped FROM updated;

  -- 3. Enqueue stage=dm if no in-flight one exists for this company
  v_new_dm := NULL;
  IF v_review.discovered_company_id IS NOT NULL THEN
    SELECT id INTO v_existing_dm
      FROM public.lb_work_items
     WHERE stage = 'dm'
       AND status IN ('pending', 'claimed')
       AND payload->>'company_id' = v_review.discovered_company_id::TEXT
     LIMIT 1;

    IF v_existing_dm IS NULL THEN
      SELECT id, job_id, organization_id, company_name, domain, website_url, linkedin_url
        INTO v_company
        FROM public.lb_discovered_companies
       WHERE id = v_review.discovered_company_id;

      IF v_company.id IS NOT NULL THEN
        INSERT INTO public.lb_work_items (job_id, organization_id, stage, status, payload, priority)
        VALUES (
          v_company.job_id,
          v_company.organization_id,
          'dm',
          'pending',
          jsonb_build_object(
            'company_id',    v_company.id,
            'company_name',  v_company.company_name,
            'domain',        v_company.domain,
            'website_url',   v_company.website_url,
            'linkedin_url',  v_company.linkedin_url
          ),
          9
        )
        RETURNING id INTO v_new_dm;
      END IF;
    END IF;
  END IF;

  RETURN QUERY SELECT
    v_review.id, v_review.subscription_id, v_review.organization_id,
    v_review.discovered_company_id, v_flipped, v_new_dm;
END;
$$;


ALTER FUNCTION "public"."approve_signal_review_item"("p_review_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."approve_signup_request"("p_request_id" "uuid", "p_plan_tier" "text", "p_admin_notes" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_request signup_requests%ROWTYPE;
  v_user_id UUID;
  v_org_id UUID;
  v_org_slug TEXT;
  v_result JSONB;
BEGIN
  -- Get the request WITH ROW LOCK to prevent race conditions
  -- FOR UPDATE NOWAIT will immediately fail if another transaction holds the lock
  SELECT * INTO v_request
  FROM signup_requests
  WHERE id = p_request_id
  FOR UPDATE NOWAIT;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Request not found');
  END IF;

  IF v_request.status != 'pending' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Request already processed');
  END IF;

  -- Check if user already exists
  SELECT id INTO v_user_id
  FROM auth.users
  WHERE email = v_request.email;

  IF v_user_id IS NOT NULL THEN
    -- User already exists - just update the request
    UPDATE signup_requests
    SET
      status = 'approved',
      assigned_plan_tier = p_plan_tier,
      processed_by = auth.uid(),
      processed_at = NOW(),
      admin_notes = p_admin_notes,
      created_user_id = v_user_id,
      updated_at = NOW()
    WHERE id = p_request_id;

    RETURN jsonb_build_object(
      'success', true,
      'user_existed', true,
      'user_id', v_user_id,
      'message', 'User already exists with this email'
    );
  END IF;

  -- Mark as approved - the edge function will handle account creation
  UPDATE signup_requests
  SET
    status = 'approved',
    assigned_plan_tier = p_plan_tier,
    processed_by = auth.uid(),
    processed_at = NOW(),
    admin_notes = p_admin_notes,
    updated_at = NOW()
  WHERE id = p_request_id;

  RETURN jsonb_build_object(
    'success', true,
    'needs_account_creation', true,
    'email', v_request.email,
    'full_name', v_request.full_name,
    'plan_tier', p_plan_tier
  );

EXCEPTION
  WHEN lock_not_available THEN
    -- Another transaction is processing this request
    RETURN jsonb_build_object('success', false, 'error', 'Request is being processed by another action');
END;
$$;


ALTER FUNCTION "public"."approve_signup_request"("p_request_id" "uuid", "p_plan_tier" "text", "p_admin_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."assert_smart_segment_org_access"("p_org_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  -- SECURITY DEFINER changes current_user, so it cannot identify the caller.
  IF auth.role() = 'service_role'
    OR (auth.uid() IS NULL AND session_user IN ('postgres','supabase_admin')) THEN RETURN; END IF;
  IF p_org_id IS NULL OR NOT EXISTS (
    SELECT 1 FROM public.organization_members m
    WHERE m.organization_id=p_org_id AND m.user_id=auth.uid()
  ) THEN RAISE EXCEPTION 'Not a member of this organization' USING ERRCODE='42501'; END IF;
END;
$$;


ALTER FUNCTION "public"."assert_smart_segment_org_access"("p_org_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."auth_user_is_org_admin"("org_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.organization_members 
    WHERE user_id = auth.uid() 
    AND organization_id = org_id 
    AND role IN ('owner', 'admin')
  );
