CREATE OR REPLACE FUNCTION "public"."authorize_sending_domain_control"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.sending_paused_at IS NULL AND NEW.sending_pause_reason IS NULL AND NEW.sending_paused_by IS NULL THEN RETURN NEW; END IF;
  ELSIF NEW.sending_paused_at IS NOT DISTINCT FROM OLD.sending_paused_at
    AND NEW.sending_pause_reason IS NOT DISTINCT FROM OLD.sending_pause_reason
    AND NEW.sending_paused_by IS NOT DISTINCT FROM OLD.sending_paused_by THEN RETURN NEW;
  END IF;
  IF auth.role() IS DISTINCT FROM 'service_role' AND NOT public.is_super_admin(auth.uid()) AND NOT EXISTS (
    SELECT 1 FROM public.organization_members
    WHERE organization_id = NEW.organization_id AND user_id = auth.uid() AND role IN ('owner', 'admin')) THEN
    RAISE EXCEPTION 'Only organization owners and admins may change sending controls' USING ERRCODE = '42501';
  END IF;
  IF NEW.sending_paused_at IS NULL AND public.is_sending_domain_technically_unusable(NEW.id) THEN
    RAISE EXCEPTION 'This domain is technically unusable or replaced and cannot be resumed' USING ERRCODE = '22023';
  END IF;
  IF NEW.sending_paused_at IS NOT NULL THEN
    NEW.sending_paused_by := auth.uid();
    NEW.sending_pause_reason := coalesce(nullif(btrim(NEW.sending_pause_reason), ''), 'Paused by operator');
  ELSE
    NEW.sending_paused_by := NULL;
    NEW.sending_pause_reason := NULL;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."authorize_sending_domain_control"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."auto_assign_conversation_from_account"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_owner_id UUID;
BEGIN
  -- Skip if already assigned
  IF NEW.assigned_to_user_id IS NOT NULL THEN
    RETURN NEW;
  END IF;

  -- Try email mailbox owner first
  IF NEW.mailbox_id IS NOT NULL THEN
    SELECT owner_user_id INTO v_owner_id
    FROM email_mailboxes
    WHERE id = NEW.mailbox_id AND owner_user_id IS NOT NULL;

    IF v_owner_id IS NOT NULL THEN
      NEW.assigned_to_user_id := v_owner_id;
      NEW.assigned_to_type := 'user';
      RETURN NEW;
    END IF;
  END IF;

  -- Try Unipile account owner (LinkedIn/Instagram)
  IF NEW.channel_account_id IS NOT NULL THEN
    SELECT owner_user_id INTO v_owner_id
    FROM unipile_accounts
    WHERE id = NEW.channel_account_id AND owner_user_id IS NOT NULL;

    IF v_owner_id IS NOT NULL THEN
      NEW.assigned_to_user_id := v_owner_id;
      NEW.assigned_to_type := 'user';
      RETURN NEW;
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."auto_assign_conversation_from_account"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."auto_progress_account_stage"() RETURNS TABLE("promoted_to_active" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_count INTEGER := 0;
BEGIN
  WITH eligible AS (
    SELECT c.company_id AS id
    FROM public.crm_messages m
    JOIN public.crm_contacts c ON c.id = m.contact_id
    JOIN public.crm_companies cc ON cc.id = c.company_id
    WHERE m.direction = 'inbound'
      AND c.company_id IS NOT NULL
      AND cc.account_stage = 'prospect'
      AND cc.account_stage_locked_at IS NULL
    GROUP BY c.company_id
    LIMIT 500
  ),
  upd AS (
    UPDATE public.crm_companies cc
       SET account_stage = 'active',
           account_stage_locked_at = NULL,
           last_contact_at = COALESCE(cc.last_contact_at, NOW()),
           updated_at = NOW()
     WHERE cc.id IN (SELECT id FROM eligible)
    RETURNING 1
  )
  SELECT count(*)::INTEGER INTO v_count FROM upd;

  promoted_to_active := v_count;
  RETURN NEXT;
END;
$$;


ALTER FUNCTION "public"."auto_progress_account_stage"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."autopilot_feed_entries"("p_ideas_source" "text", "p_shared_tags" "text"[], "p_content_mix" "jsonb") RETURNS TABLE("blueprint_id" "text", "tags" "text"[])
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
  SELECT
    m->>'blueprint_id',
    CASE
      WHEN p_ideas_source = 'shared' AND cardinality(coalesce(p_shared_tags, '{}'::text[])) > 0
        THEN p_shared_tags
      ELSE ARRAY(
        SELECT btrim(t)
        FROM jsonb_array_elements_text(
          CASE WHEN jsonb_typeof(m->'idea_tags') = 'array' THEN m->'idea_tags' ELSE '[]'::jsonb END
        ) t
        WHERE btrim(t) <> ''
      )
    END
  FROM jsonb_array_elements(
    CASE WHEN jsonb_typeof(p_content_mix) = 'array' THEN p_content_mix ELSE '[]'::jsonb END
  ) m
  WHERE coalesce(m->>'enabled', 'true') <> 'false';
$$;


ALTER FUNCTION "public"."autopilot_feed_entries"("p_ideas_source" "text", "p_shared_tags" "text"[], "p_content_mix" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."autopilots_clear_pause_reason"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NEW.status = 'active' AND OLD.status IS DISTINCT FROM 'active' THEN
    NEW.paused_reason := NULL;
    NEW.paused_at := NULL;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."autopilots_clear_pause_reason"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."bucket_employee_range"("p_count" integer) RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  SELECT CASE
    WHEN p_count IS NULL OR p_count <= 0 THEN NULL
    WHEN p_count <= 10 THEN '1-10'
    WHEN p_count <= 20 THEN '11-20'
    WHEN p_count <= 50 THEN '21-50'
    WHEN p_count <= 200 THEN '51-200'
    WHEN p_count <= 500 THEN '201-500'
    WHEN p_count <= 1000 THEN '501-1000'
    WHEN p_count <= 5000 THEN '1001-5000'
    ELSE '5001+'
  END;
$$;


ALTER FUNCTION "public"."bucket_employee_range"("p_count" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."bulk_import_contacts"("p_organization_id" "uuid", "p_rows" "jsonb", "p_list_id" "uuid" DEFAULT NULL::"uuid", "p_dedupe_on_email" boolean DEFAULT true, "p_default_source" "text" DEFAULT 'api'::"text", "p_log_activity" boolean DEFAULT true) RETURNS TABLE("idx" integer, "contact_id" "uuid", "status" "text", "added_to_list" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_prep jsonb;
  v_now timestamptz := now();
BEGIN
  IF p_rows IS NULL OR jsonb_typeof(p_rows) <> 'array' THEN
    RAISE EXCEPTION 'p_rows must be a JSON array' USING ERRCODE = '22023';
  END IF;
  IF jsonb_array_length(p_rows) > 1000 THEN
    RAISE EXCEPTION 'Maximum 1000 contacts per call (received %)', jsonb_array_length(p_rows)
      USING ERRCODE = '22023';
  END IF;
  IF p_list_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM lead_lists WHERE id = p_list_id AND organization_id = p_organization_id
  ) THEN
    RAISE EXCEPTION 'List not found' USING ERRCODE = 'P0002';
  END IF;

  WITH input AS (
    SELECT
      (o.n - 1)::int AS idx,
      o.r,
      nullif(lower(btrim(o.r->>'primary_email')), '') AS email_l,
      nullif(btrim(o.r->>'primary_linkedin_url'), '') AS li,
      coalesce(
        nullif(btrim(o.r->>'display_name'), ''),
        nullif(btrim(concat_ws(' ', nullif(btrim(o.r->>'first_name'), ''), nullif(btrim(o.r->>'last_name'), ''))), ''),
        nullif(btrim(o.r->>'company'), ''),
        nullif(btrim(o.r->>'primary_email'), '')
      ) AS display_name
    FROM jsonb_array_elements(p_rows) WITH ORDINALITY AS o(r, n)
  ),
  matched AS (
    SELECT
      i.*,
      coalesce(
        CASE WHEN p_dedupe_on_email AND i.email_l IS NOT NULL THEN (
          SELECT c.id FROM crm_contacts c
          WHERE c.organization_id = p_organization_id AND lower(c.primary_email) = i.email_l
          ORDER BY c.created_at
          LIMIT 1
        ) END,
        CASE WHEN i.li IS NOT NULL THEN (
          SELECT c.id FROM crm_contacts c
          WHERE c.organization_id = p_organization_id AND c.primary_linkedin_url = i.li
          LIMIT 1
        ) END
      ) AS match_id
    FROM input i
  ),
  ranked AS (
    SELECT
      m.*,
      min(m.idx) FILTER (WHERE m.match_id IS NULL AND m.display_name IS NOT NULL)
        OVER (PARTITION BY m.email_l) AS first_by_email,
      min(m.idx) FILTER (WHERE m.match_id IS NULL AND m.display_name IS NOT NULL)
        OVER (PARTITION BY m.li) AS first_by_li
    FROM matched m
  )
  SELECT jsonb_agg(jsonb_build_object(
    'idx', r.idx,
    'r', r.r,
    'email_l', r.email_l,
    'li', r.li,
    'display_name', r.display_name,
    'match_id', r.match_id,
    'new_id', CASE
      WHEN r.match_id IS NULL
       AND r.display_name IS NOT NULL
       AND (r.email_l IS NULL OR NOT p_dedupe_on_email OR r.idx = r.first_by_email)
       AND (r.li IS NULL OR r.idx = r.first_by_li)
      THEN gen_random_uuid()
    END
  ))
  INTO v_prep
  FROM ranked r;

  IF v_prep IS NULL THEN
    RETURN;
  END IF;

  INSERT INTO crm_contacts (
    id, organization_id, display_name, status, source,
    first_name, last_name, company, job_title, primary_email, primary_phone,
    primary_linkedin_url, instagram_url, linkedin_bio, home_page_text, company_website,
    city, state, country, pipeline_id, owner_user_id, stage_id, stage_entered_at,
    tags, custom_fields, discovery_metadata
  )
  SELECT
    (p->>'new_id')::uuid,
    p_organization_id,
    p->>'display_name',
    'active',
    coalesce(nullif(btrim(r->>'source'), ''), p_default_source),
    nullif(btrim(r->>'first_name'), ''),
    nullif(btrim(r->>'last_name'), ''),
    nullif(btrim(r->>'company'), ''),
    nullif(btrim(r->>'job_title'), ''),
    nullif(btrim(r->>'primary_email'), ''),
    nullif(btrim(r->>'primary_phone'), ''),
    p->>'li',
    nullif(btrim(r->>'instagram_url'), ''),
    nullif(btrim(r->>'linkedin_bio'), ''),
    nullif(btrim(r->>'home_page_text'), ''),
    nullif(btrim(r->>'company_website'), ''),
    nullif(btrim(r->>'city'), ''),
    nullif(btrim(r->>'state'), ''),
    nullif(btrim(r->>'country'), ''),
    nullif(btrim(r->>'pipeline_id'), '')::uuid,
    nullif(btrim(r->>'owner_user_id'), '')::uuid,
    nullif(btrim(r->>'stage_id'), '')::uuid,
    CASE WHEN nullif(btrim(r->>'stage_id'), '') IS NOT NULL THEN v_now END,
    CASE WHEN jsonb_typeof(r->'tags') = 'array'
      THEN ARRAY(SELECT jsonb_array_elements_text(r->'tags'))
      ELSE '{}'::text[] END,
    CASE WHEN jsonb_typeof(r->'custom_fields') = 'object' THEN r->'custom_fields' ELSE '{}'::jsonb END,
    CASE WHEN jsonb_typeof(r->'discovery_metadata') = 'object' THEN r->'discovery_metadata' END
  FROM jsonb_array_elements(v_prep) AS p
  CROSS JOIN LATERAL (SELECT p->'r' AS r) x
  WHERE p->>'new_id' IS NOT NULL
  ON CONFLICT DO NOTHING;

  IF p_log_activity THEN
    INSERT INTO crm_activities (organization_id, contact_id, activity_type, title, performed_by_type)
    SELECT p_organization_id, c.id, 'contact_created', 'Contact created (bulk import)', 'system'
    FROM jsonb_array_elements(v_prep) AS p
    JOIN crm_contacts c ON c.id = (p->>'new_id')::uuid
    WHERE p->>'new_id' IS NOT NULL;
  END IF;

  RETURN QUERY
  WITH prep AS (
    SELECT
      (p->>'idx')::int AS idx,
      (p->>'match_id')::uuid AS match_id,
      (p->>'new_id')::uuid AS new_id,
      p->>'email_l' AS email_l,
      p->>'li' AS li,
      p->>'display_name' AS display_name
    FROM jsonb_array_elements(v_prep) AS p
  ),
  resolved AS (
    SELECT
      pr.idx,
      pr.display_name,
      (SELECT c.id FROM crm_contacts c WHERE c.id = pr.new_id) AS created_id,
      coalesce(
        pr.match_id,
        (SELECT c.id FROM crm_contacts c WHERE c.id = pr.new_id),
        CASE WHEN pr.email_l IS NOT NULL THEN (
          SELECT c.id FROM crm_contacts c
          WHERE c.organization_id = p_organization_id AND lower(c.primary_email) = pr.email_l
          ORDER BY c.created_at
          LIMIT 1
        ) END,
        CASE WHEN pr.li IS NOT NULL THEN (
          SELECT c.id FROM crm_contacts c
          WHERE c.organization_id = p_organization_id AND c.primary_linkedin_url = pr.li
          LIMIT 1
        ) END
      ) AS cid
    FROM prep pr
  ),
  members AS (
    INSERT INTO lead_list_members (list_id, contact_id)
    SELECT DISTINCT p_list_id, rs.cid
    FROM resolved rs
    WHERE p_list_id IS NOT NULL AND rs.cid IS NOT NULL AND rs.display_name IS NOT NULL
    ON CONFLICT DO NOTHING
    RETURNING lead_list_members.contact_id
  )
  SELECT
    rs.idx,
    CASE WHEN rs.display_name IS NULL THEN NULL ELSE rs.cid END,
    CASE
      WHEN rs.display_name IS NULL THEN 'invalid'
      WHEN rs.created_id IS NOT NULL THEN 'created'
      ELSE 'existing'
    END,
    EXISTS (SELECT 1 FROM members mb WHERE mb.contact_id = rs.cid)
  FROM resolved rs
  ORDER BY rs.idx;
END;
$$;


ALTER FUNCTION "public"."bulk_import_contacts"("p_organization_id" "uuid", "p_rows" "jsonb", "p_list_id" "uuid", "p_dedupe_on_email" boolean, "p_default_source" "text", "p_log_activity" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."bulk_remove_filtered_list_members"("p_list_id" "uuid", "p_filters" "jsonb" DEFAULT '{}'::"jsonb") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org_id UUID;
  v_deleted INTEGER;
BEGIN
  SELECT organization_id INTO v_org_id
  FROM public.lead_lists
  WHERE id = p_list_id
    AND organization_id = get_user_organization_id();

  IF v_org_id IS NULL THEN
    RAISE EXCEPTION 'List not found or access denied';
  END IF;

  DELETE FROM public.lead_list_members m
  WHERE m.list_id = p_list_id
    AND m.contact_id IN (
      SELECT r.contact_id
      FROM public.filter_lead_list_member_rows(p_list_id, p_filters) r
    );

  GET DIAGNOSTICS v_deleted = ROW_COUNT;
  RETURN v_deleted;
END;
$$;


ALTER FUNCTION "public"."bulk_remove_filtered_list_members"("p_list_id" "uuid", "p_filters" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."bulk_remove_list_members"("p_list_id" "uuid", "p_contact_ids" "uuid"[]) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org_id UUID;
  v_deleted INTEGER;
BEGIN
  -- 1. Validate the caller owns this list via their org
  SELECT organization_id INTO v_org_id
  FROM public.lead_lists
  WHERE id = p_list_id
    AND organization_id = get_user_organization_id();

  IF v_org_id IS NULL THEN
    RAISE EXCEPTION 'List not found or access denied';
  END IF;

  -- 2. Delete members — no RLS overhead since SECURITY DEFINER
  DELETE FROM public.lead_list_members
  WHERE list_id = p_list_id
    AND contact_id = ANY(p_contact_ids);

  GET DIAGNOSTICS v_deleted = ROW_COUNT;

  -- The statement-level trigger trg_update_lead_list_count_delete
  -- will automatically decrement lead_count based on deleted rows.

  RETURN v_deleted;
END;
$$;


ALTER FUNCTION "public"."bulk_remove_list_members"("p_list_id" "uuid", "p_contact_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."bulk_set_contact_custom_field"("p_organization_id" "uuid", "p_contact_ids" "uuid"[], "p_field_key" "text", "p_field_value" "text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_count INTEGER;
BEGIN
  UPDATE crm_contacts
  SET
    custom_fields = COALESCE(custom_fields, '{}'::jsonb) || jsonb_build_object(p_field_key, p_field_value),
    updated_at = now()
  WHERE organization_id = p_organization_id
    AND id = ANY(p_contact_ids);

  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$$;


ALTER FUNCTION "public"."bulk_set_contact_custom_field"("p_organization_id" "uuid", "p_contact_ids" "uuid"[], "p_field_key" "text", "p_field_value" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."bulk_update_mailbox_owner"("p_ids" "uuid"[], "p_user_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org_id UUID;
  v_count  INTEGER;
  v_bad    INTEGER;
BEGIN
  v_org_id := get_user_organization_id();
  IF v_org_id IS NULL THEN
    RAISE EXCEPTION 'No organization context';
  END IF;

  SELECT count(*) INTO v_bad
  FROM unnest(p_ids) AS t(id)
  WHERE NOT EXISTS (
    SELECT 1 FROM email_mailboxes em
    WHERE em.id = t.id AND em.organization_id = v_org_id
  );
  IF v_bad > 0 THEN
    RAISE EXCEPTION '% mailbox(es) not found or access denied', v_bad;
  END IF;

  UPDATE email_mailboxes
  SET
    owner_user_id = p_user_id,
    updated_at = now()
  WHERE id = ANY(p_ids)
    AND organization_id = v_org_id;

  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$$;


ALTER FUNCTION "public"."bulk_update_mailbox_owner"("p_ids" "uuid"[], "p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."bulk_update_mailbox_tags"("p_ids" "uuid"[], "p_tags" "text"[], "p_mode" "text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org_id UUID;
  v_count  INTEGER;
  v_bad    INTEGER;
BEGIN
  v_org_id := get_user_organization_id();
  IF v_org_id IS NULL THEN
    RAISE EXCEPTION 'No organization context';
  END IF;

  IF p_mode NOT IN ('add', 'remove', 'set') THEN
    RAISE EXCEPTION 'Invalid mode: %', p_mode;
  END IF;

  SELECT count(*) INTO v_bad
  FROM unnest(p_ids) AS t(id)
  WHERE NOT EXISTS (
    SELECT 1 FROM email_mailboxes em
    WHERE em.id = t.id AND em.organization_id = v_org_id
  );
  IF v_bad > 0 THEN
    RAISE EXCEPTION '% mailbox(es) not found or access denied', v_bad;
  END IF;

  UPDATE email_mailboxes
  SET
    tags = CASE p_mode
             WHEN 'set' THEN p_tags
             WHEN 'add' THEN (
               SELECT ARRAY(
                 SELECT DISTINCT unnest(COALESCE(tags, ARRAY[]::TEXT[]) || p_tags)
               )
             )
             WHEN 'remove' THEN (
               SELECT ARRAY(
                 SELECT t FROM unnest(COALESCE(tags, ARRAY[]::TEXT[])) AS t
                 WHERE t <> ALL(p_tags)
               )
             )
           END,
    updated_at = now()
  WHERE id = ANY(p_ids)
    AND organization_id = v_org_id;

  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$$;


ALTER FUNCTION "public"."bulk_update_mailbox_tags"("p_ids" "uuid"[], "p_tags" "text"[], "p_mode" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."bulk_update_mailboxes"("p_ids" "uuid"[], "p_column_updates" "jsonb" DEFAULT NULL::"jsonb", "p_metadata_merge" "jsonb" DEFAULT NULL::"jsonb") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org_id UUID;
  v_count  INTEGER;
  v_bad    INTEGER;
BEGIN
  v_org_id := get_user_organization_id();
  IF v_org_id IS NULL THEN
    RAISE EXCEPTION 'No organization context';
  END IF;

  -- Reject if any ID doesn't belong to caller's org
  SELECT count(*) INTO v_bad
  FROM unnest(p_ids) AS t(id)
  WHERE NOT EXISTS (
    SELECT 1 FROM email_mailboxes em
    WHERE em.id = t.id AND em.organization_id = v_org_id
  );
  IF v_bad > 0 THEN
    RAISE EXCEPTION '% mailbox(es) not found or access denied', v_bad;
  END IF;

  -- Atomic update: merge metadata + set whitelisted columns
  UPDATE email_mailboxes
  SET
    metadata = CASE WHEN p_metadata_merge IS NOT NULL
               THEN COALESCE(metadata, '{}'::jsonb) || p_metadata_merge
               ELSE metadata END,
    daily_limit = CASE WHEN p_column_updates ? 'daily_limit'
                  THEN (p_column_updates->>'daily_limit')::int
                  ELSE daily_limit END,
    status = CASE WHEN p_column_updates ? 'status'
             THEN p_column_updates->>'status'
             ELSE status END,
    warmup_enabled = CASE WHEN p_column_updates ? 'warmup_enabled'
                     THEN (p_column_updates->>'warmup_enabled')::boolean
                     ELSE warmup_enabled END,
    updated_at = now()
  WHERE id = ANY(p_ids)
    AND organization_id = v_org_id;

  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$$;


ALTER FUNCTION "public"."bulk_update_mailboxes"("p_ids" "uuid"[], "p_column_updates" "jsonb", "p_metadata_merge" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."bulk_upsert_csv_contacts"("p_organization_id" "uuid", "p_rows" "jsonb") RETURNS TABLE("id" "uuid", "is_new" boolean)
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  RETURN QUERY
  WITH raw_rows AS (
    SELECT
      (r->>'primary_email') AS primary_email,
      r->>'display_name' AS display_name,
      r->>'source' AS source,
      COALESCE(r->'source_details', '{}'::jsonb) AS source_details,
      r->>'first_name' AS first_name,
      r->>'last_name' AS last_name,
      r->>'job_title' AS job_title,
      r->>'company' AS company,
      r->>'company_website' AS company_website,
      r->>'city' AS city,
      r->>'state' AS state,
      r->>'country' AS country,
      r->>'primary_phone' AS primary_phone,
      CASE
        WHEN r->>'primary_linkedin_url' ~* 'linkedin\.com/(company|school|showcase)/' THEN NULL
        ELSE nullif(btrim(r->>'primary_linkedin_url'), '')
      END AS raw_linkedin_url,
      nullif(btrim(r->>'instagram_url'), '') AS instagram_url,
      r->'enrichment_data' AS enrichment_data,
      r->'custom_fields' AS custom_fields,
      ord
    FROM jsonb_array_elements(p_rows) WITH ORDINALITY AS t(r, ord)
  ),
  input_rows AS (
    SELECT rr.*,
      CASE
        WHEN rr.raw_linkedin_url IS NULL THEN NULL
        WHEN row_number() OVER (PARTITION BY rr.raw_linkedin_url ORDER BY rr.ord) > 1 THEN NULL
        ELSE rr.raw_linkedin_url
      END AS primary_linkedin_url
    FROM raw_rows rr
  ),
  updated AS (
    UPDATE crm_contacts c SET
      first_name = COALESCE(i.first_name, c.first_name),
      last_name = COALESCE(i.last_name, c.last_name),
      display_name = COALESCE(NULLIF(i.display_name, ''), c.display_name),
      job_title = COALESCE(i.job_title, c.job_title),
      company = COALESCE(i.company, c.company),
      company_website = COALESCE(i.company_website, c.company_website),
      city = COALESCE(i.city, c.city),
      state = COALESCE(i.state, c.state),
      country = COALESCE(i.country, c.country),
      primary_phone = COALESCE(c.primary_phone, i.primary_phone),
      primary_linkedin_url = CASE
        WHEN c.primary_linkedin_url IS NOT NULL THEN c.primary_linkedin_url
        WHEN i.primary_linkedin_url IS NULL THEN NULL
        WHEN EXISTS (
          SELECT 1 FROM crm_contacts other
          WHERE other.organization_id = p_organization_id
            AND other.primary_linkedin_url = i.primary_linkedin_url
            AND other.id <> c.id
        ) THEN NULL
        ELSE i.primary_linkedin_url
      END,
      instagram_url = COALESCE(i.instagram_url, c.instagram_url),
      enrichment_data = COALESCE(c.enrichment_data, '{}'::jsonb) || COALESCE(i.enrichment_data, '{}'::jsonb),
      custom_fields = COALESCE(c.custom_fields, '{}'::jsonb) || COALESCE(i.custom_fields, '{}'::jsonb),
      updated_at = now()
    FROM input_rows i
    WHERE c.organization_id = p_organization_id
      AND lower(c.primary_email) = lower(i.primary_email)
    RETURNING c.id, lower(c.primary_email) AS matched_email
  ),
  to_insert AS (
    SELECT i.* FROM input_rows i
    WHERE NOT EXISTS (SELECT 1 FROM updated u WHERE u.matched_email = lower(i.primary_email))
  ),
  inserted AS (
    INSERT INTO crm_contacts (
      organization_id, display_name, source, source_details,
      primary_email, first_name, last_name, job_title, company, company_website,
      city, state, country, primary_phone, primary_linkedin_url, instagram_url,
      enrichment_data, custom_fields
    )
    SELECT
      p_organization_id, COALESCE(NULLIF(ti.display_name, ''), 'Unknown'), ti.source, ti.source_details,
      ti.primary_email, ti.first_name, ti.last_name, ti.job_title, ti.company, ti.company_website,
      ti.city, ti.state, ti.country, ti.primary_phone,
      CASE
        WHEN ti.primary_linkedin_url IS NULL THEN NULL
        WHEN EXISTS (
          SELECT 1 FROM crm_contacts other
          WHERE other.organization_id = p_organization_id
            AND other.primary_linkedin_url = ti.primary_linkedin_url
        ) THEN NULL
        ELSE ti.primary_linkedin_url
      END,
      ti.instagram_url,
      COALESCE(ti.enrichment_data, '{}'::jsonb), COALESCE(ti.custom_fields, '{}'::jsonb)
    FROM to_insert ti
    ON CONFLICT (organization_id, primary_linkedin_url) DO NOTHING
    RETURNING crm_contacts.id
  )
  SELECT updated.id, false FROM updated
  UNION ALL
  SELECT inserted.id, true FROM inserted;
END;
$$;


ALTER FUNCTION "public"."bulk_upsert_csv_contacts"("p_organization_id" "uuid", "p_rows" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."bump_email_verification_progress"("p_list_id" "uuid", "p_organization_id" "uuid", "p_total" integer, "p_delta_processed" integer DEFAULT 0, "p_delta_cache_hits" integer DEFAULT 0, "p_delta_passes" integer DEFAULT 0, "p_delta_drops" integer DEFAULT 0, "p_delta_apify" integer DEFAULT 0, "p_phase" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  INSERT INTO public.email_verification_progress (
    list_id, organization_id, total,
    processed, cache_hits, tier1_passes, tier1_drops, apify_submitted,
    phase, updated_at
  )
  VALUES (
    p_list_id, p_organization_id, p_total,
    p_delta_processed, p_delta_cache_hits, p_delta_passes, p_delta_drops, p_delta_apify,
    COALESCE(p_phase, 'running'), now()
  )
  ON CONFLICT (list_id) DO UPDATE SET
    total           = EXCLUDED.total,
    processed       = email_verification_progress.processed       + EXCLUDED.processed,
    cache_hits      = email_verification_progress.cache_hits      + EXCLUDED.cache_hits,
    tier1_passes    = email_verification_progress.tier1_passes    + EXCLUDED.tier1_passes,
    tier1_drops     = email_verification_progress.tier1_drops     + EXCLUDED.tier1_drops,
    apify_submitted = email_verification_progress.apify_submitted + EXCLUDED.apify_submitted,
    phase           = COALESCE(p_phase, email_verification_progress.phase),
    updated_at      = now();
$$;


ALTER FUNCTION "public"."bump_email_verification_progress"("p_list_id" "uuid", "p_organization_id" "uuid", "p_total" integer, "p_delta_processed" integer, "p_delta_cache_hits" integer, "p_delta_passes" integer, "p_delta_drops" integer, "p_delta_apify" integer, "p_phase" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."calculate_ai_acceptance_rate"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
DECLARE
  recommended_count INTEGER;
  selected_count INTEGER;
  overlap_count INTEGER;
BEGIN
  IF NEW.selected_template_ids IS NOT NULL AND NEW.ai_recommended_template_ids IS NOT NULL THEN
    recommended_count := COALESCE(array_length(NEW.ai_recommended_template_ids, 1), 0);
    selected_count := COALESCE(array_length(NEW.selected_template_ids, 1), 0);

    -- Calculate overlap between recommendations and selections
    IF recommended_count > 0 THEN
      SELECT COUNT(*) INTO overlap_count
      FROM unnest(NEW.selected_template_ids) AS selected(id)
      WHERE selected.id = ANY(NEW.ai_recommended_template_ids);

      NEW.ai_acceptance_rate := (overlap_count::DECIMAL / recommended_count::DECIMAL)::DECIMAL(3,2);
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."calculate_ai_acceptance_rate"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."calculate_next_run"("frequency" "text", "cron_expr" "text" DEFAULT NULL::"text", "from_time" timestamp with time zone DEFAULT "now"()) RETURNS timestamp with time zone
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
DECLARE
  next_time TIMESTAMPTZ;
BEGIN
  CASE frequency
    WHEN 'hourly' THEN
      next_time := from_time + INTERVAL '1 hour';
    WHEN 'daily' THEN
      next_time := from_time + INTERVAL '1 day';
    WHEN 'weekly' THEN
      next_time := from_time + INTERVAL '7 days';
    WHEN 'custom' THEN
      -- For custom cron, we'll calculate in application code
      -- Return 1 hour as fallback
      next_time := from_time + INTERVAL '1 hour';
    ELSE
      next_time := from_time + INTERVAL '1 day';
  END CASE;

  RETURN next_time;
END;
$$;


ALTER FUNCTION "public"."calculate_next_run"("frequency" "text", "cron_expr" "text", "from_time" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."calculate_scene_duration"("word_count" integer) RETURNS integer
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
BEGIN
  -- Average speaking rate: 150 words per minute
  RETURN CEIL((word_count::DECIMAL / 150.0) * 60.0);
END;
$$;


ALTER FUNCTION "public"."calculate_scene_duration"("word_count" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."calculate_session_duration"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
BEGIN
  IF NEW.completed_at IS NOT NULL AND OLD.completed_at IS NULL THEN
    NEW.duration_seconds := EXTRACT(EPOCH FROM (NEW.completed_at - NEW.created_at))::INTEGER;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."calculate_session_duration"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."can_manage_client_org"("target_org_id" "uuid", "required_roles" "text"[] DEFAULT NULL::"text"[]) RETURNS boolean
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT EXISTS (
    -- Direct membership check
    SELECT 1 FROM public.organization_members
    WHERE organization_id = target_org_id
      AND user_id = auth.uid()
      AND (required_roles IS NULL OR role = ANY(required_roles))
  )
  OR EXISTS (
    -- Parent organization (agency) check
    SELECT 1 FROM public.organizations o
    JOIN public.organization_members om ON om.organization_id = o.parent_id
    WHERE o.id = target_org_id
      AND o.parent_id IS NOT NULL
      AND om.user_id = auth.uid()
      AND (required_roles IS NULL OR om.role = ANY(required_roles))
  )
  OR is_super_admin(auth.uid());
$$;


ALTER FUNCTION "public"."can_manage_client_org"("target_org_id" "uuid", "required_roles" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."can_user_access_organization"("user_id" "uuid", "org_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  RETURN EXISTS (
    SELECT 1 FROM public.users
    WHERE id = user_id
      AND (
        organization_id = org_id
        OR can_access_organizations @> ARRAY[org_id]
      )
  );
END;
$$;


