    AS $$
DECLARE
  v_count INT;
BEGIN
  UPDATE public.lb_work_items
  SET status = 'dead',
      error = COALESCE(error, '') || ' [cancelled by stop-job]',
      updated_at = NOW()
  WHERE job_id = p_job_id
    AND status IN ('pending', 'claimed');
  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
