CREATE OR REPLACE FUNCTION "public"."cancel_lead_list_processing_contacts"("p_list_id" "uuid", "p_contact_ids" "uuid"[]) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_policy_id UUID;
  v_count INTEGER;
BEGIN
  SELECT p.id
  INTO v_policy_id
  FROM public.lead_list_processing_policies p
  WHERE p.lead_list_id = p_list_id
    AND EXISTS (
      SELECT 1
      FROM public.organization_members membership
      WHERE membership.organization_id = p.organization_id
        AND membership.user_id = auth.uid()
    );

  IF v_policy_id IS NULL THEN
    RAISE EXCEPTION 'Configure lead processing for this list before stopping it';
  END IF;

  UPDATE public.lead_list_processing_items item
  SET cancel_requested_at = NOW(),
      canceled_at = CASE WHEN item.status = 'processing' THEN NULL ELSE NOW() END,
      status = CASE WHEN item.status = 'processing' THEN 'processing' ELSE 'canceled' END,
      stage = CASE WHEN item.status = 'processing' THEN item.stage ELSE 'canceled' END,
      completed_at = CASE WHEN item.status = 'processing' THEN item.completed_at ELSE NOW() END,
      manual_run = FALSE,
      updated_at = NOW()
  WHERE item.policy_id = v_policy_id
    AND item.contact_id = ANY(COALESCE(p_contact_ids, '{}'::UUID[]))
    AND item.status IN ('pending', 'retry', 'processing')
    AND NOT (item.status = 'processing' AND item.stage = 'enrolling');

  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$$;


ALTER FUNCTION "public"."cancel_lead_list_processing_contacts"("p_list_id" "uuid", "p_contact_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cancel_lead_list_processing_run"("p_list_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_policy_id UUID;
  v_count INTEGER;
BEGIN
  SELECT policy.id INTO v_policy_id
  FROM public.lead_list_processing_policies policy
  WHERE policy.lead_list_id = p_list_id
    AND EXISTS (
      SELECT 1
      FROM public.organization_members membership
      WHERE membership.organization_id = policy.organization_id
        AND membership.user_id = auth.uid()
    );

  IF v_policy_id IS NULL THEN
    RAISE EXCEPTION 'Configure lead processing for this list before canceling it';
  END IF;

  UPDATE public.lead_list_processing_items item
  SET cancel_requested_at = NOW(),
      pause_requested_at = NULL,
      canceled_at = CASE WHEN item.status = 'processing' THEN NULL ELSE NOW() END,
      status = CASE WHEN item.status = 'processing' THEN 'processing' ELSE 'canceled' END,
      stage = CASE WHEN item.status = 'processing' THEN item.stage ELSE 'canceled' END,
      completed_at = CASE WHEN item.status = 'processing' THEN item.completed_at ELSE NOW() END,
      manual_run = FALSE,
      updated_at = NOW()
  WHERE item.policy_id = v_policy_id
    AND item.status IN ('pending', 'retry', 'processing')
    AND NOT (item.status = 'processing' AND item.stage = 'enrolling');

  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$$;


ALTER FUNCTION "public"."cancel_lead_list_processing_run"("p_list_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."capture_list_member_campaign_entry"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE source_list lead_lists%ROWTYPE;
BEGIN
  SELECT * INTO source_list FROM lead_lists WHERE id=NEW.list_id
    AND status='active' AND NOT coalesce(is_smart,false) AND coalesce(source_type,'manual')<>'smart';
  IF NOT FOUND OR NOT EXISTS (SELECT 1 FROM crm_contacts WHERE id=NEW.contact_id AND organization_id=source_list.organization_id) THEN RETURN NEW; END IF;
  INSERT INTO campaign_trigger_events(organization_id,campaign_id,trigger_id,trigger_snapshot,source_event_id,event_type,contact_id,context)
  SELECT source_list.organization_id,c.id,t.value->>'id',t.value,'list_member_added:' || NEW.id::text,'list_member_added',NEW.contact_id,
    jsonb_build_object('native',true,'listId',NEW.list_id,'memberId',NEW.id,'listName',source_list.name)
  FROM linkedin_campaigns c CROSS JOIN LATERAL jsonb_array_elements(c.entry_triggers) t
  WHERE c.organization_id=source_list.organization_id AND c.status='active'
    AND t.value->>'type'='list_member_added' AND t.value->>'enabled'='true'
    AND nullif(trim(t.value->>'id'),'') IS NOT NULL
    AND t.value->>'channel'='any' AND t.value->'accountIds'='[]'::jsonb
    -- CASE protects list inserts from malformed persisted trigger filters.
    AND jsonb_array_length(CASE WHEN jsonb_typeof(t.value->'listIds')='array' THEN t.value->'listIds' ELSE '[]'::jsonb END) BETWEEN 1 AND 100
    AND NOT EXISTS (
      SELECT 1 FROM jsonb_array_elements(CASE WHEN jsonb_typeof(t.value->'listIds')='array' THEN t.value->'listIds' ELSE '[]'::jsonb END) selected
      WHERE jsonb_typeof(selected)<>'string' OR coalesce(selected #>> '{}','') !~* '^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$'
    )
    AND EXISTS (
      SELECT 1 FROM jsonb_array_elements_text(CASE WHEN jsonb_typeof(t.value->'listIds')='array' THEN t.value->'listIds' ELSE '[]'::jsonb END) selected
      WHERE CASE WHEN selected ~* '^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$' THEN selected::uuid=NEW.list_id ELSE false END
    )
  ON CONFLICT(campaign_id,trigger_id,source_event_id) DO NOTHING;
  RETURN NEW;
END;
$_$;


ALTER FUNCTION "public"."capture_list_member_campaign_entry"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."capture_list_member_campaign_entry_stmt"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
BEGIN
  INSERT INTO campaign_trigger_events(organization_id,campaign_id,trigger_id,trigger_snapshot,source_event_id,event_type,contact_id,context)
  SELECT l.organization_id, c.id, t.value->>'id', t.value, 'list_member_added:' || i.id::text, 'list_member_added', i.contact_id,
    jsonb_build_object('native',true,'listId',i.list_id,'memberId',i.id,'listName',l.name)
  FROM inserted i
  JOIN lead_lists l ON l.id = i.list_id
    AND l.status = 'active' AND NOT coalesce(l.is_smart,false) AND coalesce(l.source_type,'manual') <> 'smart'
  JOIN crm_contacts ct ON ct.id = i.contact_id AND ct.organization_id = l.organization_id
  JOIN linkedin_campaigns c ON c.organization_id = l.organization_id AND c.status = 'active'
  CROSS JOIN LATERAL jsonb_array_elements(c.entry_triggers) t
  WHERE t.value->>'type'='list_member_added' AND t.value->>'enabled'='true'
    AND nullif(trim(t.value->>'id'),'') IS NOT NULL
    AND t.value->>'channel'='any' AND t.value->'accountIds'='[]'::jsonb
    AND jsonb_array_length(CASE WHEN jsonb_typeof(t.value->'listIds')='array' THEN t.value->'listIds' ELSE '[]'::jsonb END) BETWEEN 1 AND 100
    AND NOT EXISTS (
      SELECT 1 FROM jsonb_array_elements(CASE WHEN jsonb_typeof(t.value->'listIds')='array' THEN t.value->'listIds' ELSE '[]'::jsonb END) selected
      WHERE jsonb_typeof(selected)<>'string' OR coalesce(selected #>> '{}','') !~* '^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$'
    )
    AND EXISTS (
      SELECT 1 FROM jsonb_array_elements_text(CASE WHEN jsonb_typeof(t.value->'listIds')='array' THEN t.value->'listIds' ELSE '[]'::jsonb END) selected
      WHERE CASE WHEN selected ~* '^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$' THEN selected::uuid=i.list_id ELSE false END
    )
  ON CONFLICT(campaign_id,trigger_id,source_event_id) DO NOTHING;
  RETURN NULL;
END;
$_$;


ALTER FUNCTION "public"."capture_list_member_campaign_entry_stmt"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."capture_signal_campaign_entry"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE org_id uuid; signal_kind text; source_id text; person crm_contacts%ROWTYPE;
BEGIN
  IF position('signal' in lower(coalesce(NEW.source_data->>'source',''))) = 0 THEN RETURN NEW; END IF;
  SELECT organization_id INTO org_id FROM lead_lists WHERE id=NEW.list_id;
  IF org_id IS NULL THEN RETURN NEW; END IF;
  SELECT * INTO person FROM crm_contacts WHERE id=NEW.contact_id AND organization_id=org_id;
  IF NOT FOUND THEN RETURN NEW; END IF;
  signal_kind := coalesce(NEW.source_data->>'signal_type',person.discovery_metadata->>'signal_type',person.signal_type,'unknown');
  source_id := 'signal:' || coalesce(NEW.source_data->>'public_signal_id',NEW.source_data->>'signal_event_id',person.signal_event_id::text,NEW.id::text) || ':' || person.id::text;
  INSERT INTO campaign_trigger_events(organization_id,campaign_id,trigger_id,trigger_snapshot,source_event_id,event_type,contact_id,context)
  SELECT org_id,c.id,t.value->>'id',t.value,source_id,'signal',person.id,
    jsonb_build_object('signalType',signal_kind,'listId',NEW.list_id,'source',NEW.source_data->>'source','native',true)
  FROM linkedin_campaigns c CROSS JOIN LATERAL jsonb_array_elements(c.entry_triggers) t
  WHERE c.organization_id=org_id AND c.status='active' AND t.value->>'type'='signal' AND t.value->>'enabled'='true'
    AND coalesce(t.value->>'channel','any')='any'
    AND jsonb_array_length(coalesce(t.value->'accountIds','[]'::jsonb))=0
    AND (jsonb_array_length(coalesce(t.value->'signalTypes','[]'::jsonb))=0 OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(t.value->'signalTypes') kind WHERE lower(kind)=lower(signal_kind)))
  ON CONFLICT(campaign_id,trigger_id,source_event_id) DO NOTHING;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."capture_signal_campaign_entry"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_api_rate_limit"("p_key" "text", "p_limit" integer DEFAULT 120, "p_window_seconds" integer DEFAULT 60) RETURNS TABLE("allowed" boolean, "used" integer, "remaining" integer, "reset_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_window_start TIMESTAMPTZ;
  v_count INTEGER;
BEGIN
  v_window_start := to_timestamp(
    floor(extract(epoch FROM clock_timestamp()) / p_window_seconds) * p_window_seconds
  );

  INSERT INTO api_rate_limits (bucket_key, window_start, request_count)
  VALUES (p_key, v_window_start, 1)
  ON CONFLICT (bucket_key, window_start)
  DO UPDATE SET request_count = api_rate_limits.request_count + 1
  RETURNING request_count INTO v_count;

  RETURN QUERY SELECT
    v_count <= p_limit,
    v_count,
    GREATEST(p_limit - v_count, 0),
    v_window_start + make_interval(secs => p_window_seconds);
END;
$$;


ALTER FUNCTION "public"."check_api_rate_limit"("p_key" "text", "p_limit" integer, "p_window_seconds" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_campaign_completion"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE finished integer;
BEGIN
  UPDATE linkedin_campaigns c SET status='completed',completed_at=now(),updated_at=now()
  WHERE c.status='active'
    AND jsonb_array_length(c.entry_triggers)=0
    AND NOT EXISTS (SELECT 1 FROM campaign_lead_progress p WHERE p.campaign_id=c.id AND p.status IN ('pending','waiting','in_progress'));
  GET DIAGNOSTICS finished=ROW_COUNT;
  RETURN finished;
END;
$$;


ALTER FUNCTION "public"."check_campaign_completion"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_channel_limit"("p_organization_id" "uuid", "p_channel" "public"."crm_channel_type", "p_channel_account_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("allowed" boolean, "remaining" integer, "daily_limit" integer, "daily_used" integer, "hourly_limit" integer, "hourly_used" integer, "reason" "text")
    LANGUAGE "plpgsql" STABLE
    AS $$
DECLARE
    v_daily_limit INTEGER;
    v_hourly_limit INTEGER;
    v_daily_used INTEGER;
    v_hourly_used INTEGER;
    v_definition channel_limit_definitions%ROWTYPE;
    v_org_limit organization_channel_limits%ROWTYPE;
    v_account_limit organization_channel_limits%ROWTYPE;
    v_has_account_limit BOOLEAN := false;
    v_has_org_limit BOOLEAN := false;
    v_bh_config organization_channel_limits%ROWTYPE;
    v_current_time TIME;
    v_current_dow INTEGER;
BEGIN
    -- Get channel definition defaults
    SELECT * INTO v_definition FROM channel_limit_definitions WHERE channel = p_channel;
    IF NOT FOUND THEN
        -- Unknown channel type — allow by default
        RETURN QUERY SELECT true, 999, 999, 0, 999, 0, NULL::TEXT;
        RETURN;
    END IF;

    -- 1. Check org-wide limit (channel_account_id IS NULL)
    SELECT * INTO v_org_limit
    FROM organization_channel_limits
    WHERE organization_id = p_organization_id
      AND channel = p_channel
      AND channel_account_id IS NULL;

    v_has_org_limit := FOUND;

    -- 2. Check per-account limit if account ID provided
    IF p_channel_account_id IS NOT NULL THEN
        SELECT * INTO v_account_limit
        FROM organization_channel_limits
        WHERE organization_id = p_organization_id
          AND channel = p_channel
          AND channel_account_id = p_channel_account_id;

        IF FOUND THEN
            v_has_account_limit := true;
        END IF;
    END IF;

    -- Determine effective daily limit (per-account takes priority if set)
    IF v_has_account_limit AND v_account_limit.custom_daily_limit IS NOT NULL THEN
        v_daily_limit := v_account_limit.custom_daily_limit;
    ELSE
        v_daily_limit := get_effective_daily_limit(p_organization_id, p_channel, NULL);
    END IF;

    -- Determine effective hourly limit
    IF v_has_account_limit AND v_account_limit.custom_hourly_limit IS NOT NULL THEN
        v_hourly_limit := v_account_limit.custom_hourly_limit;
    ELSIF v_has_org_limit AND v_org_limit.custom_hourly_limit IS NOT NULL THEN
        v_hourly_limit := v_org_limit.custom_hourly_limit;
    ELSE
        v_hourly_limit := COALESCE(v_definition.absolute_max_hourly, 20);
    END IF;

    -- Get current usage (per-account if provided, otherwise org-wide)
    SELECT COALESCE(SUM(messages_sent), 0) INTO v_daily_used
    FROM channel_usage_tracking
    WHERE organization_id = p_organization_id
      AND channel = p_channel
      AND (
          (p_channel_account_id IS NOT NULL AND channel_account_id = p_channel_account_id)
          OR (p_channel_account_id IS NULL AND channel_account_id IS NULL)
      )
      AND period_date = CURRENT_DATE
      AND period_hour IS NULL;

    SELECT COALESCE(SUM(messages_sent), 0) INTO v_hourly_used
    FROM channel_usage_tracking
    WHERE organization_id = p_organization_id
      AND channel = p_channel
      AND (
          (p_channel_account_id IS NOT NULL AND channel_account_id = p_channel_account_id)
          OR (p_channel_account_id IS NULL AND channel_account_id IS NULL)
      )
      AND period_date = CURRENT_DATE
      AND period_hour = EXTRACT(HOUR FROM now());

    -- Check if disabled
    IF v_has_account_limit AND NOT v_account_limit.is_enabled THEN
        RETURN QUERY SELECT false, 0, 0, v_daily_used, v_hourly_limit, v_hourly_used, 'Channel is disabled for this account'::TEXT;
        RETURN;
    END IF;

    IF v_daily_limit = 0 THEN
        RETURN QUERY SELECT false, 0, 0, v_daily_used, v_hourly_limit, v_hourly_used, 'Channel is disabled'::TEXT;
        RETURN;
    ELSIF v_daily_used >= v_daily_limit THEN
        RETURN QUERY SELECT false, 0, v_daily_limit, v_daily_used, v_hourly_limit, v_hourly_used, 'Daily limit reached'::TEXT;
        RETURN;
    ELSIF v_hourly_used >= v_hourly_limit THEN
        RETURN QUERY SELECT false, 0, v_daily_limit, v_daily_used, v_hourly_limit, v_hourly_used, 'Hourly limit reached'::TEXT;
        RETURN;
    END IF;

    -- Check business hours (from per-account config, fallback to org-wide)
    IF v_has_account_limit THEN
        v_bh_config := v_account_limit;
    ELSIF v_has_org_limit THEN
        v_bh_config := v_org_limit;
    END IF;

    IF (v_has_account_limit OR v_has_org_limit) AND v_bh_config.business_hours_only THEN
        v_current_time := (now() AT TIME ZONE COALESCE(v_bh_config.timezone, 'UTC'))::TIME;
        v_current_dow := EXTRACT(DOW FROM now() AT TIME ZONE COALESCE(v_bh_config.timezone, 'UTC'));

        IF v_current_time < v_bh_config.business_hours_start
           OR v_current_time > v_bh_config.business_hours_end
           OR NOT (v_current_dow = ANY(v_bh_config.active_days)) THEN
            RETURN QUERY SELECT false, v_daily_limit - v_daily_used, v_daily_limit, v_daily_used, v_hourly_limit, v_hourly_used, 'Outside business hours'::TEXT;
            RETURN;
        END IF;
    END IF;

    -- All checks passed
    RETURN QUERY SELECT true, v_daily_limit - v_daily_used, v_daily_limit, v_daily_used, v_hourly_limit, v_hourly_used, NULL::TEXT;
END;
$$;


ALTER FUNCTION "public"."check_channel_limit"("p_organization_id" "uuid", "p_channel" "public"."crm_channel_type", "p_channel_account_id" "uuid") OWNER TO "postgres";


