CREATE OR REPLACE FUNCTION "public"."check_organization_quota"("p_org_id" "uuid", "p_count" integer DEFAULT 1) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_org RECORD;
  v_limits JSONB;
  v_usage JSONB;
  v_daily_generations INT;
  v_monthly_generations INT;
  v_daily_gen_limit INT;
  v_monthly_gen_limit INT;
  v_current_date TEXT;
  v_current_month TEXT;
BEGIN
  -- Get organization with limits
  SELECT plan_tier, limits, current_usage, is_suspended
  INTO v_org
  FROM organizations
  WHERE id = p_org_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'allowed', false,
      'reason', 'Organization not found'
    );
  END IF;

  -- Check if suspended
  IF v_org.is_suspended THEN
    RETURN jsonb_build_object(
      'allowed', false,
      'reason', 'Organization is suspended'
    );
  END IF;

  -- Get default limits based on plan tier (TIGHTENED FREE LIMITS)
  v_limits := CASE v_org.plan_tier
    WHEN 'enterprise' THEN jsonb_build_object(
      'daily_generations', -1,
      'monthly_generations', -1,
      'daily_cost_limit', -1,
      'monthly_cost_limit', -1
    )
    WHEN 'pro' THEN jsonb_build_object(
      'daily_generations', 100,
      'monthly_generations', 2000,
      'daily_cost_limit', 50,
      'monthly_cost_limit', 500
    )
    ELSE jsonb_build_object(
      -- TIGHTENED: was 10/100, now 3/25
      'daily_generations', 3,
      'monthly_generations', 25,
      'daily_cost_limit', 2,
      'monthly_cost_limit', 10
    )
  END;

  -- Merge with custom limits if set
  IF v_org.limits IS NOT NULL AND v_org.limits != '{}'::jsonb THEN
    v_limits := v_limits || v_org.limits;
  END IF;

  -- Get current usage, auto-reset if date/month changed
  v_usage := v_org.current_usage;
  v_current_date := to_char(CURRENT_DATE, 'YYYY-MM-DD');
  v_current_month := to_char(CURRENT_DATE, 'YYYY-MM');

  -- Initialize or reset daily if needed
  IF v_usage IS NULL OR v_usage->'daily' IS NULL OR (v_usage->'daily'->>'date') != v_current_date THEN
    v_daily_generations := 0;
  ELSE
    v_daily_generations := COALESCE((v_usage->'daily'->>'generations')::int, 0);
  END IF;

  -- Initialize or reset monthly if needed
  IF v_usage IS NULL OR v_usage->'monthly' IS NULL OR (v_usage->'monthly'->>'month') != v_current_month THEN
    v_monthly_generations := 0;
  ELSE
    v_monthly_generations := COALESCE((v_usage->'monthly'->>'generations')::int, 0);
  END IF;

  -- Get limits (with tightened defaults)
  v_daily_gen_limit := COALESCE((v_limits->>'daily_generations')::int, 3);
  v_monthly_gen_limit := COALESCE((v_limits->>'monthly_generations')::int, 25);

  -- Check daily limit (-1 means unlimited)
  IF v_daily_gen_limit != -1 AND (v_daily_generations + p_count) > v_daily_gen_limit THEN
    -- Record the limit hit
    PERFORM record_limit_hit(p_org_id, 'daily');

    RETURN jsonb_build_object(
      'allowed', false,
      'reason', format('Daily limit reached (%s/%s)', v_daily_generations, v_daily_gen_limit),
      'limit_type', 'daily',
      'usage', jsonb_build_object(
        'daily_generations', v_daily_generations,
        'monthly_generations', v_monthly_generations
      ),
      'limits', v_limits
    );
  END IF;

  -- Check monthly limit (-1 means unlimited)
  IF v_monthly_gen_limit != -1 AND (v_monthly_generations + p_count) > v_monthly_gen_limit THEN
    -- Record the limit hit
    PERFORM record_limit_hit(p_org_id, 'monthly');

    RETURN jsonb_build_object(
      'allowed', false,
      'reason', format('Monthly limit reached (%s/%s)', v_monthly_generations, v_monthly_gen_limit),
      'limit_type', 'monthly',
      'usage', jsonb_build_object(
        'daily_generations', v_daily_generations,
        'monthly_generations', v_monthly_generations
      ),
      'limits', v_limits
    );
  END IF;

  -- All checks passed
  RETURN jsonb_build_object(
    'allowed', true,
    'usage', jsonb_build_object(
      'daily_generations', v_daily_generations,
      'monthly_generations', v_monthly_generations
    ),
    'limits', v_limits
  );
END;
$$;


ALTER FUNCTION "public"."check_organization_quota"("p_org_id" "uuid", "p_count" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_provisioning_rate_limit"("p_key" "text", "p_limit" integer, "p_window_seconds" integer) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_hits integer;
begin
  insert into provisioning_rate_limit as r (key, hits, window_started_at, last_seen_at)
  values (p_key, 1, now(), now())
  on conflict (key) do update
    set hits = case
          when r.window_started_at < now() - make_interval(secs => p_window_seconds) then 1
          else r.hits + 1
        end,
        window_started_at = case
          when r.window_started_at < now() - make_interval(secs => p_window_seconds) then now()
          else r.window_started_at
        end,
        last_seen_at = now()
  returning hits into v_hits;

  return v_hits <= p_limit;
end;
$$;


ALTER FUNCTION "public"."check_provisioning_rate_limit"("p_key" "text", "p_limit" integer, "p_window_seconds" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_unipile_rate_limit"("p_account_id" "uuid", "p_max_per_hour" integer, "p_max_per_day" integer) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_hour_count INTEGER;
  v_day_count INTEGER;
BEGIN
  -- Count messages sent in last hour
  SELECT COUNT(*) INTO v_hour_count
  FROM unipile_message_queue
  WHERE account_id = p_account_id
    AND status = 'sent'
    AND sent_at >= NOW() - INTERVAL '1 hour';

  IF v_hour_count >= p_max_per_hour THEN
    RETURN FALSE;
  END IF;

  -- Count messages sent in last day
  SELECT COUNT(*) INTO v_day_count
  FROM unipile_message_queue
  WHERE account_id = p_account_id
    AND status = 'sent'
    AND sent_at >= NOW() - INTERVAL '1 day';

  RETURN v_day_count < p_max_per_day;
END;
$$;


ALTER FUNCTION "public"."check_unipile_rate_limit"("p_account_id" "uuid", "p_max_per_hour" integer, "p_max_per_day" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_apify_leads_import_job"("p_job_id" "uuid", "p_lock_seconds" integer DEFAULT 300) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_id uuid;
BEGIN
  UPDATE public.apify_leads_import_jobs
  SET metadata = jsonb_set(
        COALESCE(metadata, '{}'::jsonb),
        '{poller_lock_at}',
        to_jsonb(now())
      )
  WHERE id = p_job_id
    AND status = 'running'
    AND (
      metadata->>'poller_lock_at' IS NULL
      OR (metadata->>'poller_lock_at')::timestamptz < now() - make_interval(secs => p_lock_seconds)
    )
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;


