    "context" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "reason" "text",
    "icp_score" numeric,
    "decision_state" "text",
    "provider_decision" "text",
    "reviewed_by" "uuid",
    "reviewed_at" timestamp with time zone,
    "lease_until" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "processed_at" timestamp with time zone,
    CONSTRAINT "campaign_trigger_events_event_type_check" CHECK (("event_type" = ANY (ARRAY['connection_request'::"text", 'message_received'::"text", 'post_comment'::"text", 'keyword_match'::"text", 'signal'::"text", 'integration_event'::"text", 'list_member_added'::"text"]))),
    CONSTRAINT "campaign_trigger_events_provider_decision_check" CHECK ((("provider_decision" IS NULL) OR ("provider_decision" = ANY (ARRAY['accept'::"text", 'decline'::"text"])))),
    CONSTRAINT "campaign_trigger_events_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'processing'::"text", 'review'::"text", 'enrolled'::"text", 'ignored'::"text", 'declined'::"text", 'error'::"text"])))
);


ALTER TABLE "public"."campaign_trigger_events" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_campaign_trigger_events"("p_limit" integer DEFAULT 10) RETURNS SETOF "public"."campaign_trigger_events"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  -- A crashed provider call has an uncertain outcome; it must never be retried automatically.
  UPDATE campaign_trigger_events e SET status = 'review', reason = 'Processing interrupted. Review the provider outcome before continuing.', lease_until = NULL,
    decision_state = CASE WHEN EXISTS (SELECT 1 FROM campaign_trigger_invite_decisions d WHERE d.account_id=e.account_id AND d.invitation_id=e.context->>'invitationId' AND d.state<>'completed') THEN 'provider_unknown' ELSE e.decision_state END
    WHERE e.status = 'processing' AND e.lease_until < now();
  RETURN QUERY WITH picked AS (
    SELECT e.id FROM campaign_trigger_events e WHERE e.status = 'pending'
      AND EXISTS (SELECT 1 FROM linkedin_campaigns c WHERE c.id=e.campaign_id AND c.organization_id=e.organization_id AND c.status='active')
      ORDER BY e.created_at,e.id LIMIT least(greatest(p_limit,1),25) FOR UPDATE SKIP LOCKED
  ) UPDATE campaign_trigger_events e SET status = 'processing', lease_until = now() + interval '10 minutes'
    FROM picked WHERE e.id = picked.id RETURNING e.*;
END;
$$;


ALTER FUNCTION "public"."claim_campaign_trigger_events"("p_limit" integer) OWNER TO "postgres";


