COMMENT ON TABLE "public"."crm_contacts" IS 'Unified CRM contacts - person-centric, not channel-centric';



COMMENT ON COLUMN "public"."crm_contacts"."contact_type" IS 'Classification: prospect (cold list), lead (showed intent), contact (established relationship)';



COMMENT ON COLUMN "public"."crm_contacts"."outreach_status" IS 'Tracks outreach status: unreached (no contact), reached (message sent), replied (got response)';



COMMENT ON COLUMN "public"."crm_contacts"."ai_analysis_status" IS 'Tracks AI analysis status: not_analyzed, analyzing, analyzed, failed';



