CREATE OR REPLACE FUNCTION "public"."claim_contacts_for_moltsets"("p_lead_list_id" "uuid", "p_batch_size" integer) RETURNS SETOF "public"."crm_contacts"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  UPDATE crm_contacts SET moltsets_attempted_at = now()
  WHERE id IN (
    SELECT lm.contact_id FROM lead_list_members lm
    JOIN crm_contacts c ON c.id = lm.contact_id
    WHERE lm.list_id = p_lead_list_id
      AND c.primary_email IS NULL
      AND c.moltsets_attempted_at IS NULL
      AND c.primary_linkedin_url IS NOT NULL
    LIMIT p_batch_size
    FOR UPDATE OF c SKIP LOCKED
  )
  RETURNING *;
$$;


ALTER FUNCTION "public"."claim_contacts_for_moltsets"("p_lead_list_id" "uuid", "p_batch_size" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_contacts_for_quickenrich"("p_lead_list_id" "uuid", "p_batch_size" integer) RETURNS SETOF "public"."crm_contacts"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  UPDATE crm_contacts SET quickenrich_attempted_at = now()
  WHERE id IN (
    SELECT lm.contact_id FROM lead_list_members lm
    JOIN crm_contacts c ON c.id = lm.contact_id
    WHERE lm.list_id = p_lead_list_id
      AND c.primary_email IS NULL
      AND c.quickenrich_attempted_at IS NULL
      AND (
        c.primary_linkedin_url IS NOT NULL
        OR (c.company IS NOT NULL AND c.first_name IS NOT NULL AND c.last_name IS NOT NULL)
        OR (c.company_website IS NOT NULL AND c.first_name IS NOT NULL AND c.last_name IS NOT NULL)
      )
    LIMIT p_batch_size
    FOR UPDATE OF c SKIP LOCKED
  )
  RETURNING *;
$$;


ALTER FUNCTION "public"."claim_contacts_for_quickenrich"("p_lead_list_id" "uuid", "p_batch_size" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_crm_contacts_for_firmographics"("p_org_id" "uuid" DEFAULT NULL::"uuid", "p_batch_size" integer DEFAULT 100, "p_recheck_days" integer DEFAULT 90) RETURNS SETOF "public"."crm_contacts"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  UPDATE public.crm_contacts c SET firmographics_checked_at = now()
  WHERE c.id IN (
    SELECT q.id FROM public.crm_contacts q
    WHERE (p_org_id IS NULL OR q.organization_id = p_org_id)
      AND (q.company_employee_count IS NULL OR q.company_revenue_range IS NULL OR q.company_industry IS NULL)
      AND (q.firmographics_checked_at IS NULL OR q.firmographics_checked_at < now() - make_interval(days => GREATEST(p_recheck_days, 1)))
      AND (NULLIF(q.primary_linkedin_url, '') IS NOT NULL OR NULLIF(q.company_website, '') IS NOT NULL OR q.company_id IS NOT NULL)
    -- Match idx_crm_contacts_firmographics_candidates for both global and
    -- org-scoped claims. Without organization_id first, a global cron claim
    -- sorts/scans the entire multi-million-row table before returning 100.
    ORDER BY q.organization_id, q.firmographics_checked_at NULLS FIRST, q.first_seen_at DESC
    LIMIT GREATEST(LEAST(p_batch_size, 500), 1)
    FOR UPDATE SKIP LOCKED
  ) RETURNING c.*;
$$;


ALTER FUNCTION "public"."claim_crm_contacts_for_firmographics"("p_org_id" "uuid", "p_batch_size" integer, "p_recheck_days" integer) OWNER TO "postgres";


