COMMENT ON TABLE "public"."email_enrollment_jobs" IS 'Background enrollment of list audiences into an email sequence. Written by enroll-leads (background: true) and process-email-enrollment-jobs.';



CREATE OR REPLACE FUNCTION "public"."claim_email_enrollment_job"("p_lease_seconds" integer DEFAULT 180, "p_job_id" "uuid" DEFAULT NULL::"uuid") RETURNS SETOF "public"."email_enrollment_jobs"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  UPDATE public.email_enrollment_jobs j
  SET lease_until = NOW() + make_interval(secs => p_lease_seconds),
      started_at = COALESCE(j.started_at, NOW()),
      status = CASE WHEN j.status = 'pending' THEN 'snapshotting' ELSE j.status END,
      updated_at = NOW()
  WHERE j.id = (
    SELECT c.id FROM public.email_enrollment_jobs c
    WHERE c.status IN ('pending','snapshotting','running')
      AND (c.lease_until IS NULL OR c.lease_until < NOW())
      AND (p_job_id IS NULL OR c.id = p_job_id)
    ORDER BY c.created_at
    LIMIT 1
    FOR UPDATE SKIP LOCKED
  )
  RETURNING j.*;
END;
$$;


