CREATE TABLE IF NOT EXISTS "public"."lb_work_items" (
    "id" bigint NOT NULL,
    "job_id" "uuid" NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "stage" "text" NOT NULL,
    "payload" "jsonb" NOT NULL,
    "priority" integer DEFAULT 5 NOT NULL,
    "status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "claimed_by" "text",
    "claimed_at" timestamp with time zone,
    "completed_at" timestamp with time zone,
    "error" "text",
    "attempts" integer DEFAULT 0 NOT NULL,
    "max_attempts" integer DEFAULT 3 NOT NULL,
    "depends_on" bigint,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "lb_work_items_stage_check" CHECK (("stage" = ANY (ARRAY['discovery'::"text", 'dm'::"text", 'pattern'::"text", 'smtp'::"text", 'icp'::"text", 'enrich'::"text", 'profile_email'::"text"]))),
    CONSTRAINT "lb_work_items_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'claimed'::"text", 'completed'::"text", 'failed'::"text", 'dead'::"text"])))
);


ALTER TABLE "public"."lb_work_items" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_lb_work_items"("p_worker_id" "text", "p_stage" "text", "p_batch_size" integer) RETURNS SETOF "public"."lb_work_items"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  WITH picked AS (
    SELECT w.id
    FROM public.lb_work_items w
    JOIN public.list_building_jobs j ON j.id = w.job_id
    WHERE w.status = 'pending'
      AND w.stage = p_stage
      AND j.status = 'running'
      AND (
        w.depends_on IS NULL
        OR EXISTS (
          SELECT 1 FROM public.lb_work_items d
          WHERE d.id = w.depends_on AND d.status = 'completed'
        )
      )
    ORDER BY w.priority DESC, w.created_at
    LIMIT p_batch_size
    FOR UPDATE OF w SKIP LOCKED
  )
  UPDATE public.lb_work_items w
  SET status = 'claimed',
      claimed_by = p_worker_id,
      claimed_at = NOW(),
      attempts = w.attempts + 1,
      updated_at = NOW()
  FROM picked
  WHERE w.id = picked.id
  RETURNING w.*;
END;
$$;


ALTER FUNCTION "public"."claim_lb_work_items"("p_worker_id" "text", "p_stage" "text", "p_batch_size" integer) OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."lead_list_processing_items" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "policy_id" "uuid" NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "lead_list_id" "uuid" NOT NULL,
    "contact_id" "uuid" NOT NULL,
    "status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "stage" "text" DEFAULT 'queued'::"text" NOT NULL,
    "attempts" integer DEFAULT 0 NOT NULL,
    "next_attempt_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "claimed_at" timestamp with time zone,
    "completed_at" timestamp with time zone,
    "rejected_reason" "text",
    "last_error" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "manual_run" boolean DEFAULT false NOT NULL,
    "cancel_requested_at" timestamp with time zone,
    "canceled_at" timestamp with time zone,
    "pause_requested_at" timestamp with time zone,
    "failure_category" "text",
    "recovery_attempts" integer DEFAULT 0 NOT NULL,
    "replacement_attempts" integer DEFAULT 0 NOT NULL,
    "analysis_reused" boolean DEFAULT false NOT NULL,
    "force_reprocess" boolean DEFAULT false NOT NULL,
    "contact_has_email" boolean DEFAULT false NOT NULL,
    "contact_email_verification_status" "text",
    "contact_email_search_attempted" boolean DEFAULT false NOT NULL,
    CONSTRAINT "lead_list_processing_items_failure_category_check" CHECK ((("failure_category" IS NULL) OR ("failure_category" = ANY (ARRAY['no_source_data'::"text", 'transient'::"text", 'unknown'::"text"])))),
    CONSTRAINT "lead_list_processing_items_stage_check" CHECK (("stage" = ANY (ARRAY['queued'::"text", 'analyzing_icp'::"text", 'finding_email'::"text", 'verifying_email'::"text", 'replacement_email_found'::"text", 'writing_message'::"text", 'enrolling'::"text", 'completed'::"text", 'rejected'::"text", 'failed'::"text", 'canceled'::"text"]))),
    CONSTRAINT "lead_list_processing_items_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'processing'::"text", 'retry'::"text", 'completed'::"text", 'rejected'::"text", 'failed'::"text", 'canceled'::"text"])))
);


ALTER TABLE "public"."lead_list_processing_items" OWNER TO "postgres";


COMMENT ON COLUMN "public"."lead_list_processing_items"."replacement_attempts" IS 'How many times find_email has swapped in a replacement address for this contact after a non-valid verification. Caps the verify<->find re-search loop.';



COMMENT ON COLUMN "public"."lead_list_processing_items"."analysis_reused" IS 'TRUE when the ICP stage reused a stored company analysis instead of re-crawling. Feeds the "N reused" figure on the run status card.';



COMMENT ON COLUMN "public"."lead_list_processing_items"."force_reprocess" IS 'Set by a full list reset. Makes the next run execute configured ICP, enrichment, and verification stages even when shared contact data is still fresh.';



CREATE OR REPLACE FUNCTION "public"."claim_lead_list_processing_items"("p_limit" integer DEFAULT 10, "p_list_id" "uuid" DEFAULT NULL::"uuid") RETURNS SETOF "public"."lead_list_processing_items"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  UPDATE public.lead_list_processing_items item
  SET status = CASE WHEN item.cancel_requested_at IS NOT NULL THEN 'canceled'
                    WHEN item.pause_requested_at IS NOT NULL THEN 'pending' ELSE 'retry' END,
      stage = CASE WHEN item.cancel_requested_at IS NOT NULL THEN 'canceled' ELSE item.stage END,
      next_attempt_at = NOW(), claimed_at = NULL,
      completed_at = CASE WHEN item.cancel_requested_at IS NOT NULL THEN NOW() ELSE NULL END,
      canceled_at = CASE WHEN item.cancel_requested_at IS NOT NULL THEN NOW() ELSE item.canceled_at END,
      pause_requested_at = NULL,
      last_error = CASE WHEN item.cancel_requested_at IS NOT NULL OR item.pause_requested_at IS NOT NULL THEN NULL
                        ELSE 'Processing lease expired; retrying' END,
      updated_at = NOW()
  WHERE item.status = 'processing' AND item.updated_at < NOW() - INTERVAL '15 minutes';

  INSERT INTO public.lead_list_processing_items (policy_id, organization_id, lead_list_id, contact_id)
  SELECT policy.id, policy.organization_id, policy.lead_list_id, eligible.contact_id
  FROM public.lead_list_processing_policies policy
  JOIN public.lead_lists list ON list.id = policy.lead_list_id AND list.is_smart = TRUE
  CROSS JOIN LATERAL public.smart_list_eligible_contact_ids(policy.lead_list_id) AS eligible(contact_id)
  WHERE policy.enabled = TRUE AND (p_list_id IS NULL OR policy.lead_list_id = p_list_id)
  ON CONFLICT (policy_id, contact_id) DO NOTHING;

  RETURN QUERY
  WITH ready AS (
    SELECT item.id,
      CASE item.stage WHEN 'enrolling' THEN 0 WHEN 'replacement_email_found' THEN 0
        WHEN 'writing_message' THEN 0
        WHEN 'verifying_email' THEN 1 WHEN 'finding_email' THEN 2
        WHEN 'analyzing_icp' THEN 3 WHEN 'failed' THEN 4 WHEN 'queued' THEN 5 ELSE 4 END AS stage_priority,
      item.next_attempt_at,
      item.created_at,
      ROW_NUMBER() OVER (
        PARTITION BY item.lead_list_id, item.stage
        ORDER BY item.next_attempt_at, item.created_at
      ) AS stage_turn
    FROM public.lead_list_processing_items item
    JOIN public.lead_list_processing_policies policy ON policy.id = item.policy_id
    WHERE (policy.enabled = TRUE OR item.manual_run = TRUE)
      AND policy.paused_at IS NULL AND item.pause_requested_at IS NULL
      AND item.status IN ('pending', 'retry') AND item.next_attempt_at <= NOW()
      AND (p_list_id IS NULL OR item.lead_list_id = p_list_id)
  ), locked AS (
    SELECT target.id
    FROM ready
    JOIN public.lead_list_processing_items target ON target.id = ready.id
    WHERE target.status IN ('pending', 'retry')
    ORDER BY ready.stage_turn, ready.stage_priority, ready.next_attempt_at, ready.created_at
    LIMIT GREATEST(1, LEAST(p_limit, 25))
    FOR UPDATE OF target SKIP LOCKED
  )
  UPDATE public.lead_list_processing_items item
  SET status = 'processing', claimed_at = NOW(), attempts = item.attempts + 1, updated_at = NOW()
  FROM locked WHERE item.id = locked.id AND item.status IN ('pending', 'retry')
  RETURNING item.*;
END;
$$;


ALTER FUNCTION "public"."claim_lead_list_processing_items"("p_limit" integer, "p_list_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_lead_list_source"("p_source_id" "uuid", "p_lock_seconds" integer DEFAULT 600) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_id uuid;
BEGIN
  UPDATE public.lead_list_sources
  SET state = jsonb_set(
        COALESCE(state, '{}'::jsonb),
        '{poller_lock_at}',
        to_jsonb(now())
      )
  WHERE id = p_source_id
    AND status = 'active'
    AND (
      state->>'poller_lock_at' IS NULL
      OR (state->>'poller_lock_at')::timestamptz < now() - make_interval(secs => p_lock_seconds)
    )
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;


ALTER FUNCTION "public"."claim_lead_list_source"("p_source_id" "uuid", "p_lock_seconds" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_pack_refresh_job"("p_job_id" "uuid", "p_lock_seconds" integer DEFAULT 300) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_id UUID;
BEGIN
  UPDATE public.pack_refresh_jobs
     SET poll_lock_until = NOW() + make_interval(secs => p_lock_seconds)
   WHERE id = p_job_id
     AND (poll_lock_until IS NULL OR poll_lock_until < NOW())
  RETURNING id INTO v_id;
  RETURN v_id;  -- NULL if no match (another worker holds the lock)
END;
$$;


ALTER FUNCTION "public"."claim_pack_refresh_job"("p_job_id" "uuid", "p_lock_seconds" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_pending_dm_work_items"("p_batch_size" integer DEFAULT 20, "p_claimed_by" "text" DEFAULT 'edge:list-building-dm-scraper'::"text") RETURNS SETOF "public"."lb_work_items"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH due AS (
    SELECT item.id
    FROM public.lb_work_items item
    WHERE item.stage = 'dm'
      AND item.status = 'pending'
    ORDER BY item.priority DESC, item.created_at, item.id
    LIMIT GREATEST(LEAST(p_batch_size, 100), 1)
    FOR UPDATE SKIP LOCKED
  ), claimed AS (
    UPDATE public.lb_work_items item
    SET status = 'claimed',
        claimed_by = p_claimed_by,
        claimed_at = now(),
        updated_at = now()
    FROM due
    WHERE item.id = due.id
    RETURNING item.*
  )
  SELECT * FROM claimed;
$$;


ALTER FUNCTION "public"."claim_pending_dm_work_items"("p_batch_size" integer, "p_claimed_by" "text") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."pool_add_to_list_jobs" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "target_list_id" "uuid" NOT NULL,
    "created_by" "uuid",
    "query_body" "jsonb" NOT NULL,
    "status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "total" integer DEFAULT 0,
    "processed" integer DEFAULT 0,
    "errors" integer DEFAULT 0,
    "error_message" "text",
    "current_offset" integer DEFAULT 0,
    "created_at" timestamp with time zone DEFAULT "now"(),
    "started_at" timestamp with time zone,
    "completed_at" timestamp with time zone,
    "cursor_id" character varying,
    "cursor_row_count" bigint,
    "lease_until" timestamp with time zone,
    CONSTRAINT "pool_add_to_list_jobs_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'running'::"text", 'completed'::"text", 'failed'::"text", 'cancelled'::"text"])))
);


ALTER TABLE "public"."pool_add_to_list_jobs" OWNER TO "postgres";


COMMENT ON COLUMN "public"."pool_add_to_list_jobs"."cursor_id" IS 'Worker-side cursor handle from /search/cursor/start. NULL = legacy offset-paged job.';



COMMENT ON COLUMN "public"."pool_add_to_list_jobs"."cursor_row_count" IS 'Exact materialized row count returned by /search/cursor/start. Used as the job total.';



COMMENT ON COLUMN "public"."pool_add_to_list_jobs"."lease_until" IS 'Exclusive claim held by one worker tick. A job is claimable when this is NULL or in the past.';



CREATE OR REPLACE FUNCTION "public"."claim_pool_add_to_list_job"("p_lease_seconds" integer DEFAULT 300, "p_job_id" "uuid" DEFAULT NULL::"uuid") RETURNS SETOF "public"."pool_add_to_list_jobs"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  UPDATE pool_add_to_list_jobs j
  SET lease_until = now() + make_interval(secs => p_lease_seconds)
  WHERE j.id = (
    SELECT c.id
    FROM pool_add_to_list_jobs c
    WHERE c.status IN ('pending', 'running')
      AND (c.lease_until IS NULL OR c.lease_until < now())
      AND (p_job_id IS NULL OR c.id = p_job_id)
    ORDER BY c.created_at
    LIMIT 1
    FOR UPDATE SKIP LOCKED
  )
  RETURNING j.*;
END;
$$;


ALTER FUNCTION "public"."claim_pool_add_to_list_job"("p_lease_seconds" integer, "p_job_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."claim_pool_add_to_list_job"("p_lease_seconds" integer, "p_job_id" "uuid") IS 'Atomically leases one pending/running pool build job. Returns no rows when every job is already claimed.';



CREATE TABLE IF NOT EXISTS "public"."lead_pool_classify_queue" (
    "domain" "text" NOT NULL,
    "priority" smallint DEFAULT 100 NOT NULL,
    "source" "text",
    "status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "attempts" smallint DEFAULT 0 NOT NULL,
    "lease_until" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "completed_at" timestamp with time zone
);


ALTER TABLE "public"."lead_pool_classify_queue" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_pool_classify_batch"("p_limit" integer DEFAULT 50, "p_lease_seconds" integer DEFAULT 600) RETURNS SETOF "public"."lead_pool_classify_queue"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  return query
  update lead_pool_classify_queue q
     set lease_until = now() + make_interval(secs => p_lease_seconds),
         attempts = q.attempts + 1
   where q.domain in (
     select c.domain from lead_pool_classify_queue c
      where c.status = 'pending'
        and (c.lease_until is null or c.lease_until < now())
        and c.attempts < 3
      order by c.priority, c.created_at
      limit p_limit for update skip locked)
  returning q.*;
end; $$;


ALTER FUNCTION "public"."claim_pool_classify_batch"("p_limit" integer, "p_lease_seconds" integer) OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."lead_pool_enrich_queue" (
    "domain" "text" NOT NULL,
    "linkedin_url" "text" NOT NULL,
    "priority" smallint DEFAULT 100 NOT NULL,
    "source" "text",
    "requested_by" "uuid",
    "status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "attempts" smallint DEFAULT 0 NOT NULL,
    "last_error" "text",
    "lease_until" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "completed_at" timestamp with time zone
);


ALTER TABLE "public"."lead_pool_enrich_queue" OWNER TO "postgres";


COMMENT ON TABLE "public"."lead_pool_enrich_queue" IS 'Domains awaiting MoltSets reverse_linkedin_lookup. Demand-driven on purpose: the ~75k records/week ceiling means a blind sweep of the 2.19M reachable domains would take ~29 weeks, so the budget goes to domains someone is actually about to use.';



CREATE OR REPLACE FUNCTION "public"."claim_pool_enrich_batch"("p_limit" integer DEFAULT 25, "p_lease_seconds" integer DEFAULT 300) RETURNS SETOF "public"."lead_pool_enrich_queue"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  return query
  update lead_pool_enrich_queue q
     set lease_until = now() + make_interval(secs => p_lease_seconds),
         attempts    = q.attempts + 1
   where q.domain in (
     select c.domain
       from lead_pool_enrich_queue c
      where c.status = 'pending'
        and (c.lease_until is null or c.lease_until < now())
        and c.attempts < 3
      order by c.priority, c.created_at
      limit p_limit
      for update skip locked
   )
  returning q.*;
end;
$$;


ALTER FUNCTION "public"."claim_pool_enrich_batch"("p_limit" integer, "p_lease_seconds" integer) OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."pool_export_jobs" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "created_by" "uuid",
    "query_body" "jsonb" NOT NULL,
    "dedup_by_email" boolean DEFAULT true NOT NULL,
    "status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "estimated_rows" bigint,
    "total_rows" bigint,
    "slice_rows" integer,
    "next_slice" integer DEFAULT 0 NOT NULL,
    "slices_total" integer,
    "rows_written" bigint DEFAULT 0 NOT NULL,
    "r2_prefix" "text",
    "parts" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "expires_at" timestamp with time zone,
    "error_message" "text",
    "attempts" integer DEFAULT 0 NOT NULL,
    "lease_until" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "started_at" timestamp with time zone,
    "completed_at" timestamp with time zone,
    CONSTRAINT "pool_export_jobs_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'materializing'::"text", 'running'::"text", 'completed'::"text", 'failed'::"text", 'cancelled'::"text"])))
);


ALTER TABLE "public"."pool_export_jobs" OWNER TO "postgres";


COMMENT ON TABLE "public"."pool_export_jobs" IS 'Async NDJSON exports of the lead pool to R2. Holds job state and object keys only - lead rows go DuckDB -> R2 and never enter Postgres.';



COMMENT ON COLUMN "public"."pool_export_jobs"."parts" IS 'Ordered [{key,rows}] of R2 objects. Keys only: presigned URLs are minted per read so a leaked API response expires in an hour.';



CREATE OR REPLACE FUNCTION "public"."claim_pool_export_job"("p_lease_seconds" integer DEFAULT 300, "p_job_id" "uuid" DEFAULT NULL::"uuid") RETURNS SETOF "public"."pool_export_jobs"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  UPDATE public.pool_export_jobs j
  SET lease_until = NOW() + make_interval(secs => p_lease_seconds)
  WHERE j.id = (
    SELECT c.id
    FROM public.pool_export_jobs c
    WHERE c.status IN ('pending','materializing','running')
      AND (c.lease_until IS NULL OR c.lease_until < NOW())
      AND (p_job_id IS NULL OR c.id = p_job_id)
      AND NOT EXISTS (
        SELECT 1 FROM public.pool_export_jobs o
        WHERE o.status IN ('materializing','running')
          AND o.lease_until > NOW()
          AND o.id <> c.id
      )
    ORDER BY c.created_at
    LIMIT 1
    FOR UPDATE SKIP LOCKED
  )
  RETURNING j.*;
END;
$$;


ALTER FUNCTION "public"."claim_pool_export_job"("p_lease_seconds" integer, "p_job_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_profile_email_items"("p_batch_size" integer DEFAULT 20) RETURNS TABLE("id" bigint, "job_id" "uuid", "organization_id" "uuid", "payload" "jsonb")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  WITH claimed AS (
    SELECT wi.id AS wi_id
    FROM public.lb_work_items wi
    WHERE wi.stage = 'profile_email'
      AND wi.status = 'pending'
      AND (wi.attempts IS NULL OR wi.attempts < wi.max_attempts)
    ORDER BY wi.priority DESC, wi.created_at ASC
    LIMIT p_batch_size
    FOR UPDATE SKIP LOCKED
  ),
  updated AS (
    UPDATE public.lb_work_items wi
       SET status = 'claimed',
           claimed_at = NOW(),
           claimed_by = 'profile-email-finder',
           attempts = COALESCE(wi.attempts, 0) + 1,
           updated_at = NOW()
     WHERE wi.id IN (SELECT c.wi_id FROM claimed c)
     RETURNING wi.id AS row_id, wi.job_id, wi.organization_id, wi.payload
  )
  SELECT u.row_id, u.job_id, u.organization_id, u.payload FROM updated u;
END;
$$;


ALTER FUNCTION "public"."claim_profile_email_items"("p_batch_size" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_public_signal_companies_for_quickenrich"("p_batch_size" integer DEFAULT 10, "p_lookback_days" integer DEFAULT 14) RETURNS TABLE("company_key" "text", "company_name" "text", "domain" "text", "company_linkedin_url" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_inflight_domains text[] := ARRAY[]::text[];
  v_claimed_domains text[] := ARRAY[]::text[];
  v_domain_key text;
  v_row record;
BEGIN
  -- One short database transaction owns queue selection globally. Provider
  -- calls happen after commit, so this lock never spans network activity.
  PERFORM pg_advisory_xact_lock(
    hashtextextended('public-signal-quickenrich-domain-claim', 0)
  );

  SELECT COALESCE(array_agg(DISTINCT lower(btrim(q.domain))), ARRAY[]::text[])
  INTO v_inflight_domains
  FROM public.public_signal_people_enrichment_state q
  WHERE q.status = 'claimed'
    AND q.lease_expires_at > now()
    AND COALESCE(btrim(q.domain), '') <> '';

  -- A provider miss is reusable evidence too. Apply the longest live negative
  -- TTL to every alias of the same exact domain before anything can be claimed.
  UPDATE public.public_signal_people_enrichment_state AS target
  SET status = 'not_found',
      provider = cached.provider,
      people_found = 0,
      pages_fetched = cached.pages_fetched,
      completed_at = cached.completed_at,
      lease_expires_at = NULL,
      next_attempt_at = cached.next_attempt_at,
      last_error = NULL,
      updated_at = now()
  FROM (
    SELECT DISTINCT ON (lower(btrim(source.domain)))
      lower(btrim(source.domain)) AS domain_key,
      source.company_key,
      source.provider,
      source.pages_fetched,
      source.completed_at,
      source.next_attempt_at
    FROM public.public_signal_people_enrichment_state source
    WHERE source.status = 'not_found'
      AND source.next_attempt_at > now()
      AND COALESCE(btrim(source.domain), '') <> ''
    ORDER BY lower(btrim(source.domain)), source.next_attempt_at DESC
  ) cached
  WHERE lower(btrim(target.domain)) = cached.domain_key
    AND target.company_key <> cached.company_key
    AND target.status IN ('pending', 'failed', 'not_found')
    AND target.next_attempt_at < cached.next_attempt_at;

  FOR v_row IN
    SELECT claimed.*
    FROM public.claim_public_signal_companies_for_quickenrich_by_company(
      p_batch_size,
      p_lookback_days
    ) claimed
    ORDER BY lower(btrim(claimed.domain)), claimed.company_key
  LOOP
    v_domain_key := lower(btrim(v_row.domain));
    IF v_domain_key = ANY(v_inflight_domains)
       OR v_domain_key = ANY(v_claimed_domains) THEN
      UPDATE public.public_signal_people_enrichment_state q
      SET status = 'pending',
          lease_expires_at = NULL,
          next_attempt_at = GREATEST(q.next_attempt_at, now() + interval '5 minutes'),
          updated_at = now()
      WHERE q.company_key = v_row.company_key;
      CONTINUE;
    END IF;

    v_claimed_domains := array_append(v_claimed_domains, v_domain_key);
    company_key := v_row.company_key;
    company_name := v_row.company_name;
    domain := v_row.domain;
    company_linkedin_url := v_row.company_linkedin_url;
    RETURN NEXT;
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."claim_public_signal_companies_for_quickenrich"("p_batch_size" integer, "p_lookback_days" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_public_signal_companies_for_quickenrich_by_company"("p_batch_size" integer DEFAULT 10, "p_lookback_days" integer DEFAULT 14) RETURNS TABLE("company_key" "text", "company_name" "text", "domain" "text", "company_linkedin_url" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  INSERT INTO public.public_signal_people_enrichment_state AS q
    (company_key, company_name, domain, company_linkedin_url, last_signal_date)
  SELECT DISTINCT ON (lower(btrim(s.company_name)))
    lower(btrim(s.company_name)), btrim(s.company_name), lower(btrim(s.domain)),
    s.company_linkedin_url, s.signal_date
  FROM public.public_signals s
  WHERE s.published
    AND s.source_key = 'aca_native'
    AND s.signal_date >= current_date - GREATEST(p_lookback_days, 1)
    AND COALESCE(btrim(s.company_name), '') <> ''
    AND COALESCE(btrim(s.domain), '') <> ''
  ORDER BY lower(btrim(s.company_name)), s.signal_date DESC, s.quality_score DESC, s.created_at DESC
  ON CONFLICT ON CONSTRAINT public_signal_people_enrichment_state_pkey DO UPDATE SET
    company_name = EXCLUDED.company_name,
    domain = EXCLUDED.domain,
    company_linkedin_url = COALESCE(EXCLUDED.company_linkedin_url, q.company_linkedin_url),
    last_signal_date = GREATEST(q.last_signal_date, EXCLUDED.last_signal_date),
    updated_at = now();

  WITH reusable AS (
    SELECT DISTINCT ON (q.company_key, p.linkedin_url)
      q.company_key AS target_company_key,
      q.company_linkedin_url AS target_company_linkedin_url,
      q.domain AS target_domain,
      p.full_name, p.title, p.linkedin_url, p.photo_url, p.seniority_rank,
      p.email, p.email_status, p.enriched_at
    FROM public.public_signal_people_enrichment_state q
    JOIN public.public_signal_people p
      ON lower(btrim(p.domain)) = lower(btrim(q.domain))
     AND p.company_key <> q.company_key
    WHERE p.source = 'quickenrich'
      AND p.enriched_at >= now() - interval '30 days'
      AND COALESCE(btrim(p.email), '') <> ''
      AND q.last_signal_date >= current_date - GREATEST(p_lookback_days, 1)
    ORDER BY q.company_key, p.linkedin_url, p.enriched_at DESC
  )
  INSERT INTO public.public_signal_people AS target (
    company_key, company_linkedin_url, domain, full_name, title, linkedin_url,
    photo_url, seniority_rank, source, enriched_at, email, email_status
  )
  SELECT
    r.target_company_key, r.target_company_linkedin_url, r.target_domain,
    r.full_name, r.title, r.linkedin_url, r.photo_url, r.seniority_rank,
    'quickenrich', r.enriched_at, r.email, r.email_status
  FROM reusable r
  ON CONFLICT ON CONSTRAINT public_signal_people_company_key_linkedin_url_key DO UPDATE SET
    email = COALESCE(EXCLUDED.email, target.email),
    email_status = COALESCE(EXCLUDED.email_status, target.email_status),
    enriched_at = GREATEST(EXCLUDED.enriched_at, target.enriched_at);

  WITH reusable AS (
    SELECT DISTINCT ON (q.company_key)
      q.company_key AS target_company_key,
      q.domain AS target_domain,
      c.employee_count, c.employee_range, c.revenue_range, c.industry,
      c.country, c.state, c.city, c.enriched_at
    FROM public.public_signal_people_enrichment_state q
    JOIN public.public_signal_companies c
      ON lower(btrim(c.domain)) = lower(btrim(q.domain))
     AND c.company_key <> q.company_key
    WHERE c.source = 'quickenrich'
      AND c.enriched_at >= now() - interval '30 days'
    ORDER BY q.company_key, c.enriched_at DESC
  )
  INSERT INTO public.public_signal_companies AS target (
    company_key, domain, employee_count, employee_range, revenue_range,
    industry, country, state, city, source, enriched_at
  )
  SELECT
    r.target_company_key, r.target_domain, r.employee_count, r.employee_range,
    r.revenue_range, r.industry, r.country, r.state, r.city,
    'quickenrich', r.enriched_at
  FROM reusable r
  ON CONFLICT ON CONSTRAINT public_signal_companies_pkey DO UPDATE SET
    domain = EXCLUDED.domain,
    employee_count = COALESCE(EXCLUDED.employee_count, target.employee_count),
    employee_range = COALESCE(EXCLUDED.employee_range, target.employee_range),
    revenue_range = COALESCE(EXCLUDED.revenue_range, target.revenue_range),
    industry = COALESCE(EXCLUDED.industry, target.industry),
    country = COALESCE(EXCLUDED.country, target.country),
    state = COALESCE(EXCLUDED.state, target.state),
    city = COALESCE(EXCLUDED.city, target.city),
    source = 'quickenrich',
    enriched_at = GREATEST(EXCLUDED.enriched_at, target.enriched_at);

  UPDATE public.public_signal_people_enrichment_state q
  SET status = 'complete',
      people_found = fresh.people_found,
      provider = 'quickenrich',
      completed_at = fresh.last_enriched_at,
      next_attempt_at = fresh.last_enriched_at + interval '30 days',
      lease_expires_at = NULL,
      last_error = NULL,
      updated_at = now()
  FROM (
    SELECT p.company_key, count(*)::integer AS people_found,
           max(p.enriched_at) AS last_enriched_at
    FROM public.public_signal_people p
    WHERE p.enriched_at >= now() - interval '30 days'
      AND p.source = 'quickenrich'
      AND COALESCE(btrim(p.email), '') <> ''
    GROUP BY p.company_key
  ) fresh
  WHERE q.company_key = fresh.company_key
    AND q.status IN ('pending', 'failed', 'not_found')
    AND q.next_attempt_at <= fresh.last_enriched_at + interval '30 days';

  RETURN QUERY
  WITH due AS (
    SELECT q.company_key
    FROM public.public_signal_people_enrichment_state q
    WHERE (
        (q.status IN ('pending', 'complete', 'not_found', 'failed') AND q.next_attempt_at <= now())
        OR (q.status = 'claimed' AND q.lease_expires_at < now())
      )
      AND (q.lease_expires_at IS NULL OR q.lease_expires_at < now())
      AND q.last_signal_date >= current_date - GREATEST(p_lookback_days, 1)
      AND EXISTS (
        SELECT 1
        FROM public.public_signals s
        WHERE s.source_key = 'aca_native'
          AND s.published
          AND lower(btrim(s.company_name)) = q.company_key
          AND s.signal_date >= current_date - GREATEST(p_lookback_days, 1)
      )
    ORDER BY q.last_signal_date DESC, q.next_attempt_at, q.company_key
    LIMIT GREATEST(LEAST(p_batch_size, 25), 1)
    FOR UPDATE SKIP LOCKED
  ), claimed AS (
    UPDATE public.public_signal_people_enrichment_state q
    SET status = 'claimed',
        attempts = q.attempts + 1,
        lease_expires_at = now() + interval '10 minutes',
        updated_at = now()
    FROM due
    WHERE q.company_key = due.company_key
    RETURNING q.company_key, q.company_name, q.domain, q.company_linkedin_url
  )
  SELECT c.company_key, c.company_name, c.domain, c.company_linkedin_url FROM claimed c;
END;
$$;


ALTER FUNCTION "public"."claim_public_signal_companies_for_quickenrich_by_company"("p_batch_size" integer, "p_lookback_days" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_public_signal_companies_for_quickenrich_personas"("p_batch_size" integer DEFAULT 5, "p_lookback_days" integer DEFAULT 14) RETURNS TABLE("company_key" "text", "company_name" "text", "domain" "text", "company_linkedin_url" "text", "start_page" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  PERFORM pg_advisory_xact_lock(hashtextextended('public-signal-quickenrich-domain-claim', 0));

  INSERT INTO public.public_signal_people_enrichment_state AS q
    (company_key, company_name, domain, company_linkedin_url, last_signal_date)
  SELECT DISTINCT ON (lower(btrim(s.company_name)))
    lower(btrim(s.company_name)), btrim(s.company_name), lower(btrim(s.domain)),
    s.company_linkedin_url, s.signal_date
  FROM public.public_signals s
  WHERE s.published AND s.source_key = 'aca_native'
    AND s.signal_date >= current_date - GREATEST(p_lookback_days, 1)
    AND COALESCE(btrim(s.company_name), '') <> '' AND COALESCE(btrim(s.domain), '') <> ''
  ORDER BY lower(btrim(s.company_name)), s.signal_date DESC, s.quality_score DESC, s.created_at DESC
  ON CONFLICT ON CONSTRAINT public_signal_people_enrichment_state_pkey DO UPDATE SET
    company_name = EXCLUDED.company_name,
    domain = EXCLUDED.domain,
    company_linkedin_url = COALESCE(EXCLUDED.company_linkedin_url, q.company_linkedin_url),
    last_signal_date = GREATEST(q.last_signal_date, EXCLUDED.last_signal_date),
    updated_at = now();

  WITH reusable AS (
    SELECT DISTINCT ON (target.company_key, p.linkedin_url)
      target.company_key, target.company_linkedin_url, target.domain,
      p.full_name, p.title, p.linkedin_url, p.photo_url, p.seniority_rank,
      p.email, p.email_status, p.outreach_persona, p.enriched_at
    FROM public.public_signal_people_enrichment_state target
    JOIN public.public_signal_people_enrichment_state source
      ON lower(btrim(source.domain)) = lower(btrim(target.domain))
     AND source.company_key <> target.company_key
     AND source.persona_policy_version >= 2
     AND source.status IN ('complete', 'not_found')
     AND source.next_attempt_at > now()
    JOIN public.public_signal_people p ON p.company_key = source.company_key
    WHERE target.persona_policy_version < 2
      AND p.source = 'quickenrich' AND p.outreach_persona IS NOT NULL
    ORDER BY target.company_key, p.linkedin_url, p.enriched_at DESC
  )
  INSERT INTO public.public_signal_people AS destination (
    company_key, company_linkedin_url, domain, full_name, title, linkedin_url,
    photo_url, seniority_rank, source, enriched_at, email, email_status,
    outreach_persona, persona_policy_version
  )
  SELECT r.company_key, r.company_linkedin_url, r.domain, r.full_name, r.title, r.linkedin_url,
    r.photo_url, r.seniority_rank, 'quickenrich', r.enriched_at, r.email, r.email_status,
    r.outreach_persona, 2
  FROM reusable r
  ON CONFLICT ON CONSTRAINT public_signal_people_company_key_linkedin_url_key DO UPDATE SET
    email = COALESCE(EXCLUDED.email, destination.email),
    email_status = COALESCE(EXCLUDED.email_status, destination.email_status),
    outreach_persona = EXCLUDED.outreach_persona,
    persona_policy_version = 2,
    enriched_at = GREATEST(EXCLUDED.enriched_at, destination.enriched_at);

  UPDATE public.public_signal_people_enrichment_state target
  SET status = source.status,
      provider = source.provider,
      people_found = source.people_found,
      pages_fetched = source.pages_fetched,
      completed_at = source.completed_at,
      lease_expires_at = NULL,
      next_attempt_at = source.next_attempt_at,
      last_error = NULL,
      persona_policy_version = 2,
      updated_at = now()
  FROM public.public_signal_people_enrichment_state source
  WHERE target.persona_policy_version < 2
    AND source.persona_policy_version >= 2
    AND source.company_key <> target.company_key
    AND lower(btrim(source.domain)) = lower(btrim(target.domain))
    AND source.status IN ('complete', 'not_found')
    AND source.next_attempt_at > now();

  RETURN QUERY
  WITH due AS (
    SELECT DISTINCT ON (lower(btrim(q.domain))) q.company_key
    FROM public.public_signal_people_enrichment_state q
    WHERE q.last_signal_date >= current_date - GREATEST(p_lookback_days, 1)
      AND COALESCE(btrim(q.domain), '') <> ''
      AND (q.lease_expires_at IS NULL OR q.lease_expires_at < now())
      AND (
        q.persona_policy_version < 2
        OR (q.status IN ('pending', 'complete', 'not_found', 'failed') AND q.next_attempt_at <= now())
        OR (q.status = 'claimed' AND q.lease_expires_at < now())
      )
      AND EXISTS (
        SELECT 1 FROM public.public_signals s
        WHERE s.source_key = 'aca_native' AND s.published
          AND lower(btrim(s.company_name)) = q.company_key
          AND s.signal_date >= current_date - GREATEST(p_lookback_days, 1)
      )
    ORDER BY lower(btrim(q.domain)), q.last_signal_date DESC, q.next_attempt_at, q.company_key
    LIMIT GREATEST(LEAST(p_batch_size, 10), 1)
  ), claimed AS (
    UPDATE public.public_signal_people_enrichment_state q
    SET status = 'claimed', attempts = q.attempts + 1,
        lease_expires_at = now() + interval '10 minutes', updated_at = now()
    FROM due WHERE q.company_key = due.company_key
    RETURNING q.company_key, q.company_name, q.domain, q.company_linkedin_url,
      GREATEST(COALESCE(q.pages_fetched, 0) + 1, 1) AS start_page
  )
  SELECT c.company_key, c.company_name, c.domain, c.company_linkedin_url, c.start_page FROM claimed c;
END;
$$;


ALTER FUNCTION "public"."claim_public_signal_companies_for_quickenrich_personas"("p_batch_size" integer, "p_lookback_days" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_sequence_send_batch"("p_worker_id" "text", "p_max_orgs" integer DEFAULT 8, "p_per_org" integer DEFAULT 25, "p_lease_seconds" integer DEFAULT 300, "p_exclude_org_ids" "uuid"[] DEFAULT '{}'::"uuid"[]) RETURNS TABLE("enrollment_id" "uuid", "organization_id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_now timestamptz := now();
BEGIN
  IF p_max_orgs IS NULL OR p_max_orgs <= 0 THEN
    RETURN;
  END IF;

  RETURN QUERY
  WITH due_orgs AS (
    SELECT s.organization_id AS org_id, min(d.next_send_at) AS oldest_due
    FROM email_sequences s
    CROSS JOIN LATERAL (
      SELECT e.next_send_at
      FROM email_sequence_enrollments e
      WHERE e.sequence_id = s.id
        AND e.status = 'active'
        AND e.next_send_at <= v_now
      ORDER BY e.next_send_at
      LIMIT 1
    ) d
    WHERE s.status = 'active'
      AND s.organization_id IS NOT NULL
      AND NOT (s.organization_id = ANY (coalesce(p_exclude_org_ids, '{}')))
    GROUP BY s.organization_id
  ),
  candidates AS (
    SELECT o.org_id, o.oldest_due
    FROM due_orgs o
    LEFT JOIN sequence_sender_org_leases l ON l.organization_id = o.org_id
    WHERE l.organization_id IS NULL OR l.leased_until < v_now
    ORDER BY o.oldest_due
    LIMIT p_max_orgs
  ),
  leased AS (
    INSERT INTO sequence_sender_org_leases AS l (organization_id, holder, leased_until, updated_at)
    SELECT c.org_id, p_worker_id, v_now + make_interval(secs => p_lease_seconds), v_now
    FROM candidates c
    ON CONFLICT ON CONSTRAINT sequence_sender_org_leases_pkey DO UPDATE
      SET holder = EXCLUDED.holder,
          leased_until = EXCLUDED.leased_until,
          updated_at = EXCLUDED.updated_at
      WHERE l.leased_until < v_now
    RETURNING l.organization_id AS org_id
  )
  SELECT pick.id, le.org_id
  FROM leased le
  CROSS JOIN LATERAL (
    SELECT e.id
    FROM email_sequences s
    JOIN email_sequence_enrollments e ON e.sequence_id = s.id
    WHERE s.organization_id = le.org_id
      AND s.status = 'active'
      AND e.status = 'active'
      AND e.next_send_at <= v_now
    ORDER BY e.next_send_at
    LIMIT p_per_org
  ) pick;
END;
$$;


ALTER FUNCTION "public"."claim_sequence_send_batch"("p_worker_id" "text", "p_max_orgs" integer, "p_per_org" integer, "p_lease_seconds" integer, "p_exclude_org_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_signal_company_lookup"("p_provider" "text", "p_name" "text", "p_country" "text" DEFAULT ''::"text") RETURNS TABLE("status" "text", "token" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE r public.signal_company_lookup_cache; v_token uuid;
BEGIN
  IF p_provider <> 'quickenrich' OR nullif(trim(p_name),'') IS NULL THEN
    RAISE EXCEPTION 'invalid lookup key';
  END IF;
  INSERT INTO public.signal_company_lookup_cache(provider,name_normalized,country_code)
    VALUES(p_provider,p_name,coalesce(p_country,'')) ON CONFLICT DO NOTHING;
  SELECT * INTO r FROM public.signal_company_lookup_cache
    WHERE provider=p_provider AND name_normalized=p_name AND country_code=coalesce(p_country,'') FOR UPDATE;
  IF r.lease_until > now() THEN RETURN QUERY SELECT 'busy'::text,NULL::uuid; RETURN; END IF;
  IF r.attempts >= 2 OR r.last_attempt_at > now()-interval '30 days' THEN
    RETURN QUERY SELECT 'cached_miss'::text,NULL::uuid; RETURN;
  END IF;
  v_token := gen_random_uuid();
  -- Reserve an attempt before sending the request. An interrupted worker's
  -- unknown spend stays cached; known operational failures refund it below.
  UPDATE public.signal_company_lookup_cache SET attempts=attempts+1,
    last_attempt_at=now(),lease_until=now()+interval '2 minutes',lease_token=v_token
    WHERE provider=p_provider AND name_normalized=p_name AND country_code=coalesce(p_country,'');
  RETURN QUERY SELECT 'granted'::text,v_token;
END;
$$;


ALTER FUNCTION "public"."claim_signal_company_lookup"("p_provider" "text", "p_name" "text", "p_country" "text") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."company_identities" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "name" "text" NOT NULL,
    "name_normalized" "text" NOT NULL,
    "domain" "text",
    "website_url" "text",
    "linkedin_url" "text",
    "cik" "text",
    "aliases" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "industry" "text",
    "employee_count" integer,
    "country" "text",
    "founded_year" integer,
    "resolved_via" "text",
    "resolved_at" timestamp with time zone,
    "resolution_attempts" integer DEFAULT 0 NOT NULL,
    "last_resolution_error" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "resolution_lease_until" timestamp with time zone,
    "resolution_claimed_by" "text"
);


ALTER TABLE "public"."company_identities" OWNER TO "postgres";


COMMENT ON TABLE "public"."company_identities" IS 'Global company resolution cache. Write-once-per-company: resolve a name/CIK/ATS token to a domain once, reuse forever. Entity resolution is what killed the v1 scrapers (commit 1a812ac8); this table is the fix.';



CREATE OR REPLACE FUNCTION "public"."claim_signal_identities"("p_limit" integer DEFAULT 100, "p_max_attempts" integer DEFAULT 3, "p_worker" "text" DEFAULT 'signal-domain-finder'::"text", "p_lease_seconds" integer DEFAULT 600) RETURNS SETOF "public"."company_identities"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  UPDATE public.company_identities i
  SET resolution_lease_until = now() + make_interval(secs => LEAST(GREATEST(p_lease_seconds, 60), 3600)),
      resolution_claimed_by = left(p_worker, 120),
      updated_at = now()
  FROM (
    SELECT id
    FROM public.company_identities
    WHERE domain IS NULL
      AND resolution_attempts < LEAST(GREATEST(p_max_attempts, 1), 20)
      AND (resolution_lease_until IS NULL OR resolution_lease_until < now())
    ORDER BY resolution_attempts, created_at
    FOR UPDATE SKIP LOCKED
    LIMIT LEAST(GREATEST(p_limit, 1), 500)
  ) claimable
  WHERE i.id = claimable.id
  RETURNING i.*;
$$;


ALTER FUNCTION "public"."claim_signal_identities"("p_limit" integer, "p_max_attempts" integer, "p_worker" "text", "p_lease_seconds" integer) OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."signal_observations" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "source_id" "uuid" NOT NULL,
    "collector_key" "text" NOT NULL,
    "external_id" "text" NOT NULL,
    "source_url" "text",
    "title" "text",
    "body_text" "text",
    "structured" "jsonb",
    "entity_hints" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "published_at" timestamp with time zone,
    "observed_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "event_type" "text",
    "extracted" "jsonb",
    "company_identity_id" "uuid",
    "signal_event_id" "uuid",
    "attempts" integer DEFAULT 0 NOT NULL,
    "error" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "lease_until" timestamp with time zone,
    "claimed_by" "text",
    CONSTRAINT "signal_observations_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'extracted'::"text", 'resolved'::"text", 'merged'::"text", 'skipped'::"text", 'failed'::"text"])))
);


ALTER TABLE "public"."signal_observations" OWNER TO "postgres";


COMMENT ON TABLE "public"."signal_observations" IS 'Raw append-only collector intake. Never interpreted at write time so extraction/resolution can be re-run without re-fetching the source.';



CREATE OR REPLACE FUNCTION "public"."claim_signal_observations"("p_status" "text", "p_limit" integer DEFAULT 25, "p_max_attempts" integer DEFAULT 3, "p_worker" "text" DEFAULT 'signal-refinery'::"text", "p_lease_seconds" integer DEFAULT 300) RETURNS SETOF "public"."signal_observations"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  UPDATE public.signal_observations o
  SET lease_until = now() + make_interval(secs => LEAST(GREATEST(p_lease_seconds, 30), 1800)),
      claimed_by = left(p_worker, 120),
      updated_at = now()
  FROM (
    SELECT id
    FROM public.signal_observations
    WHERE status = p_status
      AND attempts < LEAST(GREATEST(p_max_attempts, 1), 100)
      AND (lease_until IS NULL OR lease_until < now())
    ORDER BY
      CASE WHEN collector_key = 'yc_directory' THEN 1 ELSE 0 END,
      CASE WHEN p_status = 'extracted' THEN updated_at ELSE created_at END,
      created_at,
      id
    FOR UPDATE SKIP LOCKED
    LIMIT LEAST(GREATEST(p_limit, 1), 500)
  ) claimable
  WHERE o.id = claimable.id
  RETURNING o.*;
$$;


ALTER FUNCTION "public"."claim_signal_observations"("p_status" "text", "p_limit" integer, "p_max_attempts" integer, "p_worker" "text", "p_lease_seconds" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_warmup_send"("p_from_mailbox_id" "uuid", "p_to_mailbox_id" "uuid", "p_warmup_ref" "text", "p_subject" "text", "p_parent_send_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("send_id" "uuid", "deferred_reason" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  sender public.email_mailboxes%ROWTYPE;
  recipient public.email_mailboxes%ROWTYPE;
  parent public.email_warmup_sends%ROWTYPE;
  day_start timestamptz := ((now() AT TIME ZONE 'UTC')::date)::timestamp AT TIME ZONE 'UTC';
  domain_cap integer;
  domain_used integer;
  replies_reserved integer;
  mailbox_used integer;
  mailbox_cap integer;
  genuine_sent integer;
  received_today integer;
  receive_cap integer;
  claimed_id uuid;
BEGIN
  -- Both workers take the same transaction lock before reading or inserting
  -- reservations. The critical section performs no provider/network operations.
  PERFORM pg_advisory_xact_lock(61006110000::bigint);
  SELECT * INTO sender FROM public.email_mailboxes WHERE id = p_from_mailbox_id;
  SELECT * INTO recipient FROM public.email_mailboxes WHERE id = p_to_mailbox_id;
  IF sender.id IS NULL OR recipient.id IS NULL OR sender.id = recipient.id
     OR sender.status NOT IN ('ready', 'warming', 'paused')
     OR recipient.status NOT IN ('ready', 'warming', 'paused')
     OR COALESCE(sender.metadata->>'paused_reason', '') IN ('tenant_outbound_blocked', 'tenant_mail_send_missing')
     OR sender.metadata->'capability_probe'->>'mail_send' = 'false'
     OR (p_parent_send_id IS NULL AND NOT COALESCE(sender.warmup_enabled, false)) THEN
    RETURN QUERY SELECT NULL::uuid, 'ineligible'::text; RETURN;
  END IF;

  IF p_parent_send_id IS NOT NULL THEN
    SELECT * INTO parent FROM public.email_warmup_sends WHERE id = p_parent_send_id;
    IF parent.id IS NULL OR parent.status <> 'delivered' OR parent.is_reply
       OR parent.from_mailbox_id <> recipient.id OR parent.to_mailbox_id <> sender.id
       OR parent.sent_at IS NULL OR parent.sent_at < now() - interval '36 hours' THEN
      RETURN QUERY SELECT NULL::uuid, 'ineligible'::text; RETURN;
    END IF;
    IF parent.replied_at IS NOT NULL OR EXISTS (
      SELECT 1 FROM public.email_warmup_sends w
      WHERE w.parent_send_id = parent.id AND w.is_reply AND w.status <> 'failed'
    ) THEN
      RETURN QUERY SELECT NULL::uuid, 'duplicate_reply'::text; RETURN;
    END IF;
    SELECT count(*)::integer INTO mailbox_used FROM public.email_warmup_sends w
    WHERE w.from_mailbox_id = sender.id AND w.is_reply AND w.status <> 'failed'
      AND COALESCE(w.sent_at, w.created_at) >= day_start;
    mailbox_cap := GREATEST(0, LEAST(2, COALESCE(sender.warmup_daily_reply_target, 8)));
  ELSE
    SELECT count(*)::integer INTO mailbox_used FROM public.email_warmup_sends w
    WHERE w.from_mailbox_id = sender.id AND w.status <> 'failed'
      AND COALESCE(w.sent_at, w.created_at) >= day_start;
    genuine_sent := CASE WHEN sender.daily_sent_reset_at = (now() AT TIME ZONE 'UTC')::date
                        THEN COALESCE(sender.daily_sent, 0) ELSE 0 END;
    mailbox_cap := GREATEST(0, LEAST(3, COALESCE(sender.warmup_max_daily, 40),
      GREATEST(1, floor(COALESCE(sender.daily_limit, 30) * 0.2)::integer),
      GREATEST(0, COALESCE(sender.daily_limit, 30) - genuine_sent)));
    IF EXISTS (SELECT 1 FROM public.warmup_endpoint_health h
               WHERE h.mailbox_id = sender.id AND h.dead_as_sender) THEN
      mailbox_cap := LEAST(mailbox_cap, 1);
    END IF;
  END IF;
  IF mailbox_used >= mailbox_cap THEN
    RETURN QUERY SELECT NULL::uuid, 'mailbox_capacity'::text; RETURN;
  END IF;

  SELECT LEAST(50, 10 + 2 * GREATEST(0, COALESCE(max(m.warmup_day), sender.warmup_day, 0)))
  INTO domain_cap FROM public.email_mailboxes m
  WHERE (CASE WHEN sender.sending_domain_id IS NULL THEN m.id = sender.id
              ELSE m.sending_domain_id = sender.sending_domain_id END)
    AND m.warmup_enabled AND m.status IN ('ready', 'warming', 'paused')
    AND COALESCE(m.metadata->>'paused_reason', '') NOT IN ('tenant_outbound_blocked', 'tenant_mail_send_missing')
    AND COALESCE(m.metadata->'capability_probe'->>'mail_send', 'true') <> 'false';
  SELECT count(*)::integer INTO domain_used
  FROM public.email_warmup_sends w JOIN public.email_mailboxes m ON m.id = w.from_mailbox_id
  WHERE w.status <> 'failed' AND COALESCE(w.sent_at, w.created_at) >= day_start
    AND (CASE WHEN sender.sending_domain_id IS NULL THEN m.id = sender.id
              ELSE m.sending_domain_id = sender.sending_domain_id END);
  IF domain_used >= domain_cap THEN
    RETURN QUERY SELECT NULL::uuid, 'domain_capacity'::text; RETURN;
  END IF;

  IF p_parent_send_id IS NULL THEN
    -- Reserve only existing, recent conversations that the receive worker can
    -- actually answer, under its configured rate and two-reply daily ceiling.
    -- ceil protects the fractional reply opportunity; no fixed traffic split.
    WITH repliers AS (
      SELECT m.id, m.warmup_reply_rate_target, m.warmup_daily_reply_target
      FROM public.email_mailboxes m
      WHERE (CASE WHEN sender.sending_domain_id IS NULL THEN m.id = sender.id
                  ELSE m.sending_domain_id = sender.sending_domain_id END)
        AND m.status IN ('ready', 'warming', 'paused')
        AND COALESCE(m.metadata->>'paused_reason', '') NOT IN ('tenant_outbound_blocked', 'tenant_mail_send_missing')
        AND COALESCE(m.metadata->'capability_probe'->>'mail_send', 'true') <> 'false'
    ), demand AS (
      SELECT r.id,
        (SELECT count(*) FROM public.email_warmup_sends w
         JOIN public.email_mailboxes target ON target.id = w.from_mailbox_id
         WHERE w.to_mailbox_id = r.id AND w.status = 'delivered' AND NOT w.is_reply
           AND w.replied_at IS NULL AND w.sent_at >= now() - interval '36 hours'
           AND target.status IN ('ready', 'warming', 'paused')
           AND NOT EXISTS (SELECT 1 FROM public.email_warmup_sends reply
                           WHERE reply.parent_send_id = w.id AND reply.is_reply AND reply.status <> 'failed')) AS candidates,
        (SELECT count(*) FROM public.email_warmup_sends w
         WHERE w.to_mailbox_id = r.id AND w.status = 'delivered' AND w.sent_at >= day_start) AS delivered,
        (SELECT count(*) FROM public.email_warmup_sends w
         WHERE w.from_mailbox_id = r.id AND w.is_reply AND w.status <> 'failed'
           AND COALESCE(w.sent_at, w.created_at) >= day_start) AS replied,
        r.warmup_reply_rate_target, r.warmup_daily_reply_target
      FROM repliers r
    )
    SELECT COALESCE(sum(LEAST(candidates, GREATEST(0,
      LEAST(2, COALESCE(warmup_daily_reply_target, 8),
        ceil(delivered * COALESCE(warmup_reply_rate_target, 20) / 100.0)) - replied))), 0)::integer
    INTO replies_reserved FROM demand;
    IF domain_used + replies_reserved >= domain_cap THEN
      RETURN QUERY SELECT NULL::uuid, 'reply_priority'::text; RETURN;
    END IF;

    -- Match the partner RPC's receive caps even if two worker runs overlap.
    SELECT count(*)::integer INTO received_today FROM public.email_warmup_sends w
    WHERE w.to_mailbox_id = recipient.id AND w.status <> 'failed'
      AND COALESCE(w.sent_at, w.created_at) >= day_start;
    receive_cap := CASE WHEN 'warmup-seed' = ANY(COALESCE(recipient.tags, '{}'::text[]))
      THEN LEAST(20, ceil(20 * (EXTRACT(EPOCH FROM now() - day_start) / 86400.0 + 1.0 / 24)))::integer
      ELSE 3 END;
    IF EXISTS (SELECT 1 FROM public.warmup_endpoint_health h
               WHERE h.mailbox_id = recipient.id AND h.dead_as_recipient) THEN
      receive_cap := LEAST(receive_cap, 1);
    END IF;
    IF received_today >= receive_cap THEN
      RETURN QUERY SELECT NULL::uuid, 'partner_capacity'::text; RETURN;
    END IF;
    IF EXISTS (SELECT 1 FROM public.email_warmup_sends w
               WHERE w.from_mailbox_id = sender.id AND w.to_mailbox_id = recipient.id
                 AND w.status <> 'failed'
                 AND COALESCE(w.sent_at, w.created_at) > now() - interval '7 days') THEN
      RETURN QUERY SELECT NULL::uuid, 'partner_capacity'::text; RETURN;
    END IF;
  END IF;

  INSERT INTO public.email_warmup_sends(from_mailbox_id, to_mailbox_id,
    from_organization_id, to_organization_id, warmup_ref, subject, status, is_reply, parent_send_id)
  VALUES (sender.id, recipient.id, sender.organization_id, recipient.organization_id,
    p_warmup_ref, p_subject, 'pending', p_parent_send_id IS NOT NULL, p_parent_send_id)
  RETURNING id INTO claimed_id;
  IF p_parent_send_id IS NULL THEN
    -- Commit attempt evidence with the reservation, before calling the provider.
    -- A worker crash must not make a real opportunity disappear from alerts.
    INSERT INTO public.warmup_scheduler_daily(day, mailbox_id, organization_id, last_reason, had_opportunity)
    VALUES ((now() AT TIME ZONE 'UTC')::date, sender.id, sender.organization_id, 'attempted', true)
    ON CONFLICT (day, mailbox_id) DO UPDATE SET
      last_seen_at = now(), last_reason = 'attempted', had_opportunity = true;
  END IF;
  RETURN QUERY SELECT claimed_id, NULL::text;
END;
$$;


ALTER FUNCTION "public"."claim_warmup_send"("p_from_mailbox_id" "uuid", "p_to_mailbox_id" "uuid", "p_warmup_ref" "text", "p_subject" "text", "p_parent_send_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."clamp_mailbox_daily_limit"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
declare
  v_cap integer;
  v_type_ceiling integer;
  v_org_cap_applies boolean;
begin
  select max_mailbox_daily_limit
    into v_cap
  from organization_channel_limits
  where organization_id = NEW.organization_id
    and channel = 'email'
    and max_mailbox_daily_limit is not null
  limit 1;

  select max_daily_limit, org_cap_applies
    into v_type_ceiling, v_org_cap_applies
  from mailbox_daily_ceilings
  where connection_type = NEW.connection_type;

  -- Types flagged org_cap_applies = false (PostShiba) ignore the org cap row.
  if v_org_cap_applies = false then
    v_cap := null;
  end if;

  if v_type_ceiling is not null then
    v_cap := least(coalesce(v_cap, v_type_ceiling), v_type_ceiling);
  end if;

  if v_cap is not null then
    if NEW.daily_limit is not null and NEW.daily_limit > v_cap then
      NEW.daily_limit := v_cap;
    end if;
    if NEW.warmup_max_daily is not null and NEW.warmup_max_daily > v_cap then
      NEW.warmup_max_daily := v_cap;
    end if;
    if NEW.daily_limit_baseline is not null and NEW.daily_limit_baseline > v_cap then
      NEW.daily_limit_baseline := v_cap;
    end if;
  end if;

  return NEW;
end;
$$;


ALTER FUNCTION "public"."clamp_mailbox_daily_limit"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."classify_quickenrich_signal_person"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NEW.source <> 'quickenrich' THEN RETURN NEW; END IF;
  NEW.outreach_persona := public.signal_buyer_persona(NEW.title);
  NEW.seniority_rank := public.signal_buyer_persona_priority(NEW.title);
  NEW.persona_policy_version := 2;
  IF NEW.outreach_persona IS NULL THEN
    INSERT INTO public.signal_people_persona_rejections (
      company_key, full_name, title, linkedin_url, reason
    ) VALUES (
      NEW.company_key, NEW.full_name, NEW.title, NEW.linkedin_url,
      'not_an_outreach_buyer'
    ) ON CONFLICT ON CONSTRAINT signal_persona_rejection_dedupe
      DO NOTHING;
    RETURN NULL;
  END IF;
  RETURN NEW;
END;
$$;


