CREATE OR REPLACE FUNCTION "public"."complete_generation_job"("p_job_id" "uuid", "p_status" "text", "p_results" "jsonb" DEFAULT NULL::"jsonb", "p_errors" "jsonb" DEFAULT NULL::"jsonb", "p_total_tokens" integer DEFAULT 0, "p_total_cost" numeric DEFAULT 0, "p_duration_ms" integer DEFAULT 0) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF p_status NOT IN ('completed', 'partial', 'failed') THEN
    RAISE EXCEPTION 'Invalid status: %. Must be completed, partial, or failed', p_status;
  END IF;

  UPDATE generation_jobs
  SET
    status = p_status,
    results = p_results,
    errors = p_errors,
    total_tokens_used = p_total_tokens,
    total_cost_usd = p_total_cost,
    generation_duration_ms = p_duration_ms,
    completed_at = NOW(),
    updated_at = NOW()
  WHERE id = p_job_id
    AND status IN ('queued', 'processing');

  IF NOT FOUND THEN
    RETURN FALSE;
  END IF;

  RETURN TRUE;
END;
$$;


ALTER FUNCTION "public"."complete_generation_job"("p_job_id" "uuid", "p_status" "text", "p_results" "jsonb", "p_errors" "jsonb", "p_total_tokens" integer, "p_total_cost" numeric, "p_duration_ms" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."complete_job"("p_job_id" "uuid", "p_result" "jsonb" DEFAULT NULL::"jsonb") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
BEGIN
    UPDATE job_queue
    SET status = 'completed',
        completed_at = NOW(),
        metadata = COALESCE(metadata, '{}'::jsonb) || COALESCE(p_result, '{}'::jsonb)
    WHERE id = p_job_id;
END;
$$;


ALTER FUNCTION "public"."complete_job"("p_job_id" "uuid", "p_result" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."complete_lb_work_item"("p_item_id" bigint, "p_ok" boolean, "p_err" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_attempts INT; v_max INT;
BEGIN
  IF p_ok THEN
    UPDATE public.lb_work_items SET status='completed', completed_at=NOW(), updated_at=NOW(), error=NULL WHERE id = p_item_id;
    RETURN;
  END IF;
  SELECT attempts, max_attempts INTO v_attempts, v_max FROM public.lb_work_items WHERE id = p_item_id;
  IF v_attempts IS NULL THEN RETURN; END IF;
  IF v_attempts >= v_max THEN
    UPDATE public.lb_work_items SET status='dead', completed_at=NOW(), updated_at=NOW(), error=p_err WHERE id = p_item_id;
  ELSE
    UPDATE public.lb_work_items SET status='pending', claimed_by=NULL, claimed_at=NULL, updated_at=NOW(), error=p_err WHERE id = p_item_id;
  END IF;
END; $$;


ALTER FUNCTION "public"."complete_lb_work_item"("p_item_id" bigint, "p_ok" boolean, "p_err" "text") OWNER TO "postgres";


