    CONSTRAINT "crm_conversations_channel_check" CHECK (("channel" = ANY (ARRAY['linkedin'::"text", 'instagram'::"text", 'email'::"text", 'sms'::"text", 'whatsapp'::"text"]))),
    CONSTRAINT "crm_conversations_last_message_direction_check" CHECK (("last_message_direction" = ANY (ARRAY['inbound'::"text", 'outbound'::"text"]))),
    CONSTRAINT "crm_conversations_momentum_trend_check" CHECK (("momentum_trend" = ANY (ARRAY['rising'::"text", 'stable'::"text", 'falling'::"text", 'cold'::"text"]))),
    CONSTRAINT "crm_conversations_sla_status_check" CHECK (("sla_status" = ANY (ARRAY['ok'::"text", 'warning'::"text", 'breached'::"text"]))),
    CONSTRAINT "crm_conversations_snooze_type_check" CHECK (("snooze_type" = ANY (ARRAY['timed'::"text", 'until_reply'::"text", 'until_ooo_ends'::"text", 'until_meeting'::"text", 'until_timezone_morning'::"text"]))),
