CREATE OR REPLACE FUNCTION "public"."compute_conversation_priority"("conv" "public"."crm_conversations") RETURNS smallint
    LANGUAGE "plpgsql" STABLE
    AS $$
DECLARE
  score SMALLINT := 0;
  hours_since FLOAT;
  contact_score INT;
BEGIN
  -- System conversations always get priority 0
  IF conv.is_system = true THEN
    RETURN 0::SMALLINT;
  END IF;

  -- Unread messages: 0-20 points
  score := score + LEAST(conv.unread_count * 5, 20);

  -- Recency: 0-25 points (decays over 48h)
  IF conv.last_message_at IS NOT NULL THEN
    hours_since := EXTRACT(EPOCH FROM (now() - conv.last_message_at)) / 3600;
    IF hours_since < 1 THEN score := score + 25;
    ELSIF hours_since < 4 THEN score := score + 20;
    ELSIF hours_since < 12 THEN score := score + 15;
    ELSIF hours_since < 24 THEN score := score + 10;
    ELSIF hours_since < 48 THEN score := score + 5;
    END IF;
  END IF;

  -- Lead intent signals: -10 to +30 points
  IF conv.lead_intent = 'interested' THEN score := score + 30;
  ELSIF conv.lead_intent = 'meeting_booked' THEN score := score + 25;
  ELSIF conv.lead_intent = 'neutral' THEN score := score + 10;
  ELSIF conv.lead_intent = 'out_of_office' THEN score := score + 5;
  ELSIF conv.lead_intent IN ('not_interested', 'do_not_contact', 'unsubscribe') THEN score := score - 10;
  END IF;

  -- Inbound reply bonus: +15
  IF conv.last_message_direction = 'inbound' THEN
    score := score + 15;
  END IF;

  -- Contact lead score: 0-10 points
  SELECT lead_score INTO contact_score FROM public.crm_contacts WHERE id = conv.contact_id;
  IF contact_score IS NOT NULL AND contact_score > 0 THEN
    score := score + LEAST(contact_score / 10, 10);
  END IF;

  RETURN GREATEST(score, 0)::SMALLINT;
END;
$$;


ALTER FUNCTION "public"."compute_conversation_priority"("conv" "public"."crm_conversations") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."compute_lead_list_channel_stats"("p_list_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "plan_cache_mode" TO 'force_custom_plan'
    AS $$
DECLARE
  v_is_smart BOOLEAN;
  v_org_id UUID;
  v_filter_criteria JSONB;
  v_total INTEGER;
  v_linkedin INTEGER;
  v_email INTEGER;
  v_phone INTEGER;
  v_whatsapp INTEGER;
  v_instagram INTEGER;
  v_twitter INTEGER;
BEGIN
  SELECT is_smart, organization_id, filter_criteria
  INTO v_is_smart, v_org_id, v_filter_criteria
  FROM public.lead_lists
  WHERE id = p_list_id;

  IF NOT FOUND THEN
    RETURN;
  END IF;

  IF v_is_smart THEN
    WITH matched AS (
      SELECT
        c.id,
        (c.primary_linkedin_url IS NOT NULL AND c.primary_linkedin_url != '') AS has_linkedin_url,
        (c.primary_email IS NOT NULL AND c.primary_email != '') AS has_primary_email,
        (c.primary_phone IS NOT NULL AND c.primary_phone != '') AS has_primary_phone,
        (v_filter_criteria->>'owner_user_id' IS NULL
          OR c.owner_user_id = (v_filter_criteria->>'owner_user_id')::UUID) AS owner_ok,
        (v_filter_criteria->>'has_email' IS NULL OR
          (v_filter_criteria->>'has_email' = 'true' AND c.primary_email IS NOT NULL AND c.primary_email != '') OR
          (v_filter_criteria->>'has_email' = 'false' AND (c.primary_email IS NULL OR c.primary_email = ''))) AS email_filter_ok,
        (v_filter_criteria->>'has_linkedin' IS NULL OR
          (v_filter_criteria->>'has_linkedin' = 'true' AND c.primary_linkedin_url IS NOT NULL AND c.primary_linkedin_url != '') OR
          (v_filter_criteria->>'has_linkedin' = 'false' AND (c.primary_linkedin_url IS NULL OR c.primary_linkedin_url = ''))) AS linkedin_filter_ok
      FROM public.crm_contacts c
      WHERE c.organization_id = v_org_id
        AND (v_filter_criteria->>'source' IS NULL OR c.source = v_filter_criteria->>'source')
        AND (v_filter_criteria->>'status' IS NULL OR c.status = v_filter_criteria->>'status')
        AND (v_filter_criteria->'tags' IS NULL OR c.tags && ARRAY(SELECT jsonb_array_elements_text(v_filter_criteria->'tags')))
        AND (v_filter_criteria->>'min_score' IS NULL OR c.lead_score >= (v_filter_criteria->>'min_score')::INTEGER)
        AND (v_filter_criteria->>'max_score' IS NULL OR c.lead_score <= (v_filter_criteria->>'max_score')::INTEGER)
        AND (v_filter_criteria->>'pipeline_id' IS NULL OR c.pipeline_id = (v_filter_criteria->>'pipeline_id')::UUID)
        AND (v_filter_criteria->>'stage_id' IS NULL OR c.stage_id = (v_filter_criteria->>'stage_id')::UUID)
    ),
    identity_flags AS (
      SELECT
        ci.contact_id,
        bool_or(ci.channel = 'linkedin') AS linkedin_identity,
        bool_or(ci.channel = 'email') AS email_identity,
        bool_or(ci.channel IN ('sms', 'whatsapp')) AS phone_identity,
        bool_or(ci.channel = 'whatsapp') AS whatsapp_identity,
        bool_or(ci.channel = 'instagram') AS instagram_identity,
        bool_or(ci.channel = 'twitter') AS twitter_identity
      FROM public.crm_contact_identities ci
      JOIN matched m ON m.id = ci.contact_id
      GROUP BY ci.contact_id
    )
    SELECT
      COUNT(*) FILTER (WHERE m.owner_ok AND m.email_filter_ok AND m.linkedin_filter_ok),
      COUNT(*) FILTER (WHERE m.email_filter_ok AND m.linkedin_filter_ok
        AND (m.has_linkedin_url OR COALESCE(f.linkedin_identity, false))),
      COUNT(*) FILTER (WHERE m.email_filter_ok AND m.linkedin_filter_ok
        AND (m.has_primary_email OR COALESCE(f.email_identity, false))),
      COUNT(*) FILTER (WHERE m.has_primary_phone OR COALESCE(f.phone_identity, false)),
      COUNT(*) FILTER (WHERE COALESCE(f.whatsapp_identity, false)),
      COUNT(*) FILTER (WHERE COALESCE(f.instagram_identity, false)),
      COUNT(*) FILTER (WHERE COALESCE(f.twitter_identity, false))
    INTO v_total, v_linkedin, v_email, v_phone, v_whatsapp, v_instagram, v_twitter
    FROM matched m
    LEFT JOIN identity_flags f ON f.contact_id = m.id;

  ELSE
    WITH members AS (
      -- lead_list_members has a unique (list_id, contact_id) constraint, so
      -- each row is already one distinct contact. Avoid a redundant hash
      -- aggregate before the contacts and identity joins.
      SELECT llm.contact_id
      FROM public.lead_list_members llm
      WHERE llm.list_id = p_list_id
    ),
    identity_flags AS (
      SELECT
        ci.contact_id,
        bool_or(ci.channel = 'linkedin') AS linkedin_identity,
        bool_or(ci.channel = 'email') AS email_identity,
        bool_or(ci.channel IN ('sms', 'whatsapp')) AS phone_identity,
        bool_or(ci.channel = 'whatsapp') AS whatsapp_identity,
        bool_or(ci.channel = 'instagram') AS instagram_identity,
        bool_or(ci.channel = 'twitter') AS twitter_identity
      FROM public.crm_contact_identities ci
      JOIN members mem ON mem.contact_id = ci.contact_id
      GROUP BY ci.contact_id
    )
    SELECT
      COUNT(*),
      COUNT(*) FILTER (WHERE COALESCE(f.linkedin_identity, false)
        OR (c.primary_linkedin_url IS NOT NULL AND c.primary_linkedin_url != '')),
      COUNT(*) FILTER (WHERE (c.primary_email IS NOT NULL AND c.primary_email != '')
        OR COALESCE(f.email_identity, false)),
      COUNT(*) FILTER (WHERE (c.primary_phone IS NOT NULL AND c.primary_phone != '')
        OR COALESCE(f.phone_identity, false)),
      COUNT(*) FILTER (WHERE COALESCE(f.whatsapp_identity, false)),
      COUNT(*) FILTER (WHERE COALESCE(f.instagram_identity, false)),
      COUNT(*) FILTER (WHERE COALESCE(f.twitter_identity, false))
    INTO v_total, v_linkedin, v_email, v_phone, v_whatsapp, v_instagram, v_twitter
    FROM members m
    LEFT JOIN public.crm_contacts c ON c.id = m.contact_id
    LEFT JOIN identity_flags f ON f.contact_id = m.contact_id;
  END IF;

  IF v_total = 0 THEN
    DELETE FROM public.lead_list_channel_stats WHERE list_id = p_list_id;
    RETURN;
  END IF;

  INSERT INTO public.lead_list_channel_stats (
    list_id,
    total_leads,
    has_linkedin, has_email, has_phone, has_whatsapp, has_instagram, has_twitter,
    linkedin_pct, email_pct, phone_pct, whatsapp_pct, instagram_pct, twitter_pct,
    computed_at
  ) VALUES (
    p_list_id,
    v_total,
    v_linkedin, v_email, v_phone, v_whatsapp, v_instagram, v_twitter,
    ROUND((v_linkedin::NUMERIC / v_total) * 100, 2),
    ROUND((v_email::NUMERIC / v_total) * 100, 2),
    ROUND((v_phone::NUMERIC / v_total) * 100, 2),
    ROUND((v_whatsapp::NUMERIC / v_total) * 100, 2),
    ROUND((v_instagram::NUMERIC / v_total) * 100, 2),
    ROUND((v_twitter::NUMERIC / v_total) * 100, 2),
    NOW()
  )
  ON CONFLICT (list_id) DO UPDATE SET
    total_leads = EXCLUDED.total_leads,
    has_linkedin = EXCLUDED.has_linkedin,
    has_email = EXCLUDED.has_email,
    has_phone = EXCLUDED.has_phone,
    has_whatsapp = EXCLUDED.has_whatsapp,
    has_instagram = EXCLUDED.has_instagram,
    has_twitter = EXCLUDED.has_twitter,
    linkedin_pct = EXCLUDED.linkedin_pct,
    email_pct = EXCLUDED.email_pct,
    phone_pct = EXCLUDED.phone_pct,
    whatsapp_pct = EXCLUDED.whatsapp_pct,
    instagram_pct = EXCLUDED.instagram_pct,
    twitter_pct = EXCLUDED.twitter_pct,
    computed_at = EXCLUDED.computed_at;
END;
$$;


ALTER FUNCTION "public"."compute_lead_list_channel_stats"("p_list_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."compute_response_time"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  last_inbound TIMESTAMPTZ;
  response_ms BIGINT;
BEGIN
  -- Only track outbound messages from users or AI
  IF NEW.direction != 'outbound' OR NEW.sender_type NOT IN ('user', 'ai') THEN
    RETURN NEW;
  END IF;

  -- Find the last unanswered inbound message that warrants a response.
  -- Skip OOO, auto-replies, do-not-contact, and unsubscribe messages.
  SELECT MAX(created_at) INTO last_inbound
  FROM public.crm_messages
  WHERE conversation_id = NEW.conversation_id
    AND direction = 'inbound'
    AND created_at < NEW.created_at
    AND COALESCE(
      metadata->'classification'->>'intent', 'unknown'
    ) NOT IN ('out_of_office', 'auto_reply', 'do_not_contact', 'unsubscribe');

  IF last_inbound IS NULL THEN
    RETURN NEW;
  END IF;

  -- Check no outbound between that inbound and this one (already answered)
  IF EXISTS (
    SELECT 1 FROM public.crm_messages
    WHERE conversation_id = NEW.conversation_id
      AND direction = 'outbound'
      AND created_at > last_inbound
      AND created_at < NEW.created_at
      AND id != NEW.id
  ) THEN
    RETURN NEW;
  END IF;

  response_ms := EXTRACT(EPOCH FROM (NEW.created_at - last_inbound)) * 1000;

  -- Update conversation response time (rolling average) + SLA status
  -- Thresholds: warning > 4h (14400000ms), breached > 24h (86400000ms)
  UPDATE public.crm_conversations
  SET avg_response_time_ms = CASE
    WHEN avg_response_time_ms IS NULL THEN response_ms
    ELSE (avg_response_time_ms + response_ms) / 2
  END,
  sla_status = CASE
    WHEN CASE WHEN avg_response_time_ms IS NULL THEN response_ms ELSE (avg_response_time_ms + response_ms) / 2 END > 86400000 THEN 'breached'
    WHEN CASE WHEN avg_response_time_ms IS NULL THEN response_ms ELSE (avg_response_time_ms + response_ms) / 2 END > 14400000 THEN 'warning'
    ELSE 'ok'
  END
  WHERE id = NEW.conversation_id;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."compute_response_time"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."compute_smart_list_count"("p_list_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_org uuid; v_criteria jsonb; v_count integer;
BEGIN
  SELECT organization_id,filter_criteria INTO v_org,v_criteria FROM public.lead_lists WHERE id=p_list_id AND is_smart;
  IF v_org IS NULL THEN RAISE EXCEPTION 'Smart segment not found' USING ERRCODE='P0002'; END IF;
  PERFORM public.assert_smart_segment_org_access(v_org);
  v_count:=public.smart_list_preview_count(v_org,coalesce(v_criteria,'{}'::jsonb));
  UPDATE public.lead_lists SET lead_count=v_count,last_computed_at=now() WHERE id=p_list_id AND organization_id=v_org;
  RETURN v_count;
END;
$$;


ALTER FUNCTION "public"."compute_smart_list_count"("p_list_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."compute_smart_list_count"("p_list_id" "uuid") IS 'Computes the count of contacts matching a smart list''s filter criteria and updates the list''s lead_count and last_computed_at fields.';



CREATE OR REPLACE FUNCTION "public"."contact_excluded_by_campaign_history"("p_organization_id" "uuid", "p_campaign_id" "uuid", "p_contact_id" "uuid", "p_exclude_other_campaigns" boolean, "p_exclude_same_sender" boolean, "p_sender_account_ids" "uuid"[]) RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.campaign_lead_progress clp
    JOIN public.linkedin_campaigns lc ON lc.id = clp.campaign_id
    WHERE clp.contact_id = p_contact_id
      AND lc.organization_id = p_organization_id
      AND (p_campaign_id IS NULL OR lc.id <> p_campaign_id)
      AND (
        (
          COALESCE(p_exclude_other_campaigns, FALSE)
          AND lc.status IN ('active', 'paused')
        )
        OR (
          COALESCE(p_exclude_same_sender, FALSE)
          AND p_sender_account_ids IS NOT NULL
          AND cardinality(p_sender_account_ids) > 0
          AND clp.sender_account_id = ANY(p_sender_account_ids)
          AND (clp.connection_sent_at IS NOT NULL OR clp.last_message_at IS NOT NULL)
        )
      )
  );
$$;


ALTER FUNCTION "public"."contact_excluded_by_campaign_history"("p_organization_id" "uuid", "p_campaign_id" "uuid", "p_contact_id" "uuid", "p_exclude_other_campaigns" boolean, "p_exclude_same_sender" boolean, "p_sender_account_ids" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."contact_excluded_by_campaign_history"("p_organization_id" "uuid", "p_campaign_id" "uuid", "p_contact_id" "uuid", "p_exclude_other_campaigns" boolean, "p_exclude_same_sender" boolean, "p_sender_account_ids" "uuid"[]) IS 'Single source of truth for campaign lead de-duplication. Used by initialize_campaign_leads, reinitialize_campaign_leads, enroll_smart_list_into_active_campaigns and the preview_eligible_leads_count* functions so enrollment and the wizard preview can never disagree.';



