CREATE OR REPLACE FUNCTION "public"."create_default_pipeline_for_org"("p_org_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_pipeline_id uuid;
BEGIN
  IF coalesce(auth.role(), '') <> 'service_role'
     AND NOT EXISTS (SELECT 1 FROM get_accessible_organization_ids() o WHERE o = p_org_id) THEN
    RAISE EXCEPTION 'Not allowed to create a pipeline for this organization';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtext('crm_default_pipeline:' || p_org_id::text));

  SELECT id INTO v_pipeline_id FROM crm_pipelines
   WHERE organization_id = p_org_id
   ORDER BY is_default DESC NULLS LAST, created_at
   LIMIT 1;
  IF v_pipeline_id IS NOT NULL THEN
    RETURN v_pipeline_id;
  END IF;

  INSERT INTO crm_pipelines (organization_id, name, description, is_default, color)
  VALUES (p_org_id, 'Sales Pipeline', 'Default sales pipeline', true, '#6366f1')
  RETURNING id INTO v_pipeline_id;

  INSERT INTO crm_pipeline_stages (pipeline_id, organization_id, name, stage_order, stage_type, color, win_probability) VALUES
    (v_pipeline_id, p_org_id, 'Lead',          1, 'new',    '#3b82f6', 10),
    (v_pipeline_id, p_org_id, 'Qualified',     2, 'active', '#8b5cf6', 25),
    (v_pipeline_id, p_org_id, 'Meeting booked',3, 'active', '#f59e0b', 40),
    (v_pipeline_id, p_org_id, 'Proposal sent', 4, 'active', '#ec4899', 60),
    (v_pipeline_id, p_org_id, 'Negotiation',   5, 'active', '#14b8a6', 80),
    (v_pipeline_id, p_org_id, 'Won',           6, 'won',    '#22c55e', 100),
    (v_pipeline_id, p_org_id, 'Lost',          7, 'lost',   '#ef4444', 0);

  RETURN v_pipeline_id;
END;
$$;


ALTER FUNCTION "public"."create_default_pipeline_for_org"("p_org_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_email_enrollment_job"("p_org" "uuid", "p_sequence_id" "uuid", "p_list_ids" "uuid"[], "p_filters" "jsonb" DEFAULT NULL::"jsonb", "p_delay_hours" numeric DEFAULT NULL::numeric, "p_created_by" "uuid" DEFAULT NULL::"uuid", "p_contact_ids" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_job public.email_enrollment_jobs;
  v_existing BOOLEAN := false;
  v_added INTEGER := 0;
BEGIN
  SELECT * INTO v_job FROM public.email_enrollment_jobs
  WHERE sequence_id = p_sequence_id AND status IN ('pending','snapshotting','running');

  IF FOUND THEN
    v_existing := true;
  ELSE
    BEGIN
      INSERT INTO public.email_enrollment_jobs
        (organization_id, sequence_id, created_by, list_ids, filters, delay_hours)
      VALUES
        (p_org, p_sequence_id, p_created_by, COALESCE(p_list_ids, '{}'::UUID[]),
         NULLIF(p_filters, '{}'::JSONB), NULLIF(p_delay_hours, 0))
      RETURNING * INTO v_job;
    EXCEPTION WHEN unique_violation THEN
      SELECT * INTO v_job FROM public.email_enrollment_jobs
      WHERE sequence_id = p_sequence_id AND status IN ('pending','snapshotting','running');
      v_existing := true;
    END;

    IF NOT v_existing AND COALESCE(cardinality(p_contact_ids), 0) > 0 THEN
      INSERT INTO public.email_enrollment_job_members (job_id, contact_id)
      SELECT v_job.id, c FROM unnest(p_contact_ids) AS c
      ON CONFLICT DO NOTHING;
      GET DIAGNOSTICS v_added = ROW_COUNT;
      UPDATE public.email_enrollment_jobs SET total = v_added WHERE id = v_job.id;
    END IF;
  END IF;

  PERFORM public.kick_email_enrollment_job(v_job.id);

  RETURN jsonb_build_object('jobId', v_job.id, 'status', v_job.status, 'existing', v_existing);
END;
$$;


ALTER FUNCTION "public"."create_email_enrollment_job"("p_org" "uuid", "p_sequence_id" "uuid", "p_list_ids" "uuid"[], "p_filters" "jsonb", "p_delay_hours" numeric, "p_created_by" "uuid", "p_contact_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_script_version_snapshot"("script_uuid" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
DECLARE
  current_version INTEGER;
  snapshot_data JSONB;
  version_id UUID;
BEGIN
  -- Get current version number
  SELECT COALESCE(MAX(version_number), 0) + 1
  INTO current_version
  FROM script_versions
  WHERE script_id = script_uuid;

  -- Build snapshot
  SELECT jsonb_build_object(
    'script', row_to_json(s.*),
    'scenes', (
      SELECT jsonb_agg(row_to_json(sc.*) ORDER BY scene_number)
      FROM script_scenes sc
      WHERE sc.script_id = script_uuid
    )
  )
  INTO snapshot_data
  FROM youtube_scripts s
  WHERE s.id = script_uuid;

  -- Insert version
  INSERT INTO script_versions (script_id, version_number, snapshot, change_type)
  VALUES (script_uuid, current_version, snapshot_data, 'edit')
  RETURNING id INTO version_id;

  RETURN version_id;
END;
$$;


ALTER FUNCTION "public"."create_script_version_snapshot"("script_uuid" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."crm_companies_lock_on_stage_change"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  IF NEW.account_stage IS DISTINCT FROM OLD.account_stage
     AND NEW.account_stage_locked_at IS NOT DISTINCT FROM OLD.account_stage_locked_at
  THEN
    NEW.account_stage_locked_at := NOW();
  END IF;
  RETURN NEW;
END; $$;


