CREATE OR REPLACE FUNCTION "public"."crm_companies_set_normalized_domain"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $_$
BEGIN
  IF NEW.domain IS NULL OR TRIM(NEW.domain) = '' THEN
    NEW.normalized_domain := NULL;
  ELSE
    NEW.normalized_domain := LOWER(REGEXP_REPLACE(
      TRIM(NEW.domain),
      '^(https?://)?(www\.)?([^/]+).*$',
      '\3'
    ));
  END IF;
  NEW.updated_at := NOW();
  RETURN NEW;
END;
$_$;


