CREATE OR REPLACE FUNCTION "public"."crm_company_size_matches"("p_count" integer, "p_range" "text", "p_legacy_size" "text", "p_sizes" "text"[]) RETURNS boolean
    LANGUAGE "sql" IMMUTABLE PARALLEL SAFE
    AS $$
  SELECT p_sizes IS NULL OR EXISTS (
    SELECT 1 FROM unnest(p_sizes) s
    WHERE lower(s) = lower(COALESCE(p_range, p_legacy_size, ''))
       OR (lower(s) = '1-10' AND p_count BETWEEN 1 AND 10)
       OR (lower(s) = '11-50' AND p_count BETWEEN 11 AND 50)
       OR (lower(s) = '51-200' AND p_count BETWEEN 51 AND 200)
       OR (lower(s) = '201-500' AND p_count BETWEEN 201 AND 500)
       OR (lower(s) = '501-1000' AND p_count BETWEEN 501 AND 1000)
       OR (lower(s) = '1001-5000' AND p_count BETWEEN 1001 AND 5000)
       OR (lower(s) = '5001-10000' AND p_count BETWEEN 5001 AND 10000)
       OR (lower(s) IN ('10000+', '10001+') AND p_count >= 10001)
  );
$$;


ALTER FUNCTION "public"."crm_company_size_matches"("p_count" integer, "p_range" "text", "p_legacy_size" "text", "p_sizes" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."crm_contact_ids_by_custom_field"("p_organization_id" "uuid", "p_field_key" "text", "p_operator" "text", "p_value" "text" DEFAULT NULL::"text") RETURNS TABLE("id" "uuid")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF p_operator = 'has_value' THEN
    RETURN QUERY
      SELECT c.id FROM crm_contacts c
      WHERE c.organization_id = p_organization_id
        AND c.custom_fields ? p_field_key
        AND c.custom_fields ->> p_field_key IS DISTINCT FROM '';
  ELSIF p_operator = 'is_empty' THEN
    RETURN QUERY
      SELECT c.id FROM crm_contacts c
      WHERE c.organization_id = p_organization_id
        AND (NOT (c.custom_fields ? p_field_key) OR c.custom_fields ->> p_field_key = '');
  ELSIF p_operator = 'equals' THEN
    RETURN QUERY
      SELECT c.id FROM crm_contacts c
      WHERE c.organization_id = p_organization_id
        AND c.custom_fields @> jsonb_build_object(p_field_key, p_value);
  ELSIF p_operator = 'contains' THEN
    RETURN QUERY
      SELECT c.id FROM crm_contacts c
      WHERE c.organization_id = p_organization_id
        AND c.custom_fields ? p_field_key
        AND c.custom_fields ->> p_field_key ILIKE '%' || p_value || '%';
  END IF;
END;
$$;


ALTER FUNCTION "public"."crm_contact_ids_by_custom_field"("p_organization_id" "uuid", "p_field_key" "text", "p_operator" "text", "p_value" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."crm_contact_ids_by_custom_question"("p_organization_id" "uuid", "p_question" "text", "p_min_score" numeric DEFAULT NULL::numeric) RETURNS TABLE("id" "uuid")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
  SELECT c.id
  FROM crm_contacts c
  WHERE c.organization_id = p_organization_id
    AND c.enrichment_data @> jsonb_build_object(
      'custom_analysis', jsonb_build_array(jsonb_build_object('question', p_question)))
    AND EXISTS (
      SELECT 1 FROM jsonb_array_elements(COALESCE(c.enrichment_data->'custom_analysis', '[]'::jsonb)) e
      WHERE e->>'question' = p_question
        AND COALESCE(TRIM(e->>'answer'), '') <> ''
        AND (p_min_score IS NULL OR ((e->>'score') ~ '^-?[0-9]+(\.[0-9]+)?$' AND (e->>'score')::NUMERIC >= p_min_score))
    );
$_$;


ALTER FUNCTION "public"."crm_contact_ids_by_custom_question"("p_organization_id" "uuid", "p_question" "text", "p_min_score" numeric) OWNER TO "postgres";


