CREATE OR REPLACE FUNCTION "public"."crm_contacts_propagate_email_to_list_members"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$ DECLARE v_new_email text := NULLIF(lower(trim(NEW.primary_email)), ''); v_old_email text := NULLIF(lower(trim(OLD.primary_email)), ''); BEGIN IF v_new_email IS DISTINCT FROM v_old_email THEN DELETE FROM public.lead_list_members losing USING public.lead_list_members keeping WHERE losing.contact_id = NEW.id AND keeping.list_id = losing.list_id AND keeping.email_lower = v_new_email AND keeping.contact_id <> NEW.id AND (keeping.added_at, keeping.id) < (losing.added_at, losing.id); UPDATE public.lead_list_members SET email_lower = v_new_email WHERE contact_id = NEW.id; END IF; RETURN NEW; END; $$;


