CREATE OR REPLACE FUNCTION "public"."crm_create_pipeline"("p_org_id" "uuid", "p_name" "text", "p_template" "text" DEFAULT 'sales'::"text", "p_copy_from" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_id uuid;
  v_first boolean;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM get_accessible_organization_ids() o WHERE o = p_org_id) THEN
    RAISE EXCEPTION 'Not allowed to create a pipeline for this organization';
  END IF;
  IF coalesce(trim(p_name), '') = '' THEN
    RAISE EXCEPTION 'Pipeline name is required';
  END IF;
  IF p_template NOT IN ('sales', 'blank', 'copy') THEN
    RAISE EXCEPTION 'Unknown pipeline template %', p_template;
  END IF;
  IF p_template = 'copy' AND NOT EXISTS (
       SELECT 1 FROM crm_pipelines WHERE id = p_copy_from AND organization_id = p_org_id) THEN
    RAISE EXCEPTION 'Pipeline to copy was not found';
  END IF;

  v_first := NOT EXISTS (SELECT 1 FROM crm_pipelines WHERE organization_id = p_org_id);

  INSERT INTO crm_pipelines (organization_id, name, is_default, color)
  VALUES (p_org_id, trim(p_name), v_first, '#6366f1')
  RETURNING id INTO v_id;

  IF p_template = 'copy' THEN
    INSERT INTO crm_pipeline_stages (pipeline_id, organization_id, name, description, stage_order,
                                     stage_type, color, expected_days, win_probability)
    SELECT v_id, p_org_id, name, description, stage_order, stage_type, color, expected_days, win_probability
      FROM crm_pipeline_stages WHERE pipeline_id = p_copy_from;
  ELSIF p_template = 'blank' THEN
    INSERT INTO crm_pipeline_stages (pipeline_id, organization_id, name, stage_order, stage_type, color, win_probability) VALUES
      (v_id, p_org_id, 'New',  1, 'new',  '#3b82f6', 10),
      (v_id, p_org_id, 'Won',  2, 'won',  '#22c55e', 100),
      (v_id, p_org_id, 'Lost', 3, 'lost', '#ef4444', 0);
  ELSE
    INSERT INTO crm_pipeline_stages (pipeline_id, organization_id, name, stage_order, stage_type, color, win_probability) VALUES
      (v_id, p_org_id, 'Lead',           1, 'new',    '#3b82f6', 10),
      (v_id, p_org_id, 'Qualified',      2, 'active', '#8b5cf6', 25),
      (v_id, p_org_id, 'Meeting booked', 3, 'active', '#f59e0b', 40),
      (v_id, p_org_id, 'Proposal sent',  4, 'active', '#ec4899', 60),
      (v_id, p_org_id, 'Negotiation',    5, 'active', '#14b8a6', 80),
      (v_id, p_org_id, 'Won',            6, 'won',    '#22c55e', 100),
      (v_id, p_org_id, 'Lost',           7, 'lost',   '#ef4444', 0);
  END IF;

  RETURN v_id;
END;
$$;


ALTER FUNCTION "public"."crm_create_pipeline"("p_org_id" "uuid", "p_name" "text", "p_template" "text", "p_copy_from" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."crm_deal_report"("p_org_id" "uuid", "p_pipeline_id" "uuid" DEFAULT NULL::"uuid", "p_from" timestamp with time zone DEFAULT ("now"() - '90 days'::interval), "p_to" timestamp with time zone DEFAULT "now"(), "p_owner_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_result jsonb;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM get_accessible_organization_ids() o WHERE o = p_org_id) THEN
    RAISE EXCEPTION 'Not allowed to read this organization';
  END IF;

  WITH d AS (
    SELECT deals.*, s.win_probability AS stage_probability, s.name AS stage_name,
           s.stage_order, s.color AS stage_color, s.stage_type
      FROM crm_deals deals
      JOIN crm_pipeline_stages s ON s.id = deals.stage_id
     WHERE deals.organization_id = p_org_id
       AND (p_pipeline_id IS NULL OR deals.pipeline_id = p_pipeline_id)
       AND (p_owner_user_id IS NULL OR deals.owner_user_id = p_owner_user_id)
  ),
  open_d AS (
    SELECT *, value * coalesce(confidence, stage_probability, 0) / 100.0 AS weighted
      FROM d WHERE status = 'open'
  ),
  closed_d AS (
    SELECT * FROM d WHERE status IN ('won', 'lost') AND closed_at >= p_from AND closed_at <= p_to
  ),
  stages AS (
    SELECT s.id, s.name, s.color, s.stage_order, s.stage_type, s.win_probability
      FROM crm_pipeline_stages s
     WHERE s.organization_id = p_org_id
       AND (p_pipeline_id IS NULL OR s.pipeline_id = p_pipeline_id)
  )
  SELECT jsonb_build_object(
    'summary', jsonb_build_object(
      'open_count',     (SELECT count(*) FROM open_d),
      'open_value',     (SELECT coalesce(sum(value), 0) FROM open_d),
      'weighted_value', (SELECT coalesce(round(sum(weighted), 2), 0) FROM open_d),
      'won_count',      (SELECT count(*) FROM closed_d WHERE status = 'won'),
      'won_value',      (SELECT coalesce(sum(value), 0) FROM closed_d WHERE status = 'won'),
      'lost_count',     (SELECT count(*) FROM closed_d WHERE status = 'lost'),
      'lost_value',     (SELECT coalesce(sum(value), 0) FROM closed_d WHERE status = 'lost'),
      'win_rate',       (SELECT CASE WHEN count(*) = 0 THEN NULL
                                ELSE round(100.0 * count(*) FILTER (WHERE status = 'won') / count(*), 1) END
                           FROM closed_d),
      'avg_won_value',  (SELECT round(avg(value), 2) FROM closed_d WHERE status = 'won'),
      'avg_cycle_days', (SELECT round(avg(extract(epoch FROM closed_at - created_at) / 86400.0)::numeric, 1)
                           FROM closed_d WHERE status = 'won'),
      'overdue_count',  (SELECT count(*) FROM open_d WHERE expected_close_date < current_date)
    ),
    'by_stage', coalesce((
      SELECT jsonb_agg(jsonb_build_object(
               'stage_id', st.id, 'name', st.name, 'color', st.color, 'stage_type', st.stage_type,
               'win_probability', st.win_probability,
               'count', coalesce(x.cnt, 0), 'value', coalesce(x.val, 0),
               'weighted', coalesce(x.w, 0), 'avg_days_in_stage', x.avg_days)
             ORDER BY st.stage_order)
        FROM stages st
        LEFT JOIN (
          SELECT stage_id, count(*) cnt, sum(value) val, round(sum(weighted), 2) w,
                 round(avg(extract(epoch FROM now() - stage_entered_at) / 86400.0)::numeric, 1) avg_days
            FROM open_d GROUP BY stage_id
        ) x ON x.stage_id = st.id
       WHERE st.stage_type NOT IN ('won', 'lost')
    ), '[]'::jsonb),
    'forecast', coalesce((
      SELECT jsonb_agg(jsonb_build_object('month', m, 'count', cnt, 'value', val, 'weighted', w) ORDER BY m NULLS FIRST)
        FROM (
          SELECT CASE
                   WHEN expected_close_date IS NULL THEN NULL
                   WHEN expected_close_date < date_trunc('month', current_date) THEN 'overdue'
                   ELSE to_char(expected_close_date, 'YYYY-MM') END AS m,
                 count(*) cnt, sum(value) val, round(sum(weighted), 2) w
            FROM open_d
           WHERE expected_close_date IS NULL
              OR expected_close_date < (date_trunc('month', current_date) + interval '6 months')
           GROUP BY 1
        ) f
    ), '[]'::jsonb),
    'won_by_month', coalesce((
      SELECT jsonb_agg(jsonb_build_object('month', m, 'won_count', wc, 'won_value', wv, 'lost_count', lc) ORDER BY m)
        FROM (
          SELECT to_char(closed_at, 'YYYY-MM') m,
                 count(*) FILTER (WHERE status = 'won') wc,
                 coalesce(sum(value) FILTER (WHERE status = 'won'), 0) wv,
                 count(*) FILTER (WHERE status = 'lost') lc
            FROM closed_d GROUP BY 1
        ) w
    ), '[]'::jsonb),
    'by_owner', coalesce((
      SELECT jsonb_agg(jsonb_build_object(
               'owner_user_id', o.owner_user_id,
               'name', coalesce(u.full_name, u.email, 'Unassigned'),
               'open_count', o.open_count, 'open_value', o.open_value, 'weighted', o.weighted,
               'won_count', o.won_count, 'won_value', o.won_value, 'lost_count', o.lost_count,
               'win_rate', CASE WHEN o.won_count + o.lost_count = 0 THEN NULL
                                ELSE round(100.0 * o.won_count / (o.won_count + o.lost_count), 1) END)
             ORDER BY o.won_value DESC, o.open_value DESC)
        FROM (
          SELECT owner_user_id,
                 count(*) FILTER (WHERE src = 'open') open_count,
                 coalesce(sum(value) FILTER (WHERE src = 'open'), 0) open_value,
                 coalesce(round(sum(weighted) FILTER (WHERE src = 'open'), 2), 0) weighted,
                 count(*) FILTER (WHERE src = 'won') won_count,
                 coalesce(sum(value) FILTER (WHERE src = 'won'), 0) won_value,
                 count(*) FILTER (WHERE src = 'lost') lost_count
            FROM (
              SELECT owner_user_id, value, weighted, 'open'::text src FROM open_d
              UNION ALL
              SELECT owner_user_id, value, 0, status FROM closed_d
            ) u
           GROUP BY owner_user_id
        ) o
        LEFT JOIN users u ON u.id = o.owner_user_id
    ), '[]'::jsonb),
    'lost_reasons', coalesce((
      SELECT jsonb_agg(jsonb_build_object('reason', reason, 'count', cnt, 'value', val) ORDER BY cnt DESC)
        FROM (
          SELECT coalesce(nullif(trim(lost_reason), ''), 'No reason given') reason, count(*) cnt, sum(value) val
            FROM closed_d WHERE status = 'lost' GROUP BY 1
        ) l
    ), '[]'::jsonb)
  ) INTO v_result;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."crm_deal_report"("p_org_id" "uuid", "p_pipeline_id" "uuid", "p_from" timestamp with time zone, "p_to" timestamp with time zone, "p_owner_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."crm_deals_stage_log"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_to_name text;
  v_from_name text;
  v_activity_type text;
  v_title text;
BEGIN
  IF TG_OP = 'UPDATE' AND NEW.stage_id IS NOT DISTINCT FROM OLD.stage_id THEN
    RETURN NEW;
  END IF;

  INSERT INTO crm_deal_stage_history (organization_id, deal_id, from_stage_id, to_stage_id, value, changed_by)
  VALUES (NEW.organization_id, NEW.id,
          CASE WHEN TG_OP = 'UPDATE' THEN OLD.stage_id END,
          NEW.stage_id, NEW.value, auth.uid());

  IF NEW.contact_id IS NOT NULL AND EXISTS (
       SELECT 1 FROM crm_contacts c WHERE c.id = NEW.contact_id AND c.organization_id = NEW.organization_id) THEN
    SELECT name INTO v_to_name FROM crm_pipeline_stages WHERE id = NEW.stage_id;
    IF TG_OP = 'UPDATE' THEN
      SELECT name INTO v_from_name FROM crm_pipeline_stages WHERE id = OLD.stage_id;
    END IF;

    v_activity_type := CASE
      WHEN NEW.status = 'won' THEN 'deal_won'
      WHEN NEW.status = 'lost' THEN 'deal_lost'
      WHEN TG_OP = 'INSERT' THEN 'deal_created'
      ELSE 'stage_changed' END;
    v_title := CASE v_activity_type
      WHEN 'deal_won' THEN 'Deal won: ' || NEW.name
      WHEN 'deal_lost' THEN 'Deal lost: ' || NEW.name
      WHEN 'deal_created' THEN 'Deal created: ' || NEW.name
      ELSE 'Deal moved to ' || coalesce(v_to_name, 'a new stage') || ': ' || NEW.name END;

    INSERT INTO crm_activities (organization_id, contact_id, activity_type, title, description, metadata,
                                performed_by_type, performed_by_user_id)
    VALUES (NEW.organization_id, NEW.contact_id, v_activity_type, v_title,
            CASE WHEN v_activity_type = 'deal_lost' THEN NEW.lost_reason END,
            jsonb_build_object('deal_id', NEW.id, 'value', NEW.value, 'currency', NEW.currency,
                               'from_stage', v_from_name, 'to_stage', v_to_name),
            CASE WHEN auth.uid() IS NULL THEN 'system' ELSE 'user' END, auth.uid());
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."crm_deals_stage_log"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."crm_deals_stage_sync"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_stage record;
BEGIN
  IF TG_OP = 'UPDATE' AND NEW.stage_id IS NOT DISTINCT FROM OLD.stage_id
     AND NEW.pipeline_id IS NOT DISTINCT FROM OLD.pipeline_id THEN
    RETURN NEW;
  END IF;

  SELECT id, pipeline_id, organization_id, name, stage_type
    INTO v_stage
    FROM crm_pipeline_stages WHERE id = NEW.stage_id;

  IF v_stage.id IS NULL
     OR v_stage.pipeline_id <> NEW.pipeline_id
     OR v_stage.organization_id <> NEW.organization_id THEN
    RAISE EXCEPTION 'Stage % does not belong to pipeline %', NEW.stage_id, NEW.pipeline_id;
  END IF;

  NEW.stage_entered_at := now();
  NEW.status := CASE v_stage.stage_type WHEN 'won' THEN 'won' WHEN 'lost' THEN 'lost' ELSE 'open' END;
  IF NEW.status = 'open' THEN
    NEW.closed_at := NULL;
    NEW.lost_reason := NULL;
  ELSIF TG_OP = 'INSERT' OR OLD.status IS DISTINCT FROM NEW.status THEN
    NEW.closed_at := now();
  END IF;
  IF NEW.status <> 'lost' THEN
    NEW.lost_reason := NULL;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."crm_deals_stage_sync"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."crm_delete_pipeline"("p_pipeline_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org uuid;
  v_was_default boolean;
  v_deals bigint;
BEGIN
  SELECT organization_id, coalesce(is_default, false) INTO v_org, v_was_default
    FROM crm_pipelines WHERE id = p_pipeline_id;
  IF v_org IS NULL OR NOT EXISTS (SELECT 1 FROM get_accessible_organization_ids() o WHERE o = v_org) THEN
    RAISE EXCEPTION 'Pipeline not found';
  END IF;

  SELECT count(*) INTO v_deals FROM crm_deals WHERE pipeline_id = p_pipeline_id;
  IF v_deals > 0 THEN
    RAISE EXCEPTION 'This pipeline still has % deal(s). Move or delete them first.', v_deals;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM crm_pipelines WHERE organization_id = v_org AND id <> p_pipeline_id) THEN
    RAISE EXCEPTION 'You need at least one pipeline.';
  END IF;

  DELETE FROM crm_pipelines WHERE id = p_pipeline_id;

  IF v_was_default THEN
    UPDATE crm_pipelines SET is_default = true, updated_at = now()
     WHERE id = (SELECT id FROM crm_pipelines WHERE organization_id = v_org ORDER BY created_at LIMIT 1);
  END IF;
END;
$$;


ALTER FUNCTION "public"."crm_delete_pipeline"("p_pipeline_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."crm_email_quality_matches"("c" "public"."crm_contacts", "p_qualities" "text"[]) RETURNS boolean
    LANGUAGE "sql" IMMUTABLE PARALLEL SAFE
    AS $$
  SELECT p_qualities IS NULL OR (
    ('clean' = ANY(p_qualities) AND c.email_verified_at IS NOT NULL AND c.email_verification_status = 'valid'
      AND COALESCE(c.email_is_catch_all,false)=false AND COALESCE(c.email_is_role,false)=false AND COALESCE(c.email_is_free,false)=false
      AND COALESCE(c.email_is_disposable,false)=false AND COALESCE(c.email_is_spamtrap,false)=false)
    OR ('risky' = ANY(p_qualities) AND c.email_verified_at IS NOT NULL AND
      (c.email_verification_status='catch_all' OR c.email_is_catch_all=true OR c.email_is_role=true OR c.email_is_free=true)
      AND COALESCE(c.email_is_disposable,false)=false AND COALESCE(c.email_is_spamtrap,false)=false)
    OR ('failed' = ANY(p_qualities) AND c.email_verified_at IS NOT NULL AND
      (c.email_verification_status IN ('invalid','disposable','spamtrap','disabled','role_only') OR c.email_is_disposable=true OR c.email_is_spamtrap=true))
    OR ('unverified' = ANY(p_qualities) AND c.email_verified_at IS NULL)
  );
$$;


ALTER FUNCTION "public"."crm_email_quality_matches"("c" "public"."crm_contacts", "p_qualities" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."crm_set_default_pipeline"("p_pipeline_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org uuid;
BEGIN
  SELECT organization_id INTO v_org FROM crm_pipelines WHERE id = p_pipeline_id;
  IF v_org IS NULL OR NOT EXISTS (SELECT 1 FROM get_accessible_organization_ids() o WHERE o = v_org) THEN
    RAISE EXCEPTION 'Pipeline not found';
  END IF;

  UPDATE crm_pipelines
     SET is_default = (id = p_pipeline_id), updated_at = now()
   WHERE organization_id = v_org
     AND is_default IS DISTINCT FROM (id = p_pipeline_id);
END;
$$;


ALTER FUNCTION "public"."crm_set_default_pipeline"("p_pipeline_id" "uuid") OWNER TO "postgres";


