    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    SET "statement_timeout" TO '55s'
    AS $$
DECLARE
  v_deleted integer;
BEGIN
  DELETE FROM public.email_mailboxes WHERE id = ANY(p_ids);
  GET DIAGNOSTICS v_deleted = ROW_COUNT;
  RETURN v_deleted;
END;
$$;


ALTER FUNCTION "public"."delete_email_mailboxes"("p_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."determine_contact_type"("p_is_linkedin_connection" boolean, "p_source" "text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$
BEGIN
  -- Contact: Established relationship
  IF p_is_linkedin_connection = true OR p_source = 'linkedin_connection' THEN
    RETURN 'contact';
  END IF;

  -- Lead: Showed intent via comment/engagement
  IF p_source IN ('linkedin_comment', 'instagram_comment') THEN
    RETURN 'lead';
  END IF;

  -- Prospect: No interaction yet (imports, manual, search)
  RETURN 'prospect';
END;
$$;


