CREATE OR REPLACE FUNCTION "public"."dpc_record_hard_bounce"("p_org_id" "uuid", "p_domain" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  UPDATE public.domain_pattern_cache
  SET bounce_count = bounce_count + 1,
      hard_bounce_window_30d = hard_bounce_window_30d + 1,
      updated_at = NOW()
  WHERE organization_id = p_org_id
    AND domain = p_domain;

  -- §9.10 invalidation: 5+ hard bounces in 30 days flips confidence to 0
  -- and re-enters discovery on next access.
  UPDATE public.domain_pattern_cache
  SET confidence = 0,
      negative_result = TRUE,
      discovery_exhausted = FALSE,
      last_discovery_at = NULL
  WHERE organization_id = p_org_id
    AND domain = p_domain
    AND hard_bounce_window_30d >= 5;
END;
$$;


ALTER FUNCTION "public"."dpc_record_hard_bounce"("p_org_id" "uuid", "p_domain" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."dpc_reset_30d_bounce_window"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  UPDATE public.domain_pattern_cache
  SET hard_bounce_window_30d = 0
  WHERE updated_at < NOW() - INTERVAL '30 days'
    AND hard_bounce_window_30d > 0;
END;
$$;


ALTER FUNCTION "public"."dpc_reset_30d_bounce_window"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."email_analytics_assert_org"("p_org" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF coalesce(auth.jwt()->>'role', '') = 'service_role' THEN
    RETURN;
  END IF;
  IF p_org IS NULL OR p_org IS DISTINCT FROM public.get_user_organization_id() THEN
    RAISE EXCEPTION 'Not authorized for this organization' USING ERRCODE = '42501';
  END IF;
END;
$$;


ALTER FUNCTION "public"."email_analytics_assert_org"("p_org" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."email_analytics_period"("p_org" "uuid", "p_start" timestamp with time zone, "p_end" timestamp with time zone, "p_sequence_id" "uuid" DEFAULT NULL::"uuid", "p_mailbox_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "plan_cache_mode" TO 'force_custom_plan'
    AS $$
BEGIN
RETURN (
WITH rows AS (
  SELECT l.id, l.status, l.mailbox_id,
         coalesce(l.lead_id, l.id) AS lead_key,
         CASE l.status
           WHEN 'sent' THEN 1 WHEN 'delivered' THEN 2 WHEN 'auto_replied' THEN 2
           WHEN 'opened' THEN 3 WHEN 'clicked' THEN 4
           WHEN 'blocked' THEN 0 WHEN 'bounced' THEN 6 WHEN 'spam' THEN 7
           WHEN 'replied' THEN 8 ELSE -1
         END AS rank,
         (l.status IN ('opened','clicked')
           OR (l.status = 'replied' AND coalesce((es.settings->>'open_tracking')::boolean, true))
         ) AS opened_signal,
         (l.status = 'clicked'
           OR (l.status = 'replied' AND coalesce((es.settings->>'click_tracking')::boolean, true))
         ) AS clicked_signal
  FROM email_send_log l
  LEFT JOIN email_sequences es ON es.id = l.sequence_id
  WHERE l.organization_id = p_org
    AND l.status NOT IN ('queued','sending','filtered','skipped','failed')
    AND l.created_at >= coalesce(p_start, '-infinity'::timestamptz)
    AND l.created_at <= coalesce(p_end, 'infinity'::timestamptz)
    AND (p_sequence_id IS NULL OR l.sequence_id = p_sequence_id)
    AND (p_mailbox_id IS NULL OR l.mailbox_id = p_mailbox_id)
),
lead_best AS (
  SELECT lead_key, max(rank) AS rank,
         bool_or(opened_signal) AS opened, bool_or(clicked_signal) AS clicked
  FROM rows GROUP BY lead_key
),
responses AS (
  SELECT r.lead_key, o.lead_intent, coalesce(o.meeting, false) AS meeting,
         (r.status = 'replied'
           AND (coalesce(o.meeting, false) OR o.lead_intent IS NULL
                OR o.lead_intent NOT IN ('out_of_office', 'auto_reply'))) AS genuine
  FROM rows r
  JOIN email_send_log s ON s.id = r.id
  LEFT JOIN LATERAL public.email_reply_outcome(p_org, s.recipient_email, r.mailbox_id) o ON true
  WHERE r.status IN ('replied', 'auto_replied')
),
response_leads AS (
  SELECT lead_key,
         bool_or(genuine) AS genuine,
         (array_agg(lead_intent ORDER BY public.email_reply_intent_priority(lead_intent) DESC)
            FILTER (WHERE genuine))[1] AS intent,
         coalesce(bool_or(meeting AND genuine), false) AS meeting,
         coalesce(bool_or(lead_intent = 'out_of_office'), false) AS ooo
  FROM responses GROUP BY lead_key
),
agg AS (
  SELECT (SELECT count(*) FROM rows) AS sent,
         count(*) AS unique_leads,
         count(*) FILTER (WHERE rank NOT IN (0,6,7)) AS delivered,
         count(*) FILTER (WHERE opened) AS opened,
         count(*) FILTER (WHERE clicked) AS clicked,
         count(*) FILTER (WHERE rank = 6) AS bounced,
         count(*) FILTER (WHERE rank = 0) AS blocked
  FROM lead_best
)
SELECT to_jsonb(agg) || jsonb_build_object(
  'replied', (SELECT count(*) FROM response_leads WHERE genuine),
  'positive', (SELECT count(*) FROM response_leads WHERE genuine AND (intent IN ('interested','meeting_booked') OR meeting)),
  'meetings', (SELECT count(*) FROM response_leads WHERE genuine AND meeting),
  'out_of_office', (SELECT count(*) FROM response_leads WHERE NOT genuine AND ooo),
  'auto_replied', (SELECT count(*) FROM response_leads WHERE NOT genuine AND NOT ooo),
  'intents', (
    SELECT coalesce(jsonb_object_agg(k, n), '{}'::jsonb)
    FROM (
      SELECT CASE WHEN meeting THEN 'meeting_booked' ELSE coalesce(intent, 'unclassified') END AS k,
             count(*) AS n
      FROM response_leads WHERE genuine GROUP BY 1
    ) x
  )
)
FROM agg
);
END;
$$;


ALTER FUNCTION "public"."email_analytics_period"("p_org" "uuid", "p_start" timestamp with time zone, "p_end" timestamp with time zone, "p_sequence_id" "uuid", "p_mailbox_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."email_reply_intent_priority"("p_intent" "text") RETURNS integer
    LANGUAGE "sql" IMMUTABLE
    AS $$
  SELECT CASE p_intent
    WHEN 'meeting_booked' THEN 8 WHEN 'interested' THEN 7 WHEN 'neutral' THEN 6
    WHEN 'not_interested' THEN 5 WHEN 'unsubscribe' THEN 4 WHEN 'do_not_contact' THEN 3
    WHEN 'out_of_office' THEN 2 WHEN 'auto_reply' THEN 1 ELSE 0
  END
$$;


ALTER FUNCTION "public"."email_reply_intent_priority"("p_intent" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."email_reply_outcome"("p_org" "uuid", "p_email" "text", "p_mailbox_id" "uuid") RETURNS TABLE("conversation_id" "uuid", "contact_id" "uuid", "contact_name" "text", "lead_intent" "text", "meeting" boolean)
    LANGUAGE "sql" STABLE
    AS $$
  SELECT cv.id, c.id, c.display_name, cv.lead_intent,
         (cv.lead_intent = 'meeting_booked'
           OR EXISTS (
             SELECT 1 FROM ghl_appointment_log a
             WHERE a.organization_id = p_org
               AND a.conversation_id = cv.id
               AND coalesce(lower(a.appointment_status), '') NOT IN ('cancelled', 'canceled', 'invalid')
           )) AS meeting
  FROM crm_contacts c
  JOIN crm_conversations cv ON cv.contact_id = c.id AND cv.mailbox_id IS NOT NULL
  WHERE c.organization_id = p_org
    AND lower(c.primary_email) = lower(p_email)
  ORDER BY (cv.mailbox_id = p_mailbox_id) DESC NULLS LAST,
           (cv.lead_intent IS NOT NULL) DESC,
           cv.last_message_at DESC NULLS LAST
  LIMIT 1
$$;


ALTER FUNCTION "public"."email_reply_outcome"("p_org" "uuid", "p_email" "text", "p_mailbox_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."emit_campaign_entry_decision"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NEW.status IS DISTINCT FROM OLD.status AND NEW.status IN ('review','enrolled','ignored','declined','error') THEN
    PERFORM public.queue_webhook_event(NEW.organization_id,'campaign_entry_decided',jsonb_build_object(
      'entry_event_id',NEW.id,'campaign_id',NEW.campaign_id,'trigger_id',NEW.trigger_id,'contact_id',NEW.contact_id,
      'event_type',NEW.event_type,'status',NEW.status,'reason',NEW.reason,'icp_score',NEW.icp_score,'source_event_id',NEW.source_event_id
    ));
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."emit_campaign_entry_decision"() OWNER TO "postgres";


