CREATE OR REPLACE FUNCTION "public"."enqueue_lead_list_processing_all"("p_list_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_policy_id UUID;
  v_org_id UUID;
  v_is_smart BOOLEAN;
  v_count INTEGER;
BEGIN
  SELECT p.id, p.organization_id, l.is_smart
  INTO v_policy_id, v_org_id, v_is_smart
  FROM public.lead_list_processing_policies p
  JOIN public.lead_lists l ON l.id = p.lead_list_id
  WHERE p.lead_list_id = p_list_id
    AND EXISTS (
      SELECT 1
      FROM public.organization_members membership
      WHERE membership.organization_id = p.organization_id
        AND membership.user_id = auth.uid()
    );

  IF v_policy_id IS NULL THEN
    RAISE EXCEPTION 'Configure lead processing for this list before running it';
  END IF;

  INSERT INTO public.lead_list_processing_items (
    policy_id,
    organization_id,
    lead_list_id,
    contact_id,
    manual_run
  )
  SELECT v_policy_id, v_org_id, p_list_id, source.contact_id, TRUE
  FROM (
    -- Smart lists follow saved eligibility; static lists follow membership.
    SELECT eligible.contact_id
    FROM public.smart_list_eligible_contact_ids(p_list_id) AS eligible(contact_id)
    WHERE v_is_smart
    UNION
    SELECT member.contact_id
    FROM public.lead_list_members member
    WHERE NOT v_is_smart
      AND member.list_id = p_list_id
  ) AS source
  JOIN public.crm_contacts contact
    ON contact.id = source.contact_id
   AND contact.organization_id = v_org_id
  ON CONFLICT (policy_id, contact_id) DO UPDATE
  SET manual_run = TRUE,
      status = CASE
        WHEN lead_list_processing_items.status IN ('processing', 'completed') THEN lead_list_processing_items.status
        ELSE 'pending'
      END,
      stage = CASE
        WHEN lead_list_processing_items.status IN ('processing', 'completed') THEN lead_list_processing_items.stage
        ELSE 'queued'
      END,
      attempts = CASE
        WHEN lead_list_processing_items.status IN ('processing', 'completed') THEN lead_list_processing_items.attempts
        ELSE 0
      END,
      next_attempt_at = CASE
        WHEN lead_list_processing_items.status IN ('processing', 'completed') THEN lead_list_processing_items.next_attempt_at
        ELSE NOW()
      END,
      completed_at = CASE
        WHEN lead_list_processing_items.status IN ('processing', 'completed') THEN lead_list_processing_items.completed_at
        ELSE NULL
      END,
      rejected_reason = CASE
        WHEN lead_list_processing_items.status IN ('processing', 'completed') THEN lead_list_processing_items.rejected_reason
        ELSE NULL
      END,
      last_error = CASE
        WHEN lead_list_processing_items.status IN ('processing', 'completed') THEN lead_list_processing_items.last_error
        ELSE NULL
      END,
      updated_at = NOW();

  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$$;


ALTER FUNCTION "public"."enqueue_lead_list_processing_all"("p_list_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enqueue_lead_list_processing_contacts"("p_list_id" "uuid", "p_contact_ids" "uuid"[]) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_policy_id UUID;
  v_org_id UUID;
  v_is_smart BOOLEAN;
  v_count INTEGER;
BEGIN
  SELECT p.id, p.organization_id, l.is_smart
  INTO v_policy_id, v_org_id, v_is_smart
  FROM public.lead_list_processing_policies p
  JOIN public.lead_lists l ON l.id = p.lead_list_id
  WHERE p.lead_list_id = p_list_id
    AND EXISTS (
      SELECT 1
      FROM public.organization_members membership
      WHERE membership.organization_id = p.organization_id
        AND membership.user_id = auth.uid()
    );

  IF v_policy_id IS NULL THEN
    RAISE EXCEPTION 'Configure lead processing for this list before running it';
  END IF;

  INSERT INTO public.lead_list_processing_items (
    policy_id,
    organization_id,
    lead_list_id,
    contact_id,
    manual_run
  )
  SELECT v_policy_id, v_org_id, p_list_id, contact.id, TRUE
  FROM unnest(COALESCE(p_contact_ids, '{}')) AS requested(contact_id)
  JOIN public.crm_contacts contact
    ON contact.id = requested.contact_id
   AND contact.organization_id = v_org_id
  WHERE v_is_smart
     OR EXISTS (
       SELECT 1
       FROM public.lead_list_members member
       WHERE member.list_id = p_list_id
         AND member.contact_id = requested.contact_id
     )
  ON CONFLICT (policy_id, contact_id) DO UPDATE
  SET manual_run = TRUE,
      status = CASE
        WHEN lead_list_processing_items.status = 'processing' THEN lead_list_processing_items.status
        ELSE 'pending'
      END,
      stage = CASE
        WHEN lead_list_processing_items.status = 'processing' THEN lead_list_processing_items.stage
        ELSE 'queued'
      END,
      attempts = CASE
        WHEN lead_list_processing_items.status = 'processing' THEN lead_list_processing_items.attempts
        ELSE 0
      END,
      next_attempt_at = CASE
        WHEN lead_list_processing_items.status = 'processing' THEN lead_list_processing_items.next_attempt_at
        ELSE NOW()
      END,
      completed_at = CASE
        WHEN lead_list_processing_items.status = 'processing' THEN lead_list_processing_items.completed_at
        ELSE NULL
      END,
      rejected_reason = CASE
        WHEN lead_list_processing_items.status = 'processing' THEN lead_list_processing_items.rejected_reason
        ELSE NULL
      END,
      last_error = CASE
        WHEN lead_list_processing_items.status = 'processing' THEN lead_list_processing_items.last_error
        ELSE NULL
      END,
      cancel_requested_at = CASE
        WHEN lead_list_processing_items.status = 'processing' THEN lead_list_processing_items.cancel_requested_at
        ELSE NULL
      END,
      canceled_at = CASE
        WHEN lead_list_processing_items.status = 'processing' THEN lead_list_processing_items.canceled_at
        ELSE NULL
      END,
      updated_at = NOW();

  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$$;


ALTER FUNCTION "public"."enqueue_lead_list_processing_contacts"("p_list_id" "uuid", "p_contact_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enqueue_lead_list_processing_item"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_policy public.lead_list_processing_policies%ROWTYPE;
BEGIN
  SELECT * INTO v_policy
  FROM public.lead_list_processing_policies
  WHERE lead_list_id = NEW.list_id AND enabled = TRUE;

  IF FOUND THEN
    INSERT INTO public.lead_list_processing_items (
      policy_id, organization_id, lead_list_id, contact_id
    ) VALUES (
      v_policy.id, v_policy.organization_id, NEW.list_id, NEW.contact_id
    ) ON CONFLICT (policy_id, contact_id) DO UPDATE
      SET status = CASE
        WHEN lead_list_processing_items.status IN ('rejected', 'failed') THEN 'pending'
        ELSE lead_list_processing_items.status
      END,
      stage = CASE
        WHEN lead_list_processing_items.status IN ('rejected', 'failed') THEN 'queued'
        ELSE lead_list_processing_items.stage
      END,
      next_attempt_at = CASE
        WHEN lead_list_processing_items.status IN ('rejected', 'failed') THEN NOW()
        ELSE lead_list_processing_items.next_attempt_at
      END,
      updated_at = NOW();
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."enqueue_lead_list_processing_item"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enqueue_lead_list_processing_items_stmt"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  INSERT INTO public.lead_list_processing_items (policy_id, organization_id, lead_list_id, contact_id)
  SELECT p.id, p.organization_id, i.list_id, i.contact_id
  FROM inserted i
  JOIN public.lead_list_processing_policies p ON p.lead_list_id = i.list_id AND p.enabled = TRUE
  ON CONFLICT (policy_id, contact_id) DO UPDATE
    SET status = CASE
      WHEN lead_list_processing_items.status IN ('rejected', 'failed') THEN 'pending'
      ELSE lead_list_processing_items.status
    END,
    stage = CASE
      WHEN lead_list_processing_items.status IN ('rejected', 'failed') THEN 'queued'
      ELSE lead_list_processing_items.stage
    END,
    next_attempt_at = CASE
      WHEN lead_list_processing_items.status IN ('rejected', 'failed') THEN NOW()
      ELSE lead_list_processing_items.next_attempt_at
    END,
    updated_at = NOW();
  RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."enqueue_lead_list_processing_items_stmt"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enqueue_pool_classification"("p_domains" "text"[], "p_source" "text" DEFAULT 'bulk'::"text", "p_priority" smallint DEFAULT 100) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
declare v_n int;
begin
  insert into lead_pool_classify_queue (domain, source, priority)
  select lower(trim(d)), p_source, p_priority
    from unnest(p_domains) d
   -- The dump contains genuine garbage in the domain column: tab-delimited
   -- fragments, leading punctuation, bare labels with no TLD. Fetching those
   -- burns a slot and always fails, so reject anything that is not shaped like
   -- a hostname before it ever enters the queue.
   where d is not null
     and lower(trim(d)) ~ '^[a-z0-9]([a-z0-9-]*[a-z0-9])?(\.[a-z0-9]([a-z0-9-]*[a-z0-9])?)*\.[a-z]{2,}$'
     and length(trim(d)) between 4 and 253
     and not exists (select 1 from lead_pool_verified v
                      where v.domain = lower(trim(d)) and v.website_checked_at is not null)
  on conflict (domain) do update
     set priority = least(lead_pool_classify_queue.priority, excluded.priority)
   where lead_pool_classify_queue.status = 'pending';
  get diagnostics v_n = row_count;
  return v_n;
end; $_$;


ALTER FUNCTION "public"."enqueue_pool_classification"("p_domains" "text"[], "p_source" "text", "p_priority" smallint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enqueue_pool_enrichment"("p_rows" "jsonb", "p_source" "text" DEFAULT 'pool_build'::"text", "p_priority" smallint DEFAULT 100, "p_requested_by" "uuid" DEFAULT NULL::"uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_inserted int;
begin
  with candidate as (
    select lower(r->>'domain')  as domain,
           r->>'linkedin_url'   as linkedin_url
      from jsonb_array_elements(p_rows) r
     where coalesce(r->>'domain', '') <> ''
       and coalesce(r->>'linkedin_url', '') <> ''
  ), fresh as (
    select c.domain, min(c.linkedin_url) as linkedin_url
      from candidate c
      left join lead_pool_verified v on v.domain = c.domain
     -- Already looked up (hit or miss) = nothing more to learn cheaply.
     where v.moltsets_checked_at is null
     group by c.domain
  )
  insert into lead_pool_enrich_queue (domain, linkedin_url, source, priority, requested_by)
  select f.domain, f.linkedin_url, p_source, p_priority, p_requested_by
    from fresh f
  on conflict (domain) do update
     -- A later request at higher priority promotes an already-queued domain.
     set priority = least(lead_pool_enrich_queue.priority, excluded.priority)
   where lead_pool_enrich_queue.status = 'pending';

  get diagnostics v_inserted = row_count;
  return v_inserted;
end;
$$;


ALTER FUNCTION "public"."enqueue_pool_enrichment"("p_rows" "jsonb", "p_source" "text", "p_priority" smallint, "p_requested_by" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enrich_pool_contacts_from_rows"("p_org_id" "uuid", "p_rows" "jsonb") RETURNS TABLE("matched" integer, "updated" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    SET "statement_timeout" TO '120s'
    AS $$
DECLARE
  v_matched int := 0;
  v_updated int := 0;
BEGIN
  WITH desired AS (
    SELECT DISTINCT ON (lower(r->>'email'))
      lower(r->>'email') AS email_lc,
      jsonb_strip_nulls(jsonb_build_object(
        'industry',          NULLIF(r->>'industry', '\N'),
        'p_industry',        NULLIF(r->>'p_industry', '\N'),
        'p_bucket',          NULLIF(r->>'p_bucket', '\N'),
        'sic_code',          NULLIF(r->>'sic_code', '\N'),
        'department',        NULLIF(r->>'department', '\N'),
        'seniority',         NULLIF(r->>'seniority', '\N'),
        'employees',         CASE
                                WHEN r->>'employees' IS NULL OR r->>'employees' IN ('','\N')
                                  THEN NULL
                                ELSE (r->>'employees')::int
                             END,
        'employees_range',   NULLIF(r->>'employees_range', '\N'),
        'employees_max',     CASE
                                WHEN r->>'employees_max' IS NULL OR r->>'employees_max' IN ('','\N')
                                  THEN NULL
                                ELSE (r->>'employees_max')::int
                             END,
        'annual_revenue',    NULLIF(r->>'annual_revenue', '\N'),
        'company_phone',     NULLIF(r->>'company_phone', '\N'),
        'company_linkedin',  NULLIF(r->>'company_linkedin_url', '\N'),
        'company_address',   NULLIF(r->>'company_address', '\N'),
        'company_city',      NULLIF(r->>'company_city', '\N'),
        'company_state',     NULLIF(r->>'company_state', '\N'),
        'company_zip',       NULLIF(r->>'company_zip', '\N'),
        'email_status',      NULLIF(r->>'email_status', '\N'),
        'personal_emails',   NULLIF(r->>'personal_emails', '\N')
      )) AS pool_data
    FROM jsonb_array_elements(p_rows) r
    WHERE r->>'email' IS NOT NULL AND r->>'email' <> ''
  ),
  updated AS (
    UPDATE crm_contacts c
       SET custom_fields = COALESCE(c.custom_fields, '{}'::jsonb) || d.pool_data,
           updated_at    = now()
      FROM desired d
     WHERE c.organization_id = p_org_id
       AND c.primary_email   = d.email_lc
       AND d.pool_data <> '{}'::jsonb
    RETURNING 1
  )
  SELECT count(*)::int INTO v_updated FROM updated;

  SELECT count(*)::int INTO v_matched
  FROM (
    SELECT DISTINCT lower(r->>'email') AS email_lc
    FROM jsonb_array_elements(p_rows) r
    WHERE r->>'email' IS NOT NULL AND r->>'email' <> ''
  ) d
  WHERE EXISTS (
    SELECT 1 FROM public.crm_contacts c
    WHERE c.organization_id = p_org_id AND c.primary_email = d.email_lc
  );

  RETURN QUERY SELECT v_matched, v_updated;
END;
$$;


ALTER FUNCTION "public"."enrich_pool_contacts_from_rows"("p_org_id" "uuid", "p_rows" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enroll_in_sequence"("p_org_id" "uuid", "p_sequence_id" "uuid", "p_contact_id" "uuid", "p_enrolled_by" "uuid" DEFAULT NULL::"uuid", "p_conversation_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_enrollment_id UUID;
  v_first_step_id UUID;
  v_first_step_delay INTERVAL;
BEGIN
  SELECT id, CASE delay_unit
    WHEN 'minutes' THEN delay_amount * INTERVAL '1 minute'
    WHEN 'hours' THEN delay_amount * INTERVAL '1 hour'
    WHEN 'days' THEN delay_amount * INTERVAL '1 day'
    WHEN 'weeks' THEN delay_amount * INTERVAL '1 week'
    ELSE INTERVAL '0'
  END INTO v_first_step_id, v_first_step_delay
  FROM crm_sequence_steps WHERE sequence_id = p_sequence_id AND is_active = true ORDER BY position ASC LIMIT 1;

  INSERT INTO crm_sequence_enrollments (organization_id, sequence_id, contact_id, current_step_id, current_step_position, next_step_at, conversation_id, enrolled_by)
  VALUES (p_org_id, p_sequence_id, p_contact_id, v_first_step_id, 0, NOW() + COALESCE(v_first_step_delay, INTERVAL '0'), p_conversation_id, p_enrolled_by)
  ON CONFLICT (sequence_id, contact_id) DO UPDATE SET
    status = 'active', current_step_id = EXCLUDED.current_step_id, current_step_position = 0,
    next_step_at = EXCLUDED.next_step_at, exited_at = NULL, exit_reason = NULL, paused_at = NULL, steps_completed = 0, messages_sent = 0
  RETURNING id INTO v_enrollment_id;

  UPDATE crm_sequences SET total_enrolled = total_enrolled + 1, updated_at = NOW() WHERE id = p_sequence_id;
  RETURN v_enrollment_id;
END;
$$;


ALTER FUNCTION "public"."enroll_in_sequence"("p_org_id" "uuid", "p_sequence_id" "uuid", "p_contact_id" "uuid", "p_enrolled_by" "uuid", "p_conversation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enroll_smart_list_into_active_campaigns"("p_max_per_campaign" integer DEFAULT 500) RETURNS TABLE("campaign_id" "uuid", "list_id" "uuid", "is_smart" boolean, "enrolled" integer, "skipped" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_campaign RECORD;
  v_list RECORD;
  v_eligible UUID[];
  v_to_enroll UUID[];
  v_enrolled INTEGER;
  v_skipped INTEGER;
  v_total_eligible INTEGER;
  v_any_smart BOOLEAN;
BEGIN
  FOR v_campaign IN
    SELECT lc.id, lc.organization_id, lc.lead_list_ids, lc.exclusion_list_ids,
           lc.exclude_other_campaigns, lc.exclude_same_sender, lc.sender_account_ids,
           lc.enroll_filter_criteria
    FROM public.linkedin_campaigns lc
    WHERE lc.auto_enroll_new_members = TRUE
      AND lc.status = 'active'
      AND cardinality(COALESCE(lc.lead_list_ids, '{}')) > 0
  LOOP
    v_eligible := '{}';
    v_any_smart := FALSE;

    FOR v_list IN
      SELECT ll.id, ll.is_smart
      FROM public.lead_lists ll
      WHERE ll.id = ANY(v_campaign.lead_list_ids)
        AND ll.organization_id = v_campaign.organization_id
    LOOP
      IF v_list.is_smart THEN
        v_any_smart := TRUE;
        v_eligible := v_eligible || ARRAY(
          SELECT public.smart_list_eligible_contact_ids(v_list.id)
        );
      ELSE
        v_eligible := v_eligible || ARRAY(
          SELECT m.contact_id FROM public.lead_list_members m
          WHERE m.list_id = v_list.id
        );
      END IF;
    END LOOP;

    SELECT ARRAY(SELECT DISTINCT u FROM unnest(v_eligible) AS u) INTO v_eligible;

    v_eligible := public.filter_contact_ids_by_criteria(
      v_campaign.organization_id, v_eligible,
      COALESCE(v_campaign.enroll_filter_criteria, '{}'::jsonb)
    );

    v_eligible := public.filter_contact_ids_by_pipeline_gate(
      v_campaign.organization_id, v_campaign.lead_list_ids,
      'linkedin_campaign', v_campaign.id, v_eligible
    );

    v_total_eligible := COALESCE(array_length(v_eligible, 1), 0);

    SELECT ARRAY(
      SELECT cid
      FROM unnest(v_eligible) AS cid
      WHERE NOT EXISTS (
        SELECT 1 FROM public.campaign_lead_progress clp
        WHERE clp.campaign_id = v_campaign.id AND clp.contact_id = cid
      )
      AND (
        v_campaign.exclusion_list_ids IS NULL
        OR cardinality(v_campaign.exclusion_list_ids) = 0
        OR NOT EXISTS (
          SELECT 1 FROM public.lead_list_members exc
          WHERE exc.contact_id = cid
            AND exc.list_id = ANY(v_campaign.exclusion_list_ids)
        )
      )
      AND NOT public.contact_excluded_by_campaign_history(
        v_campaign.organization_id, v_campaign.id, cid,
        v_campaign.exclude_other_campaigns,
        v_campaign.exclude_same_sender,
        v_campaign.sender_account_ids
      )
      LIMIT p_max_per_campaign
    ) INTO v_to_enroll;

    v_enrolled := COALESCE(array_length(v_to_enroll, 1), 0);
    v_skipped := v_total_eligible - v_enrolled;

    IF v_enrolled > 0 THEN
      INSERT INTO public.campaign_lead_progress (
        campaign_id, contact_id, status, retry_count, created_at, updated_at
      )
      SELECT v_campaign.id, cid, 'pending', 0, NOW(), NOW()
      FROM unnest(v_to_enroll) AS cid;
    END IF;

    campaign_id := v_campaign.id;
    list_id := v_campaign.lead_list_ids[1];
    is_smart := v_any_smart;
    enrolled := v_enrolled;
    skipped := v_skipped;
    RETURN NEXT;
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."enroll_smart_list_into_active_campaigns"("p_max_per_campaign" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."enroll_smart_list_into_active_campaigns"("p_max_per_campaign" integer) IS 'Discovery Layer agent loop closure. Continuously enrolls newly eligible contacts into active campaigns whose auto_enroll_new_members=true. Cron-driven; idempotent.';



CREATE OR REPLACE FUNCTION "public"."enroll_smart_list_into_active_sequences"() RETURNS TABLE("sequence_id" "uuid", "list_id" "uuid", "http_request_id" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_seq RECORD;
  v_request_id BIGINT;
  v_supabase_url TEXT := (SELECT decrypted_secret FROM vault.decrypted_secrets WHERE name = 'supabase_url');
  v_service_key TEXT := (SELECT decrypted_secret FROM vault.decrypted_secrets WHERE name = 'supabase_service_role_key');
BEGIN
  FOR v_seq IN
    SELECT es.id, es.organization_id, es.lead_list_ids
    FROM public.email_sequences es
    WHERE es.auto_enroll_new_members = TRUE
      AND es.status = 'active'
      AND cardinality(COALESCE(es.lead_list_ids, '{}')) > 0
  LOOP
    SELECT net.http_post(
      url := v_supabase_url || '/functions/v1/enroll-leads',
      headers := jsonb_build_object(
        'Content-Type', 'application/json',
        'Authorization', 'Bearer ' || v_service_key
      ),
      body := jsonb_build_object(
        'sequenceId', v_seq.id,
        'organizationId', v_seq.organization_id,
        'listIds', to_jsonb(v_seq.lead_list_ids)
      )
    ) INTO v_request_id;

    sequence_id := v_seq.id;
    list_id := v_seq.lead_list_ids[1];
    http_request_id := v_request_id;
    RETURN NEXT;
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."enroll_smart_list_into_active_sequences"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."enroll_smart_list_into_active_sequences"() IS 'Sister function of enroll_smart_list_into_active_campaigns for email sequences. Posts to the enroll-leads edge function for each linked sequence so contact→lead resolution + scheduling stays in one place. Cron-driven; idempotent via the edge function''s ON CONFLICT clause.';



CREATE OR REPLACE FUNCTION "public"."enrollment_filter_preview"("p_org" "uuid", "p_list_ids" "uuid"[], "p_criteria" "jsonb") RETURNS TABLE("total_in_lists" integer, "matching" integer)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_ids uuid[];
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.organization_members om
    WHERE om.organization_id = p_org AND om.user_id = auth.uid()
  ) AND current_user NOT IN ('service_role', 'postgres') THEN
    RAISE EXCEPTION 'Not a member of this organization';
  END IF;

  SELECT ARRAY(
    SELECT DISTINCT x.contact_id
    FROM (
      SELECT unnest(ARRAY(SELECT public.smart_list_eligible_contact_ids(ll.id))) AS contact_id
      FROM public.lead_lists ll
      WHERE ll.id = ANY(COALESCE(p_list_ids, '{}')) AND ll.organization_id = p_org AND ll.is_smart
      UNION ALL
      SELECT m.contact_id
      FROM public.lead_list_members m
      JOIN public.lead_lists ll ON ll.id = m.list_id
      WHERE ll.id = ANY(COALESCE(p_list_ids, '{}')) AND ll.organization_id = p_org
        AND COALESCE(ll.is_smart, false) = false
    ) x
  ) INTO v_ids;

  total_in_lists := COALESCE(array_length(v_ids, 1), 0);
  matching := COALESCE(
    array_length(public.filter_contact_ids_by_criteria(p_org, v_ids, COALESCE(p_criteria, '{}'::jsonb)), 1),
    0
  );
  RETURN NEXT;
END;
$$;


ALTER FUNCTION "public"."enrollment_filter_preview"("p_org" "uuid", "p_list_ids" "uuid"[], "p_criteria" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enrollment_pipeline_inflows"("p_org" "uuid", "p_dest_type" "text", "p_dest_id" "uuid") RETURNS TABLE("list_id" "uuid", "list_name" "text", "enabled" boolean, "total" integer, "approved" integer, "rejected" integer, "awaiting" integer)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF auth.uid() IS NOT NULL AND NOT EXISTS (
    SELECT 1
    FROM public.organization_members membership
    WHERE membership.organization_id = p_org
      AND membership.user_id = auth.uid()
  ) THEN
    RAISE EXCEPTION 'Not a member of this organization';
  END IF;

  IF auth.uid() IS NULL
     AND auth.role() IS DISTINCT FROM 'service_role'
     AND session_user NOT IN ('postgres', 'supabase_admin') THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  RETURN QUERY
  SELECT
    list.id,
    list.name::text,
    policy.enabled,
    counts.total::integer,
    counts.approved::integer,
    counts.rejected::integer,
    GREATEST(counts.total - counts.approved - counts.rejected, 0)::integer
  FROM public.lead_list_processing_policies policy
  JOIN public.lead_lists list ON list.id = policy.lead_list_id
  CROSS JOIN LATERAL (
    SELECT
      (SELECT COUNT(*)
       FROM public.lead_list_members member
       WHERE member.list_id = policy.lead_list_id) AS total,
      (SELECT COUNT(*)
       FROM public.lead_list_processing_items item
       WHERE item.lead_list_id = policy.lead_list_id
         AND item.status = 'completed'
         AND item.rejected_reason IS NULL) AS approved,
      (SELECT COUNT(*)
       FROM public.lead_list_processing_items item
       WHERE item.lead_list_id = policy.lead_list_id
         AND item.rejected_reason IS NOT NULL) AS rejected
  ) counts
  WHERE policy.organization_id = p_org
    AND policy.approved_destination_type = p_dest_type
    AND policy.approved_destination_id = p_dest_id
  ORDER BY list.name;
END;
$$;


ALTER FUNCTION "public"."enrollment_pipeline_inflows"("p_org" "uuid", "p_dest_type" "text", "p_dest_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."enrollment_pipeline_inflows"("p_org" "uuid", "p_dest_type" "text", "p_dest_id" "uuid") IS 'Lead lists whose processing pipeline routes approved leads into this sequence/campaign, with per-list approved/rejected/awaiting counts. Lets the builder show every inflow, not just the directly attached lists.';



CREATE OR REPLACE FUNCTION "public"."ensure_public_signal_why_it_matters"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  IF NEW.why_it_matters IS NULL OR btrim(NEW.why_it_matters) = '' THEN
    NEW.why_it_matters := CASE NEW.signal_type
      WHEN 'funding' THEN NEW.company_name || ' has fresh funding: new budget and pressure to grow pipeline.'
      WHEN 'hiring' THEN NEW.company_name || ' is actively hiring: live growth investment and a timely reason to reach out.'
      WHEN 'hiring_demand' THEN NEW.company_name || ' is actively hiring: live growth investment and a timely reason to reach out.'
      WHEN 'acquisition' THEN NEW.company_name || ' announced an acquisition: new integration and growth priorities.'
      WHEN 'job_change' THEN NEW.company_name || ' has new leadership: a fresh mandate and vendor-evaluation window.'
      WHEN 'executive_hire' THEN NEW.company_name || ' has new leadership: a fresh mandate and vendor-evaluation window.'
      ELSE NEW.company_name || ' has a verified growth event: a timely reason to reach out.'
    END;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."ensure_public_signal_why_it_matters"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ensure_single_default_pipeline"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NEW.is_default = true THEN
    UPDATE crm_pipelines SET is_default = false WHERE organization_id = NEW.organization_id AND id != NEW.id AND is_default = true;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."ensure_single_default_pipeline"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."exclude_ideas_from_autopilot"("p_autopilot_id" "uuid", "p_idea_ids" "uuid"[]) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org uuid;
  v_count integer;
BEGIN
  SELECT organization_id INTO v_org FROM public.autopilots WHERE id = p_autopilot_id;
  IF v_org IS NULL OR v_org NOT IN (SELECT get_accessible_organization_ids()) THEN
    RAISE EXCEPTION 'Autopilot not found';
  END IF;

  INSERT INTO public.autopilot_idea_exclusions (autopilot_id, idea_id, organization_id)
  SELECT p_autopilot_id, ci.id, v_org
  FROM public.content_ideas ci
  WHERE ci.id = ANY (p_idea_ids) AND ci.organization_id = v_org
  ON CONFLICT DO NOTHING;
  GET DIAGNOSTICS v_count = ROW_COUNT;

  DELETE FROM public.autopilot_idea_pools
  WHERE autopilot_id = p_autopilot_id
    AND idea_id = ANY (p_idea_ids)
    AND status <> 'in_progress';

  RETURN v_count;
END;
$$;


ALTER FUNCTION "public"."exclude_ideas_from_autopilot"("p_autopilot_id" "uuid", "p_idea_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."exit_sequence_enrollment"("p_enrollment_id" "uuid", "p_reason" "text" DEFAULT 'manual'::"text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_sequence_id UUID;
BEGIN
  UPDATE crm_sequence_enrollments SET status = 'exited', exit_reason = p_reason, exited_at = NOW(), next_step_at = NULL
  WHERE id = p_enrollment_id RETURNING sequence_id INTO v_sequence_id;

  IF v_sequence_id IS NOT NULL AND p_reason = 'replied' THEN
    UPDATE crm_sequences SET total_replied = total_replied + 1, updated_at = NOW() WHERE id = v_sequence_id;
  END IF;
  RETURN FOUND;
END;
$$;


ALTER FUNCTION "public"."exit_sequence_enrollment"("p_enrollment_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."expire_stale_signal_reviews"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  UPDATE public.signal_review_queue
  SET status = 'expired', decided_at = NOW()
  WHERE status = 'pending'
    AND expires_at < NOW();
END;
$$;


ALTER FUNCTION "public"."expire_stale_signal_reviews"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fail_job"("p_job_id" "uuid", "p_error_message" "text", "p_error_stack" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
DECLARE
    v_job job_queue;
BEGIN
    -- Get current job state
    SELECT * INTO v_job FROM job_queue WHERE id = p_job_id;

    -- Check if we should retry
    IF v_job.retry_count < v_job.max_retries THEN
        UPDATE job_queue
        SET status = 'pending',
            retry_count = retry_count + 1,
            error_message = p_error_message,
            error_stack = p_error_stack,
            started_at = NULL,
            -- Exponential backoff: wait 2^retry_count minutes
            scheduled_for = NOW() + (POWER(2, retry_count) || ' minutes')::INTERVAL
        WHERE id = p_job_id;
    ELSE
        -- Max retries exceeded, mark as failed
        UPDATE job_queue
        SET status = 'failed',
            error_message = p_error_message,
            error_stack = p_error_stack,
            completed_at = NOW()
        WHERE id = p_job_id;
    END IF;
END;
$$;


ALTER FUNCTION "public"."fail_job"("p_job_id" "uuid", "p_error_message" "text", "p_error_stack" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."filter_contact_ids_by_criteria"("p_org" "uuid", "p_ids" "uuid"[], "p_criteria" "jsonb") RETURNS "uuid"[]
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_out uuid[];
BEGIN
  IF p_ids IS NULL OR cardinality(p_ids) = 0 THEN
    RETURN COALESCE(p_ids, '{}');
  END IF;
  IF p_criteria IS NULL OR p_criteria = '{}'::jsonb THEN
    RETURN p_ids;
  END IF;

  SELECT ARRAY(
    SELECT public.smart_list_eligible_contacts_for_criteria(p_org, p_criteria, p_ids)
  ) INTO v_out;

  RETURN COALESCE(v_out, '{}');
END;
$$;


ALTER FUNCTION "public"."filter_contact_ids_by_criteria"("p_org" "uuid", "p_ids" "uuid"[], "p_criteria" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."filter_contact_ids_by_criteria"("p_org" "uuid", "p_ids" "uuid"[], "p_criteria" "jsonb") IS 'Narrows a set of contact ids to those matching SmartListFilterCriteria, via the shared smart-list core. Empty criteria returns the input unchanged.';



CREATE OR REPLACE FUNCTION "public"."filter_contact_ids_by_pipeline_gate"("p_org" "uuid", "p_list_ids" "uuid"[], "p_dest_type" "text", "p_dest_id" "uuid", "p_ids" "uuid"[]) RETURNS "uuid"[]
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_gated  uuid[];
  v_lists  uuid[];
BEGIN
  IF p_ids IS NULL OR cardinality(p_ids) = 0 OR p_dest_id IS NULL THEN
    RETURN COALESCE(p_ids, '{}'::uuid[]);
  END IF;

  SELECT ARRAY(SELECT DISTINCT u FROM unnest(COALESCE(p_list_ids, '{}'::uuid[])) AS u)
  INTO v_lists;

  IF cardinality(v_lists) = 0 THEN
    RETURN p_ids;
  END IF;

  SELECT ARRAY(
    SELECT p.lead_list_id
    FROM public.lead_list_processing_policies p
    WHERE p.organization_id = p_org
      AND p.lead_list_id = ANY(v_lists)
      AND p.enabled = TRUE
      AND p.approved_destination_type = p_dest_type
      AND p.approved_destination_id = p_dest_id
  ) INTO v_gated;

  IF cardinality(v_gated) = 0 OR cardinality(v_gated) < cardinality(v_lists) THEN
    RETURN p_ids;
  END IF;

  RETURN ARRAY(
    SELECT cid
    FROM unnest(p_ids) AS cid
    WHERE EXISTS (
      SELECT 1
      FROM public.lead_list_processing_items i
      WHERE i.contact_id = cid
        AND i.lead_list_id = ANY(v_gated)
        AND i.status = 'completed'
        AND i.rejected_reason IS NULL
    )
  );
END;
$$;


ALTER FUNCTION "public"."filter_contact_ids_by_pipeline_gate"("p_org" "uuid", "p_list_ids" "uuid"[], "p_dest_type" "text", "p_dest_id" "uuid", "p_ids" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."filter_contact_ids_by_pipeline_gate"("p_org" "uuid", "p_list_ids" "uuid"[], "p_dest_type" "text", "p_dest_id" "uuid", "p_ids" "uuid"[]) IS 'Pipeline-owned enrollment gate. When every attached lead list routes its approved leads into this same destination, only contacts the processing pipeline approved may enrol — the direct "Ongoing" pull must not bypass qualify/enrich/verify. A mixed attach is passed through untouched.';



CREATE OR REPLACE FUNCTION "public"."filter_lead_list_member_rows"("p_list_id" "uuid", "p_filters" "jsonb" DEFAULT '{}'::"jsonb", "p_limit" integer DEFAULT NULL::integer, "p_offset" integer DEFAULT 0) RETURNS TABLE("member_id" "uuid", "contact_id" "uuid", "added_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    SET "statement_timeout" TO '55s'
    AS $$
DECLARE
  v_sizes text[] := CASE
    WHEN jsonb_typeof(p_filters->'companySizes') = 'array' AND jsonb_array_length(p_filters->'companySizes') > 0
    THEN ARRAY(SELECT lower(jsonb_array_elements_text(p_filters->'companySizes'))) END;
  v_min integer := NULLIF(p_filters->>'minEmployeeCount', '')::integer;
  v_max integer := NULLIF(p_filters->>'maxEmployeeCount', '')::integer;
BEGIN
  -- No firmographic filter: the core pages by itself, so a big list never
  -- gets fully scanned just to be cut down by LIMIT here.
  IF v_sizes IS NULL AND v_min IS NULL AND v_max IS NULL THEN
    RETURN QUERY
    SELECT r.member_id, r.contact_id, r.added_at
    FROM public.filter_lead_list_member_rows_core(p_list_id, COALESCE(p_filters, '{}'::jsonb), p_limit, p_offset) r;
    RETURN;
  END IF;

  RETURN QUERY
  SELECT r.member_id, r.contact_id, r.added_at
  FROM public.filter_lead_list_member_rows_core(
    p_list_id,
    p_filters - 'companySizes' - 'minEmployeeCount' - 'maxEmployeeCount',
    NULL, 0
  ) r
  JOIN public.crm_contacts c ON c.id = r.contact_id
  WHERE public.crm_company_size_matches(
      c.company_employee_count, c.company_employee_range,
      c.enrichment_data->'company'->>'size', v_sizes)
    AND (v_min IS NULL OR c.company_employee_count >= v_min)
    AND (v_max IS NULL OR c.company_employee_count <= v_max)
  ORDER BY r.added_at DESC, r.member_id DESC
  LIMIT p_limit OFFSET COALESCE(p_offset, 0);
END;
$$;


ALTER FUNCTION "public"."filter_lead_list_member_rows"("p_list_id" "uuid", "p_filters" "jsonb", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."filter_lead_list_member_rows"("p_list_id" "uuid", "p_filters" "jsonb", "p_limit" integer, "p_offset" integer) IS 'Lead-list Advanced Filters entry point: firmographic wrapper (companySizes, minEmployeeCount, maxEmployeeCount) around filter_lead_list_member_rows_core. Backs filter_lead_list_members, count_filtered_lead_list_members, get_filtered_lead_list_member_ids and /v1/lists/members filters.';



CREATE OR REPLACE FUNCTION "public"."filter_lead_list_member_rows_core"("p_list_id" "uuid", "p_filters" "jsonb" DEFAULT '{}'::"jsonb", "p_limit" integer DEFAULT NULL::integer, "p_offset" integer DEFAULT 0) RETURNS TABLE("member_id" "uuid", "contact_id" "uuid", "added_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    SET "statement_timeout" TO '55s'
    AS $_$
DECLARE
  v_org_id UUID;
  v_search TEXT;
  v_industries TEXT[];
  v_company_sizes TEXT[];
  v_seniorities TEXT[];
  v_departments TEXT[];
  v_technologies TEXT[];
  v_email_verified BOOLEAN;
  v_email_quality TEXT[];
  v_min_email_confidence INTEGER;
  v_email_type TEXT;
  v_has_email BOOLEAN;
  v_countries TEXT[];
  v_cities TEXT[];
  v_has_enrichment_data BOOLEAN;
  v_icp_product_id UUID;
  v_min_icp_score INTEGER;
  v_max_icp_score INTEGER;
  v_min_dm_score INTEGER;
  v_max_dm_score INTEGER;
  v_is_b2b BOOLEAN;
  v_revenue_models TEXT[];
  v_has_outbound_motion BOOLEAN;
  v_hiring_sales_roles BOOLEAN;
  v_has_notion_url BOOLEAN;
  v_seg_firewall TEXT;
  v_ai_analysis_status TEXT;
  v_runs_ads BOOLEAN;
  v_detected_technologies TEXT[];
  v_detected_tech_all BOOLEAN;
  v_excluded_technologies TEXT[];
  v_cq_question TEXT;
  v_cq_min_score NUMERIC;
  v_custom_questions JSONB;
  v_custom_fields JSONB;
  v_contact_fields JSONB;
BEGIN
  SELECT organization_id INTO v_org_id
  FROM public.lead_lists
  WHERE id = p_list_id;

  IF v_org_id IS NULL THEN
    RETURN;
  END IF;

  v_search := p_filters->>'search';
  v_icp_product_id := NULLIF(p_filters->>'icpProductId', '')::UUID;
  v_min_icp_score := NULLIF(p_filters->>'minIcpScore', '')::INTEGER;
  v_max_icp_score := NULLIF(p_filters->>'maxIcpScore', '')::INTEGER;
  v_min_dm_score := NULLIF(p_filters->>'minDmScore', '')::INTEGER;
  v_max_dm_score := NULLIF(p_filters->>'maxDmScore', '')::INTEGER;
  v_email_verified := NULLIF(p_filters->>'emailVerified', '')::BOOLEAN;
  v_min_email_confidence := NULLIF(p_filters->>'minEmailConfidence', '')::INTEGER;
  v_email_type := NULLIF(p_filters->>'emailType', '');
  v_has_email := NULLIF(p_filters->>'hasEmail', '')::BOOLEAN;
  v_has_enrichment_data := NULLIF(p_filters->>'hasEnrichmentData', '')::BOOLEAN;
  v_is_b2b := NULLIF(p_filters->>'isB2b', '')::BOOLEAN;
  v_has_outbound_motion := NULLIF(p_filters->>'hasOutboundMotion', '')::BOOLEAN;
  v_hiring_sales_roles := NULLIF(p_filters->>'hiringSalesRoles', '')::BOOLEAN;
  v_has_notion_url := NULLIF(p_filters->>'hasNotionUrl', '')::BOOLEAN;
  v_seg_firewall := NULLIF(p_filters->>'segFirewall', '');
  v_ai_analysis_status := NULLIF(p_filters->>'aiAnalysisStatus', '');
  v_runs_ads := NULLIF(p_filters->>'runsAds', '')::BOOLEAN;
  v_detected_tech_all := NULLIF(p_filters->>'detectedTechMatchAll', '')::BOOLEAN;
  v_cq_question := NULLIF(p_filters->>'customQuestion', '');
  v_cq_min_score := NULLIF(p_filters->>'customQuestionMinScore', '')::NUMERIC;

  IF jsonb_typeof(p_filters->'customQuestions') = 'array' AND jsonb_array_length(p_filters->'customQuestions') > 0 THEN
    v_custom_questions := p_filters->'customQuestions';
  END IF;
  IF jsonb_typeof(p_filters->'customFieldConditions') = 'array' AND jsonb_array_length(p_filters->'customFieldConditions') > 0 THEN
    v_custom_fields := p_filters->'customFieldConditions';
  END IF;
  IF jsonb_typeof(p_filters->'contactFieldConditions') = 'array' AND jsonb_array_length(p_filters->'contactFieldConditions') > 0 THEN
    v_contact_fields := p_filters->'contactFieldConditions';
  END IF;

  IF v_ai_analysis_status IS NOT NULL
    AND v_ai_analysis_status NOT IN ('not_analyzed', 'analyzing', 'analyzed', 'failed', 'no_data')
  THEN
    v_ai_analysis_status := NULL;
  END IF;

  IF jsonb_typeof(p_filters->'industries') = 'array' AND jsonb_array_length(p_filters->'industries') > 0 THEN
    SELECT ARRAY(SELECT LOWER(jsonb_array_elements_text(p_filters->'industries'))) INTO v_industries;
  END IF;
  IF jsonb_typeof(p_filters->'companySizes') = 'array' AND jsonb_array_length(p_filters->'companySizes') > 0 THEN
    SELECT ARRAY(SELECT LOWER(jsonb_array_elements_text(p_filters->'companySizes'))) INTO v_company_sizes;
  END IF;
  IF jsonb_typeof(p_filters->'seniorities') = 'array' AND jsonb_array_length(p_filters->'seniorities') > 0 THEN
    SELECT ARRAY(SELECT LOWER(jsonb_array_elements_text(p_filters->'seniorities'))) INTO v_seniorities;
  END IF;
  IF jsonb_typeof(p_filters->'departments') = 'array' AND jsonb_array_length(p_filters->'departments') > 0 THEN
    SELECT ARRAY(SELECT LOWER(jsonb_array_elements_text(p_filters->'departments'))) INTO v_departments;
  END IF;
  IF jsonb_typeof(p_filters->'technologies') = 'array' AND jsonb_array_length(p_filters->'technologies') > 0 THEN
    SELECT ARRAY(SELECT jsonb_array_elements_text(p_filters->'technologies')) INTO v_technologies;
  END IF;
  IF jsonb_typeof(p_filters->'detectedTechnologies') = 'array' AND jsonb_array_length(p_filters->'detectedTechnologies') > 0 THEN
    SELECT ARRAY(SELECT jsonb_array_elements_text(p_filters->'detectedTechnologies')) INTO v_detected_technologies;
  END IF;
  IF jsonb_typeof(p_filters->'excludedTechnologies') = 'array' AND jsonb_array_length(p_filters->'excludedTechnologies') > 0 THEN
    SELECT ARRAY(SELECT jsonb_array_elements_text(p_filters->'excludedTechnologies')) INTO v_excluded_technologies;
  END IF;
  IF jsonb_typeof(p_filters->'countries') = 'array' AND jsonb_array_length(p_filters->'countries') > 0 THEN
    SELECT ARRAY(SELECT LOWER(jsonb_array_elements_text(p_filters->'countries'))) INTO v_countries;
  END IF;
  IF jsonb_typeof(p_filters->'cities') = 'array' AND jsonb_array_length(p_filters->'cities') > 0 THEN
    SELECT ARRAY(SELECT LOWER(jsonb_array_elements_text(p_filters->'cities'))) INTO v_cities;
  END IF;
  IF jsonb_typeof(p_filters->'revenueModels') = 'array' AND jsonb_array_length(p_filters->'revenueModels') > 0 THEN
    SELECT ARRAY(SELECT LOWER(jsonb_array_elements_text(p_filters->'revenueModels'))) INTO v_revenue_models;
  END IF;
  IF jsonb_typeof(p_filters->'emailQuality') = 'array' AND jsonb_array_length(p_filters->'emailQuality') > 0 THEN
    SELECT ARRAY(SELECT jsonb_array_elements_text(p_filters->'emailQuality')) INTO v_email_quality;
  END IF;

  RETURN QUERY
  SELECT m.id, m.contact_id, m.added_at
  FROM public.lead_list_members m
  INNER JOIN public.crm_contacts c ON c.id = m.contact_id
  WHERE m.list_id = p_list_id
    AND (v_search IS NULL OR (
      c.display_name ILIKE '%' || v_search || '%'
      OR c.primary_email ILIKE '%' || v_search || '%'
      OR c.company ILIKE '%' || v_search || '%'
      OR c.job_title ILIKE '%' || v_search || '%'
    ))
    AND (v_icp_product_id IS NULL OR EXISTS (
      SELECT 1 FROM public.contact_product_scores cps
      WHERE cps.contact_id = c.id
        AND cps.product_id = v_icp_product_id
        AND cps.organization_id = v_org_id
        AND (v_min_icp_score IS NULL OR cps.icp_score >= v_min_icp_score)
        AND (v_max_icp_score IS NULL OR cps.icp_score <= v_max_icp_score)
        AND (v_min_dm_score IS NULL OR cps.decision_maker_score >= v_min_dm_score)
        AND (v_max_dm_score IS NULL OR cps.decision_maker_score <= v_max_dm_score)
    ))
    AND (v_industries IS NULL OR LOWER(c.enrichment_data->'company'->>'industry') = ANY(v_industries))
    AND (v_company_sizes IS NULL OR LOWER(c.enrichment_data->'company'->>'size') = ANY(v_company_sizes))
    AND (v_seniorities IS NULL OR LOWER(c.enrichment_data->>'seniority') = ANY(v_seniorities))
    AND (v_departments IS NULL OR LOWER(c.enrichment_data->>'department') = ANY(v_departments))
    AND (v_technologies IS NULL OR (c.enrichment_data->'company'->'technologies') @> to_jsonb(v_technologies))
    AND (v_detected_technologies IS NULL OR (
      CASE WHEN v_detected_tech_all
        THEN (c.enrichment_data->'detected_technologies'->'all') ?& v_detected_technologies
        ELSE (c.enrichment_data->'detected_technologies'->'all') ?| v_detected_technologies
      END))
    AND (v_excluded_technologies IS NULL OR NOT (COALESCE(c.enrichment_data->'detected_technologies'->'all', '[]'::jsonb) ?| v_excluded_technologies))
    AND (v_runs_ads IS NULL OR (c.enrichment_data->'detected_technologies'->>'runs_paid_ads')::BOOLEAN = v_runs_ads)
    AND (v_cq_question IS NULL OR EXISTS (
      SELECT 1 FROM jsonb_array_elements(COALESCE(c.enrichment_data->'custom_analysis', '[]'::jsonb)) e
      WHERE e->>'question' = v_cq_question
        AND COALESCE(TRIM(e->>'answer'), '') <> ''
        AND (v_cq_min_score IS NULL OR ((e->>'score') ~ '^-?[0-9]+(\.[0-9]+)?$' AND (e->>'score')::NUMERIC >= v_cq_min_score))
    ))
    AND (v_custom_questions IS NULL OR NOT EXISTS (
      SELECT 1 FROM jsonb_array_elements(v_custom_questions) cond
      WHERE NOT EXISTS (
        SELECT 1 FROM jsonb_array_elements(COALESCE(c.enrichment_data->'custom_analysis', '[]'::jsonb)) e
        WHERE e->>'question' = cond->>'question'
          AND COALESCE(TRIM(e->>'answer'), '') <> ''
          AND (NULLIF(cond->>'minScore','') IS NULL OR ((e->>'score') ~ '^-?[0-9]+(\.[0-9]+)?$' AND (e->>'score')::NUMERIC >= (cond->>'minScore')::NUMERIC))
      )
    ))
    AND (v_custom_fields IS NULL OR NOT EXISTS (
      SELECT 1 FROM jsonb_array_elements(v_custom_fields) cond
      WHERE NOT (
        CASE cond->>'operator'
          WHEN 'has_value' THEN c.custom_fields ? (cond->>'fieldKey')
            AND c.custom_fields->>(cond->>'fieldKey') IS DISTINCT FROM ''
          WHEN 'is_empty' THEN (NOT (c.custom_fields ? (cond->>'fieldKey')))
            OR c.custom_fields->>(cond->>'fieldKey') = ''
          WHEN 'equals' THEN c.custom_fields @> jsonb_build_object(cond->>'fieldKey', cond->>'value')
          WHEN 'contains' THEN c.custom_fields ? (cond->>'fieldKey')
            AND c.custom_fields->>(cond->>'fieldKey') ILIKE '%' || (cond->>'value') || '%'
          ELSE TRUE
        END
      )
    ))
    -- Native-column presence/match conditions. The allowlist lives in the inner
    -- CASE: an unrecognised field name resolves to NULL and therefore fails
    -- has_value / equals / contains and satisfies is_empty, rather than reaching
    -- the query planner as anything caller-controlled.
    AND (v_contact_fields IS NULL OR NOT EXISTS (
      SELECT 1 FROM jsonb_array_elements(v_contact_fields) cond
      WHERE NOT (
        CASE cond->>'operator'
          WHEN 'has_value' THEN COALESCE(TRIM(
            CASE cond->>'field'
              WHEN 'primary_email' THEN c.primary_email
              WHEN 'primary_phone' THEN c.primary_phone
              WHEN 'primary_linkedin_url' THEN c.primary_linkedin_url
              WHEN 'linkedin_bio' THEN c.linkedin_bio
              WHEN 'home_page_text' THEN c.home_page_text
              WHEN 'company' THEN c.company
              WHEN 'company_website' THEN c.company_website
              WHEN 'job_title' THEN c.job_title
              WHEN 'display_name' THEN c.display_name
              WHEN 'first_name' THEN c.first_name
              WHEN 'last_name' THEN c.last_name
              WHEN 'city' THEN c.city
              WHEN 'state' THEN c.state
              WHEN 'country' THEN c.country
              WHEN 'source' THEN c.source
              WHEN 'status' THEN c.status
              ELSE NULL
            END), '') <> ''
          WHEN 'is_empty' THEN COALESCE(TRIM(
            CASE cond->>'field'
              WHEN 'primary_email' THEN c.primary_email
              WHEN 'primary_phone' THEN c.primary_phone
              WHEN 'primary_linkedin_url' THEN c.primary_linkedin_url
              WHEN 'linkedin_bio' THEN c.linkedin_bio
              WHEN 'home_page_text' THEN c.home_page_text
              WHEN 'company' THEN c.company
              WHEN 'company_website' THEN c.company_website
              WHEN 'job_title' THEN c.job_title
              WHEN 'display_name' THEN c.display_name
              WHEN 'first_name' THEN c.first_name
              WHEN 'last_name' THEN c.last_name
              WHEN 'city' THEN c.city
              WHEN 'state' THEN c.state
              WHEN 'country' THEN c.country
              WHEN 'source' THEN c.source
              WHEN 'status' THEN c.status
              ELSE NULL
            END), '') = ''
          WHEN 'equals' THEN LOWER(COALESCE(
            CASE cond->>'field'
              WHEN 'primary_email' THEN c.primary_email
              WHEN 'primary_phone' THEN c.primary_phone
              WHEN 'primary_linkedin_url' THEN c.primary_linkedin_url
              WHEN 'linkedin_bio' THEN c.linkedin_bio
              WHEN 'home_page_text' THEN c.home_page_text
              WHEN 'company' THEN c.company
              WHEN 'company_website' THEN c.company_website
              WHEN 'job_title' THEN c.job_title
              WHEN 'display_name' THEN c.display_name
              WHEN 'first_name' THEN c.first_name
              WHEN 'last_name' THEN c.last_name
              WHEN 'city' THEN c.city
              WHEN 'state' THEN c.state
              WHEN 'country' THEN c.country
              WHEN 'source' THEN c.source
              WHEN 'status' THEN c.status
              ELSE NULL
            END, '')) = LOWER(COALESCE(cond->>'value', ''))
          WHEN 'contains' THEN COALESCE(
            CASE cond->>'field'
              WHEN 'primary_email' THEN c.primary_email
              WHEN 'primary_phone' THEN c.primary_phone
              WHEN 'primary_linkedin_url' THEN c.primary_linkedin_url
              WHEN 'linkedin_bio' THEN c.linkedin_bio
              WHEN 'home_page_text' THEN c.home_page_text
              WHEN 'company' THEN c.company
              WHEN 'company_website' THEN c.company_website
              WHEN 'job_title' THEN c.job_title
              WHEN 'display_name' THEN c.display_name
              WHEN 'first_name' THEN c.first_name
              WHEN 'last_name' THEN c.last_name
              WHEN 'city' THEN c.city
              WHEN 'state' THEN c.state
              WHEN 'country' THEN c.country
              WHEN 'source' THEN c.source
              WHEN 'status' THEN c.status
              ELSE NULL
            END, '') ILIKE '%' || COALESCE(cond->>'value', '') || '%'
          ELSE TRUE
        END
      )
    ))
    AND (v_email_verified IS NULL OR (c.enrichment_data->>'emailVerified')::BOOLEAN = v_email_verified)
    AND (v_email_quality IS NULL OR (
      ('clean' = ANY(v_email_quality) AND c.email_verified_at IS NOT NULL AND c.email_verification_status = 'valid'
        AND COALESCE(c.email_is_catch_all,false)=false AND COALESCE(c.email_is_role,false)=false AND COALESCE(c.email_is_free,false)=false
        AND COALESCE(c.email_is_disposable,false)=false AND COALESCE(c.email_is_spamtrap,false)=false)
      OR ('risky' = ANY(v_email_quality) AND c.email_verified_at IS NOT NULL AND
        (c.email_verification_status='catch_all' OR c.email_is_catch_all=true OR c.email_is_role=true OR c.email_is_free=true)
        AND COALESCE(c.email_is_disposable,false)=false AND COALESCE(c.email_is_spamtrap,false)=false)
      OR ('failed' = ANY(v_email_quality) AND c.email_verified_at IS NOT NULL AND
        (c.email_verification_status IN ('invalid','disposable','spamtrap','disabled','role_only') OR c.email_is_disposable=true OR c.email_is_spamtrap=true))
      OR ('unverified' = ANY(v_email_quality) AND c.email_verified_at IS NULL)
    ))
    AND (v_min_email_confidence IS NULL OR (c.enrichment_data->>'emailConfidence')::INTEGER >= v_min_email_confidence)
    AND (v_email_type IS NULL OR c.email_type = v_email_type)
    AND (v_has_email IS NULL
      OR (v_has_email = TRUE AND c.primary_email IS NOT NULL AND c.primary_email != '')
      OR (v_has_email = FALSE AND (c.primary_email IS NULL OR c.primary_email = '')))
    AND (v_countries IS NULL OR LOWER(c.country) = ANY(v_countries))
    AND (v_cities IS NULL OR LOWER(c.city) = ANY(v_cities))
    AND (v_has_enrichment_data IS NULL
      OR (v_has_enrichment_data = TRUE AND c.enrichment_data IS NOT NULL AND c.enrichment_data != '{}'::JSONB)
      OR (v_has_enrichment_data = FALSE AND (c.enrichment_data IS NULL OR c.enrichment_data = '{}'::JSONB)))
    AND (v_is_b2b IS NULL OR (c.enrichment_data->>'is_b2b')::BOOLEAN = v_is_b2b)
    AND (v_revenue_models IS NULL OR LOWER(c.enrichment_data->>'revenue_model') = ANY(v_revenue_models))
    AND (v_has_outbound_motion IS NULL OR (c.enrichment_data->>'has_outbound_motion')::BOOLEAN = v_has_outbound_motion)
    AND (v_hiring_sales_roles IS NULL OR (c.enrichment_data->>'hiring_sales_roles')::BOOLEAN = v_hiring_sales_roles)
    AND (v_has_notion_url IS NULL
      OR (v_has_notion_url = TRUE AND c.notion_preview_url IS NOT NULL AND c.notion_preview_url != '')
      OR (v_has_notion_url = FALSE AND (c.notion_preview_url IS NULL OR c.notion_preview_url = '')))
    AND (v_seg_firewall IS NULL
      OR (v_seg_firewall = 'behind' AND c.seg_provider IS NOT NULL)
      OR (v_seg_firewall = 'clear' AND c.seg_provider IS NULL AND c.seg_checked_at IS NOT NULL)
      OR (v_seg_firewall = 'unchecked' AND c.seg_checked_at IS NULL))
    AND (v_ai_analysis_status IS NULL
      OR (v_ai_analysis_status = 'no_data' AND (
            c.ai_analysis_status = 'failed'
            OR ((c.company_website IS NULL OR c.company_website = '')
              AND (c.primary_linkedin_url IS NULL OR c.primary_linkedin_url = ''))))
      OR (v_ai_analysis_status != 'no_data' AND c.ai_analysis_status = v_ai_analysis_status))
  ORDER BY m.added_at DESC, m.id DESC
  LIMIT p_limit OFFSET COALESCE(p_offset, 0);
END;
$_$;


ALTER FUNCTION "public"."filter_lead_list_member_rows_core"("p_list_id" "uuid", "p_filters" "jsonb", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."filter_lead_list_member_rows_core"("p_list_id" "uuid", "p_filters" "jsonb", "p_limit" integer, "p_offset" integer) IS 'Advanced Filters predicate core for lead-list members. Called only by filter_lead_list_member_rows, which strips companySizes/minEmployeeCount/maxEmployeeCount and applies them via crm_company_size_matches(). Edit predicates HERE, never by replacing filter_lead_list_member_rows with a full body.';



CREATE OR REPLACE FUNCTION "public"."filter_lead_list_member_rows_legacy"("p_list_id" "uuid", "p_filters" "jsonb" DEFAULT '{}'::"jsonb", "p_limit" integer DEFAULT NULL::integer, "p_offset" integer DEFAULT 0) RETURNS TABLE("member_id" "uuid", "contact_id" "uuid", "added_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    SET "statement_timeout" TO '55s'
    AS $_$
DECLARE
  v_org_id UUID;
  v_search TEXT;
  v_industries TEXT[];
  v_company_sizes TEXT[];
  v_seniorities TEXT[];
  v_departments TEXT[];
  v_technologies TEXT[];
  v_email_verified BOOLEAN;
  v_email_quality TEXT[];
  v_min_email_confidence INTEGER;
  v_email_type TEXT;
  v_has_email BOOLEAN;
  v_countries TEXT[];
  v_cities TEXT[];
  v_has_enrichment_data BOOLEAN;
  v_icp_product_id UUID;
  v_min_icp_score INTEGER;
  v_max_icp_score INTEGER;
  v_min_dm_score INTEGER;
  v_max_dm_score INTEGER;
  v_is_b2b BOOLEAN;
  v_revenue_models TEXT[];
  v_has_outbound_motion BOOLEAN;
  v_hiring_sales_roles BOOLEAN;
  v_has_notion_url BOOLEAN;
  v_seg_firewall TEXT;
  v_ai_analysis_status TEXT;
  v_runs_ads BOOLEAN;
  v_detected_technologies TEXT[];
  v_detected_tech_all BOOLEAN;
  v_excluded_technologies TEXT[];
  v_cq_question TEXT;
  v_cq_min_score NUMERIC;
  v_custom_questions JSONB;
  v_custom_fields JSONB;
  v_contact_fields JSONB;
BEGIN
  SELECT organization_id INTO v_org_id
  FROM public.lead_lists
  WHERE id = p_list_id;

  IF v_org_id IS NULL THEN
    RETURN;
  END IF;

  v_search := p_filters->>'search';
  v_icp_product_id := NULLIF(p_filters->>'icpProductId', '')::UUID;
  v_min_icp_score := NULLIF(p_filters->>'minIcpScore', '')::INTEGER;
  v_max_icp_score := NULLIF(p_filters->>'maxIcpScore', '')::INTEGER;
  v_min_dm_score := NULLIF(p_filters->>'minDmScore', '')::INTEGER;
  v_max_dm_score := NULLIF(p_filters->>'maxDmScore', '')::INTEGER;
  v_email_verified := NULLIF(p_filters->>'emailVerified', '')::BOOLEAN;
  v_min_email_confidence := NULLIF(p_filters->>'minEmailConfidence', '')::INTEGER;
  v_email_type := NULLIF(p_filters->>'emailType', '');
  v_has_email := NULLIF(p_filters->>'hasEmail', '')::BOOLEAN;
  v_has_enrichment_data := NULLIF(p_filters->>'hasEnrichmentData', '')::BOOLEAN;
  v_is_b2b := NULLIF(p_filters->>'isB2b', '')::BOOLEAN;
  v_has_outbound_motion := NULLIF(p_filters->>'hasOutboundMotion', '')::BOOLEAN;
  v_hiring_sales_roles := NULLIF(p_filters->>'hiringSalesRoles', '')::BOOLEAN;
  v_has_notion_url := NULLIF(p_filters->>'hasNotionUrl', '')::BOOLEAN;
  v_seg_firewall := NULLIF(p_filters->>'segFirewall', '');
  v_ai_analysis_status := NULLIF(p_filters->>'aiAnalysisStatus', '');
  v_runs_ads := NULLIF(p_filters->>'runsAds', '')::BOOLEAN;
  v_detected_tech_all := NULLIF(p_filters->>'detectedTechMatchAll', '')::BOOLEAN;
  v_cq_question := NULLIF(p_filters->>'customQuestion', '');
  v_cq_min_score := NULLIF(p_filters->>'customQuestionMinScore', '')::NUMERIC;

  IF jsonb_typeof(p_filters->'customQuestions') = 'array' AND jsonb_array_length(p_filters->'customQuestions') > 0 THEN
    v_custom_questions := p_filters->'customQuestions';
  END IF;
  IF jsonb_typeof(p_filters->'customFieldConditions') = 'array' AND jsonb_array_length(p_filters->'customFieldConditions') > 0 THEN
    v_custom_fields := p_filters->'customFieldConditions';
  END IF;
  IF jsonb_typeof(p_filters->'contactFieldConditions') = 'array' AND jsonb_array_length(p_filters->'contactFieldConditions') > 0 THEN
    v_contact_fields := p_filters->'contactFieldConditions';
  END IF;

  IF v_ai_analysis_status IS NOT NULL
    AND v_ai_analysis_status NOT IN ('not_analyzed', 'analyzing', 'analyzed', 'failed', 'no_data')
  THEN
    v_ai_analysis_status := NULL;
  END IF;

  IF jsonb_typeof(p_filters->'industries') = 'array' AND jsonb_array_length(p_filters->'industries') > 0 THEN
    SELECT ARRAY(SELECT LOWER(jsonb_array_elements_text(p_filters->'industries'))) INTO v_industries;
  END IF;
  IF jsonb_typeof(p_filters->'companySizes') = 'array' AND jsonb_array_length(p_filters->'companySizes') > 0 THEN
    SELECT ARRAY(SELECT LOWER(jsonb_array_elements_text(p_filters->'companySizes'))) INTO v_company_sizes;
  END IF;
  IF jsonb_typeof(p_filters->'seniorities') = 'array' AND jsonb_array_length(p_filters->'seniorities') > 0 THEN
    SELECT ARRAY(SELECT LOWER(jsonb_array_elements_text(p_filters->'seniorities'))) INTO v_seniorities;
  END IF;
  IF jsonb_typeof(p_filters->'departments') = 'array' AND jsonb_array_length(p_filters->'departments') > 0 THEN
    SELECT ARRAY(SELECT LOWER(jsonb_array_elements_text(p_filters->'departments'))) INTO v_departments;
  END IF;
  IF jsonb_typeof(p_filters->'technologies') = 'array' AND jsonb_array_length(p_filters->'technologies') > 0 THEN
    SELECT ARRAY(SELECT jsonb_array_elements_text(p_filters->'technologies')) INTO v_technologies;
  END IF;
  IF jsonb_typeof(p_filters->'detectedTechnologies') = 'array' AND jsonb_array_length(p_filters->'detectedTechnologies') > 0 THEN
    SELECT ARRAY(SELECT jsonb_array_elements_text(p_filters->'detectedTechnologies')) INTO v_detected_technologies;
  END IF;
  IF jsonb_typeof(p_filters->'excludedTechnologies') = 'array' AND jsonb_array_length(p_filters->'excludedTechnologies') > 0 THEN
    SELECT ARRAY(SELECT jsonb_array_elements_text(p_filters->'excludedTechnologies')) INTO v_excluded_technologies;
  END IF;
  IF jsonb_typeof(p_filters->'countries') = 'array' AND jsonb_array_length(p_filters->'countries') > 0 THEN
    SELECT ARRAY(SELECT LOWER(jsonb_array_elements_text(p_filters->'countries'))) INTO v_countries;
  END IF;
  IF jsonb_typeof(p_filters->'cities') = 'array' AND jsonb_array_length(p_filters->'cities') > 0 THEN
    SELECT ARRAY(SELECT LOWER(jsonb_array_elements_text(p_filters->'cities'))) INTO v_cities;
  END IF;
  IF jsonb_typeof(p_filters->'revenueModels') = 'array' AND jsonb_array_length(p_filters->'revenueModels') > 0 THEN
    SELECT ARRAY(SELECT LOWER(jsonb_array_elements_text(p_filters->'revenueModels'))) INTO v_revenue_models;
  END IF;
  IF jsonb_typeof(p_filters->'emailQuality') = 'array' AND jsonb_array_length(p_filters->'emailQuality') > 0 THEN
    SELECT ARRAY(SELECT jsonb_array_elements_text(p_filters->'emailQuality')) INTO v_email_quality;
  END IF;

  RETURN QUERY
  SELECT m.id, m.contact_id, m.added_at
  FROM public.lead_list_members m
  INNER JOIN public.crm_contacts c ON c.id = m.contact_id
  WHERE m.list_id = p_list_id
    AND (v_search IS NULL OR (
      c.display_name ILIKE '%' || v_search || '%'
      OR c.primary_email ILIKE '%' || v_search || '%'
      OR c.company ILIKE '%' || v_search || '%'
      OR c.job_title ILIKE '%' || v_search || '%'
    ))
    AND (v_icp_product_id IS NULL OR EXISTS (
      SELECT 1 FROM public.contact_product_scores cps
      WHERE cps.contact_id = c.id
        AND cps.product_id = v_icp_product_id
        AND cps.organization_id = v_org_id
        AND (v_min_icp_score IS NULL OR cps.icp_score >= v_min_icp_score)
        AND (v_max_icp_score IS NULL OR cps.icp_score <= v_max_icp_score)
        AND (v_min_dm_score IS NULL OR cps.decision_maker_score >= v_min_dm_score)
        AND (v_max_dm_score IS NULL OR cps.decision_maker_score <= v_max_dm_score)
    ))
    AND (v_industries IS NULL OR LOWER(c.enrichment_data->'company'->>'industry') = ANY(v_industries))
    AND (v_company_sizes IS NULL OR LOWER(c.enrichment_data->'company'->>'size') = ANY(v_company_sizes))
    AND (v_seniorities IS NULL OR LOWER(c.enrichment_data->>'seniority') = ANY(v_seniorities))
    AND (v_departments IS NULL OR LOWER(c.enrichment_data->>'department') = ANY(v_departments))
    AND (v_technologies IS NULL OR (c.enrichment_data->'company'->'technologies') @> to_jsonb(v_technologies))
    AND (v_detected_technologies IS NULL OR (
      CASE WHEN v_detected_tech_all
        THEN (c.enrichment_data->'detected_technologies'->'all') ?& v_detected_technologies
        ELSE (c.enrichment_data->'detected_technologies'->'all') ?| v_detected_technologies
      END))
    AND (v_excluded_technologies IS NULL OR NOT (COALESCE(c.enrichment_data->'detected_technologies'->'all', '[]'::jsonb) ?| v_excluded_technologies))
    AND (v_runs_ads IS NULL OR (c.enrichment_data->'detected_technologies'->>'runs_paid_ads')::BOOLEAN = v_runs_ads)
    AND (v_cq_question IS NULL OR EXISTS (
      SELECT 1 FROM jsonb_array_elements(COALESCE(c.enrichment_data->'custom_analysis', '[]'::jsonb)) e
      WHERE e->>'question' = v_cq_question
        AND COALESCE(TRIM(e->>'answer'), '') <> ''
        AND (v_cq_min_score IS NULL OR ((e->>'score') ~ '^-?[0-9]+(\.[0-9]+)?$' AND (e->>'score')::NUMERIC >= v_cq_min_score))
    ))
    AND (v_custom_questions IS NULL OR NOT EXISTS (
      SELECT 1 FROM jsonb_array_elements(v_custom_questions) cond
      WHERE NOT EXISTS (
        SELECT 1 FROM jsonb_array_elements(COALESCE(c.enrichment_data->'custom_analysis', '[]'::jsonb)) e
        WHERE e->>'question' = cond->>'question'
          AND COALESCE(TRIM(e->>'answer'), '') <> ''
          AND (NULLIF(cond->>'minScore','') IS NULL OR ((e->>'score') ~ '^-?[0-9]+(\.[0-9]+)?$' AND (e->>'score')::NUMERIC >= (cond->>'minScore')::NUMERIC))
      )
    ))
    AND (v_custom_fields IS NULL OR NOT EXISTS (
      SELECT 1 FROM jsonb_array_elements(v_custom_fields) cond
      WHERE NOT (
        CASE cond->>'operator'
          WHEN 'has_value' THEN c.custom_fields ? (cond->>'fieldKey')
            AND c.custom_fields->>(cond->>'fieldKey') IS DISTINCT FROM ''
          WHEN 'is_empty' THEN (NOT (c.custom_fields ? (cond->>'fieldKey')))
            OR c.custom_fields->>(cond->>'fieldKey') = ''
          WHEN 'equals' THEN c.custom_fields @> jsonb_build_object(cond->>'fieldKey', cond->>'value')
          WHEN 'contains' THEN c.custom_fields ? (cond->>'fieldKey')
            AND c.custom_fields->>(cond->>'fieldKey') ILIKE '%' || (cond->>'value') || '%'
          ELSE TRUE
        END
      )
    ))
    -- Native-column presence/match conditions. The allowlist lives in the inner
    -- CASE: an unrecognised field name resolves to NULL and therefore fails
    -- has_value / equals / contains and satisfies is_empty, rather than reaching
    -- the query planner as anything caller-controlled.
    AND (v_contact_fields IS NULL OR NOT EXISTS (
      SELECT 1 FROM jsonb_array_elements(v_contact_fields) cond
      WHERE NOT (
        CASE cond->>'operator'
          WHEN 'has_value' THEN COALESCE(TRIM(
            CASE cond->>'field'
              WHEN 'primary_email' THEN c.primary_email
              WHEN 'primary_phone' THEN c.primary_phone
              WHEN 'primary_linkedin_url' THEN c.primary_linkedin_url
              WHEN 'company' THEN c.company
              WHEN 'company_website' THEN c.company_website
              WHEN 'job_title' THEN c.job_title
              WHEN 'display_name' THEN c.display_name
              WHEN 'first_name' THEN c.first_name
              WHEN 'last_name' THEN c.last_name
              WHEN 'city' THEN c.city
              WHEN 'state' THEN c.state
              WHEN 'country' THEN c.country
              WHEN 'source' THEN c.source
              WHEN 'status' THEN c.status
              ELSE NULL
            END), '') <> ''
          WHEN 'is_empty' THEN COALESCE(TRIM(
            CASE cond->>'field'
              WHEN 'primary_email' THEN c.primary_email
              WHEN 'primary_phone' THEN c.primary_phone
              WHEN 'primary_linkedin_url' THEN c.primary_linkedin_url
              WHEN 'company' THEN c.company
              WHEN 'company_website' THEN c.company_website
              WHEN 'job_title' THEN c.job_title
              WHEN 'display_name' THEN c.display_name
              WHEN 'first_name' THEN c.first_name
              WHEN 'last_name' THEN c.last_name
              WHEN 'city' THEN c.city
              WHEN 'state' THEN c.state
              WHEN 'country' THEN c.country
              WHEN 'source' THEN c.source
              WHEN 'status' THEN c.status
              ELSE NULL
            END), '') = ''
          WHEN 'equals' THEN LOWER(COALESCE(
            CASE cond->>'field'
              WHEN 'primary_email' THEN c.primary_email
              WHEN 'primary_phone' THEN c.primary_phone
              WHEN 'primary_linkedin_url' THEN c.primary_linkedin_url
              WHEN 'company' THEN c.company
              WHEN 'company_website' THEN c.company_website
              WHEN 'job_title' THEN c.job_title
              WHEN 'display_name' THEN c.display_name
              WHEN 'first_name' THEN c.first_name
              WHEN 'last_name' THEN c.last_name
              WHEN 'city' THEN c.city
              WHEN 'state' THEN c.state
              WHEN 'country' THEN c.country
              WHEN 'source' THEN c.source
              WHEN 'status' THEN c.status
              ELSE NULL
            END, '')) = LOWER(COALESCE(cond->>'value', ''))
          WHEN 'contains' THEN COALESCE(
            CASE cond->>'field'
              WHEN 'primary_email' THEN c.primary_email
              WHEN 'primary_phone' THEN c.primary_phone
              WHEN 'primary_linkedin_url' THEN c.primary_linkedin_url
              WHEN 'company' THEN c.company
              WHEN 'company_website' THEN c.company_website
              WHEN 'job_title' THEN c.job_title
              WHEN 'display_name' THEN c.display_name
              WHEN 'first_name' THEN c.first_name
              WHEN 'last_name' THEN c.last_name
              WHEN 'city' THEN c.city
              WHEN 'state' THEN c.state
              WHEN 'country' THEN c.country
              WHEN 'source' THEN c.source
              WHEN 'status' THEN c.status
              ELSE NULL
            END, '') ILIKE '%' || COALESCE(cond->>'value', '') || '%'
          ELSE TRUE
        END
      )
    ))
    AND (v_email_verified IS NULL OR (c.enrichment_data->>'emailVerified')::BOOLEAN = v_email_verified)
    AND (v_email_quality IS NULL OR (
      ('clean' = ANY(v_email_quality) AND c.email_verified_at IS NOT NULL AND c.email_verification_status = 'valid'
        AND COALESCE(c.email_is_catch_all,false)=false AND COALESCE(c.email_is_role,false)=false AND COALESCE(c.email_is_free,false)=false
        AND COALESCE(c.email_is_disposable,false)=false AND COALESCE(c.email_is_spamtrap,false)=false)
      OR ('risky' = ANY(v_email_quality) AND c.email_verified_at IS NOT NULL AND
        (c.email_verification_status='catch_all' OR c.email_is_catch_all=true OR c.email_is_role=true OR c.email_is_free=true)
        AND COALESCE(c.email_is_disposable,false)=false AND COALESCE(c.email_is_spamtrap,false)=false)
      OR ('failed' = ANY(v_email_quality) AND c.email_verified_at IS NOT NULL AND
        (c.email_verification_status IN ('invalid','disposable','spamtrap','disabled','role_only') OR c.email_is_disposable=true OR c.email_is_spamtrap=true))
      OR ('unverified' = ANY(v_email_quality) AND c.email_verified_at IS NULL)
    ))
    AND (v_min_email_confidence IS NULL OR (c.enrichment_data->>'emailConfidence')::INTEGER >= v_min_email_confidence)
    AND (v_email_type IS NULL OR c.email_type = v_email_type)
    AND (v_has_email IS NULL
      OR (v_has_email = TRUE AND c.primary_email IS NOT NULL AND c.primary_email != '')
      OR (v_has_email = FALSE AND (c.primary_email IS NULL OR c.primary_email = '')))
    AND (v_countries IS NULL OR LOWER(c.country) = ANY(v_countries))
    AND (v_cities IS NULL OR LOWER(c.city) = ANY(v_cities))
    AND (v_has_enrichment_data IS NULL
      OR (v_has_enrichment_data = TRUE AND c.enrichment_data IS NOT NULL AND c.enrichment_data != '{}'::JSONB)
      OR (v_has_enrichment_data = FALSE AND (c.enrichment_data IS NULL OR c.enrichment_data = '{}'::JSONB)))
    AND (v_is_b2b IS NULL OR (c.enrichment_data->>'is_b2b')::BOOLEAN = v_is_b2b)
    AND (v_revenue_models IS NULL OR LOWER(c.enrichment_data->>'revenue_model') = ANY(v_revenue_models))
    AND (v_has_outbound_motion IS NULL OR (c.enrichment_data->>'has_outbound_motion')::BOOLEAN = v_has_outbound_motion)
    AND (v_hiring_sales_roles IS NULL OR (c.enrichment_data->>'hiring_sales_roles')::BOOLEAN = v_hiring_sales_roles)
    AND (v_has_notion_url IS NULL
      OR (v_has_notion_url = TRUE AND c.notion_preview_url IS NOT NULL AND c.notion_preview_url != '')
      OR (v_has_notion_url = FALSE AND (c.notion_preview_url IS NULL OR c.notion_preview_url = '')))
    AND (v_seg_firewall IS NULL
      OR (v_seg_firewall = 'behind' AND c.seg_provider IS NOT NULL)
      OR (v_seg_firewall = 'clear' AND c.seg_provider IS NULL AND c.seg_checked_at IS NOT NULL)
      OR (v_seg_firewall = 'unchecked' AND c.seg_checked_at IS NULL))
    AND (v_ai_analysis_status IS NULL
      OR (v_ai_analysis_status = 'no_data' AND (
            c.ai_analysis_status = 'failed'
            OR ((c.company_website IS NULL OR c.company_website = '')
              AND (c.primary_linkedin_url IS NULL OR c.primary_linkedin_url = ''))))
      OR (v_ai_analysis_status != 'no_data' AND c.ai_analysis_status = v_ai_analysis_status))
  ORDER BY m.added_at DESC, m.id DESC
  LIMIT p_limit OFFSET COALESCE(p_offset, 0);
END;
$_$;


ALTER FUNCTION "public"."filter_lead_list_member_rows_legacy"("p_list_id" "uuid", "p_filters" "jsonb", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."filter_lead_list_member_rows_legacy"("p_list_id" "uuid", "p_filters" "jsonb", "p_limit" integer, "p_offset" integer) IS 'Advanced Filters predicate core for lead-list members. Backs filter_lead_list_members and get_filtered_lead_list_member_ids, and the /v1/lists/members REST filters. contactFieldConditions matches native crm_contacts columns against a fixed allowlist; customFieldConditions does the same for custom_fields keys.';



CREATE OR REPLACE FUNCTION "public"."filter_lead_list_members"("p_list_id" "uuid", "p_filters" "jsonb" DEFAULT '{}'::"jsonb", "p_page" integer DEFAULT 1, "p_page_size" integer DEFAULT 50) RETURNS TABLE("members" "jsonb", "total_count" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    SET "statement_timeout" TO '55s'
    AS $$
DECLARE
  v_page_ids UUID[];
  v_offset INTEGER;
  v_result JSONB;
BEGIN
  v_offset := GREATEST(p_page - 1, 0) * p_page_size;

  SELECT ARRAY(
    SELECT r.member_id
    FROM public.filter_lead_list_member_rows(p_list_id, p_filters, p_page_size, v_offset) r
  ) INTO v_page_ids;

  SELECT COALESCE(jsonb_agg(to_jsonb(sub)), '[]'::JSONB) INTO v_result
  FROM (
    SELECT
      m.id AS member_id,
      m.list_id,
      m.contact_id,
      m.added_at,
      m.source_data,
      jsonb_build_object(
        'id', c.id,
        'display_name', c.display_name,
        'first_name', c.first_name,
        'last_name', c.last_name,
        'company', c.company,
        'job_title', c.job_title,
        'primary_email', c.primary_email,
        'primary_linkedin_url', c.primary_linkedin_url,
        'avatar_url', c.avatar_url,
        'lead_score', c.lead_score,
        'company_website', c.company_website,
        'primary_phone', c.primary_phone,
        'city', c.city,
        'state', c.state,
        'country', c.country,
        'tags', c.tags,
        'source', c.source,
        'status', c.status,
        'outreach_status', c.outreach_status,
        'ai_analysis_status', c.ai_analysis_status,
        'enrichment_data', c.enrichment_data,
        'seg_provider', c.seg_provider,
        'seg_checked_at', c.seg_checked_at,
        'notion_preview_url', c.notion_preview_url,
        'notion_page_id', c.notion_page_id,
        'identities', COALESCE((
          SELECT jsonb_agg(jsonb_build_object(
            'id', ci.id,
            'channel', ci.channel,
            'platform_user_id', ci.platform_user_id,
            'platform_avatar_url', ci.platform_avatar_url
          ))
          FROM public.crm_contact_identities ci
          WHERE ci.contact_id = c.id
        ), '[]'::JSONB)
      ) AS contact
    FROM public.lead_list_members m
    INNER JOIN public.crm_contacts c ON c.id = m.contact_id
    WHERE m.id = ANY(v_page_ids)
    ORDER BY m.added_at DESC, m.id DESC
  ) sub;

  RETURN QUERY SELECT v_result, NULL::BIGINT;
END;
$$;


ALTER FUNCTION "public"."filter_lead_list_members"("p_list_id" "uuid", "p_filters" "jsonb", "p_page" integer, "p_page_size" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."finalize_mailtester_tick"("p_job_id" "uuid", "p_token" "uuid", "p_processed_emails" "text"[], "p_valid_delta" integer, "p_invalid_delta" integer, "p_catch_all_delta" integer, "p_unknown_delta" integer, "p_daily_limit_reached" boolean) RETURNS TABLE("applied" boolean, "pending_after" integer, "status" "text")
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_pending     text[];
  v_new_pending text[];
  v_removed     int;
  v_status      text;
BEGIN
  SELECT j.pending_emails INTO v_pending
    FROM public.mailtester_verification_jobs j
   WHERE j.id = p_job_id
     AND j.locked_by = p_token
     AND j.status IN ('queued','running')
   FOR UPDATE;

  IF NOT FOUND THEN
    RETURN QUERY SELECT FALSE, NULL::int, NULL::text;
    RETURN;
  END IF;

  SELECT COALESCE(array_agg(e), '{}')
    INTO v_new_pending
    FROM unnest(COALESCE(v_pending, '{}'::text[])) AS e
   WHERE lower(e) <> ALL (
     SELECT lower(x) FROM unnest(COALESCE(p_processed_emails, '{}'::text[])) AS x
   );

  v_removed := COALESCE(array_length(v_pending, 1), 0)
             - COALESCE(array_length(v_new_pending, 1), 0);
  v_status  := CASE WHEN COALESCE(array_length(v_new_pending, 1), 0) = 0
                    THEN 'succeeded' ELSE 'running' END;

  UPDATE public.mailtester_verification_jobs j
     SET pending_emails      = v_new_pending,
         processed           = j.processed + GREATEST(v_removed, 0),
         valid               = j.valid + p_valid_delta,
         invalid             = j.invalid + p_invalid_delta,
         catch_all           = j.catch_all + p_catch_all_delta,
         unknown             = j.unknown + p_unknown_delta,
         daily_limit_reached = p_daily_limit_reached,
         status              = v_status,
         finished_at         = CASE WHEN v_status = 'succeeded' THEN now() ELSE NULL END,
         last_tick_at        = now()
   WHERE j.id = p_job_id
     AND j.locked_by = p_token;

  RETURN QUERY SELECT TRUE, COALESCE(array_length(v_new_pending, 1), 0), v_status;
END;
$$;


ALTER FUNCTION "public"."finalize_mailtester_tick"("p_job_id" "uuid", "p_token" "uuid", "p_processed_emails" "text"[], "p_valid_delta" integer, "p_invalid_delta" integer, "p_catch_all_delta" integer, "p_unknown_delta" integer, "p_daily_limit_reached" boolean) OWNER TO "postgres";


