CREATE OR REPLACE FUNCTION "public"."find_keyword_excluded_conversations"("p_org_id" "uuid", "p_keywords" "text"[]) RETURNS TABLE("conversation_id" "uuid")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  predicate_sql text;
  query_sql text;
BEGIN
  IF auth.uid() IS NOT NULL AND NOT EXISTS (
    SELECT 1
    FROM public.organization_members membership
    WHERE membership.organization_id = p_org_id
      AND membership.user_id = auth.uid()
  ) THEN
    RAISE EXCEPTION 'Not a member of this organization';
  END IF;

  IF auth.uid() IS NULL
     AND auth.role() IS DISTINCT FROM 'service_role'
     AND session_user NOT IN ('postgres', 'supabase_admin') THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  -- Literal patterns let PostgreSQL use the composite org + trigram indexes.
  -- format(%L) quotes every value, so user keywords cannot become SQL.
  SELECT string_agg(
    format(
      'message.content ILIKE %L OR message.email_subject ILIKE %L',
      '%' || keyword || '%',
      '%' || keyword || '%'
    ),
    ' OR '
  )
  INTO predicate_sql
  FROM unnest(COALESCE(p_keywords, ARRAY[]::text[])) AS keyword
  WHERE BTRIM(keyword) <> '';

  IF predicate_sql IS NULL THEN
    RETURN;
  END IF;

  query_sql := format($query$
    SELECT DISTINCT message.conversation_id
    FROM public.crm_messages message
    WHERE message.organization_id = %L
      AND message.direction = 'inbound'
      AND (%s)
  $query$, p_org_id, predicate_sql);

  RETURN QUERY EXECUTE query_sql;
END;
$_$;


ALTER FUNCTION "public"."find_keyword_excluded_conversations"("p_org_id" "uuid", "p_keywords" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."finish_signal_company_lookup"("p_provider" "text", "p_name" "text", "p_country" "text", "p_token" "uuid", "p_outcome" "text", "p_credits" integer DEFAULT 0) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE affected integer;
BEGIN
  IF p_outcome NOT IN ('matched','not_found','ambiguous','unavailable') OR p_credits < 0 THEN
    RAISE EXCEPTION 'invalid lookup outcome';
  END IF;
  UPDATE public.signal_company_lookup_cache SET outcome=p_outcome,
    attempts=CASE WHEN p_outcome='unavailable' THEN greatest(attempts-1,0) ELSE attempts END,
    last_attempt_at=CASE WHEN p_outcome='unavailable' THEN NULL ELSE last_attempt_at END,
    lease_until=NULL,lease_token=NULL,credits_used=credits_used+p_credits
    WHERE provider=p_provider AND name_normalized=p_name AND country_code=coalesce(p_country,'')
      AND lease_token=p_token;
  GET DIAGNOSTICS affected = ROW_COUNT;
  RETURN affected=1;
END;
$$;


ALTER FUNCTION "public"."finish_signal_company_lookup"("p_provider" "text", "p_name" "text", "p_country" "text", "p_token" "uuid", "p_outcome" "text", "p_credits" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_slug_to_label"("slug" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $$
