CREATE OR REPLACE FUNCTION "public"."gate_native_signal_list_persona"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_persona text;
  v_company text;
  v_cap integer;
  v_count integer;
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.lead_lists l
    WHERE l.id = NEW.list_id
      AND l.organization_id = public.aca_house_org_id()
      AND l.name = 'Fresh ACA-Native Signal Decision Makers — QuickEnrich'
  ) OR coalesce(NEW.source_data->>'provider', '') <> 'quickenrich' THEN
    RETURN NEW;
  END IF;

  SELECT public.signal_buyer_persona(c.job_title), lower(btrim(c.company))
  INTO v_persona, v_company
  FROM public.crm_contacts c
  WHERE c.id = NEW.contact_id;
  IF v_persona IS NULL THEN RETURN NULL; END IF;
  v_cap := CASE WHEN v_persona = 'executive' THEN 2 ELSE 1 END;

  SELECT count(*) INTO v_count
  FROM public.lead_list_members existing
  JOIN public.crm_contacts c ON c.id = existing.contact_id
  WHERE existing.list_id = NEW.list_id
    AND lower(btrim(c.company)) = v_company
    AND public.signal_buyer_persona(c.job_title) = v_persona;
  IF v_count >= v_cap THEN RETURN NULL; END IF;
  NEW.source_data := coalesce(NEW.source_data, '{}'::jsonb)
    || jsonb_build_object('outreach_persona', v_persona, 'persona_policy_version', 2);
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."gate_native_signal_list_persona"() OWNER TO "postgres";


