CREATE OR REPLACE FUNCTION "public"."get_accessible_organization_ids"() RETURNS SETOF "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  current_org_id uuid;
  current_user_id uuid;  -- Renamed from 'user_id' to avoid ambiguity
BEGIN
  -- Get authenticated user ID
  current_user_id := auth.uid();

  -- Get user's effective organization (handles impersonation)
  current_org_id := get_user_organization_id();

  -- Always return current org
  RETURN NEXT current_org_id;

  -- If user is admin/owner of an agency, also return child orgs
  IF EXISTS (
    SELECT 1
    FROM public.organization_members om
    JOIN public.organizations o ON o.id = om.organization_id
    WHERE om.user_id = current_user_id  -- Now unambiguous
      AND om.organization_id = current_org_id
      AND om.role IN ('owner', 'admin')
      AND o.type = 'agency'
  ) THEN
    -- Return all client organizations under this agency
    RETURN QUERY
      SELECT id
      FROM public.organizations
      WHERE parent_id = current_org_id
        AND status = 'active';
  END IF;

  RETURN;
END;
$$;


ALTER FUNCTION "public"."get_accessible_organization_ids"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_accessible_organization_ids"() IS 'Returns all organization IDs the current user can access.
For agency admins/owners, this includes their own org plus all client organizations.
For regular users, this returns only their current organization.
Respects impersonation via get_user_organization_id().';



CREATE OR REPLACE FUNCTION "public"."get_admin_action_logs"("p_organization_id" "uuid" DEFAULT NULL::"uuid", "p_action_type" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 100) RETURNS TABLE("id" "uuid", "admin_user_id" "uuid", "admin_email" "text", "admin_name" "text", "target_organization_id" "uuid", "target_organization_name" "text", "action_type" "text", "previous_value" "jsonb", "new_value" "jsonb", "notes" "text", "created_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  -- Only allow super admins to call this function
  IF NOT is_super_admin(auth.uid()) THEN
    RAISE EXCEPTION 'Access denied: Super admin required';
  END IF;

  RETURN QUERY
  SELECT
    l.id,
    l.admin_user_id,
    u.email::TEXT as admin_email,
    u.full_name::TEXT as admin_name,
    l.target_organization_id,
    l.target_organization_name::TEXT,
    l.action_type::TEXT,
    l.previous_value,
    l.new_value,
    l.notes::TEXT,
    l.created_at
  FROM public.admin_action_logs l
  JOIN public.users u ON u.id = l.admin_user_id
  WHERE
    (p_organization_id IS NULL OR l.target_organization_id = p_organization_id)
    AND (p_action_type IS NULL OR l.action_type = p_action_type)
  ORDER BY l.created_at DESC
  LIMIT p_limit;
END;
$$;


ALTER FUNCTION "public"."get_admin_action_logs"("p_organization_id" "uuid", "p_action_type" "text", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_agency_clients_with_metrics"("p_agency_id" "uuid") RETURNS TABLE("id" "uuid", "name" "text", "slug" "text", "status" "text", "created_at" timestamp with time zone, "parent_id" "uuid", "logo_url" "text", "user_count" bigint, "content_count" bigint, "jobs_count" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  -- Verify the calling user has access to the agency
  IF NOT (
    auth.uid() IN (
      SELECT om.user_id FROM organization_members om WHERE om.organization_id = p_agency_id
    )
    OR EXISTS (
      SELECT 1 FROM users u WHERE u.id = auth.uid() AND p_agency_id = ANY(u.can_access_organizations)
    )
    OR is_super_admin(auth.uid())
  ) THEN
    RAISE EXCEPTION 'Access denied: You do not have access to this organization';
  END IF;

  RETURN QUERY
  SELECT
    o.id,
    o.name::TEXT,
    o.slug::TEXT,
    o.status::TEXT,
    o.created_at,
    o.parent_id,
    o.logo_url::TEXT,
    (SELECT COUNT(*) FROM organization_members om WHERE om.organization_id = o.id)::BIGINT as user_count,
    (SELECT COUNT(*) FROM content_outputs co WHERE co.organization_id = o.id)::BIGINT as content_count,
    (SELECT COUNT(*) FROM content_generation_jobs cgj WHERE cgj.organization_id = o.id)::BIGINT as jobs_count
  FROM organizations o
  WHERE o.parent_id = p_agency_id
  ORDER BY o.created_at DESC;
END;
$$;


ALTER FUNCTION "public"."get_agency_clients_with_metrics"("p_agency_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_all_organizations_with_metrics"("p_type_filter" "text" DEFAULT NULL::"text", "p_status_filter" "text" DEFAULT NULL::"text", "p_plan_filter" "text" DEFAULT NULL::"text", "p_search" "text" DEFAULT NULL::"text", "p_include_suspended" boolean DEFAULT true) RETURNS TABLE("id" "uuid", "name" "text", "slug" "text", "type" "text", "status" "text", "plan_tier" "text", "is_suspended" boolean, "suspended_at" timestamp with time zone, "suspension_reason" "text", "parent_id" "uuid", "parent_name" "text", "created_at" timestamp with time zone, "user_count" bigint, "content_count" bigint, "jobs_count" bigint, "api_key_count" bigint, "owner_email" "text", "logo_url" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  -- Only allow super admins to call this function
  IF NOT is_super_admin(auth.uid()) THEN
    RAISE EXCEPTION 'Access denied: Super admin required';
  END IF;

  RETURN QUERY
  SELECT
    o.id,
    o.name::TEXT,
    o.slug::TEXT,
    o.type::TEXT,
    o.status::TEXT,
    COALESCE(o.plan_tier, 'free')::TEXT,
    COALESCE(o.is_suspended, false),
    o.suspended_at,
    o.suspension_reason::TEXT,
    o.parent_id,
    parent_org.name::TEXT as parent_name,
    o.created_at,
    (SELECT COUNT(*) FROM organization_members om WHERE om.organization_id = o.id)::BIGINT as user_count,
    (SELECT COUNT(*) FROM content_outputs co WHERE co.organization_id = o.id)::BIGINT as content_count,
    (SELECT COUNT(*) FROM content_generation_jobs cgj WHERE cgj.organization_id = o.id)::BIGINT as jobs_count,
    (SELECT COUNT(*) FROM api_keys ak WHERE ak.organization_id = o.id)::BIGINT as api_key_count,
    (SELECT u.email FROM users u
     JOIN organization_members om ON om.user_id = u.id
     WHERE om.organization_id = o.id AND om.is_primary_owner = true
     LIMIT 1)::TEXT as owner_email,
    o.logo_url::TEXT
  FROM organizations o
  LEFT JOIN organizations parent_org ON parent_org.id = o.parent_id
  WHERE
    (p_type_filter IS NULL OR o.type = p_type_filter)
    AND (p_status_filter IS NULL OR o.status = p_status_filter)
    AND (p_plan_filter IS NULL OR COALESCE(o.plan_tier, 'free') = p_plan_filter)
    AND (p_include_suspended OR COALESCE(o.is_suspended, false) = false)
    AND (p_search IS NULL OR
         o.name ILIKE '%' || p_search || '%' OR
         o.slug ILIKE '%' || p_search || '%')
  ORDER BY o.created_at DESC;
END;
$$;


ALTER FUNCTION "public"."get_all_organizations_with_metrics"("p_type_filter" "text", "p_status_filter" "text", "p_plan_filter" "text", "p_search" "text", "p_include_suspended" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_autopilot_fuel"("p_organization_id" "uuid") RETURNS TABLE("autopilot_id" "uuid", "name" "text", "status" "text", "paused_reason" "text", "entries" "jsonb", "feed_tags" "text"[], "draws_from_all" boolean, "matching_ideas" integer, "fresh_ideas" integer, "posts_per_day" numeric, "runway_days" numeric, "recycles" boolean, "last_output_at" timestamp with time zone, "starving_since" timestamp with time zone, "starved_runs_7d" integer, "awaiting_review" integer)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  WITH ap AS (
    SELECT a.*
    FROM public.autopilots a
    WHERE a.organization_id = p_organization_id
  ),
  org_tags AS (
    SELECT t.id, lower(t.name) AS lname
    FROM public.idea_tags t
    WHERE t.organization_id = p_organization_id
  ),
  entries AS (
    SELECT
      ap.id AS autopilot_id,
      e.blueprint_id,
      e.tags,
      ARRAY(SELECT ot.id FROM org_tags ot WHERE ot.lname IN (SELECT lower(x) FROM unnest(e.tags) x)) AS tag_ids
    FROM ap
    CROSS JOIN LATERAL public.autopilot_feed_entries(ap.ideas_source, ap.shared_idea_tags, ap.content_mix) e
  ),
  entry_summary AS (
    SELECT
      e.autopilot_id,
      jsonb_agg(jsonb_build_object(
        'blueprint_id', e.blueprint_id,
        'tags', to_jsonb(e.tags),
        'draws_from_all', cardinality(e.tag_ids) = 0
      )) AS entries,
      bool_or(cardinality(e.tag_ids) = 0) AS draws_from_all
    FROM entries e
    GROUP BY e.autopilot_id
  ),
  tag_summary AS (
    SELECT e.autopilot_id, array_agg(DISTINCT t ORDER BY t) AS feed_tags
    FROM entries e, unnest(e.tags) t
    GROUP BY e.autopilot_id
  ),
  tagged AS (
    SELECT DISTINCT
      e.autopilot_id,
      i.id AS idea_id,
      (NOT coalesce(ap.only_approved_ideas, false) OR i.guidelines_approved_at IS NOT NULL) AS postable
    FROM entries e
    JOIN ap ON ap.id = e.autopilot_id
    JOIN public.content_ideas i ON i.organization_id = p_organization_id
    WHERE NOT EXISTS (
            SELECT 1 FROM public.autopilot_idea_exclusions ex
            WHERE ex.autopilot_id = e.autopilot_id AND ex.idea_id = i.id
          )
      AND (
        cardinality(e.tag_ids) = 0
        OR EXISTS (
          SELECT 1 FROM public.idea_tag_assignments x
          WHERE x.idea_id = i.id AND x.tag_id = ANY (e.tag_ids)
        )
      )
  ),
  used AS (
    SELECT DISTINCT co.autopilot_id, co.idea_id
    FROM public.content_outputs co
    WHERE co.organization_id = p_organization_id
      AND co.autopilot_id IS NOT NULL
      AND co.idea_id IS NOT NULL
  ),
  counts AS (
    SELECT
      m.autopilot_id,
      count(*) FILTER (WHERE m.postable)::int AS matching,
      count(*) FILTER (
        WHERE m.postable
          AND NOT EXISTS (SELECT 1 FROM used u WHERE u.autopilot_id = m.autopilot_id AND u.idea_id = m.idea_id)
      )::int AS fresh,
      count(*) FILTER (WHERE NOT m.postable)::int AS awaiting_review
    FROM tagged m
    GROUP BY m.autopilot_id
  ),
  last_output AS (
    SELECT co.autopilot_id, max(co.created_at) AS at
    FROM public.content_outputs co
    WHERE co.organization_id = p_organization_id AND co.autopilot_id IS NOT NULL
    GROUP BY co.autopilot_id
  ),
  last_start AS (
    SELECT l.autopilot_id, max(l.created_at) AS at
    FROM public.automation_logs l
    WHERE l.autopilot_id IN (SELECT id FROM ap)
      AND l.event_type = 'generation_started'
      AND l.created_at > now() - interval '90 days'
    GROUP BY l.autopilot_id
  ),
  starving AS (
    SELECT
      l.autopilot_id,
      min(l.created_at) FILTER (WHERE l.created_at > coalesce(ls.at, '-infinity'::timestamptz)) AS since,
      count(*) FILTER (WHERE l.created_at > now() - interval '7 days')::int AS runs_7d
    FROM public.automation_logs l
    LEFT JOIN last_start ls ON ls.autopilot_id = l.autopilot_id
    WHERE l.autopilot_id IN (SELECT id FROM ap)
      AND l.event_type = 'no_ideas_available'
      AND l.created_at > now() - interval '90 days'
    GROUP BY l.autopilot_id
  ),
  cadence AS (
    SELECT
      ap.id AS autopilot_id,
      CASE
        WHEN ap.scheduling_mode = 'scheduled'
             AND jsonb_typeof(ap.schedule_slots) = 'array'
             AND jsonb_array_length(ap.schedule_slots) > 0 THEN
          jsonb_array_length(ap.schedule_slots) / 7.0
        WHEN ap.scheduling_mode = 'scheduled' AND cardinality(coalesce(ap.scheduled_times, '{}'::text[])) > 0 THEN
          cardinality(ap.scheduled_times)
            * (CASE WHEN cardinality(coalesce(ap.scheduled_days, '{}'::smallint[])) > 0
                    THEN cardinality(ap.scheduled_days) ELSE 7 END)
            / 7.0
        WHEN coalesce((ap.frequency->>'amount')::numeric, 0) > 0 THEN
          CASE ap.frequency->>'unit'
            WHEN 'hour' THEN 24 / (ap.frequency->>'amount')::numeric
            WHEN 'day' THEN 1 / (ap.frequency->>'amount')::numeric
            WHEN 'week' THEN 1 / (7 * (ap.frequency->>'amount')::numeric)
          END
      END AS per_day
    FROM ap
  )
  SELECT
    ap.id,
    ap.name,
    ap.status,
    ap.paused_reason,
    coalesce(es.entries, '[]'::jsonb),
    coalesce(ts.feed_tags, '{}'::text[]),
    coalesce(es.draws_from_all, false),
    coalesce(c.matching, 0),
    coalesce(c.fresh, 0),
    round(cd.per_day, 2),
    CASE WHEN cd.per_day > 0 THEN round(coalesce(c.fresh, 0) / cd.per_day, 1) END,
    coalesce(ap.auto_reload_pool, false),
    lo.at,
    s.since,
    coalesce(s.runs_7d, 0),
    coalesce(c.awaiting_review, 0)
  FROM ap
  LEFT JOIN entry_summary es ON es.autopilot_id = ap.id
  LEFT JOIN tag_summary ts ON ts.autopilot_id = ap.id
  LEFT JOIN counts c ON c.autopilot_id = ap.id
  LEFT JOIN last_output lo ON lo.autopilot_id = ap.id
  LEFT JOIN starving s ON s.autopilot_id = ap.id
  LEFT JOIN cadence cd ON cd.autopilot_id = ap.id
  ORDER BY ap.name;
$$;


ALTER FUNCTION "public"."get_autopilot_fuel"("p_organization_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_batch_progress"("batch_uuid" "uuid") RETURNS TABLE("batch_id" "uuid", "batch_size" integer, "completed" integer, "failed" integer, "in_progress" integer, "progress_percentage" numeric)
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    b.id,
    b.batch_size,
    b.completed_count,
    b.failed_count,
    b.batch_size - b.completed_count - b.failed_count AS in_progress,
    ROUND((b.completed_count::DECIMAL / NULLIF(b.batch_size, 0)) * 100, 2) AS progress_percentage
  FROM content_batches b
  WHERE b.id = batch_uuid;
END;
$$;


ALTER FUNCTION "public"."get_batch_progress"("batch_uuid" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_blueprint_latest_samples"("p_organization_id" "uuid") RETURNS TABLE("blueprint_id" "uuid", "output_id" "uuid", "pipeline" "text", "created_at" timestamp with time zone, "title" "text", "text_snippet" "text", "image_url" "text")
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  WITH latest AS (
    SELECT DISTINCT ON (c.blueprint_id) c.id
    FROM public.content_outputs c
    WHERE c.organization_id = p_organization_id
      AND c.blueprint_id IS NOT NULL
      AND c.status <> 'failed'
    ORDER BY c.blueprint_id, c.created_at DESC
  )
  SELECT
    co.blueprint_id,
    co.id AS output_id,
    co.pipeline,
    co.created_at,
    co.data->>'title' AS title,
    left(
      COALESCE(
        co.stage_data->'caption'->>'content',
        co.data->>'text',
        co.stage_data->'text'->>'content',
        co.stage_data->'thread_tweets'->>'content'
      ),
      400
    ) AS text_snippet,
    COALESCE(
      co.stage_data->'image'->>'url',
      co.stage_data->'image'->>'image_url',
      co.stage_data->'carousel_slides'->'slides'->0->>'image_url',
      co.stage_data->'manual_image'->>'url'
    ) AS image_url
  FROM latest
  JOIN public.content_outputs co ON co.id = latest.id;
$$;


ALTER FUNCTION "public"."get_blueprint_latest_samples"("p_organization_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_blueprint_run_stats"("p_organization_id" "uuid") RETURNS TABLE("blueprint_id" "uuid", "runs" bigint, "succeeded" bigint, "failed" bigint, "in_progress" bigint, "last_run_at" timestamp with time zone, "last_success_at" timestamp with time zone, "last_status" "text", "last_error" "text", "failed_in_last_two" integer)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  WITH j AS (
    SELECT
      cgj.blueprint_id,
      cgj.status,
      cgj.created_at,
      cgj.error,
      row_number() OVER (PARTITION BY cgj.blueprint_id ORDER BY cgj.created_at DESC) AS rn
    FROM public.content_generation_jobs cgj
    WHERE cgj.organization_id = p_organization_id
      AND cgj.blueprint_id IS NOT NULL
      AND COALESCE(cgj.is_demo, false) = false
  )
  SELECT
    j.blueprint_id,
    count(*) AS runs,
    count(*) FILTER (WHERE j.status = 'completed') AS succeeded,
    count(*) FILTER (WHERE j.status = 'failed') AS failed,
    count(*) FILTER (WHERE j.status IN ('queued', 'processing') AND j.created_at > now() - interval '2 hours') AS in_progress,
    max(j.created_at) AS last_run_at,
    max(j.created_at) FILTER (WHERE j.status = 'completed') AS last_success_at,
    max(j.status) FILTER (WHERE j.rn = 1) AS last_status,
    max(j.error) FILTER (WHERE j.rn = 1) AS last_error,
    (count(*) FILTER (WHERE j.rn <= 2 AND j.status = 'failed'))::integer AS failed_in_last_two
  FROM j
  GROUP BY j.blueprint_id;
$$;


ALTER FUNCTION "public"."get_blueprint_run_stats"("p_organization_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_branding_by_domain"("p_domain" "text") RETURNS TABLE("organization_id" "uuid", "organization_slug" "text", "app_name" "text", "tagline" "text", "logo_url" "text", "logo_dark_url" "text", "favicon_url" "text", "og_image_url" "text", "primary_color" "jsonb", "cta_color" "jsonb", "accent_color" "jsonb", "meta_title" "text", "meta_description" "text", "twitter_handle" "text", "support_email" "text", "support_url" "text", "footer_text" "text", "terms_url" "text", "privacy_url" "text", "hide_powered_by" boolean, "custom_css" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    o.id as organization_id,
    o.slug::TEXT as organization_slug,
    COALESCE(b.app_name, 'ACA')::TEXT,
    b.tagline::TEXT,
    b.logo_url::TEXT,
    b.logo_dark_url::TEXT,
    b.favicon_url::TEXT,
    b.og_image_url::TEXT,
    COALESCE(b.primary_color, '{"h": 1, "s": 70, "l": 54}'::jsonb),
    COALESCE(b.cta_color, '{"h": 43, "s": 80, "l": 72}'::jsonb),
    COALESCE(b.accent_color, '{"h": 40, "s": 15, "l": 94}'::jsonb),
    b.meta_title::TEXT,
    b.meta_description::TEXT,
    b.twitter_handle::TEXT,
    b.support_email::TEXT,
    b.support_url::TEXT,
    b.footer_text::TEXT,
    b.terms_url::TEXT,
    b.privacy_url::TEXT,
    COALESCE(b.hide_powered_by, false),
    b.custom_css::TEXT
  FROM organization_domains d
  JOIN organizations o ON o.id = d.organization_id
  LEFT JOIN organization_branding b ON b.organization_id = o.id
  WHERE LOWER(d.domain) = LOWER(p_domain)
    AND d.verification_status = 'verified'
    AND o.is_white_labeled = true
  LIMIT 1;
END;
$$;


ALTER FUNCTION "public"."get_branding_by_domain"("p_domain" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_bulk_job_summary"("job_uuid" "uuid") RETURNS TABLE("job_id" "uuid", "job_name" "text", "total_count" integer, "pending_count" integer, "generating_count" integer, "completed_count" integer, "failed_count" integer, "cancelled_count" integer, "avg_generation_time_ms" integer, "total_cost" numeric)
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    j.id AS job_id,
    j.name AS job_name,
    j.total_count,
    COUNT(*) FILTER (WHERE i.status = 'pending')::INTEGER AS pending_count,
    COUNT(*) FILTER (WHERE i.status IN ('queued', 'generating'))::INTEGER AS generating_count,
    COUNT(*) FILTER (WHERE i.status = 'completed')::INTEGER AS completed_count,
    COUNT(*) FILTER (WHERE i.status = 'failed')::INTEGER AS failed_count,
    COUNT(*) FILTER (WHERE i.status = 'cancelled')::INTEGER AS cancelled_count,
    AVG(i.generation_duration_ms) FILTER (WHERE i.status = 'completed')::INTEGER AS avg_generation_time_ms,
    COALESCE(SUM(i.generation_cost), 0) AS total_cost
  FROM bulk_generation_jobs j
  LEFT JOIN bulk_generation_items i ON i.job_id = j.id
  WHERE j.id = job_uuid
  GROUP BY j.id, j.name, j.total_count;
END;
$$;


ALTER FUNCTION "public"."get_bulk_job_summary"("job_uuid" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_bulk_job_summary"("job_uuid" "uuid") IS 'Get comprehensive summary of a bulk generation job with status counts and metrics';



CREATE OR REPLACE FUNCTION "public"."get_channel_limits_summary"("p_organization_id" "uuid", "p_date_range_days" integer DEFAULT 7) RETURNS TABLE("channel" "public"."crm_channel_type", "display_name" "text", "description" "text", "icon" "text", "logo_url" "text", "brand_color" "text", "is_enabled" boolean, "current_zone" "public"."limit_zone", "daily_limit" integer, "today_used" integer, "today_remaining" integer, "usage_percent" numeric, "warmup_status" "public"."warmup_status", "warmup_progress" integer, "avg_daily_usage" numeric, "total_sent_period" integer, "total_delivered_period" integer, "total_failed_period" integer, "reply_rate" numeric)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_def RECORD;
    v_org_limit RECORD;
    v_today_used INTEGER;
    v_daily_limit INTEGER;
BEGIN
    FOR v_def IN SELECT * FROM channel_limit_definitions ORDER BY channel_limit_definitions.display_name
    LOOP
        SELECT * INTO v_org_limit
        FROM organization_channel_limits ocl
        WHERE ocl.organization_id = p_organization_id
          AND ocl.channel = v_def.channel
          AND ocl.channel_account_id IS NULL;

        SELECT COALESCE(SUM(cut.messages_sent), 0)::INTEGER INTO v_today_used
        FROM channel_usage_tracking cut
        WHERE cut.organization_id = p_organization_id
          AND cut.channel = v_def.channel
          AND cut.period_date = CURRENT_DATE
          AND cut.period_hour IS NULL;

        v_daily_limit := get_effective_daily_limit(p_organization_id, v_def.channel, NULL);

        channel := v_def.channel;
        display_name := v_def.display_name;
        description := v_def.description;
        icon := v_def.icon;
        logo_url := v_def.logo_url;
        brand_color := v_def.brand_color;
        is_enabled := COALESCE(v_org_limit.is_enabled, true);
        current_zone := COALESCE(v_org_limit.current_zone, 'safe'::limit_zone);
        daily_limit := v_daily_limit;
        today_used := v_today_used;
        today_remaining := v_daily_limit - v_today_used;
        usage_percent := CASE WHEN v_daily_limit > 0 THEN (v_today_used::DECIMAL / v_daily_limit) * 100 ELSE 0 END;
        warmup_status := COALESCE(v_org_limit.warmup_status, 'not_started'::warmup_status);
        warmup_progress := COALESCE(v_org_limit.warmup_progress_percent, 0);

        SELECT COALESCE(AVG(cut.messages_sent), 0) INTO avg_daily_usage
        FROM channel_usage_tracking cut
        WHERE cut.organization_id = p_organization_id
          AND cut.channel = v_def.channel
          AND cut.period_date >= CURRENT_DATE - p_date_range_days
          AND cut.period_hour IS NULL;

        SELECT COALESCE(SUM(cut.messages_sent), 0)::INTEGER INTO total_sent_period
        FROM channel_usage_tracking cut
        WHERE cut.organization_id = p_organization_id
          AND cut.channel = v_def.channel
          AND cut.period_date >= CURRENT_DATE - p_date_range_days
          AND cut.period_hour IS NULL;

        SELECT COALESCE(SUM(cut.messages_delivered), 0)::INTEGER INTO total_delivered_period
        FROM channel_usage_tracking cut
        WHERE cut.organization_id = p_organization_id
          AND cut.channel = v_def.channel
          AND cut.period_date >= CURRENT_DATE - p_date_range_days
          AND cut.period_hour IS NULL;

        SELECT COALESCE(SUM(cut.messages_failed), 0)::INTEGER INTO total_failed_period
        FROM channel_usage_tracking cut
        WHERE cut.organization_id = p_organization_id
          AND cut.channel = v_def.channel
          AND cut.period_date >= CURRENT_DATE - p_date_range_days
          AND cut.period_hour IS NULL;

        IF total_sent_period > 0 THEN
            SELECT (COALESCE(SUM(cut.replies_received), 0)::DECIMAL / total_sent_period) * 100 INTO reply_rate
            FROM channel_usage_tracking cut
            WHERE cut.organization_id = p_organization_id
              AND cut.channel = v_def.channel
              AND cut.period_date >= CURRENT_DATE - p_date_range_days
              AND cut.period_hour IS NULL;
        ELSE
            reply_rate := 0;
        END IF;

        RETURN NEXT;
    END LOOP;
END;
$$;


ALTER FUNCTION "public"."get_channel_limits_summary"("p_organization_id" "uuid", "p_date_range_days" integer) OWNER TO "postgres";


