CREATE OR REPLACE FUNCTION "public"."get_contact_available_channels"("p_contact_id" "uuid") RETURNS "text"[]
    LANGUAGE "plpgsql" STABLE
    AS $$
DECLARE
  v_channels TEXT[] := '{}';
BEGIN
  -- Check for LinkedIn identity
  IF EXISTS (
    SELECT 1 FROM public.crm_contact_identities
    WHERE contact_id = p_contact_id AND channel = 'linkedin'
  ) THEN
    v_channels := array_append(v_channels, 'linkedin');
  END IF;

  -- Check for email (either on contact or identity)
  IF EXISTS (
    SELECT 1 FROM public.crm_contacts c
    WHERE c.id = p_contact_id AND c.primary_email IS NOT NULL
  ) OR EXISTS (
    SELECT 1 FROM public.crm_contact_identities
    WHERE contact_id = p_contact_id AND channel = 'email'
  ) THEN
    v_channels := array_append(v_channels, 'email');
  END IF;

  -- Check for WhatsApp identity
  IF EXISTS (
    SELECT 1 FROM public.crm_contact_identities
    WHERE contact_id = p_contact_id AND channel = 'whatsapp'
  ) THEN
    v_channels := array_append(v_channels, 'whatsapp');
  END IF;

  -- Check for SMS (phone number)
  IF EXISTS (
    SELECT 1 FROM public.crm_contacts c
    WHERE c.id = p_contact_id AND c.primary_phone IS NOT NULL
  ) OR EXISTS (
    SELECT 1 FROM public.crm_contact_identities
    WHERE contact_id = p_contact_id AND channel = 'sms'
  ) THEN
    v_channels := array_append(v_channels, 'sms');
  END IF;

  -- Check for Instagram identity
  IF EXISTS (
    SELECT 1 FROM public.crm_contact_identities
    WHERE contact_id = p_contact_id AND channel = 'instagram'
  ) THEN
    v_channels := array_append(v_channels, 'instagram');
  END IF;

  -- Check for Telegram identity
  IF EXISTS (
    SELECT 1 FROM public.crm_contact_identities
    WHERE contact_id = p_contact_id AND channel = 'telegram'
  ) THEN
    v_channels := array_append(v_channels, 'telegram');
  END IF;

  RETURN v_channels;
END;
$$;


ALTER FUNCTION "public"."get_contact_available_channels"("p_contact_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_contact_enrollments"("p_contact_id" "uuid") RETURNS TABLE("source" "text", "enrollment_id" "uuid", "sequence_id" "uuid", "sequence_name" "text", "sequence_status" "text", "enrollment_status" "text", "is_active" boolean, "is_followup" boolean, "next_action_at" timestamp with time zone, "pause_reason" "text")
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  WITH target AS (
    SELECT
      c.id                            AS contact_id,
      c.organization_id,
      lower(trim(c.primary_email))    AS email
    FROM crm_contacts c
    WHERE c.id = p_contact_id
  ),
  contact_leads AS (
    SELECT t.organization_id, t.contact_id AS lead_id FROM target t

    UNION

    SELECT t.organization_id, l.id
    FROM target t
    JOIN leads l
      ON l.organization_id = t.organization_id
     AND l.source_id = t.contact_id

    UNION

    SELECT t.organization_id, l.id
    FROM target t
    JOIN leads l
      ON l.organization_id = t.organization_id
     AND t.email IS NOT NULL
     AND lower(trim(l.email)) = t.email
  )
  SELECT
    'linkedin'::text                                      AS source,
    clp.id                                                AS enrollment_id,
    lc.id                                                 AS sequence_id,
    lc.name                                               AS sequence_name,
    lc.status::text                                       AS sequence_status,
    clp.status::text                                      AS enrollment_status,
    (clp.status IN ('pending', 'in_progress', 'waiting')) AS is_active,
    false                                                 AS is_followup,
    clp.next_action_at                                    AS next_action_at,
    NULL::text                                            AS pause_reason
  FROM campaign_lead_progress clp
  JOIN linkedin_campaigns lc ON lc.id = clp.campaign_id
  WHERE clp.contact_id = p_contact_id
    AND clp.is_test_contact = false

  UNION ALL

  SELECT
    'email'::text                                             AS source,
    e.id                                                      AS enrollment_id,
    es.id                                                     AS sequence_id,
    es.name                                                   AS sequence_name,
    es.status::text                                           AS sequence_status,
    e.status::text                                            AS enrollment_status,
    (e.status IN ('active', 'paused', 'sender_disconnected')) AS is_active,
    (e.metadata->>'recovery_type' = 'lead_magnet_followup')   AS is_followup,
    CASE WHEN e.status = 'paused' THEN e.resume_at ELSE e.next_send_at END
                                                              AS next_action_at,
    e.pause_reason                                            AS pause_reason
  FROM contact_leads cl
  JOIN email_sequence_enrollments e ON e.lead_id = cl.lead_id
  JOIN email_sequences es
    ON es.id = e.sequence_id
   AND es.organization_id = cl.organization_id

  ORDER BY is_followup DESC, is_active DESC, sequence_name;
$$;


ALTER FUNCTION "public"."get_contact_enrollments"("p_contact_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_contact_enrollments"("p_contact_id" "uuid") IS 'Returns a CRM contact''s outreach enrollments, prioritizing lead-magnet recovery follow-ups for the Inbox status indicator. Index-driven (source_id / normalized email) so it stays well inside the authenticated statement timeout.';



CREATE OR REPLACE FUNCTION "public"."get_contact_ids_by_emails"("p_org" "uuid", "p_emails" "text"[]) RETURNS TABLE("id" "uuid")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    SET "plan_cache_mode" TO 'force_custom_plan'
    AS $$
BEGIN
  IF p_org IS DISTINCT FROM public.get_user_organization_id() THEN
    RETURN;
  END IF;

  RETURN QUERY
  SELECT c.id
  FROM crm_contacts c
  WHERE c.organization_id = p_org
    AND lower(c.primary_email) = ANY(SELECT lower(e) FROM unnest(p_emails) AS e);
END;
$$;


ALTER FUNCTION "public"."get_contact_ids_by_emails"("p_org" "uuid", "p_emails" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_contact_ids_for_list_filter"("p_organization_id" "uuid", "p_in_list_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_exclude_list_ids" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS "uuid"[]
    LANGUAGE "sql" STABLE SECURITY DEFINER
    AS $$
  SELECT COALESCE(array_agg(id), ARRAY[]::UUID[])
  FROM (
    -- Branch 1: inListIds provided — contacts in those lists, optionally excluding others
    SELECT DISTINCT m.contact_id AS id
    FROM lead_list_members m
    JOIN crm_contacts c ON c.id = m.contact_id
    WHERE c.organization_id = p_organization_id
      AND p_in_list_ids IS NOT NULL
      AND m.list_id = ANY(p_in_list_ids)
      AND (
        p_exclude_list_ids IS NULL
        OR NOT EXISTS (
          SELECT 1 FROM lead_list_members x
          WHERE x.contact_id = m.contact_id
            AND x.list_id = ANY(p_exclude_list_ids)
        )
      )

    UNION ALL

    -- Branch 2: only excluding (no inListIds) — all org contacts not in excluded lists
    SELECT c.id
    FROM crm_contacts c
    WHERE c.organization_id = p_organization_id
      AND p_in_list_ids IS NULL
      AND p_exclude_list_ids IS NOT NULL
      AND NOT EXISTS (
        SELECT 1 FROM lead_list_members x
        WHERE x.contact_id = c.id
          AND x.list_id = ANY(p_exclude_list_ids)
      )
  ) sub;
$$;


ALTER FUNCTION "public"."get_contact_ids_for_list_filter"("p_organization_id" "uuid", "p_in_list_ids" "uuid"[], "p_exclude_list_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_contact_ids_not_in_lists"("p_organization_id" "uuid", "p_exclude_list_ids" "uuid"[]) RETURNS SETOF "uuid"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    AS $$
  SELECT c.id
  FROM crm_contacts c
  WHERE c.organization_id = p_organization_id
    AND NOT EXISTS (
      SELECT 1
      FROM lead_list_members m
      WHERE m.contact_id = c.id
        AND m.list_id = ANY(p_exclude_list_ids)
    );
$$;


ALTER FUNCTION "public"."get_contact_ids_not_in_lists"("p_organization_id" "uuid", "p_exclude_list_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_contact_unified_messages"("p_contact_id" "uuid", "p_org_id" "uuid", "p_limit" integer DEFAULT 100) RETURNS TABLE("message_id" "uuid", "conversation_id" "uuid", "channel" "text", "direction" "text", "sender_type" "text", "content" "text", "content_type" "text", "email_subject" "text", "attachments" "jsonb", "ai_generated" boolean, "status" "text", "metadata" "jsonb", "created_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    m.id AS message_id,
    m.conversation_id,
    c.channel::TEXT,
    m.direction::TEXT,
    m.sender_type::TEXT,
    m.content,
    m.content_type::TEXT,
    m.email_subject,
    m.attachments::JSONB,
    m.ai_generated,
    m.status::TEXT,
    m.metadata,
    m.created_at
  FROM public.crm_messages m
  JOIN public.crm_conversations c ON c.id = m.conversation_id
  WHERE m.contact_id = p_contact_id
    AND m.organization_id = p_org_id
  ORDER BY m.created_at DESC
  LIMIT p_limit;
END;
$$;


ALTER FUNCTION "public"."get_contact_unified_messages"("p_contact_id" "uuid", "p_org_id" "uuid", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_custom_signal_leads"("p_org_id" "uuid", "p_limit" integer DEFAULT 50, "p_offset" integer DEFAULT 0, "p_search" "text" DEFAULT NULL::"text", "p_signal_types" "text"[] DEFAULT NULL::"text"[], "p_has_email" boolean DEFAULT NULL::boolean, "p_max_age_days" integer DEFAULT NULL::integer, "p_sort_by" "text" DEFAULT 'signal_date'::"text", "p_sort_dir" "text" DEFAULT 'desc'::"text", "p_employee_bands" "text"[] DEFAULT NULL::"text"[], "p_revenue_bands" "text"[] DEFAULT NULL::"text"[], "p_industries" "text"[] DEFAULT NULL::"text"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_result jsonb;
  v_limit integer := LEAST(GREATEST(COALESCE(p_limit, 50), 1), 100);
  v_offset integer := GREATEST(COALESCE(p_offset, 0), 0);
  v_cutoff date := NULL;
  v_sort text := lower(COALESCE(p_sort_by, 'signal_date'));
  v_dir text := CASE WHEN lower(COALESCE(p_sort_dir, 'desc')) = 'asc' THEN 'asc' ELSE 'desc' END;
  v_emp text[] := NULL;
  v_rev text[] := NULL;
  v_ind text[] := NULL;
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.organization_members m
    WHERE m.organization_id = p_org_id AND m.user_id = auth.uid()
  ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'forbidden', 'leads', '[]'::jsonb, 'total', 0);
  END IF;

  IF v_sort NOT IN ('signal_date', 'name', 'company', 'email',
                    'employees', 'revenue', 'industry', 'country') THEN
    v_sort := 'signal_date';
  END IF;

  IF p_max_age_days IS NOT NULL AND p_max_age_days > 0 THEN
    v_cutoff := (now() AT TIME ZONE 'utc')::date - LEAST(p_max_age_days, 3650);
  END IF;

  SELECT NULLIF(ARRAY(SELECT btrim(v) FROM unnest(COALESCE(p_employee_bands, '{}')) v WHERE btrim(v) <> ''), '{}')
    INTO v_emp;
  SELECT NULLIF(ARRAY(SELECT public.signal_revenue_band(v) FROM unnest(COALESCE(p_revenue_bands, '{}')) v
                      WHERE public.signal_revenue_band(v) IS NOT NULL), '{}')
    INTO v_rev;
  SELECT NULLIF(ARRAY(SELECT lower(btrim(v)) FROM unnest(COALESCE(p_industries, '{}')) v WHERE btrim(v) <> ''), '{}')
    INTO v_ind;

  WITH org_companies AS (
    -- One row per normalized domain for this org. A domain can have several
    -- discovered-company rows (209 of them in prod), and doing this as a
    -- correlated lateral cost 75s per call — the normalize function defeats any
    -- index, so scan the org's companies once and join on the result.
    SELECT DISTINCT ON (nd) nd, employee_count_estimate, employee_signal, revenue_range
    FROM (
      SELECT public.signal_normalize_domain(d.domain) AS nd,
             d.employee_count_estimate, d.employee_signal, d.revenue_range, d.scraped_at, d.id
      FROM public.lb_discovered_companies d
      WHERE d.organization_id = p_org_id AND d.domain IS NOT NULL
    ) x
    WHERE nd IS NOT NULL
    ORDER BY nd,
             (employee_count_estimate IS NOT NULL) DESC,
             (revenue_range IS NOT NULL) DESC,
             scraped_at DESC NULLS LAST,
             id
  ), base AS (
    SELECT c.id, c.display_name, c.job_title, c.company, c.primary_email, c.email_type,
      c.primary_linkedin_url,
      COALESCE(NULLIF(c.company_website, ''),
               c.discovery_metadata->>'ai_signal_company_website') AS website_url,
      COALESCE(c.discovery_metadata->>'signal_type', ps.pack_key) AS signal_type,
      COALESCE(ps.name, ps.pack_key) AS signal_name,
      c.discovery_metadata->>'signal_date' AS signal_date,
      c.discovery_metadata->>'directory_evidence_url' AS source_url,
      COALESCE(
        NULLIF(c.discovery_metadata->>'company_employee_count', '')::integer,
        dc.employee_count_estimate
      ) AS employee_count,
      COALESCE(
        NULLIF(c.discovery_metadata->>'company_employee_range', ''),
        NULLIF(c.discovery_metadata->>'ai_signal_company_size', ''),
        dc.employee_signal
      ) AS employee_range,
      COALESCE(
        NULLIF(c.discovery_metadata->>'company_revenue_range', ''),
        NULLIF(c.discovery_metadata->>'ai_signal_revenue', ''),
        dc.revenue_range
      ) AS revenue_range,
      COALESCE(
        NULLIF(c.discovery_metadata->>'company_industry', ''),
        NULLIF(c.discovery_metadata->>'ai_signal_company_industry', ''),
        NULLIF(c.enrichment_data->>'industry', ''),
        cc.industry
      ) AS industry,
      CASE WHEN jsonb_typeof(c.discovery_metadata->'company_linkedin_industries') = 'array'
        THEN c.discovery_metadata->'company_linkedin_industries' END AS linkedin_industries,
      CASE WHEN jsonb_typeof(c.discovery_metadata->'company_naics_titles') = 'array'
        THEN c.discovery_metadata->'company_naics_titles' END AS naics_titles,
      COALESCE(NULLIF(c.discovery_metadata->>'company_country', ''), c.country, cc.country) AS company_country,
      CASE
        WHEN c.discovery_metadata->>'signal_date' ~ '^\d{4}-\d{2}-\d{2}$'
        THEN (c.discovery_metadata->>'signal_date')::date
      END AS signal_date_parsed
    FROM public.crm_contacts c
    JOIN public.pack_subscriptions ps ON ps.id::text = c.discovery_metadata->>'signal_subscription_id'
    LEFT JOIN public.crm_companies cc
      ON cc.id = c.company_id AND cc.organization_id = p_org_id
    LEFT JOIN org_companies dc
      ON dc.nd = public.signal_normalize_domain(
           COALESCE(NULLIF(c.company_website, ''),
                    c.enrichment_data->>'website',
                    c.discovery_metadata->>'ai_signal_company_website')
         )
    WHERE c.organization_id = p_org_id AND ps.organization_id = p_org_id
      AND (p_search IS NULL OR btrim(p_search) = ''
           OR c.display_name ILIKE '%'||btrim(p_search)||'%'
           OR c.company ILIKE '%'||btrim(p_search)||'%'
           OR c.primary_email ILIKE '%'||btrim(p_search)||'%')
      AND (p_signal_types IS NULL OR cardinality(p_signal_types) = 0
           OR COALESCE(c.discovery_metadata->>'signal_type', ps.pack_key) = ANY(p_signal_types))
      AND (p_has_email IS NULL
           OR (p_has_email AND NULLIF(c.primary_email,'') IS NOT NULL)
           OR (NOT p_has_email AND NULLIF(c.primary_email,'') IS NULL))
  ), filtered AS (
    SELECT * FROM base
    WHERE (v_cutoff IS NULL OR signal_date_parsed >= v_cutoff)
      AND (v_emp IS NULL
           OR public.signal_employee_band(employee_count, employee_range) = ANY(v_emp))
      AND (v_rev IS NULL
           OR public.signal_revenue_band(revenue_range) = ANY(v_rev))
      AND (v_ind IS NULL
           OR lower(COALESCE(industry, '')) = ANY(v_ind))
  ), counted AS (
    SELECT count(*) AS total FROM filtered
  ), paged AS (
    SELECT * FROM filtered
    ORDER BY
      CASE WHEN v_dir = 'asc' THEN
        CASE v_sort
          WHEN 'name'     THEN lower(display_name)
          WHEN 'company'  THEN lower(NULLIF(company, ''))
          WHEN 'email'    THEN lower(NULLIF(primary_email, ''))
          WHEN 'industry' THEN lower(NULLIF(industry, ''))
          WHEN 'country'  THEN lower(NULLIF(company_country, ''))
        END
      END ASC NULLS LAST,
      CASE WHEN v_dir = 'desc' THEN
        CASE v_sort
          WHEN 'name'     THEN lower(display_name)
          WHEN 'company'  THEN lower(NULLIF(company, ''))
          WHEN 'email'    THEN lower(NULLIF(primary_email, ''))
          WHEN 'industry' THEN lower(NULLIF(industry, ''))
          WHEN 'country'  THEN lower(NULLIF(company_country, ''))
        END
      END DESC NULLS LAST,
      CASE WHEN v_sort = 'signal_date' AND v_dir = 'asc'  THEN signal_date_parsed END ASC NULLS LAST,
      CASE WHEN v_sort = 'signal_date' AND v_dir = 'desc' THEN signal_date_parsed END DESC NULLS LAST,
      CASE WHEN v_sort = 'employees' AND v_dir = 'asc'  THEN employee_count END ASC NULLS LAST,
      CASE WHEN v_sort = 'employees' AND v_dir = 'desc' THEN employee_count END DESC NULLS LAST,
      CASE WHEN v_sort = 'revenue' AND v_dir = 'asc'
           THEN public.signal_revenue_rank(revenue_range) END ASC NULLS LAST,
      CASE WHEN v_sort = 'revenue' AND v_dir = 'desc'
           THEN public.signal_revenue_rank(revenue_range) END DESC NULLS LAST,
      id DESC
    LIMIT v_limit OFFSET v_offset
  )
  SELECT jsonb_build_object(
    'ok', true,
    'total', (SELECT total FROM counted),
    'leads', COALESCE(jsonb_agg(jsonb_build_object(
      'id', id,
      'name', display_name,
      'title', job_title,
      'company', company,
      'website_url', website_url,
      'email', primary_email,
      'email_status', COALESCE(email_type, CASE WHEN NULLIF(primary_email,'') IS NOT NULL THEN 'available' END),
      'linkedin_url', primary_linkedin_url,
      'signal_type', signal_type,
      'signal_name', signal_name,
      'signal_date', signal_date,
      'source_url', source_url,
      'company_employee_count', employee_count,
      'company_employee_range', employee_range,
      'company_employee_band', public.signal_employee_band(employee_count, employee_range),
      'company_revenue_range', revenue_range,
      'company_industry', industry,
      'company_linkedin_industries', linkedin_industries,
      'company_naics_titles', naics_titles,
      'company_country', company_country
    )), '[]'::jsonb)
  ) INTO v_result FROM paged;

  RETURN v_result;
END;
$_$;


ALTER FUNCTION "public"."get_custom_signal_leads"("p_org_id" "uuid", "p_limit" integer, "p_offset" integer, "p_search" "text", "p_signal_types" "text"[], "p_has_email" boolean, "p_max_age_days" integer, "p_sort_by" "text", "p_sort_dir" "text", "p_employee_bands" "text"[], "p_revenue_bands" "text"[], "p_industries" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_decrypted_api_key"("p_organization_id" "uuid", "p_provider" "text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_encrypted TEXT;
  v_decrypted TEXT;
  v_key TEXT;
BEGIN
  -- Get encryption key from environment (stored in secrets)
  v_key := current_setting('app.encryption_key', true);
  
  IF v_key IS NULL THEN
    RAISE EXCEPTION 'Encryption key not configured';
  END IF;

  -- Get encrypted API key
  SELECT key_encrypted INTO v_encrypted
  FROM public.api_keys
  WHERE organization_id = p_organization_id
    AND provider = p_provider
  LIMIT 1;

  IF v_encrypted IS NULL THEN
    RAISE EXCEPTION 'API key not found for provider %', p_provider;
  END IF;

  -- Decrypt using pgcrypto (assuming AES encryption)
  BEGIN
    v_decrypted := convert_from(decode(v_encrypted, 'base64'), 'UTF8');
  EXCEPTION WHEN OTHERS THEN
    v_decrypted := v_encrypted;
  END;

  RETURN v_decrypted;
END;
$$;


ALTER FUNCTION "public"."get_decrypted_api_key"("p_organization_id" "uuid", "p_provider" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_domain_delivery_monitoring"("p_domain_id" "uuid", "p_days" integer DEFAULT 7) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_domain public.email_sending_domains%ROWTYPE;
  v_days integer := coalesce(p_days, 7);
  v_since timestamptz;
  v_providers jsonb;
  v_probes jsonb;
  v_postmaster jsonb;
BEGIN
  IF v_days < 1 OR v_days > 90 THEN RAISE EXCEPTION 'Days must be between 1 and 90' USING ERRCODE = '22023'; END IF;
  SELECT * INTO v_domain FROM public.email_sending_domains WHERE id = p_domain_id;
  IF NOT FOUND OR (auth.role() IS DISTINCT FROM 'service_role' AND NOT public.is_super_admin(auth.uid()) AND NOT EXISTS (
    SELECT 1 FROM public.organization_members WHERE organization_id = v_domain.organization_id AND user_id = auth.uid())) THEN
    RAISE EXCEPTION 'Domain unavailable or permission denied' USING ERRCODE = '42501';
  END IF;
  v_since := now() - make_interval(days => v_days);

  -- Restrict the hot log by tenant, indexed date and the domain's mailbox IDs.
  -- A sent handoff is not confirmed delivery. Failed SMTP attempts (which can
  -- have NULL sent_at) belong in the attempted denominator, skipped rows do not.
  WITH attempts AS (
    SELECT l.*, lower(split_part(l.recipient_email, '@', 2)) AS recipient_domain
    FROM public.email_send_log l
    WHERE l.organization_id = v_domain.organization_id AND l.created_at >= v_since
      AND l.mailbox_id IN (SELECT id FROM public.email_mailboxes
        WHERE sending_domain_id = p_domain_id AND organization_id = v_domain.organization_id)
      AND l.status IN ('sent', 'delivered', 'opened', 'clicked', 'replied', 'bounced', 'blocked', 'failed', 'spam')
  ), classified AS (
    SELECT CASE
      WHEN recipient_domain IN ('gmail.com', 'googlemail.com') THEN 'gmail'
      WHEN recipient_domain IN ('outlook.com', 'hotmail.com', 'live.com', 'msn.com', 'hotmail.co.uk', 'hotmail.fr', 'outlook.fr') THEN 'microsoft'
      WHEN recipient_domain IN ('yahoo.com', 'ymail.com', 'rocketmail.com', 'yahoo.co.uk', 'yahoo.fr', 'yahoo.ca', 'yahoo.com.au') THEN 'yahoo'
      WHEN recipient_domain IN ('aol.com', 'icloud.com', 'me.com', 'mac.com', 'proton.me', 'protonmail.com', 'gmx.com', 'gmx.de', 'mail.com', 'zoho.com') THEN 'other_consumer'
      WHEN cache.mx_provider = 'google' THEN 'gmail'
      WHEN cache.mx_provider = 'microsoft' THEN 'microsoft'
      ELSE 'unknown' END AS provider,
      CASE
        WHEN opened_at IS NOT NULL OR clicked_at IS NOT NULL OR replied_at IS NOT NULL
          OR status IN ('delivered', 'opened', 'clicked', 'replied') OR lower(coalesce(trace_status, '')) = 'delivered' THEN 'delivered'
        WHEN error_category = 'reputation_block' THEN 'reputation_rejected'
        WHEN error_category IN ('hard_bounce', 'ndr_bounce') OR (status = 'bounced' AND bounced_at IS NOT NULL) THEN 'recipient_bounced'
        WHEN status IN ('failed', 'blocked', 'spam', 'bounced') OR lower(coalesce(trace_status, '')) IN ('failed', 'quarantined', 'filteredasspam') THEN 'send_failed'
        ELSE 'unconfirmed' END AS outcome
    FROM attempts
    -- DNS MX evidence is shared globally. Look up only attempted recipient
    -- domains; LIMIT 1 ensures duplicate cache entries cannot multiply sends.
    LEFT JOIN LATERAL (
      SELECT mx_provider FROM public.domain_pattern_cache
      WHERE domain = attempts.recipient_domain AND mx_valid = true
        AND last_verified_at IS NOT NULL AND expires_at > now()
      ORDER BY last_verified_at DESC LIMIT 1
    ) cache ON true
  ), cohorts AS (
    SELECT provider, count(*) AS attempted,
      count(*) FILTER (WHERE outcome = 'delivered') AS delivered,
      count(*) FILTER (WHERE outcome = 'reputation_rejected') AS reputation_rejected,
      count(*) FILTER (WHERE outcome = 'recipient_bounced') AS recipient_bounced,
      count(*) FILTER (WHERE outcome = 'send_failed') AS send_failed,
      count(*) FILTER (WHERE outcome = 'unconfirmed') AS unconfirmed
    FROM classified GROUP BY provider
  ) SELECT coalesce(jsonb_agg(to_jsonb(cohorts) ORDER BY provider), '[]'::jsonb) INTO v_providers FROM cohorts;

  WITH cohorts AS (
    SELECT coalesce(nullif(btrim(seed_provider), ''), 'unknown') AS seed_provider,
      count(*) AS attempted,
      count(*) FILTER (WHERE outcome = 'delivered') AS delivered,
      count(*) FILTER (WHERE outcome = 'failed_550') AS reputation_rejected,
      count(*) FILTER (WHERE outcome = 'spam') AS spam,
      count(*) FILTER (WHERE outcome = 'send_failed') AS send_failed,
      count(*) FILTER (WHERE outcome IN ('pending', 'no_trace')) AS unconfirmed
    FROM public.email_domain_probes
    WHERE domain_id = p_domain_id AND organization_id = v_domain.organization_id AND created_at >= v_since
      AND (sent_at IS NOT NULL OR outcome <> 'pending')
    GROUP BY 1
  ) SELECT coalesce(jsonb_agg(to_jsonb(cohorts) ORDER BY seed_provider), '[]'::jsonb) INTO v_probes FROM cohorts;

  SELECT jsonb_build_object('recorded_for', recorded_for,
    'domain_reputation', domain_reputation, 'ip_reputation', ip_reputation,
    'spam_rate', spam_rate, 'dkim_success_ratio', dkim_success_ratio,
    'spf_success_ratio', spf_success_ratio, 'dmarc_success_ratio', dmarc_success_ratio,
    'delivery_errors', delivery_errors)
  INTO v_postmaster FROM public.email_domain_reputation_log
  WHERE domain_id = p_domain_id AND organization_id = v_domain.organization_id
  ORDER BY recorded_for DESC LIMIT 1;

  RETURN jsonb_build_object('domain_id', p_domain_id, 'days', v_days,
    'window_start', v_since, 'window_end', now(),
    'sending_paused_at', v_domain.sending_paused_at, 'sending_pause_reason', v_domain.sending_pause_reason,
    'sending_paused_by', v_domain.sending_paused_by,
    'technically_unusable', public.is_sending_domain_technically_unusable(p_domain_id),
    'recipient_providers', v_providers, 'probes', v_probes, 'gmail_postmaster', v_postmaster);
END;
$$;


ALTER FUNCTION "public"."get_domain_delivery_monitoring"("p_domain_id" "uuid", "p_days" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_effective_daily_limit"("p_organization_id" "uuid", "p_channel" "public"."crm_channel_type", "p_channel_account_id" "uuid" DEFAULT NULL::"uuid") RETURNS integer
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_org_limit organization_channel_limits%ROWTYPE;
    v_definition channel_limit_definitions%ROWTYPE;
    v_warmup_limit INTEGER;
    v_zone_limit INTEGER;
    v_effective_limit INTEGER;
BEGIN
    SELECT * INTO v_definition FROM channel_limit_definitions WHERE channel = p_channel;
    IF NOT FOUND THEN
        RETURN 0;
    END IF;

    SELECT * INTO v_org_limit
    FROM organization_channel_limits
    WHERE organization_id = p_organization_id
      AND channel = p_channel
      AND (channel_account_id = p_channel_account_id OR (channel_account_id IS NULL AND p_channel_account_id IS NULL));

    IF NOT FOUND THEN
        RETURN v_definition.safe_daily_limit;
    END IF;

    IF NOT v_org_limit.is_enabled THEN
        RETURN 0;
    END IF;

    IF v_org_limit.custom_daily_limit IS NOT NULL THEN
        v_effective_limit := v_org_limit.custom_daily_limit;
    ELSE
        v_zone_limit := CASE v_org_limit.current_zone
            WHEN 'safe' THEN v_definition.safe_daily_limit
            WHEN 'moderate' THEN v_definition.moderate_daily_limit
            WHEN 'faster' THEN v_definition.faster_daily_limit
            WHEN 'risky' THEN v_definition.risky_daily_limit
            ELSE v_definition.safe_daily_limit
        END;
        v_effective_limit := v_zone_limit;
    END IF;

    IF v_org_limit.warmup_status = 'in_progress' THEN
        v_warmup_limit := v_definition.warmup_start_limit +
            (v_org_limit.warmup_current_day * v_definition.warmup_increment_per_day);
        v_effective_limit := LEAST(v_effective_limit, v_warmup_limit);
    END IF;

    v_effective_limit := FLOOR(v_effective_limit * v_org_limit.risk_tolerance);
    v_effective_limit := LEAST(v_effective_limit, v_definition.absolute_max_daily);

    RETURN v_effective_limit;
END;
$$;


ALTER FUNCTION "public"."get_effective_daily_limit"("p_organization_id" "uuid", "p_channel" "public"."crm_channel_type", "p_channel_account_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_effective_daily_limits_for_accounts"("p_organization_id" "uuid", "p_channel_account_ids" "uuid"[], "p_channels" "public"."crm_channel_type"[] DEFAULT ARRAY['linkedin_invitation'::"public"."crm_channel_type", 'linkedin_message'::"public"."crm_channel_type", 'linkedin_inmail'::"public"."crm_channel_type", 'linkedin_profile_view'::"public"."crm_channel_type", 'linkedin_follow'::"public"."crm_channel_type", 'linkedin_post_like'::"public"."crm_channel_type"]) RETURNS TABLE("channel_account_id" "uuid", "channel" "public"."crm_channel_type", "daily_limit" integer)
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        acc.account_id,
        ch.ch,
        lim.daily_limit
    FROM unnest(p_channel_account_ids) AS acc(account_id)
    CROSS JOIN unnest(p_channels) AS ch(ch)
    CROSS JOIN LATERAL check_channel_limit(p_organization_id, ch.ch, acc.account_id) AS lim;
END;
$$;


ALTER FUNCTION "public"."get_effective_daily_limits_for_accounts"("p_organization_id" "uuid", "p_channel_account_ids" "uuid"[], "p_channels" "public"."crm_channel_type"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_email_analytics_daily_trend"("p_org" "uuid", "p_start" timestamp with time zone, "p_end" timestamp with time zone, "p_sequence_id" "uuid" DEFAULT NULL::"uuid", "p_mailbox_id" "uuid" DEFAULT NULL::"uuid", "p_tz" "text" DEFAULT 'UTC'::"text") RETURNS TABLE("day" "date", "sent" bigint, "unique_leads" bigint, "delivered" bigint, "opened" bigint, "clicked" bigint, "replied" bigint, "bounced" bigint)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    SET "plan_cache_mode" TO 'force_custom_plan'
    AS $$
#variable_conflict use_column
BEGIN
PERFORM public.email_analytics_assert_org(p_org);
RETURN QUERY
WITH rows AS (
  SELECT l.id, l.mailbox_id AS mb,
         (l.created_at AT TIME ZONE p_tz)::date AS d,
         coalesce(l.lead_id, l.id) AS lead_key,
         CASE l.status
           WHEN 'sent' THEN 1 WHEN 'delivered' THEN 2 WHEN 'auto_replied' THEN 2
           WHEN 'opened' THEN 3 WHEN 'clicked' THEN 4
           WHEN 'blocked' THEN 0 WHEN 'bounced' THEN 6 WHEN 'spam' THEN 7
           WHEN 'replied' THEN 8 ELSE -1
         END AS rank,
         (l.status IN ('opened','clicked')
           OR (l.status = 'replied' AND coalesce((es.settings->>'open_tracking')::boolean, true))
         ) AS opened_signal,
         (l.status = 'clicked'
           OR (l.status = 'replied' AND coalesce((es.settings->>'click_tracking')::boolean, true))
         ) AS clicked_signal
  FROM email_send_log l
  LEFT JOIN email_sequences es ON es.id = l.sequence_id
  WHERE l.organization_id = p_org
    AND l.status NOT IN ('queued','sending','filtered','skipped','failed')
    AND l.created_at >= coalesce(p_start, '-infinity'::timestamptz)
    AND l.created_at <= coalesce(p_end, 'infinity'::timestamptz)
    AND (p_sequence_id IS NULL OR l.sequence_id = p_sequence_id)
    AND (p_mailbox_id IS NULL OR l.mailbox_id = p_mailbox_id)
),
not_genuine AS (
  SELECT r.id
  FROM rows r
  JOIN email_send_log s ON s.id = r.id
  LEFT JOIN LATERAL public.email_reply_outcome(p_org, s.recipient_email, r.mb) o ON true
  WHERE r.rank = 8
    AND NOT (coalesce(o.meeting, false) OR o.lead_intent IS NULL
             OR o.lead_intent NOT IN ('out_of_office', 'auto_reply'))
),
day_totals AS (
  SELECT r.d, count(*) AS n FROM rows r GROUP BY r.d
),
per_day_lead AS (
  SELECT r.d, r.lead_key,
         max(CASE WHEN ng.id IS NOT NULL THEN 2 ELSE r.rank END) AS rank,
         bool_or(r.opened_signal) AS is_opened, bool_or(r.clicked_signal) AS is_clicked
  FROM rows r
  LEFT JOIN not_genuine ng ON ng.id = r.id
  GROUP BY r.d, r.lead_key
)
SELECT
  t.d,
  t.n,
  count(*),
  count(*) FILTER (WHERE pl.rank NOT IN (0,6,7)),
  count(*) FILTER (WHERE pl.is_opened),
  count(*) FILTER (WHERE pl.is_clicked),
  count(*) FILTER (WHERE pl.rank = 8),
  count(*) FILTER (WHERE pl.rank = 6)
FROM per_day_lead pl
JOIN day_totals t ON t.d = pl.d
GROUP BY t.d, t.n
ORDER BY t.d;
END;
$$;


ALTER FUNCTION "public"."get_email_analytics_daily_trend"("p_org" "uuid", "p_start" timestamp with time zone, "p_end" timestamp with time zone, "p_sequence_id" "uuid", "p_mailbox_id" "uuid", "p_tz" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_email_analytics_stats"("p_org" "uuid", "p_start" timestamp with time zone, "p_end" timestamp with time zone, "p_prev_start" timestamp with time zone, "p_prev_end" timestamp with time zone, "p_sequence_id" "uuid" DEFAULT NULL::"uuid", "p_mailbox_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    SET "plan_cache_mode" TO 'force_custom_plan'
    AS $$
BEGIN
PERFORM public.email_analytics_assert_org(p_org);
RETURN jsonb_build_object(
  'curr', public.email_analytics_period(p_org, p_start, p_end, p_sequence_id, p_mailbox_id),
  'prev', CASE WHEN p_prev_start IS NULL AND p_prev_end IS NULL THEN NULL
               ELSE public.email_analytics_period(p_org, p_prev_start, p_prev_end, p_sequence_id, p_mailbox_id)
          END,
  'filtered', (
    SELECT coalesce(jsonb_object_agg(reason, n), '{}'::jsonb)
    FROM (
      SELECT coalesce(l.error_message, 'unknown') AS reason, count(*) AS n
      FROM email_send_log l
      WHERE l.organization_id = p_org
        AND l.status = 'filtered'
        AND l.created_at >= coalesce(p_start, '-infinity'::timestamptz)
        AND l.created_at <= coalesce(p_end, 'infinity'::timestamptz)
        AND (p_sequence_id IS NULL OR l.sequence_id = p_sequence_id)
        AND (p_mailbox_id IS NULL OR l.mailbox_id = p_mailbox_id)
      GROUP BY 1
    ) f
  )
);
END;
$$;


ALTER FUNCTION "public"."get_email_analytics_stats"("p_org" "uuid", "p_start" timestamp with time zone, "p_end" timestamp with time zone, "p_prev_start" timestamp with time zone, "p_prev_end" timestamp with time zone, "p_sequence_id" "uuid", "p_mailbox_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_email_fleet_demand"("p_org" "uuid", "p_tags" "text"[] DEFAULT '{}'::"text"[], "p_tag_match" "text" DEFAULT 'any'::"text", "p_sequence_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_tags text[] := array_remove(coalesce(p_tags, '{}'::text[]), '');
  v_all boolean := coalesce(p_tag_match, 'any') = 'all';
  v_today date := (now() AT TIME ZONE 'UTC')::date;
  v_day_start timestamptz := ((now() AT TIME ZONE 'UTC')::date)::timestamp AT TIME ZONE 'UTC';
  v_result jsonb;
BEGIN
  -- SECURITY DEFINER changes current_user, so it cannot identify the caller.
  IF NOT (
    auth.role() = 'service_role'
    OR (auth.uid() IS NULL AND session_user IN ('postgres', 'supabase_admin'))
    OR (p_org IS NOT NULL AND check_org_membership(p_org))
  ) THEN
    RAISE EXCEPTION 'Not a member of this organization' USING ERRCODE = '42501';
  END IF;

  WITH blocked AS (
    SELECT b.id FROM blocked_sending_domains b WHERE b.organization_id = p_org
  ),
  fleet AS (
    SELECT
      m.id,
      coalesce(m.daily_limit, 0) AS cap,
      coalesce(m.tags, '{}'::text[]) AS tags,
      CASE WHEN m.daily_sent_reset_at = v_today THEN coalesce(m.daily_sent, 0) ELSE 0 END AS sent
    FROM email_mailboxes m
    WHERE m.organization_id = p_org
      AND m.status = 'ready'
      AND m.imap_connected
      AND m.health_score >= 0.5
      AND (m.sending_domain_id IS NULL OR m.sending_domain_id NOT IN (SELECT id FROM blocked))
      AND NOT (
        coalesce(m.warmup_enabled, false)
        AND (coalesce(m.warmup_day, 0) < 23 OR coalesce(m.health_score, 0) < 0.7)
      )
  ),
  pool AS (
    SELECT f.* FROM fleet f
    WHERE cardinality(v_tags) = 0
       OR (v_all AND f.tags @> v_tags)
       OR (NOT v_all AND f.tags && v_tags)
  ),
  seqs AS (
    SELECT
      s.id,
      s.name,
      CASE
        WHEN NOT (s.settings ? 'daily_limit') THEN 30
        WHEN (s.settings->>'daily_limit') ~ '^[0-9]+(\.[0-9]+)?$'
          AND (s.settings->>'daily_limit')::numeric > 0
          THEN ceil((s.settings->>'daily_limit')::numeric)::int
        ELSE NULL
      END AS daily_limit,
      CASE
        WHEN jsonb_typeof(s.settings->'mailbox_selection'->'tags') = 'array'
          THEN array_remove(ARRAY(
            SELECT jsonb_array_elements_text(s.settings->'mailbox_selection'->'tags')
          ), '')
        ELSE '{}'::text[]
      END AS tags,
      coalesce(s.settings->'mailbox_selection'->>'tag_match', 'any') AS tag_match
    FROM email_sequences s
    WHERE s.organization_id = p_org
      AND s.status = 'active'
      AND s.settings->'mailbox_selection'->>'mode' = 'auto'
      AND (p_sequence_id IS NULL OR s.id <> p_sequence_id)
  ),
  sized AS (
    SELECT
      q.*,
      (SELECT coalesce(sum(f.cap), 0) FROM fleet f
        WHERE cardinality(q.tags) = 0
           OR (q.tag_match = 'all' AND f.tags @> q.tags)
           OR (q.tag_match <> 'all' AND f.tags && q.tags))::int AS pool_capacity,
      (SELECT coalesce(sum(p.cap), 0) FROM pool p
        WHERE cardinality(q.tags) = 0
           OR (q.tag_match = 'all' AND p.tags @> q.tags)
           OR (q.tag_match <> 'all' AND p.tags && q.tags))::int AS shared_capacity,
      (SELECT count(*) FROM email_send_log l
        WHERE l.sequence_id = q.id
          AND l.sent_at >= v_day_start
          AND l.status IN ('sent', 'delivered', 'opened', 'clicked', 'replied'))::int AS sent_today
    FROM seqs q
  ),
  counted AS (
    SELECT
      z.*,
      coalesce(z.daily_limit, z.pool_capacity) AS cap,
      (SELECT count(*) FROM (
        SELECT 1 FROM email_sequence_enrollments e
        WHERE e.sequence_id = z.id
          AND e.status = 'active'
          AND e.next_send_at <= now() + interval '24 hours'
        LIMIT greatest(coalesce(z.daily_limit, z.pool_capacity), 1)
      ) d)::int AS due
    FROM sized z
  )
  SELECT jsonb_build_object(
    'day_start', v_day_start,
    -- The Senders panel previews the pool from raw mailbox rows; this lets it
    -- drop the same blocked domains the sender does.
    'blocked_domain_ids', (SELECT coalesce(jsonb_agg(id), '[]'::jsonb) FROM blocked),
    'fleet', (SELECT jsonb_build_object(
      'mailboxes', count(*),
      'capacity', coalesce(sum(cap), 0),
      'sent_today', coalesce(sum(sent), 0)
    ) FROM fleet),
    'pool', (SELECT jsonb_build_object(
      'mailboxes', count(*),
      'capacity', coalesce(sum(cap), 0),
      'sent_today', coalesce(sum(sent), 0)
    ) FROM pool),
    'sequences', coalesce((
      SELECT jsonb_agg(jsonb_build_object(
        'id', c.id,
        'name', c.name,
        'daily_limit', c.daily_limit,
        'tags', to_jsonb(c.tags),
        'tag_match', c.tag_match,
        'sent_today', c.sent_today,
        'due', c.due,
        'demand', least(c.cap, c.sent_today + c.due),
        'pool_capacity', c.pool_capacity,
        'shared_capacity', c.shared_capacity
      ) ORDER BY least(c.cap, c.sent_today + c.due) DESC, c.name)
      FROM counted c
    ), '[]'::jsonb),
    'self', CASE WHEN p_sequence_id IS NULL THEN NULL ELSE (
      SELECT jsonb_build_object(
        'status', s.status,
        'sent_today', (SELECT count(*) FROM email_send_log l
          WHERE l.sequence_id = s.id
            AND l.sent_at >= v_day_start
            AND l.status IN ('sent', 'delivered', 'opened', 'clicked', 'replied')),
        'due', (SELECT count(*) FROM (
          SELECT 1 FROM email_sequence_enrollments e
          WHERE e.sequence_id = s.id
            AND e.status = 'active'
            AND e.next_send_at <= now() + interval '24 hours'
          LIMIT 25000 -- SELF_DUE_COUNT_CAP in src/lib/fleet-demand.ts
        ) d)
      )
      FROM email_sequences s
      WHERE s.id = p_sequence_id AND s.organization_id = p_org
    ) END
  ) INTO v_result;

  RETURN v_result;
END;
$_$;


ALTER FUNCTION "public"."get_email_fleet_demand"("p_org" "uuid", "p_tags" "text"[], "p_tag_match" "text", "p_sequence_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_email_reply_leads"("p_org" "uuid", "p_start" timestamp with time zone, "p_end" timestamp with time zone, "p_sequence_id" "uuid" DEFAULT NULL::"uuid", "p_mailbox_id" "uuid" DEFAULT NULL::"uuid", "p_kind" "text" DEFAULT 'replied'::"text", "p_limit" integer DEFAULT 500) RETURNS TABLE("lead_key" "text", "recipient_email" "text", "contact_id" "uuid", "contact_name" "text", "conversation_id" "uuid", "sequence_id" "uuid", "sequence_name" "text", "lead_intent" "text", "meeting" boolean, "replied_at" timestamp with time zone, "subject" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    SET "plan_cache_mode" TO 'force_custom_plan'
    AS $$
#variable_conflict use_column
BEGIN
PERFORM public.email_analytics_assert_org(p_org);
RETURN QUERY
WITH response_rows AS (
  SELECT coalesce(l.lead_id, l.id) AS lk, l.status AS st, l.recipient_email AS em,
         l.sequence_id AS seq, l.mailbox_id AS mb,
         coalesce(l.replied_at, l.created_at) AS r_at, l.subject AS subj
  FROM email_send_log l
  WHERE l.organization_id = p_org
    AND l.status IN ('replied', 'auto_replied')
    AND l.created_at >= coalesce(p_start, '-infinity'::timestamptz)
    AND l.created_at <= coalesce(p_end, 'infinity'::timestamptz)
    AND (p_sequence_id IS NULL OR l.sequence_id = p_sequence_id)
    AND (p_mailbox_id IS NULL OR l.mailbox_id = p_mailbox_id)
),
scored AS (
  SELECT r.lk, r.em, r.seq, r.r_at, r.subj,
         o.contact_id AS c_id, o.contact_name AS c_name, o.conversation_id AS conv_id,
         o.lead_intent AS intent, coalesce(o.meeting, false) AS is_meeting,
         (r.st = 'replied'
           AND (coalesce(o.meeting, false) OR o.lead_intent IS NULL
                OR o.lead_intent NOT IN ('out_of_office', 'auto_reply'))) AS genuine
  FROM response_rows r
  LEFT JOIN LATERAL public.email_reply_outcome(p_org, r.em, r.mb) o ON true
),
per_lead AS (
  SELECT DISTINCT ON (x.lk) x.*, bool_or(x.genuine) OVER (PARTITION BY x.lk) AS lead_genuine
  FROM scored x
  ORDER BY x.lk, x.genuine DESC, x.is_meeting DESC,
           public.email_reply_intent_priority(x.intent) DESC, x.r_at DESC
)
SELECT p.lk::text, p.em, p.c_id, p.c_name, p.conv_id, p.seq, es.name,
       CASE
         WHEN p.lead_genuine AND p.is_meeting THEN 'meeting_booked'
         WHEN NOT p.lead_genuine AND p.intent IS DISTINCT FROM 'out_of_office' THEN 'auto_reply'
         ELSE p.intent
       END,
       p.lead_genuine AND p.is_meeting, p.r_at, p.subj
FROM per_lead p
LEFT JOIN email_sequences es ON es.id = p.seq
WHERE (p_kind = 'replied' AND p.lead_genuine)
   OR (p_kind = 'positive' AND p.lead_genuine AND (p.intent IN ('interested','meeting_booked') OR p.is_meeting))
   OR (p_kind = 'meetings' AND p.lead_genuine AND p.is_meeting)
   OR (p_kind = 'auto' AND NOT p.lead_genuine)
ORDER BY p.r_at DESC
LIMIT greatest(1, least(coalesce(p_limit, 500), 2000));
END;
$$;


ALTER FUNCTION "public"."get_email_reply_leads"("p_org" "uuid", "p_start" timestamp with time zone, "p_end" timestamp with time zone, "p_sequence_id" "uuid", "p_mailbox_id" "uuid", "p_kind" "text", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_email_sequence_mailbox_ids"("p_org" "uuid", "p_sequence_id" "uuid") RETURNS "uuid"[]
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    SET "plan_cache_mode" TO 'force_custom_plan'
    AS $$
BEGIN
PERFORM public.email_analytics_assert_org(p_org);
RETURN (
  SELECT coalesce(array_agg(DISTINCT l.mailbox_id), '{}'::uuid[])
  FROM email_send_log l
  WHERE l.organization_id = p_org
    AND l.sequence_id = p_sequence_id
    AND l.mailbox_id IS NOT NULL
    AND l.status NOT IN ('queued','sending','filtered','skipped','failed')
);
END;
$$;


ALTER FUNCTION "public"."get_email_sequence_mailbox_ids"("p_org" "uuid", "p_sequence_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_email_sequence_performance"("p_org" "uuid", "p_start" timestamp with time zone, "p_end" timestamp with time zone, "p_mailbox_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("sequence_id" "uuid", "sequence_name" "text", "sequence_status" "text", "sent" bigint, "unique_leads" bigint, "delivered" bigint, "replied" bigint, "positive" bigint, "meetings" bigint, "bounced" bigint, "blocked" bigint, "auto_replies" bigint, "last_sent_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    SET "plan_cache_mode" TO 'force_custom_plan'
    AS $$
#variable_conflict use_column
BEGIN
PERFORM public.email_analytics_assert_org(p_org);
RETURN QUERY
WITH rows AS (
  SELECT l.id, l.sequence_id AS seq, l.status AS st, l.mailbox_id AS mb, l.created_at AS at,
         coalesce(l.lead_id, l.id) AS lead_key,
         CASE l.status
           WHEN 'sent' THEN 1 WHEN 'delivered' THEN 2 WHEN 'auto_replied' THEN 2
           WHEN 'opened' THEN 3 WHEN 'clicked' THEN 4
           WHEN 'blocked' THEN 0 WHEN 'bounced' THEN 6 WHEN 'spam' THEN 7
           WHEN 'replied' THEN 8 ELSE -1
         END AS rank
  FROM email_send_log l
  WHERE l.organization_id = p_org
    AND l.sequence_id IS NOT NULL
    AND l.status NOT IN ('queued','sending','filtered','skipped','failed')
    AND l.created_at >= coalesce(p_start, '-infinity'::timestamptz)
    AND l.created_at <= coalesce(p_end, 'infinity'::timestamptz)
    AND (p_mailbox_id IS NULL OR l.mailbox_id = p_mailbox_id)
),
seq_totals AS (
  SELECT r.seq, count(*) AS n, max(r.at) AS last_at FROM rows r GROUP BY r.seq
),
lead_best AS (
  SELECT r.seq, r.lead_key, max(r.rank) AS rank FROM rows r GROUP BY r.seq, r.lead_key
),
responses AS (
  SELECT r.seq, r.lead_key, o.lead_intent, coalesce(o.meeting, false) AS meeting,
         (r.st = 'replied'
           AND (coalesce(o.meeting, false) OR o.lead_intent IS NULL
                OR o.lead_intent NOT IN ('out_of_office', 'auto_reply'))) AS genuine
  FROM rows r
  JOIN email_send_log s ON s.id = r.id
  LEFT JOIN LATERAL public.email_reply_outcome(p_org, s.recipient_email, r.mb) o ON true
  WHERE r.st IN ('replied', 'auto_replied')
),
response_leads AS (
  SELECT seq, lead_key,
         bool_or(genuine) AS is_reply,
         coalesce(bool_or(genuine AND (coalesce(lead_intent IN ('interested','meeting_booked'), false) OR meeting)), false) AS is_positive,
         coalesce(bool_or(genuine AND meeting), false) AS is_meeting
  FROM responses GROUP BY seq, lead_key
),
lead_agg AS (
  SELECT b.seq,
         count(*) AS n_leads,
         count(*) FILTER (WHERE b.rank NOT IN (0,6,7)) AS n_delivered,
         count(*) FILTER (WHERE rl.is_reply) AS n_replied,
         count(*) FILTER (WHERE rl.is_positive) AS n_positive,
         count(*) FILTER (WHERE rl.is_meeting) AS n_meetings,
         count(*) FILTER (WHERE b.rank = 6) AS n_bounced,
         count(*) FILTER (WHERE b.rank = 0) AS n_blocked,
         count(*) FILTER (WHERE rl.lead_key IS NOT NULL AND NOT rl.is_reply) AS n_auto
  FROM lead_best b
  LEFT JOIN response_leads rl ON rl.seq = b.seq AND rl.lead_key = b.lead_key
  GROUP BY b.seq
)
SELECT a.seq, es.name, es.status,
       t.n, a.n_leads, a.n_delivered, a.n_replied, a.n_positive, a.n_meetings, a.n_bounced, a.n_blocked, a.n_auto,
       t.last_at
FROM lead_agg a
JOIN seq_totals t ON t.seq = a.seq
LEFT JOIN email_sequences es ON es.id = a.seq
ORDER BY t.n DESC;
END;
$$;


ALTER FUNCTION "public"."get_email_sequence_performance"("p_org" "uuid", "p_start" timestamp with time zone, "p_end" timestamp with time zone, "p_mailbox_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_farm_campaign_stats"("campaign_uuid" "uuid", "target_date" "date" DEFAULT CURRENT_DATE) RETURNS TABLE("campaign_id" "uuid", "date" "date", "pieces_generated" integer, "pieces_published" integer, "derivatives_created" integer, "target_pieces" integer)
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    c.id AS campaign_id,
    target_date AS date,
    COUNT(DISTINCT ci.id) FILTER (WHERE DATE(ci.created_at) = target_date) AS pieces_generated,
    COUNT(DISTINCT ci.id) FILTER (WHERE DATE(ci.created_at) = target_date AND ci.status = 'published') AS pieces_published,
    COUNT(DISTINCT cd.id) FILTER (WHERE DATE(cd.created_at) = target_date) AS derivatives_created,
    (c.volume_targets->>'daily_pieces')::INTEGER AS target_pieces
  FROM campaigns c
  LEFT JOIN content_ideas ci ON ci.campaign_id = c.id
  LEFT JOIN content_derivatives cd ON cd.campaign_id = c.id
  WHERE c.id = campaign_uuid
  GROUP BY c.id;
END;
$$;


ALTER FUNCTION "public"."get_farm_campaign_stats"("campaign_uuid" "uuid", "target_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_filtered_lead_list_member_ids"("p_list_id" "uuid", "p_filters" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    SET "statement_timeout" TO '55s'
    AS $$
  SELECT COALESCE(jsonb_agg(r.contact_id ORDER BY r.added_at DESC, r.member_id DESC),'[]'::jsonb)
  FROM public.filter_lead_list_member_rows(p_list_id,p_filters,NULL,0) r;
$$;


