CREATE OR REPLACE FUNCTION "public"."get_filtered_lead_list_member_ids"("p_list_id" "uuid", "p_filters" "jsonb" DEFAULT '{}'::"jsonb", "p_limit" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    SET "statement_timeout" TO '55s'
    AS $$
  SELECT COALESCE(jsonb_agg(r.contact_id), '[]'::JSONB)
  FROM public.filter_lead_list_member_rows(p_list_id, p_filters, p_limit, 0) r;
$$;


ALTER FUNCTION "public"."get_filtered_lead_list_member_ids"("p_list_id" "uuid", "p_filters" "jsonb", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_idea_usage"("p_organization_id" "uuid") RETURNS TABLE("idea_id" "uuid", "used_count" integer, "last_used_at" timestamp with time zone, "autopilot_ids" "uuid"[])
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  SELECT
    co.idea_id,
    count(*)::int,
    max(co.created_at),
    coalesce(array_agg(DISTINCT co.autopilot_id) FILTER (WHERE co.autopilot_id IS NOT NULL), '{}'::uuid[])
  FROM public.content_outputs co
  WHERE co.organization_id = p_organization_id
    AND co.idea_id IS NOT NULL
    AND co.status <> 'failed'
  GROUP BY co.idea_id;
$$;


