CREATE OR REPLACE FUNCTION "public"."get_ideas_count_by_tag"("p_organization_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("tag_name" "text", "idea_count" bigint)
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    it.name AS tag_name,
    COUNT(DISTINCT ita.idea_id) AS idea_count
  FROM public.idea_tags it
  LEFT JOIN public.idea_tag_assignments ita ON ita.tag_id = it.id
  WHERE (p_organization_id IS NULL OR it.organization_id = p_organization_id)
  GROUP BY it.id, it.name
  ORDER BY it.name;
END;
$$;


ALTER FUNCTION "public"."get_ideas_count_by_tag"("p_organization_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_lead_handoffs_by_contacts"("p_org_id" "uuid", "p_contact_ids" "uuid"[], "p_tool_type" "text" DEFAULT NULL::"text", "p_connection_id" "uuid" DEFAULT NULL::"uuid", "p_external_campaign_id" "text" DEFAULT NULL::"text", "p_status" "text" DEFAULT NULL::"text", "p_deletion_status" "text" DEFAULT NULL::"text") RETURNS SETOF json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT row_to_json(t) FROM (
    SELECT
      h.*,
      json_build_object(
        'id', c.id,
        'display_name', c.display_name,
        'primary_email', c.primary_email,
        'company', c.company
      ) AS contact,
      CASE WHEN ec.id IS NOT NULL THEN
        json_build_object('id', ec.id, 'name', ec.name)
      ELSE NULL END AS connection
    FROM lead_handoffs h
    LEFT JOIN crm_contacts c ON c.id = h.contact_id
    LEFT JOIN email_tool_connections ec ON ec.id = h.connection_id
    WHERE h.organization_id = p_org_id
      AND h.contact_id = ANY(p_contact_ids)
      AND (p_tool_type IS NULL OR h.tool_type = p_tool_type)
      AND (p_connection_id IS NULL OR h.connection_id = p_connection_id)
      AND (p_external_campaign_id IS NULL OR h.external_campaign_id = p_external_campaign_id)
      AND (p_status IS NULL OR h.status = p_status)
      AND (
        p_deletion_status IS NULL
        OR (p_deletion_status = 'not_deleted' AND h.deletion_status IS NULL)
        OR (p_deletion_status <> 'not_deleted' AND h.deletion_status = p_deletion_status)
      )
    ORDER BY h.pushed_at DESC NULLS LAST
  ) t;
END;
$$;


ALTER FUNCTION "public"."get_lead_handoffs_by_contacts"("p_org_id" "uuid", "p_contact_ids" "uuid"[], "p_tool_type" "text", "p_connection_id" "uuid", "p_external_campaign_id" "text", "p_status" "text", "p_deletion_status" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_lead_list_ai_analysis_summary"("p_list_id" "uuid") RETURNS TABLE("total" bigint, "not_analyzed" bigint, "analyzing" bigint, "analyzed" bigint, "failed" bigint)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    SET "statement_timeout" TO '30s'
    AS $$
  SELECT
    COUNT(*)::BIGINT AS total,
    COUNT(*) FILTER (WHERE c.ai_analysis_status = 'not_analyzed')::BIGINT AS not_analyzed,
    COUNT(*) FILTER (WHERE c.ai_analysis_status = 'analyzing')::BIGINT AS analyzing,
    COUNT(*) FILTER (WHERE c.ai_analysis_status = 'analyzed')::BIGINT AS analyzed,
    COUNT(*) FILTER (WHERE c.ai_analysis_status = 'failed')::BIGINT AS failed
  FROM public.lead_list_members m
  INNER JOIN public.crm_contacts c ON c.id = m.contact_id
  INNER JOIN public.lead_lists l ON l.id = m.list_id
  WHERE m.list_id = p_list_id
    AND EXISTS (
      SELECT 1
      FROM public.organization_members om
      WHERE om.organization_id = l.organization_id
        AND om.user_id = auth.uid()
    );
$$;


