CREATE OR REPLACE FUNCTION "public"."get_lead_list_processing_llm_key_status"("p_list_id" "uuid") RETURNS TABLE("provider" "text", "model" "text", "key_configured" boolean, "key_valid" boolean, "health_status" "text", "health_reason" "text", "health_message" "text", "health_checked_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH selected_policy AS (
    SELECT policy.organization_id, policy.analyze_icp, policy.icp_llm_model
    FROM public.lead_list_processing_policies policy
    WHERE policy.lead_list_id = p_list_id
      AND EXISTS (
        SELECT 1
        FROM public.organization_members membership
        WHERE membership.organization_id = policy.organization_id
          AND membership.user_id = auth.uid()
      )
    LIMIT 1
  ), latest_key AS (
    SELECT DISTINCT ON (api_key.organization_id)
      api_key.organization_id,
      api_key.is_valid,
      api_key.metadata
    FROM public.api_keys api_key
    JOIN selected_policy ON selected_policy.organization_id = api_key.organization_id
    WHERE api_key.provider = 'openrouter'
    ORDER BY api_key.organization_id, api_key.updated_at DESC NULLS LAST, api_key.created_at DESC
  )
  SELECT
    'openrouter'::TEXT,
    selected_policy.icp_llm_model,
    latest_key.organization_id IS NOT NULL,
    COALESCE(latest_key.is_valid, FALSE),
    COALESCE(latest_key.metadata ->> 'health_status', CASE WHEN latest_key.is_valid = FALSE THEN 'invalid' ELSE 'healthy' END),
    latest_key.metadata ->> 'health_reason',
    latest_key.metadata ->> 'last_error',
    NULLIF(latest_key.metadata ->> 'health_checked_at', '')::TIMESTAMPTZ
  FROM selected_policy
  LEFT JOIN latest_key ON latest_key.organization_id = selected_policy.organization_id
  WHERE selected_policy.analyze_icp
    AND COALESCE(selected_policy.icp_llm_model, '') NOT LIKE 'ollama:%';
$$;


ALTER FUNCTION "public"."get_lead_list_processing_llm_key_status"("p_list_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_lead_list_processing_operational_metrics"("p_list_id" "uuid") RETURNS TABLE("total_people" bigint, "contacts_with_email" bigint, "valid_emails" bigint, "verified_emails" bigint, "email_searches_total" bigint, "email_found_total" bigint, "ready_contacts" bigint, "active_contacts" bigint, "completed_last_five_minutes" bigint, "stage_order" "text"[], "stage_icp_enabled" boolean, "stage_find_email_enabled" boolean, "stage_verify_email_enabled" boolean, "cleared_icp" bigint, "cleared_verify_email" bigint, "cleared_find_email" bigint, "enrolled" bigint, "no_email_searched" bigint, "no_email_unsearched" bigint, "analysis_reused" bigint, "analysis_ran" bigint)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    SET "plan_cache_mode" TO 'force_custom_plan'
    AS $$
  WITH policy AS (
    SELECT
      configured.organization_id,
      configured.stage_order,
      configured.analyze_icp,
      configured.find_email,
      configured.verify_email
    FROM public.lead_list_processing_policies configured
    WHERE configured.lead_list_id = p_list_id
      AND EXISTS (
        SELECT 1
        FROM public.organization_members membership
        WHERE membership.organization_id = configured.organization_id
          AND membership.user_id = auth.uid()
      )
    LIMIT 1
  ),
  stage_positions AS (
    SELECT
      configured.*,
      array_position(configured.stage_order, 'icp') AS icp_pos,
      array_position(configured.stage_order, 'verify_email') AS verify_pos,
      array_position(configured.stage_order, 'find_email') AS find_pos,
      array_position(configured.stage_order, 'enroll') AS enroll_pos,
      CASE
        WHEN configured.verify_email
             AND array_position(configured.stage_order, 'verify_email') IS NOT NULL
          THEN LEAST(
            array_position(configured.stage_order, 'find_email'),
            array_position(configured.stage_order, 'verify_email')
          )
        ELSE array_position(configured.stage_order, 'find_email')
      END AS find_effective_pos
    FROM policy configured
  ),
  lookup_by_contact AS (
    SELECT outcome.contact_id, true AS attempted
    FROM public.email_provider_lookup_outcomes outcome
    WHERE outcome.lead_list_id = p_list_id
    GROUP BY outcome.contact_id
  ),
  lookup_totals AS (
    SELECT
      COUNT(*) AS searches,
      COUNT(*) FILTER (WHERE outcome.outcome = 'found') AS found,
      COUNT(DISTINCT outcome.contact_id) FILTER (WHERE outcome.outcome = 'found') AS found_contacts
    FROM public.email_provider_lookup_outcomes outcome
    WHERE outcome.lead_list_id = p_list_id
  ),
  item_facts AS (
    SELECT
      item.*,
      positions.stage_order AS configured_stage_order,
      positions.analyze_icp,
      positions.find_email,
      positions.verify_email,
      positions.icp_pos,
      positions.verify_pos,
      positions.find_effective_pos,
      positions.enroll_pos,
      COALESCE(lookup.attempted, false) AS provider_attempted,
      CASE
        WHEN item.status = 'completed' THEN array_length(positions.stage_order, 1)
        WHEN item.status = 'rejected' THEN COALESCE(CASE
          WHEN item.rejected_reason ~ '^ICP score' THEN positions.icp_pos
          WHEN item.rejected_reason ~ 'No email found' THEN positions.find_effective_pos
          WHEN item.rejected_reason ~ '^Email status' OR item.rejected_reason ~ 'verification' THEN positions.verify_pos
          ELSE positions.icp_pos
        END - 1, 0)
        WHEN item.status IN ('failed', 'canceled') THEN COALESCE(CASE
          WHEN item.failure_category = 'no_source_data' THEN positions.icp_pos
          WHEN item.stage = 'finding_email' THEN positions.find_effective_pos
          WHEN item.stage = 'verifying_email' THEN positions.verify_pos
          ELSE positions.icp_pos
        END - 1, 0)
        WHEN item.stage = 'analyzing_icp' THEN positions.icp_pos - 1
        WHEN item.stage = 'finding_email' THEN positions.find_effective_pos - 1
        WHEN item.stage = 'verifying_email' THEN positions.verify_pos - 1
        WHEN item.stage IN ('enrolling', 'replacement_email_found', 'writing_message') THEN positions.enroll_pos - 1
        ELSE -1
      END AS progress_ordinal
    FROM public.lead_list_processing_items item
    CROSS JOIN stage_positions positions
    LEFT JOIN lookup_by_contact lookup ON lookup.contact_id = item.contact_id
    WHERE item.lead_list_id = p_list_id
  ),
  metrics AS (
    SELECT
      COUNT(*) AS total_people,
      COUNT(*) FILTER (WHERE fact.contact_has_email) AS contacts_with_email,
      COUNT(*) FILTER (WHERE fact.contact_email_verification_status = 'valid') AS valid_emails,
      COUNT(*) FILTER (
        WHERE fact.contact_email_verification_status IN ('valid', 'bad', 'catch_all', 'unknown')
      ) AS verified_emails,
      COUNT(*) FILTER (
        WHERE fact.status IN ('pending', 'retry') AND fact.next_attempt_at <= NOW()
      ) AS ready_contacts,
      COUNT(*) FILTER (WHERE fact.status = 'processing') AS active_contacts,
      COUNT(*) FILTER (
        WHERE (fact.status IN ('completed', 'rejected') AND fact.completed_at >= NOW() - INTERVAL '5 minutes')
           OR (fact.status = 'failed' AND fact.updated_at >= NOW() - INTERVAL '5 minutes')
      ) AS completed_last_five_minutes,
      COUNT(*) FILTER (WHERE fact.progress_ordinal > (fact.icp_pos - 1)) AS cleared_icp,
      COUNT(*) FILTER (WHERE fact.progress_ordinal >= array_length(fact.configured_stage_order, 1)) AS enrolled,
      COUNT(*) FILTER (
        WHERE NOT fact.contact_has_email
          AND (fact.contact_email_search_attempted OR fact.provider_attempted)
      ) AS no_email_searched,
      COUNT(*) FILTER (
        WHERE NOT fact.contact_has_email
          AND NOT fact.contact_email_search_attempted
          AND NOT fact.provider_attempted
      ) AS no_email_unsearched,
      COUNT(*) FILTER (WHERE fact.analyze_icp AND fact.analysis_reused) AS analysis_reused,
      COUNT(*) FILTER (
        WHERE fact.analyze_icp
          AND NOT fact.analysis_reused
          AND fact.stage NOT IN ('queued', 'analyzing_icp')
          AND NOT (fact.status = 'failed' AND fact.failure_category = 'no_source_data')
      ) AS analysis_ran
    FROM item_facts fact
  )
  SELECT
    metrics.total_people,
    metrics.contacts_with_email,
    metrics.valid_emails,
    metrics.verified_emails,
    lookup_totals.searches,
    lookup_totals.found,
    metrics.ready_contacts,
    metrics.active_contacts,
    metrics.completed_last_five_minutes,
    policy.stage_order,
    policy.analyze_icp,
    policy.find_email,
    policy.verify_email,
    metrics.cleared_icp,
    metrics.valid_emails,
    lookup_totals.found_contacts,
    metrics.enrolled,
    metrics.no_email_searched,
    metrics.no_email_unsearched,
    metrics.analysis_reused,
    metrics.analysis_ran
  FROM policy
  CROSS JOIN metrics
  CROSS JOIN lookup_totals;
$$;


ALTER FUNCTION "public"."get_lead_list_processing_operational_metrics"("p_list_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_lead_list_processing_provider_fairness"("p_list_id" "uuid") RETURNS TABLE("provider" "text", "active_lists" bigint, "list_waiting" bigint)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH selected_policy AS (
    SELECT policy.organization_id, policy.email_provider, policy.email_provider_chain
    FROM public.lead_list_processing_policies policy
    WHERE policy.lead_list_id = p_list_id
      AND EXISTS (SELECT 1 FROM public.organization_members member WHERE member.organization_id = policy.organization_id AND member.user_id = auth.uid())
    LIMIT 1
  ), providers AS (
    SELECT DISTINCT configured.provider
    FROM selected_policy
    CROSS JOIN LATERAL unnest(COALESCE(selected_policy.email_provider_chain, ARRAY[selected_policy.email_provider]::TEXT[])) configured(provider)
    WHERE configured.provider IS NOT NULL
  ), waiting AS (
    SELECT item.lead_list_id, policy.organization_id, policy.email_provider, policy.email_provider_chain
    FROM public.lead_list_processing_items item
    JOIN public.lead_list_processing_policies policy ON policy.id = item.policy_id
    WHERE item.status IN ('pending', 'retry') AND item.next_attempt_at <= NOW()
      AND item.stage = 'finding_email' AND policy.enabled = TRUE AND policy.paused_at IS NULL
  )
  SELECT provider.provider,
    COUNT(DISTINCT waiting.lead_list_id) FILTER (WHERE waiting.organization_id = selected_policy.organization_id
      AND (provider.provider = ANY(COALESCE(waiting.email_provider_chain, ARRAY[]::TEXT[])) OR waiting.email_provider = provider.provider)),
    COUNT(*) FILTER (WHERE waiting.lead_list_id = p_list_id
      AND (provider.provider = ANY(COALESCE(waiting.email_provider_chain, ARRAY[]::TEXT[])) OR waiting.email_provider = provider.provider))
  FROM selected_policy CROSS JOIN providers provider
  LEFT JOIN waiting ON waiting.organization_id = selected_policy.organization_id
  GROUP BY provider.provider;
$$;


ALTER FUNCTION "public"."get_lead_list_processing_provider_fairness"("p_list_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_lead_list_processing_provider_status"("p_list_id" "uuid") RETURNS TABLE("provider" "text", "chain_position" integer, "key_configured" boolean, "key_valid" boolean, "provider_plan" "text", "attempt_count" bigint, "running_count" bigint, "found_count" bigint, "not_found_count" bigint, "skipped_count" bigint, "failed_count" bigint, "last_attempt_at" timestamp with time zone, "last_success_at" timestamp with time zone, "last_error" "text", "daily_request_count" integer, "daily_cap" integer, "daily_found_count" bigint)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH selected_policy AS (
    SELECT policy.* FROM public.lead_list_processing_policies policy
    WHERE policy.lead_list_id = p_list_id
      AND EXISTS (SELECT 1 FROM public.organization_members membership
        WHERE membership.organization_id = policy.organization_id AND membership.user_id = auth.uid())
    LIMIT 1
  ),
  configured_providers AS (
    SELECT selected_policy.organization_id, configured.provider, configured.ordinality::INTEGER AS chain_position
    FROM selected_policy
    CROSS JOIN LATERAL unnest(
      CASE WHEN cardinality(COALESCE(selected_policy.email_provider_chain, ARRAY[]::TEXT[])) > 0 THEN selected_policy.email_provider_chain
           WHEN selected_policy.email_provider IS NOT NULL THEN ARRAY[selected_policy.email_provider]
           ELSE ARRAY[]::TEXT[] END
    ) WITH ORDINALITY AS configured(provider, ordinality)
  ),
  latest_keys AS (
    SELECT DISTINCT ON (api_key.organization_id, api_key.provider)
      api_key.organization_id, api_key.provider, TRUE AS key_configured,
      api_key.is_valid AS key_valid, api_key.metadata ->> 'plan' AS provider_plan
    FROM public.api_keys api_key
    JOIN selected_policy ON selected_policy.organization_id = api_key.organization_id
    WHERE api_key.provider IN ('apollo', 'hunter', 'prospeo', 'moltsets')
    ORDER BY api_key.organization_id, api_key.provider, api_key.updated_at DESC NULLS LAST, api_key.created_at DESC
  ),
  lookup_totals AS (
    SELECT outcome.provider,
      COUNT(*) FILTER (WHERE outcome.outcome = 'found') AS found_count,
      COUNT(*) FILTER (WHERE outcome.outcome = 'not_found') AS not_found_count
    FROM public.email_provider_lookup_outcomes outcome
    JOIN selected_policy ON selected_policy.lead_list_id = outcome.lead_list_id
    GROUP BY outcome.provider
  ),
  attempt_totals AS (
    SELECT attempt.provider, COUNT(*) AS attempt_count,
      COUNT(*) FILTER (WHERE attempt.status = 'running' AND attempt.started_at > NOW() - INTERVAL '15 minutes') AS running_count,
      COUNT(*) FILTER (WHERE attempt.status = 'skipped') AS skipped_count,
      COUNT(*) FILTER (WHERE attempt.status = 'failed' OR (attempt.status = 'running' AND attempt.started_at <= NOW() - INTERVAL '15 minutes')) AS failed_count,
      MAX(attempt.started_at) AS last_attempt_at,
      MAX(attempt.completed_at) FILTER (WHERE attempt.status = 'found') AS last_success_at,
      (ARRAY_AGG(COALESCE(attempt.error_message, attempt.error_code) ORDER BY attempt.started_at DESC)
        FILTER (WHERE attempt.status = 'failed' AND COALESCE(attempt.error_message, attempt.error_code) IS NOT NULL))[1] AS last_error
    FROM public.lead_list_processing_provider_attempts attempt
    JOIN selected_policy ON selected_policy.lead_list_id = attempt.lead_list_id
    GROUP BY attempt.provider
  ),
  daily_usage AS (
    SELECT usage.provider, usage.request_count, usage.daily_cap
    FROM public.enrichment_provider_daily_usage usage
    JOIN selected_policy ON selected_policy.organization_id = usage.organization_id
    WHERE usage.usage_date = CURRENT_DATE
  ),
  daily_success AS (
    SELECT history.provider, COUNT(*) FILTER (WHERE NULLIF(history.data_found ->> 'email', '') IS NOT NULL) AS found_count
    FROM public.enrichment_history history
    JOIN selected_policy ON selected_policy.organization_id = history.organization_id
    WHERE history.created_at >= CURRENT_DATE
    GROUP BY history.provider
  )
  SELECT configured.provider, configured.chain_position,
    COALESCE(latest_key.key_configured, FALSE), COALESCE(latest_key.key_valid, FALSE), latest_key.provider_plan,
    COALESCE(attempt.attempt_count, 0), COALESCE(attempt.running_count, 0),
    COALESCE(lookup.found_count, 0), COALESCE(lookup.not_found_count, 0),
    COALESCE(attempt.skipped_count, 0), COALESCE(attempt.failed_count, 0),
    attempt.last_attempt_at, attempt.last_success_at, attempt.last_error,
    usage.request_count, usage.daily_cap, COALESCE(success.found_count, 0)
  FROM configured_providers configured
  LEFT JOIN latest_keys latest_key ON latest_key.organization_id = configured.organization_id AND latest_key.provider = configured.provider
  LEFT JOIN lookup_totals lookup ON lookup.provider = configured.provider
  LEFT JOIN attempt_totals attempt ON attempt.provider = configured.provider
  LEFT JOIN daily_usage usage ON usage.provider = configured.provider
  LEFT JOIN daily_success success ON success.provider = configured.provider
  ORDER BY configured.chain_position;
$$;


ALTER FUNCTION "public"."get_lead_list_processing_provider_status"("p_list_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_lead_list_processing_status"("p_list_id" "uuid") RETURNS TABLE("item_status" "text", "item_stage" "text", "failure_category" "text", "recovery_exhausted" boolean, "item_count" bigint, "latest_updated_at" timestamp with time zone, "policy_paused_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT
    item.status,
    item.stage,
    item.failure_category,
    item.recovery_attempts >= 3 AS recovery_exhausted,
    COUNT(*),
    MAX(item.updated_at),
    MAX(policy.paused_at)
  FROM public.lead_list_processing_items item
  JOIN public.lead_list_processing_policies policy ON policy.id = item.policy_id
  WHERE item.lead_list_id = p_list_id
    AND EXISTS (
      SELECT 1
      FROM public.organization_members membership
      WHERE membership.organization_id = item.organization_id
        AND membership.user_id = auth.uid()
    )
  GROUP BY item.status, item.stage, item.failure_category, (item.recovery_attempts >= 3);
$$;


ALTER FUNCTION "public"."get_lead_list_processing_status"("p_list_id" "uuid") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."job_queue" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "job_type" "text" NOT NULL,
    "job_name" "text" NOT NULL,
    "payload" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "priority" integer DEFAULT 0 NOT NULL,
    "max_retries" integer DEFAULT 3 NOT NULL,
    "retry_count" integer DEFAULT 0 NOT NULL,
    "error_message" "text",
    "error_stack" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "scheduled_for" timestamp with time zone DEFAULT "now"() NOT NULL,
    "started_at" timestamp with time zone,
    "completed_at" timestamp with time zone,
    "expires_at" timestamp with time zone,
    "metadata" "jsonb" DEFAULT '{}'::"jsonb",
    CONSTRAINT "job_queue_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'processing'::"text", 'completed'::"text", 'failed'::"text", 'cancelled'::"text"])))
);


ALTER TABLE "public"."job_queue" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_next_job"("p_job_types" "text"[] DEFAULT NULL::"text"[]) RETURNS "public"."job_queue"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
DECLARE
    v_job job_queue;
BEGIN
    -- Get and lock the next pending job
    SELECT * INTO v_job
    FROM job_queue
    WHERE status = 'pending'
      AND scheduled_for <= NOW()
      AND (p_job_types IS NULL OR job_type = ANY(p_job_types))
    ORDER BY priority DESC, created_at ASC
    LIMIT 1
    FOR UPDATE SKIP LOCKED;

    -- Mark as processing
    IF FOUND THEN
        UPDATE job_queue
        SET status = 'processing',
            started_at = NOW()
        WHERE id = v_job.id;

        -- Fetch updated record
        SELECT * INTO v_job FROM job_queue WHERE id = v_job.id;
    END IF;

    RETURN v_job;
END;
$$;


ALTER FUNCTION "public"."get_next_job"("p_job_types" "text"[]) OWNER TO "postgres";


