CREATE OR REPLACE FUNCTION "public"."get_or_create_conversation"("p_org_id" "uuid", "p_contact_id" "uuid", "p_channel" "text", "p_channel_account_id" "uuid" DEFAULT NULL::"uuid", "p_external_conversation_id" "text" DEFAULT NULL::"text", "p_external_participant_id" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_conversation_id UUID;
BEGIN
  SELECT id INTO v_conversation_id FROM crm_conversations WHERE organization_id = p_org_id AND contact_id = p_contact_id AND channel = p_channel;
  IF v_conversation_id IS NULL THEN
    INSERT INTO crm_conversations (organization_id, contact_id, channel, channel_account_id, external_conversation_id, external_participant_id)
    VALUES (p_org_id, p_contact_id, p_channel, p_channel_account_id, p_external_conversation_id, p_external_participant_id)
    RETURNING id INTO v_conversation_id;
  ELSE
    UPDATE crm_conversations SET
      channel_account_id = COALESCE(p_channel_account_id, channel_account_id),
      external_conversation_id = COALESCE(p_external_conversation_id, external_conversation_id),
      external_participant_id = COALESCE(p_external_participant_id, external_participant_id),
      updated_at = NOW()
    WHERE id = v_conversation_id AND (
      (p_channel_account_id IS NOT NULL AND channel_account_id IS DISTINCT FROM p_channel_account_id)
      OR (p_external_conversation_id IS NOT NULL AND external_conversation_id IS DISTINCT FROM p_external_conversation_id)
      OR (p_external_participant_id IS NOT NULL AND external_participant_id IS DISTINCT FROM p_external_participant_id)
    );
  END IF;
  RETURN v_conversation_id;
END;
$$;


ALTER FUNCTION "public"."get_or_create_conversation"("p_org_id" "uuid", "p_contact_id" "uuid", "p_channel" "text", "p_channel_account_id" "uuid", "p_external_conversation_id" "text", "p_external_participant_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_or_create_conversation"("p_org_id" "uuid", "p_contact_id" "uuid", "p_channel" "text", "p_channel_account_id" "uuid" DEFAULT NULL::"uuid", "p_external_conversation_id" "text" DEFAULT NULL::"text", "p_external_participant_id" "text" DEFAULT NULL::"text", "p_mailbox_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_conversation_id UUID;
BEGIN
  IF p_channel = 'email' THEN
    SELECT id INTO v_conversation_id
    FROM crm_conversations
    WHERE organization_id = p_org_id
      AND contact_id = p_contact_id
      AND channel = p_channel
      AND mailbox_id IS NOT DISTINCT FROM p_mailbox_id;
  ELSE
    SELECT id INTO v_conversation_id
    FROM crm_conversations
    WHERE organization_id = p_org_id
      AND contact_id = p_contact_id
      AND channel = p_channel;
  END IF;

  IF v_conversation_id IS NULL THEN
    INSERT INTO crm_conversations (
      organization_id,
      contact_id,
      channel,
      channel_account_id,
      external_conversation_id,
      external_participant_id,
      mailbox_id
    ) VALUES (
      p_org_id,
      p_contact_id,
      p_channel,
      p_channel_account_id,
      p_external_conversation_id,
      p_external_participant_id,
      p_mailbox_id
    )
    RETURNING id INTO v_conversation_id;
  ELSE
    UPDATE crm_conversations
    SET
      channel_account_id = COALESCE(p_channel_account_id, channel_account_id),
      external_conversation_id = COALESCE(p_external_conversation_id, external_conversation_id),
      external_participant_id = COALESCE(p_external_participant_id, external_participant_id),
      mailbox_id = COALESCE(p_mailbox_id, mailbox_id),
      updated_at = NOW()
    WHERE id = v_conversation_id
      AND (
        (p_channel_account_id IS NOT NULL AND channel_account_id IS DISTINCT FROM p_channel_account_id)
        OR (p_external_conversation_id IS NOT NULL AND external_conversation_id IS DISTINCT FROM p_external_conversation_id)
        OR (p_external_participant_id IS NOT NULL AND external_participant_id IS DISTINCT FROM p_external_participant_id)
        OR (p_mailbox_id IS NOT NULL AND mailbox_id IS DISTINCT FROM p_mailbox_id)
      );
  END IF;

  RETURN v_conversation_id;
END;
$$;


ALTER FUNCTION "public"."get_or_create_conversation"("p_org_id" "uuid", "p_contact_id" "uuid", "p_channel" "text", "p_channel_account_id" "uuid", "p_external_conversation_id" "text", "p_external_participant_id" "text", "p_mailbox_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_org_lead_list_workflow_status"("p_org_id" "uuid") RETURNS TABLE("lead_list_id" "uuid", "policy_enabled" boolean, "policy_paused_at" timestamp with time zone, "total_count" bigint, "pending_count" bigint, "processing_count" bigint, "latest_updated_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT
    policy.lead_list_id,
    policy.enabled,
    policy.paused_at,
    COUNT(item.id) AS total_count,
    COALESCE(SUM(CASE WHEN item.status IN ('pending', 'retry') THEN 1 ELSE 0 END), 0) AS pending_count,
    COALESCE(SUM(CASE WHEN item.status = 'processing' THEN 1 ELSE 0 END), 0) AS processing_count,
    MAX(item.updated_at) AS latest_updated_at
  FROM public.lead_list_processing_policies policy
  LEFT JOIN public.lead_list_processing_items item
    ON item.lead_list_id = policy.lead_list_id
  WHERE policy.organization_id = p_org_id
    AND EXISTS (
      SELECT 1
      FROM public.organization_members membership
      WHERE membership.organization_id = p_org_id
        AND membership.user_id = auth.uid()
    )
  GROUP BY policy.lead_list_id, policy.enabled, policy.paused_at;
$$;


ALTER FUNCTION "public"."get_org_lead_list_workflow_status"("p_org_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_pending_crm_messages"("p_limit" integer DEFAULT 10, "p_channel" "text" DEFAULT NULL::"text") RETURNS TABLE("id" "uuid", "organization_id" "uuid", "conversation_id" "uuid", "contact_id" "uuid", "channel" "text", "channel_account_id" "uuid", "recipient_identity_id" "uuid", "recipient_external_id" "text", "recipient_display_name" "text", "content" "text", "content_type" "text", "attachments" "jsonb", "email_subject" "text", "email_cc" "text"[], "email_bcc" "text"[], "sender_type" "text", "sender_user_id" "uuid", "source_type" "text", "source_id" "uuid", "scheduled_for" timestamp with time zone, "priority" integer, "attempts" integer, "metadata" "jsonb")
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    mq.id,
    mq.organization_id,
    mq.conversation_id,
    mq.contact_id,
    mq.channel,
    mq.channel_account_id,
    mq.recipient_identity_id,
    mq.recipient_external_id,
    mq.recipient_display_name,
    mq.content,
    mq.content_type,
    mq.attachments,
    mq.email_subject,
    mq.email_cc,
    mq.email_bcc,
    mq.sender_type,
    mq.sender_user_id,
    mq.source_type,
    mq.source_id,
    mq.scheduled_for,
    mq.priority,
    mq.attempts,
    mq.metadata
  FROM crm_message_queue mq
  WHERE mq.status = 'pending'
    AND mq.scheduled_for <= NOW()
    AND mq.attempts < mq.max_attempts
    AND (p_channel IS NULL OR mq.channel = p_channel)
  ORDER BY mq.priority DESC, mq.scheduled_for ASC
  LIMIT p_limit
  FOR UPDATE SKIP LOCKED;
END;
$$;


ALTER FUNCTION "public"."get_pending_crm_messages"("p_limit" integer, "p_channel" "text") OWNER TO "postgres";


