CREATE OR REPLACE FUNCTION "public"."get_pending_webhook_events"("p_limit" integer DEFAULT 50) RETURNS TABLE("id" "uuid", "organization_id" "uuid", "event_type" "text", "event_data" "jsonb", "webhook_url" "text", "auth_header_name" "text", "auth_header_value" "text", "webhook_secret" "text", "attempt_count" integer, "max_attempts" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  WITH candidates AS (
    SELECT w.id AS event_id, w.webhook_url, w.scheduled_at
      FROM webhook_event_log w
     WHERE w.status IN ('pending', 'retrying')
       AND (w.next_retry_at IS NULL OR w.next_retry_at <= now())
       AND w.attempt_count < w.max_attempts
     ORDER BY w.scheduled_at ASC
     LIMIT GREATEST(p_limit, 1) * 20
  ),
  ranked AS (
    SELECT c.event_id,
           c.scheduled_at,
           ROW_NUMBER() OVER (PARTITION BY c.webhook_url ORDER BY c.scheduled_at ASC)
             AS rank_in_destination
      FROM candidates c
  ),
  picked AS (
    SELECT r.event_id
      FROM ranked r
     ORDER BY r.rank_in_destination ASC, r.scheduled_at ASC
     LIMIT p_limit
  ),
  locked AS (
    SELECT e.id
      FROM webhook_event_log e
      JOIN picked p ON p.event_id = e.id
     WHERE e.status IN ('pending', 'retrying')
       FOR UPDATE OF e SKIP LOCKED
  ),
  claimed AS (
    UPDATE webhook_event_log e
       SET status  = 'sending',
           sent_at = now()
     WHERE e.id IN (SELECT l.id FROM locked l)
    RETURNING e.id, e.organization_id, e.event_type, e.event_data,
              e.webhook_url, e.subscription_id, e.attempt_count,
              e.max_attempts, e.scheduled_at
  )
  SELECT
    c.id,
    c.organization_id,
    c.event_type,
    c.event_data,
    c.webhook_url,
    CASE WHEN c.subscription_id IS NOT NULL THEN sub.auth_header_name  ELSE s.auth_header_name  END,
    CASE WHEN c.subscription_id IS NOT NULL THEN sub.auth_header_value ELSE s.auth_header_value END,
    CASE WHEN c.subscription_id IS NOT NULL THEN sub.secret            ELSE s.webhook_secret    END,
    c.attempt_count,
    c.max_attempts
  FROM claimed c
  LEFT JOIN organization_webhook_settings s ON s.organization_id = c.organization_id
  LEFT JOIN webhook_subscriptions sub       ON sub.id = c.subscription_id
  ORDER BY c.scheduled_at ASC;
END;
$$;


ALTER FUNCTION "public"."get_pending_webhook_events"("p_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_pending_webhook_events"("p_limit" integer) IS 'Hands the delivery worker a batch, round-robin across destinations so a failing endpoint cannot starve healthy ones. Retains FOR UPDATE SKIP LOCKED so overlapping runs cannot double-deliver.';



