CREATE OR REPLACE FUNCTION "public"."get_suggested_blocks"("p_organization_id" "uuid", "p_product_ids" "uuid"[], "p_block_type" "text" DEFAULT NULL::"text") RETURNS TABLE("block_id" "uuid", "block_type" "text", "block_name" "text", "block_content" "text", "total_fit_score" bigint, "avg_fit_score" numeric)
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
BEGIN
  RETURN QUERY
  SELECT 
    b.id,
    b.block_type,
    b.name,
    b.content,
    COALESCE(SUM(pbf.fit_score), 0) AS total_fit_score,
    COALESCE(AVG(pbf.fit_score), 0) AS avg_fit_score
  FROM library_blocks b
  LEFT JOIN product_block_fit pbf ON pbf.block_id = b.id 
    AND pbf.product_id = ANY(p_product_ids)
  WHERE b.organization_id = p_organization_id
    AND (p_block_type IS NULL OR b.block_type = p_block_type)
  GROUP BY b.id, b.block_type, b.name, b.content
  ORDER BY total_fit_score DESC, b.name;
END;
$$;


ALTER FUNCTION "public"."get_suggested_blocks"("p_organization_id" "uuid", "p_product_ids" "uuid"[], "p_block_type" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_suggested_icps"("p_organization_id" "uuid", "p_product_ids" "uuid"[]) RETURNS TABLE("icp_id" "uuid", "icp_name" "text", "total_fit_score" bigint, "avg_fit_score" numeric, "matching_products" integer)
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
BEGIN
  RETURN QUERY
  SELECT 
    i.id,
    i.name,
    COALESCE(SUM(pif.fit_score), 0) AS total_fit_score,
    COALESCE(AVG(pif.fit_score), 0) AS avg_fit_score,
    COUNT(pif.product_id)::INTEGER AS matching_products
  FROM library_icps i
  LEFT JOIN product_icp_fit pif ON pif.icp_id = i.id 
    AND pif.product_id = ANY(p_product_ids)
  WHERE i.organization_id = p_organization_id
  GROUP BY i.id, i.name
  ORDER BY total_fit_score DESC, i.name;
END;
$$;


ALTER FUNCTION "public"."get_suggested_icps"("p_organization_id" "uuid", "p_product_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_trending_content"("p_org" "uuid", "p_platform" "text" DEFAULT NULL::"text", "p_days" integer DEFAULT 30, "p_min_ratio" numeric DEFAULT 2, "p_limit" integer DEFAULT 60, "p_only_unanalyzed" boolean DEFAULT false) RETURNS TABLE("id" "text", "platform" "text", "title" "text", "thumbnail_url" "text", "url" "text", "author_name" "text", "author_handle" "text", "author_avatar_url" "text", "published_at" timestamp with time zone, "engagement" "jsonb", "source" "text", "score" numeric, "baseline" numeric, "baseline_basis" "text", "ratio" numeric, "percentile" numeric, "velocity_per_day" numeric, "growth_7d" numeric, "fit_score" numeric, "fit_reason" "text", "analyzed" boolean, "format" "text", "hook_type" "text", "formula" "text", "worth" numeric)
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $$
#variable_conflict use_column
BEGIN
  IF coalesce(auth.role(), '') <> 'service_role'
     AND NOT (p_org IN (SELECT get_accessible_organization_ids())) THEN
    RAISE EXCEPTION 'Not allowed to read this organization' USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  WITH pool AS (
    SELECT rc.id, rc.platform, rc.published_at, rc.search_term_id,
           coalesce(rc.creator_id::text, 'h:' || lower(nullif(rc.author_handle, '')),
                    'n:' || lower(nullif(rc.author_name, '')), 'id:' || rc.id::text) AS author_key,
           research_engagement_score(rc.platform, rc.engagement) AS score,
           nullif(coalesce(rc.author_audience, cr.follower_count, cr.subscriber_count), 0)::numeric AS audience
    FROM research_content rc
    LEFT JOIN research_creators cr ON cr.id = rc.creator_id
    WHERE rc.organization_id = p_org
      AND rc.source <> 'paste'
      -- retweets carry the original's views: they'd duplicate it and skew the retweeter's median
      AND NOT coalesce((rc.platform_data->>'isRetweet')::boolean, false)
      AND coalesce(rc.title, '') NOT LIKE 'RT @%'
      -- a reply is part of someone else's thread, not a post worth copying
      AND NOT coalesce((rc.platform_data->>'isReply')::boolean, false)
      AND rc.published_at > now() - interval '180 days'
      AND (p_platform IS NULL OR rc.platform = p_platform)
  ),
  author_stats AS (
    SELECT author_key, platform, count(*) AS n,
           percentile_cont(0.5) WITHIN GROUP (ORDER BY score)::numeric AS med
    FROM pool GROUP BY author_key, platform
  ),
  audience_rate AS (
    SELECT platform, percentile_cont(0.5) WITHIN GROUP (ORDER BY score / audience)::numeric AS rate
    FROM pool WHERE audience > 0 AND score > 0 GROUP BY platform
  ),
  term_stats AS (
    SELECT platform, search_term_id, count(*) AS n,
           percentile_cont(0.5) WITHIN GROUP (ORDER BY score)::numeric AS med
    FROM pool WHERE search_term_id IS NOT NULL GROUP BY platform, search_term_id
  ),
  platform_stats AS (
    SELECT platform, percentile_cont(0.5) WITHIN GROUP (ORDER BY score)::numeric AS med
    FROM pool GROUP BY platform
  ),
  scored AS (
    SELECT p.*,
      -- never expect less than the platform median: a tiny account's estimate
      -- (4 views) turns an ordinary 1,750-view post into a "411x" outlier
      greatest(CASE
        WHEN a.n >= 5 AND a.med > 0 THEN a.med
        WHEN p.audience > 0 AND ar.rate > 0 THEN p.audience * ar.rate
        WHEN t.n >= 10 AND t.med > 0 THEN t.med
        ELSE ps.med
      END, ps.med) AS base,
      CASE
        WHEN a.n >= 5 AND a.med > 0 THEN 'author'
        WHEN p.audience > 0 AND ar.rate > 0 THEN 'audience'
        WHEN t.n >= 10 AND t.med > 0 THEN 'search_term'
        ELSE 'platform'
      END AS basis,
      percent_rank() OVER (PARTITION BY p.platform ORDER BY p.score)::numeric AS pct
    FROM pool p
    JOIN author_stats a ON a.author_key = p.author_key AND a.platform = p.platform
    LEFT JOIN audience_rate ar ON ar.platform = p.platform
    LEFT JOIN term_stats t ON t.platform = p.platform AND t.search_term_id = p.search_term_id
    LEFT JOIN platform_stats ps ON ps.platform = p.platform
  ),
  candidates AS (
    SELECT s.*, round(s.score / greatest(s.base, 1), 2) AS ratio
    FROM scored s
    WHERE s.published_at > now() - make_interval(days => p_days)
      AND s.score > 0
  ),
  ranked AS (
    SELECT c.*,
           rc.ai_analysis,
           rc.analyzed_at,
           research_safe_numeric(rc.ai_analysis->'fit'->>'score') AS fit,
           -- fit 10 keeps the full ratio, fit 0 keeps 40%; unanalyzed posts count as fit 3.5
           -- so a raw view spike can't outrank posts already judged relevant
           round(c.ratio * (0.4 + 0.06 * least(greatest(coalesce(research_safe_numeric(rc.ai_analysis->'fit'->>'score'), 3.5), 0), 10)), 2) AS worth
    FROM candidates c
    JOIN research_content rc ON rc.id = c.id
    -- an outlier must also clear the platform median in absolute terms, so a tiny
    -- account beating its own tiny baseline (14 views = "3x") doesn't qualify
    -- a top-3% post still has to beat its own baseline: raw reach alone (a big
    -- account's ordinary post) isn't an outlier
    WHERE ((c.ratio >= p_min_ratio AND c.pct >= 0.5) OR (c.pct >= 0.97 AND c.ratio >= 1.5))
      -- once analyzed, off-niche posts are dropped rather than just discounted
      AND coalesce(research_safe_numeric(rc.ai_analysis->'fit'->>'score'), 10) >= 4
      -- analyzed_at is also set on a failed auto attempt, so those aren't retried hourly
      AND (NOT p_only_unanalyzed OR rc.analyzed_at IS NULL)
  ),
  diverse AS (
    -- at most 3 per author so one prolific creator can't fill the list
    SELECT r.*, row_number() OVER (PARTITION BY r.author_key ORDER BY r.worth DESC) AS author_rank
    FROM ranked r
  )
  SELECT rc.id, rc.platform, rc.title, rc.thumbnail_url, rc.url,
         rc.author_name, rc.author_handle, rc.author_avatar_url,
         rc.published_at, rc.engagement, rc.source,
         d.score, round(d.base, 2), d.basis, d.ratio, round(d.pct, 4),
         round(d.score / greatest(extract(epoch FROM now() - rc.published_at) / 86400, 1)::numeric, 2),
         g.growth,
         d.fit,
         d.ai_analysis->'fit'->>'reason',
         d.analyzed_at IS NOT NULL AND d.ai_analysis ? '_meta',
         d.ai_analysis->>'format',
         d.ai_analysis->'hook'->>'type',
         d.ai_analysis->>'formula',
         d.worth
  FROM diverse d
  JOIN research_content rc ON rc.id = d.id
  LEFT JOIN LATERAL (
    SELECT max(m.score) - min(m.score) AS growth
    FROM research_content_metrics m
    WHERE m.content_id = d.id AND m.captured_at > now() - interval '7 days'
    HAVING count(*) > 1
  ) g ON true
  WHERE d.author_rank <= 3
  ORDER BY d.worth DESC, d.ratio DESC
  LIMIT p_limit;
END;
$$;


