CREATE OR REPLACE FUNCTION "public"."get_user_org_role"("p_user_id" "uuid", "p_organization_id" "uuid") RETURNS character varying
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_role VARCHAR;
BEGIN
  -- First check if super admin
  IF is_super_admin(p_user_id) THEN
    RETURN 'super_admin';
  END IF;
  
  -- Check organization membership
  SELECT role INTO v_role
  FROM organization_members
  WHERE user_id = p_user_id
    AND organization_id = p_organization_id;
    
  RETURN v_role;
END;
$$;


