CREATE OR REPLACE FUNCTION "public"."guard_active_lead_processing_policy_changes"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_config_changed BOOLEAN;
  v_has_active BOOLEAN;
  v_has_processing BOOLEAN;
BEGIN
  v_config_changed := (
    to_jsonb(NEW) - ARRAY['id', 'organization_id', 'lead_list_id', 'enabled', 'paused_at', 'created_at', 'updated_at']
  ) IS DISTINCT FROM (
    to_jsonb(OLD) - ARRAY['id', 'organization_id', 'lead_list_id', 'enabled', 'paused_at', 'created_at', 'updated_at']
  );

  IF NOT v_config_changed THEN
    RETURN NEW;
  END IF;

  SELECT
    EXISTS (
      SELECT 1 FROM public.lead_list_processing_items item
      WHERE item.policy_id = OLD.id
        AND item.status IN ('pending', 'retry', 'processing')
    ),
    EXISTS (
      SELECT 1 FROM public.lead_list_processing_items item
      WHERE item.policy_id = OLD.id
        AND item.status = 'processing'
    )
  INTO v_has_active, v_has_processing;

  IF v_has_active AND (OLD.paused_at IS NULL OR v_has_processing) THEN
    RAISE EXCEPTION 'Pause this workflow and wait for active contacts to park before changing its processing settings';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."guard_active_lead_processing_policy_changes"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."guard_burned_domain_mailbox"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NEW.status IS DISTINCT FROM 'ready' OR NEW.sending_domain_id IS NULL THEN RETURN NEW; END IF;
  IF public.is_sending_domain_sendable(NEW.sending_domain_id) THEN RETURN NEW; END IF;
  NEW.status := 'paused';
  -- Never take ownership of a hold already owned by another subsystem/human.
  IF coalesce(NEW.metadata->>'paused_reason', '') NOT IN ('', 'domain_paused', 'domain_not_sendable') THEN
    RETURN NEW;
  END IF;
  NEW.metadata := coalesce(NEW.metadata, '{}'::jsonb) || jsonb_build_object(
    'paused_reason', 'domain_paused', 'paused_at', now(),
    'domain_pause_previous_status', 'ready', 'domain_pause_id', NEW.sending_domain_id::text);
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."guard_burned_domain_mailbox"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."guard_burned_domain_mailbox"() IS 'Refuses status=ready for a mailbox whose sending domain is not in sendable_sending_domains. Replaces the manual paused sweep, which any re-provision undid.';



CREATE OR REPLACE FUNCTION "public"."guard_organization_network_columns"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  -- session_user, not current_user: inside this SECURITY DEFINER function
  -- current_user is always the owner. session_user is 'authenticator' for API
  -- requests and 'postgres' for the SQL editor / migrations.
  IF current_setting('aca.network_write', true) = 'on'
     OR auth.role() = 'service_role'
     OR session_user IN ('postgres', 'supabase_admin')
     OR is_super_admin(auth.uid()) THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'INSERT' THEN
    NEW.network_status := 'none';
    NEW.network_only := false;
    NEW.network_application := NULL;
    NEW.network_requested_at := NULL;
    NEW.network_reviewed_at := NULL;
    NEW.network_reviewed_by := NULL;
    NEW.network_review_note := NULL;
    NEW.network_billing_ready_at := NULL;
    RETURN NEW;
  END IF;

  IF NEW.network_status IS DISTINCT FROM OLD.network_status
     OR NEW.network_only IS DISTINCT FROM OLD.network_only
     OR NEW.network_application IS DISTINCT FROM OLD.network_application
     OR NEW.network_requested_at IS DISTINCT FROM OLD.network_requested_at
     OR NEW.network_reviewed_at IS DISTINCT FROM OLD.network_reviewed_at
     OR NEW.network_reviewed_by IS DISTINCT FROM OLD.network_reviewed_by
     OR NEW.network_review_note IS DISTINCT FROM OLD.network_review_note
     OR NEW.network_billing_ready_at IS DISTINCT FROM OLD.network_billing_ready_at THEN
    RAISE EXCEPTION 'ACA Network fields can only be changed through request_network_access or by ACA staff'
      USING ERRCODE = '42501';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."guard_organization_network_columns"() OWNER TO "postgres";


