CREATE OR REPLACE FUNCTION "public"."handle_mailbox_disconnected"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  -- Park: mailbox leaving 'ready'.
  IF OLD.status = 'ready' AND NEW.status != 'ready' THEN

    -- Not yet started (step 0): clear the mailbox so the processor re-picks one.
    -- These are safe to re-home because nothing has been sent for them yet.
    UPDATE email_sequence_enrollments
    SET
      mailbox_id = NULL,
      updated_at = NOW()
    WHERE mailbox_id = OLD.id
      AND status = 'active'
      AND current_step = 0;

    -- Already started (step > 0): freeze. Follow-ups are sender-enforced to stay
    -- in the same inbox and thread (resolveContinuationAnchor), so silently
    -- moving step 3 to another address would start a fresh thread from a
    -- stranger. Freezing keeps the choice with a human.
    UPDATE email_sequence_enrollments
    SET
      status = 'sender_disconnected',
      updated_at = NOW()
    WHERE mailbox_id = OLD.id
      AND status = 'active'
      AND current_step > 0;

  END IF;

  -- Restore: mailbox coming back to 'ready'. The mailbox that owns the thread is
  -- usable again, so the enrollments it stranded can resume exactly where they
  -- left off — same inbox, same thread, which is why they were held rather than
  -- re-homed in the first place.
  IF OLD.status IS DISTINCT FROM 'ready' AND NEW.status = 'ready' THEN
    UPDATE email_sequence_enrollments
    SET
      status = 'active',
      -- Never leave next_send_at NULL or in the distant past: a NULL strands the
      -- row outside every due-query (the recurring "active + NULL next_send_at"
      -- bug), and a long-stale timestamp makes the whole parked cohort due at
      -- once. Clamping to now() releases them into the normal pacing, where
      -- per-mailbox daily limits and business hours throttle the rate.
      next_send_at = GREATEST(COALESCE(next_send_at, NOW()), NOW()),
      updated_at = NOW()
    WHERE mailbox_id = NEW.id
      AND status = 'sender_disconnected';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."handle_mailbox_disconnected"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."handle_mailbox_disconnected"() IS 'Parks in-flight email enrollments when a mailbox leaves ready, and releases them when it returns. Mirrors handle_sender_account_disconnected() on the LinkedIn side.';



CREATE OR REPLACE FUNCTION "public"."handle_new_user"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_full_name TEXT;
  v_org_id UUID;
  v_org_slug TEXT;
  v_org_name TEXT;
BEGIN
  -- Skip if this user was created via community signup flow
  -- The create-community-account edge function handles org/user creation for these users
  IF NEW.raw_user_meta_data->>'source' = 'community_signup' THEN
    RETURN NEW;
  END IF;

  -- Extract full name from user metadata or email
  v_full_name := COALESCE(
    NEW.raw_user_meta_data->>'full_name',
    NEW.raw_user_meta_data->>'name',
    split_part(NEW.email, '@', 1)
  );

  -- Generate organization slug from email
  v_org_slug := LOWER(REPLACE(split_part(NEW.email, '@', 1), '.', '-')) || '-' || SUBSTRING(NEW.id::TEXT, 1, 8);
  v_org_name := COALESCE(v_full_name, split_part(NEW.email, '@', 1)) || '''s Workspace';

  -- Create organization first
  INSERT INTO organizations (
    name,
    slug,
    type,
    status,
    plan_tier,
    settings,
    limits,
    current_usage
  ) VALUES (
    v_org_name,
    v_org_slug,
    'standalone',
    'active',
    'free',
    '{}'::jsonb,
    '{}'::jsonb,
    jsonb_build_object(
      'daily', jsonb_build_object('generations', 0, 'cost', 0, 'date', CURRENT_DATE::TEXT),
      'monthly', jsonb_build_object('generations', 0, 'cost', 0, 'month', TO_CHAR(CURRENT_DATE, 'YYYY-MM')),
      'all_time', jsonb_build_object('generations', 0, 'cost', 0)
    )
  )
  RETURNING id INTO v_org_id;

  -- Create user record in users table
  INSERT INTO users (
    id,
    email,
    full_name,
    organization_id,
    role,
    avatar_url,
    is_super_admin
  ) VALUES (
    NEW.id,
    NEW.email,
    v_full_name,
    v_org_id,
    'owner',
    NEW.raw_user_meta_data->>'avatar_url',
    false
  );

  -- Create organization member entry
  INSERT INTO organization_members (
    user_id,
    organization_id,
    role,
    is_primary_owner
  ) VALUES (
    NEW.id,
    v_org_id,
    'owner',
    true
  );

  -- Create organization_settings with onboarding not completed
  INSERT INTO organization_settings (
    organization_id,
    onboarding_completed,
    onboarding_step
  ) VALUES (
    v_org_id,
    false,
    'welcome'
  );

  RETURN NEW;
EXCEPTION
  WHEN OTHERS THEN
    -- Log error but don't block user creation
    RAISE WARNING 'Error in handle_new_user: %', SQLERRM;
    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."handle_new_user"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."handle_new_user"() IS 'Creates user record and organization when a new auth user signs up. Includes slug generation and uses standalone type.';



CREATE OR REPLACE FUNCTION "public"."handle_sender_account_disconnected"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF OLD.status = 'active' AND NEW.status != 'active' THEN
    UPDATE campaign_lead_progress
    SET sender_account_id = NULL,
        updated_at = NOW()
    WHERE sender_account_id = OLD.id
      AND status = 'pending'
      AND current_node_id IS NULL
      AND connection_sent_at IS NULL;

    UPDATE campaign_lead_progress
    SET status = 'sender_disconnected',
        error_message = 'Sender account disconnected (' || NEW.status || '): '
                        || COALESCE(NEW.error_message, 'Account unavailable'),
        updated_at = NOW()
    WHERE sender_account_id = OLD.id
      AND status NOT IN ('completed', 'failed', 'skipped', 'replied', 'handed_off', 'sender_disconnected')
      AND NOT (status = 'pending' AND current_node_id IS NULL AND connection_sent_at IS NULL);
  END IF;

  -- Reconnect: un-park the leads this account left stranded.
  IF OLD.status IS DISTINCT FROM 'active' AND NEW.status = 'active' THEN
    UPDATE campaign_lead_progress
    SET status = 'waiting',
        error_message = NULL,
        updated_at = NOW()
    WHERE sender_account_id = NEW.id
      AND status = 'sender_disconnected';
  END IF;

  IF NEW.status = 'disconnected' AND OLD.status IS DISTINCT FROM 'disconnected' THEN
    PERFORM scrub_disconnected_sender_links(NEW.id);
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."handle_sender_account_disconnected"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."hydrate_aca_native_contact_signal"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_signal public.public_signals%ROWTYPE;
  v_details jsonb;
BEGIN
  IF NEW.source <> 'aca_native_signal' THEN RETURN NEW; END IF;
  IF coalesce(NEW.source_details->>'public_signal_id', '') ~*
     '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' THEN
    SELECT * INTO v_signal FROM public.public_signals
    WHERE id = (NEW.source_details->>'public_signal_id')::uuid;
  ELSIF NEW.signal_event_id IS NOT NULL THEN
    SELECT * INTO v_signal FROM public.public_signals
    WHERE metadata->>'signal_event_id' = NEW.signal_event_id::text
    ORDER BY signal_date DESC LIMIT 1;
  END IF;
  IF v_signal.id IS NULL THEN RETURN NEW; END IF;

  v_details := coalesce(v_signal.metadata->'signal_details', '{}'::jsonb);
  NEW.signal_event_id := nullif(v_signal.metadata->>'signal_event_id', '')::uuid;
  NEW.signal_type := v_signal.signal_type;
  NEW.signal_date := v_signal.signal_date;
  NEW.signal_title := v_signal.title;
  NEW.signal_detail := coalesce(v_signal.summary, v_signal.title);
  NEW.signal_why_it_matters := v_signal.why_it_matters;
  NEW.signal_source_url := v_signal.source_url;
  NEW.signal_role_count := CASE WHEN coalesce(v_details->>'new_role_count', '') ~ '^\d+$'
    THEN (v_details->>'new_role_count')::integer END;
  NEW.signal_total_open_roles := CASE WHEN coalesce(v_details->>'total_open_roles', '') ~ '^\d+$'
    THEN (v_details->>'total_open_roles')::integer END;
  NEW.signal_role_titles := CASE WHEN jsonb_typeof(v_details->'role_titles') = 'array'
    THEN ARRAY(SELECT jsonb_array_elements_text(v_details->'role_titles')) END;
  NEW.signal_locations := CASE WHEN jsonb_typeof(v_details->'locations') = 'array'
    THEN ARRAY(SELECT jsonb_array_elements_text(v_details->'locations')) END;
  NEW.signal_amount_label := v_signal.amount_label;
  NEW.signal_amount_usd := v_signal.amount_usd;
  NEW.discovery_metadata := coalesce(NEW.discovery_metadata, '{}'::jsonb)
    || jsonb_strip_nulls(jsonb_build_object(
      'signal_type', NEW.signal_type,
      'signal_event_id', NEW.signal_event_id,
      'signal_date', to_char(NEW.signal_date, 'YYYY-MM-DD'),
      'signal_title', NEW.signal_title,
      'signal_detail', NEW.signal_detail,
      'signal_why_it_matters', NEW.signal_why_it_matters,
      'signal_source_url', NEW.signal_source_url,
      'signal_amount_label', NEW.signal_amount_label,
      'signal_amount_usd', NEW.signal_amount_usd,
      'signal_details', v_details,
      'signal_outreach_context', NEW.signal_detail
    ));
  RETURN NEW;
END;
$_$;


ALTER FUNCTION "public"."hydrate_aca_native_contact_signal"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."hydrate_aca_native_public_signal"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_event record;
  v_presentation jsonb;
BEGIN
  IF NEW.source_key <> 'aca_native'
     OR coalesce(NEW.metadata->>'signal_event_id', '') !~*
       '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' THEN
    RETURN NEW;
  END IF;
  SELECT event_type, payload INTO v_event
  FROM public.signal_events
  WHERE id = (NEW.metadata->>'signal_event_id')::uuid;
  IF NOT FOUND THEN RETURN NEW; END IF;

  v_presentation := CASE WHEN v_event.event_type = 'acquisition'
    THEN public.native_acquisition_signal_presentation(NEW.company_name, v_event.payload)
    ELSE public.native_signal_presentation(NEW.company_name, v_event.event_type, v_event.payload) END;
  NEW.title := v_presentation->>'title';
  NEW.summary := v_presentation->>'detail';
  NEW.why_it_matters := v_presentation->>'why_it_matters';
  NEW.amount_label := v_presentation->>'amount_label';
  NEW.amount_usd := nullif(v_presentation->>'amount_usd', '')::numeric;
  NEW.metadata := coalesce(NEW.metadata, '{}'::jsonb)
    || jsonb_build_object('signal_details', v_presentation->'details');
  RETURN NEW;
END;
$_$;


ALTER FUNCTION "public"."hydrate_aca_native_public_signal"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."hydrate_public_signal_contact_email"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_email text;
  v_status text;
BEGIN
  IF NULLIF(btrim(COALESCE(NEW.primary_email, '')), '') IS NOT NULL
     OR NULLIF(btrim(COALESCE(NEW.primary_linkedin_url, '')), '') IS NULL THEN
    RETURN NEW;
  END IF;

  IF NOT (
    NEW.source = 'public_signal'
    OR COALESCE(NEW.discovery_metadata ->> 'source', '') = 'public_signal'
    OR COALESCE(NEW.source_details ->> 'public_signal_id', '') <> ''
  ) THEN
    RETURN NEW;
  END IF;

  SELECT lower(btrim(p.email)), lower(btrim(COALESCE(p.email_status, 'unknown')))
    INTO v_email, v_status
  FROM public.public_signal_people p
  WHERE p.linkedin_url = NEW.primary_linkedin_url
    AND NULLIF(btrim(COALESCE(p.email, '')), '') IS NOT NULL
    AND NOT EXISTS (
      SELECT 1
      FROM public.crm_contacts existing
      WHERE existing.organization_id = NEW.organization_id
        AND lower(existing.primary_email) = lower(p.email)
        AND existing.id IS DISTINCT FROM NEW.id
    )
  ORDER BY
    CASE lower(COALESCE(p.email_status, ''))
      WHEN 'valid' THEN 1
      WHEN 'verified' THEN 2
      WHEN 'catch_all' THEN 3
      WHEN 'catch-all' THEN 3
      ELSE 4
    END,
    p.enriched_at DESC NULLS LAST
  LIMIT 1;

  IF v_email IS NULL THEN
    RETURN NEW;
  END IF;

  NEW.primary_email := v_email;
  NEW.email_verification_status := CASE
    WHEN v_status IN ('valid', 'verified') THEN 'valid'
    WHEN v_status IN ('catch_all', 'catch-all') THEN 'catch_all'
    ELSE 'unknown'
  END;
  NEW.email_is_deliverable := v_status IN ('valid', 'verified');
  NEW.email_is_catch_all := v_status IN ('catch_all', 'catch-all');
  NEW.email_verified_at := CASE
    WHEN v_status IN ('valid', 'verified') THEN COALESCE(NEW.email_verified_at, now())
    ELSE NEW.email_verified_at
  END;
  NEW.email_verification_source := COALESCE(NEW.email_verification_source, 'moltsets_signal');
  NEW.enrichment_data := COALESCE(NEW.enrichment_data, '{}'::jsonb) || jsonb_build_object(
    'email_status', v_status,
    'email_source', 'public_signal_people',
    'public_signal_email_backfilled', true
  );
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."hydrate_public_signal_contact_email"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."import_pool_rows_to_list"("p_list_id" "uuid", "p_org_id" "uuid", "p_rows" "jsonb") RETURNS TABLE("inserted_contacts" integer, "added_members" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    SET "statement_timeout" TO '120s'
    AS $$
DECLARE
  v_inserted_count int := 0;
  v_member_count   int := 0;
BEGIN
  WITH desired AS (
    SELECT DISTINCT ON (lower(r->>'email'))
      lower(r->>'email') AS email_lc,
      NULLIF(r->>'first_name', '\N')          AS first_name,
      NULLIF(r->>'last_name', '\N')           AS last_name,
      NULLIF(r->>'mobile_phone', '\N')        AS phone,
      NULLIF(r->>'person_linkedin_url', '\N') AS linkedin,
      NULLIF(r->>'title', '\N')               AS title,
      NULLIF(r->>'company', '\N')             AS company,
      r->>'domain'                             AS domain,
      NULLIF(r->>'person_city', '\N')         AS city,
      NULLIF(r->>'person_state', '\N')        AS state,
      jsonb_strip_nulls(jsonb_build_object(
        'industry',          NULLIF(r->>'industry', '\N'),
        'p_industry',        NULLIF(r->>'p_industry', '\N'),
        'p_bucket',          NULLIF(r->>'p_bucket', '\N'),
        'sic_code',          NULLIF(r->>'sic_code', '\N'),
        'department',        NULLIF(r->>'department', '\N'),
        'seniority',         NULLIF(r->>'seniority', '\N'),
        'employees',         CASE
                                WHEN r->>'employees' IS NULL OR r->>'employees' IN ('','\N')
                                  THEN NULL
                                ELSE (r->>'employees')::int
                             END,
        'employees_range',   NULLIF(r->>'employees_range', '\N'),
        'employees_max',     CASE
                                WHEN r->>'employees_max' IS NULL OR r->>'employees_max' IN ('','\N')
                                  THEN NULL
                                ELSE (r->>'employees_max')::int
                             END,
        'annual_revenue',    NULLIF(r->>'annual_revenue', '\N'),
        'company_phone',     NULLIF(r->>'company_phone', '\N'),
        'company_linkedin',  NULLIF(r->>'company_linkedin_url', '\N'),
        'company_address',   NULLIF(r->>'company_address', '\N'),
        'company_city',      NULLIF(r->>'company_city', '\N'),
        'company_state',     NULLIF(r->>'company_state', '\N'),
        'company_zip',       NULLIF(r->>'company_zip', '\N'),
        'email_status',      NULLIF(r->>'email_status', '\N'),
        'personal_emails',   NULLIF(r->>'personal_emails', '\N')
      )) AS pool_data
    FROM jsonb_array_elements(p_rows) r
    WHERE r->>'email' IS NOT NULL AND r->>'email' <> ''
  ),
  to_insert AS (
    SELECT d.*
    FROM desired d
    WHERE NOT EXISTS (
      SELECT 1 FROM public.crm_contacts c
      WHERE c.organization_id = p_org_id
        AND (
          c.primary_email = d.email_lc
          OR (d.linkedin IS NOT NULL AND c.primary_linkedin_url = d.linkedin)
        )
    )
  ),
  to_insert_uniq AS (
    SELECT DISTINCT ON (COALESCE(linkedin, email_lc)) *
    FROM to_insert
    ORDER BY COALESCE(linkedin, email_lc), email_lc
  ),
  inserted AS (
    INSERT INTO public.crm_contacts (
      organization_id,
      first_name, last_name, display_name,
      primary_email, primary_phone, primary_linkedin_url,
      job_title, company, company_website,
      city, state, country, source,
      custom_fields
    )
    SELECT
      p_org_id,
      first_name, last_name,
      COALESCE(
        NULLIF(trim(COALESCE(first_name,'') || ' ' || COALESCE(last_name,'')), ''),
        email_lc
      ),
      email_lc, phone, linkedin,
      title, company,
      CASE WHEN domain IS NULL OR domain IN ('','\N') THEN NULL
           ELSE 'https://' || domain END,
      city, state, 'US', 'pool_export',
      pool_data
    FROM to_insert_uniq
    ON CONFLICT (organization_id, primary_linkedin_url) DO NOTHING
    RETURNING id
  )
  SELECT count(*)::int INTO v_inserted_count FROM inserted;

  WITH desired_keys AS (
    SELECT
      lower(r->>'email')                       AS email_lc,
      NULLIF(r->>'person_linkedin_url', '\N')  AS linkedin
    FROM jsonb_array_elements(p_rows) r
    WHERE r->>'email' IS NOT NULL AND r->>'email' <> ''
  ),
  matching_contacts AS (
    SELECT DISTINCT c.id
    FROM public.crm_contacts c
    WHERE c.organization_id = p_org_id
      AND (
        c.primary_email IN (SELECT email_lc FROM desired_keys)
        OR (c.primary_linkedin_url IS NOT NULL
            AND c.primary_linkedin_url IN (
              SELECT linkedin FROM desired_keys WHERE linkedin IS NOT NULL
            ))
      )
  ),
  inserted_members AS (
    INSERT INTO public.lead_list_members (list_id, contact_id)
    SELECT p_list_id, id FROM matching_contacts
    ON CONFLICT (list_id, contact_id) DO NOTHING
    RETURNING 1
  )
  SELECT count(*)::int INTO v_member_count FROM inserted_members;

  RETURN QUERY SELECT v_inserted_count, v_member_count;
END;
$$;


ALTER FUNCTION "public"."import_pool_rows_to_list"("p_list_id" "uuid", "p_org_id" "uuid", "p_rows" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."inbox_keyword_regex"("p_keywords" "text"[]) RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $_$
  SELECT NULLIF(
    string_agg(regexp_replace(k, '([.^$|()\[\]{}*+?\\/-])', '\\\1', 'g'), '|'),
    ''
  )
  FROM unnest(COALESCE(p_keywords, ARRAY[]::TEXT[])) AS k
  WHERE COALESCE(k, '') <> '';
$_$;


ALTER FUNCTION "public"."inbox_keyword_regex"("p_keywords" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."include_ideas_in_autopilot"("p_autopilot_id" "uuid", "p_idea_ids" "uuid"[]) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org uuid;
  v_count integer;
BEGIN
  SELECT organization_id INTO v_org FROM public.autopilots WHERE id = p_autopilot_id;
  IF v_org IS NULL OR v_org NOT IN (SELECT get_accessible_organization_ids()) THEN
    RAISE EXCEPTION 'Autopilot not found';
  END IF;

  DELETE FROM public.autopilot_idea_exclusions
  WHERE autopilot_id = p_autopilot_id AND idea_id = ANY (p_idea_ids);
  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$$;


ALTER FUNCTION "public"."include_ideas_in_autopilot"("p_autopilot_id" "uuid", "p_idea_ids" "uuid"[]) OWNER TO "postgres";


