CREATE OR REPLACE FUNCTION "public"."increment_campaign_analytics"("p_organization_id" "uuid", "p_campaign_id" "uuid", "p_account_id" "uuid", "p_metric" "text", "p_value" integer DEFAULT 1) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
BEGIN
  -- Insert if not exists, then update
  INSERT INTO campaign_analytics (organization_id, campaign_id, account_id, date)
  VALUES (p_organization_id, p_campaign_id, p_account_id, CURRENT_DATE)
  ON CONFLICT (organization_id, campaign_id, account_id, date) DO NOTHING;

  -- Dynamic column update based on metric name
  EXECUTE format('
    UPDATE campaign_analytics
    SET %I = %I + $1, updated_at = NOW()
    WHERE organization_id = $2
      AND campaign_id = $3
      AND account_id = $4
      AND date = CURRENT_DATE
  ', p_metric, p_metric)
  USING p_value, p_organization_id, p_campaign_id, p_account_id;
END;
$_$;


ALTER FUNCTION "public"."increment_campaign_analytics"("p_organization_id" "uuid", "p_campaign_id" "uuid", "p_account_id" "uuid", "p_metric" "text", "p_value" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."increment_channel_usage"("p_organization_id" "uuid", "p_channel" "public"."crm_channel_type", "p_channel_account_id" "uuid" DEFAULT NULL::"uuid", "p_status" "text" DEFAULT 'sent'::"text") RETURNS boolean
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    v_effective_limit INTEGER;
    v_current_hour INTEGER := EXTRACT(HOUR FROM now())::INTEGER;
BEGIN
    v_effective_limit := get_effective_daily_limit(p_organization_id, p_channel, p_channel_account_id);

    -- Upsert daily counter (period_hour IS NULL)
    INSERT INTO channel_usage_tracking (
        organization_id, channel, channel_account_id, period_date, period_hour,
        messages_sent, messages_delivered, messages_failed, messages_bounced,
        effective_limit
    ) VALUES (
        p_organization_id, p_channel, p_channel_account_id, CURRENT_DATE, NULL,
        CASE WHEN p_status = 'sent' THEN 1 ELSE 0 END,
        CASE WHEN p_status = 'delivered' THEN 1 ELSE 0 END,
        CASE WHEN p_status = 'failed' THEN 1 ELSE 0 END,
        CASE WHEN p_status = 'bounced' THEN 1 ELSE 0 END,
        v_effective_limit
    )
    ON CONFLICT (organization_id, channel, COALESCE(channel_account_id, '00000000-0000-0000-0000-000000000000'::uuid), period_date)
    WHERE period_hour IS NULL
    DO UPDATE SET
        messages_sent = channel_usage_tracking.messages_sent + CASE WHEN p_status = 'sent' THEN 1 ELSE 0 END,
        messages_delivered = channel_usage_tracking.messages_delivered + CASE WHEN p_status = 'delivered' THEN 1 ELSE 0 END,
        messages_failed = channel_usage_tracking.messages_failed + CASE WHEN p_status = 'failed' THEN 1 ELSE 0 END,
        messages_bounced = channel_usage_tracking.messages_bounced + CASE WHEN p_status = 'bounced' THEN 1 ELSE 0 END,
        usage_percent = ((channel_usage_tracking.messages_sent + 1)::DECIMAL / NULLIF(v_effective_limit, 0)) * 100,
        updated_at = now();

    -- Upsert hourly counter
    INSERT INTO channel_usage_tracking (
        organization_id, channel, channel_account_id, period_date, period_hour,
        messages_sent, effective_limit
    ) VALUES (
        p_organization_id, p_channel, p_channel_account_id, CURRENT_DATE, v_current_hour,
        CASE WHEN p_status = 'sent' THEN 1 ELSE 0 END,
        v_effective_limit
    )
    ON CONFLICT (organization_id, channel, COALESCE(channel_account_id, '00000000-0000-0000-0000-000000000000'::uuid), period_date, period_hour)
    WHERE period_hour IS NOT NULL
    DO UPDATE SET
        messages_sent = channel_usage_tracking.messages_sent + CASE WHEN p_status = 'sent' THEN 1 ELSE 0 END,
        updated_at = now();

    RETURN true;
END;
$$;


ALTER FUNCTION "public"."increment_channel_usage"("p_organization_id" "uuid", "p_channel" "public"."crm_channel_type", "p_channel_account_id" "uuid", "p_status" "text") OWNER TO "postgres";


