CREATE OR REPLACE FUNCTION "public"."increment_csv_import_progress"("p_job_id" "uuid", "p_imported_delta" integer DEFAULT 0, "p_skipped_delta" integer DEFAULT 0, "p_failed_delta" integer DEFAULT 0, "p_rows_delta" integer DEFAULT 0, "p_progress" integer DEFAULT 0, "p_is_complete" boolean DEFAULT false, "p_skip_reasons_missing" integer DEFAULT 0, "p_skip_reasons_invalid" integer DEFAULT 0) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  UPDATE csv_import_jobs SET
    imported_count = imported_count + p_imported_delta,
    skipped_count = skipped_count + p_skipped_delta,
    failed_count = failed_count + p_failed_delta,
    current_row = current_row + p_rows_delta,
    progress = GREATEST(progress, p_progress),
    status = CASE WHEN p_is_complete THEN 'completed' ELSE status END,
    completed_at = CASE WHEN p_is_complete THEN now() ELSE completed_at END,
    skip_reasons = jsonb_build_object(
      'missing_linkedin_url', COALESCE((skip_reasons->>'missing_linkedin_url')::int, 0) + p_skip_reasons_missing,
      'invalid_linkedin_url', COALESCE((skip_reasons->>'invalid_linkedin_url')::int, 0) + p_skip_reasons_invalid
    )
  WHERE id = p_job_id;
END;
$$;


