CREATE OR REPLACE FUNCTION "public"."increment_identity_usage"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
BEGIN
  -- Increment usage_count on the identity
  IF NEW.last_used_identity_id IS NOT NULL AND
     (OLD.last_used_identity_id IS NULL OR NEW.last_used_identity_id != OLD.last_used_identity_id) THEN
    UPDATE public.identities
    SET usage_count = COALESCE(usage_count, 0) + 1
    WHERE id = NEW.last_used_identity_id;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."increment_identity_usage"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."increment_job_progress"("p_job_id" "uuid", "p_increment_completed" boolean DEFAULT false, "p_increment_failed" boolean DEFAULT false) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_progress JSONB;
  v_items_count INTEGER;
  v_new_completed INTEGER;
  v_new_failed INTEGER;
  v_outputs_count INTEGER;
BEGIN
  SELECT
    progress,
    jsonb_array_length(items)
  INTO v_progress, v_items_count
  FROM public.content_generation_jobs
  WHERE id = p_job_id
  FOR UPDATE;

  v_new_completed := COALESCE((v_progress->>'completed')::INTEGER, 0);
  v_new_failed := COALESCE((v_progress->>'failed')::INTEGER, 0);

  IF p_increment_completed THEN
    v_new_completed := v_new_completed + 1;
  END IF;

  IF p_increment_failed THEN
    v_new_failed := v_new_failed + 1;
  END IF;

  SELECT COUNT(*) INTO v_outputs_count
  FROM public.content_outputs
  WHERE job_id = p_job_id;

  UPDATE public.content_generation_jobs
  SET
    progress = jsonb_build_object(
      'total', v_items_count,
      'completed', v_new_completed,
      'failed', v_new_failed,
      'dispatched', v_outputs_count
    )
  WHERE id = p_job_id;
END;
$$;


ALTER FUNCTION "public"."increment_job_progress"("p_job_id" "uuid", "p_increment_completed" boolean, "p_increment_failed" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."increment_job_progress"("p_job_id" "uuid", "p_current_platform" "text" DEFAULT NULL::"text", "p_total" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_progress JSONB;
  v_current_completed INTEGER;
  v_platforms_status JSONB;
BEGIN
  SELECT progress INTO v_progress
  FROM generation_jobs
  WHERE id = p_job_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Generation job % not found', p_job_id;
  END IF;

  v_current_completed := COALESCE((v_progress->>'completed')::INTEGER, 0) + 1;

  IF p_current_platform IS NOT NULL THEN
    v_platforms_status := COALESCE(v_progress->'platforms_status', '{}'::JSONB);
    v_platforms_status := jsonb_set(v_platforms_status, array[p_current_platform], '"processing"'::JSONB);
  ELSE
    v_platforms_status := v_progress->'platforms_status';
  END IF;

  UPDATE generation_jobs
  SET progress = jsonb_build_object(
    'completed', v_current_completed,
    'total', COALESCE(p_total, (v_progress->>'total')::INTEGER),
    'current_platform', p_current_platform,
    'platforms_status', v_platforms_status
  ),
  updated_at = NOW()
  WHERE id = p_job_id
  RETURNING progress INTO v_progress;

  RETURN v_progress;
END;
$$;


ALTER FUNCTION "public"."increment_job_progress"("p_job_id" "uuid", "p_current_platform" "text", "p_total" integer) OWNER TO "postgres";


