CREATE OR REPLACE FUNCTION "public"."increment_organization_usage"("p_org_id" "uuid", "p_count" integer DEFAULT 1, "p_cost" numeric DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_current_usage jsonb;
  v_current_date text;
  v_current_month text;
  v_daily_date text;
  v_monthly_month text;
BEGIN
  SELECT current_usage INTO v_current_usage
  FROM public.organizations
  WHERE id = p_org_id;

  IF v_current_usage IS NULL THEN
    v_current_usage := jsonb_build_object(
      'daily', jsonb_build_object('generations', 0, 'cost', 0, 'date', to_char(CURRENT_DATE, 'YYYY-MM-DD')),
      'monthly', jsonb_build_object('generations', 0, 'cost', 0, 'month', to_char(CURRENT_DATE, 'YYYY-MM')),
      'all_time', jsonb_build_object('generations', 0, 'cost', 0)
    );
  END IF;

  v_current_date := to_char(CURRENT_DATE, 'YYYY-MM-DD');
  v_current_month := to_char(CURRENT_DATE, 'YYYY-MM');
  v_daily_date := COALESCE(v_current_usage->'daily'->>'date', '');
  v_monthly_month := COALESCE(v_current_usage->'monthly'->>'month', '');

  IF v_daily_date != v_current_date THEN
    v_current_usage := jsonb_set(v_current_usage, '{daily}', jsonb_build_object(
      'generations', 0, 'cost', 0, 'date', v_current_date
    ));
  END IF;

  IF v_monthly_month != v_current_month THEN
    v_current_usage := jsonb_set(v_current_usage, '{monthly}', jsonb_build_object(
      'generations', 0, 'cost', 0, 'month', v_current_month
    ));
  END IF;

  v_current_usage := jsonb_set(v_current_usage, '{daily,generations}',
    to_jsonb(COALESCE((v_current_usage->'daily'->>'generations')::int, 0) + p_count));
  v_current_usage := jsonb_set(v_current_usage, '{daily,cost}',
    to_jsonb(COALESCE((v_current_usage->'daily'->>'cost')::numeric, 0) + p_cost));
  v_current_usage := jsonb_set(v_current_usage, '{monthly,generations}',
    to_jsonb(COALESCE((v_current_usage->'monthly'->>'generations')::int, 0) + p_count));
  v_current_usage := jsonb_set(v_current_usage, '{monthly,cost}',
    to_jsonb(COALESCE((v_current_usage->'monthly'->>'cost')::numeric, 0) + p_cost));
  v_current_usage := jsonb_set(v_current_usage, '{all_time,generations}',
    to_jsonb(COALESCE((v_current_usage->'all_time'->>'generations')::int, 0) + p_count));
  v_current_usage := jsonb_set(v_current_usage, '{all_time,cost}',
    to_jsonb(COALESCE((v_current_usage->'all_time'->>'cost')::numeric, 0) + p_cost));

  UPDATE public.organizations
  SET current_usage = v_current_usage
  WHERE id = p_org_id;

  RETURN v_current_usage;
END;
$$;


ALTER FUNCTION "public"."increment_organization_usage"("p_org_id" "uuid", "p_count" integer, "p_cost" numeric) OWNER TO "postgres";


