CREATE OR REPLACE FUNCTION "public"."increment_variant_stat"("p_variant_id" "uuid", "p_column" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  IF p_column = 'sent' THEN
    UPDATE public.email_ab_variants SET sent = sent + 1 WHERE id = p_variant_id;
  ELSIF p_column = 'opened' THEN
    UPDATE public.email_ab_variants SET opened = opened + 1 WHERE id = p_variant_id;
  ELSIF p_column = 'clicked' THEN
    UPDATE public.email_ab_variants SET clicked = clicked + 1 WHERE id = p_variant_id;
  ELSIF p_column = 'replied' THEN
    UPDATE public.email_ab_variants SET replied = replied + 1 WHERE id = p_variant_id;
  ELSIF p_column = 'bounced' THEN
    UPDATE public.email_ab_variants SET bounced = bounced + 1 WHERE id = p_variant_id;
  END IF;
END;
$$;


