CREATE OR REPLACE FUNCTION "public"."initialize_agency_user_access"("user_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  user_org_id UUID;
  user_org_type TEXT;
  child_org_ids UUID[];
BEGIN
  SELECT u.organization_id INTO user_org_id
  FROM public.users u
  WHERE u.id = initialize_agency_user_access.user_id;

  SELECT o.type INTO user_org_type
  FROM public.organizations o
  WHERE o.id = user_org_id;

  IF user_org_type = 'agency' THEN
    SELECT ARRAY_AGG(o.id) INTO child_org_ids
    FROM public.organizations o
    WHERE o.parent_id = user_org_id;

    UPDATE public.users u
    SET
      can_access_organizations = ARRAY[user_org_id] || COALESCE(child_org_ids, '{}'),
      active_organization_id = COALESCE(u.active_organization_id, user_org_id)
    WHERE u.id = initialize_agency_user_access.user_id;
  ELSE
    UPDATE public.users u
    SET
      can_access_organizations = ARRAY[user_org_id],
      active_organization_id = COALESCE(u.active_organization_id, user_org_id)
    WHERE u.id = initialize_agency_user_access.user_id;
  END IF;
END;
$$;


ALTER FUNCTION "public"."initialize_agency_user_access"("user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."initialize_campaign_leads"("p_campaign_id" "uuid") RETURNS TABLE("leads_added" integer, "leads_excluded" integer, "total_in_list" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_campaign RECORD;
  v_total_in_list INTEGER := 0;
  v_leads_added INTEGER := 0;
  v_leads_excluded INTEGER := 0;
  v_org_id UUID;
  v_list_ids UUID[];
  v_member_ids UUID[];
BEGIN
  SELECT * INTO v_campaign FROM linkedin_campaigns WHERE id = p_campaign_id;

  IF v_campaign IS NULL THEN
    RAISE EXCEPTION 'Campaign not found: %', p_campaign_id;
  END IF;

  v_org_id := v_campaign.organization_id;
  PERFORM public.assert_smart_segment_org_access(v_org_id);

  v_list_ids := COALESCE(NULLIF(v_campaign.lead_list_ids, '{}'),
    CASE WHEN v_campaign.lead_list_id IS NOT NULL THEN ARRAY[v_campaign.lead_list_id] ELSE '{}' END);

  IF cardinality(v_list_ids) = 0 THEN
    RAISE EXCEPTION 'Campaign has no lead list selected';
  END IF;

  SELECT coalesce(array_agg(s.contact_id),'{}'::uuid[]),count(*)::integer
  INTO v_member_ids,v_total_in_list
  FROM public.lead_source_contacts(v_org_id,v_list_ids) s;

  v_member_ids := public.filter_contact_ids_by_criteria(
    v_org_id, v_member_ids, COALESCE(v_campaign.enroll_filter_criteria, '{}'::jsonb)
  );

  v_member_ids := public.filter_contact_ids_by_pipeline_gate(
    v_org_id, v_list_ids, 'linkedin_campaign', p_campaign_id, v_member_ids
  );

  ALTER TABLE campaign_lead_progress DISABLE TRIGGER trg_update_campaign_metrics;

  WITH members AS (
    SELECT s.contact_id,s.first_added
    FROM public.lead_source_contacts(v_org_id,v_list_ids) s
    WHERE s.contact_id=ANY(v_member_ids)
  ),
  eligible_leads AS (
    SELECT
      m.contact_id,
      ROW_NUMBER() OVER (ORDER BY m.first_added,m.contact_id) AS rn
    FROM members m
    JOIN crm_contacts c ON c.id = m.contact_id
    WHERE (
        v_campaign.exclusion_list_ids IS NULL
        OR array_length(v_campaign.exclusion_list_ids, 1) IS NULL
        OR NOT EXISTS (
          SELECT 1 FROM lead_list_members exc
          WHERE exc.contact_id = m.contact_id
            AND exc.list_id = ANY(v_campaign.exclusion_list_ids)
        )
      )
      AND NOT EXISTS (
        SELECT 1 FROM campaign_lead_progress clp
        WHERE clp.campaign_id = p_campaign_id
          AND clp.contact_id = m.contact_id
      )
      AND NOT public.contact_excluded_by_campaign_history(
        v_org_id, p_campaign_id, m.contact_id,
        v_campaign.exclude_other_campaigns,
        v_campaign.exclude_same_sender,
        v_campaign.sender_account_ids
      )
  )
  INSERT INTO campaign_lead_progress (
    campaign_id, contact_id, status, current_node_id,
    next_action_at, variation_index, is_test_contact, created_at, updated_at
  )
  SELECT
    p_campaign_id, el.contact_id, 'pending', NULL,
    NOW(), (el.rn % 2)::INTEGER, false, NOW(), NOW()
  FROM eligible_leads el;

  GET DIAGNOSTICS v_leads_added = ROW_COUNT;
  v_leads_excluded := v_total_in_list - v_leads_added;

  ALTER TABLE campaign_lead_progress ENABLE TRIGGER trg_update_campaign_metrics;

  UPDATE linkedin_campaigns
  SET
    total_leads = (
      SELECT COUNT(*) FROM campaign_lead_progress
      WHERE campaign_id = p_campaign_id
    ),
    updated_at = NOW()
  WHERE id = p_campaign_id;

  RETURN QUERY SELECT v_leads_added, v_leads_excluded, v_total_in_list;
END;
$$;


ALTER FUNCTION "public"."initialize_campaign_leads"("p_campaign_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."initialize_campaign_leads"("p_campaign_id" "uuid") IS 'Populates campaign_lead_progress from the lead list, applying exclusion filters';



