CREATE OR REPLACE FUNCTION "public"."kick_email_enrollment_job"("p_job_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_url TEXT;
  v_key TEXT;
BEGIN
  SELECT decrypted_secret INTO v_url FROM vault.decrypted_secrets WHERE name = 'supabase_url';
  SELECT decrypted_secret INTO v_key FROM vault.decrypted_secrets WHERE name = 'supabase_service_role_key';
  IF v_url IS NULL OR v_key IS NULL THEN RETURN; END IF;
  PERFORM net.http_post(
    url := v_url || '/functions/v1/process-email-enrollment-jobs',
    headers := jsonb_build_object('Content-Type', 'application/json', 'Authorization', 'Bearer ' || v_key),
    body := jsonb_build_object('jobId', p_job_id, 'source', 'kick')
  );
END;
$$;


ALTER FUNCTION "public"."kick_email_enrollment_job"("p_job_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."kick_webhook_dispatcher"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_kicked boolean;
  v_url    text;
  v_key    text;
BEGIN
  UPDATE webhook_dispatcher_state
     SET last_kick_at = clock_timestamp()
   WHERE id = true
     AND last_kick_at < clock_timestamp() - interval '3 seconds'
  RETURNING true INTO v_kicked;

  IF NOT COALESCE(v_kicked, false) THEN
    RETURN;
  END IF;

  SELECT decrypted_secret INTO v_url
    FROM vault.decrypted_secrets WHERE name = 'supabase_url';
  SELECT decrypted_secret INTO v_key
    FROM vault.decrypted_secrets WHERE name = 'supabase_service_role_key';

  IF v_url IS NULL OR v_key IS NULL THEN
    RETURN;
  END IF;

  PERFORM net.http_post(
    url     := v_url || '/functions/v1/crm-process-webhooks',
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'Authorization', 'Bearer ' || v_key
    ),
    body    := '{}'::jsonb
  );
EXCEPTION WHEN OTHERS THEN
  RETURN;
END;
$$;


ALTER FUNCTION "public"."kick_webhook_dispatcher"() OWNER TO "postgres";


