CREATE OR REPLACE FUNCTION "public"."lead_list_member_page"("p_list_id" "uuid", "p_limit" integer DEFAULT 50, "p_after_added_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_after_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("member_id" "uuid", "contact_id" "uuid", "added_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    SET "statement_timeout" TO '30s'
    AS $$
DECLARE
  v_limit INTEGER := LEAST(GREATEST(COALESCE(p_limit, 50), 0), 1000);
BEGIN
  -- Two explicit branches rather than one query with `p_after_id IS NULL OR …`:
  -- an OR against a non-indexable branch costs the row comparison its Index Cond
  -- and puts the full-partition scan straight back.
  IF p_after_id IS NULL OR p_after_added_at IS NULL THEN
    RETURN QUERY
      SELECT m.id, m.contact_id, m.added_at
      FROM public.lead_list_members m
      WHERE m.list_id = p_list_id
      ORDER BY m.added_at DESC, m.id DESC
      LIMIT v_limit;
  ELSE
    RETURN QUERY
      SELECT m.id, m.contact_id, m.added_at
      FROM public.lead_list_members m
      WHERE m.list_id = p_list_id
        AND (m.added_at, m.id) < (p_after_added_at, p_after_id)
      ORDER BY m.added_at DESC, m.id DESC
      LIMIT v_limit;
  END IF;
END;
$$;


ALTER FUNCTION "public"."lead_list_member_page"("p_list_id" "uuid", "p_limit" integer, "p_after_added_at" timestamp with time zone, "p_after_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."lead_list_member_page"("p_list_id" "uuid", "p_limit" integer, "p_after_added_at" timestamp with time zone, "p_after_id" "uuid") IS 'Keyset page of a lead list''s members, ordered (added_at DESC, id DESC). Backs the unfiltered /v1/lists/members read. Callers must already have checked the list belongs to their organization.';



