    LANGUAGE "plpgsql"
    AS $$ DECLARE v_email text; BEGIN SELECT NULLIF(lower(trim(c.primary_email)), '') INTO v_email FROM public.crm_contacts c WHERE c.id = NEW.contact_id; NEW.email_lower := v_email; RETURN NEW; END; $$;


