CREATE OR REPLACE FUNCTION "public"."lead_lists_awaiting_processing"("p_org" "uuid", "p_list_ids" "uuid"[]) RETURNS integer
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_lists uuid[];
  v_count integer;
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.organization_members om
    WHERE om.organization_id = p_org AND om.user_id = auth.uid()
  ) AND current_user NOT IN ('service_role', 'postgres') THEN
    RAISE EXCEPTION 'Not a member of this organization';
  END IF;

  SELECT ARRAY(
    SELECT p.lead_list_id
    FROM public.lead_list_processing_policies p
    WHERE p.organization_id = p_org
      AND p.lead_list_id = ANY(COALESCE(p_list_ids, '{}'::uuid[]))
      AND p.enabled = TRUE
  ) INTO v_lists;

  IF cardinality(v_lists) = 0 THEN
    RETURN 0;
  END IF;

  SELECT COUNT(DISTINCT m.contact_id) INTO v_count
  FROM public.lead_list_members m
  WHERE m.list_id = ANY(v_lists)
    AND NOT EXISTS (
      SELECT 1 FROM public.lead_list_processing_items i
      WHERE i.lead_list_id = m.list_id
        AND i.contact_id = m.contact_id
        AND (i.status = 'completed' OR i.rejected_reason IS NOT NULL)
    );

  RETURN COALESCE(v_count, 0);
END;
$$;


ALTER FUNCTION "public"."lead_lists_awaiting_processing"("p_org" "uuid", "p_list_ids" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."lead_lists_awaiting_processing"("p_org" "uuid", "p_list_ids" "uuid"[]) IS 'Members of these lists that their (enabled) processing pipeline has not finished with — neither approved nor rejected. Drives the "still being processed" caveat on the Ongoing / One-time send choice.';



CREATE OR REPLACE FUNCTION "public"."lead_source_contacts"("p_org_id" "uuid", "p_list_ids" "uuid"[]) RETURNS TABLE("contact_id" "uuid", "first_added" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  PERFORM public.assert_smart_segment_org_access(p_org_id);
  IF EXISTS (
    SELECT 1 FROM unnest(coalesce(p_list_ids,'{}'::uuid[])) requested(id)
    WHERE NOT EXISTS (SELECT 1 FROM public.lead_lists l WHERE l.id=requested.id AND l.organization_id=p_org_id)
  ) THEN RAISE EXCEPTION 'Lead source not found' USING ERRCODE='P0002'; END IF;
  RETURN QUERY
  WITH sources AS (
    SELECT m.contact_id,m.added_at
    FROM public.lead_lists l JOIN public.lead_list_members m ON m.list_id=l.id
    JOIN public.crm_contacts c ON c.id=m.contact_id AND c.organization_id=p_org_id
    WHERE l.organization_id=p_org_id AND l.id=ANY(p_list_ids) AND NOT coalesce(l.is_smart,false)
    UNION ALL
    SELECT c.id,c.created_at
    FROM public.lead_lists l
    CROSS JOIN LATERAL public.smart_list_eligible_contact_ids(l.id) eligible(id)
    JOIN public.crm_contacts c ON c.id=eligible.id AND c.organization_id=p_org_id
    WHERE l.organization_id=p_org_id AND l.id=ANY(p_list_ids) AND l.is_smart
  )
  SELECT s.contact_id,min(s.added_at) FROM sources s GROUP BY s.contact_id;
END;
$$;


ALTER FUNCTION "public"."lead_source_contacts"("p_org_id" "uuid", "p_list_ids" "uuid"[]) OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."pool_email_verifications" (
    "email_hash" "bytea" NOT NULL,
    "last_verified_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "last_source" "text" NOT NULL,
    "status" "text" NOT NULL,
    "is_deliverable" boolean,
    "is_catch_all" boolean,
    "is_role" boolean,
    "is_free" boolean,
    "is_disposable" boolean,
    "is_spamtrap" boolean,
    "is_disabled" boolean,
    "overall_score" integer,
    "mx_host" "text",
    "raw_result" "jsonb",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "pool_email_verifications_last_source_check" CHECK (("last_source" = ANY (ARRAY['tier1'::"text", 'apify_millionverifier'::"text", 'apify_generic'::"text", 'manual'::"text"]))),
    CONSTRAINT "pool_email_verifications_overall_score_check" CHECK ((("overall_score" >= 0) AND ("overall_score" <= 100))),
    CONSTRAINT "pool_email_verifications_status_check" CHECK (("status" = ANY (ARRAY['valid'::"text", 'invalid'::"text", 'catch_all'::"text", 'disposable'::"text", 'disabled'::"text", 'unknown'::"text", 'role_only'::"text", 'free_only'::"text", 'spamtrap'::"text"])))
);


ALTER TABLE "public"."pool_email_verifications" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."lookup_email_verifications"("p_hashes_hex" "text"[], "p_stale_cutoff" timestamp with time zone, "p_min_score" integer, "p_apify_only" boolean DEFAULT false) RETURNS SETOF "public"."pool_email_verifications"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    SET "statement_timeout" TO '60s'
    AS $$
  -- Pre-decode the hex array once into a bytea[] so the WHERE clause can use
  -- the email_hash unique index instead of decoding row-by-row.
  WITH hashes AS (
    SELECT array_agg(decode(h, 'hex')) AS arr
    FROM unnest(p_hashes_hex) AS t(h)
    WHERE h IS NOT NULL AND length(h) = 64
  )
  SELECT v.*
  FROM public.pool_email_verifications v, hashes
  WHERE v.email_hash = ANY (hashes.arr)
    AND v.last_verified_at >= p_stale_cutoff
    AND v.overall_score    >= p_min_score
    AND (NOT p_apify_only OR v.last_source LIKE 'apify_%');
$$;


ALTER FUNCTION "public"."lookup_email_verifications"("p_hashes_hex" "text"[], "p_stale_cutoff" timestamp with time zone, "p_min_score" integer, "p_apify_only" boolean) OWNER TO "postgres";


