CREATE OR REPLACE FUNCTION "public"."mark_conversation_read"("p_conversation_id" "uuid", "p_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  UPDATE crm_conversations SET unread_count = 0, updated_at = NOW() WHERE id = p_conversation_id;
  IF p_user_id IS NOT NULL THEN
    UPDATE crm_conversation_participants SET last_read_at = NOW(), last_read_message_id = (SELECT id FROM crm_messages WHERE conversation_id = p_conversation_id ORDER BY created_at DESC LIMIT 1)
    WHERE conversation_id = p_conversation_id AND user_id = p_user_id;
  END IF;
END;
$$;


