CREATE OR REPLACE FUNCTION "public"."mark_keyword_excluded_conversation"("p_conversation_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_match RECORD;
BEGIN
  SELECT c.id AS conversation_id, c.organization_id, c.contact_id, kw.normalized_keyword AS matched_keyword
  INTO v_match
  FROM public.crm_conversations c
  JOIN public.crm_contacts ct ON ct.id = c.contact_id
  JOIN public.inbox_keyword_exclusions kw ON kw.organization_id = c.organization_id
  LEFT JOIN public.crm_messages m
    ON m.conversation_id = c.id
   AND m.organization_id = c.organization_id
   AND m.direction = 'inbound'
  WHERE c.id = p_conversation_id
    AND c.channel = 'email'
    AND (
      COALESCE(c.last_message_preview, '') ILIKE '%' || kw.normalized_keyword || '%'
      OR COALESCE(c.last_message_subject, '') ILIKE '%' || kw.normalized_keyword || '%'
      OR COALESCE(ct.display_name, '') ILIKE '%' || kw.normalized_keyword || '%'
      OR COALESCE(ct.primary_email, '') ILIKE '%' || kw.normalized_keyword || '%'
      OR COALESCE(m.email_subject, '') ILIKE '%' || kw.normalized_keyword || '%'
      OR COALESCE(m.content, '') ILIKE '%' || kw.normalized_keyword || '%'
    )
  LIMIT 1;

  IF v_match.conversation_id IS NULL THEN
    RETURN false;
  END IF;

  UPDATE public.crm_conversations c
  SET
    is_system = true,
    status = 'closed',
    unread_count = 0,
    metadata = COALESCE(c.metadata, '{}'::jsonb) || jsonb_build_object(
      'keyword_excluded', true,
      'keyword_excluded_at', NOW(),
      'keyword_excluded_match', v_match.matched_keyword
    ),
    updated_at = NOW()
  WHERE c.id = v_match.conversation_id;

  UPDATE public.crm_contacts ct
  SET
    status = CASE
      WHEN ct.status IN ('unsubscribed', 'do_not_contact') THEN ct.status
      ELSE 'archived'
    END,
    custom_fields = COALESCE(ct.custom_fields, '{}'::jsonb) || jsonb_build_object(
      'keyword_excluded', true,
      'keyword_excluded_at', NOW()
    ),
    updated_at = NOW()
  WHERE ct.id = v_match.contact_id
    AND ct.organization_id = v_match.organization_id;

  RETURN true;
END;
$$;


ALTER FUNCTION "public"."mark_keyword_excluded_conversation"("p_conversation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mark_keyword_excluded_conversations"("p_org_id" "uuid", "p_keywords" "text"[] DEFAULT NULL::"text"[]) RETURNS TABLE("conversations_excluded" integer, "contacts_archived" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  keywords text[];
  header_pattern text;
  contact_ids uuid[];
BEGIN
  IF auth.uid() IS NOT NULL AND NOT EXISTS (
    SELECT 1
    FROM public.organization_members membership
    WHERE membership.organization_id = p_org_id
      AND membership.user_id = auth.uid()
  ) THEN
    RAISE EXCEPTION 'Not a member of this organization';
  END IF;

  IF auth.uid() IS NULL
     AND auth.role() IS DISTINCT FROM 'service_role'
     AND session_user NOT IN ('postgres', 'supabase_admin') THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  SELECT ARRAY_AGG(DISTINCT normalized ORDER BY normalized)
  INTO keywords
  FROM (
    SELECT public.normalize_inbox_keyword(keyword) AS normalized
    FROM unnest(COALESCE(p_keywords, ARRAY[]::text[])) AS keyword
    UNION
    SELECT exclusion.normalized_keyword
    FROM public.inbox_keyword_exclusions exclusion
    WHERE exclusion.organization_id = p_org_id
      AND p_keywords IS NULL
  ) normalized_keywords
  WHERE normalized <> '';

  IF keywords IS NULL OR array_length(keywords, 1) IS NULL THEN
    conversations_excluded := 0;
    contacts_archived := 0;
    RETURN NEXT;
    RETURN;
  END IF;

  header_pattern := public.inbox_keyword_regex(keywords);

  DROP TABLE IF EXISTS tmp_keyword_excluded_conversations;
  CREATE TEMP TABLE tmp_keyword_excluded_conversations (
    conversation_id uuid PRIMARY KEY,
    contact_id uuid NOT NULL,
    matched_keyword text NOT NULL
  ) ON COMMIT DROP;

  -- Message bodies/subjects use the org-scoped GIN trigram indexes.
  INSERT INTO tmp_keyword_excluded_conversations (conversation_id, contact_id, matched_keyword)
  SELECT conversation.id, conversation.contact_id, keywords[1]
  FROM public.find_keyword_excluded_conversations(p_org_id, keywords) body_match
  JOIN public.crm_conversations conversation
    ON conversation.id = body_match.conversation_id
   AND conversation.organization_id = p_org_id
  WHERE conversation.channel = 'email'
    AND conversation.is_system = false
  ON CONFLICT (conversation_id) DO NOTHING;

  -- Preview/contact fields are small and do not require detoasting message HTML.
  INSERT INTO tmp_keyword_excluded_conversations (conversation_id, contact_id, matched_keyword)
  SELECT
    conversation.id,
    conversation.contact_id,
    COALESCE((
      SELECT keyword
      FROM unnest(keywords) AS keyword
      WHERE concat_ws(
        ' ',
        conversation.last_message_preview,
        conversation.last_message_subject,
        contact.display_name,
        contact.primary_email
      ) ILIKE '%' || keyword || '%'
      LIMIT 1
    ), keywords[1])
  FROM public.crm_conversations conversation
  JOIN public.crm_contacts contact ON contact.id = conversation.contact_id
  WHERE conversation.organization_id = p_org_id
    AND conversation.channel = 'email'
    AND conversation.is_system = false
    AND concat_ws(
      ' ',
      conversation.last_message_preview,
      conversation.last_message_subject,
      contact.display_name,
      contact.primary_email
    ) ~* header_pattern
  ON CONFLICT (conversation_id) DO NOTHING;

  UPDATE public.crm_conversations conversation
  SET is_system = true,
      status = 'closed',
      unread_count = 0,
      metadata = COALESCE(conversation.metadata, '{}'::jsonb) || jsonb_build_object(
        'keyword_excluded', true,
        'keyword_excluded_at', NOW(),
        'keyword_excluded_match', excluded.matched_keyword
      ),
      updated_at = NOW()
  FROM tmp_keyword_excluded_conversations excluded
  WHERE conversation.id = excluded.conversation_id
    AND conversation.organization_id = p_org_id;

  GET DIAGNOSTICS conversations_excluded = ROW_COUNT;

  SELECT ARRAY_AGG(DISTINCT excluded.contact_id)
  INTO contact_ids
  FROM tmp_keyword_excluded_conversations excluded;

  IF contact_ids IS NULL OR array_length(contact_ids, 1) IS NULL THEN
    contacts_archived := 0;
  ELSE
    UPDATE public.crm_contacts contact
    SET status = CASE
          WHEN contact.status IN ('unsubscribed', 'do_not_contact') THEN contact.status
          ELSE 'archived'
        END,
        custom_fields = COALESCE(contact.custom_fields, '{}'::jsonb) || jsonb_build_object(
          'keyword_excluded', true,
          'keyword_excluded_at', NOW()
        ),
        updated_at = NOW()
    WHERE contact.organization_id = p_org_id
      AND contact.id = ANY(contact_ids)
      AND COALESCE(contact.custom_fields->>'keyword_excluded', 'false') <> 'true';

    GET DIAGNOSTICS contacts_archived = ROW_COUNT;
  END IF;

  RETURN NEXT;
END;
$$;


ALTER FUNCTION "public"."mark_keyword_excluded_conversations"("p_org_id" "uuid", "p_keywords" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mark_webhook_sent"("p_event_id" "uuid", "p_success" boolean, "p_response_status" integer DEFAULT NULL::integer, "p_response_body" "text" DEFAULT NULL::"text", "p_error_message" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_event webhook_event_log; v_settings organization_webhook_settings;
BEGIN
  SELECT * INTO v_event FROM webhook_event_log WHERE id = p_event_id;
  IF v_event IS NULL THEN RETURN; END IF;

  IF p_success THEN
    UPDATE webhook_event_log SET status = 'success', response_status = p_response_status, response_body = p_response_body,
      sent_at = now(), completed_at = now(), attempt_count = attempt_count + 1 WHERE id = p_event_id;
    UPDATE organization_webhook_settings SET total_events_sent = total_events_sent + 1, last_event_at = now() WHERE organization_id = v_event.organization_id;
  ELSE
    SELECT * INTO v_settings FROM organization_webhook_settings WHERE organization_id = v_event.organization_id;
    IF v_event.attempt_count + 1 < v_event.max_attempts THEN
      UPDATE webhook_event_log SET status = 'retrying', response_status = p_response_status, response_body = p_response_body,
        error_message = p_error_message, attempt_count = attempt_count + 1,
        next_retry_at = now() + (COALESCE(v_settings.retry_delay_seconds, 60) * INTERVAL '1 second') WHERE id = p_event_id;
    ELSE
      UPDATE webhook_event_log SET status = 'failed', response_status = p_response_status, response_body = p_response_body,
        error_message = p_error_message, attempt_count = attempt_count + 1, completed_at = now() WHERE id = p_event_id;
      UPDATE organization_webhook_settings SET total_events_failed = total_events_failed + 1 WHERE organization_id = v_event.organization_id;
    END IF;
  END IF;
END;
$$;


ALTER FUNCTION "public"."mark_webhook_sent"("p_event_id" "uuid", "p_success" boolean, "p_response_status" integer, "p_response_body" "text", "p_error_message" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."materialize_quickenrich_signal_leads"("p_batch_size" integer DEFAULT 200) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org constant uuid := public.aca_house_org_id();
  v_list_id uuid;
  v_company_id uuid;
  v_contact_id uuid;
  v_added integer := 0;
  v_row record;
BEGIN
  INSERT INTO public.lead_lists (
    organization_id, name, description, source_type, source_config, status
  )
  SELECT
    v_org,
    'Fresh ACA-Native Signal Decision Makers — QuickEnrich',
    'Senior decision-makers with work emails attached to fresh ACA-native buying signals.',
    'event',
    '{"provider":"quickenrich","source":"aca_native_signals","lookback_days":30}'::jsonb,
    'active'
  WHERE NOT EXISTS (
    SELECT 1 FROM public.lead_lists
    WHERE organization_id = v_org
      AND name = 'Fresh ACA-Native Signal Decision Makers — QuickEnrich'
  );

  SELECT id INTO v_list_id
  FROM public.lead_lists
  WHERE organization_id = v_org
    AND name = 'Fresh ACA-Native Signal Decision Makers — QuickEnrich'
  ORDER BY created_at
  LIMIT 1;
  IF v_list_id IS NULL THEN RAISE EXCEPTION 'QuickEnrich signal list unavailable'; END IF;

  FOR v_row IN
    WITH latest_signal AS (
      SELECT DISTINCT ON (lower(btrim(s.company_name)))
        s.id AS public_signal_id,
        NULLIF(s.metadata->>'signal_event_id', '')::uuid AS signal_event_id,
        s.company_name, s.domain, s.company_linkedin_url,
        s.signal_type, s.signal_date,
        COALESCE(NULLIF(btrim(s.summary), ''), NULLIF(btrim(s.title), '')) AS signal_detail,
        s.source_url
      FROM public.public_signals s
      WHERE s.published
        AND s.source_key = 'aca_native'
        AND NULLIF(s.metadata->>'signal_event_id', '') IS NOT NULL
      ORDER BY lower(btrim(s.company_name)), s.signal_date DESC, s.quality_score DESC, s.created_at DESC
    )
    SELECT p.full_name, p.title AS person_title, p.linkedin_url, lower(btrim(p.email)) AS email,
           p.email_status, p.company_key, p.domain,
           s.public_signal_id, s.signal_event_id, s.company_name, s.company_linkedin_url,
           s.signal_type, s.signal_date, s.signal_detail, s.source_url,
           pc.employee_count, pc.employee_range, pc.revenue_range, pc.industry
    FROM public.public_signal_people p
    JOIN latest_signal s ON lower(btrim(s.company_name)) = p.company_key
    LEFT JOIN public.public_signal_companies pc ON pc.company_key = p.company_key
    WHERE p.source = 'quickenrich'
      AND p.enriched_at >= now() - interval '30 days'
      AND COALESCE(btrim(p.email), '') <> ''
      AND NOT EXISTS (
        SELECT 1
        FROM public.crm_contacts existing
        JOIN public.lead_list_members member ON member.contact_id = existing.id
        WHERE existing.organization_id = v_org
          AND member.list_id = v_list_id
          AND (existing.primary_email = lower(btrim(p.email))
            OR existing.primary_linkedin_url = p.linkedin_url)
          AND existing.signal_event_id = s.signal_event_id
          AND existing.signal_date = s.signal_date
      )
    ORDER BY p.enriched_at DESC, p.seniority_rank DESC
    LIMIT GREATEST(LEAST(p_batch_size, 500), 1)
  LOOP
    INSERT INTO public.crm_companies (
      organization_id, name, domain, website_url, linkedin_url, industry,
      employee_count, last_signal_at, enrichment_source
    ) VALUES (
      v_org, v_row.company_name, v_row.domain, 'https://' || v_row.domain,
      v_row.company_linkedin_url, v_row.industry, v_row.employee_count, now(), 'quickenrich'
    )
    ON CONFLICT (organization_id, normalized_domain) WHERE normalized_domain IS NOT NULL
    DO UPDATE SET
      linkedin_url = COALESCE(EXCLUDED.linkedin_url, crm_companies.linkedin_url),
      industry = COALESCE(EXCLUDED.industry, crm_companies.industry),
      employee_count = COALESCE(EXCLUDED.employee_count, crm_companies.employee_count),
      last_signal_at = GREATEST(EXCLUDED.last_signal_at, crm_companies.last_signal_at),
      enrichment_source = 'quickenrich',
      updated_at = now()
    RETURNING id INTO v_company_id;

    SELECT id INTO v_contact_id
    FROM public.crm_contacts
    WHERE organization_id = v_org AND primary_email = v_row.email
    LIMIT 1;
    IF v_contact_id IS NULL THEN
      SELECT id INTO v_contact_id
      FROM public.crm_contacts
      WHERE organization_id = v_org AND primary_linkedin_url = v_row.linkedin_url
      LIMIT 1;
    END IF;

    -- Skip only an unchanged signal. A newer event refreshes the flat signal
    -- fields below while list membership remains independently idempotent.
    IF v_contact_id IS NOT NULL AND EXISTS (
      SELECT 1 FROM public.lead_list_members
      WHERE list_id = v_list_id AND contact_id = v_contact_id
    ) AND EXISTS (
      SELECT 1 FROM public.crm_contacts c
      WHERE c.id = v_contact_id
        AND c.signal_event_id = v_row.signal_event_id
        AND c.signal_date = v_row.signal_date
    ) THEN
      CONTINUE;
    END IF;

    IF v_contact_id IS NULL THEN
      INSERT INTO public.crm_contacts (
        organization_id, display_name, company, company_id, job_title,
        primary_email, primary_linkedin_url, company_website, source, status,
        source_details, discovery_metadata,
        signal_event_id, signal_type, signal_date, signal_detail, signal_source_url,
        company_employee_count, company_employee_range, company_revenue_range, company_industry,
        firmographics_checked_at, firmographics_source,
        email_verification_status, email_verification_source, email_verified_at
      ) VALUES (
        v_org, v_row.full_name, v_row.company_name, v_company_id, v_row.person_title,
        v_row.email, v_row.linkedin_url, 'https://' || v_row.domain, 'aca_native_signal', 'active',
        jsonb_build_object('public_signal_id', v_row.public_signal_id, 'provider', 'quickenrich'),
        jsonb_strip_nulls(jsonb_build_object(
          'signal_type', v_row.signal_type, 'signal_date', to_char(v_row.signal_date, 'YYYY-MM-DD'),
          'signal_detail', v_row.signal_detail, 'signal_source_url', v_row.source_url,
          'ai_signal_company_website', 'https://' || v_row.domain,
          'ai_signal_company_industry', v_row.industry,
          'company_employee_range', v_row.employee_range,
          'company_revenue_range', v_row.revenue_range,
          'provider', 'quickenrich'
        )),
        v_row.signal_event_id, v_row.signal_type, v_row.signal_date, v_row.signal_detail, v_row.source_url,
        v_row.employee_count, v_row.employee_range, v_row.revenue_range, v_row.industry,
        now(), 'quickenrich',
        CASE WHEN v_row.email_status = 'verified' THEN 'valid' ELSE 'unknown' END,
        'quickenrich', CASE WHEN v_row.email_status = 'verified' THEN now() ELSE NULL END
      )
      ON CONFLICT DO NOTHING
      RETURNING id INTO v_contact_id;
      IF v_contact_id IS NULL THEN
        SELECT id INTO v_contact_id FROM public.crm_contacts
        WHERE organization_id = v_org
          AND (primary_email = v_row.email OR primary_linkedin_url = v_row.linkedin_url)
        ORDER BY (primary_email = v_row.email) DESC
        LIMIT 1;
      END IF;
    ELSE
      UPDATE public.crm_contacts SET
        company = v_row.company_name, company_id = v_company_id,
        job_title = COALESCE(v_row.person_title, job_title),
        company_website = COALESCE(company_website, 'https://' || v_row.domain),
        signal_event_id = v_row.signal_event_id, signal_type = v_row.signal_type,
        signal_date = v_row.signal_date, signal_detail = v_row.signal_detail,
        signal_source_url = v_row.source_url,
        company_employee_count = COALESCE(v_row.employee_count, company_employee_count),
        company_employee_range = COALESCE(v_row.employee_range, company_employee_range),
        company_revenue_range = COALESCE(v_row.revenue_range, company_revenue_range),
        company_industry = COALESCE(v_row.industry, company_industry),
        firmographics_checked_at = now(), firmographics_source = 'quickenrich',
        email_verification_status = CASE
          WHEN v_row.email_status = 'verified' THEN 'valid'
          ELSE email_verification_status
        END,
        email_verification_source = CASE
          WHEN v_row.email_status = 'verified' THEN 'quickenrich'
          ELSE email_verification_source
        END,
        email_verified_at = CASE
          WHEN v_row.email_status = 'verified' THEN COALESCE(email_verified_at, now())
          ELSE email_verified_at
        END,
        updated_at = now()
      WHERE id = v_contact_id;
    END IF;

    IF v_contact_id IS NULL THEN CONTINUE; END IF;
    INSERT INTO public.crm_contact_identities (
      organization_id, contact_id, channel, platform_user_id,
      platform_username, is_verified, is_primary
    ) VALUES (
      v_org, v_contact_id, 'email', v_row.email, v_row.email,
      v_row.email_status = 'verified', true
    )
    ON CONFLICT (organization_id, channel, platform_user_id) DO UPDATE SET
      is_verified = crm_contact_identities.is_verified OR EXCLUDED.is_verified;

    INSERT INTO public.crm_contact_identities (
      organization_id, contact_id, channel, platform_user_id,
      platform_username, platform_profile_url, is_verified, is_primary
    ) VALUES (
      v_org, v_contact_id, 'linkedin',
      COALESCE(NULLIF(split_part(v_row.linkedin_url, '/in/', 2), ''), v_row.linkedin_url),
      v_row.full_name, v_row.linkedin_url, false, false
    ) ON CONFLICT (organization_id, channel, platform_user_id) DO NOTHING;

    INSERT INTO public.lead_list_members (list_id, contact_id, source_data)
    VALUES (v_list_id, v_contact_id, jsonb_build_object(
      'source', 'aca_native_signal', 'provider', 'quickenrich',
      'public_signal_id', v_row.public_signal_id,
      'signal_event_id', v_row.signal_event_id,
      'signal_type', v_row.signal_type
    )) ON CONFLICT (list_id, contact_id) DO NOTHING;
    IF FOUND THEN v_added := v_added + 1; END IF;
  END LOOP;

  RETURN jsonb_build_object('ok', true, 'list_id', v_list_id, 'added', v_added);
END;
$$;


ALTER FUNCTION "public"."materialize_quickenrich_signal_leads"("p_batch_size" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."merge_contact_custom_fields"("p_organization_id" "uuid", "p_contact_id" "uuid", "p_patch" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_result JSONB;
  v_null_keys TEXT[];
BEGIN
  -- Keys explicitly set to null are removals, not values to store.
  SELECT ARRAY(
    SELECT key FROM jsonb_each(p_patch) WHERE jsonb_typeof(value) = 'null'
  ) INTO v_null_keys;

  UPDATE crm_contacts
     SET custom_fields = (
           COALESCE(custom_fields, '{}'::jsonb)
           || (SELECT COALESCE(jsonb_object_agg(key, value), '{}'::jsonb)
                 FROM jsonb_each(p_patch)
                WHERE jsonb_typeof(value) <> 'null')
         ) - v_null_keys,
         updated_at = now()
   WHERE id = p_contact_id
     AND organization_id = p_organization_id
  RETURNING custom_fields INTO v_result;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."merge_contact_custom_fields"("p_organization_id" "uuid", "p_contact_id" "uuid", "p_patch" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."merge_contact_custom_fields"("p_organization_id" "uuid", "p_contact_id" "uuid", "p_patch" "jsonb") IS 'Merge keys into crm_contacts.custom_fields atomically. A null value removes the key. Backs custom_fields_patch on PATCH /v1/contacts/{id}; the plain custom_fields field still replaces wholesale.';



CREATE OR REPLACE FUNCTION "public"."merge_conversation_metadata"("p_conversation_id" "uuid", "p_metadata_update" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_result JSONB;
BEGIN
  UPDATE crm_conversations
  SET metadata = COALESCE(metadata, '{}'::jsonb) || p_metadata_update,
      updated_at = now()
  WHERE id = p_conversation_id
  RETURNING metadata INTO v_result;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."merge_conversation_metadata"("p_conversation_id" "uuid", "p_metadata_update" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."merge_into_active_mailtester_job"("p_organization_id" "uuid", "p_new_emails" "text"[], "p_new_total_increment" integer, "p_pre_pass_increment" integer, "p_valid_increment" integer, "p_invalid_increment" integer, "p_catch_all_increment" integer, "p_unknown_increment" integer, "p_list_id" "uuid") RETURNS TABLE("id" "uuid", "appended" integer, "pending_after" integer, "total_after" integer)
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_job_id uuid;
  v_existing text[];
  v_existing_set text[];
  v_to_append text[];
  v_merged text[];
  v_appended int;
BEGIN
  SELECT job.id, job.pending_emails
    INTO v_job_id, v_existing
    FROM public.mailtester_verification_jobs job
   WHERE job.organization_id = p_organization_id
     AND job.status IN ('queued', 'running')
   ORDER BY (CASE WHEN job.status = 'running' THEN 0 ELSE 1 END), job.created_at ASC
   LIMIT 1
   FOR UPDATE;

  IF v_job_id IS NULL THEN
    RETURN;
  END IF;

  SELECT COALESCE(array_agg(DISTINCT lower(email)), '{}')
    INTO v_existing_set
    FROM unnest(COALESCE(v_existing, '{}'::text[])) AS email;

  SELECT COALESCE(array_agg(DISTINCT email), '{}')
    INTO v_to_append
    FROM unnest(COALESCE(p_new_emails, '{}'::text[])) AS email
   WHERE lower(email) <> ALL(v_existing_set);

  v_appended := COALESCE(array_length(v_to_append, 1), 0);
  v_merged := COALESCE(v_existing, '{}'::text[]) || COALESCE(v_to_append, '{}'::text[]);

  UPDATE public.mailtester_verification_jobs job
     SET pending_emails = v_merged,
         total = job.total + v_appended
   WHERE job.id = v_job_id;

  IF p_list_id IS NOT NULL THEN
    INSERT INTO public.mailtester_job_lists (job_id, list_id, attached_at, emails_contributed)
    VALUES (v_job_id, p_list_id, now(), v_appended)
    ON CONFLICT (job_id, list_id)
      DO UPDATE SET emails_contributed = mailtester_job_lists.emails_contributed + EXCLUDED.emails_contributed;
  END IF;

  RETURN QUERY
    SELECT v_job_id,
           v_appended,
           COALESCE(array_length(v_merged, 1), 0),
           (SELECT job.total FROM public.mailtester_verification_jobs job WHERE job.id = v_job_id);
END;
$$;


ALTER FUNCTION "public"."merge_into_active_mailtester_job"("p_organization_id" "uuid", "p_new_emails" "text"[], "p_new_total_increment" integer, "p_pre_pass_increment" integer, "p_valid_increment" integer, "p_invalid_increment" integer, "p_catch_all_increment" integer, "p_unknown_increment" integer, "p_list_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."merge_lead_lists"("p_source_list_ids" "uuid"[], "p_target_list_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org_id UUID := get_user_organization_id();
  v_target_org UUID;
  v_source_count INTEGER;
  v_inserted INTEGER;
BEGIN
  -- Validate the caller owns the target list via their org
  SELECT organization_id INTO v_target_org
  FROM public.lead_lists
  WHERE id = p_target_list_id
    AND organization_id = v_org_id;

  IF v_target_org IS NULL THEN
    RAISE EXCEPTION 'Target list not found or access denied';
  END IF;

  -- Validate every source list belongs to the same org
  SELECT count(*) INTO v_source_count
  FROM public.lead_lists
  WHERE id = ANY(p_source_list_ids)
    AND organization_id = v_org_id;

  IF v_source_count IS DISTINCT FROM array_length(p_source_list_ids, 1) THEN
    RAISE EXCEPTION 'One or more source lists not found or access denied';
  END IF;

  INSERT INTO public.lead_list_members (list_id, contact_id, source_data)
  SELECT DISTINCT ON (m.contact_id)
    p_target_list_id,
    m.contact_id,
    jsonb_build_object('merged_from_list_id', m.list_id)
  FROM public.lead_list_members m
  WHERE m.list_id = ANY(p_source_list_ids)
    AND m.list_id <> p_target_list_id
  ORDER BY m.contact_id, m.list_id
  ON CONFLICT DO NOTHING;

  GET DIAGNOSTICS v_inserted = ROW_COUNT;

  RETURN v_inserted;
END;
$$;


ALTER FUNCTION "public"."merge_lead_lists"("p_source_list_ids" "uuid"[], "p_target_list_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."merge_mailbox_metadata"("p_id" "uuid", "p_merge" "jsonb") RETURNS "void"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$ UPDATE email_mailboxes SET metadata = COALESCE(metadata, '{}'::jsonb) || p_merge, updated_at = now() WHERE id = p_id; $$;


ALTER FUNCTION "public"."merge_mailbox_metadata"("p_id" "uuid", "p_merge" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."merge_mailbox_smtp_credentials"("p_id" "uuid", "p_encrypted" "text") RETURNS "void"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$ UPDATE email_mailboxes SET metadata = COALESCE(metadata, '{}'::jsonb) || jsonb_build_object('smtp_credentials', p_encrypted), updated_at = now() WHERE id = p_id; $$;


ALTER FUNCTION "public"."merge_mailbox_smtp_credentials"("p_id" "uuid", "p_encrypted" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."messaging_funnel"("p_org_id" "uuid", "p_campaign_id" "uuid" DEFAULT NULL::"uuid", "p_since" timestamp with time zone DEFAULT ("now"() - '90 days'::interval)) RETURNS TABLE("campaign_id" "uuid", "channel" "text", "sent" integer, "delivered" integer, "failed" integer, "replied" integer, "positive" integer, "booked" integer, "out_of_office" integer, "auto_reply" integer, "opted_out" integer)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  -- NOT EXISTS, not NOT IN: get_accessible_organization_ids() returns a NULL row for a
  -- user with no org, and NOT (x IN (NULL)) is NULL, which would skip this check.
  IF coalesce(auth.role(), '') <> 'service_role'
     AND NOT EXISTS (SELECT 1 FROM get_accessible_organization_ids() g WHERE g = p_org_id) THEN
    RAISE EXCEPTION 'Not allowed for this organization' USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  WITH sends AS (
    SELECT
      l.campaign_id AS cid, l.channel AS ch, l.contact_id, l.to_address,
      min(l.created_at) AS first_sent,
      bool_or(l.status <> 'failed') AS any_ok,
      bool_or(l.status IN ('delivered', 'read')) AS any_delivered
    FROM messaging_send_log l
    WHERE l.organization_id = p_org_id
      AND l.source = 'campaign'
      AND l.created_at >= p_since
      AND l.contact_id IS NOT NULL
      AND (p_campaign_id IS NULL OR l.campaign_id = p_campaign_id)
    GROUP BY 1, 2, 3, 4
  ),
  leads AS (
    SELECT
      s.*,
      cv.lead_intent,
      EXISTS (SELECT 1 FROM crm_messages m WHERE m.conversation_id = cv.id AND m.direction = 'inbound' AND m.created_at >= s.first_sent) AS has_reply,
      EXISTS (SELECT 1 FROM ghl_appointment_log a WHERE a.organization_id = p_org_id AND a.contact_id = s.contact_id AND a.created_at >= s.first_sent AND coalesce(a.appointment_status, 'booked') <> 'cancelled') AS has_appointment,
      EXISTS (SELECT 1 FROM channel_opt_outs o WHERE o.organization_id = p_org_id AND o.phone_e164 = s.to_address AND o.channel IN (s.ch, 'all')) AS is_opted_out
    FROM sends s
    LEFT JOIN crm_conversations cv
      ON cv.contact_id = s.contact_id
     AND cv.channel = CASE WHEN s.ch = 'sms' THEN 'sms' ELSE 'whatsapp' END
     AND cv.organization_id = p_org_id
  )
  SELECT
    x.cid, x.ch,
    count(*) FILTER (WHERE x.any_ok)::int,
    count(*) FILTER (WHERE x.any_delivered)::int,
    count(*) FILTER (WHERE NOT x.any_ok)::int,
    count(*) FILTER (WHERE x.has_reply AND coalesce(x.lead_intent, '') NOT IN ('out_of_office', 'auto_reply'))::int,
    count(*) FILTER (WHERE x.has_reply AND x.lead_intent IN ('interested', 'meeting_booked'))::int,
    count(*) FILTER (WHERE x.lead_intent = 'meeting_booked' OR x.has_appointment)::int,
    count(*) FILTER (WHERE x.has_reply AND x.lead_intent = 'out_of_office')::int,
    count(*) FILTER (WHERE x.has_reply AND x.lead_intent = 'auto_reply')::int,
    count(*) FILTER (WHERE x.is_opted_out)::int
  FROM leads x
  GROUP BY x.cid, x.ch;
END;
$$;


ALTER FUNCTION "public"."messaging_funnel"("p_org_id" "uuid", "p_campaign_id" "uuid", "p_since" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."migrate_linkedin_connections_to_crm"() RETURNS TABLE("connections_migrated" integer, "contacts_created" integer, "contacts_updated" integer, "accounts_linked" integer, "errors" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_conn RECORD;
  v_result RECORD;
  v_migrated INTEGER := 0;
  v_created INTEGER := 0;
  v_updated INTEGER := 0;
  v_linked INTEGER := 0;
  v_errors INTEGER := 0;
BEGIN
  FOR v_conn IN
    SELECT * FROM linkedin_connections
    ORDER BY organization_id, synced_at DESC
  LOOP
    BEGIN
      SELECT * INTO v_result
      FROM sync_linkedin_connection_to_crm(
        v_conn.organization_id,
        v_conn.account_id,
        v_conn.linkedin_id,
        v_conn.linkedin_url,
        v_conn.first_name,
        v_conn.last_name,
        v_conn.full_name,
        v_conn.headline,
        v_conn.job_title,
        v_conn.company,
        v_conn.location,
        v_conn.profile_picture_url,
        v_conn.connected_at,
        v_conn.raw_data
      );

      v_migrated := v_migrated + 1;

      IF v_result.action = 'created' THEN
        v_created := v_created + 1;
      ELSIF v_result.action = 'updated' THEN
        v_updated := v_updated + 1;
      ELSIF v_result.action = 'account_linked' THEN
        v_linked := v_linked + 1;
      END IF;

    EXCEPTION WHEN OTHERS THEN
      v_errors := v_errors + 1;
      RAISE NOTICE 'Error migrating connection %: %', v_conn.id, SQLERRM;
    END;
  END LOOP;

  RETURN QUERY SELECT v_migrated, v_created, v_updated, v_linked, v_errors;
END;
$$;


ALTER FUNCTION "public"."migrate_linkedin_connections_to_crm"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."migrate_linkedin_connections_to_crm"() IS 'One-time migration of all linkedin_connections to crm_contacts';



CREATE OR REPLACE FUNCTION "public"."mirror_email_verification_to_crm_contacts"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  UPDATE public.crm_contacts c
  SET
    email_verification_status = NEW.status,
    email_is_catch_all        = COALESCE(NEW.is_catch_all, false),
    email_is_role             = COALESCE(NEW.is_role, false),
    email_is_disposable       = COALESCE(NEW.is_disposable, false),
    email_is_spamtrap         = COALESCE(NEW.is_spamtrap, false),
    email_is_deliverable      = (NEW.status = 'valid'),
    email_verified_at         = NEW.verified_at,
    email_verification_source = NEW.provider
  WHERE c.organization_id = NEW.organization_id
    AND LOWER(c.primary_email) = NEW.email_lower;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."mirror_email_verification_to_crm_contacts"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."native_acquisition_signal_presentation"("p_company_name" "text", "p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
  WITH facts AS (
    SELECT
      coalesce(nullif(btrim(p_payload->>'form_type'), ''), 'SEC filing') AS form_type,
      CASE WHEN jsonb_typeof(p_payload->'items') = 'array' THEN p_payload->'items' ELSE '[]'::jsonb END AS items
  ), copy AS (
    SELECT
      format('%s filed an acquisition-related %s', p_company_name, form_type) AS title,
      (SELECT string_agg(value, '; ' ORDER BY ordinality)
       FROM jsonb_array_elements_text(items) WITH ORDINALITY AS item(value, ordinality)
       WHERE ordinality <= 4) AS item_summary,
      items
    FROM facts
  )
  SELECT jsonb_build_object(
    'title', title,
    'detail', title || '.' || CASE WHEN item_summary IS NOT NULL THEN ' Filing items: ' || item_summary || '.' ELSE '' END,
    'why_it_matters', 'Acquisition activity creates integration, consolidation, and change-management needs with executive visibility.',
    'details', p_payload || jsonb_build_object('filing_items', items)
  )
  FROM copy;
$$;


ALTER FUNCTION "public"."native_acquisition_signal_presentation"("p_company_name" "text", "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."native_signal_presentation"("p_company_name" "text", "p_event_type" "text", "p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_roles jsonb := CASE WHEN jsonb_typeof(p_payload->'roles') = 'array'
    THEN p_payload->'roles' ELSE '[]'::jsonb END;
  v_role_titles text[];
  v_locations text[];
  v_new_count integer;
  v_total_count integer;
  v_title text;
  v_detail text;
  v_role_summary text;
  v_amount_usd numeric;
  v_amount_label text;
  v_investor_count integer;
BEGIN
  SELECT coalesce(array_agg(DISTINCT nullif(btrim(role->>'title'), ''))
    FILTER (WHERE nullif(btrim(role->>'title'), '') IS NOT NULL), '{}')
  INTO v_role_titles FROM jsonb_array_elements(v_roles) role;
  SELECT coalesce(array_agg(DISTINCT nullif(btrim(role->>'location'), ''))
    FILTER (WHERE nullif(btrim(role->>'location'), '') IS NOT NULL), '{}')
  INTO v_locations FROM jsonb_array_elements(v_roles) role;

  IF coalesce(p_payload->>'new_role_count', '') ~ '^\d+$' THEN
    v_new_count := (p_payload->>'new_role_count')::integer;
  ELSE
    v_new_count := jsonb_array_length(v_roles);
  END IF;
  IF coalesce(p_payload->>'total_open_roles', '') ~ '^\d+$' THEN
    v_total_count := (p_payload->>'total_open_roles')::integer;
  END IF;

  IF nullif(btrim(p_payload->>'headline'), '') IS NOT NULL
     AND nullif(btrim(p_payload->>'summary'), '') IS NOT NULL THEN
    v_title := btrim(p_payload->>'headline');
    v_detail := btrim(p_payload->>'summary');
  ELSIF p_event_type = 'hiring' THEN
    v_title := format('%s opened %s new %s', p_company_name, v_new_count,
      CASE WHEN v_new_count = 1 THEN 'role' ELSE 'roles' END);
    SELECT string_agg(
      CASE WHEN nullif(btrim(role->>'location'), '') IS NOT NULL
        THEN format('%s (%s)', btrim(role->>'title'), btrim(role->>'location'))
        ELSE btrim(role->>'title') END,
      '; ' ORDER BY ordinality
    ) INTO v_role_summary
    FROM jsonb_array_elements(v_roles) WITH ORDINALITY AS item(role, ordinality)
    WHERE nullif(btrim(role->>'title'), '') IS NOT NULL
      AND ordinality <= 3;
    v_detail := v_title || '.'
      || CASE WHEN v_role_summary IS NOT NULL THEN ' Roles: ' || v_role_summary || '.' ELSE '' END
      || CASE WHEN v_total_count IS NOT NULL THEN format(' %s total open roles.', v_total_count) ELSE '' END;
  ELSIF p_event_type = 'funding' THEN
    IF coalesce(p_payload->>'total_amount_sold', '') ~ '^\d+(\.\d+)?$' THEN
      v_amount_usd := (p_payload->>'total_amount_sold')::numeric;
    ELSIF coalesce(p_payload->>'amount_usd', '') ~ '^\d+(\.\d+)?$' THEN
      v_amount_usd := (p_payload->>'amount_usd')::numeric;
    ELSIF coalesce(p_payload->>'total_offering_amount', '') ~ '^\d+(\.\d+)?$' THEN
      v_amount_usd := (p_payload->>'total_offering_amount')::numeric;
    END IF;
    IF v_amount_usd IS NOT NULL THEN
      v_amount_label := CASE
        WHEN v_amount_usd >= 1000000000 THEN '$' || trim(to_char(v_amount_usd / 1000000000, 'FM999999990.0')) || 'B'
        WHEN v_amount_usd >= 1000000 THEN '$' || trim(to_char(v_amount_usd / 1000000, 'FM999999990.0')) || 'M'
        WHEN v_amount_usd >= 1000 THEN '$' || trim(to_char(v_amount_usd / 1000, 'FM999999990.0')) || 'K'
        ELSE '$' || trim(to_char(v_amount_usd, 'FM999999990')) END;
      v_amount_label := replace(v_amount_label, '.0B', 'B');
      v_amount_label := replace(v_amount_label, '.0M', 'M');
      v_amount_label := replace(v_amount_label, '.0K', 'K');
    END IF;
    IF coalesce(p_payload->>'investor_count', '') ~ '^\d+$' THEN
      v_investor_count := (p_payload->>'investor_count')::integer;
    END IF;
    v_title := CASE WHEN v_amount_label IS NOT NULL
      THEN format('%s disclosed %s in funding', p_company_name, v_amount_label)
      ELSE format('%s disclosed a funding event', p_company_name) END;
    v_detail := v_title || '.'
      || CASE WHEN nullif(btrim(p_payload->>'form_type'), '') IS NOT NULL
        THEN format(' %s filing.', btrim(p_payload->>'form_type')) ELSE '' END
      || CASE WHEN v_investor_count IS NOT NULL
        THEN format(' %s reported %s.', v_investor_count,
          CASE WHEN v_investor_count = 1 THEN 'investor' ELSE 'investors' END) ELSE '' END;
  ELSE
    v_title := coalesce(nullif(btrim(p_payload->>'headline'), ''),
      nullif(btrim(p_payload->>'title'), ''),
      p_company_name || ': ' || replace(p_event_type, '_', ' '));
    v_detail := coalesce(nullif(btrim(p_payload->>'summary'), ''),
      nullif(btrim(p_payload->>'detail'), ''), v_title);
  END IF;

  RETURN jsonb_strip_nulls(jsonb_build_object(
    'title', v_title,
    'detail', v_detail,
    'why_it_matters', coalesce(nullif(btrim(p_payload->>'why_it_matters'), ''),
      CASE
        WHEN p_event_type = 'hiring' THEN 'Active hiring indicates budget, growth, and near-term operational needs.'
        WHEN p_event_type = 'funding' THEN 'Fresh financing signals available budget and a near-term window for new vendors and growth initiatives.'
      END),
    'amount_label', v_amount_label,
    'amount_usd', v_amount_usd,
    'details', p_payload || jsonb_strip_nulls(jsonb_build_object(
      'new_role_count', CASE WHEN p_event_type = 'hiring' THEN v_new_count END,
      'total_open_roles', CASE WHEN p_event_type = 'hiring' THEN v_total_count END,
      'role_titles', CASE WHEN p_event_type = 'hiring' THEN to_jsonb(v_role_titles) END,
      'locations', CASE WHEN p_event_type = 'hiring' THEN to_jsonb(v_locations) END,
      'amount_label', CASE WHEN p_event_type = 'funding' THEN v_amount_label END,
      'amount_usd', CASE WHEN p_event_type = 'funding' THEN v_amount_usd END
    ))
  ));
END;
$_$;


ALTER FUNCTION "public"."native_signal_presentation"("p_company_name" "text", "p_event_type" "text", "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."next_email_enrollment_job_page"("p_job_id" "uuid", "p_after" "uuid" DEFAULT NULL::"uuid", "p_limit" integer DEFAULT 2500) RETURNS "uuid"[]
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT COALESCE(array_agg(contact_id ORDER BY contact_id), '{}'::UUID[])
  FROM (
    SELECT contact_id
    FROM public.email_enrollment_job_members
    WHERE job_id = p_job_id
      AND (p_after IS NULL OR contact_id > p_after)
    ORDER BY contact_id
    LIMIT p_limit
  ) p;
$$;


