CREATE OR REPLACE FUNCTION "public"."next_unused_idea"("p_autopilot_id" "uuid", "p_blueprint_id" "uuid", "p_tag_ids" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS SETOF "public"."content_ideas"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  SELECT i.*
  FROM public.content_ideas i
  JOIN public.autopilots a ON a.id = p_autopilot_id AND a.organization_id = i.organization_id
  WHERE (
      cardinality(coalesce(p_tag_ids, '{}'::uuid[])) = 0
      OR EXISTS (
        SELECT 1 FROM public.idea_tag_assignments x
        WHERE x.idea_id = i.id AND x.tag_id = ANY (p_tag_ids)
      )
    )
    AND (NOT a.only_approved_ideas OR i.guidelines_approved_at IS NOT NULL)
    AND NOT EXISTS (
      SELECT 1 FROM public.autopilot_idea_exclusions ex
      WHERE ex.autopilot_id = p_autopilot_id AND ex.idea_id = i.id
    )
    AND NOT EXISTS (
      SELECT 1 FROM public.content_outputs co
      WHERE co.idea_id = i.id
        AND co.autopilot_id = p_autopilot_id
        AND co.blueprint_id = p_blueprint_id
    )
  ORDER BY i.created_at ASC
  LIMIT 1;
$$;


ALTER FUNCTION "public"."next_unused_idea"("p_autopilot_id" "uuid", "p_blueprint_id" "uuid", "p_tag_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."normalize_company_domain"("p_domain" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  select case
    when d is null or d = '' then null
    -- Only strip when something meaningful remains: 3+ labels. Guards against
    -- turning a real domain like `careers.com` into `com`.
    when array_length(string_to_array(d, '.'), 1) >= 3
         and split_part(d, '.', 1) in (
           'www','careers','career','jobs','job','apply','recruiting','recruit',
           'info','go','about','shop','store','blog','my','portal','app','apps',
           'secure','work','hire','talent','join','get','try','start'
         )
      then substring(d from position('.' in d) + 1)
    else d
  end
  from (select lower(trim(coalesce(p_domain, ''))) as d) s;
$$;


ALTER FUNCTION "public"."normalize_company_domain"("p_domain" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."normalize_company_domain"("p_domain" "text") IS 'Strip a known non-corporate leading label (www, careers, jobs, apply, ...) so careers.sharp.com and sharp.com resolve to one company row. Only applies at 3+ labels, so careers.com is left alone.';



CREATE OR REPLACE FUNCTION "public"."normalize_country_code"("p_value" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE PARALLEL SAFE
    AS $_$
  WITH v AS (SELECT lower(btrim(COALESCE(p_value, ''))) AS s)
  SELECT CASE
    WHEN v.s = '' THEN NULL
    ELSE COALESCE(
      (
        SELECT m.code
        FROM (VALUES
          ('united states', 'US'), ('united states of america', 'US'), ('usa', 'US'), ('u.s.', 'US'), ('u.s.a.', 'US'),
          ('united kingdom', 'GB'), ('uk', 'GB'), ('great britain', 'GB'), ('england', 'GB'), ('scotland', 'GB'),
          ('canada', 'CA'), ('australia', 'AU'), ('ireland', 'IE'), ('germany', 'DE'), ('deutschland', 'DE'),
          ('france', 'FR'), ('netherlands', 'NL'), ('the netherlands', 'NL'), ('holland', 'NL'),
          ('spain', 'ES'), ('italy', 'IT'), ('sweden', 'SE'), ('switzerland', 'CH'), ('norway', 'NO'),
          ('denmark', 'DK'), ('finland', 'FI'), ('belgium', 'BE'), ('austria', 'AT'), ('portugal', 'PT'),
          ('poland', 'PL'), ('israel', 'IL'), ('india', 'IN'), ('singapore', 'SG'), ('japan', 'JP'),
          ('south korea', 'KR'), ('korea', 'KR'), ('china', 'CN'), ('hong kong', 'HK'),
          ('united arab emirates', 'AE'), ('uae', 'AE'), ('saudi arabia', 'SA'), ('brazil', 'BR'),
          ('mexico', 'MX'), ('argentina', 'AR'), ('south africa', 'ZA'), ('new zealand', 'NZ'),
          ('estonia', 'EE'), ('lithuania', 'LT'), ('latvia', 'LV'), ('czechia', 'CZ'), ('czech republic', 'CZ'),
          ('romania', 'RO'), ('greece', 'GR'), ('turkey', 'TR'), ('nigeria', 'NG'), ('kenya', 'KE'),
          ('egypt', 'EG'), ('bulgaria', 'BG'), ('hungary', 'HU'), ('luxembourg', 'LU'), ('ukraine', 'UA'),
          ('russia', 'RU'), ('jordan', 'JO'), ('kuwait', 'KW'), ('pakistan', 'PK'), ('philippines', 'PH'),
          ('macau', 'MO'), ('morocco', 'MA'), ('ghana', 'GH'), ('senegal', 'SN'), ('burkina faso', 'BF'),
          ('equatorial guinea', 'GQ'), ('european union', 'EU')
        ) AS m(name, code)
        WHERE m.name = v.s
      ),
      CASE WHEN v.s ~ '^[a-z]{2}$' THEN upper(v.s) ELSE NULL END
    )
  END
  FROM v;
$_$;


ALTER FUNCTION "public"."normalize_country_code"("p_value" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."normalize_country_code"("p_value" "text") IS 'Coerces a country value to ISO-3166 alpha-2. Accepts a bare 2-letter code or a common full name; NULL when neither.';



CREATE OR REPLACE FUNCTION "public"."normalize_employee_range_text"("p_raw" "text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$
DECLARE
  v_trimmed TEXT;
  v_numbers INTEGER[];
  v_mid NUMERIC;
BEGIN
  IF p_raw IS NULL THEN RETURN NULL; END IF;
  v_trimmed := TRIM(p_raw);
  IF v_trimmed = '' THEN RETURN NULL; END IF;

  IF v_trimmed = ANY (ARRAY['1-10','11-20','21-50','51-200','201-500','501-1000','1001-5000','5001+']) THEN
    RETURN v_trimmed;
  END IF;

  SELECT ARRAY(SELECT (m[1])::INTEGER FROM regexp_matches(v_trimmed, '\d+', 'g') AS m) INTO v_numbers;
  IF v_numbers IS NULL OR array_length(v_numbers, 1) IS NULL THEN RETURN NULL; END IF;

  IF array_length(v_numbers, 1) = 1 THEN
    RETURN public.bucket_employee_range(v_numbers[1]);
  END IF;

  v_mid := (LEAST(v_numbers[1], v_numbers[2]) + GREATEST(v_numbers[1], v_numbers[2])) / 2.0;
  RETURN public.bucket_employee_range(ROUND(v_mid)::INTEGER);
END;
$$;


ALTER FUNCTION "public"."normalize_employee_range_text"("p_raw" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."normalize_inbox_keyword"("p_keyword" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  SELECT lower(trim(regexp_replace(COALESCE(p_keyword, ''), '\s+', ' ', 'g')));
$$;


ALTER FUNCTION "public"."normalize_inbox_keyword"("p_keyword" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."normalize_industry_text"("p_raw" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  SELECT NULLIF(REGEXP_REPLACE(TRIM(p_raw), '\s+', ' ', 'g'), '');
$$;


ALTER FUNCTION "public"."normalize_industry_text"("p_raw" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."normalize_sequence_steps_fn"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $_$DECLARE i int; el jsonb; b text; nb text; BEGIN IF NEW.steps IS NULL OR jsonb_typeof(NEW.steps) <> 'array' THEN RETURN NEW; END IF; FOR i IN 0 .. jsonb_array_length(NEW.steps) - 1 LOOP el := NEW.steps->i; IF (el->>'type') = 'email' AND el->>'body' IS NOT NULL THEN b := el->>'body'; nb := regexp_replace(b, '<br[^>]*>', '<br>', 'gi'); nb := regexp_replace(nb, '<p[^>]*>([[:space:]]|&nbsp;|&#160;)*</p>', '', 'gi'); nb := regexp_replace(nb, '</p[ ]*>[[:space:]]*<p[^>]*>', '<br><br>', 'gi'); nb := regexp_replace(nb, '</?p[^>]*>', '', 'gi'); nb := replace(replace(nb, chr(13) || chr(10), chr(10)), chr(13), chr(10)); nb := regexp_replace(nb, '(' || chr(10) || '){2,}', '<br><br>', 'g'); nb := replace(nb, chr(10), '<br>'); nb := regexp_replace(nb, '(<br>[[:space:]]*){3,}', '<br><br>', 'gi'); nb := regexp_replace(nb, '^([[:space:]]|<br>)+', '', 'gi'); nb := regexp_replace(nb, '([[:space:]]|<br>)+$', '', 'gi'); IF nb IS DISTINCT FROM b THEN NEW.steps := jsonb_set(NEW.steps, ARRAY[i::text, 'body'], to_jsonb(nb)); END IF; END IF; END LOOP; RETURN NEW; END;$_$;


ALTER FUNCTION "public"."normalize_sequence_steps_fn"() OWNER TO "postgres";


