CREATE OR REPLACE FUNCTION "public"."pause_lead_list_processing"("p_list_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_policy_id UUID;
  v_count INTEGER;
BEGIN
  UPDATE public.lead_list_processing_policies policy
  SET paused_at = COALESCE(policy.paused_at, NOW()),
      updated_at = NOW()
  WHERE policy.lead_list_id = p_list_id
    AND EXISTS (
      SELECT 1
      FROM public.organization_members membership
      WHERE membership.organization_id = policy.organization_id
        AND membership.user_id = auth.uid()
    )
  RETURNING policy.id INTO v_policy_id;

  IF v_policy_id IS NULL THEN
    RAISE EXCEPTION 'Configure lead processing for this list before pausing it';
  END IF;

  UPDATE public.lead_list_processing_items item
  SET pause_requested_at = NOW(),
      updated_at = NOW()
  WHERE item.policy_id = v_policy_id
    AND item.status = 'processing'
    AND item.stage <> 'enrolling';

  SELECT COUNT(*)::INTEGER INTO v_count
  FROM public.lead_list_processing_items item
  WHERE item.policy_id = v_policy_id
    AND item.status IN ('pending', 'retry', 'processing');

  RETURN v_count;
END;
$$;


ALTER FUNCTION "public"."pause_lead_list_processing"("p_list_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pick_warmup_partners"("p_sender_ids" "uuid"[], "p_cooldown_days" integer DEFAULT 7, "p_max_receives_per_day" integer DEFAULT 3, "p_seed_max_receives_per_day" integer DEFAULT 20) RETURNS TABLE("sender_id" "uuid", "partner_id" "uuid")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH senders AS MATERIALIZED (
    SELECT m.id, m.organization_id, m.sending_domain_id, requested.ordinality AS priority
    FROM unnest(p_sender_ids) WITH ORDINALITY AS requested(id, ordinality)
    JOIN public.email_mailboxes m ON m.id = requested.id
  ),
  recent_pairs AS MATERIALIZED (
    SELECT w.from_mailbox_id AS id,
           array_agg(DISTINCT w.to_mailbox_id) AS blocked
    FROM public.email_warmup_sends w
    WHERE w.from_mailbox_id = ANY(p_sender_ids)
      AND COALESCE(w.sent_at, w.created_at) > now() - make_interval(days => p_cooldown_days)
      AND w.status <> 'failed'
    GROUP BY w.from_mailbox_id
  ),
  received AS MATERIALIZED (
    SELECT w.to_mailbox_id, count(*)::int AS n
    FROM public.email_warmup_sends w
    WHERE COALESCE(w.sent_at, w.created_at) >= date_trunc('day', now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'
      AND w.status <> 'failed'
    GROUP BY w.to_mailbox_id
  ),
  seeds AS MATERIALIZED (
    SELECT m.id
    FROM public.email_mailboxes m
    WHERE 'warmup-seed' = ANY(COALESCE(m.tags, '{}'::text[]))
  ),
  -- Share of today's seed budget released so far, plus one hour's worth so the
  -- first hour is not empty.
  seed_budget AS MATERIALIZED (
    SELECT LEAST(
      p_seed_max_receives_per_day,
      CEIL(
        p_seed_max_receives_per_day * (
          EXTRACT(EPOCH FROM (now() AT TIME ZONE 'UTC') - date_trunc('day', now() AT TIME ZONE 'UTC'))
            / 86400.0
          + 1.0 / 24
        )
      )::int
    ) AS n
  ),
  domain_seed_contact AS MATERIALIZED (
    SELECT f.sending_domain_id, count(*)::int AS n
    FROM public.email_warmup_sends w
    JOIN public.email_mailboxes f ON f.id = w.from_mailbox_id
    WHERE COALESCE(w.sent_at, w.created_at) > now() - interval '7 days'
      AND w.status <> 'failed'
      AND w.to_mailbox_id IN (SELECT id FROM seeds)
      AND f.sending_domain_id IN (SELECT sending_domain_id FROM senders)
    GROUP BY f.sending_domain_id
  ),
  pool AS MATERIALIZED (
    SELECT x.*
    FROM (
      SELECT m.id,
             m.organization_id,
             m.sending_domain_id,
             (s.id IS NOT NULL) AS is_seed,
             COALESCE(r.n, 0) AS received_today,
             CASE WHEN s.id IS NOT NULL THEN (SELECT n FROM seed_budget) ELSE p_max_receives_per_day END
               - COALESCE(r.n, 0) AS capacity
      FROM public.email_mailboxes m
      LEFT JOIN seeds s ON s.id = m.id
      LEFT JOIN received r ON r.to_mailbox_id = m.id
      LEFT JOIN public.warmup_endpoint_health h ON h.mailbox_id = m.id
      WHERE m.status IN ('ready', 'warming', 'paused')
        AND NOT (COALESCE(h.dead_as_recipient, false) AND COALESCE(r.n, 0) >= 1)
    ) x
    WHERE x.capacity > 0
  ),
  choices AS MATERIALIZED (
    SELECT s.id AS sender_id, s.priority,
           p.id AS partner_id,
           p.capacity,
           COALESCE(dsc.n, 0) AS domain_seed_contact
    FROM senders s
    LEFT JOIN recent_pairs rp ON rp.id = s.id
    LEFT JOIN domain_seed_contact dsc ON dsc.sending_domain_id = s.sending_domain_id
    CROSS JOIN LATERAL (
      SELECT pl.id, pl.capacity
      FROM pool pl
      WHERE pl.id <> s.id
        AND NOT (pl.id = ANY(COALESCE(rp.blocked, ARRAY[]::uuid[])))
      ORDER BY
        pl.is_seed DESC,
        (pl.organization_id IS DISTINCT FROM s.organization_id) DESC,
        (pl.sending_domain_id IS DISTINCT FROM s.sending_domain_id) DESC,
        pl.received_today ASC,
        random()
      LIMIT 1
    ) p
  ),
  ranked AS (
    SELECT c.sender_id, c.priority,
           c.partner_id,
           c.capacity,
           row_number() OVER (
             PARTITION BY c.partner_id
             ORDER BY c.priority ASC, c.domain_seed_contact ASC, random()
           ) AS rn
    FROM choices c
  )
  SELECT r.sender_id, r.partner_id
  FROM ranked r
  WHERE r.rn <= r.capacity
  ORDER BY r.priority;
$$;


ALTER FUNCTION "public"."pick_warmup_partners"("p_sender_ids" "uuid"[], "p_cooldown_days" integer, "p_max_receives_per_day" integer, "p_seed_max_receives_per_day" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."populate_lead_processing_item_contact_snapshot"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  contact_record record;
BEGIN
  SELECT
    NULLIF(BTRIM(contact.primary_email), '') IS NOT NULL AS has_email,
    contact.email_verification_status,
    contact.moltsets_attempted_at IS NOT NULL AS search_attempted
  INTO contact_record
  FROM public.crm_contacts contact
  WHERE contact.id = NEW.contact_id;

  IF FOUND THEN
    NEW.contact_has_email := contact_record.has_email;
    NEW.contact_email_verification_status := contact_record.email_verification_status;
    NEW.contact_email_search_attempted := contact_record.search_attempted;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."populate_lead_processing_item_contact_snapshot"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."postshiba_cluster_send_counts"("p_org_id" "uuid") RETURNS TABLE("emails_per_hour" integer, "emails_per_day" integer, "sent_last_hour" bigint, "sent_last_day" bigint)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with me as (
    select team_id, cluster_id from postshiba_connections where organization_id = p_org_id
  ), cluster as (
    select c.organization_id, c.emails_per_hour, c.emails_per_day
    from postshiba_connections c join me on c.team_id = me.team_id and c.cluster_id = me.cluster_id
  ), sends as (
    select l.created_at
    from email_send_log l
    join cluster c on c.organization_id = l.organization_id
    join email_mailboxes m on m.id = l.mailbox_id and m.connection_type = 'postshiba'
    where l.created_at >= now() - interval '24 hours'
      and l.status in ('sending', 'sent', 'delivered', 'opened', 'clicked', 'replied', 'bounced', 'blocked', 'spam')
  )
  select (select max(emails_per_hour) from cluster),
         (select max(emails_per_day) from cluster),
         (select count(*) from sends where created_at >= now() - interval '1 hour'),
         (select count(*) from sends)
  where exists (select 1 from me);
$$;


ALTER FUNCTION "public"."postshiba_cluster_send_counts"("p_org_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."postshiba_rebalance_cluster"("p_team_id" "text", "p_cluster_id" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_budget integer;
  v_room bigint;
  v_domain record;
begin
  select max(emails_per_day) into v_budget
  from postshiba_connections
  where team_id = p_team_id and cluster_id = p_cluster_id;

  if v_budget is not null and v_budget > 0 then
    select greatest(v_budget - coalesce(sum(d.postshiba_daily_volume), 0), 0) into v_room
    from email_sending_domains d
    join postshiba_connections c on c.id = d.postshiba_connection_id
    where c.team_id = p_team_id and c.cluster_id = p_cluster_id
      and d.infra_type = 'postshiba' and d.postshiba_volume_mode = 'manual';

    with capacity as (
      select d.id,
             d.postshiba_sender_cap::bigint * (
               select count(*) from email_mailboxes m
               where m.sending_domain_id = d.id
                 and m.connection_type = 'postshiba'
                 and m.status in ('ready', 'active', 'warming')) as capacity
      from email_sending_domains d
      join postshiba_connections c on c.id = d.postshiba_connection_id
      where c.team_id = p_team_id and c.cluster_id = p_cluster_id
        and d.infra_type = 'postshiba' and d.postshiba_volume_mode = 'auto'
    ), volumes as (
      select id,
             case when sum(capacity) over () <= v_room then capacity
                  else floor(capacity * v_room::numeric / sum(capacity) over ())
             end::integer as volume
      from capacity
    )
    update email_sending_domains d
       set postshiba_daily_volume = v.volume,
           updated_at = now()
      from volumes v
     where d.id = v.id
       and d.postshiba_daily_volume is distinct from v.volume;
  end if;

  for v_domain in
    select d.id
    from email_sending_domains d
    join postshiba_connections c on c.id = d.postshiba_connection_id
    where c.team_id = p_team_id and c.cluster_id = p_cluster_id and d.infra_type = 'postshiba'
  loop
    perform postshiba_rebalance_domain(v_domain.id);
  end loop;
end;
$$;


ALTER FUNCTION "public"."postshiba_rebalance_cluster"("p_team_id" "text", "p_cluster_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."postshiba_rebalance_domain"("p_domain_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_volume integer;
  v_count integer;
  v_base integer;
  v_extra integer;
begin
  select postshiba_daily_volume into v_volume
  from email_sending_domains
  where id = p_domain_id and infra_type = 'postshiba';
  if v_volume is null then
    return;
  end if;

  select count(*) into v_count
  from email_mailboxes
  where sending_domain_id = p_domain_id
    and connection_type = 'postshiba'
    and status in ('ready', 'active', 'warming');
  if v_count = 0 then
    return;
  end if;

  v_base := v_volume / v_count;
  v_extra := v_volume % v_count;

  with shares as (
    select id,
           v_base + case when row_number() over (order by created_at, id) <= v_extra then 1 else 0 end as share
    from email_mailboxes
    where sending_domain_id = p_domain_id
      and connection_type = 'postshiba'
      and status in ('ready', 'active', 'warming')
  )
  update email_mailboxes m
     set daily_limit = s.share,
         daily_limit_baseline = s.share,
         warmup_max_daily = s.share
    from shares s
   where m.id = s.id
     and (m.daily_limit, m.daily_limit_baseline, m.warmup_max_daily)
         is distinct from (s.share, s.share, s.share);
end;
$$;


ALTER FUNCTION "public"."postshiba_rebalance_domain"("p_domain_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."postshiba_rebalance_for_connection"("p_connection_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_team text;
  v_cluster text;
begin
  select team_id, cluster_id into v_team, v_cluster
  from postshiba_connections where id = p_connection_id;
  if v_team is not null then
    perform postshiba_rebalance_cluster(v_team, v_cluster);
  end if;
end;
$$;


ALTER FUNCTION "public"."postshiba_rebalance_for_connection"("p_connection_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."postshiba_rebalance_for_domain"("p_domain_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_connection uuid;
begin
  select postshiba_connection_id into v_connection
  from email_sending_domains where id = p_domain_id and infra_type = 'postshiba';
  if v_connection is not null then
    perform postshiba_rebalance_for_connection(v_connection);
  else
    perform postshiba_rebalance_domain(p_domain_id);
  end if;
end;
$$;


ALTER FUNCTION "public"."postshiba_rebalance_for_domain"("p_domain_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."preview_eligible_leads_count"("p_lead_list_id" "uuid", "p_exclusion_list_ids" "uuid"[], "p_exclude_other_campaigns" boolean, "p_organization_id" "uuid", "p_campaign_id" "uuid", "p_exclude_same_sender" boolean DEFAULT false, "p_sender_account_ids" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS TABLE("eligible_count" integer, "total_in_list" integer, "excluded_by_list" integer, "excluded_by_other_campaign" integer, "excluded_by_same_sender" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  IF p_lead_list_id IS NULL THEN
    RETURN QUERY SELECT 0, 0, 0, 0, 0;
    RETURN;
  END IF;

  RETURN QUERY SELECT * FROM public.preview_eligible_leads_count_multi(
    ARRAY[p_lead_list_id], p_exclusion_list_ids, p_exclude_other_campaigns,
    p_organization_id, p_campaign_id, p_exclude_same_sender, p_sender_account_ids
  );
END;
$$;


ALTER FUNCTION "public"."preview_eligible_leads_count"("p_lead_list_id" "uuid", "p_exclusion_list_ids" "uuid"[], "p_exclude_other_campaigns" boolean, "p_organization_id" "uuid", "p_campaign_id" "uuid", "p_exclude_same_sender" boolean, "p_sender_account_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."preview_eligible_leads_count_multi"("p_lead_list_ids" "uuid"[], "p_exclusion_list_ids" "uuid"[], "p_exclude_other_campaigns" boolean, "p_organization_id" "uuid", "p_campaign_id" "uuid", "p_exclude_same_sender" boolean DEFAULT false, "p_sender_account_ids" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS TABLE("eligible_count" integer, "total_in_list" integer, "excluded_by_list" integer, "excluded_by_other_campaign" integer, "excluded_by_same_sender" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_total_in_list INTEGER := 0;
  v_org_id uuid;
BEGIN
  IF p_lead_list_ids IS NULL OR cardinality(p_lead_list_ids) = 0 THEN
    RETURN QUERY SELECT 0, 0, 0, 0, 0;
    RETURN;
  END IF;

  SELECT coalesce(p_organization_id,l.organization_id) INTO v_org_id
  FROM public.lead_lists l WHERE l.id=ANY(p_lead_list_ids) LIMIT 1;
  PERFORM public.assert_smart_segment_org_access(v_org_id);
  SELECT count(*)::integer INTO v_total_in_list
  FROM public.lead_source_contacts(v_org_id,p_lead_list_ids);

  RETURN QUERY
  WITH members AS (
    SELECT s.contact_id FROM public.lead_source_contacts(v_org_id,p_lead_list_ids) s
  ),
  classified AS (
    SELECT
      CASE
        WHEN p_exclusion_list_ids IS NOT NULL
             AND array_length(p_exclusion_list_ids, 1) IS NOT NULL
             AND EXISTS (
               SELECT 1 FROM lead_list_members exc
               WHERE exc.contact_id = m.contact_id
                 AND exc.list_id = ANY(p_exclusion_list_ids)
             )
          THEN 'list'
        WHEN v_org_id IS NOT NULL
             AND public.contact_excluded_by_campaign_history(
               v_org_id, p_campaign_id, m.contact_id,
               p_exclude_other_campaigns, FALSE, NULL
             )
          THEN 'other_campaign'
        WHEN v_org_id IS NOT NULL
             AND public.contact_excluded_by_campaign_history(
               v_org_id, p_campaign_id, m.contact_id,
               FALSE, p_exclude_same_sender, p_sender_account_ids
             )
          THEN 'same_sender'
        ELSE 'eligible'
      END AS reason
    FROM members m
    JOIN crm_contacts c ON c.id = m.contact_id
  )
  SELECT
    COUNT(*) FILTER (WHERE reason = 'eligible')::INTEGER,
    v_total_in_list,
    COUNT(*) FILTER (WHERE reason = 'list')::INTEGER,
    COUNT(*) FILTER (WHERE reason = 'other_campaign')::INTEGER,
    COUNT(*) FILTER (WHERE reason = 'same_sender')::INTEGER
  FROM classified;
END;
$$;


ALTER FUNCTION "public"."preview_eligible_leads_count_multi"("p_lead_list_ids" "uuid"[], "p_exclusion_list_ids" "uuid"[], "p_exclude_other_campaigns" boolean, "p_organization_id" "uuid", "p_campaign_id" "uuid", "p_exclude_same_sender" boolean, "p_sender_account_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."preview_email_enrollment_counts"("p_org" "uuid", "p_sequence_id" "uuid", "p_ids" "uuid"[], "p_criteria_kept" "uuid"[] DEFAULT NULL::"uuid"[], "p_gate_kept" "uuid"[] DEFAULT NULL::"uuid"[], "p_content_ok" "uuid"[] DEFAULT NULL::"uuid"[], "p_requires_content" boolean DEFAULT false, "p_enforce_exclusivity" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH ids AS (SELECT DISTINCT unnest(p_ids) AS id),
  ck AS (SELECT DISTINCT unnest(p_criteria_kept) AS id),
  gk AS (SELECT DISTINCT unnest(p_gate_kept) AS id),
  co AS (SELECT DISTINCT unnest(p_content_ok) AS id),
  c AS (
    SELECT cc.id, cc.status, cc.primary_email,
      (p_criteria_kept IS NULL OR ck.id IS NOT NULL) AS crit_ok,
      (p_gate_kept IS NULL OR gk.id IS NOT NULL) AS gate_ok,
      (NOT p_requires_content OR co.id IS NOT NULL) AS content_ok
    FROM ids
    JOIN crm_contacts cc ON cc.id = ids.id AND cc.organization_id = p_org
    LEFT JOIN ck ON ck.id = cc.id
    LEFT JOIN gk ON gk.id = cc.id
    LEFT JOIN co ON co.id = cc.id
  ),
  passed AS (
    SELECT c.id FROM c
    WHERE c.crit_ok AND c.gate_ok AND c.content_ok
      AND COALESCE(c.status, '') NOT IN ('unsubscribed', 'do_not_contact', 'bounced')
      AND COALESCE(c.primary_email, '') <> ''
  ),
  pl AS (
    SELECT p.id AS contact_id,
      (SELECT l.id FROM leads l
        WHERE l.source_id = p.id AND l.organization_id = p_org AND l.source = 'crm_contact'
        ORDER BY l.id LIMIT 1) AS lead_id
    FROM passed p
  ),
  conf AS (
    SELECT pl.contact_id, e.sequence_id
    FROM pl
    JOIN email_sequence_enrollments e ON e.lead_id = pl.lead_id
    JOIN email_sequences s ON s.id = e.sequence_id
    WHERE p_enforce_exclusivity AND e.status = 'active' AND e.sequence_id <> p_sequence_id
      AND s.organization_id = p_org AND s.status = 'active'
  ),
  busy AS (SELECT DISTINCT contact_id FROM conf),
  dup AS (
    SELECT pl.contact_id FROM pl
    JOIN email_sequence_enrollments e ON e.sequence_id = p_sequence_id AND e.lead_id = pl.lead_id
    LEFT JOIN busy b ON b.contact_id = pl.contact_id
    WHERE b.contact_id IS NULL
  )
  SELECT jsonb_build_object(
    'totalContacts', (SELECT count(*) FROM c),
    'filteredOut', (SELECT count(*) FROM c WHERE NOT c.crit_ok),
    'awaitingPipeline', (SELECT count(*) FROM c WHERE c.crit_ok AND NOT c.gate_ok),
    'suppressed', (SELECT count(*) FROM c WHERE c.crit_ok AND c.gate_ok
                   AND COALESCE(c.status, '') IN ('unsubscribed', 'do_not_contact', 'bounced')),
    'noEmail', (SELECT count(*) FROM c WHERE c.crit_ok AND c.gate_ok
                AND COALESCE(c.status, '') NOT IN ('unsubscribed', 'do_not_contact', 'bounced')
                AND COALESCE(c.primary_email, '') = ''),
    'missingContent', (SELECT count(*) FROM c WHERE c.crit_ok AND c.gate_ok AND NOT c.content_ok
                       AND COALESCE(c.status, '') NOT IN ('unsubscribed', 'do_not_contact', 'bounced')
                       AND COALESCE(c.primary_email, '') <> ''),
    'passed', (SELECT count(*) FROM passed),
    'alreadyInAnotherSequence', (SELECT count(*) FROM busy),
    'duplicates', (SELECT count(*) FROM dup),
    'conflictingSequences', COALESCE((
      SELECT jsonb_agg(jsonb_build_object('id', x.sequence_id, 'name', COALESCE(s.name, 'Another sequence'), 'count', x.n)
                       ORDER BY x.n DESC, s.name)
      FROM (SELECT sequence_id, count(DISTINCT contact_id) AS n FROM conf GROUP BY sequence_id) x
      LEFT JOIN email_sequences s ON s.id = x.sequence_id
    ), '[]'::jsonb)
  );
$$;


ALTER FUNCTION "public"."preview_email_enrollment_counts"("p_org" "uuid", "p_sequence_id" "uuid", "p_ids" "uuid"[], "p_criteria_kept" "uuid"[], "p_gate_kept" "uuid"[], "p_content_ok" "uuid"[], "p_requires_content" boolean, "p_enforce_exclusivity" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."process_channel_stats_refresh_queue"("p_max" integer DEFAULT 25) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_list_id uuid;
  v_processed integer := 0;
  v_claimed uuid[];
  v_oversized uuid[];
BEGIN
  -- Prune: keep the oldest row per list (preserves FIFO by first request).
  -- Duplicates inserted concurrently are simply pruned on the next run.
  DELETE FROM public.lead_list_channel_stats_refresh_queue q
  USING public.lead_list_channel_stats_refresh_queue keep
  WHERE keep.list_id = q.list_id
    AND keep.id < q.id;

  -- Claim up to p_max small lists, oldest-first.
  WITH claimed AS (
    SELECT q.id, q.list_id
    FROM public.lead_list_channel_stats_refresh_queue q
    JOIN public.lead_lists l ON l.id = q.list_id
    WHERE COALESCE(l.lead_count, 0) <= 25000
    ORDER BY q.requested_at
    LIMIT p_max
    FOR UPDATE OF q SKIP LOCKED
  ), removed AS (
    DELETE FROM public.lead_list_channel_stats_refresh_queue q
    USING claimed c
    WHERE q.id = c.id
    RETURNING q.list_id
  )
  SELECT COALESCE(array_agg(DISTINCT list_id), '{}') INTO v_claimed FROM removed;

  -- Claim at most one oversized list per run (IO bound, see header).
  WITH claimed AS (
    SELECT q.id, q.list_id
    FROM public.lead_list_channel_stats_refresh_queue q
    JOIN public.lead_lists l ON l.id = q.list_id
    WHERE COALESCE(l.lead_count, 0) > 25000
    ORDER BY q.requested_at
    LIMIT 1
    FOR UPDATE OF q SKIP LOCKED
  ), removed AS (
    DELETE FROM public.lead_list_channel_stats_refresh_queue q
    USING claimed c
    WHERE q.id = c.id
    RETURNING q.list_id
  )
  SELECT COALESCE(array_agg(DISTINCT list_id), '{}') INTO v_oversized FROM removed;

  v_claimed := v_claimed || v_oversized;

  FOREACH v_list_id IN ARRAY v_claimed LOOP
    BEGIN
      PERFORM public.compute_lead_list_channel_stats(v_list_id);
      v_processed := v_processed + 1;
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING 'channel stats refresh failed for list %: %', v_list_id, SQLERRM;
      INSERT INTO public.lead_list_channel_stats_refresh_queue (list_id)
      VALUES (v_list_id);
    END;
  END LOOP;

  RETURN v_processed;
END;
$$;


ALTER FUNCTION "public"."process_channel_stats_refresh_queue"("p_max" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."process_inbox_keyword_sweep_queue"("p_limit" integer DEFAULT 5) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  job record;
  keyword_batch text[];
  keyword_total integer;
  batch_size integer;
  batch_conversations integer;
  batch_contacts integer;
  processed integer := 0;
  -- Production measured ~7.4 seconds per keyword on the 34k-conversation
  -- outlier. Two keeps each minute's work near 15 seconds and leaves ample I/O
  -- headroom for customer requests instead of running maintenance continuously.
  batch_limit constant integer := 2;
BEGIN
  FOR job IN
    SELECT queue.id, queue.organization_id, queue.attempts, queue.keyword_cursor
    FROM public.inbox_keyword_sweep_queue queue
    WHERE queue.finished_at IS NULL
      AND queue.next_attempt_at <= NOW()
    ORDER BY queue.requested_at
    FOR UPDATE SKIP LOCKED
    LIMIT GREATEST(COALESCE(p_limit, 5), 1)
  LOOP
    SELECT COUNT(*)::integer
    INTO keyword_total
    FROM public.inbox_keyword_exclusions exclusion
    WHERE exclusion.organization_id = job.organization_id;

    SELECT ARRAY_AGG(selected.normalized_keyword ORDER BY selected.normalized_keyword)
    INTO keyword_batch
    FROM (
      SELECT exclusion.normalized_keyword
      FROM public.inbox_keyword_exclusions exclusion
      WHERE exclusion.organization_id = job.organization_id
      ORDER BY exclusion.normalized_keyword
      OFFSET job.keyword_cursor
      LIMIT batch_limit
    ) selected;

    batch_size := COALESCE(array_length(keyword_batch, 1), 0);

    UPDATE public.inbox_keyword_sweep_queue
    SET started_at = NOW(),
        attempts = attempts + 1
    WHERE id = job.id;

    BEGIN
      IF batch_size = 0 THEN
        batch_conversations := 0;
        batch_contacts := 0;
      ELSE
        SELECT sweep.conversations_excluded, sweep.contacts_archived
        INTO batch_conversations, batch_contacts
        FROM public.mark_keyword_excluded_conversations(job.organization_id, keyword_batch) AS sweep;
      END IF;

      UPDATE public.inbox_keyword_sweep_queue
      SET started_at = NULL,
          finished_at = CASE
            WHEN job.keyword_cursor + batch_size >= keyword_total THEN NOW()
            ELSE NULL
          END,
          conversations_excluded = COALESCE(conversations_excluded, 0)
            + COALESCE(batch_conversations, 0),
          contacts_archived = COALESCE(contacts_archived, 0)
            + COALESCE(batch_contacts, 0),
          error = NULL,
          next_attempt_at = NOW(),
          keyword_cursor = job.keyword_cursor + batch_size
      WHERE id = job.id;
    EXCEPTION WHEN OTHERS THEN
      UPDATE public.inbox_keyword_sweep_queue
      SET started_at = NULL,
          error = SQLERRM,
          next_attempt_at = NOW() + make_interval(
            secs => LEAST(3600, (30 * power(2, LEAST(job.attempts, 7)))::integer)
          )
      WHERE id = job.id;
    END;

    processed := processed + 1;
  END LOOP;

  RETURN processed;
END;
$$;


ALTER FUNCTION "public"."process_inbox_keyword_sweep_queue"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."progress_warmup"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_updated INTEGER := 0;
    v_org_limit organization_channel_limits%ROWTYPE;
    v_definition channel_limit_definitions%ROWTYPE;
BEGIN
    FOR v_org_limit IN
        SELECT * FROM organization_channel_limits
        WHERE warmup_status = 'in_progress'
    LOOP
        SELECT * INTO v_definition
        FROM channel_limit_definitions
        WHERE channel = v_org_limit.channel;

        IF FOUND THEN
            UPDATE organization_channel_limits
            SET
                warmup_current_day = warmup_current_day + 1,
                warmup_progress_percent = LEAST(100, FLOOR(((warmup_current_day + 1)::DECIMAL / v_definition.warmup_duration_days) * 100)),
                warmup_status = CASE
                    WHEN warmup_current_day + 1 >= v_definition.warmup_duration_days
                    THEN 'completed'::warmup_status
                    ELSE 'in_progress'::warmup_status
                END,
                warmup_completed_at = CASE
                    WHEN warmup_current_day + 1 >= v_definition.warmup_duration_days
                    THEN now()
                    ELSE NULL
                END,
                updated_at = now()
            WHERE id = v_org_limit.id;

            v_updated := v_updated + 1;
        END IF;
    END LOOP;

    RETURN v_updated;
END;
$$;


ALTER FUNCTION "public"."progress_warmup"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prune_api_rate_limits"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_deleted INTEGER;
BEGIN
  DELETE FROM api_rate_limits WHERE window_start < now() - INTERVAL '1 hour';
  GET DIAGNOSTICS v_deleted = ROW_COUNT;
  RETURN v_deleted;
END;
$$;


ALTER FUNCTION "public"."prune_api_rate_limits"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prune_delivery_reconciliation_runs"() RETURNS "void"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  DELETE FROM public.email_delivery_reconciliation_runs
  WHERE started_at < NOW() - INTERVAL '30 days';
$$;


ALTER FUNCTION "public"."prune_delivery_reconciliation_runs"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prune_enrichment_provider_request_events"("p_retention" interval DEFAULT '24:00:00'::interval) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_deleted INTEGER;
BEGIN
  WITH doomed AS (
    SELECT id FROM public.enrichment_provider_request_events
    WHERE created_at < NOW() - p_retention
    LIMIT 50000
  )
  DELETE FROM public.enrichment_provider_request_events event
  USING doomed WHERE event.id = doomed.id;
  GET DIAGNOSTICS v_deleted = ROW_COUNT;
  RETURN v_deleted;
END;
$$;


ALTER FUNCTION "public"."prune_enrichment_provider_request_events"("p_retention" interval) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prune_lb_mx_throughput"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  WITH old AS (
    SELECT mx_host, date_trunc('day', minute_bucket) AS day_bucket,
           SUM(attempts) AS attempts, SUM(successes) AS successes, SUM(rate_limit_hits) AS rate_limit_hits
    FROM public.lb_mx_throughput WHERE minute_bucket < NOW() - INTERVAL '24 hours'
    GROUP BY mx_host, date_trunc('day', minute_bucket)
  )
  INSERT INTO public.lb_mx_throughput (mx_host, minute_bucket, attempts, successes, rate_limit_hits)
  SELECT mx_host, day_bucket, attempts, successes, rate_limit_hits FROM old
  ON CONFLICT (mx_host, minute_bucket) DO UPDATE
    SET attempts = lb_mx_throughput.attempts + EXCLUDED.attempts,
        successes = lb_mx_throughput.successes + EXCLUDED.successes,
        rate_limit_hits = lb_mx_throughput.rate_limit_hits + EXCLUDED.rate_limit_hits;
  DELETE FROM public.lb_mx_throughput WHERE minute_bucket < NOW() - INTERVAL '24 hours' AND minute_bucket <> date_trunc('day', minute_bucket);
END; $$;


ALTER FUNCTION "public"."prune_lb_mx_throughput"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prune_webhook_event_log"() RETURNS TABLE("deleted_settled" bigint, "deleted_stale_pending" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_settled bigint;
  v_stale   bigint;
BEGIN
  WITH gone AS (
    DELETE FROM webhook_event_log
    WHERE status IN ('success', 'failed')
      AND COALESCE(completed_at, created_at) < now() - interval '30 days'
    RETURNING 1
  )
  SELECT count(*) INTO v_settled FROM gone;

  WITH gone AS (
    DELETE FROM webhook_event_log
    WHERE status IN ('pending', 'sending')
      AND created_at < now() - interval '7 days'
    RETURNING 1
  )
  SELECT count(*) INTO v_stale FROM gone;

  RETURN QUERY SELECT v_settled, v_stale;
END;
$$;


ALTER FUNCTION "public"."prune_webhook_event_log"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."prune_webhook_event_log"() IS 'Retention for webhook_event_log: drops settled events after 30d and undeliverable pending events after 7d.';



CREATE OR REPLACE FUNCTION "public"."public_signal_auto_enroll_custom_candidates"("p_org" "uuid", "p_list_id" "uuid", "p_signal_types" "text"[], "p_require_email" boolean, "p_criteria" "jsonb") RETURNS TABLE("contact_id" "uuid", "subscription_id" "uuid")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
  WITH cfg AS (
    SELECT
      public.signal_filter_int(p_criteria, 'max_per_company', NULL) AS max_per_company,
      NULLIF(public.signal_filter_int(p_criteria, 'recency_days', NULL), 0) AS window_days,
      public.signal_has_company_gate(p_criteria) AS has_company_gate
  ), matched AS (
    SELECT c.id AS m_contact_id, ps.id AS m_subscription_id,
           row_number() OVER (
             PARTITION BY COALESCE(c.company_id::text, 'contact:' || c.id::text)
             ORDER BY public.signal_seniority_rank(c.job_title) DESC, c.created_at, c.id
           ) AS person_rank
    FROM public.crm_contacts c
    JOIN public.pack_subscriptions ps
      ON ps.id::text = c.discovery_metadata->>'signal_subscription_id'
    CROSS JOIN cfg
    WHERE c.organization_id = p_org
      AND ps.organization_id = p_org
      -- Deliberately no ps.deleted_at filter — see
      -- 20260807150000_auto_enroll_include_deleted_signals.sql.
      AND (
        p_signal_types IS NULL
        OR cardinality(p_signal_types) = 0
        OR COALESCE(c.discovery_metadata->>'signal_type', ps.pack_key) = ANY(p_signal_types)
      )
      AND (NOT COALESCE(p_require_email, false) OR NULLIF(c.primary_email, '') IS NOT NULL)
      AND (cfg.window_days IS NULL OR c.created_at >= now() - make_interval(days => cfg.window_days))
      AND public.signal_lead_passes_filter(
            p_criteria, c.job_title, public.signal_seniority_rank(c.job_title), c.country
          )
      -- Firmographics live on the discovered-company row the pack module wrote,
      -- reached by normalized domain within the same org. The contact's own
      -- website column is filled for 316 of 330 prod signal leads; the two
      -- enrichment fallbacks recover most of the rest.
      AND (
        NOT cfg.has_company_gate
        OR EXISTS (
          SELECT 1
          FROM public.lb_discovered_companies dc
          WHERE dc.organization_id = p_org
            AND NULLIF(lower(regexp_replace(btrim(COALESCE(dc.domain, '')),
                  '^(https?://)?(www\.)?([^/]+).*$', '\3')), '') =
                NULLIF(lower(regexp_replace(btrim(COALESCE(
                  NULLIF(c.company_website, ''),
                  c.enrichment_data->>'website',
                  c.discovery_metadata->>'ai_signal_company_website',
                  '')), '^(https?://)?(www\.)?([^/]+).*$', '\3')), '')
            AND public.signal_company_passes_filter(
                  p_criteria, dc.employee_count_estimate, dc.employee_signal, dc.revenue_range)
        )
      )
  )
  SELECT m.m_contact_id, m.m_subscription_id
  FROM matched m, cfg
  WHERE (cfg.max_per_company IS NULL OR m.person_rank <= cfg.max_per_company)
    AND (
      p_list_id IS NULL
      OR NOT EXISTS (
        SELECT 1 FROM public.lead_list_members lm
        WHERE lm.list_id = p_list_id AND lm.contact_id = m.m_contact_id
      )
    );
$_$;


ALTER FUNCTION "public"."public_signal_auto_enroll_custom_candidates"("p_org" "uuid", "p_list_id" "uuid", "p_signal_types" "text"[], "p_require_email" boolean, "p_criteria" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."public_signal_auto_enroll_preview"("p_org" "uuid", "p_source" "text" DEFAULT 'public'::"text", "p_signal_types" "text"[] DEFAULT NULL::"text"[], "p_require_email" boolean DEFAULT false, "p_criteria" "jsonb" DEFAULT '{}'::"jsonb", "p_list_id" "uuid" DEFAULT NULL::"uuid", "p_lookback_days" integer DEFAULT 30) RETURNS integer
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_total integer := 0;
  v_branch integer;
BEGIN
  IF current_user NOT IN ('service_role', 'postgres')
     AND NOT EXISTS (
       SELECT 1 FROM public.organization_members om
       WHERE om.organization_id = p_org AND om.user_id = auth.uid()
     ) THEN
    RAISE EXCEPTION 'Not a member of this organization';
  END IF;

  IF p_list_id IS NOT NULL AND NOT EXISTS (
       SELECT 1 FROM public.lead_lists l WHERE l.id = p_list_id AND l.organization_id = p_org
     ) THEN
    RAISE EXCEPTION 'List does not belong to this organization';
  END IF;

  IF COALESCE(p_source, 'public') IN ('public', 'all') THEN
    SELECT count(*) INTO v_branch
    FROM public.public_signal_auto_enroll_public_candidates(
      p_org, p_list_id, p_signal_types, p_require_email,
      COALESCE(p_criteria, '{}'::jsonb), p_lookback_days
    );
    v_total := v_total + COALESCE(v_branch, 0);
  END IF;

  IF COALESCE(p_source, 'public') IN ('custom', 'all') THEN
    SELECT count(*) INTO v_branch
    FROM public.public_signal_auto_enroll_custom_candidates(
      p_org, p_list_id, p_signal_types, p_require_email, COALESCE(p_criteria, '{}'::jsonb)
    );
    v_total := v_total + COALESCE(v_branch, 0);
  END IF;

  RETURN v_total;
END;
$$;


ALTER FUNCTION "public"."public_signal_auto_enroll_preview"("p_org" "uuid", "p_source" "text", "p_signal_types" "text"[], "p_require_email" boolean, "p_criteria" "jsonb", "p_list_id" "uuid", "p_lookback_days" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."public_signal_auto_enroll_preview"("p_org" "uuid", "p_source" "text", "p_signal_types" "text"[], "p_require_email" boolean, "p_criteria" "jsonb", "p_list_id" "uuid", "p_lookback_days" integer) IS 'Counts the leads an auto-enroll rule would add right now, using the same candidate cores as the sweep. Org-membership checked; p_list_id NULL skips the already-a-member exclusion.';



CREATE OR REPLACE FUNCTION "public"."public_signal_auto_enroll_public_candidates"("p_org" "uuid", "p_list_id" "uuid", "p_signal_types" "text"[], "p_require_email" boolean, "p_criteria" "jsonb", "p_lookback_days" integer) RETURNS TABLE("signal_id" "uuid", "company_name" "text", "domain" "text", "company_linkedin_url" "text", "signal_type" "text", "source_url" "text", "company_key" "text", "person_id" "uuid", "full_name" "text", "person_title" "text", "linkedin_url" "text", "email" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
  WITH cfg AS (
    SELECT
      COALESCE(
        NULLIF(public.signal_filter_int(p_criteria, 'recency_days', NULL), 0),
        NULLIF(p_lookback_days, 0),
        30
      ) AS window_days,
      GREATEST(LEAST(public.signal_filter_int(p_criteria, 'max_per_company', 5), 25), 1) AS max_per_company,
      COALESCE((p_criteria ->> 'skip_known_companies') = 'true', false) AS skip_known
  ), sigs AS (
    SELECT s.id, s.company_name, s.domain, s.company_linkedin_url,
           s.signal_type, s.source_url, s.country, s.created_at,
           lower(s.company_name) AS company_key
    FROM public.public_signals s, cfg
    WHERE s.published
      AND COALESCE(s.domain, '') <> ''
      AND s.created_at >= now() - make_interval(days => cfg.window_days)
      AND (
        p_signal_types IS NULL
        OR cardinality(p_signal_types) = 0
        OR s.signal_type = ANY(p_signal_types)
      )
      AND (
        NOT cfg.skip_known
        OR NOT EXISTS (
          SELECT 1 FROM public.crm_companies cc
          WHERE cc.organization_id = p_org
            AND cc.normalized_domain =
                lower(regexp_replace(btrim(s.domain), '^(https?://)?(www\.)?([^/]+).*$', '\3'))
        )
      )
  ), company_sigs AS (
    SELECT DISTINCT ON (sg.company_key) sg.*
    FROM sigs sg
    ORDER BY sg.company_key, sg.created_at DESC, sg.id
  ), eligible AS (
    SELECT sg.id AS e_signal_id, sg.company_name AS e_company_name, sg.domain AS e_domain,
           sg.company_linkedin_url AS e_company_linkedin_url, sg.signal_type AS e_signal_type,
           sg.source_url AS e_source_url, sg.company_key AS e_company_key,
           p.id AS e_person_id, p.full_name AS e_full_name, p.title AS e_person_title,
           p.linkedin_url AS e_linkedin_url, p.email AS e_email,
           row_number() OVER (
             PARTITION BY sg.company_key
             ORDER BY GREATEST(COALESCE(p.seniority_rank, 0), public.signal_seniority_rank(p.title)) DESC,
                      p.enriched_at DESC, p.id
           ) AS person_rank
    FROM company_sigs sg
    JOIN public.public_signal_people p ON lower(p.company_key) = sg.company_key
    WHERE p.linkedin_url ~* E'^https://([a-z]{2,3}\\.)?linkedin\\.com/in/[^/?#]+/?$'
      AND p.title ~* E'\\m(founder|co-founder|owner|ceo|cto|cmo|cfo|coo|cro|cio|chro|chief|president|managing|partner|vp|vice president|head of|director)\\M'
      AND NOT EXISTS (
        SELECT 1 FROM public.public_signal_people_takedowns td
        WHERE (td.scope = 'company' AND lower(td.company_key) = sg.company_key)
           OR (td.scope = 'person' AND td.linkedin_url = p.linkedin_url)
      )
      AND (
        NOT COALESCE(p_require_email, false)
        OR (
          NULLIF(btrim(COALESCE(p.email, '')), '') IS NOT NULL
          AND lower(COALESCE(p.email_status, '')) IN ('valid', 'verified')
          AND NOT EXISTS (
            SELECT 1
            FROM public.crm_contacts existing
            WHERE existing.organization_id = p_org
              AND lower(existing.primary_email) = lower(p.email)
              AND existing.primary_linkedin_url IS DISTINCT FROM p.linkedin_url
          )
          AND NOT EXISTS (
            SELECT 1
            FROM public.crm_contacts existing_identity
            WHERE existing_identity.organization_id = p_org
              AND existing_identity.primary_linkedin_url = p.linkedin_url
              AND (
                NULLIF(btrim(COALESCE(existing_identity.primary_email, '')), '') IS NULL
                OR lower(COALESCE(existing_identity.email_verification_status, '')) <> 'valid'
              )
          )
        )
      )
      AND public.signal_lead_passes_filter(
            p_criteria,
            p.title,
            GREATEST(COALESCE(p.seniority_rank, 0), public.signal_seniority_rank(p.title)),
            sg.country
          )
  ), capped AS (
    SELECT e.* FROM eligible e, cfg WHERE e.person_rank <= cfg.max_per_company
  )
  SELECT DISTINCT ON (c2.e_linkedin_url)
         c2.e_signal_id, c2.e_company_name, c2.e_domain, c2.e_company_linkedin_url,
         c2.e_signal_type, c2.e_source_url, c2.e_company_key,
         c2.e_person_id, c2.e_full_name, c2.e_person_title, c2.e_linkedin_url, c2.e_email
  FROM capped c2
  WHERE (
      p_list_id IS NULL
      OR NOT EXISTS (
        SELECT 1
        FROM public.crm_contacts c
        JOIN public.lead_list_members m ON m.contact_id = c.id AND m.list_id = p_list_id
        WHERE c.organization_id = p_org
          AND c.primary_linkedin_url = c2.e_linkedin_url
      )
    )
  ORDER BY c2.e_linkedin_url, c2.person_rank;
$_$;


