CREATE OR REPLACE FUNCTION "public"."purge_email_enrollment_job_members"("p_job_id" "uuid", "p_limit" integer DEFAULT 25000) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_n INTEGER;
BEGIN
  DELETE FROM public.email_enrollment_job_members
  WHERE job_id = p_job_id
    AND contact_id IN (
      SELECT contact_id FROM public.email_enrollment_job_members
      WHERE job_id = p_job_id
      ORDER BY contact_id
      LIMIT p_limit
    );
  GET DIAGNOSTICS v_n = ROW_COUNT;
  RETURN v_n;
END;
$$;


