CREATE OR REPLACE FUNCTION "public"."queue_contact_enrichment"("p_contact_id" "uuid", "p_enrichment_types" "text" DEFAULT 'email,phone'::"text", "p_priority" integer DEFAULT 5, "p_source" "text" DEFAULT 'manual'::"text") RETURNS "uuid"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_org_id UUID;
  v_job_id UUID;
BEGIN
  -- Get organization ID from contact
  SELECT organization_id INTO v_org_id
  FROM public.crm_contacts
  WHERE id = p_contact_id;

  IF v_org_id IS NULL THEN
    RAISE EXCEPTION 'Contact not found: %', p_contact_id;
  END IF;

  -- Check if there's already a pending job for this contact
  SELECT id INTO v_job_id
  FROM public.enrichment_jobs
  WHERE contact_id = p_contact_id
    AND status = 'pending'
    AND enrichment_type = p_enrichment_types;

  IF v_job_id IS NOT NULL THEN
    -- Return existing job
    RETURN v_job_id;
  END IF;

  -- Create new job
  INSERT INTO public.enrichment_jobs (
    organization_id,
    contact_id,
    enrichment_type,
    priority,
    source
  ) VALUES (
    v_org_id,
    p_contact_id,
    p_enrichment_types,
    p_priority,
    p_source
  )
  RETURNING id INTO v_job_id;

  RETURN v_job_id;
END;
$$;


ALTER FUNCTION "public"."queue_contact_enrichment"("p_contact_id" "uuid", "p_enrichment_types" "text", "p_priority" integer, "p_source" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."queue_list_enrichment"("p_list_id" "uuid", "p_enrichment_types" "text" DEFAULT 'email,phone'::"text", "p_priority" integer DEFAULT 5, "p_only_missing" boolean DEFAULT true) RETURNS integer
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_count INTEGER := 0;
  v_org_id UUID;
BEGIN
  -- Get organization ID from list
  SELECT organization_id INTO v_org_id
  FROM public.lead_lists
  WHERE id = p_list_id;

  IF v_org_id IS NULL THEN
    RAISE EXCEPTION 'List not found: %', p_list_id;
  END IF;

  -- Queue enrichment for each contact in list
  IF p_only_missing THEN
    -- Only queue contacts missing email or phone
    INSERT INTO public.enrichment_jobs (
      organization_id,
      contact_id,
      enrichment_type,
      priority,
      source
    )
    SELECT
      v_org_id,
      c.id,
      p_enrichment_types,
      p_priority,
      'bulk'
    FROM public.lead_list_members llm
    JOIN public.crm_contacts c ON c.id = llm.contact_id
    WHERE llm.list_id = p_list_id
      AND (c.primary_email IS NULL OR c.primary_phone IS NULL)
      AND NOT EXISTS (
        SELECT 1 FROM public.enrichment_jobs ej
        WHERE ej.contact_id = c.id
          AND ej.status = 'pending'
          AND ej.enrichment_type = p_enrichment_types
      );
  ELSE
    -- Queue all contacts
    INSERT INTO public.enrichment_jobs (
      organization_id,
      contact_id,
      enrichment_type,
      priority,
      source
    )
    SELECT
      v_org_id,
      c.id,
      p_enrichment_types,
      p_priority,
      'bulk'
    FROM public.lead_list_members llm
    JOIN public.crm_contacts c ON c.id = llm.contact_id
    WHERE llm.list_id = p_list_id
      AND NOT EXISTS (
        SELECT 1 FROM public.enrichment_jobs ej
        WHERE ej.contact_id = c.id
          AND ej.status = 'pending'
          AND ej.enrichment_type = p_enrichment_types
      );
  END IF;

  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$$;


ALTER FUNCTION "public"."queue_list_enrichment"("p_list_id" "uuid", "p_enrichment_types" "text", "p_priority" integer, "p_only_missing" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."queue_webhook_event"("p_organization_id" "uuid", "p_event_type" "text", "p_event_data" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_settings organization_webhook_settings;
  v_webhook_url TEXT;
  v_event_id UUID;
  v_first_id UUID;
  v_sub RECORD;
BEGIN
  SELECT * INTO v_settings
    FROM organization_webhook_settings
   WHERE organization_id = p_organization_id
     AND is_active = true;

  IF v_settings.id IS NOT NULL AND p_event_type = ANY(v_settings.enabled_events) THEN
    v_webhook_url := COALESCE(
      v_settings.event_webhooks->>p_event_type,
      v_settings.default_webhook_url
    );

    IF v_webhook_url IS NOT NULL AND v_webhook_url <> '' THEN
      INSERT INTO webhook_event_log (
        organization_id, event_type, event_data, webhook_url, max_attempts
      )
      VALUES (
        p_organization_id, p_event_type, p_event_data, v_webhook_url,
        COALESCE(v_settings.max_retries, 3)
      )
      RETURNING id INTO v_first_id;
    END IF;
  END IF;

  FOR v_sub IN
    SELECT id, target_url, max_attempts
      FROM webhook_subscriptions
     WHERE organization_id = p_organization_id
       AND is_active = true
       AND p_event_type = ANY(events)
       AND webhook_subscription_matches(filters, p_event_type, p_event_data)
  LOOP
    INSERT INTO webhook_event_log (
      organization_id, event_type, event_data, webhook_url, max_attempts, subscription_id
    )
    VALUES (
      p_organization_id, p_event_type, p_event_data, v_sub.target_url,
      COALESCE(v_sub.max_attempts, 3), v_sub.id
    )
    RETURNING id INTO v_event_id;

    v_first_id := COALESCE(v_first_id, v_event_id);
  END LOOP;

  IF v_first_id IS NOT NULL THEN
    PERFORM kick_webhook_dispatcher();
  END IF;

  RETURN v_first_id;
END;
$$;


ALTER FUNCTION "public"."queue_webhook_event"("p_organization_id" "uuid", "p_event_type" "text", "p_event_data" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reap_lead_list_sources"("p_stale_lock_minutes" integer DEFAULT 15) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_unlocked int := 0;
  v_expired int := 0;
BEGIN
  WITH unlocked AS (
    UPDATE public.lead_list_sources
    SET state = state - 'poller_lock_at'
    WHERE state->>'poller_lock_at' IS NOT NULL
      AND (state->>'poller_lock_at')::timestamptz < now() - make_interval(mins => p_stale_lock_minutes)
    RETURNING id
  )
  SELECT count(*) INTO v_unlocked FROM unlocked;

  WITH expired AS (
    UPDATE public.lead_list_sources
    SET status = 'expired'
    WHERE status IN ('active', 'paused')
      AND expires_at IS NOT NULL
      AND expires_at < now()
    RETURNING id
  )
  SELECT count(*) INTO v_expired FROM expired;

  RETURN jsonb_build_object('unlocked', v_unlocked, 'expired', v_expired, 'ran_at', now());
END;
$$;


ALTER FUNCTION "public"."reap_lead_list_sources"("p_stale_lock_minutes" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reap_orphaned_sending_emails"("p_grace_minutes" integer DEFAULT 10, "p_batch_limit" integer DEFAULT 10000) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_count integer;
begin
  with batch as (
    select id
    from email_send_log
    where status = 'sending'
      and created_at < now() - make_interval(mins => p_grace_minutes)
    order by created_at
    limit p_batch_limit
    for update skip locked
  )
  update email_send_log e
  set status = 'failed',
      error_message = 'reaped: orphaned in sending state (never finalized)',
      error_category = 'network_error'
  from batch
  where e.id = batch.id;
  get diagnostics v_count = row_count;
  return v_count;
end;
$$;


ALTER FUNCTION "public"."reap_orphaned_sending_emails"("p_grace_minutes" integer, "p_batch_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reap_stranded_email_verifications"() RETURNS TABLE("org_id" "uuid", "enqueued" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  r         record;
  v_plan    text;
  v_cap     integer;
  v_used    integer;
  v_headroom integer;
  v_emails  text[];
BEGIN
  FOR r IN
    SELECT v.organization_id AS oid
    FROM public.email_address_verifications v
    WHERE v.provider = 'mailtester_ninja'
      AND v.status = 'unknown'
      AND v.raw_response->>'reason' = 'timeout'
      AND COALESCE((v.raw_response->>'reverify_attempts')::int, 0) < 3
      AND v.verified_at >= now() - interval '90 days'
      AND v.verified_at <  now() - interval '30 minutes'
    GROUP BY v.organization_id
  LOOP
    IF EXISTS (
      SELECT 1 FROM public.mailtester_verification_jobs
      WHERE organization_id = r.oid AND status IN ('queued','running')
    ) THEN
      CONTINUE;
    END IF;

    IF NOT EXISTS (
      SELECT 1 FROM public.api_keys
      WHERE organization_id = r.oid AND provider = 'mailtester_ninja' AND is_valid
    ) THEN
      CONTINUE;
    END IF;

    v_plan := COALESCE(
      (SELECT metadata->>'plan' FROM public.api_keys
       WHERE organization_id = r.oid AND provider = 'mailtester_ninja' LIMIT 1), 'pro');
    IF v_plan NOT IN ('starter','pro','ultimate') THEN v_plan := 'pro'; END IF;
    v_cap := CASE v_plan WHEN 'starter' THEN 50000 WHEN 'ultimate' THEN 500000 ELSE 100000 END;

    SELECT count(*) INTO v_used
    FROM public.email_address_verifications
    WHERE organization_id = r.oid AND provider = 'mailtester_ninja'
      AND verified_at >= date_trunc('day', now())
      AND raw_response->>'reason' IS DISTINCT FROM 'timeout';
    v_headroom := GREATEST(0, v_cap - v_used);
    IF v_headroom = 0 THEN CONTINUE; END IF;

    SELECT array_agg(email) INTO v_emails
    FROM (
      SELECT v.email
      FROM public.email_address_verifications v
      WHERE v.organization_id = r.oid AND v.provider = 'mailtester_ninja'
        AND v.status = 'unknown'
        AND v.raw_response->>'reason' = 'timeout'
        AND COALESCE((v.raw_response->>'reverify_attempts')::int, 0) < 3
        AND v.verified_at >= now() - interval '90 days'
        AND v.verified_at <  now() - interval '30 minutes'
      ORDER BY v.verified_at DESC
      LIMIT v_headroom
    ) s;

    IF v_emails IS NULL OR array_length(v_emails, 1) IS NULL THEN CONTINUE; END IF;

    INSERT INTO public.mailtester_verification_jobs (organization_id, plan, pending_emails, total)
    VALUES (r.oid, v_plan, v_emails, array_length(v_emails, 1));

    UPDATE public.email_address_verifications
       SET raw_response = jsonb_set(
             COALESCE(raw_response, '{}'::jsonb),
             '{reverify_attempts}',
             to_jsonb(COALESCE((raw_response->>'reverify_attempts')::int, 0) + 1))
     WHERE organization_id = r.oid AND email = ANY(v_emails);

    org_id := r.oid;
    enqueued := array_length(v_emails, 1);
    RETURN NEXT;
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."reap_stranded_email_verifications"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reap_stuck_autopilot_pool_entries"("p_stuck_minutes" integer DEFAULT 60, "p_max_attempts" integer DEFAULT 5) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_produced integer := 0;
  v_released integer := 0;
  v_parked   integer := 0;
begin
  with fixed as (
    update public.autopilot_idea_pools p
    set status      = 'produced',
        produced_at = coalesce(p.produced_at, now()),
        can_recycle = true,
        updated_at  = now()
    from public.content_generation_jobs j
    where p.job_id = j.id
      and p.status = 'in_progress'
      and j.status = 'completed'
    returning 1
  )
  select count(*) into v_produced from fixed;

  with released as (
    update public.autopilot_idea_pools p
    set status        = 'available',
        error_message = null,
        updated_at    = now()
    from (
      select p2.id
      from public.autopilot_idea_pools p2
      left join public.content_generation_jobs j on j.id = p2.job_id
      where p2.status = 'in_progress'
        and coalesce(p2.attempt_count, 0) < p_max_attempts
        and (
          j.id is null
          or j.status = 'failed'
          or (j.status in ('processing', 'queued')
              and j.created_at < now() - make_interval(mins => p_stuck_minutes))
        )
    ) d
    where p.id = d.id
    returning 1
  )
  select count(*) into v_released from released;

  with parked as (
    update public.autopilot_idea_pools p
    set status        = 'failed',
        can_recycle   = false,
        error_message = 'Reaped: backing job dead after ' || coalesce(p.attempt_count, 0) || ' attempts',
        updated_at    = now()
    from (
      select p2.id
      from public.autopilot_idea_pools p2
      left join public.content_generation_jobs j on j.id = p2.job_id
      where p2.status = 'in_progress'
        and coalesce(p2.attempt_count, 0) >= p_max_attempts
        and (
          j.id is null
          or j.status = 'failed'
          or (j.status in ('processing', 'queued')
              and j.created_at < now() - make_interval(mins => p_stuck_minutes))
        )
    ) d
    where p.id = d.id
    returning 1
  )
  select count(*) into v_parked from parked;

  return jsonb_build_object(
    'produced', v_produced,
    'released', v_released,
    'parked',   v_parked,
    'ran_at',   now()
  );
end;
$$;


ALTER FUNCTION "public"."reap_stuck_autopilot_pool_entries"("p_stuck_minutes" integer, "p_max_attempts" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."reap_stuck_autopilot_pool_entries"("p_stuck_minutes" integer, "p_max_attempts" integer) IS 'Releases autopilot_idea_pools entries stranded in in_progress by dead/stuck generation jobs so the idea pool does not permanently starve. Scheduled via pg_cron (reap-stuck-autopilot-pool).';



