CREATE OR REPLACE FUNCTION "public"."reclaim_stuck_webhook_events"("p_older_than" interval DEFAULT '00:05:00'::interval) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_count integer;
BEGIN
  WITH back AS (
    UPDATE webhook_event_log
       SET status        = 'pending',
           next_retry_at = NULL
     WHERE status = 'sending'
       AND sent_at < now() - p_older_than
    RETURNING 1
  )
  SELECT count(*) INTO v_count FROM back;

  RETURN v_count;
END;
$$;


