CREATE OR REPLACE FUNCTION "public"."recompute_warmup_day"("p_mailbox_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  UPDATE public.email_mailboxes m
  SET
    warmup_day = COALESCE(agg.delivered_days, 0),
    warmup_sends_total = COALESCE(agg.sends, 0),
    warmup_delivered_total = COALESCE(agg.delivered, 0),
    warmup_last_send_at = agg.last_send_at
  FROM (
    SELECT
      count(DISTINCT (sent_at AT TIME ZONE 'UTC')::date)
        FILTER (WHERE status = 'delivered')            AS delivered_days,
      count(*) FILTER (WHERE status <> 'failed')       AS sends,
      count(*) FILTER (WHERE status = 'delivered')     AS delivered,
      -- Only sends that actually left the mailbox count as activity. A failed
      -- row must never make a broken mailbox look alive to the stall alert.
      max(sent_at) FILTER (WHERE status <> 'failed')   AS last_send_at
    FROM public.email_warmup_sends
    WHERE from_mailbox_id = p_mailbox_id
  ) agg
  WHERE m.id = p_mailbox_id;
END;
$$;


ALTER FUNCTION "public"."recompute_warmup_day"("p_mailbox_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."recompute_warmup_day"("p_mailbox_id" "uuid") IS 'Recomputes a mailbox''s warmup_day from the email_warmup_sends ledger. Full recompute rather than an increment so it is self-healing and idempotent.';



CREATE OR REPLACE FUNCTION "public"."record_limit_hit"("p_org_id" "uuid", "p_limit_type" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_current_hits JSONB;
  v_current_month TEXT;
  v_tracking_month TEXT;
BEGIN
  v_current_month := to_char(CURRENT_DATE, 'YYYY-MM');

  -- Get current tracking data
  SELECT COALESCE(limit_hits, '{}'::jsonb)
  INTO v_current_hits
  FROM organizations
  WHERE id = p_org_id;

  -- Check if we need to reset monthly counters
  v_tracking_month := v_current_hits->>'month';
  IF v_tracking_month IS NULL OR v_tracking_month != v_current_month THEN
    v_current_hits := jsonb_build_object(
      'daily_hits', 0,
      'monthly_hits', COALESCE((v_current_hits->>'monthly_hits')::int, 0),
      'total_hits', COALESCE((v_current_hits->>'total_hits')::int, 0),
      'month', v_current_month
    );
  END IF;

  -- Increment appropriate counter
  IF p_limit_type = 'daily' THEN
    v_current_hits := v_current_hits || jsonb_build_object(
      'daily_hits', COALESCE((v_current_hits->>'daily_hits')::int, 0) + 1,
      'last_daily_hit', NOW(),
      'total_hits', COALESCE((v_current_hits->>'total_hits')::int, 0) + 1
    );
  ELSIF p_limit_type = 'monthly' THEN
    v_current_hits := v_current_hits || jsonb_build_object(
      'monthly_hits', COALESCE((v_current_hits->>'monthly_hits')::int, 0) + 1,
      'last_monthly_hit', NOW(),
      'total_hits', COALESCE((v_current_hits->>'total_hits')::int, 0) + 1
    );
  END IF;

  -- Update the organization
  UPDATE organizations
  SET limit_hits = v_current_hits
  WHERE id = p_org_id;
END;
$$;


ALTER FUNCTION "public"."record_limit_hit"("p_org_id" "uuid", "p_limit_type" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_warmup_scheduler_day"("p_rows" "jsonb") RETURNS "void"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  INSERT INTO public.warmup_scheduler_daily(day, mailbox_id, organization_id, last_reason, had_opportunity)
  SELECT (now() AT TIME ZONE 'UTC')::date, m.id, m.organization_id,
         r.reason, COALESCE(r.had_opportunity, false)
  FROM jsonb_to_recordset(p_rows) AS r(mailbox_id uuid, reason text, had_opportunity boolean)
  JOIN public.email_mailboxes m ON m.id = r.mailbox_id
  ON CONFLICT (day, mailbox_id) DO UPDATE SET
    last_seen_at = now(), last_reason = EXCLUDED.last_reason,
    had_opportunity = warmup_scheduler_daily.had_opportunity OR EXCLUDED.had_opportunity;
$$;


ALTER FUNCTION "public"."record_warmup_scheduler_day"("p_rows" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."recover_stale_lb_work_items"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_recovered INTEGER;
BEGIN
  WITH reset AS (
    UPDATE public.lb_work_items
       SET status = 'pending',
           claimed_at = NULL,
           claimed_by = NULL,
           updated_at = NOW()
     WHERE status = 'claimed'
       AND claimed_at < NOW() - INTERVAL '10 minutes'
     RETURNING 1
  )
  SELECT count(*)::INTEGER INTO v_recovered FROM reset;
  RETURN COALESCE(v_recovered, 0);
END;
$$;


