CREATE OR REPLACE FUNCTION "public"."recover_stuck_dm_signals"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_enqueued INTEGER := 0;
BEGIN
  WITH stuck AS (
    SELECT DISTINCT
      sal.discovered_company_id,
      sal.organization_id,
      dc.id AS company_id,
      dc.job_id,
      dc.company_name,
      dc.domain,
      dc.website_url,
      dc.linkedin_url
    FROM public.signal_activity_log sal
    JOIN public.lb_discovered_companies dc ON dc.id = sal.discovered_company_id
    WHERE sal.outcome = 'enrolled'
      AND sal.created_at < NOW() - INTERVAL '30 minutes'
      AND (dc.linkedin_url IS NOT NULL OR dc.domain IS NOT NULL OR dc.website_url IS NOT NULL)
      AND dc.dm_dead = FALSE
      AND dc.dm_attempt_count < 3
      AND NOT EXISTS (
        SELECT 1 FROM public.lb_decision_makers dm
        WHERE dm.company_id = dc.id
      )
      AND NOT EXISTS (
        SELECT 1 FROM public.lb_work_items wi
        WHERE wi.stage = 'dm'
          AND wi.status IN ('pending', 'claimed')
          AND (wi.payload->>'company_id') = dc.id::TEXT
      )
      AND NOT EXISTS (
        SELECT 1 FROM public.lb_work_items wi
        WHERE wi.stage = 'dm'
          AND (wi.payload->>'company_id') = dc.id::TEXT
          AND wi.created_at > NOW() - INTERVAL '7 days'
      )
    LIMIT 100
  ), inserted AS (
    INSERT INTO public.lb_work_items (job_id, organization_id, stage, status, payload, priority)
    SELECT
      job_id,
      organization_id,
      'dm',
      'pending',
      jsonb_build_object(
        'company_id',    company_id,
        'company_name',  company_name,
        'domain',        domain,
        'website_url',   website_url,
        'linkedin_url',  linkedin_url
      ),
      7
    FROM stuck
    RETURNING 1
  )
  SELECT count(*)::INTEGER INTO v_enqueued FROM inserted;
  RETURN COALESCE(v_enqueued, 0);
END;
$$;


ALTER FUNCTION "public"."recover_stuck_dm_signals"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."recover_stuck_dm_signals"() IS 'Re-enqueues stage=dm work items for enrolled companies with no DMs. Skips: dm_dead companies, companies that have already burned >=3 attempts, companies with any pending/claimed dm item, and companies with any dm work item in the last 7d.';



CREATE OR REPLACE FUNCTION "public"."recover_stuck_generations"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  stuck_output RECORD;
  recovered_count INT := 0;
  recovered_ideas INT := 0;
  failed_empty_jobs INT := 0;
BEGIN
  FOR stuck_output IN
    SELECT co.id, co.job_id, co.current_stage, co.stage_data, co.updated_at, co.status, co.error_message
    FROM content_outputs co
    WHERE (
        (co.status = 'generating' AND co.updated_at < now() - interval '30 minutes')
        OR (co.status = 'review' AND co.error_message IS NOT NULL AND co.updated_at < now() - interval '30 minutes')
      )
    LIMIT 20
  LOOP
    UPDATE content_outputs
    SET status = 'failed',
        error_message = CASE
          WHEN stuck_output.status = 'review' AND stuck_output.error_message IS NOT NULL
            THEN stuck_output.error_message
          ELSE format(
            'Generation timed out: stage "%s" has been stuck since %s (over 30 minutes). This was likely caused by a transient API error. Please retry.',
            stuck_output.current_stage,
            stuck_output.updated_at
          )
        END,
        stage_data = jsonb_set(
          COALESCE(stuck_output.stage_data, '{}'::jsonb),
          ARRAY[COALESCE(stuck_output.current_stage, 'unknown')],
          COALESCE(
            stuck_output.stage_data->COALESCE(stuck_output.current_stage, 'unknown'),
            '{}'::jsonb
          ) || jsonb_build_object(
            'status', 'failed',
            'error', COALESCE(stuck_output.error_message, 'Generation timed out after 30 minutes'),
            'failed_at', now()::text
          )
        ),
        updated_at = now()
    WHERE id = stuck_output.id;

    IF stuck_output.job_id IS NOT NULL THEN
      PERFORM sync_job_progress(stuck_output.job_id);
    END IF;

    recovered_count := recovered_count + 1;
    RAISE LOG '[stuck-generation-recovery] Recovered output % (status: %, stage: %, stuck since: %)',
      stuck_output.id, stuck_output.status, stuck_output.current_stage, stuck_output.updated_at;
  END LOOP;

  IF recovered_count > 0 THEN
    RAISE LOG '[stuck-generation-recovery] Recovered % stuck outputs', recovered_count;
  END IF;

  WITH empty_jobs AS (
    UPDATE content_generation_jobs j
    SET status = 'failed',
        error = COALESCE(j.error, 'This run stopped before it made anything. Run it again.'),
        completed_at = COALESCE(j.completed_at, now())
    WHERE j.status IN ('queued', 'processing')
      AND j.created_at < now() - interval '1 hour'
      AND NOT EXISTS (SELECT 1 FROM content_outputs o WHERE o.job_id = j.id)
    RETURNING 1
  )
  SELECT count(*) INTO failed_empty_jobs FROM empty_jobs;

  IF failed_empty_jobs > 0 THEN
    RAISE LOG '[stuck-generation-recovery] Failed % runs that never created an output', failed_empty_jobs;
  END IF;

  WITH reaped AS (
    UPDATE content_ideas
    SET generation_in_progress = false,
        metadata = COALESCE(metadata, '{}'::jsonb) || jsonb_build_object(
          'generation_timed_out_at', now()::text,
          'generation_timeout_reason',
            'Idea generation never completed (client stream did not finish the write-back). Auto-cleared after 15 minutes. Re-run generation to retry.'
        ),
        updated_at = now()
    WHERE generation_in_progress = true
      AND updated_at < now() - interval '15 minutes'
    RETURNING 1
  )
  SELECT count(*) INTO recovered_ideas FROM reaped;

  IF recovered_ideas > 0 THEN
    RAISE LOG '[stuck-generation-recovery] Cleared % stuck content_ideas generation flags', recovered_ideas;
  END IF;
END;
$$;


ALTER FUNCTION "public"."recover_stuck_generations"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."recover_stuck_import_jobs"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  j RECORD;
  v_resumed INT := 0;
  v_failed  INT := 0;
  v_stale interval := interval '7 minutes';
  v_max_attempts INT := 5;
  v_url  text := (SELECT decrypted_secret FROM vault.decrypted_secrets WHERE name = 'supabase_url') || '/functions/v1/linkedin-search-import';
  v_auth text := 'Bearer ' || (SELECT decrypted_secret FROM vault.decrypted_secrets WHERE name = 'supabase_service_role_key');
BEGIN
  FOR j IN
    SELECT id,
           COALESCE((metadata->>'max_leads')::int, 100)        AS max_leads,
           COALESCE((metadata->>'resume_attempts')::int, 0)    AS attempts,
           COALESCE(total_imported, 0) + COALESCE(total_skipped, 0) AS processed
    FROM linkedin_import_jobs
    WHERE status = 'running'
      AND started_at < now() - v_stale
      AND COALESCE((metadata->>'resume_attempts')::int, 0) < v_max_attempts
      AND COALESCE(total_imported, 0) + COALESCE(total_skipped, 0)
          < COALESCE((metadata->>'max_leads')::int, 100)
    ORDER BY started_at ASC
    LIMIT 20
  LOOP
    UPDATE linkedin_import_jobs
    SET started_at = now(),
        metadata = jsonb_set(
          COALESCE(metadata, '{}'::jsonb),
          '{resume_attempts}',
          to_jsonb(j.attempts + 1)
        )
    WHERE id = j.id;

    PERFORM net.http_post(
      url     := v_url,
      headers := jsonb_build_object(
        'Content-Type', 'application/json',
        'Authorization', v_auth
      ),
      body    := jsonb_build_object('jobId', j.id),
      timeout_milliseconds := 30000
    );

    v_resumed := v_resumed + 1;
    RAISE LOG '[stuck-import-recovery] Resumed job % (attempt %/%, processed %/%)',
      j.id, j.attempts + 1, v_max_attempts, j.processed, j.max_leads;
  END LOOP;

  FOR j IN
    SELECT id, type
    FROM linkedin_import_jobs
    WHERE status = 'running'
      AND started_at < now() - v_stale
      AND (
        COALESCE((metadata->>'resume_attempts')::int, 0) >= v_max_attempts
        OR (total_found = 0 AND total_imported = 0
            AND created_at < now() - interval '2 hours')
      )
    LIMIT 20
  LOOP
    UPDATE linkedin_import_jobs
    SET status = 'failed',
        error_message = CASE
          WHEN j.type = 'sales_nav' THEN
            'Import stalled and could not be recovered automatically. Please verify your Sales Navigator subscription is active and try again with a fresh search URL.'
          ELSE
            'Import stalled and could not be recovered automatically after several attempts. Please try again.'
        END,
        completed_at = now()
    WHERE id = j.id;

    v_failed := v_failed + 1;
    RAISE LOG '[stuck-import-recovery] Failed unrecoverable job %', j.id;
  END LOOP;

  IF v_resumed > 0 OR v_failed > 0 THEN
    RAISE LOG '[stuck-import-recovery] resumed=% failed=%', v_resumed, v_failed;
  END IF;
END;
$$;


ALTER FUNCTION "public"."recover_stuck_import_jobs"() OWNER TO "postgres";


