CREATE OR REPLACE FUNCTION "public"."recycle_autopilot_pool"("p_autopilot_id" "uuid", "p_include_failed" boolean DEFAULT false, "p_min_idle" interval DEFAULT NULL::interval) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_recycled_count INTEGER := 0;
BEGIN
  UPDATE public.autopilot_idea_pools
  SET
    status = 'available',
    recycle_count = COALESCE(recycle_count, 0) + 1,
    last_recycled_at = NOW(),
    error_message = CASE WHEN status = 'failed' THEN NULL ELSE error_message END
  WHERE autopilot_id = p_autopilot_id
    AND (status = 'produced' OR (p_include_failed AND status = 'failed'))
    AND can_recycle = true
    AND (
      p_min_idle IS NULL
      OR last_attempt_at IS NULL
      OR last_attempt_at < NOW() - p_min_idle
    );

  GET DIAGNOSTICS v_recycled_count = ROW_COUNT;

  RETURN jsonb_build_object(
    'success', true,
    'recycled', v_recycled_count,
    'autopilot_id', p_autopilot_id
  );
END;
$$;


ALTER FUNCTION "public"."recycle_autopilot_pool"("p_autopilot_id" "uuid", "p_include_failed" boolean, "p_min_idle" interval) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."refresh_all_campaign_metrics"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_updated INTEGER := 0;
  v_campaign RECORD;
  v_total INTEGER;
  v_processed INTEGER;
  v_contacted INTEGER;
  v_replied INTEGER;
  v_connection_rate DECIMAL;
BEGIN
  FOR v_campaign IN SELECT id FROM linkedin_campaigns WHERE status != 'completed' LOOP
    SELECT
      COUNT(*),
      COUNT(*) FILTER (WHERE status IN ('completed', 'replied', 'failed', 'skipped')),
      COUNT(*) FILTER (WHERE connection_sent_at IS NOT NULL OR last_message_at IS NOT NULL),
      COUNT(*) FILTER (WHERE status = 'replied')
    INTO v_total, v_processed, v_contacted, v_replied
    FROM campaign_lead_progress
    WHERE campaign_id = v_campaign.id
      AND is_test_contact = FALSE;

    SELECT
      CASE
        WHEN COUNT(*) FILTER (WHERE connection_sent_at IS NOT NULL) > 0
        THEN (COUNT(*) FILTER (WHERE connection_accepted_at IS NOT NULL)::DECIMAL /
              COUNT(*) FILTER (WHERE connection_sent_at IS NOT NULL) * 100)
        ELSE 0
      END
    INTO v_connection_rate
    FROM campaign_lead_progress
    WHERE campaign_id = v_campaign.id
      AND is_test_contact = FALSE;

    UPDATE linkedin_campaigns
    SET
      total_leads = v_total,
      processed_leads = v_processed,
      contacted_leads = v_contacted,
      replied_count = v_replied,
      connection_rate = v_connection_rate,
      updated_at = NOW()
    WHERE id = v_campaign.id
      AND (total_leads != v_total
        OR processed_leads != v_processed
        OR COALESCE(contacted_leads, 0) != v_contacted
        OR replied_count != v_replied
        OR COALESCE(connection_rate, 0) != v_connection_rate);

    IF FOUND THEN
      v_updated := v_updated + 1;
    END IF;
  END LOOP;

  RETURN v_updated;
END;
$$;


ALTER FUNCTION "public"."refresh_all_campaign_metrics"() OWNER TO "postgres";


