CREATE OR REPLACE FUNCTION "public"."refresh_channel_stats_for_contact"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF (TG_OP = 'UPDATE' AND (
    (OLD.primary_email IS DISTINCT FROM NEW.primary_email) OR
    (OLD.primary_phone IS DISTINCT FROM NEW.primary_phone)
  )) THEN
    INSERT INTO public.lead_list_channel_stats_refresh_queue (list_id)
    SELECT DISTINCT m.list_id
    FROM public.lead_list_members m
    WHERE m.contact_id = NEW.id
      AND EXISTS (SELECT 1 FROM public.lead_lists l WHERE l.id = m.list_id);
  END IF;
  RETURN NEW;
END;
$$;


