CREATE OR REPLACE FUNCTION "public"."refresh_channel_stats_on_member_change"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    PERFORM compute_lead_list_channel_stats(NEW.list_id);
    RETURN NEW;
  ELSIF TG_OP = 'DELETE' THEN
    PERFORM compute_lead_list_channel_stats(OLD.list_id);
    RETURN OLD;
  END IF;
  RETURN NULL;
END;
$$;


