    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    INSERT INTO public.lead_list_channel_stats_refresh_queue (list_id)
    SELECT DISTINCT i.list_id
    FROM inserted i
    WHERE EXISTS (SELECT 1 FROM public.lead_lists l WHERE l.id = i.list_id);
  ELSIF TG_OP = 'DELETE' THEN
    INSERT INTO public.lead_list_channel_stats_refresh_queue (list_id)
    SELECT DISTINCT d.list_id
    FROM deleted d
    WHERE EXISTS (SELECT 1 FROM public.lead_lists l WHERE l.id = d.list_id);
  END IF;
  RETURN NULL;
END;
$$;


