CREATE OR REPLACE FUNCTION "public"."refresh_warmup_endpoint_health"() RETURNS TABLE("dead_senders" integer, "dead_recipients" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  WITH checked AS (
    SELECT w.from_mailbox_id, w.to_mailbox_id, w.placement,
           coalesce(s.sending_domain_id::text, 'mbx:' || s.id::text) AS send_group,
           coalesce(r.organization_id::text || '|' || (r.metadata->>'m365_admin_email'),
                    'mbx:' || r.id::text) AS recv_group
    FROM public.email_warmup_sends w
    JOIN public.email_mailboxes s ON s.id = w.from_mailbox_id
    JOIN public.email_mailboxes r ON r.id = w.to_mailbox_id
    WHERE NOT w.is_reply
      AND w.placement IN ('inbox', 'junk', 'missing')
      AND w.sent_at > now() - interval '3 days'
  ),
  send_verdict AS (
    SELECT send_group,
           count(*)::int AS checked,
           count(*) FILTER (WHERE placement IN ('inbox','junk'))::int AS placed,
           count(*) FILTER (WHERE placement = 'missing')::int AS missing
    FROM checked GROUP BY 1
  ),
  recv_verdict AS (
    SELECT recv_group,
           count(*)::int AS checked,
           count(*) FILTER (WHERE placement IN ('inbox','junk'))::int AS placed,
           count(*) FILTER (WHERE placement = 'missing')::int AS missing
    FROM checked GROUP BY 1
  ),
  mbx AS (
    SELECT m.id,
           coalesce(m.sending_domain_id::text, 'mbx:' || m.id::text) AS send_group,
           coalesce(m.organization_id::text || '|' || (m.metadata->>'m365_admin_email'),
                    'mbx:' || m.id::text) AS recv_group
    FROM public.email_mailboxes m
    WHERE m.status IN ('ready', 'warming', 'paused')
  ),
  verdicts AS (
    SELECT mbx.id AS mailbox_id,
           coalesce(sv.checked,0) AS sc, coalesce(sv.placed,0) AS sp, coalesce(sv.missing,0) AS sm,
           coalesce(rv.checked,0) AS rc, coalesce(rv.placed,0) AS rp, coalesce(rv.missing,0) AS rm
    FROM mbx
    LEFT JOIN send_verdict sv ON sv.send_group = mbx.send_group
    LEFT JOIN recv_verdict rv ON rv.recv_group = mbx.recv_group
    WHERE sv.send_group IS NOT NULL OR rv.recv_group IS NOT NULL
  )
  INSERT INTO public.warmup_endpoint_health (
    mailbox_id, sent_checked_3d, sent_placed_3d, sent_missing_3d,
    recv_checked_3d, recv_placed_3d, recv_missing_3d,
    dead_as_sender, dead_as_recipient, refreshed_at)
  SELECT mailbox_id, sc, sp, sm, rc, rp, rm,
         (sc >= 20 AND sp = 0 AND sm >= 0.9 * sc),
         (rc >= 20 AND rp = 0 AND rm >= 0.9 * rc),
         now()
  FROM verdicts
  ON CONFLICT (mailbox_id) DO UPDATE SET
    sent_checked_3d   = EXCLUDED.sent_checked_3d,
    sent_placed_3d    = EXCLUDED.sent_placed_3d,
    sent_missing_3d   = EXCLUDED.sent_missing_3d,
    recv_checked_3d   = EXCLUDED.recv_checked_3d,
    recv_placed_3d    = EXCLUDED.recv_placed_3d,
    recv_missing_3d   = EXCLUDED.recv_missing_3d,
    dead_as_sender    = EXCLUDED.dead_as_sender,
    dead_as_recipient = EXCLUDED.dead_as_recipient,
    refreshed_at      = EXCLUDED.refreshed_at;

  UPDATE public.warmup_endpoint_health
     SET dead_as_sender = false, dead_as_recipient = false,
         sent_checked_3d = 0, sent_placed_3d = 0, sent_missing_3d = 0,
         recv_checked_3d = 0, recv_placed_3d = 0, recv_missing_3d = 0,
         refreshed_at = now()
   WHERE refreshed_at < now();

  RETURN QUERY
    SELECT count(*) FILTER (WHERE dead_as_sender)::int,
           count(*) FILTER (WHERE dead_as_recipient)::int
    FROM public.warmup_endpoint_health;
END;
$$;


ALTER FUNCTION "public"."refresh_warmup_endpoint_health"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."refund_rate_limited_enrichment_request"("p_reservation_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_event public.enrichment_provider_request_events%ROWTYPE;
  v_lock_key BIGINT;
BEGIN
  SELECT * INTO v_event
  FROM public.enrichment_provider_request_events event
  WHERE event.id = p_reservation_id
    AND event.status = 'scheduled'
  FOR UPDATE;

  IF v_event.id IS NULL THEN
    RETURN FALSE;
  END IF;

  v_lock_key := ('x' || left(md5(v_event.organization_id::TEXT || ':' || v_event.provider), 15))::bit(60)::bigint;
  PERFORM pg_advisory_xact_lock(v_lock_key);

  UPDATE public.enrichment_provider_request_events
  SET status = 'provider_rate_limited'
  WHERE id = v_event.id
    AND status = 'scheduled';

  UPDATE public.enrichment_provider_daily_usage usage
  SET request_count = GREATEST(0, usage.request_count - 1)
  WHERE usage.organization_id = v_event.organization_id
    AND usage.provider = v_event.provider
    AND usage.usage_date = v_event.usage_date;

  RETURN TRUE;
END;
$$;


ALTER FUNCTION "public"."refund_rate_limited_enrichment_request"("p_reservation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reinitialize_campaign_leads"("p_campaign_id" "uuid") RETURNS TABLE("leads_added" integer, "leads_removed" integer, "total_leads" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_campaign RECORD;
  v_org_id UUID;
  v_leads_added INTEGER := 0;
  v_leads_removed INTEGER := 0;
  v_total_leads INTEGER := 0;
BEGIN
  SELECT * INTO v_campaign FROM linkedin_campaigns WHERE id = p_campaign_id;
  IF v_campaign IS NULL THEN
    RAISE EXCEPTION 'Campaign not found: %', p_campaign_id;
  END IF;

  v_org_id := v_campaign.organization_id;

  IF v_campaign.lead_list_id IS NULL THEN
    RAISE EXCEPTION 'Campaign has no lead list selected';
  END IF;

  ALTER TABLE campaign_lead_progress DISABLE TRIGGER trg_update_campaign_metrics;

  DELETE FROM campaign_lead_progress
  WHERE campaign_id = p_campaign_id
    AND status = 'pending'
    AND contact_id NOT IN (
      SELECT llm.contact_id
      FROM lead_list_members llm
      JOIN crm_contacts c ON c.id = llm.contact_id
      WHERE llm.list_id = v_campaign.lead_list_id
        AND (
          v_campaign.exclusion_list_ids IS NULL
          OR array_length(v_campaign.exclusion_list_ids, 1) IS NULL
          OR NOT EXISTS (
            SELECT 1 FROM lead_list_members exc
            WHERE exc.contact_id = llm.contact_id
              AND exc.list_id = ANY(v_campaign.exclusion_list_ids)
          )
        )
        AND NOT public.contact_excluded_by_campaign_history(
          v_org_id, p_campaign_id, llm.contact_id,
          v_campaign.exclude_other_campaigns,
          v_campaign.exclude_same_sender,
          v_campaign.sender_account_ids
        )
    );

  GET DIAGNOSTICS v_leads_removed = ROW_COUNT;

  WITH eligible_leads AS (
    SELECT
      llm.contact_id,
      ROW_NUMBER() OVER (ORDER BY llm.added_at) as rn
    FROM lead_list_members llm
    JOIN crm_contacts c ON c.id = llm.contact_id
    WHERE llm.list_id = v_campaign.lead_list_id
      AND (
        v_campaign.exclusion_list_ids IS NULL
        OR array_length(v_campaign.exclusion_list_ids, 1) IS NULL
        OR NOT EXISTS (
          SELECT 1 FROM lead_list_members exc
          WHERE exc.contact_id = llm.contact_id
            AND exc.list_id = ANY(v_campaign.exclusion_list_ids)
        )
      )
      AND NOT EXISTS (
        SELECT 1 FROM campaign_lead_progress clp
        WHERE clp.campaign_id = p_campaign_id
          AND clp.contact_id = llm.contact_id
      )
      AND NOT public.contact_excluded_by_campaign_history(
        v_org_id, p_campaign_id, llm.contact_id,
        v_campaign.exclude_other_campaigns,
        v_campaign.exclude_same_sender,
        v_campaign.sender_account_ids
      )
  )
  INSERT INTO campaign_lead_progress (
    campaign_id, contact_id, status, current_node_id,
    next_action_at, variation_index, is_test_contact, created_at, updated_at
  )
  SELECT
    p_campaign_id, el.contact_id, 'pending', NULL,
    NOW(), (el.rn % 2)::INTEGER, false, NOW(), NOW()
  FROM eligible_leads el;

  GET DIAGNOSTICS v_leads_added = ROW_COUNT;

  ALTER TABLE campaign_lead_progress ENABLE TRIGGER trg_update_campaign_metrics;

  SELECT COUNT(*)::INTEGER INTO v_total_leads
  FROM campaign_lead_progress
  WHERE campaign_id = p_campaign_id;

  UPDATE linkedin_campaigns
  SET total_leads = v_total_leads, updated_at = NOW()
  WHERE id = p_campaign_id;

  RETURN QUERY SELECT v_leads_added, v_leads_removed, v_total_leads;
END;
$$;


ALTER FUNCTION "public"."reinitialize_campaign_leads"("p_campaign_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."reinitialize_campaign_leads"("p_campaign_id" "uuid") IS 'Re-initializes campaign leads after settings change. Removes pending-only leads no longer eligible, adds newly eligible leads.';



CREATE OR REPLACE FUNCTION "public"."reject_inconsistent_quickenrich_person"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NEW.source = 'quickenrich'
     AND NOT public.signal_person_identity_consistent(NEW.full_name, NEW.email, NEW.linkedin_url) THEN
    INSERT INTO public.signal_people_quality_rejections (
      source_person_id, company_key, full_name, email, linkedin_url, reason
    ) VALUES (
      NEW.id, NEW.company_key, NEW.full_name, NEW.email, NEW.linkedin_url,
      'name/email/linkedin identity mismatch'
    ) ON CONFLICT (source_person_id) DO NOTHING;
    RETURN NULL;
  END IF;
  RETURN NEW;
END;
$$;


