CREATE OR REPLACE FUNCTION "public"."reject_signup_request"("p_request_id" "uuid", "p_reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_request signup_requests%ROWTYPE;
BEGIN
  SELECT * INTO v_request FROM signup_requests WHERE id = p_request_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Request not found');
  END IF;

  IF v_request.status != 'pending' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Request already processed');
  END IF;

  UPDATE signup_requests SET
    status = 'rejected',
    processed_by = auth.uid(),
    processed_at = NOW(),
    rejection_reason = p_reason,
    updated_at = NOW()
  WHERE id = p_request_id;

  RETURN jsonb_build_object('success', true);
END;
$$;


