CREATE OR REPLACE FUNCTION "public"."remap_leads_on_sequence_change"("p_campaign_id" "uuid", "p_old_node_ids" "text"[]) RETURNS TABLE("leads_remapped" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_campaign RECORD;
  v_new_node_ids TEXT[];
  v_deleted_node_ids TEXT[];
  v_remapped INTEGER := 0;
BEGIN
  SELECT * INTO v_campaign FROM linkedin_campaigns WHERE id = p_campaign_id;
  IF v_campaign IS NULL THEN
    RAISE EXCEPTION 'Campaign not found: %', p_campaign_id;
  END IF;

  SELECT COALESCE(array_agg(node_obj->>'id'), ARRAY[]::TEXT[])
  INTO v_new_node_ids
  FROM jsonb_array_elements(COALESCE(v_campaign.sequence_nodes, '[]'::jsonb)) AS node_obj;

  SELECT COALESCE(array_agg(old_id), ARRAY[]::TEXT[])
  INTO v_deleted_node_ids
  FROM unnest(p_old_node_ids) AS old_id
  WHERE old_id != ALL(v_new_node_ids);

  IF array_length(v_deleted_node_ids, 1) IS NULL THEN
    RETURN QUERY SELECT 0;
    RETURN;
  END IF;

  UPDATE campaign_lead_progress
  SET
    status = 'pending',
    current_node_id = NULL,
    next_action_at = NOW(),
    error_message = NULL,
    retry_count = 0,
    updated_at = NOW()
  WHERE campaign_id = p_campaign_id
    AND current_node_id = ANY(v_deleted_node_ids)
    AND status IN ('pending', 'in_progress', 'waiting', 'pending_review', 'replied');

  GET DIAGNOSTICS v_remapped = ROW_COUNT;

  RETURN QUERY SELECT v_remapped;
END;
$$;


ALTER FUNCTION "public"."remap_leads_on_sequence_change"("p_campaign_id" "uuid", "p_old_node_ids" "text"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."remap_leads_on_sequence_change"("p_campaign_id" "uuid", "p_old_node_ids" "text"[]) IS 'When a campaign sequence is modified mid-flight, resets affected active leads to pending so the processor re-enters them at the new start node.';



CREATE OR REPLACE FUNCTION "public"."renew_sequence_sender_org_lease"("p_worker_id" "text", "p_org_id" "uuid", "p_lease_seconds" integer DEFAULT 300) RETURNS boolean
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH r AS (
    UPDATE sequence_sender_org_leases
    SET leased_until = now() + make_interval(secs => p_lease_seconds),
        updated_at = now()
    WHERE organization_id = p_org_id
      AND holder = p_worker_id
      AND leased_until >= now()
    RETURNING 1
  )
  SELECT EXISTS (SELECT 1 FROM r);
$$;


