CREATE OR REPLACE FUNCTION "public"."request_network_access"("p_company" "text", "p_website" "text", "p_use_case" "text", "p_self_hosted" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org_id uuid := get_user_organization_id();
  v_status text;
BEGIN
  IF auth.uid() IS NULL OR v_org_id IS NULL THEN
    RAISE EXCEPTION 'Not signed in' USING ERRCODE = '42501';
  END IF;

  -- get_user_org_role returns 'super_admin' for ACA staff instead of their org role.
  IF COALESCE(get_user_org_role(auth.uid(), v_org_id)::text, '') NOT IN ('owner', 'admin', 'super_admin') THEN
    RAISE EXCEPTION 'Only an organization owner or admin can apply for network access'
      USING ERRCODE = '42501';
  END IF;

  IF length(trim(COALESCE(p_company, ''))) = 0
     OR length(trim(COALESCE(p_website, ''))) = 0
     OR length(trim(COALESCE(p_use_case, ''))) < 20 THEN
    RAISE EXCEPTION 'Company, website and a use case of at least 20 characters are required';
  END IF;

  SELECT network_status INTO v_status FROM organizations WHERE id = v_org_id;

  IF v_status IN ('approved', 'suspended') THEN
    RAISE EXCEPTION 'This organization is already %', v_status;
  END IF;

  PERFORM set_config('aca.network_write', 'on', true);

  UPDATE organizations
  SET network_status = 'pending',
      network_only = COALESCE(p_self_hosted, false),
      network_application = jsonb_build_object(
        'company', left(trim(p_company), 200),
        'website', left(trim(p_website), 300),
        'use_case', left(trim(p_use_case), 2000),
        'self_hosted', COALESCE(p_self_hosted, false),
        'requested_by', auth.uid()
      ),
      network_requested_at = now(),
      network_reviewed_at = NULL,
      network_reviewed_by = NULL,
      network_review_note = NULL
  WHERE id = v_org_id;

  RETURN jsonb_build_object('organization_id', v_org_id, 'network_status', 'pending');
END;
$$;


ALTER FUNCTION "public"."request_network_access"("p_company" "text", "p_website" "text", "p_use_case" "text", "p_self_hosted" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."research_content_capture_metrics"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NEW.engagement IS NOT NULL
     AND (TG_OP = 'INSERT' OR NEW.engagement IS DISTINCT FROM OLD.engagement) THEN
    INSERT INTO research_content_metrics (content_id, organization_id, score, engagement)
    VALUES (NEW.id, NEW.organization_id, research_engagement_score(NEW.platform, NEW.engagement), NEW.engagement);
  END IF;
  RETURN NEW;
END;
$$;


