    LANGUAGE "plpgsql"
    AS $$
BEGIN
  NEW.id := OLD.id;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."research_content_keep_id"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."research_engagement_score"("p_platform" "text", "e" "jsonb") RETURNS numeric
    LANGUAGE "sql" IMMUTABLE
    AS $$
  SELECT CASE
    WHEN p_platform IN ('youtube', 'tiktok', 'twitter')
         AND coalesce(public.research_safe_numeric(e->>'viewCount'), 0) > 0
      THEN public.research_safe_numeric(e->>'viewCount')
    ELSE coalesce(public.research_safe_numeric(e->>'likeCount'), 0)
       + 3 * coalesce(public.research_safe_numeric(e->>'commentCount'), 0)
       + 5 * coalesce(public.research_safe_numeric(e->>'shareCount'), 0)
  END
$$;


ALTER FUNCTION "public"."research_engagement_score"("p_platform" "text", "e" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."research_refresh_candidates"("p_org" "uuid", "p_limit" integer DEFAULT 120) RETURNS TABLE("id" "text", "platform" "text", "url" "text", "published_at" timestamp with time zone)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  WITH outliers AS (
    SELECT t.id FROM get_trending_content(p_org, NULL, 30, 1.5, 200) t
  ),
  pool AS (
    SELECT rc.id, rc.platform, rc.url, rc.published_at, rc.metrics_checked_at,
           extract(epoch FROM now() - rc.published_at) / 3600 AS age_h
    FROM research_content rc
    WHERE rc.organization_id = p_org
      AND rc.url ~ '^https?://'
      AND rc.platform IN ('youtube', 'twitter', 'linkedin')
      AND rc.published_at > now() - interval '30 days'
      AND (rc.published_at > now() - interval '72 hours'
           OR rc.id IN (SELECT o.id FROM outliers o))
  )
  SELECT p.id, p.platform, p.url, p.published_at
  FROM pool p
  WHERE p.metrics_checked_at IS NULL
     OR p.metrics_checked_at < now() - CASE
          WHEN p.age_h < 48  THEN interval '6 hours'
          WHEN p.age_h < 168 THEN interval '24 hours'
          ELSE interval '84 hours'
        END
  ORDER BY coalesce(p.metrics_checked_at, 'epoch'::timestamptz), p.published_at DESC
  LIMIT p_limit;
$$;


ALTER FUNCTION "public"."research_refresh_candidates"("p_org" "uuid", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."research_safe_numeric"("v" "text") RETURNS numeric
    LANGUAGE "sql" IMMUTABLE
    AS $_$
  SELECT CASE WHEN v ~ '^\s*-?\d+(\.\d+)?\s*$' THEN v::numeric END
$_$;


ALTER FUNCTION "public"."research_safe_numeric"("v" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reserve_enrichment_provider_request"("p_organization_id" "uuid", "p_provider" "text", "p_requests_per_minute" integer, "p_daily_cap" integer DEFAULT NULL::integer, "p_max_wait_ms" integer DEFAULT 110000, "p_list_id" "uuid" DEFAULT NULL::"uuid", "p_records_per_minute" numeric DEFAULT NULL::numeric, "p_max_requests_per_minute" integer DEFAULT NULL::integer, "p_min_find_rate" numeric DEFAULT 0.05) RETURNS TABLE("reservation_status" "text", "reservation_id" "uuid", "wait_ms" integer, "scheduled_at" timestamp with time zone, "daily_used" integer, "daily_cap" integer, "requests_per_minute" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  c_min_sample CONSTANT INTEGER := 100;
  c_decay_at CONSTANT INTEGER := 2000;
  v_lock_key BIGINT;
  v_now TIMESTAMPTZ := clock_timestamp();
  v_next_slot TIMESTAMPTZ;
  v_slot TIMESTAMPTZ;
  v_wait_ms INTEGER;
  v_daily_used INTEGER := 0;
  v_reservation_id UUID;
  v_slot_interval INTERVAL;
  v_last_served_list_id UUID;
  v_other_list_waiting BOOLEAN := FALSE;
  v_recent_requests INTEGER := 0;
  v_recent_records INTEGER := 0;
  v_find_rate NUMERIC;
  v_effective_rpm INTEGER;
BEGIN
  IF p_requests_per_minute IS NULL OR p_requests_per_minute <= 0 THEN
    RAISE EXCEPTION 'requests_per_minute must be greater than zero';
  END IF;
  IF p_daily_cap IS NOT NULL AND p_daily_cap <= 0 THEN
    RAISE EXCEPTION 'daily_cap must be greater than zero when provided';
  END IF;

  v_lock_key := ('x' || left(md5(p_organization_id::TEXT || ':' || p_provider), 15))::bit(60)::bigint;
  PERFORM pg_advisory_xact_lock(v_lock_key);

  IF p_daily_cap IS NOT NULL THEN
    INSERT INTO public.enrichment_provider_daily_usage (organization_id, provider, usage_date, request_count, daily_cap)
    VALUES (p_organization_id, p_provider, CURRENT_DATE, 0, p_daily_cap)
    ON CONFLICT (organization_id, provider, usage_date)
    DO UPDATE SET daily_cap = EXCLUDED.daily_cap;

    SELECT usage.request_count INTO v_daily_used
    FROM public.enrichment_provider_daily_usage usage
    WHERE usage.organization_id = p_organization_id
      AND usage.provider = p_provider
      AND usage.usage_date = CURRENT_DATE;

    IF v_daily_used >= p_daily_cap THEN
      INSERT INTO public.enrichment_provider_request_events (organization_id, provider, status, requests_per_minute)
      VALUES (p_organization_id, p_provider, 'daily_exhausted', p_requests_per_minute);
      RETURN QUERY SELECT 'daily_exhausted'::TEXT, NULL::UUID, 0, NULL::TIMESTAMPTZ,
        v_daily_used, p_daily_cap, p_requests_per_minute;
      RETURN;
    END IF;
  END IF;

  INSERT INTO public.enrichment_provider_rate_limit_state (organization_id, provider, next_slot_at)
  VALUES (p_organization_id, p_provider, v_now)
  ON CONFLICT (organization_id, provider) DO NOTHING;

  SELECT state.next_slot_at, state.recent_requests, state.recent_records
    INTO v_next_slot, v_recent_requests, v_recent_records
  FROM public.enrichment_provider_rate_limit_state state
  WHERE state.organization_id = p_organization_id AND state.provider = p_provider
  FOR UPDATE;

  IF v_next_slot > v_now + INTERVAL '5 minutes' THEN v_next_slot := v_now; END IF;

  -- Caller owns the record budget (it asked the provider). We only convert it
  -- into a request rate through the find rate we actually observe.
  v_effective_rpm := p_requests_per_minute;
  IF p_records_per_minute IS NOT NULL AND p_records_per_minute > 0
     AND v_recent_requests >= c_min_sample THEN
    v_find_rate := GREATEST(v_recent_records::NUMERIC / v_recent_requests, p_min_find_rate);
    v_effective_rpm := GREATEST(1, FLOOR(p_records_per_minute / v_find_rate))::INTEGER;
  END IF;
  IF p_max_requests_per_minute IS NOT NULL THEN
    v_effective_rpm := LEAST(v_effective_rpm, GREATEST(1, p_max_requests_per_minute));
  END IF;

  v_slot_interval := (60000.0 / v_effective_rpm) * INTERVAL '1 millisecond';

  IF p_list_id IS NOT NULL THEN
    INSERT INTO public.enrichment_provider_fairness_state (organization_id, provider, last_served_list_id)
    VALUES (p_organization_id, p_provider, NULL)
    ON CONFLICT (organization_id, provider) DO NOTHING;

    SELECT state.last_served_list_id INTO v_last_served_list_id
    FROM public.enrichment_provider_fairness_state state
    WHERE state.organization_id = p_organization_id AND state.provider = p_provider
    FOR UPDATE;

    IF v_last_served_list_id = p_list_id THEN
      SELECT EXISTS (
        SELECT 1
        FROM public.lead_list_processing_items item
        JOIN public.lead_list_processing_policies policy ON policy.id = item.policy_id
        WHERE item.organization_id = p_organization_id
          AND (item.lead_list_id < p_list_id OR item.lead_list_id > p_list_id)
          AND policy.enabled = TRUE
          AND policy.paused_at IS NULL
          AND item.status IN ('pending', 'retry')
          AND item.next_attempt_at <= v_now
          AND item.stage = 'finding_email'
          AND (p_provider = ANY(COALESCE(policy.email_provider_chain, ARRAY[]::TEXT[])) OR policy.email_provider = p_provider)
      ) INTO v_other_list_waiting;
    END IF;

    IF v_other_list_waiting THEN
      v_wait_ms := GREATEST(
        CEIL(EXTRACT(EPOCH FROM (v_next_slot - v_now)) * 1000)::INTEGER,
        CEIL(EXTRACT(EPOCH FROM v_slot_interval) * 1000)::INTEGER
      );
      INSERT INTO public.enrichment_provider_request_events (organization_id, provider, status, requests_per_minute, scheduled_at)
      VALUES (p_organization_id, p_provider, 'deferred', v_effective_rpm, v_now + (v_wait_ms * INTERVAL '1 millisecond'));
      RETURN QUERY SELECT 'rate_wait'::TEXT, NULL::UUID, v_wait_ms,
        v_now + (v_wait_ms * INTERVAL '1 millisecond'), v_daily_used, p_daily_cap, v_effective_rpm;
      RETURN;
    END IF;
  END IF;

  v_slot := GREATEST(v_now, v_next_slot);
  v_wait_ms := GREATEST(0, CEIL(EXTRACT(EPOCH FROM (v_slot - v_now)) * 1000)::INTEGER);
  IF v_wait_ms > GREATEST(0, p_max_wait_ms) THEN
    INSERT INTO public.enrichment_provider_request_events (organization_id, provider, status, requests_per_minute, scheduled_at)
    VALUES (p_organization_id, p_provider, 'deferred', v_effective_rpm, v_slot);
    RETURN QUERY SELECT 'rate_wait'::TEXT, NULL::UUID, v_wait_ms, v_slot,
      v_daily_used, p_daily_cap, v_effective_rpm;
    RETURN;
  END IF;

  v_recent_requests := v_recent_requests + 1;
  IF v_recent_requests >= c_decay_at THEN
    v_recent_requests := v_recent_requests / 2;
    v_recent_records := v_recent_records / 2;
  END IF;

  UPDATE public.enrichment_provider_rate_limit_state state
  SET next_slot_at = v_slot + v_slot_interval,
      recent_requests = v_recent_requests,
      recent_records = v_recent_records,
      updated_at = v_now
  WHERE state.organization_id = p_organization_id AND state.provider = p_provider;

  IF p_list_id IS NOT NULL THEN
    UPDATE public.enrichment_provider_fairness_state state
    SET last_served_list_id = p_list_id, last_served_at = v_now
    WHERE state.organization_id = p_organization_id AND state.provider = p_provider;
  END IF;

  IF p_daily_cap IS NOT NULL THEN
    UPDATE public.enrichment_provider_daily_usage usage
    SET request_count = usage.request_count + 1, daily_cap = p_daily_cap
    WHERE usage.organization_id = p_organization_id AND usage.provider = p_provider AND usage.usage_date = CURRENT_DATE
    RETURNING usage.request_count INTO v_daily_used;
  END IF;

  INSERT INTO public.enrichment_provider_request_events (organization_id, provider, status, requests_per_minute, scheduled_at)
  VALUES (p_organization_id, p_provider, 'scheduled', v_effective_rpm, v_slot)
  RETURNING id INTO v_reservation_id;

  RETURN QUERY SELECT 'granted'::TEXT, v_reservation_id, v_wait_ms, v_slot,
    v_daily_used, p_daily_cap, v_effective_rpm;
END;
$$;


ALTER FUNCTION "public"."reserve_enrichment_provider_request"("p_organization_id" "uuid", "p_provider" "text", "p_requests_per_minute" integer, "p_daily_cap" integer, "p_max_wait_ms" integer, "p_list_id" "uuid", "p_records_per_minute" numeric, "p_max_requests_per_minute" integer, "p_min_find_rate" numeric) OWNER TO "postgres";


