CREATE OR REPLACE FUNCTION "public"."reset_idea_guidelines_approval"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  new_ai jsonb := CASE WHEN jsonb_typeof(NEW.ai_analysis) = 'object' THEN NEW.ai_analysis -> 'talking_points_ai' END;
BEGIN
  IF NEW.guidelines_approved_at IS NULL
     OR NEW.guidelines_approved_at IS DISTINCT FROM OLD.guidelines_approved_at THEN
    RETURN NEW;
  END IF;

  IF (jsonb_typeof(new_ai) = 'array' AND jsonb_array_length(new_ai) > 0)
     OR (
       new_ai IS NULL
       AND (NEW.ai_analysis -> 'talking_points') IS DISTINCT FROM (OLD.ai_analysis -> 'talking_points')
     ) THEN
    NEW.guidelines_approved_at := NULL;
    NEW.guidelines_approved_by := NULL;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."reset_idea_guidelines_approval"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reset_lead_list_processing_run"("p_list_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_policy_id UUID;
  v_count INTEGER;
BEGIN
  SELECT policy.id INTO v_policy_id
  FROM public.lead_list_processing_policies policy
  WHERE policy.lead_list_id = p_list_id
    AND EXISTS (
      SELECT 1
      FROM public.organization_members membership
      WHERE membership.organization_id = policy.organization_id
        AND membership.user_id = auth.uid()
    );

  IF v_policy_id IS NULL THEN
    RAISE EXCEPTION 'Configure lead processing for this list before resetting it';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.lead_list_processing_items item
    WHERE item.policy_id = v_policy_id
      AND item.status = 'processing'
  ) THEN
    RAISE EXCEPTION 'Cancel this workflow and wait for active provider calls to finish before resetting it';
  END IF;

  DELETE FROM public.lead_list_processing_provider_attempts
  WHERE lead_list_id = p_list_id;

  DELETE FROM public.email_provider_lookup_outcomes
  WHERE lead_list_id = p_list_id;

  UPDATE public.lead_list_processing_policies
  SET paused_at = NOW(),
      updated_at = NOW()
  WHERE id = v_policy_id;

  UPDATE public.lead_list_processing_items item
  SET status = 'pending',
      stage = 'queued',
      attempts = 0,
      recovery_attempts = 0,
      replacement_attempts = 0,
      analysis_reused = FALSE,
      force_reprocess = TRUE,
      next_attempt_at = NOW(),
      claimed_at = NULL,
      completed_at = NULL,
      rejected_reason = NULL,
      last_error = NULL,
      failure_category = NULL,
      cancel_requested_at = NULL,
      canceled_at = NULL,
      pause_requested_at = NULL,
      manual_run = TRUE,
      updated_at = NOW()
  WHERE item.policy_id = v_policy_id;

  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$$;


ALTER FUNCTION "public"."reset_lead_list_processing_run"("p_list_id" "uuid") OWNER TO "postgres";


