CREATE OR REPLACE FUNCTION "public"."resolve_campaign_entry_contact"("p_org" "uuid", "p_account" "uuid", "p_platform_id" "text", "p_name" "text", "p_profile_url" "text", "p_job_title" "text" DEFAULT NULL::"text", "p_avatar" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE contact_id uuid; identity_id uuid; linked uuid[];
BEGIN
  IF nullif(trim(p_platform_id),'') IS NULL OR NOT EXISTS(SELECT 1 FROM unipile_accounts WHERE id=p_account AND organization_id=p_org AND provider='LINKEDIN' AND status='active') THEN RAISE EXCEPTION 'Invalid incoming provider identity'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(p_org::text || ':linkedin:' || p_platform_id,0));
  SELECT i.contact_id,i.id,i.linked_account_ids INTO contact_id,identity_id,linked FROM crm_contact_identities i WHERE organization_id=p_org AND channel='linkedin' AND platform_user_id=p_platform_id;
  IF contact_id IS NOT NULL THEN
    UPDATE crm_contact_identities SET linked_account_ids=ARRAY(SELECT DISTINCT x FROM unnest(coalesce(linked,'{}'::uuid[]) || ARRAY[p_account]) x),updated_at=now() WHERE id=identity_id;
    RETURN contact_id;
  END IF;
  IF p_profile_url IS NOT NULL THEN
    SELECT c.id INTO contact_id FROM crm_contacts c WHERE organization_id=p_org AND lower(regexp_replace(coalesce(primary_linkedin_url,linkedin_url),'/+$',''))=lower(regexp_replace(p_profile_url,'/+$','')) LIMIT 1;
  END IF;
  IF contact_id IS NULL THEN
    INSERT INTO crm_contacts(organization_id,display_name,first_name,last_name,primary_linkedin_url,linkedin_url,job_title,avatar_url,source,status)
    VALUES(p_org,coalesce(nullif(p_name,''),p_platform_id),
      CASE WHEN nullif(trim(p_name),'') IS NOT NULL AND p_name<>p_platform_id THEN split_part(trim(p_name),' ',1) END,
      CASE WHEN nullif(trim(p_name),'') IS NOT NULL AND p_name<>p_platform_id THEN nullif(trim(substr(trim(p_name),length(split_part(trim(p_name),' ',1))+1)),'') END,
      p_profile_url,p_profile_url,p_job_title,p_avatar,'campaign_trigger','active') RETURNING id INTO contact_id;
  END IF;
  INSERT INTO crm_contact_identities(organization_id,contact_id,channel,platform_user_id,platform_username,linked_account_ids)
    VALUES(p_org,contact_id,'linkedin',p_platform_id,p_name,ARRAY[p_account]);
  RETURN contact_id;
END;
$_$;


ALTER FUNCTION "public"."resolve_campaign_entry_contact"("p_org" "uuid", "p_account" "uuid", "p_platform_id" "text", "p_name" "text", "p_profile_url" "text", "p_job_title" "text", "p_avatar" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."restart_canceled_lead_processing_run"("p_list_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_policy_id UUID;
  v_count INTEGER;
BEGIN
  UPDATE public.lead_list_processing_policies policy
  SET paused_at = NULL,
      updated_at = NOW()
  WHERE policy.lead_list_id = p_list_id
    AND EXISTS (
      SELECT 1
      FROM public.organization_members membership
      WHERE membership.organization_id = policy.organization_id
        AND membership.user_id = auth.uid()
    )
  RETURNING policy.id INTO v_policy_id;

  IF v_policy_id IS NULL THEN
    RAISE EXCEPTION 'Configure lead processing for this list before restarting it';
  END IF;

  UPDATE public.lead_list_processing_items item
  SET status = 'pending',
      stage = 'queued',
      attempts = 0,
      next_attempt_at = NOW(),
      claimed_at = NULL,
      completed_at = NULL,
      rejected_reason = NULL,
      last_error = NULL,
      cancel_requested_at = NULL,
      canceled_at = NULL,
      pause_requested_at = NULL,
      manual_run = TRUE,
      updated_at = NOW()
  WHERE item.policy_id = v_policy_id
    AND item.status = 'canceled';

  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$$;


