CREATE OR REPLACE FUNCTION "public"."resume_due_ooo_email_enrollments"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  affected INTEGER;
BEGIN
  UPDATE public.email_sequence_enrollments AS enrollment
  SET status = 'active',
      next_send_at = GREATEST(COALESCE(enrollment.next_send_at, NOW()), NOW()),
      pause_reason = NULL,
      resume_at = NULL,
      paused_by_conversation_id = NULL,
      metadata = (
        COALESCE(enrollment.metadata, '{}'::JSONB)
        - 'ooo_return_date'
        - 'ooo_detected_at'
      ) || JSONB_BUILD_OBJECT('last_ooo_resumed_at', NOW()),
      updated_at = NOW()
  FROM public.email_sequences AS sequence
  WHERE sequence.id = enrollment.sequence_id
    AND sequence.status = 'active'
    AND enrollment.status = 'paused'
    AND enrollment.pause_reason = 'out_of_office'
    AND enrollment.resume_at IS NOT NULL
    AND enrollment.resume_at <= NOW();

  GET DIAGNOSTICS affected = ROW_COUNT;
  RETURN affected;
END;
$$;


ALTER FUNCTION "public"."resume_due_ooo_email_enrollments"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resume_lead_list_processing"("p_list_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_policy_id UUID;
  v_count INTEGER;
BEGIN
  UPDATE public.lead_list_processing_policies policy
  SET paused_at = NULL,
      updated_at = NOW()
  WHERE policy.lead_list_id = p_list_id
    AND EXISTS (
      SELECT 1
      FROM public.organization_members membership
      WHERE membership.organization_id = policy.organization_id
        AND membership.user_id = auth.uid()
    )
  RETURNING policy.id INTO v_policy_id;

  IF v_policy_id IS NULL THEN
    RAISE EXCEPTION 'Configure lead processing for this list before resuming it';
  END IF;

  UPDATE public.lead_list_processing_items item
  SET pause_requested_at = NULL,
      next_attempt_at = NOW(),
      updated_at = NOW()
  WHERE item.policy_id = v_policy_id
    AND item.status IN ('pending', 'retry');

  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$$;


ALTER FUNCTION "public"."resume_lead_list_processing"("p_list_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."retry_failed_lead_list_processing_run"("p_list_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_policy_id UUID;
  v_count INTEGER;
BEGIN
  SELECT policy.id INTO v_policy_id
  FROM public.lead_list_processing_policies policy
  WHERE policy.lead_list_id = p_list_id
    AND policy.enabled = TRUE
    AND EXISTS (
      SELECT 1 FROM public.organization_members membership
      WHERE membership.organization_id = policy.organization_id
        AND membership.user_id = auth.uid()
    )
  LIMIT 1;

  IF v_policy_id IS NULL THEN
    RAISE EXCEPTION 'Enable lead processing for this list before retrying errors';
  END IF;

  UPDATE public.lead_list_processing_items item
  SET status = 'pending', stage = 'queued', attempts = 0, next_attempt_at = NOW(),
      claimed_at = NULL, completed_at = NULL, last_error = NULL,
      failure_category = NULL, cancel_requested_at = NULL, canceled_at = NULL,
      pause_requested_at = NULL, manual_run = TRUE, updated_at = NOW()
  WHERE item.policy_id = v_policy_id
    AND item.status = 'failed'
    AND COALESCE(item.failure_category, 'unknown') <> 'no_source_data';

  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$$;


ALTER FUNCTION "public"."retry_failed_lead_list_processing_run"("p_list_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."retry_transient_lead_processing_failures"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_count INTEGER;
BEGIN
  UPDATE public.lead_list_processing_items item
  SET status = 'pending', stage = 'queued', attempts = 0,
      recovery_attempts = item.recovery_attempts + 1,
      failure_category = NULL, last_error = NULL,
      next_attempt_at = NOW(), claimed_at = NULL, completed_at = NULL,
      updated_at = NOW()
  FROM public.lead_list_processing_policies policy
  WHERE policy.id = item.policy_id
    AND policy.enabled = TRUE
    AND item.status = 'failed'
    AND item.failure_category = 'transient'
    AND item.recovery_attempts < 3
    AND item.updated_at <= NOW() - INTERVAL '20 minutes';
  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$$;


ALTER FUNCTION "public"."retry_transient_lead_processing_failures"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."review_network_access"("p_org_id" "uuid", "p_decision" "text", "p_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org organizations%ROWTYPE;
  v_new_status text;
BEGIN
  IF NOT is_super_admin(auth.uid()) THEN
    RAISE EXCEPTION 'Only ACA staff can review network access' USING ERRCODE = '42501';
  END IF;

  v_new_status := CASE p_decision
    WHEN 'approve' THEN 'approved'
    WHEN 'reject' THEN 'rejected'
    WHEN 'suspend' THEN 'suspended'
    WHEN 'reinstate' THEN 'approved'
    ELSE NULL
  END;
  IF v_new_status IS NULL THEN
    RAISE EXCEPTION 'decision must be approve, reject, suspend or reinstate';
  END IF;

  SELECT * INTO v_org FROM organizations WHERE id = p_org_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Organization not found';
  END IF;

  IF p_decision IN ('approve', 'reject') AND v_org.network_status <> 'pending' THEN
    RAISE EXCEPTION 'Only a pending application can be approved or rejected (status is %)', v_org.network_status;
  END IF;
  IF p_decision = 'suspend' AND v_org.network_status <> 'approved' THEN
    RAISE EXCEPTION 'Only an approved organization can be suspended (status is %)', v_org.network_status;
  END IF;
  IF p_decision = 'reinstate' AND v_org.network_status <> 'suspended' THEN
    RAISE EXCEPTION 'Only a suspended organization can be reinstated (status is %)', v_org.network_status;
  END IF;

  PERFORM set_config('aca.network_write', 'on', true);

  UPDATE organizations
  SET network_status = v_new_status,
      network_reviewed_at = now(),
      network_reviewed_by = auth.uid(),
      network_review_note = NULLIF(trim(COALESCE(p_note, '')), '')
  WHERE id = p_org_id;

  INSERT INTO admin_action_logs (
    admin_user_id, target_organization_id, target_organization_name,
    action_type, previous_value, new_value
  ) VALUES (
    auth.uid(), p_org_id, v_org.name, 'network_review',
    jsonb_build_object('network_status', v_org.network_status),
    jsonb_build_object('network_status', v_new_status, 'decision', p_decision, 'note', p_note)
  );

  RETURN jsonb_build_object('organization_id', p_org_id, 'network_status', v_new_status);
END;
$$;


ALTER FUNCTION "public"."review_network_access"("p_org_id" "uuid", "p_decision" "text", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."route_lead_list_processing_no_data"("p_list_id" "uuid", "p_destination_type" "text", "p_destination_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_org UUID; v_count INTEGER;
BEGIN
  SELECT policy.organization_id INTO v_org FROM public.lead_list_processing_policies policy
  WHERE policy.lead_list_id = p_list_id
    AND EXISTS (SELECT 1 FROM public.organization_members member WHERE member.organization_id = policy.organization_id AND member.user_id = auth.uid());
  IF v_org IS NULL THEN RAISE EXCEPTION 'You cannot route outcomes for this list'; END IF;
  IF p_destination_type = 'list' THEN
    INSERT INTO public.lead_list_members (list_id, contact_id, source_data)
    SELECT p_destination_id, item.contact_id, jsonb_build_object('source','lead_processing_no_data','from_list_id',p_list_id)
    FROM public.lead_list_processing_items item
    JOIN public.lead_lists destination ON destination.id = p_destination_id AND destination.organization_id = v_org AND destination.status = 'active'
    WHERE item.lead_list_id = p_list_id AND item.status = 'failed' AND item.failure_category = 'no_source_data'
    ON CONFLICT (list_id, contact_id) DO NOTHING;
  ELSIF p_destination_type = 'linkedin_campaign' THEN
    INSERT INTO public.campaign_lead_progress (campaign_id, contact_id, status, next_action_at)
    SELECT p_destination_id, item.contact_id, 'pending', NOW()
    FROM public.lead_list_processing_items item
    JOIN public.linkedin_campaigns campaign ON campaign.id = p_destination_id AND campaign.organization_id = v_org AND campaign.status = 'active'
    WHERE item.lead_list_id = p_list_id AND item.status = 'failed' AND item.failure_category = 'no_source_data'
    ON CONFLICT (campaign_id, contact_id) DO NOTHING;
  ELSE RAISE EXCEPTION 'Unsupported destination'; END IF;
  GET DIAGNOSTICS v_count = ROW_COUNT; RETURN v_count;
END;
$$;


ALTER FUNCTION "public"."route_lead_list_processing_no_data"("p_list_id" "uuid", "p_destination_type" "text", "p_destination_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."route_lead_list_processing_no_source_data"("p_list_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_policy public.lead_list_processing_policies%ROWTYPE; v_count INTEGER;
BEGIN
  SELECT policy.* INTO v_policy FROM public.lead_list_processing_policies policy
  WHERE policy.lead_list_id = p_list_id
    AND EXISTS (SELECT 1 FROM public.organization_members member WHERE member.organization_id = policy.organization_id AND member.user_id = auth.uid());
  IF v_policy.id IS NULL THEN RAISE EXCEPTION 'You cannot route outcomes for this list'; END IF;
  IF v_policy.no_source_data_destination_type = 'none' OR v_policy.no_source_data_destination_id IS NULL THEN
    RAISE EXCEPTION 'Choose a destination for No source data in Processing setup first';
  END IF;
  SELECT public.route_lead_list_processing_no_data(p_list_id, v_policy.no_source_data_destination_type, v_policy.no_source_data_destination_id) INTO v_count;
  RETURN v_count;
END; $$;


ALTER FUNCTION "public"."route_lead_list_processing_no_source_data"("p_list_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."run_public_signal_auto_enroll"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_rule RECORD;
  v_pair RECORD;
  v_sig RECORD;
  v_discovery jsonb;
  v_company_id uuid;
  v_contact_id uuid;
  v_existing_discovery jsonb;
  v_added_rule integer;
  v_custom_added integer;
  v_rules integer := 0;
  v_total integer := 0;
BEGIN
  FOR v_rule IN
    SELECT r.*, l.status AS list_status
    FROM public.public_signal_auto_enroll_rules r
    JOIN public.lead_lists l ON l.id = r.list_id
    WHERE r.status = 'active'
    ORDER BY r.created_at
  LOOP
    IF v_rule.list_status <> 'active' THEN
      UPDATE public.public_signal_auto_enroll_rules SET status = 'paused' WHERE id = v_rule.id;
      CONTINUE;
    END IF;

    v_rules := v_rules + 1;
    v_added_rule := 0;

    IF COALESCE(v_rule.source, 'public') IN ('public', 'all') THEN
      FOR v_pair IN
        SELECT * FROM public.public_signal_auto_enroll_public_candidates(
          v_rule.organization_id, v_rule.list_id, v_rule.signal_types,
          v_rule.require_email, COALESCE(v_rule.filter_criteria, '{}'::jsonb), v_rule.lookback_days
        )
        LIMIT 500
      LOOP
        SELECT s.signal_type, s.signal_date, s.title, s.summary, s.why_it_matters,
               s.source_url, s.amount_label, s.company_linkedin_url, s.domain,
               s.metadata,
               c.industry,
               COALESCE(c.employee_range, public.signal_employee_band(c.employee_count, c.employee_range)) AS employee_range,
               c.revenue_range
          INTO v_sig
          FROM public.public_signals s
          LEFT JOIN public.public_signal_companies c
                 ON c.company_key = lower(s.company_name)
         WHERE s.id = v_pair.signal_id;

        v_discovery := jsonb_strip_nulls(jsonb_build_object(
          'source', 'public_signal',
          'public_signal_id', v_pair.signal_id,
          'auto_enroll_rule_id', v_rule.id,
          'signal_type', v_sig.signal_type,
          'signal_date', to_char(v_sig.signal_date, 'YYYY-MM-DD'),
          'signal_detail', COALESCE(NULLIF(btrim(v_sig.summary), ''), NULLIF(btrim(v_sig.title), '')),
          'signal_outreach_context', COALESCE(
            NULLIF(btrim(v_sig.why_it_matters), ''),
            NULLIF(btrim(v_sig.summary), '')
          ),
          'signal_source_url', v_sig.source_url,
          'directory_evidence_url', v_sig.source_url,
          'ai_signal_amount', NULLIF(btrim(COALESCE(v_sig.amount_label, '')), ''),
          'ai_signal_investors', CASE
            WHEN jsonb_typeof(v_sig.metadata -> 'investors') = 'array'
            THEN NULLIF((
              SELECT string_agg(btrim(x), ', ')
              FROM jsonb_array_elements_text(v_sig.metadata -> 'investors') x
              WHERE btrim(x) <> ''
            ), '')
          END,
          'ai_signal_company_website', CASE
            WHEN COALESCE(v_sig.domain, '') <> '' THEN 'https://' || v_sig.domain
          END,
          'ai_signal_company_linkedin', v_sig.company_linkedin_url,
          'ai_signal_company_industry', v_sig.industry,
          'ai_signal_company_size', v_sig.employee_range,
          'company_employee_range', v_sig.employee_range,
          'company_revenue_range', v_sig.revenue_range
        ));

        INSERT INTO public.crm_companies (
          organization_id, name, domain, website_url, linkedin_url,
          last_signal_at, enrichment_source, enrichment_data
        ) VALUES (
          v_rule.organization_id, v_pair.company_name, v_pair.domain,
          'https://' || v_pair.domain, v_pair.company_linkedin_url, now(), 'public_signal',
          jsonb_build_object(
            'public_signal_id', v_pair.signal_id,
            'signal_type', v_pair.signal_type,
            'source_url', v_pair.source_url
          )
        )
        ON CONFLICT (organization_id, normalized_domain) WHERE normalized_domain IS NOT NULL
        DO UPDATE SET
          last_signal_at = EXCLUDED.last_signal_at,
          enrichment_data = EXCLUDED.enrichment_data
        RETURNING id INTO v_company_id;

        SELECT id, discovery_metadata INTO v_contact_id, v_existing_discovery
        FROM public.crm_contacts
        WHERE organization_id = v_rule.organization_id
          AND primary_linkedin_url = v_pair.linkedin_url
        LIMIT 1;

        IF v_contact_id IS NULL THEN
          INSERT INTO public.crm_contacts (
            organization_id, display_name, company, company_id, job_title,
            primary_linkedin_url, source, source_details, discovery_metadata
          ) VALUES (
            v_rule.organization_id, v_pair.full_name, v_pair.company_name,
            v_company_id, v_pair.person_title, v_pair.linkedin_url, 'public_signal',
            jsonb_build_object(
              'public_signal_id', v_pair.signal_id,
              'source_url', v_pair.source_url,
              'auto_enroll_rule_id', v_rule.id
            ),
            v_discovery
          )
          RETURNING id INTO v_contact_id;
        ELSIF v_existing_discovery IS NULL
              OR COALESCE(v_existing_discovery ->> 'public_signal_id', '') <> v_pair.signal_id::text THEN
          UPDATE public.crm_contacts
             SET discovery_metadata = v_discovery,
                 updated_at = now()
           WHERE id = v_contact_id;
        END IF;

        INSERT INTO public.lead_list_members (list_id, contact_id, source_data)
        VALUES (
          v_rule.list_id, v_contact_id,
          jsonb_build_object(
            'source', 'public_signal_auto',
            'auto_enroll_rule_id', v_rule.id,
            'public_signal_id', v_pair.signal_id,
            'source_url', v_pair.source_url
          )
        )
        ON CONFLICT (list_id, contact_id) DO NOTHING;
        IF FOUND THEN
          v_added_rule := v_added_rule + 1;
        END IF;
      END LOOP;
    END IF;

    IF COALESCE(v_rule.source, 'public') IN ('custom', 'all') THEN
      INSERT INTO public.lead_list_members (list_id, contact_id, source_data)
      SELECT
        v_rule.list_id, x.contact_id,
        jsonb_build_object(
          'source', 'custom_signal_auto',
          'auto_enroll_rule_id', v_rule.id,
          'signal_subscription_id', x.subscription_id
        )
      FROM (
        SELECT * FROM public.public_signal_auto_enroll_custom_candidates(
          v_rule.organization_id, v_rule.list_id, v_rule.signal_types,
          v_rule.require_email, COALESCE(v_rule.filter_criteria, '{}'::jsonb)
        )
        LIMIT 500
      ) x
      ON CONFLICT (list_id, contact_id) DO NOTHING;

      GET DIAGNOSTICS v_custom_added = ROW_COUNT;
      v_added_rule := v_added_rule + COALESCE(v_custom_added, 0);
    END IF;

    UPDATE public.public_signal_auto_enroll_rules
    SET last_run_at = now(), total_enrolled = total_enrolled + v_added_rule
    WHERE id = v_rule.id;

    v_total := v_total + v_added_rule;
  END LOOP;

  RETURN jsonb_build_object('ok', true, 'rules_processed', v_rules, 'enrolled', v_total);
END;
$$;


ALTER FUNCTION "public"."run_public_signal_auto_enroll"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sample_lock_contention_once"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_n int;
begin
  with blocked as (
    select a.pid,
           a.usename,
           a.state,
           a.wait_event_type || ':' || coalesce(a.wait_event, '') as wait,
           extract(epoch from clock_timestamp() - a.query_start) * 1000 as dur_ms,
           a.query,
           unnest(pg_blocking_pids(a.pid)) as bpid
    from pg_stat_activity a
    where cardinality(pg_blocking_pids(a.pid)) > 0
  )
  insert into public.diag_lock_samples (
    captured_at,
    blocked_pid, blocked_user, blocked_state, blocked_wait,
    blocked_duration_ms, blocked_query,
    blocking_pid, blocking_user, blocking_state, blocking_wait,
    blocking_duration_ms, blocking_xact_ms, blocking_query
  )
  select clock_timestamp(),
         b.pid, b.usename, b.state, b.wait,
         b.dur_ms, left(b.query, 500),
         k.pid, k.usename, k.state,
         k.wait_event_type || ':' || coalesce(k.wait_event, ''),
         extract(epoch from clock_timestamp() - k.query_start) * 1000,
         extract(epoch from clock_timestamp() - k.xact_start) * 1000,
         left(k.query, 500)
  from blocked b
  join pg_stat_activity k on k.pid = b.bpid;

  get diagnostics v_n = row_count;
  return v_n;
end;
$$;


ALTER FUNCTION "public"."sample_lock_contention_once"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."scrub_deleted_mailbox_links"("p_mailbox_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  UPDATE email_sequences s
  SET settings = jsonb_set(
        s.settings,
        '{mailbox_ids}',
        COALESCE((
          SELECT jsonb_agg(e)
          FROM jsonb_array_elements_text(s.settings->'mailbox_ids') e
          WHERE e <> p_mailbox_id::text
        ), '[]'::jsonb)
      ),
      updated_at = now()
  WHERE jsonb_typeof(s.settings->'mailbox_ids') = 'array'
    AND s.settings->'mailbox_ids' @> to_jsonb(ARRAY[p_mailbox_id::text]);

  UPDATE mailbox_sets
  SET mailbox_ids = array_remove(mailbox_ids, p_mailbox_id),
      updated_at = now()
  WHERE p_mailbox_id = ANY(mailbox_ids);

  UPDATE leads
  SET assigned_mailbox_id = NULL,
      updated_at = now()
  WHERE assigned_mailbox_id = p_mailbox_id;
END;
$$;


ALTER FUNCTION "public"."scrub_deleted_mailbox_links"("p_mailbox_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."scrub_disconnected_sender_links"("p_account_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  -- 1a. Lead-magnet junction
  DELETE FROM unipile_campaign_sender_accounts
  WHERE account_id = p_account_id;

  -- 1b. Sequence campaigns: drop the dead id from UUID[] and from each channel
  --     array inside the sender_accounts jsonb.
  UPDATE linkedin_campaigns lc
  SET sender_account_ids = array_remove(lc.sender_account_ids, p_account_id),
      sender_accounts = CASE
        WHEN jsonb_typeof(COALESCE(lc.sender_accounts, '{}'::jsonb)) = 'object' THEN
          COALESCE((
            SELECT jsonb_object_agg(
                     key,
                     COALESCE((
                       SELECT jsonb_agg(e)
                       FROM jsonb_array_elements_text(value) e
                       WHERE e <> p_account_id::text
                     ), '[]'::jsonb))
            FROM jsonb_each(COALESCE(lc.sender_accounts, '{}'::jsonb))
          ), '{}'::jsonb)
        ELSE COALESCE(lc.sender_accounts, '{}'::jsonb)
      END
  WHERE p_account_id = ANY(lc.sender_account_ids)
     OR COALESCE(lc.sender_accounts, '{}'::jsonb)::text LIKE '%' || p_account_id::text || '%';

  -- 1c. Cancel still-queued DMs pointing at the dead sender.
  UPDATE unipile_message_queue
  SET status = 'cancelled',
      error_message = 'Sender account disconnected — message cancelled',
      updated_at = now()
  WHERE account_id = p_account_id
    AND status IN ('pending', 'processing');
END;
$$;


ALTER FUNCTION "public"."scrub_disconnected_sender_links"("p_account_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."search_campaign_leads"("p_campaign_id" "uuid", "p_search" "text" DEFAULT NULL::"text", "p_status" "text" DEFAULT NULL::"text", "p_page" integer DEFAULT 1, "p_page_size" integer DEFAULT 50) RETURNS TABLE("leads" "jsonb", "total_count" bigint)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_offset INTEGER;
  v_total BIGINT;
  v_result JSONB;
  v_search TEXT;
BEGIN
  v_offset := (p_page - 1) * p_page_size;
  v_search := NULLIF(TRIM(p_search), '');

  -- Count query
  SELECT COUNT(*) INTO v_total
  FROM campaign_lead_progress p
  INNER JOIN crm_contacts c ON c.id = p.contact_id
  WHERE p.campaign_id = p_campaign_id
    AND p.is_test_contact = FALSE
    AND (p_status IS NULL OR p.status = p_status)
    AND (v_search IS NULL OR (
      c.display_name ILIKE '%' || v_search || '%'
      OR c.first_name ILIKE '%' || v_search || '%'
      OR c.last_name ILIKE '%' || v_search || '%'
      OR c.primary_email ILIKE '%' || v_search || '%'
      OR c.company ILIKE '%' || v_search || '%'
      OR c.job_title ILIKE '%' || v_search || '%'
    ));

  -- Data query
  SELECT COALESCE(jsonb_agg(to_jsonb(sub)), '[]'::JSONB) INTO v_result
  FROM (
    SELECT
      p.id,
      p.campaign_id,
      p.contact_id,
      p.sender_account_id,
      p.status,
      p.current_node_id,
      p.next_action_at,
      p.connection_sent_at,
      p.connection_accepted_at,
      p.last_message_at,
      p.replied_at,
      p.variation_index,
      p.error_message,
      p.retry_count,
      p.created_at,
      p.updated_at,
      jsonb_build_object(
        'id', c.id,
        'first_name', c.first_name,
        'last_name', c.last_name,
        'display_name', c.display_name,
        'linkedin_url', c.primary_linkedin_url,
        'company', c.company,
        'job_title', c.job_title,
        'avatar_url', c.avatar_url,
        'primary_email', c.primary_email
      ) AS contact,
      CASE WHEN p.sender_account_id IS NOT NULL THEN
        jsonb_build_object(
          'id', sa.id,
          'display_name', sa.display_name,
          'status', sa.status
        )
      ELSE NULL END AS sender_account
    FROM campaign_lead_progress p
    INNER JOIN crm_contacts c ON c.id = p.contact_id
    LEFT JOIN unipile_accounts sa ON sa.id = p.sender_account_id
    WHERE p.campaign_id = p_campaign_id
      AND p.is_test_contact = FALSE
      AND (p_status IS NULL OR p.status = p_status)
      AND (v_search IS NULL OR (
        c.display_name ILIKE '%' || v_search || '%'
        OR c.first_name ILIKE '%' || v_search || '%'
        OR c.last_name ILIKE '%' || v_search || '%'
        OR c.primary_email ILIKE '%' || v_search || '%'
        OR c.company ILIKE '%' || v_search || '%'
        OR c.job_title ILIKE '%' || v_search || '%'
      ))
    ORDER BY p.created_at DESC
    LIMIT p_page_size
    OFFSET v_offset
  ) sub;

  RETURN QUERY SELECT v_result, v_total;
END;
$$;


ALTER FUNCTION "public"."search_campaign_leads"("p_campaign_id" "uuid", "p_search" "text", "p_status" "text", "p_page" integer, "p_page_size" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."search_campaign_leads"("p_campaign_id" "uuid", "p_search" "text" DEFAULT NULL::"text", "p_status" "text" DEFAULT NULL::"text", "p_page" integer DEFAULT 1, "p_page_size" integer DEFAULT 50, "p_sort_by" "text" DEFAULT 'created_at'::"text", "p_sort_dir" "text" DEFAULT 'desc'::"text") RETURNS TABLE("leads" "jsonb", "total_count" bigint)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_offset INTEGER;
  v_total BIGINT;
  v_result JSONB;
  v_search TEXT;
  v_is_seq_changed BOOLEAN;
BEGIN
  v_offset := (p_page - 1) * p_page_size;
  v_search := NULLIF(TRIM(p_search), '');
  v_is_seq_changed := (p_status = 'sequence_changed');

  -- Count query
  SELECT COUNT(*) INTO v_total
  FROM campaign_lead_progress p
  INNER JOIN crm_contacts c ON c.id = p.contact_id
  WHERE p.campaign_id = p_campaign_id
    AND p.is_test_contact = FALSE
    AND (
      p_status IS NULL
      OR (v_is_seq_changed AND p.error_message LIKE 'Sequence modified%')
      OR (NOT v_is_seq_changed AND p.status = p_status)
    )
    AND (v_search IS NULL OR (
      c.display_name ILIKE '%' || v_search || '%'
      OR c.first_name ILIKE '%' || v_search || '%'
      OR c.last_name ILIKE '%' || v_search || '%'
      OR c.primary_email ILIKE '%' || v_search || '%'
      OR c.company ILIKE '%' || v_search || '%'
      OR c.job_title ILIKE '%' || v_search || '%'
    ));

  -- Data query with dynamic sort
  SELECT COALESCE(jsonb_agg(to_jsonb(sub)), '[]'::JSONB) INTO v_result
  FROM (
    SELECT
      p.id,
      p.campaign_id,
      p.contact_id,
      p.sender_account_id,
      p.status,
      p.current_node_id,
      p.next_action_at,
      p.connection_sent_at,
      p.connection_accepted_at,
      p.last_message_at,
      p.replied_at,
      p.variation_index,
      p.error_message,
      p.retry_count,
      p.created_at,
      p.updated_at,
      jsonb_build_object(
        'id', c.id,
        'first_name', c.first_name,
        'last_name', c.last_name,
        'display_name', c.display_name,
        'linkedin_url', c.primary_linkedin_url,
        'company', c.company,
        'job_title', c.job_title,
        'avatar_url', c.avatar_url,
        'primary_email', c.primary_email
      ) AS contact,
      CASE WHEN p.sender_account_id IS NOT NULL THEN
        jsonb_build_object(
          'id', sa.id,
          'display_name', sa.display_name,
          'status', sa.status
        )
      ELSE NULL END AS sender_account
    FROM campaign_lead_progress p
    INNER JOIN crm_contacts c ON c.id = p.contact_id
    LEFT JOIN unipile_accounts sa ON sa.id = p.sender_account_id
    WHERE p.campaign_id = p_campaign_id
      AND p.is_test_contact = FALSE
      AND (
        p_status IS NULL
        OR (v_is_seq_changed AND p.error_message LIKE 'Sequence modified%')
        OR (NOT v_is_seq_changed AND p.status = p_status)
      )
      AND (v_search IS NULL OR (
        c.display_name ILIKE '%' || v_search || '%'
        OR c.first_name ILIKE '%' || v_search || '%'
        OR c.last_name ILIKE '%' || v_search || '%'
        OR c.primary_email ILIKE '%' || v_search || '%'
        OR c.company ILIKE '%' || v_search || '%'
        OR c.job_title ILIKE '%' || v_search || '%'
      ))
    ORDER BY
      CASE WHEN p_sort_by = 'next_action_at' AND p_sort_dir = 'asc'  THEN p.next_action_at END ASC NULLS LAST,
      CASE WHEN p_sort_by = 'next_action_at' AND p_sort_dir = 'desc' THEN p.next_action_at END DESC NULLS LAST,
      CASE WHEN p_sort_by = 'created_at'    AND p_sort_dir = 'asc'  THEN p.created_at END ASC,
      CASE WHEN p_sort_by = 'created_at'    AND p_sort_dir = 'desc' THEN p.created_at END DESC,
      p.created_at DESC
    LIMIT p_page_size
    OFFSET v_offset
  ) sub;

  RETURN QUERY SELECT v_result, v_total;
END;
$$;


ALTER FUNCTION "public"."search_campaign_leads"("p_campaign_id" "uuid", "p_search" "text", "p_status" "text", "p_page" integer, "p_page_size" integer, "p_sort_by" "text", "p_sort_dir" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."search_crm_contacts"("p_org_id" "uuid", "p_query" "text", "p_limit" integer DEFAULT 1000) RETURNS TABLE("contact_id" "uuid")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT c.id AS contact_id
  FROM crm_contacts c
  WHERE c.organization_id = p_org_id
    AND (
      c.display_name ILIKE '%' || p_query || '%'
      OR c.first_name ILIKE '%' || p_query || '%'
      OR c.last_name ILIKE '%' || p_query || '%'
      OR c.primary_email ILIKE '%' || p_query || '%'
      OR c.company ILIKE '%' || p_query || '%'
      OR c.job_title ILIKE '%' || p_query || '%'
    )
  LIMIT p_limit;
$$;


ALTER FUNCTION "public"."search_crm_contacts"("p_org_id" "uuid", "p_query" "text", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."search_crm_contacts_keyset"("p_org_id" "uuid", "p_query" "text", "p_after_id" "uuid" DEFAULT '00000000-0000-0000-0000-000000000000'::"uuid", "p_limit" integer DEFAULT 1000) RETURNS TABLE("contact_id" "uuid")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT c.id AS contact_id
  FROM crm_contacts c
  WHERE c.organization_id = p_org_id
    AND c.id > p_after_id
    AND (
      c.display_name ILIKE '%' || p_query || '%'
      OR c.first_name ILIKE '%' || p_query || '%'
      OR c.last_name ILIKE '%' || p_query || '%'
      OR c.primary_email ILIKE '%' || p_query || '%'
      OR c.company ILIKE '%' || p_query || '%'
      OR c.job_title ILIKE '%' || p_query || '%'
    )
  ORDER BY c.id
  LIMIT p_limit;
$$;


ALTER FUNCTION "public"."search_crm_contacts_keyset"("p_org_id" "uuid", "p_query" "text", "p_after_id" "uuid", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."search_inbox_messages"("p_org_id" "uuid", "p_query" "text", "p_limit" integer DEFAULT 50) RETURNS TABLE("conversation_id" "uuid", "message_id" "uuid", "content" "text", "email_subject" "text", "direction" "text", "created_at" timestamp with time zone, "rank" real, "contact_name" "text", "contact_email" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  RETURN QUERY
  WITH message_matches AS (
    -- Full-text search on message content + email subject
    SELECT DISTINCT ON (m.conversation_id)
      m.conversation_id,
      m.id AS message_id,
      m.content,
      m.email_subject,
      m.direction::TEXT,
      m.created_at,
      ts_rank(m.content_tsv, plainto_tsquery('english', p_query)) AS rank
    FROM public.crm_messages m
    WHERE m.organization_id = p_org_id
      AND m.content_tsv @@ plainto_tsquery('english', p_query)
    ORDER BY m.conversation_id,
             ts_rank(m.content_tsv, plainto_tsquery('english', p_query)) DESC
  ),
  contact_matches AS (
    -- ILIKE search on contact name / email
    SELECT DISTINCT ON (conv.id)
      conv.id AS conversation_id,
      NULL::UUID AS message_id,
      conv.last_message_preview AS content,
      NULL::TEXT AS email_subject,
      conv.last_message_direction::TEXT AS direction,
      conv.last_message_at AS created_at,
      1.0::REAL AS rank
    FROM public.crm_conversations conv
    INNER JOIN public.crm_contacts c ON c.id = conv.contact_id
    WHERE conv.organization_id = p_org_id
      AND (
        c.display_name ILIKE '%' || p_query || '%'
        OR c.first_name ILIKE '%' || p_query || '%'
        OR c.last_name ILIKE '%' || p_query || '%'
        OR c.primary_email ILIKE '%' || p_query || '%'
      )
    ORDER BY conv.id
  ),
  combined AS (
    SELECT * FROM message_matches
    UNION ALL
    SELECT * FROM contact_matches cm
    WHERE NOT EXISTS (
      SELECT 1 FROM message_matches mm
      WHERE mm.conversation_id = cm.conversation_id
    )
  )
  SELECT
    cb.conversation_id,
    cb.message_id,
    cb.content,
    cb.email_subject,
    cb.direction,
    cb.created_at,
    cb.rank,
    c.display_name AS contact_name,
    c.primary_email AS contact_email
  FROM combined cb
  INNER JOIN public.crm_conversations conv ON conv.id = cb.conversation_id
  INNER JOIN public.crm_contacts c ON c.id = conv.contact_id
  ORDER BY cb.rank DESC, cb.created_at DESC
  LIMIT p_limit;
END;
$$;


ALTER FUNCTION "public"."search_inbox_messages"("p_org_id" "uuid", "p_query" "text", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."search_knowledge_chunks"("p_organization_id" "uuid", "p_document_ids" "uuid"[], "p_query_embedding" "public"."vector", "p_limit" integer DEFAULT 5) RETURNS TABLE("chunk_id" "uuid", "document_id" "uuid", "content" "text", "similarity" double precision)
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    kc.id AS chunk_id,
    kc.document_id,
    kc.content,
    1 - (kc.embedding <=> p_query_embedding) AS similarity
  FROM public.knowledge_base_chunks kc
  WHERE kc.organization_id = p_organization_id
    AND kc.document_id = ANY(p_document_ids)
    AND kc.embedding IS NOT NULL
  ORDER BY kc.embedding <=> p_query_embedding
  LIMIT p_limit;
END;
$$;


ALTER FUNCTION "public"."search_knowledge_chunks"("p_organization_id" "uuid", "p_document_ids" "uuid"[], "p_query_embedding" "public"."vector", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."search_linkedin_connections"("p_organization_id" "uuid", "p_account_id" "uuid" DEFAULT NULL::"uuid", "p_search_query" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 50, "p_offset" integer DEFAULT 0) RETURNS TABLE("id" "uuid", "account_id" "uuid", "linkedin_id" "text", "linkedin_url" "text", "first_name" "text", "last_name" "text", "full_name" "text", "headline" "text", "job_title" "text", "company" "text", "location" "text", "profile_picture_url" "text", "connected_at" timestamp with time zone, "synced_at" timestamp with time zone, "total_count" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  RETURN QUERY
  WITH filtered AS (
    SELECT
      lc.*,
      COUNT(*) OVER() AS total_count
    FROM linkedin_connections_view lc
    WHERE lc.organization_id = p_organization_id
      AND (p_account_id IS NULL OR lc.account_id = p_account_id)
      AND (
        p_search_query IS NULL
        OR p_search_query = ''
        OR to_tsvector('english',
            coalesce(lc.first_name, '') || ' ' ||
            coalesce(lc.last_name, '') || ' ' ||
            coalesce(lc.company, '') || ' ' ||
            coalesce(lc.job_title, '') || ' ' ||
            coalesce(lc.headline, '')
          ) @@ plainto_tsquery('english', p_search_query)
        OR lc.first_name ILIKE '%' || p_search_query || '%'
        OR lc.last_name ILIKE '%' || p_search_query || '%'
        OR lc.company ILIKE '%' || p_search_query || '%'
        OR lc.job_title ILIKE '%' || p_search_query || '%'
        OR lc.full_name ILIKE '%' || p_search_query || '%'
      )
    ORDER BY lc.synced_at DESC
    LIMIT p_limit
    OFFSET p_offset
  )
  SELECT
    f.id,
    f.account_id,
    f.linkedin_id,
    f.linkedin_url,
    f.first_name,
    f.last_name,
    f.full_name,
    f.headline,
    f.job_title,
    f.company,
    f.location,
    f.profile_picture_url,
    f.connected_at,
    f.synced_at,
    f.total_count
  FROM filtered f;
END;
$$;


ALTER FUNCTION "public"."search_linkedin_connections"("p_organization_id" "uuid", "p_account_id" "uuid", "p_search_query" "text", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."search_linkedin_connections"("p_organization_id" "uuid", "p_account_id" "uuid", "p_search_query" "text", "p_limit" integer, "p_offset" integer) IS 'Searches LinkedIn connections via linkedin_connections_view (crm_contacts-backed). Fixed 2026-09-03 — was reading the abandoned linkedin_connections table.';



CREATE TABLE IF NOT EXISTS "public"."prompt_library" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "name" "text" NOT NULL,
    "description" "text",
    "category" "text",
    "prompt_content" "text" NOT NULL,
    "variables" "jsonb" DEFAULT '[]'::"jsonb",
    "content_types" "text"[] DEFAULT '{}'::"text"[],
    "goals" "text"[] DEFAULT '{}'::"text"[],
    "composed_of" "uuid"[] DEFAULT '{}'::"uuid"[],
    "usage_count" integer DEFAULT 0,
    "is_public" boolean DEFAULT false,
    "is_preset" boolean DEFAULT false,
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"(),
    "updated_at" timestamp with time zone DEFAULT "now"(),
    "prompt_type" "text" DEFAULT 'text'::"text" NOT NULL,
    "pipeline_type" "text",
    "scenario" "text",
    "preview_url" "text",
    CONSTRAINT "prompt_library_category_check" CHECK (("category" = ANY (ARRAY['hook'::"text", 'framework'::"text", 'angle'::"text", 'structure'::"text", 'tone'::"text", 'cta'::"text", 'other'::"text"]))),
    CONSTRAINT "prompt_library_prompt_type_check" CHECK (("prompt_type" = ANY (ARRAY['text'::"text", 'image'::"text", 'caption'::"text", 'structure'::"text", 'master'::"text", 'director'::"text"])))
);


ALTER TABLE "public"."prompt_library" OWNER TO "postgres";


COMMENT ON TABLE "public"."prompt_library" IS 'Three-tier prompt system: blocks (atomic), templates (compositions), and masters (complete prompts)';



COMMENT ON COLUMN "public"."prompt_library"."category" IS 'Classification for blocks: hook, framework, angle, structure, tone, cta';



COMMENT ON COLUMN "public"."prompt_library"."variables" IS 'Array of variable paths required in this prompt, e.g., ["brand_voice.name", "product.icp.painPoints"]';



COMMENT ON COLUMN "public"."prompt_library"."composed_of" IS 'For templates/masters: array of prompt_library IDs that compose this prompt';



COMMENT ON COLUMN "public"."prompt_library"."prompt_type" IS 'Type of prompt: text for master prompts, image for image generation prompts';



COMMENT ON COLUMN "public"."prompt_library"."preview_url" IS 'Public URL of an example image showing what this template produces.';



CREATE OR REPLACE FUNCTION "public"."search_prompts_by_tags"("p_tags" "text"[], "p_organization_id" "uuid" DEFAULT NULL::"uuid") RETURNS SETOF "public"."prompt_library"
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  SELECT DISTINCT pl.*
  FROM prompt_library pl
  INNER JOIN prompt_library_tags plt ON pl.id = plt.prompt_id
  WHERE plt.tag = ANY(p_tags)
    AND (
      p_organization_id IS NULL
      OR pl.organization_id = p_organization_id
      OR pl.is_public = TRUE
    )
  ORDER BY pl.usage_count DESC;
$$;


ALTER FUNCTION "public"."search_prompts_by_tags"("p_tags" "text"[], "p_organization_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."search_prompts_by_tags"("p_tags" "text"[], "p_organization_id" "uuid") IS 'Search prompts by one or more tags, optionally filtered by organization';



CREATE OR REPLACE FUNCTION "public"."search_sequence_enrollments"("p_sequence_id" "uuid", "p_search" "text" DEFAULT NULL::"text", "p_status" "text" DEFAULT NULL::"text", "p_page" integer DEFAULT 1, "p_page_size" integer DEFAULT 50) RETURNS TABLE("enrollments" "jsonb", "total_count" bigint)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_offset INTEGER;
  v_total BIGINT;
  v_result JSONB;
  v_search TEXT;
BEGIN
  v_offset := (p_page - 1) * p_page_size;
  v_search := NULLIF(TRIM(p_search), '');

  -- Count query
  SELECT COUNT(*) INTO v_total
  FROM email_sequence_enrollments e
  LEFT JOIN leads l ON l.id = e.lead_id
  LEFT JOIN crm_contacts c ON c.id = COALESCE(l.source_id, e.lead_id)
  WHERE e.sequence_id = p_sequence_id
    AND (p_status IS NULL OR e.status = p_status)
    AND (v_search IS NULL OR (
      l.first_name ILIKE '%' || v_search || '%'
      OR l.last_name ILIKE '%' || v_search || '%'
      OR l.email ILIKE '%' || v_search || '%'
      OR l.company ILIKE '%' || v_search || '%'
      OR l.job_title ILIKE '%' || v_search || '%'
      OR c.display_name ILIKE '%' || v_search || '%'
      OR c.primary_email ILIKE '%' || v_search || '%'
      OR c.company ILIKE '%' || v_search || '%'
      OR c.job_title ILIKE '%' || v_search || '%'
    ));

  -- Data query
  SELECT COALESCE(jsonb_agg(to_jsonb(sub)), '[]'::JSONB) INTO v_result
  FROM (
    SELECT
      e.id,
      e.sequence_id,
      e.lead_id,
      e.current_step,
      e.status,
      e.next_send_at,
      e.mailbox_id,
      e.variant_assignments,
      e.condition_waiting_since,
      e.custom_data,
      e.cycle_number,
      e.created_at,
      e.updated_at,
      -- Enriched fields
      COALESCE(
        NULLIF(TRIM(CONCAT_WS(' ', l.first_name, l.last_name)), ''),
        c.display_name
      ) AS lead_name,
      COALESCE(l.email, c.primary_email) AS lead_email,
      COALESCE(l.job_title, c.job_title) AS lead_position,
      COALESCE(l.company, c.company) AS lead_company,
      m.email_address AS mailbox_email,
      -- crm_contact_id: if lead exists use leads.source_id, else lead_id is legacy crm contact
      CASE
        WHEN l.id IS NOT NULL THEN l.source_id
        WHEN c.id IS NOT NULL THEN c.id
        ELSE NULL
      END AS crm_contact_id
    FROM email_sequence_enrollments e
    LEFT JOIN leads l ON l.id = e.lead_id
    LEFT JOIN crm_contacts c ON c.id = COALESCE(l.source_id, e.lead_id)
    LEFT JOIN email_mailboxes m ON m.id = e.mailbox_id
    WHERE e.sequence_id = p_sequence_id
      AND (p_status IS NULL OR e.status = p_status)
      AND (v_search IS NULL OR (
        l.first_name ILIKE '%' || v_search || '%'
        OR l.last_name ILIKE '%' || v_search || '%'
        OR l.email ILIKE '%' || v_search || '%'
        OR l.company ILIKE '%' || v_search || '%'
        OR l.job_title ILIKE '%' || v_search || '%'
        OR c.display_name ILIKE '%' || v_search || '%'
        OR c.primary_email ILIKE '%' || v_search || '%'
        OR c.company ILIKE '%' || v_search || '%'
        OR c.job_title ILIKE '%' || v_search || '%'
      ))
    ORDER BY e.created_at DESC
    LIMIT p_page_size
    OFFSET v_offset
  ) sub;

  RETURN QUERY SELECT v_result, v_total;
END;
$$;


ALTER FUNCTION "public"."search_sequence_enrollments"("p_sequence_id" "uuid", "p_search" "text", "p_status" "text", "p_page" integer, "p_page_size" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."seed_lead_list_processing_items"("p_list_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_policy_id UUID;
  v_org_id UUID;
  v_count INTEGER;
BEGIN
  SELECT id, organization_id INTO v_policy_id, v_org_id
  FROM public.lead_list_processing_policies
  WHERE lead_list_id = p_list_id AND enabled = TRUE;

  IF v_policy_id IS NULL THEN RETURN 0; END IF;

  WITH batch AS (
    SELECT m.contact_id
    FROM public.lead_list_members m
    WHERE m.list_id = p_list_id
      AND NOT EXISTS (
        SELECT 1
        FROM public.lead_list_processing_items existing
        WHERE existing.policy_id = v_policy_id
          AND existing.contact_id = m.contact_id
      )
    ORDER BY m.contact_id
    LIMIT 500
  )
  INSERT INTO public.lead_list_processing_items (
    policy_id, organization_id, lead_list_id, contact_id
  )
  SELECT v_policy_id, v_org_id, p_list_id, batch.contact_id
  FROM batch
  ON CONFLICT (policy_id, contact_id) DO NOTHING;

  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$$;


ALTER FUNCTION "public"."seed_lead_list_processing_items"("p_list_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."seed_yc_identity_only_observation"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_name text;
  v_name_normalized text;
  v_domain text;
  v_website_url text;
  v_identity_id uuid;
BEGIN
  IF NEW.collector_key <> 'yc_directory'
     OR NEW.event_type IS DISTINCT FROM 'directory_presence' THEN
    RETURN NEW;
  END IF;

  v_name := nullif(trim(NEW.entity_hints->>'company_name'), '');
  v_domain := lower(nullif(trim(NEW.entity_hints->>'domain'), ''));
  v_website_url := nullif(trim(NEW.entity_hints->>'website_url'), '');

  -- Collector domains are already normalized, but reject malformed hints at
  -- the database boundary instead of making them canonical identities.
  IF v_domain IS NOT NULL
     AND v_domain ~ '^[a-z0-9](?:[a-z0-9.-]*[a-z0-9])?\.[a-z]{2,}$'
     AND v_name IS NOT NULL THEN
    v_name_normalized := trim(
      regexp_replace(lower(v_name), '[^a-z0-9-]+', ' ', 'g')
    );

    INSERT INTO public.company_identities (
      name,
      name_normalized,
      domain,
      website_url,
      resolved_via,
      resolved_at
    ) VALUES (
      v_name,
      v_name_normalized,
      v_domain,
      coalesce(v_website_url, 'https://' || v_domain),
      'yc_directory_hint',
      now()
    )
    ON CONFLICT (domain) WHERE domain IS NOT NULL DO NOTHING
    RETURNING id INTO v_identity_id;

    IF v_identity_id IS NULL THEN
      SELECT id INTO v_identity_id
      FROM public.company_identities
      WHERE domain = v_domain;
    END IF;
  END IF;

  NEW.company_identity_id := v_identity_id;
  NEW.status := 'skipped';
  NEW.error := CASE
    WHEN v_identity_id IS NOT NULL
      THEN 'identity_seed_only: YC directory evidence is not a buying signal'
    ELSE 'identity_seed_only: no source-provided domain; paid resolution disabled'
  END;
  NEW.lease_until := NULL;
  NEW.claimed_by := NULL;
  NEW.updated_at := now();
  RETURN NEW;
END;
$_$;


ALTER FUNCTION "public"."seed_yc_identity_only_observation"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."select_campaign_channel_for_contact"("p_campaign_id" "uuid", "p_contact_id" "uuid") RETURNS TABLE("channel" character varying, "identity_id" "uuid", "identifier" "text")
    LANGUAGE "plpgsql" STABLE
    AS $$
DECLARE
  v_campaign RECORD;
  v_fallback_channel TEXT;
  v_identity RECORD;
BEGIN
  -- Get campaign configuration
  SELECT * INTO v_campaign
  FROM public.campaigns
  WHERE id = p_campaign_id;

  IF NOT FOUND THEN
    RETURN;
  END IF;

  -- First, try primary channel
  SELECT ci.id, ci.channel, ci.platform_user_id INTO v_identity
  FROM public.crm_contact_identities ci
  WHERE ci.contact_id = p_contact_id
    AND ci.channel = v_campaign.primary_channel
  LIMIT 1;

  IF FOUND THEN
    RETURN QUERY SELECT
      v_campaign.primary_channel::VARCHAR(20),
      v_identity.id,
      v_identity.platform_user_id;
    RETURN;
  END IF;

  -- If primary not available and fallback enabled, try fallback order
  IF v_campaign.channel_fallback_enabled THEN
    FOREACH v_fallback_channel IN ARRAY v_campaign.fallback_order
    LOOP
      SELECT ci.id, ci.channel, ci.platform_user_id INTO v_identity
      FROM public.crm_contact_identities ci
      WHERE ci.contact_id = p_contact_id
        AND ci.channel = v_fallback_channel
      LIMIT 1;

      IF FOUND THEN
        RETURN QUERY SELECT
          v_fallback_channel::VARCHAR(20),
          v_identity.id,
          v_identity.platform_user_id;
        RETURN;
      END IF;
    END LOOP;
  END IF;

  -- No channel available
  RETURN;
END;
$$;


ALTER FUNCTION "public"."select_campaign_channel_for_contact"("p_campaign_id" "uuid", "p_contact_id" "uuid") OWNER TO "postgres";


