CREATE OR REPLACE FUNCTION "public"."set_inbox_keyword_exclusions"("p_org_id" "uuid", "p_keywords" "text"[]) RETURNS TABLE("keyword_count" integer, "conversations_excluded" integer, "contacts_archived" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  normalized_keywords text[];
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM public.organization_members membership
    WHERE membership.user_id = auth.uid()
      AND membership.organization_id = p_org_id
  ) AND auth.role() <> 'service_role' THEN
    RAISE EXCEPTION 'Not authorized for organization %', p_org_id;
  END IF;

  SELECT ARRAY_AGG(DISTINCT normalized ORDER BY normalized)
  INTO normalized_keywords
  FROM (
    SELECT public.normalize_inbox_keyword(keyword) AS normalized
    FROM unnest(COALESCE(p_keywords, ARRAY[]::text[])) AS keyword
  ) values_to_normalize
  WHERE normalized <> '';

  DELETE FROM public.inbox_keyword_exclusions exclusion
  WHERE exclusion.organization_id = p_org_id
    AND (
      normalized_keywords IS NULL
      OR exclusion.normalized_keyword <> ALL(normalized_keywords)
    );

  IF normalized_keywords IS NOT NULL AND array_length(normalized_keywords, 1) IS NOT NULL THEN
    INSERT INTO public.inbox_keyword_exclusions (
      organization_id,
      keyword,
      normalized_keyword,
      created_by_user_id
    )
    SELECT p_org_id, keyword, keyword, NULLIF(auth.uid()::text, '')::uuid
    FROM unnest(normalized_keywords) AS keyword
    ON CONFLICT (organization_id, normalized_keyword)
    DO UPDATE SET keyword = EXCLUDED.keyword, updated_at = NOW();
  END IF;

  SELECT COUNT(*)::integer
  INTO keyword_count
  FROM public.inbox_keyword_exclusions exclusion
  WHERE exclusion.organization_id = p_org_id;

  INSERT INTO public.inbox_keyword_sweep_queue (
    organization_id,
    requested_at,
    started_at,
    finished_at,
    conversations_excluded,
    contacts_archived,
    error,
    attempts,
    next_attempt_at,
    keyword_cursor
  )
  VALUES (p_org_id, NOW(), NULL, NULL, 0, 0, NULL, 0, NOW(), 0)
  ON CONFLICT (organization_id) WHERE finished_at IS NULL
  DO UPDATE SET
    requested_at = NOW(),
    started_at = NULL,
    conversations_excluded = 0,
    contacts_archived = 0,
    error = NULL,
    attempts = 0,
    next_attempt_at = NOW(),
    keyword_cursor = 0;

  conversations_excluded := 0;
  contacts_archived := 0;
  RETURN NEXT;
END;
$$;


ALTER FUNCTION "public"."set_inbox_keyword_exclusions"("p_org_id" "uuid", "p_keywords" "text"[]) OWNER TO "postgres";


