CREATE OR REPLACE FUNCTION "public"."set_sending_domain_paused"("p_domain_id" "uuid", "p_paused" boolean, "p_reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_domain public.email_sending_domains%ROWTYPE;
BEGIN
  SELECT * INTO v_domain FROM public.email_sending_domains WHERE id = p_domain_id FOR UPDATE;
  IF NOT FOUND OR (auth.role() IS DISTINCT FROM 'service_role' AND NOT public.is_super_admin(auth.uid()) AND NOT EXISTS (
    SELECT 1 FROM public.organization_members WHERE organization_id = v_domain.organization_id
      AND user_id = auth.uid() AND role IN ('owner', 'admin'))) THEN
    RAISE EXCEPTION 'Domain unavailable or permission denied' USING ERRCODE = '42501';
  END IF;
  IF p_paused IS NULL THEN RAISE EXCEPTION 'p_paused must be true or false' USING ERRCODE = '22023'; END IF;
  IF NOT p_paused AND public.is_sending_domain_technically_unusable(p_domain_id) THEN
    RAISE EXCEPTION 'This domain is technically unusable or replaced and cannot be resumed' USING ERRCODE = '22023';
  END IF;
  UPDATE public.email_sending_domains SET
    sending_paused_at = CASE WHEN p_paused THEN coalesce(sending_paused_at, now()) ELSE NULL END,
    sending_pause_reason = CASE WHEN p_paused THEN coalesce(nullif(btrim(p_reason), ''), 'Paused by operator') ELSE NULL END,
    sending_paused_by = CASE WHEN p_paused THEN auth.uid() ELSE NULL END,
    updated_at = now()
  WHERE id = p_domain_id RETURNING * INTO v_domain;
  RETURN jsonb_build_object('domain_id', v_domain.id,
    'sending_paused_at', v_domain.sending_paused_at, 'sending_pause_reason', v_domain.sending_pause_reason,
    'sending_paused_by', v_domain.sending_paused_by,
    'technically_unusable', public.is_sending_domain_technically_unusable(v_domain.id));
END;
$$;


ALTER FUNCTION "public"."set_sending_domain_paused"("p_domain_id" "uuid", "p_paused" boolean, "p_reason" "text") OWNER TO "postgres";


