CREATE OR REPLACE FUNCTION "public"."signal_buyer_persona"("p_title" "text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$
DECLARE
  v_title text := lower(btrim(coalesce(p_title, '')));
BEGIN
  IF v_title = '' OR v_title ~ '\m(assistant|associate|advisor|consultant|coordinator|intern|student)\M'
     OR v_title ~ '\m(account manager|partner manager|partner advisor|people partner|human resources partner|hr partner|product owner|process owner|office of (the )?ceo)\M' THEN
    RETURN NULL;
  END IF;

  IF v_title ~ '\m(co[ -]?founder|founder|ceo|chief executive( officer)?|managing director|managing partner|general partner|founding partner)\M'
     OR (v_title ~ '\m(owner|president)\M'
       AND v_title !~ '\m(vice president|product owner|process owner)\M') THEN
    RETURN 'executive';
  END IF;

  IF v_title ~ '\m(chief revenue officer|chief sales officer|chief commercial officer|cro)\M'
     OR (
       v_title ~ '\m(chief|vp|svp|evp|vice president|head|director)\M'
       AND v_title ~ '\m(sales|revenue|commercial|business development|partnerships?|alliances?|channel)\M'
     ) THEN
    RETURN 'sales_revenue';
  END IF;

  IF v_title ~ '\m(chief marketing officer|chief growth officer|cmo)\M'
     OR (
       v_title ~ '\m(chief|vp|svp|evp|vice president|head|director)\M'
       AND v_title ~ '\m(marketing|growth|demand generation|demand gen|go[ -]to[ -]market|gtm|brand)\M'
     ) THEN
    RETURN 'marketing_growth';
  END IF;
  RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."signal_buyer_persona"("p_title" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."signal_buyer_persona_priority"("p_title" "text") RETURNS integer
    LANGUAGE "sql" IMMUTABLE
    AS $$
  SELECT CASE
    WHEN public.signal_buyer_persona(p_title) = 'executive'
      AND lower(p_title) ~ '\m(co[ -]?founder|founder|ceo|chief executive)\M' THEN 100
    WHEN public.signal_buyer_persona(p_title) = 'executive' THEN 95
    WHEN lower(p_title) ~ '\m(chief revenue officer|chief sales officer|chief commercial officer|cro|chief marketing officer|chief growth officer|cmo)\M' THEN 90
    WHEN lower(p_title) ~ '\m(vp|svp|evp|vice president)\M' THEN 85
    WHEN lower(p_title) ~ '\mhead\M' THEN 80
    WHEN public.signal_buyer_persona(p_title) IS NOT NULL THEN 70
    ELSE 0
  END;
$$;


ALTER FUNCTION "public"."signal_buyer_persona_priority"("p_title" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."signal_company_passes_filter"("p_criteria" "jsonb", "p_employee_count" integer, "p_employee_range" "text", "p_revenue_range" "text") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE PARALLEL SAFE
    AS $$
  WITH crit AS (
    SELECT
      CASE WHEN jsonb_typeof(p_criteria -> 'employee_bands') = 'array' THEN
        ARRAY(SELECT btrim(v) FROM jsonb_array_elements_text(p_criteria -> 'employee_bands') v
              WHERE btrim(v) <> '')
      ELSE '{}'::text[] END AS emp,
      CASE WHEN jsonb_typeof(p_criteria -> 'revenue_bands') = 'array' THEN
        ARRAY(SELECT public.signal_revenue_band(v) FROM jsonb_array_elements_text(p_criteria -> 'revenue_bands') v
              WHERE public.signal_revenue_band(v) IS NOT NULL)
      ELSE '{}'::text[] END AS rev
  )
  SELECT
        (cardinality(c.emp) = 0
         OR COALESCE(public.signal_employee_band(p_employee_count, p_employee_range) = ANY(c.emp), false))
    AND (cardinality(c.rev) = 0
         OR COALESCE(public.signal_revenue_band(p_revenue_range) = ANY(c.rev), false))
  FROM crit c;
$$;


ALTER FUNCTION "public"."signal_company_passes_filter"("p_criteria" "jsonb", "p_employee_count" integer, "p_employee_range" "text", "p_revenue_range" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."signal_company_passes_filter"("p_criteria" "jsonb", "p_employee_count" integer, "p_employee_range" "text", "p_revenue_range" "text") IS 'Company-level auto-enroll gates (employee_bands, revenue_bands). A company whose firmographic is unknown FAILS a set gate — same convention as the country gate. Shared by both candidate cores and the preview RPC.';



CREATE OR REPLACE FUNCTION "public"."signal_domain_agrees"("p_left" "text", "p_right" "text") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE PARALLEL SAFE
    AS $$
  SELECT CASE
    WHEN public.signal_normalize_domain(p_left)  IS NULL THEN true
    WHEN public.signal_normalize_domain(p_right) IS NULL THEN true
    ELSE public.signal_normalize_domain(p_left) = public.signal_normalize_domain(p_right)
  END;
$$;


ALTER FUNCTION "public"."signal_domain_agrees"("p_left" "text", "p_right" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."signal_domain_agrees"("p_left" "text", "p_right" "text") IS 'False ONLY when both domains are known and differ. Unknown on either side agrees — this gate acts on positive evidence of a mismatch, never on absence of data.';



CREATE OR REPLACE FUNCTION "public"."signal_employee_band"("p_count" integer, "p_range" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE PARALLEL SAFE
    AS $$
  SELECT CASE
    WHEN p_count IS NOT NULL AND p_count >= 1 THEN
      CASE
        WHEN p_count = 1        THEN '1'
        WHEN p_count <= 10      THEN '2-10'
        WHEN p_count <= 50      THEN '11-50'
        WHEN p_count <= 200     THEN '51-200'
        WHEN p_count <= 500     THEN '201-500'
        WHEN p_count <= 1000    THEN '501-1000'
        WHEN p_count <= 5000    THEN '1001-5000'
        ELSE '5001+'
      END
    ELSE
      CASE lower(btrim(COALESCE(p_range, '')))
        WHEN '11-20'     THEN '11-50'
        WHEN '21-50'     THEN '11-50'
        WHEN '51-200'    THEN '51-200'
        WHEN '201-500'   THEN '201-500'
        WHEN '501-1000'  THEN '501-1000'
        WHEN '1001-5000' THEN '1001-5000'
        WHEN '5001+'     THEN '5001+'
        -- '1-10' and the provider's dirty values ('Small', 'Mid-Market',
        -- 'Enterprise', 'Unknown') are deliberately absent: unknown, not guessed.
        ELSE NULL
      END
  END;
$$;


ALTER FUNCTION "public"."signal_employee_band"("p_count" integer, "p_range" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."signal_employee_band"("p_count" integer, "p_range" "text") IS 'Exact headcount (preferred) or provider band → one of 1 | 2-10 | 11-50 | 51-200 | 201-500 | 501-1000 | 1001-5000 | 5001+. NULL when the inputs cannot place the company, including the provider band "1-10" which straddles the solo boundary.';



CREATE OR REPLACE FUNCTION "public"."signal_engine_health_snapshot"() RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "statement_timeout" TO '20s'
    AS $$
  WITH age AS (
    SELECT
      (SELECT extract(epoch FROM now() - max(created_at)) / 3600
         FROM signal_observations WHERE collector_key = 'google_news_rss') AS news_obs_age_h,
      (SELECT extract(epoch FROM now() - max(created_at)) / 3600
         FROM signal_observations WHERE collector_key = 'edgar_form_d') AS edgar_form_d_obs_age_h,
      (SELECT extract(epoch FROM now() - max(created_at)) / 3600
         FROM signal_observations WHERE collector_key = 'edgar_8k') AS edgar_8k_obs_age_h,
      (SELECT extract(epoch FROM now() - max(last_success_at)) / 3600
         FROM signal_sources WHERE collector_key = 'ats_boards') AS ats_run_age_h,
      (SELECT extract(epoch FROM now() - max(last_success_at)) / 3600
         FROM signal_sources WHERE enabled AND collector_key IN ('edgar_form_d', 'edgar_8k')) AS edgar_run_age_h,
      (SELECT extract(epoch FROM now() - max(published_to_public_at)) / 3600
         FROM signal_events) AS last_publish_age_h
  ),
  identity_waiting AS (
    -- `attempts = 0` is insufficient: free-only cache misses keep attempts at
    -- zero but record an awaiting-domain outcome in `error`. Count only rows
    -- no resolver has completed, excluding exhausted/intentional retry rows.
    -- Claims update updated_at, so use created_at to age untouched evidence.
    SELECT created_at
      FROM public.signal_observations
     WHERE status = 'extracted'
       AND attempts < 3
       AND error IS NULL
       AND collector_key <> 'yc_directory'
       AND (lease_until IS NULL OR lease_until < now())
  ),
  waiting AS (
    -- Non-hiring events still waiting on a publisher-article check. Hiring is
    -- excluded: news-headline hiring events are intentionally never resolved.
    SELECT o.id AS obs_id,
           o.source_url,
           o.structured
      FROM signal_events e
      JOIN signal_observations o ON o.id = ANY (e.observation_ids)
     WHERE e.public_signal_id IS NULL
       AND e.publish_status IN ('pending', 'failed')
       AND e.event_type <> 'hiring'
       AND o.collector_key = 'google_news_rss'
  )
  SELECT to_jsonb(age.*) || jsonb_build_object(
    'identity_resolution_backlog',
      (SELECT count(*) FROM identity_waiting),
    'identity_resolution_oldest_pending_age_h',
      (SELECT extract(epoch FROM now() - min(created_at)) / 3600 FROM identity_waiting),
    'identity_resolution_last_progress_age_h',
      -- Publisher verification also updates merged observations. Only merge
      -- advances an event's last_seen_at; evidence retries cannot mask a stall.
      (SELECT extract(epoch FROM now() - max(last_seen_at)) / 3600
         FROM public.signal_events WHERE event_type <> 'directory_presence'),
    'resolve_backlog',
      (SELECT count(DISTINCT obs_id) FROM waiting WHERE source_url LIKE 'https://news.google.com/%'),
    'resolve_last_attempt_age_h',
      (SELECT extract(epoch FROM now() - max((structured->>'canonical_resolution_attempted_at')::timestamptz)) / 3600
         FROM signal_observations
        WHERE collector_key = 'google_news_rss' AND structured ? 'canonical_resolution_attempted_at'),
    'verify_backlog',
      (SELECT count(DISTINCT obs_id) FROM waiting
        WHERE source_url NOT LIKE 'https://news.google.com/%'
          AND structured->>'evidence_status' = 'rss_headline_only'
          AND NOT (structured ? 'canonical_verification_attempted_at')),
    'verify_last_attempt_age_h',
      (SELECT extract(epoch FROM now() - max((structured->>'canonical_verification_attempted_at')::timestamptz)) / 3600
         FROM signal_observations
        WHERE collector_key = 'google_news_rss' AND structured ? 'canonical_verification_attempted_at'),
    'pending_non_hiring',
      (SELECT count(*) FROM signal_events
        WHERE public_signal_id IS NULL AND publish_status IN ('pending', 'failed') AND event_type <> 'hiring'),
    'failed_events',
      (SELECT count(*) FROM signal_events WHERE publish_status = 'failed')
  )
  FROM age;
$$;


ALTER FUNCTION "public"."signal_engine_health_snapshot"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."signal_enrollment_counts"("p_subscription_id" "uuid") RETURNS TABLE("today_count" integer, "week_count" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT
    (SELECT COUNT(*)::INT FROM public.signal_activity_log
       WHERE subscription_id = p_subscription_id
         AND outcome IN ('enrolled','enrolled_holding')
         AND created_at >= date_trunc('day', NOW())),
    (SELECT COUNT(*)::INT FROM public.signal_activity_log
       WHERE subscription_id = p_subscription_id
         AND outcome IN ('enrolled','enrolled_holding')
         AND created_at >= date_trunc('week', NOW()))
$$;


ALTER FUNCTION "public"."signal_enrollment_counts"("p_subscription_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."signal_filter_int"("p_criteria" "jsonb", "p_key" "text", "p_default" integer) RETURNS integer
    LANGUAGE "sql" IMMUTABLE PARALLEL SAFE
    AS $$
  SELECT CASE
    WHEN p_criteria IS NULL THEN p_default
    WHEN jsonb_typeof(p_criteria -> p_key) = 'number'
      THEN GREATEST(trunc((p_criteria ->> p_key)::numeric)::integer, 0)
    ELSE p_default
  END;
$$;


ALTER FUNCTION "public"."signal_filter_int"("p_criteria" "jsonb", "p_key" "text", "p_default" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."signal_firmographic_candidates"("p_org" "uuid" DEFAULT NULL::"uuid", "p_sources" "text"[] DEFAULT NULL::"text"[], "p_recheck_days" integer DEFAULT 90, "p_limit" integer DEFAULT 100, "p_include_domain_only" boolean DEFAULT false) RETURNS TABLE("id" "uuid", "organization_id" "uuid", "company_name" "text", "domain" "text", "website_url" "text", "source" "text", "employee_count_estimate" integer, "revenue_range" "text", "anchor_linkedin_url" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    SET "statement_timeout" TO '30s'
    AS $$
  SELECT c.id,
         c.organization_id,
         c.company_name,
         c.domain,
         c.website_url,
         c.source,
         c.employee_count_estimate,
         c.revenue_range,
         COALESCE(dm.linkedin_url, cc.primary_linkedin_url) AS anchor_linkedin_url
    FROM public.lb_discovered_companies c
    -- Company-scoped and exact, so it is tried first.
    LEFT JOIN LATERAL (
      SELECT d.linkedin_url
        FROM public.lb_decision_makers d
       WHERE d.company_id = c.id
         AND d.linkedin_url ~* '/in/'
       LIMIT 1
    ) dm ON true
    -- Name-matched, hence the nameMatches() guard on the caller side. Skipped
    -- entirely when a decision maker already anchored the row.
    LEFT JOIN LATERAL (
      SELECT x.primary_linkedin_url
        FROM public.crm_contacts x
       WHERE x.organization_id = c.organization_id
         AND x.company_name = c.company_name
         AND x.primary_linkedin_url ~* '/in/'
       LIMIT 1
    ) cc ON dm.linkedin_url IS NULL
   WHERE c.employee_count_estimate IS NULL
     AND (c.firmographics_checked_at IS NULL
          OR c.firmographics_checked_at < now() - make_interval(days => GREATEST(p_recheck_days, 1)))
     AND (p_org IS NULL OR c.organization_id = p_org)
     AND (p_sources IS NULL OR cardinality(p_sources) = 0 OR c.source = ANY(p_sources))
     AND (
           COALESCE(dm.linkedin_url, cc.primary_linkedin_url) IS NOT NULL
           -- Domain-only rows are for the opt-in search_companies lane; excluded
           -- by default so a normal run never queues work for a quota that locks
           -- for days.
           OR (p_include_domain_only AND COALESCE(c.domain, '') <> '')
         )
   ORDER BY (COALESCE(dm.linkedin_url, cc.primary_linkedin_url) IS NULL), c.scraped_at DESC
   LIMIT GREATEST(LEAST(p_limit, 500), 1);
$$;


ALTER FUNCTION "public"."signal_firmographic_candidates"("p_org" "uuid", "p_sources" "text"[], "p_recheck_days" integer, "p_limit" integer, "p_include_domain_only" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."signal_firmographic_candidates"("p_org" "uuid", "p_sources" "text"[], "p_recheck_days" integer, "p_limit" integer, "p_include_domain_only" boolean) IS 'Companies still missing a headcount, returned WITH the personal LinkedIn URL that can resolve them (decision-maker first, CRM contact by exact company name second). Anchored rows sort first. Domain-only rows are opt-in because they can only be served by the search quota. Carries its own 30s statement_timeout: deciding membership requires probing every un-enriched company, which does not fit the 8s web default.';



CREATE OR REPLACE FUNCTION "public"."signal_has_company_gate"("p_criteria" "jsonb") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE PARALLEL SAFE
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM (VALUES ('employee_bands'), ('revenue_bands')) AS k(key)
    WHERE jsonb_typeof(p_criteria -> k.key) = 'array'
      AND EXISTS (
        SELECT 1 FROM jsonb_array_elements_text(p_criteria -> k.key) v
        WHERE btrim(v) <> ''
      )
  );
$$;


ALTER FUNCTION "public"."signal_has_company_gate"("p_criteria" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."signal_has_company_gate"("p_criteria" "jsonb") IS 'True when filter_criteria sets a non-empty employee_bands or revenue_bands gate. Lets both candidate cores skip the firmographic join when no company gate is set.';



CREATE OR REPLACE FUNCTION "public"."signal_lead_passes_filter"("p_criteria" "jsonb", "p_title" "text", "p_seniority" integer, "p_country" "text") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE PARALLEL SAFE
    AS $$
  WITH crit AS (
    SELECT
      CASE WHEN jsonb_typeof(p_criteria -> 'title_includes') = 'array' THEN
        ARRAY(SELECT lower(btrim(v)) FROM jsonb_array_elements_text(p_criteria -> 'title_includes') v WHERE btrim(v) <> '')
      ELSE '{}'::text[] END AS inc,
      CASE WHEN jsonb_typeof(p_criteria -> 'title_excludes') = 'array' THEN
        ARRAY(SELECT lower(btrim(v)) FROM jsonb_array_elements_text(p_criteria -> 'title_excludes') v WHERE btrim(v) <> '')
      ELSE '{}'::text[] END AS exc,
      CASE WHEN jsonb_typeof(p_criteria -> 'countries') = 'array' THEN
        ARRAY(SELECT public.normalize_country_code(v) FROM jsonb_array_elements_text(p_criteria -> 'countries') v
              WHERE public.normalize_country_code(v) IS NOT NULL)
      ELSE '{}'::text[] END AS countries,
      public.signal_filter_int(p_criteria, 'min_seniority', 0) AS min_seniority
  )
  SELECT
        (cardinality(c.inc) = 0
         OR EXISTS (SELECT 1 FROM unnest(c.inc) k WHERE lower(COALESCE(p_title, '')) LIKE '%' || k || '%'))
    AND NOT EXISTS (SELECT 1 FROM unnest(c.exc) k WHERE lower(COALESCE(p_title, '')) LIKE '%' || k || '%')
    AND COALESCE(p_seniority, 0) >= COALESCE(c.min_seniority, 0)
    AND (cardinality(c.countries) = 0
         OR COALESCE(public.normalize_country_code(p_country) = ANY(c.countries), false))
  FROM crit c;
$$;


ALTER FUNCTION "public"."signal_lead_passes_filter"("p_criteria" "jsonb", "p_title" "text", "p_seniority" integer, "p_country" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."signal_lead_passes_filter"("p_criteria" "jsonb", "p_title" "text", "p_seniority" integer, "p_country" "text") IS 'Row-level auto-enroll gates (title includes/excludes, min_seniority, countries). Shared by the public and custom branches of the sweep and by the preview RPC.';



CREATE OR REPLACE FUNCTION "public"."signal_normalize_domain"("p_domain" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE PARALLEL SAFE
    AS $_$
  SELECT NULLIF(
    lower(regexp_replace(btrim(COALESCE(p_domain, '')),
                         '^(https?://)?(www\.)?([^/?#]+).*$', '\3')),
    ''
  );
$_$;


ALTER FUNCTION "public"."signal_normalize_domain"("p_domain" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."signal_normalize_domain"("p_domain" "text") IS 'Scheme/www/path-stripped, lowercased registrable form of a domain. NULL when blank.';



CREATE OR REPLACE FUNCTION "public"."signal_person_identity_consistent"("p_full_name" "text", "p_email" "text", "p_linkedin_url" "text") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    AS $$
  SELECT public.signal_person_name_matches_value(p_full_name, split_part(coalesce(p_email, ''), '@', 1))
    AND public.signal_person_name_matches_value(
      p_full_name,
      split_part(split_part(coalesce(p_linkedin_url, ''), '/in/', 2), '/', 1)
    );
$$;


ALTER FUNCTION "public"."signal_person_identity_consistent"("p_full_name" "text", "p_email" "text", "p_linkedin_url" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."signal_person_is_eligible"("p_linkedin_url" "text", "p_title" "text") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE PARALLEL SAFE
    AS $$
  SELECT public.signal_person_url_is_valid(p_linkedin_url)
     AND public.signal_person_title_is_senior(p_title);
$$;


ALTER FUNCTION "public"."signal_person_is_eligible"("p_linkedin_url" "text", "p_title" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."signal_person_name_matches_value"("p_full_name" "text", "p_value" "text") RETURNS boolean
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$
DECLARE
  v_parts text[] := regexp_split_to_array(btrim(coalesce(p_full_name, '')), '[[:space:]]+');
  v_first text;
  v_last text;
  v_value text := regexp_replace(lower(coalesce(p_value, '')), '[^a-z]', '', 'g');
BEGIN
  IF cardinality(v_parts) = 0 THEN RETURN false; END IF;
  v_first := regexp_replace(lower(v_parts[1]), '[^a-z]', '', 'g');
  v_last := regexp_replace(lower(v_parts[cardinality(v_parts)]), '[^a-z]', '', 'g');
  RETURN (length(v_first) >= 3 AND strpos(v_value, v_first) > 0)
    OR (length(v_last) >= 3 AND v_last NOT IN ('null', 'none') AND strpos(v_value, v_last) > 0);
END;
$$;


ALTER FUNCTION "public"."signal_person_name_matches_value"("p_full_name" "text", "p_value" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."signal_person_title_is_senior"("p_title" "text") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE PARALLEL SAFE
    AS $_$
  SELECT
    COALESCE(p_title, '') ~* E'(^|\\m)(founder|co-founder|owner|ceo|cto|cmo|cfo|coo|cro|cio|chro|chief\\s+[^ ]+\\s+officer|chief|president|managing\\s+(director|partner)|partner|general\\s+partner|gp|vp|vice\\s+president|svp|evp|head\\s+of|director)(\\M|$)'
    AND COALESCE(p_title, '') !~* E'\\m(executive\\s+assistant|assistant\\s+to|founder\\s+experience|founder''?s\\s+office)\\M';
$_$;


ALTER FUNCTION "public"."signal_person_title_is_senior"("p_title" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."signal_person_url_is_valid"("p_url" "text") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE PARALLEL SAFE
    AS $_$
  SELECT COALESCE(p_url, '') ~* E'^https://([a-z]{2,3}\\.)?linkedin\\.com/in/[^/?#]+/?$';
$_$;


ALTER FUNCTION "public"."signal_person_url_is_valid"("p_url" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."signal_revenue_band"("p_range" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE PARALLEL SAFE
    AS $_$
  SELECT CASE
    WHEN NULLIF(btrim(COALESCE(p_range, '')), '') IS NULL THEN NULL
    WHEN lower(btrim(p_range)) IN ('unknown', 'n/a', 'none') THEN NULL
    WHEN lower(btrim(p_range)) = '$1 - $1m' THEN '$500k - $1m'
    ELSE lower(btrim(p_range))
  END;
$_$;


ALTER FUNCTION "public"."signal_revenue_band"("p_range" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."signal_revenue_band"("p_range" "text") IS 'Normalizes a revenue band for comparison (case/whitespace, legacy "$1 - $1M" → "$500k - $1M"). Vocabulary is the provider''s own; NULL when unknown.';



CREATE OR REPLACE FUNCTION "public"."signal_revenue_rank"("p_range" "text") RETURNS smallint
    LANGUAGE "sql" IMMUTABLE PARALLEL SAFE
    AS $_$
  SELECT CASE public.signal_revenue_band(p_range)
    WHEN 'below $500k'   THEN 1
    WHEN '$500k - $1m'   THEN 2
    WHEN '$1m - $5m'     THEN 3
    WHEN '$5m - $10m'    THEN 4
    WHEN '$10m - $20m'   THEN 5
    WHEN '$20m - $50m'   THEN 6
    WHEN 'above $50m'    THEN 7
    WHEN '$50m - $100m'  THEN 8
    WHEN '$100m - $250m' THEN 9
    WHEN '$250m - $500m' THEN 10
    WHEN '$500m - $1b'   THEN 11
    WHEN '$1b - $2.5b'   THEN 12
    WHEN '$2.5b - $5b'   THEN 13
    WHEN 'over $5b'      THEN 14
    ELSE NULL
  END::smallint;
$_$;


ALTER FUNCTION "public"."signal_revenue_rank"("p_range" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."signal_revenue_rank"("p_range" "text") IS 'Sort ordinal for a MoltSets revenue band (1 = smallest). Normalizes through signal_revenue_band first; NULL when unknown.';



CREATE OR REPLACE FUNCTION "public"."signal_seniority_rank"("p_title" "text") RETURNS integer
    LANGUAGE "sql" IMMUTABLE PARALLEL SAFE
    AS $$
  SELECT CASE
    WHEN COALESCE(btrim(p_title), '') = '' THEN 0
    WHEN lower(p_title) ~ '\m(founder|co-?founder|owner|ceo|chief executive|president|managing director|managing partner)\M' THEN 100
    WHEN lower(p_title) ~ '(\mc[tfdmiore]o\M|\mchief\M)' THEN 90
    WHEN lower(p_title) ~ '\m(partner|general partner|gp)\M' THEN 80
    WHEN lower(p_title) ~ '\m(vp|vice president|svp|evp)\M' THEN 70
    WHEN lower(p_title) ~ '(\mhead of\M|\mhead\M|\mdirector\M)' THEN 60
    ELSE 0
  END;
$$;


ALTER FUNCTION "public"."signal_seniority_rank"("p_title" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."signal_seniority_rank"("p_title" "text") IS 'Title -> 0-100 seniority rank (100 founder/CEO, 90 chief, 80 partner, 70 VP, 60 head/director). SQL port of seniorityRank() in the public-linkedin-signals-ingest edge function.';



CREATE OR REPLACE FUNCTION "public"."smart_list_contact_page"("p_list_id" "uuid", "p_page" integer DEFAULT 1, "p_page_size" integer DEFAULT 50, "p_sort" "text" DEFAULT 'created_at'::"text", "p_direction" "text" DEFAULT 'desc'::"text") RETURNS SETOF "public"."crm_contacts"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_org uuid; v_result jsonb;
BEGIN
  SELECT organization_id INTO v_org FROM public.lead_lists WHERE id=p_list_id AND is_smart;
  IF v_org IS NULL THEN RAISE EXCEPTION 'Smart segment not found' USING ERRCODE='P0002'; END IF;
  v_result:=public.smart_segment_contact_page(v_org,p_list_id,'{}'::jsonb,'{}'::jsonb,NULL,p_page,p_page_size,p_sort,p_direction);
  RETURN QUERY SELECT * FROM jsonb_populate_recordset(NULL::public.crm_contacts,v_result->'contacts');
END;
$$;


ALTER FUNCTION "public"."smart_list_contact_page"("p_list_id" "uuid", "p_page" integer, "p_page_size" integer, "p_sort" "text", "p_direction" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."smart_list_eligible_contact_ids"("p_list_id" "uuid") RETURNS SETOF "uuid"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_org uuid; v_criteria jsonb;
BEGIN
  SELECT organization_id,filter_criteria INTO v_org,v_criteria FROM public.lead_lists WHERE id=p_list_id AND is_smart;
  IF v_org IS NULL THEN RAISE EXCEPTION 'Smart segment not found' USING ERRCODE='P0002'; END IF;
  PERFORM public.assert_smart_segment_org_access(v_org);
  RETURN QUERY SELECT public.smart_list_eligible_contacts_for_criteria(v_org,coalesce(v_criteria,'{}'::jsonb));
END;
$$;


ALTER FUNCTION "public"."smart_list_eligible_contact_ids"("p_list_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."smart_list_eligible_contacts_for_criteria"("p_org_id" "uuid", "p_criteria" "jsonb", "p_candidate_ids" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS SETOF "uuid"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  PERFORM public.assert_smart_segment_org_access(p_org_id);
  RETURN QUERY SELECT public.smart_list_eligible_contacts_for_criteria_internal(p_org_id,p_criteria,p_candidate_ids);
END;
$$;


ALTER FUNCTION "public"."smart_list_eligible_contacts_for_criteria"("p_org_id" "uuid", "p_criteria" "jsonb", "p_candidate_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."smart_list_eligible_contacts_for_criteria_internal"("p_org_id" "uuid", "p_criteria" "jsonb", "p_candidate_ids" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS SETOF "uuid"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE v_where text;
BEGIN
  IF p_criteria ? 'rule_group' THEN
    v_where := public.smart_segment_group_to_sql(p_criteria->'rule_group');
    RETURN QUERY EXECUTE format('SELECT c.id FROM public.crm_contacts c WHERE c.organization_id=$1 AND ($2 IS NULL OR c.id=ANY($2)) AND (%s)',v_where) USING p_org_id,p_candidate_ids;
  ELSE
    RETURN QUERY SELECT public.smart_list_eligible_contacts_for_flat_criteria(p_org_id,p_criteria,p_candidate_ids);
  END IF;
END;
$_$;


ALTER FUNCTION "public"."smart_list_eligible_contacts_for_criteria_internal"("p_org_id" "uuid", "p_criteria" "jsonb", "p_candidate_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."smart_list_eligible_contacts_for_flat_criteria"("p_org_id" "uuid", "p_criteria" "jsonb", "p_candidate_ids" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS SETOF "uuid"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT c.id
  FROM public.crm_contacts c
  WHERE c.organization_id = p_org_id
    AND (p_candidate_ids IS NULL OR c.id = ANY(p_candidate_ids))
    AND c.id IN (SELECT public.smart_list_eligible_contacts_for_flat_criteria_legacy(
      p_org_id,
      p_criteria - 'company_sizes' - 'min_employee_count' - 'max_employee_count',
      p_candidate_ids
    ))
    AND public.crm_company_size_matches(
      c.company_employee_count, c.company_employee_range,
      c.enrichment_data->'company'->>'size',
      CASE WHEN jsonb_typeof(p_criteria->'company_sizes') = 'array' AND jsonb_array_length(p_criteria->'company_sizes') > 0
        THEN ARRAY(SELECT lower(jsonb_array_elements_text(p_criteria->'company_sizes'))) END)
    AND (NULLIF(p_criteria->>'min_employee_count','') IS NULL OR c.company_employee_count >= (p_criteria->>'min_employee_count')::integer)
    AND (NULLIF(p_criteria->>'max_employee_count','') IS NULL OR c.company_employee_count <= (p_criteria->>'max_employee_count')::integer);
$$;


ALTER FUNCTION "public"."smart_list_eligible_contacts_for_flat_criteria"("p_org_id" "uuid", "p_criteria" "jsonb", "p_candidate_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."smart_list_eligible_contacts_for_flat_criteria_legacy"("p_org_id" "uuid", "p_criteria" "jsonb", "p_candidate_ids" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS SETOF "uuid"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_source TEXT; v_status TEXT; v_tags TEXT[];
  v_min_score INTEGER; v_max_score INTEGER;
  v_pipeline_id UUID; v_stage_id UUID; v_owner_user_id UUID;
  v_created_days_ago INTEGER; v_activity_days_ago INTEGER;
  v_has_email BOOLEAN; v_has_linkedin BOOLEAN;
  v_icp_product_id UUID; v_min_icp_score INTEGER; v_max_icp_score INTEGER;
  v_min_dm_score INTEGER; v_max_dm_score INTEGER;
  v_industries TEXT[]; v_company_sizes TEXT[]; v_seniorities TEXT[]; v_departments TEXT[];
  v_countries TEXT[]; v_cities TEXT[]; v_technologies TEXT[];
  v_is_b2b BOOLEAN; v_revenue_models TEXT[];
  v_has_outbound_motion BOOLEAN; v_hiring_sales_roles BOOLEAN; v_runs_ads BOOLEAN;
  v_detected_technologies TEXT[]; v_detected_tech_all BOOLEAN; v_excluded_technologies TEXT[];
  v_custom_questions JSONB; v_custom_fields JSONB;
  v_email_verified BOOLEAN; v_email_quality TEXT[]; v_min_email_confidence INTEGER; v_email_type TEXT;
  v_has_enrichment_data BOOLEAN; v_has_notion_url BOOLEAN; v_seg_firewall TEXT; v_ai_analysis_status TEXT;
  v_signal_types TEXT[]; v_signal_subscription_id TEXT; v_min_discovery_score INTEGER; v_signal_max_age_days INTEGER;
BEGIN
  IF p_criteria IS NULL THEN RETURN; END IF;

  v_source := NULLIF(p_criteria->>'source', '');
  v_status := NULLIF(p_criteria->>'status', '');
  v_min_score := NULLIF(p_criteria->>'min_score', '')::INTEGER;
  v_max_score := NULLIF(p_criteria->>'max_score', '')::INTEGER;
  v_pipeline_id := NULLIF(p_criteria->>'pipeline_id', '')::UUID;
  v_stage_id := NULLIF(p_criteria->>'stage_id', '')::UUID;
  v_owner_user_id := NULLIF(p_criteria->>'owner_user_id', '')::UUID;
  v_created_days_ago := NULLIF(p_criteria->>'created_days_ago', '')::INTEGER;
  v_activity_days_ago := NULLIF(p_criteria->>'activity_days_ago', '')::INTEGER;
  v_has_email := NULLIF(p_criteria->>'has_email', '')::BOOLEAN;
  v_has_linkedin := NULLIF(p_criteria->>'has_linkedin', '')::BOOLEAN;
  v_icp_product_id := NULLIF(p_criteria->>'icp_product_id', '')::UUID;
  v_min_icp_score := NULLIF(p_criteria->>'min_icp_score', '')::INTEGER;
  v_max_icp_score := NULLIF(p_criteria->>'max_icp_score', '')::INTEGER;
  v_min_dm_score := NULLIF(p_criteria->>'min_dm_score', '')::INTEGER;
  v_max_dm_score := NULLIF(p_criteria->>'max_dm_score', '')::INTEGER;
  v_is_b2b := NULLIF(p_criteria->>'is_b2b', '')::BOOLEAN;
  v_has_outbound_motion := NULLIF(p_criteria->>'has_outbound_motion', '')::BOOLEAN;
  v_hiring_sales_roles := NULLIF(p_criteria->>'hiring_sales_roles', '')::BOOLEAN;
  v_runs_ads := NULLIF(p_criteria->>'runs_ads', '')::BOOLEAN;
  v_detected_tech_all := NULLIF(p_criteria->>'detected_tech_match_all', '')::BOOLEAN;
  v_email_verified := NULLIF(p_criteria->>'email_verified', '')::BOOLEAN;
  v_min_email_confidence := NULLIF(p_criteria->>'min_email_confidence', '')::INTEGER;
  v_email_type := NULLIF(p_criteria->>'email_type', '');
  v_has_enrichment_data := NULLIF(p_criteria->>'has_enrichment_data', '')::BOOLEAN;
  v_has_notion_url := NULLIF(p_criteria->>'has_notion_url', '')::BOOLEAN;
  v_seg_firewall := NULLIF(p_criteria->>'seg_firewall', '');
  v_ai_analysis_status := NULLIF(p_criteria->>'ai_analysis_status', '');
  v_signal_subscription_id := NULLIF(p_criteria->>'signal_subscription_id', '');
  v_min_discovery_score := NULLIF(p_criteria->>'min_discovery_score', '')::INTEGER;
  v_signal_max_age_days := NULLIF(p_criteria->>'signal_max_age_days', '')::INTEGER;

  IF v_ai_analysis_status IS NOT NULL
    AND v_ai_analysis_status NOT IN ('not_analyzed','analyzing','analyzed','failed','no_data')
  THEN v_ai_analysis_status := NULL; END IF;

  IF jsonb_typeof(p_criteria->'tags') = 'array' AND jsonb_array_length(p_criteria->'tags') > 0 THEN
    SELECT ARRAY(SELECT jsonb_array_elements_text(p_criteria->'tags')) INTO v_tags;
  END IF;
  IF jsonb_typeof(p_criteria->'industries') = 'array' AND jsonb_array_length(p_criteria->'industries') > 0 THEN
    SELECT ARRAY(SELECT LOWER(jsonb_array_elements_text(p_criteria->'industries'))) INTO v_industries;
  END IF;
  IF jsonb_typeof(p_criteria->'company_sizes') = 'array' AND jsonb_array_length(p_criteria->'company_sizes') > 0 THEN
    SELECT ARRAY(SELECT LOWER(jsonb_array_elements_text(p_criteria->'company_sizes'))) INTO v_company_sizes;
  END IF;
  IF jsonb_typeof(p_criteria->'seniorities') = 'array' AND jsonb_array_length(p_criteria->'seniorities') > 0 THEN
    SELECT ARRAY(SELECT LOWER(jsonb_array_elements_text(p_criteria->'seniorities'))) INTO v_seniorities;
  END IF;
  IF jsonb_typeof(p_criteria->'departments') = 'array' AND jsonb_array_length(p_criteria->'departments') > 0 THEN
    SELECT ARRAY(SELECT LOWER(jsonb_array_elements_text(p_criteria->'departments'))) INTO v_departments;
  END IF;
  IF jsonb_typeof(p_criteria->'countries') = 'array' AND jsonb_array_length(p_criteria->'countries') > 0 THEN
    SELECT ARRAY(SELECT LOWER(jsonb_array_elements_text(p_criteria->'countries'))) INTO v_countries;
  END IF;
  IF jsonb_typeof(p_criteria->'cities') = 'array' AND jsonb_array_length(p_criteria->'cities') > 0 THEN
    SELECT ARRAY(SELECT LOWER(jsonb_array_elements_text(p_criteria->'cities'))) INTO v_cities;
  END IF;
  IF jsonb_typeof(p_criteria->'technologies') = 'array' AND jsonb_array_length(p_criteria->'technologies') > 0 THEN
    SELECT ARRAY(SELECT jsonb_array_elements_text(p_criteria->'technologies')) INTO v_technologies;
  END IF;
  IF jsonb_typeof(p_criteria->'revenue_models') = 'array' AND jsonb_array_length(p_criteria->'revenue_models') > 0 THEN
    SELECT ARRAY(SELECT LOWER(jsonb_array_elements_text(p_criteria->'revenue_models'))) INTO v_revenue_models;
  END IF;
  IF jsonb_typeof(p_criteria->'detected_technologies') = 'array' AND jsonb_array_length(p_criteria->'detected_technologies') > 0 THEN
    SELECT ARRAY(SELECT jsonb_array_elements_text(p_criteria->'detected_technologies')) INTO v_detected_technologies;
  END IF;
  IF jsonb_typeof(p_criteria->'excluded_technologies') = 'array' AND jsonb_array_length(p_criteria->'excluded_technologies') > 0 THEN
    SELECT ARRAY(SELECT jsonb_array_elements_text(p_criteria->'excluded_technologies')) INTO v_excluded_technologies;
  END IF;
  IF jsonb_typeof(p_criteria->'email_quality') = 'array' AND jsonb_array_length(p_criteria->'email_quality') > 0 THEN
    SELECT ARRAY(SELECT jsonb_array_elements_text(p_criteria->'email_quality')) INTO v_email_quality;
  END IF;
  IF jsonb_typeof(p_criteria->'signal_types') = 'array' AND jsonb_array_length(p_criteria->'signal_types') > 0 THEN
    SELECT ARRAY(SELECT jsonb_array_elements_text(p_criteria->'signal_types')) INTO v_signal_types;
  END IF;
  IF jsonb_typeof(p_criteria->'custom_questions') = 'array' AND jsonb_array_length(p_criteria->'custom_questions') > 0 THEN
    v_custom_questions := p_criteria->'custom_questions';
  END IF;
  IF jsonb_typeof(p_criteria->'custom_field_conditions') = 'array' AND jsonb_array_length(p_criteria->'custom_field_conditions') > 0 THEN
    v_custom_fields := p_criteria->'custom_field_conditions';
  END IF;

  RETURN QUERY
  SELECT c.id
  FROM public.crm_contacts c
  WHERE c.organization_id = p_org_id
    -- Candidate pushdown: restricts the scan when the caller already knows the
    -- universe (enrollment filter). NULL = evaluate the whole org, as before.
    AND (p_candidate_ids IS NULL OR c.id = ANY(p_candidate_ids))
    AND (v_source IS NULL OR c.source = v_source)
    AND (v_status IS NULL OR c.status = v_status)
    AND (v_tags IS NULL OR c.tags && v_tags)
    AND (v_min_score IS NULL OR c.lead_score >= v_min_score)
    AND (v_max_score IS NULL OR c.lead_score <= v_max_score)
    AND (v_pipeline_id IS NULL OR c.pipeline_id = v_pipeline_id)
    AND (v_stage_id IS NULL OR c.stage_id = v_stage_id)
    AND (v_owner_user_id IS NULL OR c.owner_user_id = v_owner_user_id)
    AND (v_created_days_ago IS NULL OR c.created_at >= (NOW() - (v_created_days_ago || ' days')::INTERVAL))
    AND (v_activity_days_ago IS NULL OR c.last_activity_at >= (NOW() - (v_activity_days_ago || ' days')::INTERVAL))
    AND (v_has_email IS NULL
      OR (v_has_email = TRUE AND c.primary_email IS NOT NULL AND c.primary_email != '')
      OR (v_has_email = FALSE AND (c.primary_email IS NULL OR c.primary_email = '')))
    AND (v_has_linkedin IS NULL
      OR (v_has_linkedin = TRUE AND c.primary_linkedin_url IS NOT NULL AND c.primary_linkedin_url != '')
      OR (v_has_linkedin = FALSE AND (c.primary_linkedin_url IS NULL OR c.primary_linkedin_url = '')))
    AND (v_icp_product_id IS NULL OR EXISTS (
      SELECT 1 FROM public.contact_product_scores cps
      WHERE cps.contact_id = c.id
        AND cps.product_id = v_icp_product_id
        AND (v_min_icp_score IS NULL OR cps.icp_score >= v_min_icp_score)
        AND (v_max_icp_score IS NULL OR cps.icp_score <= v_max_icp_score)
        AND (v_min_dm_score IS NULL OR cps.decision_maker_score >= v_min_dm_score)
        AND (v_max_dm_score IS NULL OR cps.decision_maker_score <= v_max_dm_score)
    ))
    AND (v_industries IS NULL OR LOWER(c.enrichment_data->'company'->>'industry') = ANY(v_industries))
    AND (v_company_sizes IS NULL OR LOWER(c.enrichment_data->'company'->>'size') = ANY(v_company_sizes))
    AND (v_seniorities IS NULL OR LOWER(c.enrichment_data->>'seniority') = ANY(v_seniorities))
    AND (v_departments IS NULL OR LOWER(c.enrichment_data->>'department') = ANY(v_departments))
    AND (v_countries IS NULL OR LOWER(c.country) = ANY(v_countries))
    AND (v_cities IS NULL OR LOWER(c.city) = ANY(v_cities))
    AND (v_technologies IS NULL OR (c.enrichment_data->'company'->'technologies') @> to_jsonb(v_technologies))
    AND (v_is_b2b IS NULL OR (c.enrichment_data->>'is_b2b')::BOOLEAN = v_is_b2b)
    AND (v_revenue_models IS NULL OR LOWER(c.enrichment_data->>'revenue_model') = ANY(v_revenue_models))
    AND (v_has_outbound_motion IS NULL OR (c.enrichment_data->>'has_outbound_motion')::BOOLEAN = v_has_outbound_motion)
    AND (v_hiring_sales_roles IS NULL OR (c.enrichment_data->>'hiring_sales_roles')::BOOLEAN = v_hiring_sales_roles)
    AND (v_runs_ads IS NULL OR (c.enrichment_data->'detected_technologies'->>'runs_paid_ads')::BOOLEAN = v_runs_ads)
    AND (v_detected_technologies IS NULL OR (
      CASE WHEN v_detected_tech_all
        THEN (c.enrichment_data->'detected_technologies'->'all') ?& v_detected_technologies
        ELSE (c.enrichment_data->'detected_technologies'->'all') ?| v_detected_technologies
      END))
    AND (v_excluded_technologies IS NULL OR NOT (COALESCE(c.enrichment_data->'detected_technologies'->'all', '[]'::jsonb) ?| v_excluded_technologies))
    AND (v_custom_questions IS NULL OR NOT EXISTS (
      SELECT 1 FROM jsonb_array_elements(v_custom_questions) cond
      WHERE NOT EXISTS (
        SELECT 1 FROM jsonb_array_elements(COALESCE(c.enrichment_data->'custom_analysis', '[]'::jsonb)) e
        WHERE e->>'question' = cond->>'question'
          AND COALESCE(TRIM(e->>'answer'), '') <> ''
          AND (NULLIF(cond->>'minScore','') IS NULL OR ((e->>'score') ~ '^-?[0-9]+(\.[0-9]+)?$' AND (e->>'score')::NUMERIC >= (cond->>'minScore')::NUMERIC))
      )
    ))
    AND (v_custom_fields IS NULL OR NOT EXISTS (
      SELECT 1 FROM jsonb_array_elements(v_custom_fields) cond
      WHERE NOT (
        CASE cond->>'operator'
          WHEN 'has_value' THEN c.custom_fields ? (cond->>'fieldKey') AND c.custom_fields->>(cond->>'fieldKey') IS DISTINCT FROM ''
          WHEN 'is_empty' THEN (NOT (c.custom_fields ? (cond->>'fieldKey'))) OR c.custom_fields->>(cond->>'fieldKey') = ''
          WHEN 'equals' THEN c.custom_fields @> jsonb_build_object(cond->>'fieldKey', cond->>'value')
          WHEN 'contains' THEN c.custom_fields ? (cond->>'fieldKey') AND c.custom_fields->>(cond->>'fieldKey') ILIKE '%' || (cond->>'value') || '%'
          ELSE TRUE
        END
      )
    ))
    AND (v_email_verified IS NULL OR (c.enrichment_data->>'emailVerified')::BOOLEAN = v_email_verified)
    AND (v_email_quality IS NULL OR (
      ('clean' = ANY(v_email_quality) AND c.email_verified_at IS NOT NULL AND c.email_verification_status = 'valid'
        AND COALESCE(c.email_is_catch_all,false)=false AND COALESCE(c.email_is_role,false)=false AND COALESCE(c.email_is_free,false)=false
        AND COALESCE(c.email_is_disposable,false)=false AND COALESCE(c.email_is_spamtrap,false)=false)
      OR ('risky' = ANY(v_email_quality) AND c.email_verified_at IS NOT NULL AND
        (c.email_verification_status='catch_all' OR c.email_is_catch_all=true OR c.email_is_role=true OR c.email_is_free=true)
        AND COALESCE(c.email_is_disposable,false)=false AND COALESCE(c.email_is_spamtrap,false)=false)
      OR ('failed' = ANY(v_email_quality) AND c.email_verified_at IS NOT NULL AND
        (c.email_verification_status IN ('invalid','disposable','spamtrap','disabled','role_only') OR c.email_is_disposable=true OR c.email_is_spamtrap=true))
      OR ('unverified' = ANY(v_email_quality) AND c.email_verified_at IS NULL)
    ))
    AND (v_min_email_confidence IS NULL OR (c.enrichment_data->>'emailConfidence')::INTEGER >= v_min_email_confidence)
    AND (v_email_type IS NULL OR c.email_type = v_email_type)
    AND (v_has_enrichment_data IS NULL
      OR (v_has_enrichment_data = TRUE AND c.enrichment_data IS NOT NULL AND c.enrichment_data != '{}'::JSONB)
      OR (v_has_enrichment_data = FALSE AND (c.enrichment_data IS NULL OR c.enrichment_data = '{}'::JSONB)))
    AND (v_has_notion_url IS NULL
      OR (v_has_notion_url = TRUE AND c.notion_preview_url IS NOT NULL AND c.notion_preview_url != '')
      OR (v_has_notion_url = FALSE AND (c.notion_preview_url IS NULL OR c.notion_preview_url = '')))
    AND (v_seg_firewall IS NULL
      OR (v_seg_firewall = 'behind' AND c.seg_provider IS NOT NULL)
      OR (v_seg_firewall = 'clear' AND c.seg_provider IS NULL AND c.seg_checked_at IS NOT NULL)
      OR (v_seg_firewall = 'unchecked' AND c.seg_checked_at IS NULL))
    AND (v_ai_analysis_status IS NULL
      OR (v_ai_analysis_status = 'no_data' AND (
            c.ai_analysis_status = 'failed'
            OR ((c.company_website IS NULL OR c.company_website = '')
              AND (c.primary_linkedin_url IS NULL OR c.primary_linkedin_url = ''))))
      OR (v_ai_analysis_status != 'no_data' AND c.ai_analysis_status = v_ai_analysis_status))
    AND (v_signal_types IS NULL OR (c.discovery_metadata->>'signal_type') = ANY(v_signal_types))
    AND (v_signal_subscription_id IS NULL OR c.discovery_metadata->>'signal_subscription_id' = v_signal_subscription_id)
    AND (v_min_discovery_score IS NULL OR c.discovery_score >= v_min_discovery_score)
    AND (v_signal_max_age_days IS NULL
      OR (c.discovery_metadata->>'signal_date')::DATE >= (CURRENT_DATE - v_signal_max_age_days));
END;
$_$;


ALTER FUNCTION "public"."smart_list_eligible_contacts_for_flat_criteria_legacy"("p_org_id" "uuid", "p_criteria" "jsonb", "p_candidate_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."smart_list_preview_count"("p_org_id" "uuid", "p_criteria" "jsonb") RETURNS integer
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE v_count integer;
BEGIN
  PERFORM public.assert_smart_segment_org_access(p_org_id);
  EXECUTE format('SELECT count(*)::integer FROM public.crm_contacts c WHERE c.organization_id=$1 AND (%s)',public.smart_segment_criteria_to_sql(p_criteria))
  INTO v_count USING p_org_id;
  RETURN v_count;
END;
$_$;


ALTER FUNCTION "public"."smart_list_preview_count"("p_org_id" "uuid", "p_criteria" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."smart_segment_contact_page"("p_org_id" "uuid", "p_list_id" "uuid" DEFAULT NULL::"uuid", "p_criteria" "jsonb" DEFAULT '{}'::"jsonb", "p_view_criteria" "jsonb" DEFAULT '{}'::"jsonb", "p_search" "text" DEFAULT NULL::"text", "p_page" integer DEFAULT 1, "p_page_size" integer DEFAULT 50, "p_sort" "text" DEFAULT 'created_at'::"text", "p_direction" "text" DEFAULT 'desc'::"text", "p_ids_only" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_org uuid; v_criteria jsonb; v_sort text; v_direction text; v_result jsonb;
  v_base_predicate text; v_view_predicate text;
  v_page integer := greatest(coalesce(p_page,1),1);
  v_size integer := least(greatest(coalesce(p_page_size,50),1),1000);
BEGIN
  PERFORM public.assert_smart_segment_org_access(p_org_id);
  IF p_list_id IS NOT NULL THEN
    SELECT organization_id,filter_criteria INTO v_org,v_criteria FROM public.lead_lists
    WHERE id=p_list_id AND organization_id=p_org_id AND is_smart;
    IF v_org IS NULL THEN RAISE EXCEPTION 'Smart segment not found' USING ERRCODE='P0002'; END IF;
  ELSE v_org:=p_org_id; v_criteria:=p_criteria; END IF;
  v_sort:=CASE p_sort WHEN 'display_name' THEN 'display_name' WHEN 'lead_score' THEN 'lead_score'
    WHEN 'last_activity_at' THEN 'last_activity_at' ELSE 'created_at' END;
  v_direction:=CASE lower(p_direction) WHEN 'asc' THEN 'ASC' ELSE 'DESC' END;
  v_base_predicate:=public.smart_segment_criteria_to_sql(coalesce(v_criteria,'{}'::jsonb));
  v_view_predicate:=public.smart_segment_criteria_to_sql(coalesce(p_view_criteria,'{}'::jsonb));
  -- Both groups stay intact and are independently ANDed. Let the planner use
  -- indexes for the count and page separately; never sort entire contact rows
  -- or build a candidate array containing the full audience.
  EXECUTE format($query$
    WITH matching AS NOT MATERIALIZED (
      SELECT c.id,c.%1$I AS sort_value FROM public.crm_contacts c
      WHERE c.organization_id=$1 AND (%3$s) AND (%4$s)
        AND (nullif(trim($2),'') IS NULL OR strpos(lower(concat_ws(' ',c.display_name,c.first_name,c.last_name,c.primary_email,c.company,c.job_title)),lower(trim($2)))>0)
    ), page AS MATERIALIZED (
      SELECT m.id,m.sort_value FROM matching m
      ORDER BY m.sort_value %2$s NULLS LAST,m.id ASC LIMIT $3 OFFSET $4
    )
    SELECT jsonb_build_object(
      'contacts',CASE WHEN $5 THEN '[]'::jsonb ELSE coalesce((SELECT jsonb_agg(to_jsonb(c) ORDER BY p.sort_value %2$s NULLS LAST,p.id ASC) FROM page p JOIN public.crm_contacts c ON c.id=p.id AND c.organization_id=$1),'[]'::jsonb) END,
      'ids',coalesce((SELECT jsonb_agg(p.id ORDER BY p.sort_value %2$s NULLS LAST,p.id ASC) FROM page p),'[]'::jsonb),
      'total',(SELECT count(*) FROM matching),'page',$6,'page_size',$3
    )
  $query$,v_sort,v_direction,v_base_predicate,v_view_predicate)
  INTO v_result USING v_org,p_search,v_size,(v_page::bigint-1)*v_size,p_ids_only,v_page;
  RETURN v_result;
END;
$_$;


ALTER FUNCTION "public"."smart_segment_contact_page"("p_org_id" "uuid", "p_list_id" "uuid", "p_criteria" "jsonb", "p_view_criteria" "jsonb", "p_search" "text", "p_page" integer, "p_page_size" integer, "p_sort" "text", "p_direction" "text", "p_ids_only" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."smart_segment_criteria_to_sql"("p_criteria" "jsonb") RETURNS "text"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $_$
BEGIN
  IF p_criteria IS NULL THEN RETURN 'FALSE'; END IF;
  IF p_criteria='{}'::jsonb THEN RETURN 'TRUE'; END IF;
  IF p_criteria ? 'rule_group' THEN
    RETURN public.smart_segment_group_to_sql(p_criteria->'rule_group');
  END IF;
  -- Some deployments use durable signal_activity_log membership and others
  -- use discovery metadata. Keep that installed canonical contract intact.
  IF NULLIF(p_criteria->>'signal_subscription_id','') IS NOT NULL THEN
    RETURN format('c.id IN (SELECT public.smart_list_eligible_contacts_for_criteria_internal($1,%L::jsonb))',p_criteria);
  END IF;
  RETURN public.smart_segment_flat_criteria_to_sql(p_criteria);
END;
$_$;


ALTER FUNCTION "public"."smart_segment_criteria_to_sql"("p_criteria" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."smart_segment_flat_criteria_to_sql"("p_criteria" "jsonb") RETURNS "text"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_min_employee_count integer; v_max_employee_count integer;
  v_source TEXT; v_status TEXT; v_tags TEXT[];
  v_min_score INTEGER; v_max_score INTEGER;
  v_pipeline_id UUID; v_stage_id UUID; v_owner_user_id UUID;
  v_created_days_ago INTEGER; v_activity_days_ago INTEGER;
  v_has_email BOOLEAN; v_has_linkedin BOOLEAN;
  v_icp_product_id UUID; v_min_icp_score INTEGER; v_max_icp_score INTEGER;
  v_min_dm_score INTEGER; v_max_dm_score INTEGER;
  v_industries TEXT[]; v_company_sizes TEXT[]; v_seniorities TEXT[]; v_departments TEXT[];
  v_countries TEXT[]; v_cities TEXT[]; v_technologies TEXT[];
  v_is_b2b BOOLEAN; v_revenue_models TEXT[];
  v_has_outbound_motion BOOLEAN; v_hiring_sales_roles BOOLEAN; v_runs_ads BOOLEAN;
  v_detected_technologies TEXT[]; v_detected_tech_all BOOLEAN; v_excluded_technologies TEXT[];
  v_custom_questions JSONB; v_custom_fields JSONB;
  v_email_verified BOOLEAN; v_email_quality TEXT[]; v_min_email_confidence INTEGER; v_email_type TEXT;
  v_has_enrichment_data BOOLEAN; v_has_notion_url BOOLEAN; v_seg_firewall TEXT; v_ai_analysis_status TEXT;
  v_signal_types TEXT[]; v_signal_subscription_id TEXT; v_min_discovery_score INTEGER; v_signal_max_age_days INTEGER;
BEGIN
  IF p_criteria IS NULL THEN RETURN 'FALSE'; END IF;

  v_min_employee_count := NULLIF(p_criteria->>'min_employee_count','')::integer;
  v_max_employee_count := NULLIF(p_criteria->>'max_employee_count','')::integer;
  v_source := NULLIF(p_criteria->>'source', '');
  v_status := NULLIF(p_criteria->>'status', '');
  v_min_score := NULLIF(p_criteria->>'min_score', '')::INTEGER;
  v_max_score := NULLIF(p_criteria->>'max_score', '')::INTEGER;
  v_pipeline_id := NULLIF(p_criteria->>'pipeline_id', '')::UUID;
  v_stage_id := NULLIF(p_criteria->>'stage_id', '')::UUID;
  v_owner_user_id := NULLIF(p_criteria->>'owner_user_id', '')::UUID;
  v_created_days_ago := NULLIF(p_criteria->>'created_days_ago', '')::INTEGER;
  v_activity_days_ago := NULLIF(p_criteria->>'activity_days_ago', '')::INTEGER;
  v_has_email := NULLIF(p_criteria->>'has_email', '')::BOOLEAN;
  v_has_linkedin := NULLIF(p_criteria->>'has_linkedin', '')::BOOLEAN;
  v_icp_product_id := NULLIF(p_criteria->>'icp_product_id', '')::UUID;
  v_min_icp_score := NULLIF(p_criteria->>'min_icp_score', '')::INTEGER;
  v_max_icp_score := NULLIF(p_criteria->>'max_icp_score', '')::INTEGER;
  v_min_dm_score := NULLIF(p_criteria->>'min_dm_score', '')::INTEGER;
  v_max_dm_score := NULLIF(p_criteria->>'max_dm_score', '')::INTEGER;
  v_is_b2b := NULLIF(p_criteria->>'is_b2b', '')::BOOLEAN;
  v_has_outbound_motion := NULLIF(p_criteria->>'has_outbound_motion', '')::BOOLEAN;
  v_hiring_sales_roles := NULLIF(p_criteria->>'hiring_sales_roles', '')::BOOLEAN;
  v_runs_ads := NULLIF(p_criteria->>'runs_ads', '')::BOOLEAN;
  v_detected_tech_all := NULLIF(p_criteria->>'detected_tech_match_all', '')::BOOLEAN;
  v_email_verified := NULLIF(p_criteria->>'email_verified', '')::BOOLEAN;
  v_min_email_confidence := NULLIF(p_criteria->>'min_email_confidence', '')::INTEGER;
  v_email_type := NULLIF(p_criteria->>'email_type', '');
  v_has_enrichment_data := NULLIF(p_criteria->>'has_enrichment_data', '')::BOOLEAN;
  v_has_notion_url := NULLIF(p_criteria->>'has_notion_url', '')::BOOLEAN;
  v_seg_firewall := NULLIF(p_criteria->>'seg_firewall', '');
  v_ai_analysis_status := NULLIF(p_criteria->>'ai_analysis_status', '');
  v_signal_subscription_id := NULLIF(p_criteria->>'signal_subscription_id', '');
  v_min_discovery_score := NULLIF(p_criteria->>'min_discovery_score', '')::INTEGER;
  v_signal_max_age_days := NULLIF(p_criteria->>'signal_max_age_days', '')::INTEGER;

  IF v_ai_analysis_status IS NOT NULL
    AND v_ai_analysis_status NOT IN ('not_analyzed','analyzing','analyzed','failed','no_data')
  THEN v_ai_analysis_status := NULL; END IF;

  IF jsonb_typeof(p_criteria->'tags') = 'array' AND jsonb_array_length(p_criteria->'tags') > 0 THEN
    SELECT ARRAY(SELECT jsonb_array_elements_text(p_criteria->'tags')) INTO v_tags;
  END IF;
  IF jsonb_typeof(p_criteria->'industries') = 'array' AND jsonb_array_length(p_criteria->'industries') > 0 THEN
    SELECT ARRAY(SELECT LOWER(jsonb_array_elements_text(p_criteria->'industries'))) INTO v_industries;
  END IF;
  IF jsonb_typeof(p_criteria->'company_sizes') = 'array' AND jsonb_array_length(p_criteria->'company_sizes') > 0 THEN
    SELECT ARRAY(SELECT LOWER(jsonb_array_elements_text(p_criteria->'company_sizes'))) INTO v_company_sizes;
  END IF;
  IF jsonb_typeof(p_criteria->'seniorities') = 'array' AND jsonb_array_length(p_criteria->'seniorities') > 0 THEN
    SELECT ARRAY(SELECT LOWER(jsonb_array_elements_text(p_criteria->'seniorities'))) INTO v_seniorities;
  END IF;
  IF jsonb_typeof(p_criteria->'departments') = 'array' AND jsonb_array_length(p_criteria->'departments') > 0 THEN
    SELECT ARRAY(SELECT LOWER(jsonb_array_elements_text(p_criteria->'departments'))) INTO v_departments;
  END IF;
  IF jsonb_typeof(p_criteria->'countries') = 'array' AND jsonb_array_length(p_criteria->'countries') > 0 THEN
    SELECT ARRAY(SELECT LOWER(jsonb_array_elements_text(p_criteria->'countries'))) INTO v_countries;
  END IF;
  IF jsonb_typeof(p_criteria->'cities') = 'array' AND jsonb_array_length(p_criteria->'cities') > 0 THEN
    SELECT ARRAY(SELECT LOWER(jsonb_array_elements_text(p_criteria->'cities'))) INTO v_cities;
  END IF;
  IF jsonb_typeof(p_criteria->'technologies') = 'array' AND jsonb_array_length(p_criteria->'technologies') > 0 THEN
    SELECT ARRAY(SELECT jsonb_array_elements_text(p_criteria->'technologies')) INTO v_technologies;
  END IF;
  IF jsonb_typeof(p_criteria->'revenue_models') = 'array' AND jsonb_array_length(p_criteria->'revenue_models') > 0 THEN
    SELECT ARRAY(SELECT LOWER(jsonb_array_elements_text(p_criteria->'revenue_models'))) INTO v_revenue_models;
  END IF;
  IF jsonb_typeof(p_criteria->'detected_technologies') = 'array' AND jsonb_array_length(p_criteria->'detected_technologies') > 0 THEN
    SELECT ARRAY(SELECT jsonb_array_elements_text(p_criteria->'detected_technologies')) INTO v_detected_technologies;
  END IF;
  IF jsonb_typeof(p_criteria->'excluded_technologies') = 'array' AND jsonb_array_length(p_criteria->'excluded_technologies') > 0 THEN
    SELECT ARRAY(SELECT jsonb_array_elements_text(p_criteria->'excluded_technologies')) INTO v_excluded_technologies;
  END IF;
  IF jsonb_typeof(p_criteria->'email_quality') = 'array' AND jsonb_array_length(p_criteria->'email_quality') > 0 THEN
    SELECT ARRAY(SELECT jsonb_array_elements_text(p_criteria->'email_quality')) INTO v_email_quality;
  END IF;
  IF jsonb_typeof(p_criteria->'signal_types') = 'array' AND jsonb_array_length(p_criteria->'signal_types') > 0 THEN
    SELECT ARRAY(SELECT jsonb_array_elements_text(p_criteria->'signal_types')) INTO v_signal_types;
  END IF;
  IF jsonb_typeof(p_criteria->'custom_questions') = 'array' AND jsonb_array_length(p_criteria->'custom_questions') > 0 THEN
    v_custom_questions := p_criteria->'custom_questions';
  END IF;
  IF jsonb_typeof(p_criteria->'custom_field_conditions') = 'array' AND jsonb_array_length(p_criteria->'custom_field_conditions') > 0 THEN
    v_custom_fields := p_criteria->'custom_field_conditions';
  END IF;

  RETURN format($predicate$
(%3$L::text IS NULL OR c.source = %3$L::text)
    AND (%4$L::text IS NULL OR c.status = %4$L::text)
    AND (%5$L::text[] IS NULL OR c.tags && %5$L::text[])
    AND (%6$L::integer IS NULL OR c.lead_score >= %6$L::integer)
    AND (%7$L::integer IS NULL OR c.lead_score <= %7$L::integer)
    AND (%8$L::uuid IS NULL OR c.pipeline_id = %8$L::uuid)
    AND (%9$L::uuid IS NULL OR c.stage_id = %9$L::uuid)
    AND (%10$L::uuid IS NULL OR c.owner_user_id = %10$L::uuid)
    AND (%11$L::integer IS NULL OR c.created_at >= (NOW() - (%11$L::integer || ' days')::INTERVAL))
    AND (%12$L::integer IS NULL OR c.last_activity_at >= (NOW() - (%12$L::integer || ' days')::INTERVAL))
    AND (%13$L::boolean IS NULL
      OR (%13$L::boolean = TRUE AND c.primary_email IS NOT NULL AND c.primary_email != '')
      OR (%13$L::boolean = FALSE AND (c.primary_email IS NULL OR c.primary_email = '')))
    AND (%14$L::boolean IS NULL
      OR (%14$L::boolean = TRUE AND c.primary_linkedin_url IS NOT NULL AND c.primary_linkedin_url != '')
      OR (%14$L::boolean = FALSE AND (c.primary_linkedin_url IS NULL OR c.primary_linkedin_url = '')))
    AND (%15$L::uuid IS NULL OR EXISTS (
      SELECT 1 FROM public.contact_product_scores cps
      WHERE cps.contact_id = c.id
        AND cps.product_id = %15$L::uuid
        AND (%16$L::integer IS NULL OR cps.icp_score >= %16$L::integer)
        AND (%17$L::integer IS NULL OR cps.icp_score <= %17$L::integer)
        AND (%18$L::integer IS NULL OR cps.decision_maker_score >= %18$L::integer)
        AND (%19$L::integer IS NULL OR cps.decision_maker_score <= %19$L::integer)
    ))
    AND (%20$L::text[] IS NULL OR LOWER(c.enrichment_data->'company'->>'industry') = ANY(%20$L::text[]))
    AND (%21$L::text[] IS NULL OR public.crm_company_size_matches(c.company_employee_count,c.company_employee_range,c.enrichment_data->'company'->>'size',%21$L::text[]))
    AND (%22$L::text[] IS NULL OR LOWER(c.enrichment_data->>'seniority') = ANY(%22$L::text[]))
    AND (%23$L::text[] IS NULL OR LOWER(c.enrichment_data->>'department') = ANY(%23$L::text[]))
    AND (%24$L::text[] IS NULL OR LOWER(c.country) = ANY(%24$L::text[]))
    AND (%25$L::text[] IS NULL OR LOWER(c.city) = ANY(%25$L::text[]))
    AND (%26$L::text[] IS NULL OR (c.enrichment_data->'company'->'technologies') @> to_jsonb(%26$L::text[]))
    AND (%27$L::boolean IS NULL OR (c.enrichment_data->>'is_b2b')::BOOLEAN = %27$L::boolean)
    AND (%28$L::text[] IS NULL OR LOWER(c.enrichment_data->>'revenue_model') = ANY(%28$L::text[]))
    AND (%29$L::boolean IS NULL OR (c.enrichment_data->>'has_outbound_motion')::BOOLEAN = %29$L::boolean)
    AND (%30$L::boolean IS NULL OR (c.enrichment_data->>'hiring_sales_roles')::BOOLEAN = %30$L::boolean)
    AND (%31$L::boolean IS NULL OR (c.enrichment_data->'detected_technologies'->>'runs_paid_ads')::BOOLEAN = %31$L::boolean)
    AND (%32$L::text[] IS NULL OR (
      CASE WHEN %33$L::boolean
        THEN (c.enrichment_data->'detected_technologies'->'all') ?& %32$L::text[]
        ELSE (c.enrichment_data->'detected_technologies'->'all') ?| %32$L::text[]
      END))
    AND (%34$L::text[] IS NULL OR NOT (COALESCE(c.enrichment_data->'detected_technologies'->'all', '[]'::jsonb) ?| %34$L::text[]))
    AND (%35$L::jsonb IS NULL OR NOT EXISTS (
      SELECT 1 FROM jsonb_array_elements(%35$L::jsonb) cond
      WHERE NOT EXISTS (
        SELECT 1 FROM jsonb_array_elements(COALESCE(c.enrichment_data->'custom_analysis', '[]'::jsonb)) e
        WHERE e->>'question' = cond->>'question'
          AND COALESCE(TRIM(e->>'answer'), '') <> ''
          AND (NULLIF(cond->>'minScore','') IS NULL OR ((e->>'score') ~ '^-?[0-9]+(\.[0-9]+)?$' AND (e->>'score')::NUMERIC >= (cond->>'minScore')::NUMERIC))
      )
    ))
    AND (%36$L::jsonb IS NULL OR NOT EXISTS (
      SELECT 1 FROM jsonb_array_elements(%36$L::jsonb) cond
      WHERE NOT (
        CASE cond->>'operator'
          WHEN 'has_value' THEN c.custom_fields ? (cond->>'fieldKey') AND c.custom_fields->>(cond->>'fieldKey') IS DISTINCT FROM ''
          WHEN 'is_empty' THEN (NOT (c.custom_fields ? (cond->>'fieldKey'))) OR c.custom_fields->>(cond->>'fieldKey') = ''
          WHEN 'equals' THEN c.custom_fields @> jsonb_build_object(cond->>'fieldKey', cond->>'value')
          WHEN 'contains' THEN c.custom_fields ? (cond->>'fieldKey') AND c.custom_fields->>(cond->>'fieldKey') ILIKE '%%' || (cond->>'value') || '%%'
          ELSE TRUE
        END
      )
    ))
    AND (%37$L::boolean IS NULL OR (c.enrichment_data->>'emailVerified')::BOOLEAN = %37$L::boolean)
    AND (%38$L::text[] IS NULL OR (
      ('clean' = ANY(%38$L::text[]) AND c.email_verified_at IS NOT NULL AND c.email_verification_status = 'valid'
        AND COALESCE(c.email_is_catch_all,false)=false AND COALESCE(c.email_is_role,false)=false AND COALESCE(c.email_is_free,false)=false
        AND COALESCE(c.email_is_disposable,false)=false AND COALESCE(c.email_is_spamtrap,false)=false)
      OR ('risky' = ANY(%38$L::text[]) AND c.email_verified_at IS NOT NULL AND
        (c.email_verification_status='catch_all' OR c.email_is_catch_all=true OR c.email_is_role=true OR c.email_is_free=true)
        AND COALESCE(c.email_is_disposable,false)=false AND COALESCE(c.email_is_spamtrap,false)=false)
      OR ('failed' = ANY(%38$L::text[]) AND c.email_verified_at IS NOT NULL AND
        (c.email_verification_status IN ('invalid','disposable','spamtrap','disabled','role_only') OR c.email_is_disposable=true OR c.email_is_spamtrap=true))
      OR ('unverified' = ANY(%38$L::text[]) AND c.email_verified_at IS NULL)
    ))
    AND (%39$L::integer IS NULL OR (c.enrichment_data->>'emailConfidence')::INTEGER >= %39$L::integer)
    AND (%40$L::text IS NULL OR c.email_type = %40$L::text)
    AND (%41$L::boolean IS NULL
      OR (%41$L::boolean = TRUE AND c.enrichment_data IS NOT NULL AND c.enrichment_data != '{}'::JSONB)
      OR (%41$L::boolean = FALSE AND (c.enrichment_data IS NULL OR c.enrichment_data = '{}'::JSONB)))
    AND (%42$L::boolean IS NULL
      OR (%42$L::boolean = TRUE AND c.notion_preview_url IS NOT NULL AND c.notion_preview_url != '')
      OR (%42$L::boolean = FALSE AND (c.notion_preview_url IS NULL OR c.notion_preview_url = '')))
    AND (%43$L::text IS NULL
      OR (%43$L::text = 'behind' AND c.seg_provider IS NOT NULL)
      OR (%43$L::text = 'clear' AND c.seg_provider IS NULL AND c.seg_checked_at IS NOT NULL)
      OR (%43$L::text = 'unchecked' AND c.seg_checked_at IS NULL))
    AND (%44$L::text IS NULL
      OR (%44$L::text = 'no_data' AND (
            c.ai_analysis_status = 'failed'
            OR ((c.company_website IS NULL OR c.company_website = '')
              AND (c.primary_linkedin_url IS NULL OR c.primary_linkedin_url = ''))))
      OR (%44$L::text != 'no_data' AND c.ai_analysis_status = %44$L::text))
    AND (%45$L::text[] IS NULL OR (c.discovery_metadata->>'signal_type') = ANY(%45$L::text[]))
    AND (%46$L::text IS NULL OR c.discovery_metadata->>'signal_subscription_id' = %46$L::text)
    AND (%47$L::integer IS NULL OR c.discovery_score >= %47$L::integer)
    AND (%48$L::integer IS NULL
      OR (c.discovery_metadata->>'signal_date')::DATE >= (CURRENT_DATE - %48$L::integer))
    AND (%1$L::integer IS NULL OR c.company_employee_count >= %1$L::integer)
    AND (%2$L::integer IS NULL OR c.company_employee_count <= %2$L::integer)
$predicate$,
    v_min_employee_count,
    v_max_employee_count,
    v_source,
    v_status,
    v_tags,
    v_min_score,
    v_max_score,
    v_pipeline_id,
    v_stage_id,
    v_owner_user_id,
    v_created_days_ago,
    v_activity_days_ago,
    v_has_email,
    v_has_linkedin,
    v_icp_product_id,
    v_min_icp_score,
    v_max_icp_score,
    v_min_dm_score,
    v_max_dm_score,
    v_industries,
    v_company_sizes,
    v_seniorities,
    v_departments,
    v_countries,
    v_cities,
    v_technologies,
    v_is_b2b,
    v_revenue_models,
    v_has_outbound_motion,
    v_hiring_sales_roles,
    v_runs_ads,
    v_detected_technologies,
    v_detected_tech_all,
    v_excluded_technologies,
    v_custom_questions,
    v_custom_fields,
    v_email_verified,
    v_email_quality,
    v_min_email_confidence,
    v_email_type,
    v_has_enrichment_data,
    v_has_notion_url,
    v_seg_firewall,
    v_ai_analysis_status,
    v_signal_types,
    v_signal_subscription_id,
    v_min_discovery_score,
    v_signal_max_age_days
  );
END;
$_$;


ALTER FUNCTION "public"."smart_segment_flat_criteria_to_sql"("p_criteria" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."smart_segment_group_to_sql"("p_group" "jsonb", "p_depth" integer DEFAULT 0) RETURNS "text"
    LANGUAGE "plpgsql" STABLE
    AS $$
DECLARE
  v_operator text := coalesce(p_group->>'operator', 'and');
  v_parts text[] := ARRAY[]::text[];
  v_node jsonb;
BEGIN
  IF p_depth > 8 OR jsonb_typeof(p_group->'rules') <> 'array' OR jsonb_array_length(p_group->'rules') = 0 THEN
    RETURN 'FALSE';
  END IF;
  FOR v_node IN SELECT value FROM jsonb_array_elements(p_group->'rules') LOOP
    IF v_node ? 'rules' THEN
      v_parts := v_parts || ('(' || public.smart_segment_group_to_sql(v_node, p_depth + 1) || ')');
    ELSE
      v_parts := v_parts || ('(' || public.smart_segment_rule_to_sql(v_node) || ')');
    END IF;
  END LOOP;
  RETURN array_to_string(v_parts, CASE WHEN v_operator = 'or' THEN ' OR ' ELSE ' AND ' END);
END;
$$;


ALTER FUNCTION "public"."smart_segment_group_to_sql"("p_group" "jsonb", "p_depth" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."smart_segment_rule_to_sql"("p_rule" "jsonb") RETURNS "text"
    LANGUAGE "plpgsql" STABLE
    AS $_$
DECLARE
  v_field text := p_rule->>'field'; v_operator text := p_rule->>'operator';
  v_value text := p_rule->>'value'; v_field_key text := p_rule->>'fieldKey';
  v_values text[]; v_array_sql text; v_array_sql_lower text;
  v_uuid_re text := '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$';
BEGIN
  IF jsonb_typeof(p_rule->'value') = 'array' THEN
    SELECT array_agg(value) INTO v_values FROM jsonb_array_elements_text(p_rule->'value') value;
    SELECT 'ARRAY[' || string_agg(quote_literal(v), ',') || ']::text[]' INTO v_array_sql FROM unnest(v_values) v;
    SELECT 'ARRAY[' || string_agg(quote_literal(LOWER(v)), ',') || ']::text[]' INTO v_array_sql_lower FROM unnest(v_values) v;
  END IF;
  CASE v_field
    WHEN 'source' THEN RETURN CASE v_operator WHEN 'is' THEN format('c.source = %L',v_value) WHEN 'is_not' THEN format('c.source IS DISTINCT FROM %L',v_value) ELSE 'FALSE' END;
    WHEN 'status' THEN RETURN CASE v_operator WHEN 'is' THEN format('c.status::text = %L',v_value) WHEN 'is_not' THEN format('c.status::text IS DISTINCT FROM %L',v_value) ELSE 'FALSE' END;
    WHEN 'tag' THEN v_array_sql := COALESCE(v_array_sql,format('ARRAY[%L]::text[]',v_value)); RETURN CASE v_operator WHEN 'has_any' THEN format('c.tags && %s',v_array_sql) WHEN 'has_all' THEN format('c.tags @> %s',v_array_sql) WHEN 'has_none' THEN format('NOT (c.tags && %s)',v_array_sql) ELSE 'FALSE' END;
    WHEN 'lead_score' THEN IF v_value !~ '^-?[0-9]+$' THEN RETURN 'FALSE'; END IF; RETURN CASE v_operator WHEN 'gte' THEN format('c.lead_score >= %s',v_value::int) WHEN 'lte' THEN format('c.lead_score <= %s',v_value::int) ELSE 'FALSE' END;
    WHEN 'company_employee_count' THEN IF v_value !~ '^[0-9]+$' THEN RETURN 'FALSE'; END IF; RETURN CASE v_operator WHEN 'gte' THEN format('c.company_employee_count >= %s',v_value::int) WHEN 'lte' THEN format('c.company_employee_count <= %s',v_value::int) WHEN 'equals' THEN format('c.company_employee_count = %s',v_value::int) ELSE 'FALSE' END;
    WHEN 'company_size' THEN v_array_sql := COALESCE(v_array_sql,format('ARRAY[%L]::text[]',v_value)); RETURN format('public.crm_company_size_matches(c.company_employee_count,c.company_employee_range,c.enrichment_data->''company''->>''size'',%s)',v_array_sql);
    WHEN 'has_email' THEN RETURN CASE v_operator WHEN 'exists' THEN $$COALESCE(c.primary_email, '') <> ''$$ WHEN 'not_exists' THEN $$COALESCE(c.primary_email, '') = ''$$ ELSE 'FALSE' END;
    WHEN 'has_linkedin' THEN RETURN CASE v_operator WHEN 'exists' THEN $$COALESCE(c.primary_linkedin_url, '') <> ''$$ WHEN 'not_exists' THEN $$COALESCE(c.primary_linkedin_url, '') = ''$$ ELSE 'FALSE' END;
    WHEN 'country' THEN RETURN CASE v_operator WHEN 'is' THEN format('LOWER(COALESCE(c.country,%L))=LOWER(%L)','',v_value) WHEN 'is_not' THEN format('LOWER(COALESCE(c.country,%L))<>LOWER(%L)','',v_value) ELSE 'FALSE' END;
    WHEN 'city' THEN RETURN CASE v_operator WHEN 'is' THEN format('LOWER(COALESCE(c.city,%L))=LOWER(%L)','',v_value) WHEN 'is_not' THEN format('LOWER(COALESCE(c.city,%L))<>LOWER(%L)','',v_value) ELSE 'FALSE' END;
    WHEN 'custom_field' THEN IF COALESCE(v_field_key,'')='' THEN RETURN 'FALSE'; END IF; RETURN CASE v_operator WHEN 'equals' THEN format('c.custom_fields @> jsonb_build_object(%L,%L::text)',v_field_key,v_value) WHEN 'contains' THEN format('(c.custom_fields ? %L AND c.custom_fields->>%L ILIKE %L)',v_field_key,v_field_key,'%'||COALESCE(v_value,'')||'%') WHEN 'exists' THEN format('(c.custom_fields ? %L AND COALESCE(c.custom_fields->>%L,%L)<>%L)',v_field_key,v_field_key,'','') WHEN 'is_empty' THEN format('(NOT(c.custom_fields ? %L) OR COALESCE(c.custom_fields->>%L,%L)=%L)',v_field_key,v_field_key,'','') ELSE 'FALSE' END;
    WHEN 'signal' THEN RETURN CASE v_operator WHEN 'is' THEN format('(c.discovery_metadata->>%L) = %L','signal_subscription_id',v_value) WHEN 'is_not' THEN format('(c.discovery_metadata->>%L) IS DISTINCT FROM %L','signal_subscription_id',v_value) ELSE 'FALSE' END;

    -- CRM context: pipeline, stage, owner, recency
    WHEN 'pipeline_id' THEN IF v_value !~ v_uuid_re THEN RETURN 'FALSE'; END IF; RETURN CASE v_operator WHEN 'is' THEN format('c.pipeline_id = %L::uuid',v_value) WHEN 'is_not' THEN format('c.pipeline_id IS DISTINCT FROM %L::uuid',v_value) ELSE 'FALSE' END;
    WHEN 'stage_id' THEN IF v_value !~ v_uuid_re THEN RETURN 'FALSE'; END IF; RETURN CASE v_operator WHEN 'is' THEN format('c.stage_id = %L::uuid',v_value) WHEN 'is_not' THEN format('c.stage_id IS DISTINCT FROM %L::uuid',v_value) ELSE 'FALSE' END;
    WHEN 'owner_user_id' THEN IF v_value !~ v_uuid_re THEN RETURN 'FALSE'; END IF; RETURN CASE v_operator WHEN 'is' THEN format('c.owner_user_id = %L::uuid',v_value) WHEN 'is_not' THEN format('c.owner_user_id IS DISTINCT FROM %L::uuid',v_value) ELSE 'FALSE' END;
    WHEN 'created_days_ago' THEN IF v_value !~ '^[0-9]+$' THEN RETURN 'FALSE'; END IF; RETURN CASE v_operator WHEN 'within' THEN format('c.created_at >= NOW() - %L::interval',v_value||' days') ELSE 'FALSE' END;
    WHEN 'activity_days_ago' THEN IF v_value !~ '^[0-9]+$' THEN RETURN 'FALSE'; END IF; RETURN CASE v_operator WHEN 'within' THEN format('c.last_activity_at >= NOW() - %L::interval',v_value||' days') ELSE 'FALSE' END;

    -- Per-product qualification scores (fieldKey = library_products.id)
    WHEN 'icp_score' THEN IF COALESCE(v_field_key,'') !~ v_uuid_re OR v_value !~ '^-?[0-9]+$' THEN RETURN 'FALSE'; END IF; RETURN CASE v_operator WHEN 'gte' THEN format('EXISTS (SELECT 1 FROM public.contact_product_scores cps WHERE cps.contact_id=c.id AND cps.product_id=%L::uuid AND cps.icp_score >= %s)',v_field_key,v_value::int) WHEN 'lte' THEN format('EXISTS (SELECT 1 FROM public.contact_product_scores cps WHERE cps.contact_id=c.id AND cps.product_id=%L::uuid AND cps.icp_score <= %s)',v_field_key,v_value::int) ELSE 'FALSE' END;
    WHEN 'dm_score' THEN IF COALESCE(v_field_key,'') !~ v_uuid_re OR v_value !~ '^-?[0-9]+$' THEN RETURN 'FALSE'; END IF; RETURN CASE v_operator WHEN 'gte' THEN format('EXISTS (SELECT 1 FROM public.contact_product_scores cps WHERE cps.contact_id=c.id AND cps.product_id=%L::uuid AND cps.decision_maker_score >= %s)',v_field_key,v_value::int) WHEN 'lte' THEN format('EXISTS (SELECT 1 FROM public.contact_product_scores cps WHERE cps.contact_id=c.id AND cps.product_id=%L::uuid AND cps.decision_maker_score <= %s)',v_field_key,v_value::int) ELSE 'FALSE' END;

    -- Firmographics (case-insensitive single-value membership, mirrors the flat path's LOWER(...) = ANY(...))
    WHEN 'industry' THEN v_array_sql_lower := COALESCE(v_array_sql_lower,format('ARRAY[LOWER(%L)]::text[]',v_value)); RETURN CASE v_operator WHEN 'in' THEN format('LOWER(c.enrichment_data->''company''->>''industry'') = ANY(%s)',v_array_sql_lower) WHEN 'not_in' THEN format('NOT (LOWER(c.enrichment_data->''company''->>''industry'') = ANY(%s))',v_array_sql_lower) ELSE 'FALSE' END;
    WHEN 'seniority' THEN v_array_sql_lower := COALESCE(v_array_sql_lower,format('ARRAY[LOWER(%L)]::text[]',v_value)); RETURN CASE v_operator WHEN 'in' THEN format('LOWER(c.enrichment_data->>''seniority'') = ANY(%s)',v_array_sql_lower) WHEN 'not_in' THEN format('NOT (LOWER(c.enrichment_data->>''seniority'') = ANY(%s))',v_array_sql_lower) ELSE 'FALSE' END;
    WHEN 'department' THEN v_array_sql_lower := COALESCE(v_array_sql_lower,format('ARRAY[LOWER(%L)]::text[]',v_value)); RETURN CASE v_operator WHEN 'in' THEN format('LOWER(c.enrichment_data->>''department'') = ANY(%s)',v_array_sql_lower) WHEN 'not_in' THEN format('NOT (LOWER(c.enrichment_data->>''department'') = ANY(%s))',v_array_sql_lower) ELSE 'FALSE' END;
    WHEN 'revenue_model' THEN v_array_sql_lower := COALESCE(v_array_sql_lower,format('ARRAY[LOWER(%L)]::text[]',v_value)); RETURN CASE v_operator WHEN 'in' THEN format('LOWER(c.enrichment_data->>''revenue_model'') = ANY(%s)',v_array_sql_lower) WHEN 'not_in' THEN format('NOT (LOWER(c.enrichment_data->>''revenue_model'') = ANY(%s))',v_array_sql_lower) ELSE 'FALSE' END;

    -- Technology arrays (case-sensitive containment, mirrors the flat path's jsonb ?|/?&/@> exactly)
    WHEN 'technology' THEN v_array_sql := COALESCE(v_array_sql,format('ARRAY[%L]::text[]',v_value)); RETURN CASE v_operator WHEN 'has_any' THEN format('(c.enrichment_data->''company''->''technologies'') ?| %s',v_array_sql) WHEN 'has_all' THEN format('(c.enrichment_data->''company''->''technologies'') ?& %s',v_array_sql) WHEN 'has_none' THEN format('NOT (COALESCE(c.enrichment_data->''company''->''technologies'',''[]''::jsonb) ?| %s)',v_array_sql) ELSE 'FALSE' END;
    WHEN 'detected_technology' THEN v_array_sql := COALESCE(v_array_sql,format('ARRAY[%L]::text[]',v_value)); RETURN CASE v_operator WHEN 'has_any' THEN format('(c.enrichment_data->''detected_technologies''->''all'') ?| %s',v_array_sql) WHEN 'has_all' THEN format('(c.enrichment_data->''detected_technologies''->''all'') ?& %s',v_array_sql) WHEN 'has_none' THEN format('NOT (COALESCE(c.enrichment_data->''detected_technologies''->''all'',''[]''::jsonb) ?| %s)',v_array_sql) ELSE 'FALSE' END;

    -- Boolean qualification flags (enrichment_data, cast from validated 'true'/'false' text)
    WHEN 'is_b2b' THEN IF v_value NOT IN ('true','false') THEN RETURN 'FALSE'; END IF; RETURN format('(c.enrichment_data->>''is_b2b'')::boolean = %s',v_value);
    WHEN 'has_outbound_motion' THEN IF v_value NOT IN ('true','false') THEN RETURN 'FALSE'; END IF; RETURN format('(c.enrichment_data->>''has_outbound_motion'')::boolean = %s',v_value);
    WHEN 'hiring_sales_roles' THEN IF v_value NOT IN ('true','false') THEN RETURN 'FALSE'; END IF; RETURN format('(c.enrichment_data->>''hiring_sales_roles'')::boolean = %s',v_value);
    WHEN 'runs_ads' THEN IF v_value NOT IN ('true','false') THEN RETURN 'FALSE'; END IF; RETURN format('(c.enrichment_data->''detected_technologies''->>''runs_paid_ads'')::boolean = %s',v_value);
    WHEN 'email_verified' THEN IF v_value NOT IN ('true','false') THEN RETURN 'FALSE'; END IF; RETURN format('(c.enrichment_data->>''emailVerified'')::boolean = %s',v_value);

    -- Email quality/type/confidence
    WHEN 'email_quality' THEN v_array_sql := COALESCE(v_array_sql,format('ARRAY[%L]::text[]',v_value)); RETURN CASE v_operator WHEN 'in' THEN format('public.crm_email_quality_matches(c,%s)',v_array_sql) WHEN 'not_in' THEN format('NOT public.crm_email_quality_matches(c,%s)',v_array_sql) ELSE 'FALSE' END;
    WHEN 'email_type' THEN RETURN CASE v_operator WHEN 'is' THEN format('c.email_type = %L',v_value) WHEN 'is_not' THEN format('c.email_type IS DISTINCT FROM %L',v_value) ELSE 'FALSE' END;
    WHEN 'min_email_confidence' THEN IF v_value !~ '^[0-9]+$' THEN RETURN 'FALSE'; END IF; RETURN CASE v_operator WHEN 'gte' THEN format('(c.enrichment_data->>''emailConfidence'')::integer >= %s',v_value::int) ELSE 'FALSE' END;

    -- Data presence / compliance / AI status
    WHEN 'has_enrichment_data' THEN RETURN CASE v_operator WHEN 'exists' THEN $$(c.enrichment_data IS NOT NULL AND c.enrichment_data <> '{}'::jsonb)$$ WHEN 'not_exists' THEN $$(c.enrichment_data IS NULL OR c.enrichment_data = '{}'::jsonb)$$ ELSE 'FALSE' END;
    WHEN 'has_notion_url' THEN RETURN CASE v_operator WHEN 'exists' THEN $$COALESCE(c.notion_preview_url,'') <> ''$$ WHEN 'not_exists' THEN $$COALESCE(c.notion_preview_url,'') = ''$$ ELSE 'FALSE' END;
    WHEN 'seg_firewall' THEN IF v_operator <> 'is' THEN RETURN 'FALSE'; END IF; RETURN CASE v_value WHEN 'behind' THEN 'c.seg_provider IS NOT NULL' WHEN 'clear' THEN '(c.seg_provider IS NULL AND c.seg_checked_at IS NOT NULL)' WHEN 'unchecked' THEN 'c.seg_checked_at IS NULL' ELSE 'FALSE' END;
    WHEN 'ai_analysis_status' THEN
      IF v_operator <> 'is' OR v_value NOT IN ('not_analyzed','analyzing','analyzed','failed','no_data') THEN RETURN 'FALSE'; END IF;
      RETURN CASE WHEN v_value = 'no_data' THEN $$(c.ai_analysis_status = 'failed' OR ((COALESCE(c.company_website,'')='') AND (COALESCE(c.primary_linkedin_url,'')='')))$$ ELSE format('c.ai_analysis_status = %L',v_value) END;

    -- AI-scored custom question. fieldKey = question text (verbatim, from
    -- library_products.analysis_questions). Blank value = "has any answer";
    -- a numeric value additionally requires that score.
    WHEN 'custom_question' THEN
      IF COALESCE(v_field_key,'')='' THEN RETURN 'FALSE'; END IF;
      IF COALESCE(v_value,'')='' THEN
        RETURN format(
          $sql$EXISTS (SELECT 1 FROM jsonb_array_elements(COALESCE(c.enrichment_data->'custom_analysis','[]'::jsonb)) e WHERE e->>'question'=%L AND COALESCE(TRIM(e->>'answer'),'')<>'')$sql$,
          v_field_key
        );
      ELSIF v_value ~ '^[0-9]+(\.[0-9]+)?$' THEN
        RETURN format(
          $sql$EXISTS (SELECT 1 FROM jsonb_array_elements(COALESCE(c.enrichment_data->'custom_analysis','[]'::jsonb)) e WHERE e->>'question'=%L AND COALESCE(TRIM(e->>'answer'),'')<>'' AND (e->>'score') ~ '^-?[0-9]+(\.[0-9]+)?$' AND (e->>'score')::numeric >= %s)$sql$,
          v_field_key, v_value
        );
      ELSE
        RETURN 'FALSE';
      END IF;

    ELSE RETURN 'FALSE';
  END CASE;
END;
$_$;


ALTER FUNCTION "public"."smart_segment_rule_to_sql"("p_rule" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."snapshot_email_enrollment_job_step"("p_job_id" "uuid", "p_limit" integer DEFAULT 20000) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_job public.email_enrollment_jobs;
  v_list UUID;
  v_smart BOOLEAN;
  v_added INTEGER := 0;
  v_scanned INTEGER := 0;
  v_last UUID;
  v_next_index INTEGER;
  v_next_cursor UUID;
BEGIN
  SELECT * INTO v_job FROM public.email_enrollment_jobs WHERE id = p_job_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Enrollment job % not found', p_job_id; END IF;
  IF v_job.status <> 'snapshotting' THEN
    RETURN jsonb_build_object('done', true, 'added', 0, 'total', v_job.total);
  END IF;

  IF v_job.snapshot_list_index >= COALESCE(cardinality(v_job.list_ids), 0) THEN
    UPDATE public.email_enrollment_jobs SET status = 'running', updated_at = NOW() WHERE id = p_job_id;
    RETURN jsonb_build_object('done', true, 'added', 0, 'total', v_job.total);
  END IF;

  v_list := v_job.list_ids[v_job.snapshot_list_index + 1];
  SELECT is_smart INTO v_smart FROM public.lead_lists
  WHERE id = v_list AND organization_id = v_job.organization_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'List % not found in this organization', v_list; END IF;

  v_next_index := v_job.snapshot_list_index + 1;
  v_next_cursor := NULL;

  IF v_smart IS TRUE THEN
    INSERT INTO public.email_enrollment_job_members (job_id, contact_id)
    SELECT p_job_id, x FROM public.smart_list_eligible_contact_ids(v_list) AS x
    ON CONFLICT DO NOTHING;
    GET DIAGNOSTICS v_added = ROW_COUNT;
  ELSIF v_job.filters IS NOT NULL AND cardinality(v_job.list_ids) = 1 THEN
    INSERT INTO public.email_enrollment_job_members (job_id, contact_id)
    SELECT p_job_id, e::UUID
    FROM jsonb_array_elements_text(
      COALESCE(public.get_filtered_lead_list_member_ids(v_list, v_job.filters, NULL::INTEGER), '[]'::JSONB)
    ) AS e
    ON CONFLICT DO NOTHING;
    GET DIAGNOSTICS v_added = ROW_COUNT;
  ELSE
    WITH page AS (
      SELECT m.contact_id
      FROM public.lead_list_members m
      WHERE m.list_id = v_list
        AND (v_job.snapshot_cursor IS NULL OR m.contact_id > v_job.snapshot_cursor)
      ORDER BY m.contact_id
      LIMIT p_limit
    ), ins AS (
      INSERT INTO public.email_enrollment_job_members (job_id, contact_id)
      SELECT p_job_id, contact_id FROM page
      ON CONFLICT DO NOTHING
      RETURNING 1
    )
    SELECT (SELECT count(*) FROM page), (SELECT max(contact_id::TEXT)::UUID FROM page), (SELECT count(*) FROM ins)
    INTO v_scanned, v_last, v_added;

    IF v_scanned >= p_limit THEN
      v_next_index := v_job.snapshot_list_index;
      v_next_cursor := v_last;
    END IF;
  END IF;

  UPDATE public.email_enrollment_jobs
  SET snapshot_list_index = v_next_index,
      snapshot_cursor = v_next_cursor,
      total = total + v_added,
      updated_at = NOW()
  WHERE id = p_job_id
  RETURNING * INTO v_job;

  RETURN jsonb_build_object('done', false, 'added', v_added, 'total', v_job.total);
END;
$$;


ALTER FUNCTION "public"."snapshot_email_enrollment_job_step"("p_job_id" "uuid", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."stop_sequence_enrollments"("p_sequence_id" "uuid", "p_lead_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_reason" "text" DEFAULT 'stopped'::"text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_count integer;
BEGIN
  UPDATE email_sequence_enrollments
     SET status = 'stopped',
         -- A stopped enrollment must not sit in any due-window. Clearing this
         -- also makes it obvious in the data that it is not merely parked.
         next_send_at = NULL,
         metadata = COALESCE(metadata, '{}'::jsonb) || jsonb_build_object(
           'stopped_at', now(),
           'stopped_reason', p_reason
         ),
         updated_at = now()
   WHERE sequence_id = p_sequence_id
     AND (p_lead_ids IS NULL OR lead_id = ANY(p_lead_ids))
     -- Only states that could still send. Outcomes that already mean something
     -- (replied, unsubscribed, bounced, completed) keep their meaning — losing
     -- them would corrupt reporting.
     AND status IN ('active', 'paused', 'sender_disconnected');

  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$$;


ALTER FUNCTION "public"."stop_sequence_enrollments"("p_sequence_id" "uuid", "p_lead_ids" "uuid"[], "p_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."stop_sequence_enrollments"("p_sequence_id" "uuid", "p_lead_ids" "uuid"[], "p_reason" "text") IS 'Terminally stops enrollments so they cannot resume. Used by the move-between-sequences flow and by archiving a sequence.';



CREATE OR REPLACE FUNCTION "public"."strip_html_to_text"("html" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  SELECT NULLIF(TRIM(
    regexp_replace(
      regexp_replace(
        regexp_replace(
          regexp_replace(
            regexp_replace(
              regexp_replace(
                regexp_replace(
                  regexp_replace(
                    regexp_replace(
                      regexp_replace(
                        regexp_replace(
                          regexp_replace(html,
                            '<(style|head|script|title)[^>]*>.*?<\/\1>', '', 'gis'),
                          '<br\s*/?>', ' ', 'gi'),
                        '<[^>]*>', '', 'g'),
                      '&amp;', '&', 'gi'),
                    '&lt;', '<', 'gi'),
                  '&gt;', '>', 'gi'),
                '&quot;', '"', 'gi'),
              '&#0?39;|&apos;', '''', 'gi'),
            '&nbsp;', ' ', 'gi'),
          E'=\\r?\\n', '', 'g'),
        '=C2=A0', ' ', 'gi'),
      '\s+', ' ', 'g')
  ), '');
$$;


ALTER FUNCTION "public"."strip_html_to_text"("html" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."suggest_inbox_warmup_keywords"("p_org_id" "uuid", "p_days" integer DEFAULT 30, "p_min_senders" integer DEFAULT 3, "p_limit" integer DEFAULT 200) RETURNS TABLE("keyword" "text", "message_count" integer, "sender_count" integer, "already_excluded" boolean)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.organization_members
    WHERE user_id = auth.uid() AND organization_id = p_org_id
  ) AND auth.role() <> 'service_role' THEN
    RAISE EXCEPTION 'Not authorized for organization %', p_org_id;
  END IF;

  RETURN QUERY
  WITH msgs AS (
    SELECT m.id, m.contact_id,
           regexp_replace(m.content, '<[^>]*>', ' ', 'g') AS txt
    FROM public.crm_messages m
    WHERE m.organization_id = p_org_id
      AND m.direction = 'inbound'
      AND m.created_at > NOW() - (GREATEST(COALESCE(p_days, 30), 1) || ' days')::INTERVAL
  ),
  toks AS (
    SELECT msgs.id, msgs.contact_id, lower(t[1] || '-' || t[2]) AS tok
    FROM msgs
    CROSS JOIN LATERAL regexp_matches(msgs.txt, '\m([a-z]{4,})-([a-z]{4,})\M', 'g') AS t
  )
  SELECT
    toks.tok,
    COUNT(DISTINCT toks.id)::INTEGER,
    COUNT(DISTINCT toks.contact_id)::INTEGER,
    EXISTS (
      SELECT 1 FROM public.inbox_keyword_exclusions k
      WHERE k.organization_id = p_org_id AND k.normalized_keyword = toks.tok
    )
  FROM toks
  GROUP BY toks.tok
  HAVING COUNT(DISTINCT toks.contact_id) >= GREATEST(COALESCE(p_min_senders, 3), 2)
  ORDER BY COUNT(DISTINCT toks.contact_id) DESC, COUNT(DISTINCT toks.id) DESC
  LIMIT GREATEST(COALESCE(p_limit, 200), 1);
END;
$$;


ALTER FUNCTION "public"."suggest_inbox_warmup_keywords"("p_org_id" "uuid", "p_days" integer, "p_min_senders" integer, "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."suppress_contact_on_hard_bounce"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NEW.recipient_email IS NULL THEN
    RETURN NEW;
  END IF;

  -- Only promote an ACTIVE contact. Never overwrite a stronger suppression
  -- (do_not_contact / unsubscribed), and skipping no-op writes matters: every
  -- crm_contacts UPDATE queues a contact_updated webhook to the customer's live
  -- endpoint, so re-stamping an already-bounced contact on each retry would be a
  -- delivery storm for no information gain.
  UPDATE crm_contacts
     SET status = 'bounced',
         updated_at = now()
   WHERE organization_id = NEW.organization_id
     AND lower(primary_email) = lower(NEW.recipient_email)
     AND status = 'active';

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."suppress_contact_on_hard_bounce"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."suppress_contact_on_hard_bounce"() IS 'Promotes a contact to status=bounced on a genuine hard bounce so every suppression guard sees it. Never fires for reputation blocks (status=blocked) — those are our domain, not their address.';



CREATE OR REPLACE FUNCTION "public"."sync_autopilot_pool_from_tags"("p_autopilot_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_autopilot RECORD;
  v_added_count INTEGER := 0;
  v_tags TEXT[];
BEGIN
  SELECT * INTO v_autopilot FROM public.autopilots WHERE id = p_autopilot_id;

  IF v_autopilot IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Autopilot not found', 'added', 0);
  END IF;

  SELECT array_agg(DISTINCT t) INTO v_tags
  FROM public.autopilot_feed_entries(v_autopilot.ideas_source, v_autopilot.shared_idea_tags, v_autopilot.content_mix) e,
       unnest(e.tags) t;

  IF v_tags IS NULL OR array_length(v_tags, 1) IS NULL THEN
    RETURN jsonb_build_object(
      'success', true,
      'added', 0,
      'autopilot_id', p_autopilot_id,
      'message', 'No tags configured',
      'ideas_source', v_autopilot.ideas_source
    );
  END IF;

  INSERT INTO public.autopilot_idea_pools (autopilot_id, idea_id, organization_id, status, added_by)
  SELECT DISTINCT p_autopilot_id, ci.id, v_autopilot.organization_id, 'available', 'tag_sync'
  FROM public.content_ideas ci
  JOIN public.idea_tag_assignments ita ON ita.idea_id = ci.id
  JOIN public.idea_tags it ON it.id = ita.tag_id
  WHERE ci.organization_id = v_autopilot.organization_id
    AND LOWER(it.name) = ANY (SELECT LOWER(unnest(v_tags)))
    AND NOT EXISTS (
      SELECT 1 FROM public.autopilot_idea_exclusions ex
      WHERE ex.autopilot_id = p_autopilot_id AND ex.idea_id = ci.id
    )
    AND NOT EXISTS (
      SELECT 1 FROM public.autopilot_idea_pools aip
      WHERE aip.autopilot_id = p_autopilot_id AND aip.idea_id = ci.id
    )
  ON CONFLICT (autopilot_id, idea_id) DO NOTHING;

  GET DIAGNOSTICS v_added_count = ROW_COUNT;

  RETURN jsonb_build_object(
    'success', true,
    'added', v_added_count,
    'autopilot_id', p_autopilot_id,
    'ideas_source', v_autopilot.ideas_source,
    'tags_used', v_tags
  );
END;
$$;


ALTER FUNCTION "public"."sync_autopilot_pool_from_tags"("p_autopilot_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_job_progress"("p_job_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_total INTEGER;
  v_done INTEGER;
  v_failed INTEGER;
  v_active INTEGER;
  v_waiting INTEGER;
  v_outputs INTEGER;
  v_existing_error TEXT;
  v_first_error TEXT;
BEGIN
  SELECT jsonb_array_length(COALESCE(items, '[]'::jsonb)), error
  INTO v_total, v_existing_error
  FROM content_generation_jobs
  WHERE id = p_job_id;

  IF NOT FOUND THEN
    RETURN;
  END IF;

  WITH o AS (
    SELECT
      CASE
        WHEN status IN ('failed', 'error') THEN 'failed'
        WHEN status IN ('generating', 'processing', 'queued', 'pending', 'regenerating') THEN 'active'
        WHEN current_stage = 'complete'
          OR status IN ('approved', 'rejected')
          OR (current_stage IS NULL AND status = 'review') THEN 'done'
        ELSE 'waiting'
      END AS bucket
    FROM content_outputs
    WHERE job_id = p_job_id
  )
  SELECT
    COUNT(*) FILTER (WHERE bucket = 'done'),
    COUNT(*) FILTER (WHERE bucket = 'failed'),
    COUNT(*) FILTER (WHERE bucket = 'active'),
    COUNT(*) FILTER (WHERE bucket = 'waiting'),
    COUNT(*)
  INTO v_done, v_failed, v_active, v_waiting, v_outputs
  FROM o;

  v_total := GREATEST(v_total, v_outputs);

  IF v_done = 0 AND v_waiting = 0 AND v_failed > 0 THEN
    SELECT error_message
    INTO v_first_error
    FROM content_outputs
    WHERE job_id = p_job_id AND error_message IS NOT NULL
    ORDER BY created_at ASC
    LIMIT 1;
  END IF;

  UPDATE content_generation_jobs
  SET
    progress = jsonb_build_object(
      'total', v_total,
      'completed', v_done,
      'failed', v_failed,
      'generating', v_active,
      'waiting', v_waiting
    ),
    status = CASE
      WHEN status = 'cancelled' THEN status
      WHEN v_active > 0 THEN 'processing'
      WHEN v_total > 0 AND v_failed >= v_total AND v_done = 0 AND v_waiting = 0 THEN 'failed'
      WHEN v_total > 0 AND (v_done + v_failed + v_waiting) >= v_total THEN 'completed'
      WHEN (v_done + v_failed + v_waiting) > 0 THEN 'processing'
      ELSE status
    END,
    error = CASE
      WHEN status = 'cancelled' THEN error
      WHEN v_active = 0
        AND v_total > 0 AND v_failed >= v_total AND v_done = 0 AND v_waiting = 0
        THEN COALESCE(v_existing_error, v_first_error, 'Generation failed for all items')
      WHEN v_failed = 0 AND v_outputs > 0 THEN NULL
      ELSE error
    END,
    completed_at = CASE
      WHEN v_active = 0 AND v_total > 0 AND (v_done + v_failed + v_waiting) >= v_total
        THEN COALESCE(completed_at, now())
      WHEN v_active > 0 THEN NULL
      ELSE completed_at
    END
  WHERE id = p_job_id;
END;
$$;


ALTER FUNCTION "public"."sync_job_progress"("p_job_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."sync_job_progress"("p_job_id" "uuid") IS 'Derives a job''s status and progress from its outputs. processing = something is still generating; completed = every item is done, failed or waiting for a person (progress.waiting); failed = every item failed.';



CREATE OR REPLACE FUNCTION "public"."sync_lead_list_scalar_array"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  IF TG_OP = 'UPDATE' THEN
    IF NEW.lead_list_ids IS DISTINCT FROM OLD.lead_list_ids THEN
      NEW.lead_list_id := CASE
        WHEN cardinality(COALESCE(NEW.lead_list_ids, '{}')) > 0 THEN NEW.lead_list_ids[1]
        ELSE NULL END;
    ELSIF NEW.lead_list_id IS DISTINCT FROM OLD.lead_list_id THEN
      NEW.lead_list_ids := CASE
        WHEN NEW.lead_list_id IS NOT NULL THEN ARRAY[NEW.lead_list_id]
        ELSE '{}' END;
    END IF;
  ELSE
    IF cardinality(COALESCE(NEW.lead_list_ids, '{}')) > 0 THEN
      NEW.lead_list_id := NEW.lead_list_ids[1];
    ELSIF NEW.lead_list_id IS NOT NULL THEN
      NEW.lead_list_ids := ARRAY[NEW.lead_list_id];
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."sync_lead_list_scalar_array"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_lead_processing_contact_snapshots"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF OLD.primary_email IS DISTINCT FROM NEW.primary_email
     OR OLD.email_verification_status IS DISTINCT FROM NEW.email_verification_status
     OR OLD.moltsets_attempted_at IS DISTINCT FROM NEW.moltsets_attempted_at THEN
    UPDATE public.lead_list_processing_items item
    SET contact_has_email = NULLIF(BTRIM(NEW.primary_email), '') IS NOT NULL,
        contact_email_verification_status = NEW.email_verification_status,
        contact_email_search_attempted = NEW.moltsets_attempted_at IS NOT NULL
    WHERE item.contact_id = NEW.id
      AND (
        item.contact_has_email IS DISTINCT FROM (NULLIF(BTRIM(NEW.primary_email), '') IS NOT NULL)
        OR item.contact_email_verification_status IS DISTINCT FROM NEW.email_verification_status
        OR item.contact_email_search_attempted IS DISTINCT FROM (NEW.moltsets_attempted_at IS NOT NULL)
      );
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."sync_lead_processing_contact_snapshots"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_linkedin_connection_to_crm"("p_organization_id" "uuid", "p_account_id" "uuid", "p_linkedin_id" "text", "p_linkedin_url" "text", "p_first_name" "text", "p_last_name" "text", "p_full_name" "text", "p_headline" "text", "p_job_title" "text", "p_company" "text", "p_location" "text", "p_profile_picture_url" "text", "p_connected_at" timestamp with time zone, "p_raw_data" "jsonb" DEFAULT '{}'::"jsonb") RETURNS TABLE("contact_id" "uuid", "action" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_contact_id UUID;
  v_existing_identity RECORD;
  v_display_name TEXT;
  v_action TEXT := 'created';
BEGIN
  -- Build display name
  v_display_name := COALESCE(
    NULLIF(TRIM(p_full_name), ''),
    NULLIF(TRIM(CONCAT(COALESCE(p_first_name, ''), ' ', COALESCE(p_last_name, ''))), ''),
    p_first_name,
    'Unknown'
  );

  -- Check if contact already exists by LinkedIn ID in this organization
  SELECT ci.*, cc.id as contact_id
  INTO v_existing_identity
  FROM crm_contact_identities ci
  JOIN crm_contacts cc ON ci.contact_id = cc.id
  WHERE ci.organization_id = p_organization_id
    AND ci.channel = 'linkedin'
    AND ci.platform_user_id = p_linkedin_id
  LIMIT 1;

  IF v_existing_identity IS NOT NULL THEN
    v_contact_id := v_existing_identity.contact_id;

    -- Check if this account is already linked
    IF p_account_id = ANY(COALESCE(v_existing_identity.linked_account_ids, '{}')) THEN
      -- Just update contact info
      v_action := 'updated';
    ELSE
      -- Add new account to the linked list
      v_action := 'account_linked';

      UPDATE crm_contact_identities
      SET
        linked_account_ids = array_append(COALESCE(linked_account_ids, '{}'), p_account_id),
        raw_connection_data = COALESCE(raw_connection_data, '{}') ||
          jsonb_build_object(p_account_id::text, p_raw_data),
        updated_at = NOW()
      WHERE id = v_existing_identity.id;
    END IF;

    -- Update contact with latest info
    UPDATE crm_contacts
    SET
      display_name = COALESCE(NULLIF(v_display_name, 'Unknown'), display_name),
      first_name = COALESCE(NULLIF(p_first_name, ''), first_name),
      last_name = COALESCE(NULLIF(p_last_name, ''), last_name),
      job_title = COALESCE(NULLIF(p_headline, ''), NULLIF(p_job_title, ''), job_title),
      company = COALESCE(NULLIF(p_company, ''), company),
      avatar_url = COALESCE(NULLIF(p_profile_picture_url, ''), avatar_url),
      primary_linkedin_url = COALESCE(NULLIF(p_linkedin_url, ''), primary_linkedin_url),
      is_linkedin_connection = true,
      linkedin_connected_at = COALESCE(p_connected_at, linkedin_connected_at),
      updated_at = NOW()
    WHERE id = v_contact_id;

    -- Also update identity's platform_avatar_url to keep in sync
    UPDATE crm_contact_identities
    SET
      platform_avatar_url = COALESCE(NULLIF(p_profile_picture_url, ''), platform_avatar_url),
      platform_profile_url = COALESCE(NULLIF(p_linkedin_url, ''), platform_profile_url),
      platform_metadata = COALESCE(platform_metadata, '{}'::jsonb) ||
        jsonb_build_object(
          'headline', COALESCE(p_headline, platform_metadata->>'headline'),
          'company', COALESCE(p_company, platform_metadata->>'company'),
          'location', COALESCE(p_location, platform_metadata->>'location')
        ),
      updated_at = NOW()
    WHERE id = v_existing_identity.id;

  ELSE
    -- Create new contact
    INSERT INTO crm_contacts (
      organization_id,
      display_name,
      first_name,
      last_name,
      job_title,
      company,
      avatar_url,
      primary_linkedin_url,
      source,
      is_linkedin_connection,
      linkedin_connected_at,
      first_seen_at,
      last_activity_at,
      status
    ) VALUES (
      p_organization_id,
      v_display_name,
      p_first_name,
      p_last_name,
      COALESCE(p_headline, p_job_title),
      p_company,
      p_profile_picture_url,
      p_linkedin_url,
      'linkedin_connection',
      true,
      p_connected_at,
      COALESCE(p_connected_at, NOW()),
      NOW(),
      'active'
    )
    RETURNING id INTO v_contact_id;

    -- Create LinkedIn identity
    INSERT INTO crm_contact_identities (
      organization_id,
      contact_id,
      channel,
      platform_user_id,
      platform_username,
      platform_profile_url,
      platform_avatar_url,
      platform_metadata,
      linked_account_ids,
      raw_connection_data,
      is_primary
    ) VALUES (
      p_organization_id,
      v_contact_id,
      'linkedin',
      p_linkedin_id,
      v_display_name,
      p_linkedin_url,
      p_profile_picture_url,
      jsonb_build_object(
        'headline', p_headline,
        'company', p_company,
        'location', p_location
      ),
      ARRAY[p_account_id],
      jsonb_build_object(p_account_id::text, p_raw_data),
      true
    );

    -- Log activity
    INSERT INTO crm_activities (
      organization_id,
      contact_id,
      activity_type,
      title,
      description,
      metadata,
      performed_by_type
    ) VALUES (
      p_organization_id,
      v_contact_id,
      'contact_created',
      'LinkedIn connection synced',
      'Contact imported from LinkedIn connections',
      jsonb_build_object(
        'source', 'linkedin_connection',
        'account_id', p_account_id,
        'linkedin_id', p_linkedin_id,
        'connected_at', p_connected_at
      ),
      'system'
    );

    v_action := 'created';
  END IF;

  RETURN QUERY SELECT v_contact_id, v_action;
END;
$$;


ALTER FUNCTION "public"."sync_linkedin_connection_to_crm"("p_organization_id" "uuid", "p_account_id" "uuid", "p_linkedin_id" "text", "p_linkedin_url" "text", "p_first_name" "text", "p_last_name" "text", "p_full_name" "text", "p_headline" "text", "p_job_title" "text", "p_company" "text", "p_location" "text", "p_profile_picture_url" "text", "p_connected_at" timestamp with time zone, "p_raw_data" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."sync_linkedin_connection_to_crm"("p_organization_id" "uuid", "p_account_id" "uuid", "p_linkedin_id" "text", "p_linkedin_url" "text", "p_first_name" "text", "p_last_name" "text", "p_full_name" "text", "p_headline" "text", "p_job_title" "text", "p_company" "text", "p_location" "text", "p_profile_picture_url" "text", "p_connected_at" timestamp with time zone, "p_raw_data" "jsonb") IS 'Syncs a single LinkedIn connection to CRM contacts with deduplication';



CREATE OR REPLACE FUNCTION "public"."sync_mailboxes_to_domain_sendability"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NEW.sending_paused_at IS NOT NULL THEN
    UPDATE public.email_mailboxes
    SET status = 'paused', updated_at = now(),
      metadata = CASE WHEN coalesce(metadata->>'paused_reason', '') IN ('', 'domain_paused', 'domain_not_sendable')
        THEN coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
        'paused_reason', 'domain_paused', 'paused_at', now(),
        'domain_pause_previous_status', status, 'domain_pause_id', NEW.id::text)
        ELSE metadata END
    WHERE sending_domain_id = NEW.id AND status = 'ready';
  ELSIF NOT public.is_sending_domain_technically_unusable(NEW.id) THEN
    UPDATE public.email_mailboxes
    SET status = 'ready', updated_at = now(),
      metadata = coalesce(metadata, '{}'::jsonb) - 'paused_reason' - 'paused_at'
        - 'domain_pause_previous_status' - 'domain_pause_id'
    WHERE sending_domain_id = NEW.id AND status = 'paused'
      AND metadata->>'paused_reason' = 'domain_paused'
      AND metadata->>'domain_pause_previous_status' = 'ready'
      AND metadata->>'domain_pause_id' = NEW.id::text;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."sync_mailboxes_to_domain_sendability"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_public_signal_person_email_to_crm"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE'
     AND NEW.email IS NOT DISTINCT FROM OLD.email
     AND NEW.email_status IS NOT DISTINCT FROM OLD.email_status THEN
    RETURN NEW;
  END IF;

  IF NULLIF(btrim(COALESCE(NEW.email, '')), '') IS NULL
     OR NULLIF(btrim(COALESCE(NEW.linkedin_url, '')), '') IS NULL THEN
    RETURN NEW;
  END IF;

  UPDATE public.crm_contacts c
  SET
    primary_email = lower(btrim(NEW.email)),
    email_verification_status = CASE
      WHEN lower(COALESCE(NEW.email_status, '')) IN ('valid', 'verified') THEN 'valid'
      WHEN lower(COALESCE(NEW.email_status, '')) IN ('catch_all', 'catch-all') THEN 'catch_all'
      ELSE 'unknown'
    END,
    email_is_deliverable = lower(COALESCE(NEW.email_status, '')) IN ('valid', 'verified'),
    email_is_catch_all = lower(COALESCE(NEW.email_status, '')) IN ('catch_all', 'catch-all'),
    email_verified_at = CASE
      WHEN lower(COALESCE(NEW.email_status, '')) IN ('valid', 'verified')
        THEN COALESCE(c.email_verified_at, now())
      ELSE c.email_verified_at
    END,
    email_verification_source = COALESCE(c.email_verification_source, 'moltsets_signal'),
    enrichment_data = COALESCE(c.enrichment_data, '{}'::jsonb) || jsonb_build_object(
      'email_status', lower(COALESCE(NEW.email_status, 'unknown')),
      'email_source', 'public_signal_people',
      'public_signal_email_backfilled', true
    ),
    updated_at = now()
  FROM public.public_signal_auto_enroll_rules r
  WHERE r.organization_id = c.organization_id
    AND r.status = 'active'
    AND c.primary_linkedin_url = NEW.linkedin_url
    AND c.primary_email IS NULL
    AND (
      c.source = 'public_signal'
      OR COALESCE(c.discovery_metadata ->> 'source', '') = 'public_signal'
      OR COALESCE(c.source_details ->> 'public_signal_id', '') <> ''
    )
    AND NOT EXISTS (
      SELECT 1
      FROM public.crm_contacts existing
      WHERE existing.organization_id = c.organization_id
        AND lower(existing.primary_email) = lower(NEW.email)
        AND existing.id <> c.id
    );

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."sync_public_signal_person_email_to_crm"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_signal_crm_contacts_to_public_people"("p_lookback" interval DEFAULT '2 days'::interval) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_count integer := 0;
BEGIN
  WITH signal_companies AS (
    SELECT DISTINCT ON (lower(s.company_name))
           lower(s.company_name) AS company_key,
           s.domain
    FROM public.public_signals s
    WHERE s.published
    ORDER BY lower(s.company_name), s.signal_date DESC, s.quality_score DESC, s.created_at DESC
  ), candidates AS (
    SELECT
      lower(COALESCE(NULLIF(c.company_name, ''), c.company)) AS company_key,
      sc.domain,
      c.full_name,
      COALESCE(NULLIF(c.job_title, ''), c.title) AS title,
      split_part(split_part(
        regexp_replace(
          CASE WHEN btrim(c.primary_linkedin_url) ~* '^https?://'
               THEN btrim(c.primary_linkedin_url)
               ELSE 'https://' || btrim(c.primary_linkedin_url) END,
          '^http://', 'https://', 'i'),
        '?', 1), '#', 1) AS linkedin_url,
      COALESCE(NULLIF(c.primary_email, ''), NULLIF(c.email, '')) AS email,
      c.email_verification_status AS email_status
    FROM public.crm_contacts c
    JOIN signal_companies sc
      ON sc.company_key = lower(COALESCE(NULLIF(c.company_name, ''), c.company))
    WHERE c.organization_id = public.aca_house_org_id()
      AND (c.source LIKE 'signal\_%' OR c.tags @> ARRAY['buying-signal'])
      AND COALESCE(btrim(c.full_name), '') <> ''
      AND COALESCE(btrim(c.primary_linkedin_url), '') <> ''
      AND (p_lookback IS NULL
           OR c.created_at >= now() - p_lookback
           OR c.updated_at >= now() - p_lookback)
  ), eligible AS (
    SELECT DISTINCT ON (cd.company_key, cd.linkedin_url) cd.*
    FROM candidates cd
    WHERE public.signal_person_url_is_valid(cd.linkedin_url)
      AND NOT EXISTS (
        SELECT 1 FROM public.public_signal_people_takedowns td
        WHERE (td.scope = 'company' AND lower(td.company_key) = cd.company_key)
           OR (td.scope = 'person'  AND td.linkedin_url = cd.linkedin_url)
      )
    ORDER BY cd.company_key, cd.linkedin_url, (cd.email IS NOT NULL) DESC
  ), upserted AS (
    INSERT INTO public.public_signal_people AS pe
      (company_key, domain, full_name, title, linkedin_url,
       seniority_rank, source, email, email_status)
    SELECT e.company_key, e.domain, e.full_name, e.title, e.linkedin_url,
           GREATEST(public.signal_seniority_rank(e.title), 0),
           'crm_signal_sync', e.email, e.email_status
    FROM eligible e
    ON CONFLICT (company_key, linkedin_url) DO UPDATE SET
      email = COALESCE(NULLIF(pe.email, ''), EXCLUDED.email),
      email_status = CASE WHEN COALESCE(pe.email, '') = ''
                          THEN EXCLUDED.email_status ELSE pe.email_status END,
      title = COALESCE(NULLIF(pe.title, ''), EXCLUDED.title),
      seniority_rank = GREATEST(pe.seniority_rank, EXCLUDED.seniority_rank)
    WHERE COALESCE(NULLIF(pe.email, ''), '') = ''
       OR COALESCE(NULLIF(pe.title, ''), '') = ''
       OR pe.seniority_rank < EXCLUDED.seniority_rank
    RETURNING 1
  )
  SELECT count(*) INTO v_count FROM upserted;

  RETURN v_count;
END;
$$;


