CREATE OR REPLACE FUNCTION "public"."sync_unipile_campaign_status_from_is_active"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  -- Only fire when is_active changed but status was NOT also changed in the same UPDATE
  IF NEW.is_active IS DISTINCT FROM OLD.is_active AND NEW.status = OLD.status THEN
    NEW.status := CASE WHEN NEW.is_active = true THEN 'active' ELSE 'paused' END;
  END IF;
  RETURN NEW;
END;
$$;


