CREATE OR REPLACE FUNCTION "public"."toggle_conversation_favorite"("p_conversation_id" "uuid", "p_is_favorite" boolean DEFAULT NULL::boolean) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_id UUID;
  v_current_favorite BOOLEAN;
  v_new_favorite BOOLEAN;
BEGIN
  v_user_id := auth.uid();
  
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;
  
  -- Get current state
  SELECT is_favorite INTO v_current_favorite
  FROM conversation_preferences
  WHERE conversation_id = p_conversation_id AND user_id = v_user_id;
  
  -- Determine new state
  IF p_is_favorite IS NOT NULL THEN
    v_new_favorite := p_is_favorite;
  ELSE
    v_new_favorite := NOT COALESCE(v_current_favorite, false);
  END IF;
  
  -- Upsert preference
  INSERT INTO conversation_preferences (conversation_id, user_id, is_favorite)
  VALUES (p_conversation_id, v_user_id, v_new_favorite)
  ON CONFLICT (conversation_id, user_id)
  DO UPDATE SET
    is_favorite = v_new_favorite,
    updated_at = NOW();
  
  RETURN v_new_favorite;
END;
$$;


