CREATE OR REPLACE FUNCTION "public"."touch_crm_company_on_signal"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_domain TEXT;
BEGIN
  IF NEW.discovered_company_id IS NULL THEN RETURN NEW; END IF;
  SELECT domain INTO v_domain FROM public.lb_discovered_companies
   WHERE id = NEW.discovered_company_id LIMIT 1;
  IF v_domain IS NULL THEN RETURN NEW; END IF;

  UPDATE public.crm_companies
     SET last_signal_at = GREATEST(COALESCE(last_signal_at, NEW.created_at), NEW.created_at),
         updated_at = NOW()
   WHERE organization_id = NEW.organization_id
     AND normalized_domain = LOWER(REGEXP_REPLACE(TRIM(v_domain), '^(https?://)?(www\.)?([^/]+).*$', '\3'));
  RETURN NEW;
END;
$_$;


