CREATE OR REPLACE FUNCTION "public"."trg_warmup_send_rollup"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  -- Only recompute when something that feeds the rollup actually changed.
  -- Insert always counts (warmup_sends_total / last_send_at); updates only
  -- matter when status moves, which is the only thing that can shift warmup_day.
  IF TG_OP = 'INSERT'
     OR (TG_OP = 'UPDATE' AND NEW.status IS DISTINCT FROM OLD.status) THEN
    PERFORM public.recompute_warmup_day(NEW.from_mailbox_id);
  END IF;
  RETURN NULL;
END;
$$;


