  IF NEW.status = 'active' AND (OLD.status IS NULL OR OLD.status != 'active') THEN
    IF NOT EXISTS (
      SELECT 1 FROM campaign_lead_progress
      WHERE campaign_id = NEW.id
      LIMIT 1
    ) THEN
