CREATE OR REPLACE FUNCTION "public"."trigger_contact_webhook"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_event_type TEXT;
  v_event_data JSONB;
BEGIN
  IF NOT org_listens_for_webhook_event(
    NEW.organization_id,
    CASE WHEN TG_OP = 'INSERT' THEN ARRAY['contact_created']
         ELSE ARRAY['contact_updated', 'stage_changed', 'score_changed'] END
  ) THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'INSERT' THEN
    v_event_type := 'contact_created';
    v_event_data := jsonb_build_object(
      'contact_id', NEW.id,
      'display_name', NEW.display_name,
      'email', NEW.primary_email,
      'phone', NEW.primary_phone,
      'source', NEW.source,
      'source_campaign_id', NEW.source_campaign_id,
      'stage_id', NEW.stage_id,
      'lead_score', NEW.lead_score,
      'custom_fields', NEW.custom_fields,
      'created_at', NEW.created_at
    );
  ELSIF TG_OP = 'UPDATE' THEN
    IF OLD.stage_id IS DISTINCT FROM NEW.stage_id THEN
      PERFORM queue_webhook_event(
        NEW.organization_id,
        'stage_changed',
        jsonb_build_object(
          'contact_id', NEW.id,
          'display_name', NEW.display_name,
          'from_stage_id', OLD.stage_id,
          'to_stage_id', NEW.stage_id,
          'changed_at', now()
        )
      );
    END IF;

    IF OLD.lead_score IS DISTINCT FROM NEW.lead_score THEN
      PERFORM queue_webhook_event(
        NEW.organization_id,
        'score_changed',
        jsonb_build_object(
          'contact_id', NEW.id,
          'display_name', NEW.display_name,
          'old_score', OLD.lead_score,
          'new_score', NEW.lead_score,
          'changed_at', now()
        )
      );
    END IF;

    v_event_type := 'contact_updated';
    v_event_data := jsonb_build_object(
      'contact_id', NEW.id,
      'display_name', NEW.display_name,
      'email', NEW.primary_email,
      'phone', NEW.primary_phone,
      'stage_id', NEW.stage_id,
      'lead_score', NEW.lead_score,
      'updated_at', NEW.updated_at
    );
  END IF;

  PERFORM queue_webhook_event(NEW.organization_id, v_event_type, v_event_data);

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."trigger_contact_webhook"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."trigger_enrollment_webhook"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_event_type TEXT;
  v_org_id UUID;
  v_sequence_name TEXT;
  v_lead RECORD;
BEGIN
  IF NEW.status = 'completed' THEN
    v_event_type := 'sequence_completed';
  ELSIF NEW.status = 'replied' THEN
    v_event_type := 'lead_replied';
  ELSE
    RETURN NEW;
  END IF;

  SELECT organization_id, name INTO v_org_id, v_sequence_name
    FROM email_sequences WHERE id = NEW.sequence_id;

  v_org_id := COALESCE(v_org_id, NEW.organization_id);
  IF v_org_id IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT id, email, source_id INTO v_lead FROM leads WHERE id = NEW.lead_id;

  PERFORM queue_webhook_event(
    v_org_id,
    v_event_type,
    jsonb_build_object(
      'enrollment_id', NEW.id,
      'sequence_id', NEW.sequence_id,
      'sequence_name', v_sequence_name,
      'lead_id', NEW.lead_id,
      'contact_id', v_lead.source_id,
      'lead_email', v_lead.email,
      'current_step', NEW.current_step,
      'status', NEW.status,
      'changed_at', now()
    )
  );

  RETURN NEW;
END;
$$;


