CREATE OR REPLACE FUNCTION "public"."trigger_increment_usage_on_content_insert"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  -- Skip charging when the row is a hard-failed dispatch (no content generated).
  -- These rows exist only to surface the error in the UI; charging for them was
  -- the source of "credit consumed, no output produced" complaints.
  IF NEW.status = 'failed' AND NEW.data = '{}'::jsonb THEN
    RETURN NEW;
  END IF;

  PERFORM increment_organization_usage(
    NEW.organization_id,
    1,
    COALESCE(NEW.generation_cost, 0)
  );
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."trigger_increment_usage_on_content_insert"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."trigger_increment_usage_on_content_insert"() IS 'Increments organization usage on content_outputs insert. Skips hard-failed dispatch rows (status=failed AND empty data) so users are not charged for generations that produced nothing.';



CREATE OR REPLACE FUNCTION "public"."trigger_list_member_webhook"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_event_type TEXT;
  v_member RECORD;
  v_org_id UUID;
  v_list_name TEXT;
  v_contact RECORD;
BEGIN
  IF TG_OP = 'INSERT' THEN
    v_event_type := 'list_member_added';
    v_member := NEW;
  ELSE
    v_event_type := 'list_member_removed';
    v_member := OLD;
  END IF;

  SELECT organization_id, name INTO v_org_id, v_list_name
    FROM lead_lists WHERE id = v_member.list_id;

  IF v_org_id IS NULL THEN
    RETURN COALESCE(NEW, OLD);
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM webhook_subscriptions
     WHERE organization_id = v_org_id
       AND is_active = true
       AND v_event_type = ANY(events)
       AND webhook_subscription_matches(
             filters,
             v_event_type,
             jsonb_build_object('list_id', v_member.list_id)
           )
  ) AND NOT EXISTS (
    SELECT 1 FROM organization_webhook_settings
     WHERE organization_id = v_org_id
       AND is_active = true
       AND v_event_type = ANY(enabled_events)
       AND COALESCE(event_webhooks->>v_event_type, default_webhook_url, '') <> ''
  ) THEN
    RETURN COALESCE(NEW, OLD);
  END IF;

  SELECT display_name, primary_email, company, job_title
    INTO v_contact
    FROM crm_contacts WHERE id = v_member.contact_id;

  PERFORM queue_webhook_event(
    v_org_id,
    v_event_type,
    jsonb_build_object(
      'member_id', v_member.id,
      'list_id', v_member.list_id,
      'list_name', v_list_name,
      'contact_id', v_member.contact_id,
      'contact_name', v_contact.display_name,
      'contact_email', v_contact.primary_email,
      'company', v_contact.company,
      'job_title', v_contact.job_title,
      'added_at', v_member.added_at,
      'changed_at', now()
    )
  );

  RETURN COALESCE(NEW, OLD);
END;
$$;


ALTER FUNCTION "public"."trigger_list_member_webhook"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."trigger_list_member_webhook"() IS 'Emits list_member_added / list_member_removed. Returns before building a payload unless a destination is subscribed, because lead_list_members is written in bulk.';



