CREATE OR REPLACE FUNCTION "public"."trigger_signal_lead_webhook"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_source TEXT;
  v_org_id UUID;
  v_list_name TEXT;
  v_contact RECORD;
  v_dm JSONB;
  v_signal_id_text TEXT;
  v_signal_id UUID;
  v_investors TEXT;
  -- Scalars, not a RECORD. The signal lookup is conditional -- the
  -- custom-signal path has no public_signal_id -- and a RECORD that is only
  -- assigned inside the IF raises "record is not assigned yet" the moment the
  -- payload reads it. Scalars are simply NULL when the lookup is skipped.
  v_sig_company TEXT;
  v_sig_type TEXT;
  v_sig_date DATE;
  v_sig_title TEXT;
  v_sig_summary TEXT;
  v_sig_why TEXT;
  v_sig_url TEXT;
  v_sig_amount TEXT;
  v_sig_company_linkedin TEXT;
  v_sig_domain TEXT;
  v_sig_metadata JSONB;
  v_sig_industry TEXT;
  v_sig_employees TEXT;
  v_sig_revenue TEXT;
BEGIN
  v_source := NEW.source_data ->> 'source';

  -- Exit one: free. No lookups, no allocations, just the row already in hand.
  IF v_source IS NULL OR position('signal' in lower(v_source)) = 0 THEN
    RETURN NEW;
  END IF;

  SELECT organization_id, name INTO v_org_id, v_list_name
    FROM lead_lists WHERE id = NEW.list_id;

  IF v_org_id IS NULL THEN
    RETURN NEW;
  END IF;

  -- Exit two: nobody is listening. Same shape as trigger_list_member_webhook --
  -- build no payload unless a destination is actually waiting for the event.
  IF NOT EXISTS (
    SELECT 1 FROM webhook_subscriptions
     WHERE organization_id = v_org_id
       AND is_active = true
       AND 'signal_lead_added' = ANY(events)
  ) AND NOT EXISTS (
    SELECT 1 FROM organization_webhook_settings
     WHERE organization_id = v_org_id
       AND is_active = true
       AND 'signal_lead_added' = ANY(enabled_events)
       AND COALESCE(event_webhooks->>'signal_lead_added', default_webhook_url, '') <> ''
  ) THEN
    RETURN NEW;
  END IF;

  SELECT display_name, primary_email, primary_linkedin_url, company, job_title,
         COALESCE(discovery_metadata, '{}'::jsonb) AS discovery_metadata
    INTO v_contact
    FROM crm_contacts WHERE id = NEW.contact_id;

  v_dm := COALESCE(v_contact.discovery_metadata, '{}'::jsonb);

  -- `discovery_metadata` is the canonical signal store -- it is what
  -- generate-email-sequence, campaign-processor and the Fly sequence-sender all
  -- read, and both run_public_signal_auto_enroll() and
  -- list-building-signal-export write it under matching key names. The live
  -- public_signals row wins where it exists because the signal can have been
  -- corrected since the contact was stamped.
  v_signal_id_text := COALESCE(
    NEW.source_data ->> 'public_signal_id',
    v_dm ->> 'public_signal_id'
  );

  IF v_signal_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_signal_id := v_signal_id_text::uuid;

    SELECT s.company_name, s.signal_type, s.signal_date, s.title, s.summary,
           s.why_it_matters, s.source_url, s.amount_label, s.company_linkedin_url,
           s.domain, s.metadata,
           c.industry,
           COALESCE(c.employee_range,
                    public.signal_employee_band(c.employee_count, c.employee_range)),
           c.revenue_range
      INTO v_sig_company, v_sig_type, v_sig_date, v_sig_title, v_sig_summary,
           v_sig_why, v_sig_url, v_sig_amount, v_sig_company_linkedin,
           v_sig_domain, v_sig_metadata,
           v_sig_industry, v_sig_employees, v_sig_revenue
      FROM public_signals s
      LEFT JOIN public_signal_companies c
             ON c.company_key = lower(s.company_name)
     WHERE s.id = v_signal_id;

    IF jsonb_typeof(v_sig_metadata -> 'investors') = 'array' THEN
      SELECT NULLIF(string_agg(btrim(x), ', '), '')
        INTO v_investors
        FROM jsonb_array_elements_text(v_sig_metadata -> 'investors') x
       WHERE btrim(x) <> '';
    END IF;
  END IF;

  PERFORM queue_webhook_event(
    v_org_id,
    'signal_lead_added',
    jsonb_strip_nulls(jsonb_build_object(
      'member_id', NEW.id,
      'list_id', NEW.list_id,
      'list_name', v_list_name,
      'added_at', NEW.added_at,
      'contact_id', NEW.contact_id,
      'contact_name', v_contact.display_name,
      'contact_email', v_contact.primary_email,
      'contact_linkedin_url', v_contact.primary_linkedin_url,
      'company', COALESCE(v_sig_company, v_contact.company),
      'job_title', COALESCE(v_contact.job_title, NEW.source_data ->> 'contact_title'),
      'signal_source', v_source,
      'signal_id', v_signal_id,
      'signal_type', COALESCE(
        v_sig_type, v_dm ->> 'signal_type', NEW.source_data ->> 'signal_type'
      ),
      'signal_date', COALESCE(
        to_char(v_sig_date, 'YYYY-MM-DD'), v_dm ->> 'signal_date'
      ),
      'signal_title', NULLIF(btrim(COALESCE(v_sig_title, '')), ''),
      'signal_detail', COALESCE(
        NULLIF(btrim(COALESCE(v_sig_summary, '')), ''),
        NULLIF(btrim(COALESCE(v_sig_title, '')), ''),
        v_dm ->> 'signal_detail'
      ),
      'why_it_matters', COALESCE(
        NULLIF(btrim(COALESCE(v_sig_why, '')), ''),
        v_dm ->> 'signal_outreach_context',
        NEW.source_data ->> 'why'
      ),
      'signal_source_url', COALESCE(
        v_sig_url, v_dm ->> 'signal_source_url', NEW.source_data ->> 'source_url'
      ),
      'amount', COALESCE(
        NULLIF(btrim(COALESCE(v_sig_amount, '')), ''), v_dm ->> 'ai_signal_amount'
      ),
      'investors', COALESCE(v_investors, v_dm ->> 'ai_signal_investors'),
      'company_domain', v_sig_domain,
      'company_website', COALESCE(
        CASE WHEN COALESCE(v_sig_domain, '') <> '' THEN 'https://' || v_sig_domain END,
        v_dm ->> 'ai_signal_company_website'
      ),
      'company_linkedin', COALESCE(
        v_sig_company_linkedin, v_dm ->> 'ai_signal_company_linkedin'
      ),
      'company_industry', COALESCE(v_sig_industry, v_dm ->> 'ai_signal_company_industry'),
      'company_employee_range', COALESCE(
        v_sig_employees, v_dm ->> 'company_employee_range'
      ),
      'company_revenue_range', COALESCE(
        v_sig_revenue, v_dm ->> 'company_revenue_range'
      ),
      'auto_enroll_rule_id', NEW.source_data ->> 'auto_enroll_rule_id',
      'signal_subscription_id', NEW.source_data ->> 'signal_subscription_id',
      'discovery_metadata', NULLIF(v_dm, '{}'::jsonb)
    ))
  );

  RETURN NEW;
END;
$_$;


