CREATE OR REPLACE FUNCTION "public"."trigger_tag_webhook"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_event_type TEXT;
  v_event_data JSONB;
  v_contact RECORD;
  v_tag RECORD;
BEGIN
  SELECT * INTO v_contact FROM crm_contacts WHERE id = COALESCE(NEW.contact_id, OLD.contact_id);
  SELECT * INTO v_tag FROM crm_tags WHERE id = COALESCE(NEW.tag_id, OLD.tag_id);

  IF TG_OP = 'INSERT' THEN
    v_event_type := 'tag_added';
    v_event_data := jsonb_build_object(
      'contact_id', NEW.contact_id,
      'contact_name', v_contact.display_name,
      'tag_id', NEW.tag_id,
      'tag_name', v_tag.name,
      'tag_color', v_tag.color,
      'added_at', NEW.added_at
    );
    PERFORM queue_webhook_event(v_contact.organization_id, v_event_type, v_event_data);
  ELSIF TG_OP = 'DELETE' THEN
    v_event_type := 'tag_removed';
    v_event_data := jsonb_build_object(
      'contact_id', OLD.contact_id,
      'contact_name', v_contact.display_name,
      'tag_id', OLD.tag_id,
      'tag_name', v_tag.name,
      'removed_at', now()
    );
    PERFORM queue_webhook_event(v_contact.organization_id, v_event_type, v_event_data);
  END IF;

  RETURN COALESCE(NEW, OLD);
END;
$$;


