CREATE OR REPLACE FUNCTION "public"."try_claim_mailtester_job"("p_job_id" "uuid", "p_lease_seconds" integer, "p_token" "uuid") RETURNS boolean
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_org_id uuid;
BEGIN
  SELECT organization_id INTO v_org_id
    FROM public.mailtester_verification_jobs
   WHERE id = p_job_id;
  IF v_org_id IS NULL THEN
    RETURN FALSE;
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.mailtester_verification_jobs
     WHERE organization_id = v_org_id
       AND id <> p_job_id
       AND status IN ('queued','running')
       AND last_tick_at IS NOT NULL
       AND last_tick_at >= now() - make_interval(secs => p_lease_seconds)
  ) THEN
    RETURN FALSE;
  END IF;

  UPDATE public.mailtester_verification_jobs
     SET last_tick_at = now(),
         locked_by    = p_token,
         status       = CASE WHEN status = 'queued' THEN 'running' ELSE status END,
         started_at   = COALESCE(started_at, now())
   WHERE id = p_job_id
     AND status IN ('queued','running')
     AND (retry_after IS NULL OR retry_after <= now())
     AND (last_tick_at IS NULL OR last_tick_at < now() - make_interval(secs => p_lease_seconds));

  RETURN FOUND;
END;
$$;


ALTER FUNCTION "public"."try_claim_mailtester_job"("p_job_id" "uuid", "p_lease_seconds" integer, "p_token" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."try_increment_enrichment_daily_usage"("p_organization_id" "uuid", "p_provider" "text", "p_daily_cap" integer) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_lock_key BIGINT;
  v_current_count INT;
BEGIN
  v_lock_key := ('x' || left(md5(p_organization_id::text || p_provider), 15))::bit(60)::bigint;
  PERFORM pg_advisory_xact_lock(v_lock_key);

  INSERT INTO enrichment_provider_daily_usage (organization_id, provider, usage_date, request_count, daily_cap)
  VALUES (p_organization_id, p_provider, CURRENT_DATE, 0, p_daily_cap)
  ON CONFLICT (organization_id, provider, usage_date)
  DO UPDATE SET daily_cap = EXCLUDED.daily_cap;

  SELECT request_count INTO v_current_count
  FROM enrichment_provider_daily_usage
  WHERE organization_id = p_organization_id
    AND provider = p_provider
    AND usage_date = CURRENT_DATE;

  IF v_current_count < p_daily_cap THEN
    UPDATE enrichment_provider_daily_usage
    SET request_count = request_count + 1
    WHERE organization_id = p_organization_id
      AND provider = p_provider
      AND usage_date = CURRENT_DATE;
    RETURN true;
  END IF;

  RETURN false;
END;
$$;


ALTER FUNCTION "public"."try_increment_enrichment_daily_usage"("p_organization_id" "uuid", "p_provider" "text", "p_daily_cap" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."unsnooze_expired_conversations"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  affected INTEGER;
BEGIN
  UPDATE public.crm_conversations
  SET status = 'open',
      snoozed_until = NULL,
      snooze_type = 'timed',
      snooze_context = '{}'::JSONB,
      updated_at = NOW()
  WHERE status = 'snoozed'
    AND snoozed_until IS NOT NULL
    AND snoozed_until <= NOW();

  GET DIAGNOSTICS affected = ROW_COUNT;
  RETURN affected;
END;
$$;


