CREATE OR REPLACE FUNCTION "public"."update_bulk_job_progress"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
DECLARE
  v_total_count INTEGER;
  v_completed_count INTEGER;
  v_failed_count INTEGER;
  v_done_count INTEGER;
BEGIN
  IF NEW.status IN ('completed', 'failed') AND (OLD.status IS NULL OR OLD.status != NEW.status) THEN
    SELECT total_count INTO v_total_count
    FROM bulk_generation_jobs WHERE id = NEW.job_id;

    SELECT
      COUNT(*) FILTER (WHERE status = 'completed'),
      COUNT(*) FILTER (WHERE status = 'failed'),
      COUNT(*) FILTER (WHERE status IN ('completed', 'failed', 'cancelled'))
    INTO v_completed_count, v_failed_count, v_done_count
    FROM bulk_generation_items WHERE job_id = NEW.job_id;

    UPDATE bulk_generation_jobs
    SET
      completed_count = v_completed_count,
      failed_count = v_failed_count,
      status = CASE
        WHEN v_done_count >= v_total_count THEN 'completed'
        WHEN status = 'running' THEN 'running'
        ELSE status
      END,
      completed_at = CASE
        WHEN v_done_count >= v_total_count THEN NOW()
        ELSE completed_at
      END,
      updated_at = NOW()
    WHERE id = NEW.job_id;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."update_bulk_job_progress"() OWNER TO "postgres";


