CREATE OR REPLACE FUNCTION "public"."update_bulk_script_batch_progress"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
BEGIN
  -- Update completed/failed counts and overall status
  UPDATE bulk_script_batches
  SET
    completed_count = (
      SELECT COUNT(*) FROM bulk_script_jobs
      WHERE batch_id = NEW.batch_id AND status = 'completed'
    ),
    failed_count = (
      SELECT COUNT(*) FROM bulk_script_jobs
      WHERE batch_id = NEW.batch_id AND status = 'failed'
    ),
    status = CASE
      WHEN (SELECT COUNT(*) FROM bulk_script_jobs WHERE batch_id = NEW.batch_id AND status IN ('completed', 'failed')) = total_scripts
      THEN 'completed'
      WHEN (SELECT COUNT(*) FROM bulk_script_jobs WHERE batch_id = NEW.batch_id AND status = 'processing') > 0
      THEN 'processing'
      ELSE status
    END,
    completed_at = CASE
      WHEN (SELECT COUNT(*) FROM bulk_script_jobs WHERE batch_id = NEW.batch_id AND status IN ('completed', 'failed')) = total_scripts
      THEN NOW()
      ELSE completed_at
    END,
    updated_at = NOW()
  WHERE id = NEW.batch_id;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."update_bulk_script_batch_progress"() OWNER TO "postgres";


