CREATE OR REPLACE FUNCTION "public"."update_campaign_metrics"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_total INTEGER;
  v_processed INTEGER;
  v_contacted INTEGER;
  v_replied INTEGER;
  v_connection_rate DECIMAL;
  v_campaign_id UUID;
BEGIN
  v_campaign_id := COALESCE(NEW.campaign_id, OLD.campaign_id);

  SELECT
    COUNT(*),
    COUNT(*) FILTER (WHERE status IN ('completed', 'replied', 'failed', 'skipped')),
    COUNT(*) FILTER (WHERE connection_sent_at IS NOT NULL OR last_message_at IS NOT NULL),
    COUNT(*) FILTER (WHERE status = 'replied')
  INTO v_total, v_processed, v_contacted, v_replied
  FROM public.campaign_lead_progress
  WHERE campaign_id = v_campaign_id
    AND is_test_contact = FALSE;

  SELECT
    CASE
      WHEN COUNT(*) FILTER (WHERE connection_sent_at IS NOT NULL) > 0
      THEN (COUNT(*) FILTER (WHERE connection_accepted_at IS NOT NULL)::DECIMAL /
            COUNT(*) FILTER (WHERE connection_sent_at IS NOT NULL) * 100)
      ELSE 0
    END
  INTO v_connection_rate
  FROM public.campaign_lead_progress
  WHERE campaign_id = v_campaign_id
    AND is_test_contact = FALSE;

  UPDATE public.linkedin_campaigns
  SET
    total_leads = v_total,
    processed_leads = v_processed,
    contacted_leads = v_contacted,
    replied_count = v_replied,
    connection_rate = v_connection_rate,
    updated_at = NOW()
  WHERE id = v_campaign_id;

  RETURN COALESCE(NEW, OLD);
END;
$$;


ALTER FUNCTION "public"."update_campaign_metrics"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_campaign_metrics_stmt"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_campaign_ids uuid[];
BEGIN
  -- Each event only has its own transition tables, and plpgsql plans a
  -- statement on first execution, so each branch names only what exists.
  IF TG_OP = 'INSERT' THEN
    SELECT array_agg(DISTINCT campaign_id) INTO v_campaign_ids
    FROM new_rows WHERE campaign_id IS NOT NULL;
  ELSIF TG_OP = 'UPDATE' THEN
    SELECT array_agg(DISTINCT campaign_id) INTO v_campaign_ids
    FROM (SELECT campaign_id FROM new_rows UNION SELECT campaign_id FROM old_rows) changed
    WHERE campaign_id IS NOT NULL;
  ELSE
    SELECT array_agg(DISTINCT campaign_id) INTO v_campaign_ids
    FROM old_rows WHERE campaign_id IS NOT NULL;
  END IF;

  IF v_campaign_ids IS NULL THEN
    RETURN NULL;
  END IF;

  UPDATE public.linkedin_campaigns lc
  SET total_leads     = m.total,
      processed_leads = m.processed,
      contacted_leads = m.contacted,
      replied_count   = m.replied,
      connection_rate = m.connection_rate,
      updated_at      = NOW()
  FROM (
    SELECT
      c.id AS campaign_id,
      COUNT(p.id) AS total,
      COUNT(p.id) FILTER (WHERE p.status IN ('completed', 'replied', 'failed', 'skipped')) AS processed,
      COUNT(p.id) FILTER (WHERE p.connection_sent_at IS NOT NULL OR p.last_message_at IS NOT NULL) AS contacted,
      COUNT(p.id) FILTER (WHERE p.status = 'replied') AS replied,
      CASE
        WHEN COUNT(p.id) FILTER (WHERE p.connection_sent_at IS NOT NULL) > 0
        THEN COUNT(p.id) FILTER (WHERE p.connection_accepted_at IS NOT NULL)::DECIMAL
             / COUNT(p.id) FILTER (WHERE p.connection_sent_at IS NOT NULL) * 100
        ELSE 0
      END AS connection_rate
    FROM unnest(v_campaign_ids) AS c(id)
    LEFT JOIN public.campaign_lead_progress p
      ON p.campaign_id = c.id
     AND p.is_test_contact = FALSE
    GROUP BY c.id
  ) m
  WHERE lc.id = m.campaign_id;

  RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."update_campaign_metrics_stmt"() OWNER TO "postgres";


