CREATE OR REPLACE FUNCTION "public"."update_clip_video"("p_output_id" "uuid", "p_stage_id" "text", "p_scene_number" integer, "p_video_url" "text", "p_status" "text", "p_completed_at" "text", "p_metrics" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_clips JSONB;
  v_updated_clips JSONB;
  v_clip JSONB;
  v_idx INT;
BEGIN
  -- Get current clips array
  SELECT stage_data->p_stage_id->'clips'
  INTO v_clips
  FROM public.content_outputs
  WHERE id = p_output_id;

  IF v_clips IS NULL THEN
    RAISE EXCEPTION 'No clips found for stage %', p_stage_id;
  END IF;

  -- Find and update the specific clip
  v_updated_clips := '[]'::jsonb;
  FOR v_idx IN 0..jsonb_array_length(v_clips) - 1 LOOP
    v_clip := v_clips->v_idx;
    IF (v_clip->>'scene_number')::int = p_scene_number THEN
      v_clip := v_clip || jsonb_build_object(
        'video_url', p_video_url,
        'status', p_status,
        'completed_at', p_completed_at,
        'metrics', p_metrics
      );
    END IF;
    v_updated_clips := v_updated_clips || jsonb_build_array(v_clip);
  END LOOP;

  -- Update the stage_data with the modified clips array
  UPDATE public.content_outputs
  SET stage_data = jsonb_set(
    stage_data,
    ARRAY[p_stage_id, 'clips'],
    v_updated_clips
  )
  WHERE id = p_output_id;
END;
$$;


