CREATE OR REPLACE FUNCTION "public"."update_contact_outreach_status"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  -- When a conversation gets a new message, update the contact's outreach status
  IF NEW.message_count > 0 AND (OLD.message_count IS NULL OR OLD.message_count = 0) THEN
    -- First outbound message sent
    UPDATE crm_contacts
    SET outreach_status = CASE
      WHEN outreach_status = 'unreached' THEN 'reached'
      ELSE outreach_status
    END
    WHERE id = NEW.contact_id;
  END IF;

  -- If they replied (inbound message received) — but never from system
  -- conversations (bounces/NDRs/noreply), which are not genuine replies.
  IF NEW.last_message_direction = 'inbound'
     AND COALESCE(NEW.is_system, FALSE) = FALSE
     AND (OLD.last_message_direction IS NULL OR OLD.last_message_direction = 'outbound') THEN
    UPDATE crm_contacts
    SET outreach_status = 'replied'
    WHERE id = NEW.contact_id;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."update_contact_outreach_status"() OWNER TO "postgres";


