CREATE OR REPLACE FUNCTION "public"."update_conversation_on_message"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  UPDATE crm_conversations SET
    message_count = message_count + 1,
    unread_count = CASE WHEN NEW.direction = 'inbound' THEN unread_count + 1 ELSE unread_count END,
    has_inbound_message = CASE WHEN NEW.direction = 'inbound' THEN true ELSE has_inbound_message END,
    has_outbound_message = CASE WHEN NEW.direction = 'outbound' THEN true ELSE has_outbound_message END,
    last_message_at = GREATEST(NEW.created_at, NOW()),
    last_message_preview = LEFT(COALESCE(strip_html_to_text(NEW.content), ''), 100),
    last_message_subject = NEW.email_subject,
    last_message_direction = NEW.direction,
    status = CASE WHEN status = 'closed' AND NEW.direction = 'inbound' THEN 'open' ELSE status END,
    updated_at = NOW()
  WHERE id = NEW.conversation_id;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."update_conversation_on_message"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_conversation_on_message"("p_conversation_id" "uuid", "p_organization_id" "uuid", "p_last_message_preview" "text", "p_direction" "text" DEFAULT 'outbound'::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  UPDATE crm_conversations
  SET
    last_message_at = now(),
    last_message_preview = p_last_message_preview,
    last_message_direction = p_direction,
    message_count = COALESCE(message_count, 0) + 1,
    updated_at = now()
  WHERE id = p_conversation_id
    AND organization_id = p_organization_id;
END;
$$;


