CREATE OR REPLACE FUNCTION "public"."update_creator_content_count"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
BEGIN
  IF TG_OP = 'INSERT' OR TG_OP = 'UPDATE' THEN
    IF NEW.creator_id IS NOT NULL THEN
      UPDATE research_creators
      SET total_content_items = (
        SELECT COUNT(*) FROM (
          SELECT id FROM research_youtube_videos WHERE creator_id = NEW.creator_id
          UNION ALL
          SELECT id FROM research_tiktok_videos WHERE creator_id = NEW.creator_id
          UNION ALL
          SELECT id FROM research_instagram_posts WHERE creator_id = NEW.creator_id
          UNION ALL
          SELECT id FROM research_linkedin_posts WHERE creator_id = NEW.creator_id
        ) AS all_content
      ),
      updated_at = NOW()
      WHERE id = NEW.creator_id;
    END IF;
  ELSIF TG_OP = 'DELETE' THEN
    IF OLD.creator_id IS NOT NULL THEN
      UPDATE research_creators
      SET total_content_items = (
        SELECT COUNT(*) FROM (
          SELECT id FROM research_youtube_videos WHERE creator_id = OLD.creator_id
          UNION ALL
          SELECT id FROM research_tiktok_videos WHERE creator_id = OLD.creator_id
          UNION ALL
          SELECT id FROM research_instagram_posts WHERE creator_id = OLD.creator_id
          UNION ALL
          SELECT id FROM research_linkedin_posts WHERE creator_id = OLD.creator_id
        ) AS all_content
      ),
      updated_at = NOW()
      WHERE id = OLD.creator_id;
    END IF;
  END IF;

  RETURN NULL;
END;
$$;


