CREATE OR REPLACE FUNCTION "public"."update_job_counts"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
BEGIN
  -- Update completed_count and failed_count in bulk_generation_jobs
  IF TG_OP = 'UPDATE' THEN
    -- If item just completed
    IF OLD.status != 'completed' AND NEW.status = 'completed' THEN
      UPDATE public.bulk_generation_jobs
      SET completed_count = completed_count + 1
      WHERE id = NEW.job_id;
    END IF;

    -- If item just failed
    IF OLD.status != 'failed' AND NEW.status = 'failed' THEN
      UPDATE public.bulk_generation_jobs
      SET failed_count = failed_count + 1
      WHERE id = NEW.job_id;
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


