  UPDATE public.lead_lists ll
  SET lead_count = GREATEST(0, lead_count - batch_counts.cnt),
      updated_at = NOW()
  FROM (
    SELECT list_id, COUNT(*) AS cnt
    FROM deleted
    GROUP BY list_id
  ) AS batch_counts
  WHERE ll.id = batch_counts.list_id;
  RETURN NULL;
END;
