CREATE OR REPLACE FUNCTION "public"."update_scene_image"("p_output_id" "uuid", "p_stage_id" "text", "p_scene_number" integer, "p_image_url" "text", "p_status" "text", "p_completed_at" "text", "p_metrics" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_scenes JSONB;
  v_updated_scenes JSONB;
  v_scene JSONB;
  v_idx INT;
BEGIN
  -- Get current scenes array
  SELECT stage_data->p_stage_id->'scenes'
  INTO v_scenes
  FROM public.content_outputs
  WHERE id = p_output_id;

  IF v_scenes IS NULL THEN
    RAISE EXCEPTION 'No scenes found for stage %', p_stage_id;
  END IF;

  -- Find and update the specific scene
  v_updated_scenes := '[]'::jsonb;
  FOR v_idx IN 0..jsonb_array_length(v_scenes) - 1 LOOP
    v_scene := v_scenes->v_idx;
    IF (v_scene->>'scene_number')::int = p_scene_number THEN
      v_scene := v_scene || jsonb_build_object(
        'image_url', p_image_url,
        'status', p_status,
        'completed_at', p_completed_at,
        'metrics', p_metrics
      );
    END IF;
    v_updated_scenes := v_updated_scenes || jsonb_build_array(v_scene);
  END LOOP;

  -- Update the stage_data with the modified scenes array
  UPDATE public.content_outputs
  SET stage_data = jsonb_set(
    stage_data,
    ARRAY[p_stage_id, 'scenes'],
    v_updated_scenes
  )
  WHERE id = p_output_id;
END;
$$;


ALTER FUNCTION "public"."update_scene_image"("p_output_id" "uuid", "p_stage_id" "text", "p_scene_number" integer, "p_image_url" "text", "p_status" "text", "p_completed_at" "text", "p_metrics" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_scene_narration_duration"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
BEGIN
  IF NEW.narration IS DISTINCT FROM OLD.narration OR NEW.narration_word_count IS DISTINCT FROM OLD.narration_word_count THEN
    -- Calculate word count if not provided
    IF NEW.narration_word_count IS NULL THEN
      NEW.narration_word_count := array_length(regexp_split_to_array(trim(NEW.narration), '\s+'), 1);
    END IF;

    -- Calculate duration
    NEW.narration_duration := calculate_scene_duration(NEW.narration_word_count);
  END IF;

  RETURN NEW;
END;
$$;


