CREATE OR REPLACE FUNCTION "public"."update_schedule_after_run"("schedule_uuid" "uuid", "success" boolean, "error_msg" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
DECLARE
  current_schedule RECORD;
  new_failures INTEGER;
BEGIN
  SELECT * INTO current_schedule FROM scrape_schedules WHERE id = schedule_uuid;

  IF NOT FOUND THEN
    RETURN;
  END IF;

  -- Calculate new failure count
  IF success THEN
    new_failures := 0;
  ELSE
    new_failures := current_schedule.consecutive_failures + 1;
  END IF;

  -- Update schedule
  UPDATE scrape_schedules SET
    last_run_at = NOW(),
    next_run_at = calculate_next_run(
      current_schedule.frequency_type,
      current_schedule.cron_expression,
      NOW()
    ),
    consecutive_failures = new_failures,
    is_active = CASE
      WHEN current_schedule.auto_pause_on_failure AND new_failures >= 3 THEN false
      ELSE current_schedule.is_active
    END,
    updated_at = NOW()
  WHERE id = schedule_uuid;
END;
$$;


ALTER FUNCTION "public"."update_schedule_after_run"("schedule_uuid" "uuid", "success" boolean, "error_msg" "text") OWNER TO "postgres";


