    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
DECLARE
  total_duration INTEGER;
BEGIN
  -- Sum all scene durations
  SELECT COALESCE(SUM(narration_duration), 0)
  INTO total_duration
  FROM script_scenes
  WHERE script_id = script_uuid;

  -- Update script
  UPDATE youtube_scripts
  SET estimated_duration = total_duration,
      updated_at = NOW()
  WHERE id = script_uuid;
END;
$$;


