CREATE OR REPLACE FUNCTION "public"."update_variant_stats_on_status_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  -- Only process if variant_id is set
  IF NEW.variant_id IS NULL THEN
    RETURN NEW;
  END IF;

  -- On status transitions, increment the appropriate variant counter
  -- opened: increment opened (only on first transition to opened)
  IF NEW.status = 'opened' AND (OLD.status IS DISTINCT FROM 'opened' AND OLD.status IS DISTINCT FROM 'clicked') THEN
    UPDATE public.email_ab_variants SET opened = opened + 1 WHERE id = NEW.variant_id;
  END IF;

  -- clicked: increment clicked (and opened if not yet counted)
  IF NEW.status = 'clicked' AND OLD.status IS DISTINCT FROM 'clicked' THEN
    UPDATE public.email_ab_variants SET clicked = clicked + 1 WHERE id = NEW.variant_id;
    -- If we jumped straight to clicked without passing through opened
    IF OLD.status NOT IN ('opened', 'clicked') THEN
      UPDATE public.email_ab_variants SET opened = opened + 1 WHERE id = NEW.variant_id;
    END IF;
  END IF;

  -- replied: increment replied
  IF NEW.status = 'replied' AND OLD.status IS DISTINCT FROM 'replied' THEN
    UPDATE public.email_ab_variants SET replied = replied + 1 WHERE id = NEW.variant_id;
  END IF;

  -- bounced: increment bounced
  IF NEW.status = 'bounced' AND OLD.status IS DISTINCT FROM 'bounced' THEN
    UPDATE public.email_ab_variants SET bounced = bounced + 1 WHERE id = NEW.variant_id;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."update_variant_stats_on_status_change"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."upgrade_contact_type_on_connection"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  -- If is_linkedin_connection changed from false to true, upgrade to contact
  IF OLD.is_linkedin_connection IS DISTINCT FROM NEW.is_linkedin_connection
     AND NEW.is_linkedin_connection = true
     AND NEW.contact_type != 'contact' THEN
    NEW.contact_type := 'contact';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."upgrade_contact_type_on_connection"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."upsert_enrollment_with_cycle"("p_sequence_id" "uuid", "p_lead_id" "uuid", "p_organization_id" "uuid", "p_custom_data" "jsonb" DEFAULT NULL::"jsonb", "p_next_send_at" timestamp with time zone DEFAULT "now"(), "p_mailbox_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("enrollment_id" "uuid", "cycle_number" integer, "is_reenrollment" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_enrollment_id UUID;
  v_cycle_number INT;
  v_is_reenrollment BOOLEAN;
BEGIN
  INSERT INTO email_sequence_enrollments (
    sequence_id, lead_id, organization_id, current_step, status,
    next_send_at, custom_data, cycle_number, mailbox_id
  )
  VALUES (
    p_sequence_id, p_lead_id, p_organization_id, 0, 'active',
    p_next_send_at, p_custom_data, 1, p_mailbox_id
  )
  ON CONFLICT (sequence_id, lead_id) DO UPDATE SET
    current_step = 0,
    status = 'active',
    next_send_at = EXCLUDED.next_send_at,
    custom_data = EXCLUDED.custom_data,
    cycle_number = email_sequence_enrollments.cycle_number + 1,
    mailbox_id = COALESCE(EXCLUDED.mailbox_id, email_sequence_enrollments.mailbox_id),
    organization_id = COALESCE(EXCLUDED.organization_id, email_sequence_enrollments.organization_id),
    updated_at = now()
  RETURNING id, email_sequence_enrollments.cycle_number, (xmax != 0)
  INTO v_enrollment_id, v_cycle_number, v_is_reenrollment;

  RETURN QUERY SELECT v_enrollment_id, v_cycle_number, v_is_reenrollment;
END;
$$;


ALTER FUNCTION "public"."upsert_enrollment_with_cycle"("p_sequence_id" "uuid", "p_lead_id" "uuid", "p_organization_id" "uuid", "p_custom_data" "jsonb", "p_next_send_at" timestamp with time zone, "p_mailbox_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."upsert_verified_person"("p" "jsonb") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
declare
  v_li text;
  v_domain text;
  v_company_payload jsonb;
  v_person_payload jsonb;
begin
  v_li := lower(regexp_replace(regexp_replace(coalesce(p->>'linkedin_url',''),
            '^https?://', ''), '/+$', ''));
  if v_li = '' then
    return null;
  end if;

  v_domain := nullif(lower(coalesce(p->>'company_domain','')), '');
  v_company_payload := case
    when jsonb_typeof(p->'moltsets_company_payload') = 'object'
      then p->'moltsets_company_payload'
    else '{}'::jsonb
  end;
  v_person_payload := case
    when jsonb_typeof(p->'moltsets_payload') = 'object'
      then p->'moltsets_payload'
    else '{}'::jsonb
  end;

  if v_domain is not null then
    insert into public.lead_pool_verified (
      domain, company_name, employee_count, employee_range, revenue_range,
      linkedin_industry, company_linkedin_url, company_country, company_state,
      company_city, moltsets_company_payload, moltsets_status,
      moltsets_checked_at
    ) values (
      v_domain,
      nullif(p->>'company_name',''),
      nullif(p->>'employee_count','')::int,
      nullif(p->>'employee_range',''),
      nullif(p->>'revenue_range',''),
      nullif(p->>'linkedin_industry',''),
      nullif(p->>'company_linkedin_url',''),
      nullif(p->>'company_country',''),
      nullif(p->>'company_state',''),
      nullif(p->>'company_city',''),
      v_company_payload,
      'found',
      now()
    )
    on conflict (domain) do update set
      company_name = coalesce(excluded.company_name, lead_pool_verified.company_name),
      employee_count = coalesce(excluded.employee_count, lead_pool_verified.employee_count),
      employee_range = coalesce(excluded.employee_range, lead_pool_verified.employee_range),
      revenue_range = coalesce(excluded.revenue_range, lead_pool_verified.revenue_range),
      linkedin_industry = coalesce(excluded.linkedin_industry, lead_pool_verified.linkedin_industry),
      company_linkedin_url = coalesce(excluded.company_linkedin_url, lead_pool_verified.company_linkedin_url),
      company_country = coalesce(excluded.company_country, lead_pool_verified.company_country),
      company_state = coalesce(excluded.company_state, lead_pool_verified.company_state),
      company_city = coalesce(excluded.company_city, lead_pool_verified.company_city),
      moltsets_company_payload = lead_pool_verified.moltsets_company_payload || excluded.moltsets_company_payload,
      moltsets_status = 'found',
      moltsets_checked_at = now();
  end if;

  insert into public.lead_pool_person_verified (
    linkedin_url, first_name, last_name, full_name, title, headline, seniority,
    city, state, country, company_domain, company_name, company_linkedin_url,
    company_country, company_state, company_city,
    business_email, business_email_validated_at, business_email_risk,
    personal_email, personal_email_validated_at, personal_email_risk,
    source_updated_at, moltsets_payload, status, checked_at
  ) values (
    v_li,
    nullif(p->>'first_name',''),
    nullif(p->>'last_name',''),
    nullif(p->>'full_name',''),
    nullif(p->>'title',''),
    nullif(p->>'headline',''),
    nullif(p->>'seniority',''),
    nullif(p->>'city',''),
    nullif(p->>'state',''),
    nullif(p->>'country',''),
    v_domain,
    nullif(p->>'company_name',''),
    nullif(p->>'company_linkedin_url',''),
    nullif(p->>'company_country',''),
    nullif(p->>'company_state',''),
    nullif(p->>'company_city',''),
    nullif(p->>'business_email',''),
    nullif(p->>'business_email_validated_at','')::date,
    nullif(p->>'business_email_risk',''),
    nullif(p->>'personal_email',''),
    nullif(p->>'personal_email_validated_at','')::date,
    nullif(p->>'personal_email_risk',''),
    nullif(p->>'source_updated_at','')::timestamptz,
    v_person_payload,
    coalesce(nullif(p->>'status',''), 'found'),
    now()
  )
  on conflict (linkedin_url) do update set
    first_name = coalesce(excluded.first_name, lead_pool_person_verified.first_name),
    last_name = coalesce(excluded.last_name, lead_pool_person_verified.last_name),
    full_name = coalesce(excluded.full_name, lead_pool_person_verified.full_name),
    title = coalesce(excluded.title, lead_pool_person_verified.title),
    headline = coalesce(excluded.headline, lead_pool_person_verified.headline),
    seniority = coalesce(excluded.seniority, lead_pool_person_verified.seniority),
    city = coalesce(excluded.city, lead_pool_person_verified.city),
    state = coalesce(excluded.state, lead_pool_person_verified.state),
    country = coalesce(excluded.country, lead_pool_person_verified.country),
    company_domain = coalesce(excluded.company_domain, lead_pool_person_verified.company_domain),
    company_name = coalesce(excluded.company_name, lead_pool_person_verified.company_name),
    company_linkedin_url = coalesce(excluded.company_linkedin_url, lead_pool_person_verified.company_linkedin_url),
    company_country = coalesce(excluded.company_country, lead_pool_person_verified.company_country),
    company_state = coalesce(excluded.company_state, lead_pool_person_verified.company_state),
    company_city = coalesce(excluded.company_city, lead_pool_person_verified.company_city),
    business_email = coalesce(excluded.business_email, lead_pool_person_verified.business_email),
    business_email_validated_at = coalesce(excluded.business_email_validated_at, lead_pool_person_verified.business_email_validated_at),
    business_email_risk = coalesce(excluded.business_email_risk, lead_pool_person_verified.business_email_risk),
    personal_email = coalesce(excluded.personal_email, lead_pool_person_verified.personal_email),
    personal_email_validated_at = coalesce(excluded.personal_email_validated_at, lead_pool_person_verified.personal_email_validated_at),
    personal_email_risk = coalesce(excluded.personal_email_risk, lead_pool_person_verified.personal_email_risk),
    source_updated_at = coalesce(excluded.source_updated_at, lead_pool_person_verified.source_updated_at),
    moltsets_payload = lead_pool_person_verified.moltsets_payload || excluded.moltsets_payload,
    status = excluded.status,
    checked_at = now();

  return v_li;
end;
$_$;


ALTER FUNCTION "public"."upsert_verified_person"("p" "jsonb") OWNER TO "postgres";


