CREATE OR REPLACE FUNCTION "public"."users_guard_can_use_org"("p_user" "uuid", "p_org" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT EXISTS (SELECT 1 FROM public.organization_members m
                 WHERE m.user_id = p_user AND m.organization_id = p_org)
      OR EXISTS (SELECT 1 FROM public.users u
                 WHERE u.id = p_user
                   AND (u.organization_id = p_org OR p_org = ANY (coalesce(u.can_access_organizations, '{}'))));
$$;


ALTER FUNCTION "public"."users_guard_can_use_org"("p_user" "uuid", "p_org" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."users_guard_privileged_columns"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_super boolean;
BEGIN
  IF current_user NOT IN ('authenticated', 'anon') THEN
    RETURN NEW;
  END IF;

  v_super := public.users_guard_caller_is_super_admin();

  IF TG_OP = 'INSERT' THEN
    NEW.is_super_admin := false;
    NEW.can_access_organizations := NULL;
    NEW.impersonating_organization_id := NULL;
    NEW.active_organization_id := NULL;
    RETURN NEW;
  END IF;

  IF NOT v_super AND (
       NEW.id IS DISTINCT FROM OLD.id
    OR NEW.is_super_admin IS DISTINCT FROM OLD.is_super_admin
    OR NEW.can_access_organizations IS DISTINCT FROM OLD.can_access_organizations
    OR NEW.organization_id IS DISTINCT FROM OLD.organization_id
    OR NEW.role IS DISTINCT FROM OLD.role
    OR NEW.is_active IS DISTINCT FROM OLD.is_active
  ) THEN
    RAISE EXCEPTION 'Not allowed to modify privileged user fields' USING ERRCODE = '42501';
  END IF;

  IF NEW.impersonating_organization_id IS DISTINCT FROM OLD.impersonating_organization_id
     AND NEW.impersonating_organization_id IS NOT NULL
     AND NOT v_super THEN
    RAISE EXCEPTION 'Only super admins can impersonate organizations' USING ERRCODE = '42501';
  END IF;

  IF NEW.active_organization_id IS DISTINCT FROM OLD.active_organization_id
     AND NEW.active_organization_id IS NOT NULL
     AND NOT v_super
     AND NOT public.users_guard_can_use_org(OLD.id, NEW.active_organization_id) THEN
    RAISE EXCEPTION 'You do not have access to this organization' USING ERRCODE = '42501';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."users_guard_privileged_columns"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_api_token"("p_token_hash" "text") RETURNS TABLE("token_id" "uuid", "user_id" "uuid", "organization_id" "uuid", "scopes" "text"[])
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_record RECORD;
BEGIN
  SELECT t.id, t.user_id, t.organization_id, t.scopes, t.expires_at, t.revoked_at
  INTO v_record
  FROM public.api_tokens t
  WHERE t.token_hash = p_token_hash;

  IF NOT FOUND THEN RETURN; END IF;
  IF v_record.revoked_at IS NOT NULL THEN RETURN; END IF;
  IF v_record.expires_at IS NOT NULL AND v_record.expires_at < now() THEN RETURN; END IF;

  UPDATE public.api_tokens SET last_used_at = now() WHERE id = v_record.id;

  RETURN QUERY SELECT v_record.id, v_record.user_id, v_record.organization_id, v_record.scopes;
END;
$$;


ALTER FUNCTION "public"."validate_api_token"("p_token_hash" "text") OWNER TO "postgres";


