CREATE OR REPLACE FUNCTION "public"."wake_event_snoozed_conversations"() RETURNS integer
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  woken INTEGER := 0;
  w INT;
BEGIN
  -- Wake OOO-based snoozes where return date has passed
  UPDATE public.crm_conversations
  SET status = 'open',
      snoozed_until = NULL,
      snooze_type = 'timed',
      snooze_context = '{}',
      updated_at = now()
  WHERE status = 'snoozed'
    AND snooze_type = 'until_ooo_ends'
    AND snooze_context->>'parsed_return_date' IS NOT NULL
    AND (snooze_context->>'parsed_return_date')::DATE <= CURRENT_DATE;
  GET DIAGNOSTICS w = ROW_COUNT;
  woken := woken + w;

  -- Wake timezone-morning snoozes where target time has passed
  UPDATE public.crm_conversations
  SET status = 'open',
      snoozed_until = NULL,
      snooze_type = 'timed',
      snooze_context = '{}',
      updated_at = now()
  WHERE status = 'snoozed'
    AND snooze_type = 'until_timezone_morning'
    AND snoozed_until IS NOT NULL
    AND snoozed_until <= now();
  GET DIAGNOSTICS w = ROW_COUNT;
  woken := woken + w;

  RETURN woken;
END;
$$;


ALTER FUNCTION "public"."wake_event_snoozed_conversations"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."warmup_scheduler_alert_state"("p_mailbox_ids" "uuid"[]) RETURNS TABLE("mailbox_id" "uuid", "opportunity_days" integer, "eligible_days" integer, "latest_reason" "text", "last_activity_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH requested AS (
    SELECT m.id FROM public.email_mailboxes m WHERE m.id = ANY(p_mailbox_ids)
  ), activity AS (
    SELECT r.id, accepted.sent_at AS last_activity
    FROM requested r LEFT JOIN LATERAL (
      SELECT w.sent_at FROM public.email_warmup_sends w
      WHERE w.from_mailbox_id = r.id AND w.status IN ('sent', 'delivered', 'bounced')
        AND w.sent_at IS NOT NULL
      ORDER BY w.sent_at DESC LIMIT 1
    ) accepted ON true
  )
  SELECT a.id,
    count(d.day) FILTER (WHERE d.had_opportunity)::integer,
    count(d.day) FILTER (WHERE d.last_reason NOT IN ('off_day', 'ineligible'))::integer,
    (SELECT latest.last_reason FROM public.warmup_scheduler_daily latest
     WHERE latest.mailbox_id = a.id ORDER BY latest.day DESC, latest.last_seen_at DESC LIMIT 1),
    a.last_activity
  FROM activity a LEFT JOIN public.warmup_scheduler_daily d ON d.mailbox_id = a.id
    AND d.day >= (now() AT TIME ZONE 'UTC')::date - 14
    AND d.day < (now() AT TIME ZONE 'UTC')::date
    AND (a.last_activity IS NULL OR d.day > (a.last_activity AT TIME ZONE 'UTC')::date)
  GROUP BY a.id, a.last_activity;
$$;


ALTER FUNCTION "public"."warmup_scheduler_alert_state"("p_mailbox_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."warmup_today_counts"("p_mailbox_ids" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS TABLE("mailbox_id" "uuid", "sent_today" integer, "received_today" integer, "replies_today" integer, "delivered_in" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH day AS (SELECT date_trunc('day', now() AT TIME ZONE 'UTC') AS start_ts),
  outbound AS (
    SELECT from_mailbox_id AS id,
           count(*) FILTER (WHERE status <> 'failed')::int             AS sent,
           count(*) FILTER (WHERE is_reply AND status <> 'failed')::int AS replies
    FROM public.email_warmup_sends, day
    WHERE sent_at >= day.start_ts
      AND (p_mailbox_ids IS NULL OR from_mailbox_id = ANY(p_mailbox_ids))
    GROUP BY from_mailbox_id
  ),
  inbound AS (
    SELECT to_mailbox_id AS id,
           count(*) FILTER (WHERE status <> 'failed')::int   AS received,
           count(*) FILTER (WHERE status = 'delivered')::int AS delivered
    FROM public.email_warmup_sends, day
    WHERE sent_at >= day.start_ts
      AND (p_mailbox_ids IS NULL OR to_mailbox_id = ANY(p_mailbox_ids))
    GROUP BY to_mailbox_id
  )
  SELECT
    COALESCE(o.id, i.id),
    COALESCE(o.sent, 0),
    COALESCE(i.received, 0),
    COALESCE(o.replies, 0),
    COALESCE(i.delivered, 0)
  FROM outbound o
  FULL OUTER JOIN inbound i ON i.id = o.id;
$$;


ALTER FUNCTION "public"."warmup_today_counts"("p_mailbox_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."webhook_subscription_matches"("p_filters" "jsonb", "p_event_type" "text", "p_event_data" "jsonb") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE PARALLEL SAFE
    SET "search_path" TO 'public'
    AS $$
  SELECT CASE
    WHEN p_filters IS NULL THEN true
    WHEN jsonb_typeof(p_filters->'list_ids') IS DISTINCT FROM 'array' THEN true
    WHEN jsonb_array_length(p_filters->'list_ids') = 0 THEN true
    WHEN COALESCE(p_event_type, '') NOT IN ('list_member_added', 'list_member_removed') THEN true
    ELSE COALESCE(p_filters->'list_ids' @> to_jsonb(p_event_data->>'list_id'), false)
  END;
$$;


ALTER FUNCTION "public"."webhook_subscription_matches"("p_filters" "jsonb", "p_event_type" "text", "p_event_data" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."webhook_subscription_matches"("p_filters" "jsonb", "p_event_type" "text", "p_event_data" "jsonb") IS 'True when a subscription filters accept this event. Only list_ids is understood; absent or empty means every list.';



