COMMENT ON COLUMN "public"."autopilots"."paused_reason" IS 'Why the system paused this autopilot (unusable API key, repeated failures). Cleared when a user resumes it.';



COMMENT ON COLUMN "public"."autopilots"."scheduled_days" IS 'Scheduled mode: local weekdays to run on (0=Sun..6=Sat). NULL/empty = every day.';



COMMENT ON COLUMN "public"."autopilots"."only_approved_ideas" IS 'Only pick ideas whose guidelines a person approved (content_ideas.guidelines_approved_at).';



COMMENT ON COLUMN "public"."autopilots"."schedule_slots" IS 'Scheduled mode, plan each day: [{day 0-6 local, time HH:MM, blueprint_id|null}]. Non-empty replaces scheduled_times x scheduled_days; a blueprint_id pins that slot.';



CREATE OR REPLACE VIEW "public"."autopilot_pool_stats" WITH ("security_invoker"='true') AS
 SELECT "a"."id" AS "autopilot_id",
    "a"."name" AS "autopilot_name",
    "a"."organization_id",
    "count"("p"."id") AS "total_ideas",
    "count"("p"."id") FILTER (WHERE ("p"."status" = 'available'::"text")) AS "available_ideas",
    "count"("p"."id") FILTER (WHERE ("p"."status" = 'in_progress'::"text")) AS "in_progress_ideas",
    "count"("p"."id") FILTER (WHERE ("p"."status" = 'produced'::"text")) AS "produced_ideas",
    "count"("p"."id") FILTER (WHERE ("p"."status" = 'failed'::"text")) AS "failed_ideas",
    "count"("p"."id") FILTER (WHERE ("p"."status" = 'skipped'::"text")) AS "skipped_ideas",
    "round"(((("count"("p"."id") FILTER (WHERE ("p"."status" = 'produced'::"text")))::numeric / (NULLIF("count"("p"."id"), 0))::numeric) * (100)::numeric), 1) AS "completion_percentage"
   FROM ("public"."autopilots" "a"
     LEFT JOIN "public"."autopilot_idea_pools" "p" ON (("a"."id" = "p"."autopilot_id")))
  GROUP BY "a"."id", "a"."name", "a"."organization_id";


ALTER VIEW "public"."autopilot_pool_stats" OWNER TO "postgres";


