ALTER TABLE "public"."email_sending_domains" OWNER TO "postgres";


COMMENT ON COLUMN "public"."email_sending_domains"."domain_health" IS 'healthy | warning | burned | resting | no_data';



COMMENT ON COLUMN "public"."email_sending_domains"."burned_at" IS 'Timestamp when domain was marked as burned';



COMMENT ON COLUMN "public"."email_sending_domains"."replaced_by_id" IS 'ID of the domain that replaced this burned domain';



COMMENT ON COLUMN "public"."email_sending_domains"."replaces_id" IS 'ID of the burned domain this one replaced';



COMMENT ON COLUMN "public"."email_sending_domains"."reputation_blocked_at" IS 'Historical reputation observation; does not automatically pause sending.';



COMMENT ON COLUMN "public"."email_sending_domains"."reputation_block_reason" IS 'Verbatim remote SMTP rejection that triggered the block, plus the counts that met the threshold.';



COMMENT ON COLUMN "public"."email_sending_domains"."health_status" IS 'unknown=never probed; healthy=probe delivered; degrading=delivered but throttled/soft-failing; burned=hard 550 on reputation; recovering=resting, re-probe before reuse';



COMMENT ON COLUMN "public"."email_sending_domains"."rest_until" IS 'Do not send from this domain before this time. Set when marked burned.';



COMMENT ON COLUMN "public"."email_sending_domains"."clean_probe_streak" IS 'Consecutive delivered probes since the last 550/spam outcome. Drives recovering -> healthy.';



COMMENT ON COLUMN "public"."email_sending_domains"."next_probe_at" IS 'When email-domain-health-probe should next probe this domain. NULL = due now.';



COMMENT ON COLUMN "public"."email_sending_domains"."mx_verified" IS 'True when the domain''s MX record resolves to its BYO server hostname. False means the domain cannot receive replies or DMARC reports.';



COMMENT ON COLUMN "public"."email_sending_domains"."sending_paused_at" IS 'Explicit sending control. NULL means monitoring only; reputation observations never set this.';



CREATE OR REPLACE VIEW "public"."blocked_sending_domains" WITH ("security_invoker"='true') AS
 SELECT "id",
    "organization_id",
    "domain",
    "health_status",
    "rest_until",
    "last_550_at",
    "last_550_reason",
    "consecutive_550",
    "reputation_blocked_at",
    "reputation_block_reason",
    "sending_paused_at",
    "sending_pause_reason",
    "sending_paused_by"
   FROM "public"."email_sending_domains" "d"
  WHERE (NOT "public"."is_sending_domain_sendable"("id"));


ALTER VIEW "public"."blocked_sending_domains" OWNER TO "postgres";


COMMENT ON VIEW "public"."blocked_sending_domains" IS 'Explicit operator pauses and technically unusable/replaced domains. Reputation is monitoring only.';



