    "campaign_id" "uuid",
    "account_id" "uuid",
    "date" "date" DEFAULT CURRENT_DATE NOT NULL,
    "connections_sent" integer DEFAULT 0,
    "connections_accepted" integer DEFAULT 0,
    "messages_sent" integer DEFAULT 0,
    "messages_replied" integer DEFAULT 0,
    "inmails_sent" integer DEFAULT 0,
    "inmails_replied" integer DEFAULT 0,
    "profile_views" integer DEFAULT 0,
    "follows" integer DEFAULT 0,
    "post_likes" integer DEFAULT 0,
    "created_at" timestamp with time zone DEFAULT "now"(),
    "updated_at" timestamp with time zone DEFAULT "now"()
);


ALTER TABLE "public"."campaign_analytics" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."campaign_analytics_summary" AS
 SELECT "organization_id",
    "campaign_id",
    "account_id",
    "sum"("connections_sent") AS "total_connections_sent",
    "sum"("connections_accepted") AS "total_connections_accepted",
        CASE
            WHEN ("sum"("connections_sent") > 0) THEN "round"(((("sum"("connections_accepted"))::numeric / ("sum"("connections_sent"))::numeric) * (100)::numeric), 2)
            ELSE (0)::numeric
        END AS "acceptance_rate",
    "sum"("messages_sent") AS "total_messages_sent",
    "sum"("messages_replied") AS "total_messages_replied",
        CASE
            WHEN ("sum"("messages_sent") > 0) THEN "round"(((("sum"("messages_replied"))::numeric / ("sum"("messages_sent"))::numeric) * (100)::numeric), 2)
            ELSE (0)::numeric
        END AS "reply_rate",
    "sum"("inmails_sent") AS "total_inmails_sent",
    "sum"("inmails_replied") AS "total_inmails_replied",
        CASE
            WHEN ("sum"("inmails_sent") > 0) THEN "round"(((("sum"("inmails_replied"))::numeric / ("sum"("inmails_sent"))::numeric) * (100)::numeric), 2)
            ELSE (0)::numeric
        END AS "inmail_reply_rate",
    "sum"("profile_views") AS "total_profile_views",
    "sum"("follows") AS "total_follows",
    "sum"("post_likes") AS "total_post_likes",
    "min"("date") AS "first_activity_date",
    "max"("date") AS "last_activity_date"
   FROM "public"."campaign_analytics"
  GROUP BY "organization_id", "campaign_id", "account_id";


ALTER VIEW "public"."campaign_analytics_summary" OWNER TO "postgres";


