CREATE OR REPLACE VIEW "public"."diag_lock_contention_summary" AS
 SELECT "date_trunc"('minute'::"text", "captured_at") AS "minute",
    "blocking_query",
    "blocked_query",
    "count"(*) AS "samples",
    "count"(DISTINCT "blocked_pid") AS "distinct_blocked_pids",
    "round"("max"("blocked_duration_ms")) AS "worst_blocked_ms",
    "round"("max"("blocking_xact_ms")) AS "worst_blocking_xact_ms"
   FROM "public"."diag_lock_samples"
  GROUP BY ("date_trunc"('minute'::"text", "captured_at")), "blocking_query", "blocked_query"
  ORDER BY ("round"("max"("blocked_duration_ms"))) DESC NULLS LAST;


ALTER VIEW "public"."diag_lock_contention_summary" OWNER TO "postgres";


