ALTER TABLE "public"."email_send_log" OWNER TO "postgres";


COMMENT ON COLUMN "public"."email_send_log"."mailbox_id" IS 'Soft reference to email_mailboxes.id (no FK on purpose). Send history outlives mailbox deletion: unsubscribe links, stop-on-reply and analytics read it. May point at a deleted mailbox; join with LEFT JOIN / null-check lookups.';



COMMENT ON COLUMN "public"."email_send_log"."trace_checked_at" IS 'Last time email-delivery-reconcile looked this row up in the M365 message trace.';



COMMENT ON COLUMN "public"."email_send_log"."trace_attempts" IS 'Trace lookups performed for this row. Bounded so a message that never appears in the trace stops being polled.';



COMMENT ON COLUMN "public"."email_send_log"."trace_status" IS 'Verbatim M365 trace status (Delivered | Failed | Pending | Quarantined | FilteredAsSpam | Expanded | Resolved | GettingStatus), or no_trace once lookups are exhausted. NULL = never reconciled.';



