CREATE TABLE IF NOT EXISTS "public"."email_sequence_followup_rules" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "sequence_id" "uuid",
    "organization_id" "uuid" NOT NULL,
    "name" "text" NOT NULL,
    "trigger_type" "text" NOT NULL,
    "trigger_config" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "target_sequence_id" "uuid" NOT NULL,
    "delay_hours" integer DEFAULT 0 NOT NULL,
    "is_active" boolean DEFAULT true NOT NULL,
    "total_triggered" integer DEFAULT 0 NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "campaign_id" "uuid",
    "lead_magnet_campaign_id" "uuid",
    CONSTRAINT "followup_rules_source_check" CHECK ((((
CASE
    WHEN ("sequence_id" IS NOT NULL) THEN 1
    ELSE 0
END +
CASE
    WHEN ("campaign_id" IS NOT NULL) THEN 1
    ELSE 0
END) +
CASE
    WHEN ("lead_magnet_campaign_id" IS NOT NULL) THEN 1
    ELSE 0
END) = 1))
);


