CREATE OR REPLACE VIEW "public"."epv_by_source" AS
 SELECT "utm_source",
    "utm_campaign",
    "funnel_id",
    "count"(DISTINCT "id") AS "conversions",
    "sum"("revenue_cents") AS "total_revenue_cents"
   FROM "public"."conversions" "c"
  GROUP BY "utm_source", "utm_campaign", "funnel_id";


