CREATE OR REPLACE VIEW "public"."funnel_revenue" AS
 SELECT "f"."id" AS "funnel_id",
    "f"."name" AS "funnel_name",
    "f"."niche",
    "count"(DISTINCT "o"."id") AS "total_orders",
    "count"(DISTINCT "o"."customer_id") AS "unique_buyers",
    COALESCE("sum"("o"."total_cents"), (0)::bigint) AS "total_revenue_cents",
    "round"(((COALESCE("sum"("o"."total_cents"), (0)::bigint))::numeric / (NULLIF("count"(DISTINCT "o"."customer_id"), 0))::numeric), 2) AS "avg_order_value_cents"
   FROM ("public"."funnels" "f"
     LEFT JOIN "public"."orders" "o" ON ((("o"."funnel_id" = "f"."id") AND ("o"."status" = 'completed'::"text"))))
  GROUP BY "f"."id", "f"."name", "f"."niche";


ALTER VIEW "public"."funnel_revenue" OWNER TO "postgres";


