CREATE OR REPLACE VIEW "public"."funnel_step_rates" AS
 SELECT "fp"."funnel_id",
    "fp"."page_type",
    "fp"."step_order",
    "count"(DISTINCT "te"."visitor_id") FILTER (WHERE ("te"."event_type" = 'page_view'::"text")) AS "views",
    "count"(DISTINCT "te"."visitor_id") FILTER (WHERE ("te"."event_type" = ANY (ARRAY['purchase'::"text", 'oto_accept'::"text", 'checkout_start'::"text"]))) AS "conversions",
    "round"(((("count"(DISTINCT "te"."visitor_id") FILTER (WHERE ("te"."event_type" = ANY (ARRAY['purchase'::"text", 'oto_accept'::"text"]))))::numeric / (NULLIF("count"(DISTINCT "te"."visitor_id") FILTER (WHERE ("te"."event_type" = 'page_view'::"text")), 0))::numeric) * (100)::numeric), 2) AS "conversion_rate"
   FROM ("public"."funnel_pages" "fp"
     LEFT JOIN "public"."tracking_events" "te" ON (("te"."page_id" = "fp"."id")))
  GROUP BY "fp"."funnel_id", "fp"."page_type", "fp"."step_order"
  ORDER BY "fp"."step_order";


ALTER VIEW "public"."funnel_step_rates" OWNER TO "postgres";


