CREATE TABLE IF NOT EXISTS "public"."lead_list_processing_policies" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "lead_list_id" "uuid" NOT NULL,
    "enabled" boolean DEFAULT false NOT NULL,
    "analyze_icp" boolean DEFAULT false NOT NULL,
    "icp_product_id" "uuid",
    "icp_ids" "uuid"[] DEFAULT '{}'::"uuid"[] NOT NULL,
    "min_icp_score" integer,
    "find_email" boolean DEFAULT false NOT NULL,
    "email_provider" "text",
    "verify_email" boolean DEFAULT false NOT NULL,
    "verification_provider" "text" DEFAULT 'lite'::"text" NOT NULL,
    "require_valid_email" boolean DEFAULT false NOT NULL,
    "sequence_id" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "approved_destination_type" "text" DEFAULT 'none'::"text" NOT NULL,
    "approved_destination_id" "uuid",
    "email_provider_chain" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "verification_provider_chain" "text"[] DEFAULT '{lite}'::"text"[] NOT NULL,
    "no_email_list_id" "uuid",
    "unverified_email_list_id" "uuid",
    "stage_order" "text"[] DEFAULT '{icp,find_email,verify_email,enroll}'::"text"[] NOT NULL,
    "low_icp_destination_type" "text" DEFAULT 'none'::"text" NOT NULL,
    "low_icp_destination_id" "uuid",
    "no_email_destination_type" "text" DEFAULT 'none'::"text" NOT NULL,
    "no_email_destination_id" "uuid",
    "unverified_email_destination_type" "text" DEFAULT 'none'::"text" NOT NULL,
    "unverified_email_destination_id" "uuid",
    "icp_llm_provider" "text",
    "icp_llm_model" "text",
    "find_replacement_email_on_invalid" boolean DEFAULT false NOT NULL,
    "paused_at" timestamp with time zone,
    "no_source_data_destination_type" "text" DEFAULT 'none'::"text" NOT NULL,
    "no_source_data_destination_id" "uuid",
    "verify_when" "text" DEFAULT 'always'::"text" NOT NULL,
    "verify_freshness_days" integer DEFAULT 30 NOT NULL,
    "write_message" boolean DEFAULT false NOT NULL,
    "message_prompt" "text",
    "message_llm_model" "text",
    "message_temperature" numeric,
    "message_product_id" "uuid",
    "analyze_when" "text" DEFAULT 'if_stale'::"text" NOT NULL,
    "analysis_freshness_days" integer DEFAULT 30 NOT NULL,
    "write_icebreaker" boolean DEFAULT false NOT NULL,
    "icebreaker_prompt" "text",
    "icebreaker_field_key" "text" DEFAULT 'icebreaker'::"text" NOT NULL,
    "icebreaker_llm_model" "text",
    "icebreaker_temperature" numeric,
    "fetch_home_page_text" boolean DEFAULT false NOT NULL,
    CONSTRAINT "lead_list_processing_analyze_when_valid" CHECK ((("analyze_when" = ANY (ARRAY['always'::"text", 'if_stale'::"text"])) AND (("analysis_freshness_days" >= 1) AND ("analysis_freshness_days" <= 3650)))),
    CONSTRAINT "lead_list_processing_approved_destination_valid" CHECK (("approved_destination_type" = ANY (ARRAY['none'::"text", 'email_sequence'::"text", 'linkedin_campaign'::"text"]))),
    CONSTRAINT "lead_list_processing_email_provider_chain_valid" CHECK (("email_provider_chain" <@ ARRAY['apollo'::"text", 'hunter'::"text", 'prospeo'::"text", 'moltsets'::"text"])),
    CONSTRAINT "lead_list_processing_low_icp_destination_valid" CHECK (("low_icp_destination_type" = ANY (ARRAY['none'::"text", 'list'::"text", 'linkedin_campaign'::"text"]))),
    CONSTRAINT "lead_list_processing_no_email_destination_valid" CHECK (("no_email_destination_type" = ANY (ARRAY['none'::"text", 'list'::"text", 'linkedin_campaign'::"text"]))),
    CONSTRAINT "lead_list_processing_policies_icebreaker_field_key_check" CHECK (("icebreaker_field_key" ~ '^[a-z][a-z0-9_]{0,62}$'::"text")),
    CONSTRAINT "lead_list_processing_policies_min_icp_score_check" CHECK ((("min_icp_score" >= 0) AND ("min_icp_score" <= 100))),
    CONSTRAINT "lead_list_processing_policies_verification_provider_check" CHECK (("verification_provider" = ANY (ARRAY['lite'::"text", 'apify_million_verifier'::"text", 'mailtester_ninja'::"text"]))),
    CONSTRAINT "lead_list_processing_policies_verify_freshness_days_check" CHECK ((("verify_freshness_days" > 0) AND ("verify_freshness_days" <= 3650))),
    CONSTRAINT "lead_list_processing_policies_verify_when_check" CHECK (("verify_when" = ANY (ARRAY['always'::"text", 'if_stale'::"text"]))),
    CONSTRAINT "lead_list_processing_requires_analysis_for_score" CHECK ((("min_icp_score" IS NULL) OR ("analyze_icp" = true))),
    CONSTRAINT "lead_list_processing_requires_verification_for_email_gate" CHECK ((("require_valid_email" = false) OR ("verify_email" = true))),
    CONSTRAINT "lead_list_processing_stage_order_valid" CHECK ((("stage_order" @> ARRAY['icp'::"text", 'find_email'::"text", 'verify_email'::"text", 'enroll'::"text"]) AND ("stage_order" <@ ARRAY['icp'::"text", 'find_email'::"text", 'verify_email'::"text", 'enroll'::"text"]) AND ("array_length"("stage_order", 1) = 4) AND ("array_position"("stage_order", 'enroll'::"text") = 4) AND ((NOT "find_email") OR ("array_position"("stage_order", 'verify_email'::"text") > "array_position"("stage_order", 'find_email'::"text")) OR "find_replacement_email_on_invalid"))),
    CONSTRAINT "lead_list_processing_unverified_destination_valid" CHECK (("unverified_email_destination_type" = ANY (ARRAY['none'::"text", 'list'::"text", 'linkedin_campaign'::"text"]))),
    CONSTRAINT "lead_list_processing_verification_provider_chain_valid" CHECK (("verification_provider_chain" <@ ARRAY['lite'::"text", 'apify_million_verifier'::"text", 'mailtester_ninja'::"text"]))
);


ALTER TABLE "public"."lead_list_processing_policies" OWNER TO "postgres";


COMMENT ON COLUMN "public"."lead_list_processing_policies"."approved_destination_id" IS 'Email sequence or LinkedIn campaign used for contacts that complete the configured processing pipeline.';



COMMENT ON COLUMN "public"."lead_list_processing_policies"."email_provider_chain" IS 'Ordered email-enrichment providers. Each provider is tried only when the previous one does not produce an email.';



COMMENT ON COLUMN "public"."lead_list_processing_policies"."no_email_list_id" IS 'Optional recovery list for contacts still missing an email after the configured provider chain.';



COMMENT ON COLUMN "public"."lead_list_processing_policies"."unverified_email_list_id" IS 'Optional recovery list for contacts whose email is not valid after the configured verification provider chain.';



COMMENT ON COLUMN "public"."lead_list_processing_policies"."write_message" IS 'Generate a personalized email sequence per contact before enrolling. Only honoured when approved_destination_type = ''email_sequence''.';



COMMENT ON COLUMN "public"."lead_list_processing_policies"."message_prompt" IS 'Creative brief passed to generate-email-sequence. Supports {{variables}} (contact, ai_*, product) resolved per contact.';



COMMENT ON COLUMN "public"."lead_list_processing_policies"."message_product_id" IS 'Optional library_products row injected as product context into the AI prompt.';



COMMENT ON COLUMN "public"."lead_list_processing_policies"."analyze_when" IS 'always = re-run company analysis for every contact; if_stale = reuse an analysis newer than analysis_freshness_days when it was scoped to the same product + ICPs.';



COMMENT ON COLUMN "public"."lead_list_processing_policies"."write_icebreaker" IS 'When true, generate a one-line AI icebreaker per contact just before routing and store it on crm_contacts.custom_fields under icebreaker_field_key. Requires analyze_icp. Fails soft.';



COMMENT ON COLUMN "public"."lead_list_processing_policies"."icebreaker_prompt" IS 'Creative brief for the icebreaker. Same {{variables}} as message_prompt; unknown tokens are stripped by generate-email-sequence.';



COMMENT ON COLUMN "public"."lead_list_processing_policies"."icebreaker_field_key" IS 'crm_contacts.custom_fields key the icebreaker is written to. Referenced in copy as {{custom_<field_key>}}.';



COMMENT ON COLUMN "public"."lead_list_processing_policies"."fetch_home_page_text" IS 'When true, the enroll stage looks up each contact''s company_website via QuickEnrich Company Finder (include_full_text) and writes the result to crm_contacts.home_page_text. Fails soft -- never blocks enrollment.';



