    "comment_reply_templates" "text"[] DEFAULT ARRAY['Hey {name}! Connect with me and I''ll send it right over!'::"text", 'Hi {name}! Let''s connect and I''ll get that to you!'::"text", '{name} - connect with me and I''ll DM you the link!'::"text", 'Thanks {name}! Send me a connection request and I''ll share it with you!'::"text", 'Hey {name}! Add me and I''ll send it your way!'::"text"],
    "require_connection_for_linkedin" boolean DEFAULT true,
    "auto_send_on_connection" boolean DEFAULT true,
    "auto_accept_connections" boolean DEFAULT true,
    "icp_id" "uuid",
    "icp_threshold" integer DEFAULT 0,
    "ai_chatbot_enabled" boolean DEFAULT false,
    "ai_chatbot_instructions" "text",
    "ai_chatbot_brand_voice_id" "uuid",
    "ai_chatbot_model" "text" DEFAULT 'anthropic/claude-3.5-sonnet'::"text",
    "ai_chatbot_max_turns" integer DEFAULT 10,
    "ai_chatbot_handoff_keywords" "text"[] DEFAULT '{}'::"text"[],
    "auto_add_posts" boolean DEFAULT false,
    "smart_config" "jsonb" DEFAULT '{}'::"jsonb",
    "autopilot_config" "jsonb",
    "ai_mode" character varying(20) DEFAULT 'chatbot_only'::character varying,
    "agent_profile_id" "uuid",
    "status" "text" DEFAULT 'active'::"text",
    "comment_link_mode" "text" DEFAULT 'gated'::"text",
    CONSTRAINT "comment_link_mode_check" CHECK (("comment_link_mode" = ANY (ARRAY['gated'::"text", 'direct'::"text"]))),
    CONSTRAINT "unipile_campaigns_icp_threshold_check" CHECK ((("icp_threshold" >= 0) AND ("icp_threshold" <= 100))),
    CONSTRAINT "unipile_campaigns_status_check" CHECK (("status" = ANY (ARRAY['draft'::"text", 'active'::"text", 'paused'::"text"])))
);


