COMMENT ON COLUMN "public"."unipile_campaigns"."icp_id" IS 'ICP to score commenters against; NULL = no ICP filtering';



COMMENT ON COLUMN "public"."unipile_campaigns"."icp_threshold" IS 'Minimum ICP score (0-100) for a lead to qualify; 0 = accept all';



