CREATE OR REPLACE VIEW "public"."lead_magnet_campaign_metrics" AS
 SELECT "c"."organization_id",
    "c"."id" AS "campaign_id",
    "c"."name" AS "campaign_name",
    "count"("e".*) FILTER (WHERE ("e"."event_type" = 'page_view'::"text")) AS "page_views",
    "count"("e".*) FILTER (WHERE ("e"."event_type" = 'email_captured'::"text")) AS "emails_captured",
    "count"("e".*) FILTER (WHERE ("e"."event_type" = 'resource_click'::"text")) AS "resource_clicks",
    "count"(DISTINCT "cap"."lead_id") AS "unique_captured_leads"
   FROM (("public"."unipile_campaigns" "c"
     LEFT JOIN "public"."lead_magnet_events" "e" ON (("e"."campaign_id" = "c"."id")))
     LEFT JOIN "public"."lead_magnet_captures" "cap" ON (("cap"."campaign_id" = "c"."id")))
  GROUP BY "c"."organization_id", "c"."id", "c"."name";


