COMMENT ON TABLE "public"."linkedin_campaigns" IS 'LinkedIn outreach campaigns with visual sequence builder';



COMMENT ON COLUMN "public"."linkedin_campaigns"."stop_on_reply" IS 'When true, campaign progress is automatically marked as "replied" when a lead sends a message. Default: true';



