CREATE OR REPLACE VIEW "public"."linkedin_connections_view" AS
 SELECT "cc"."id",
    "ci"."linked_account_ids"[1] AS "account_id",
    "ci"."platform_user_id" AS "linkedin_id",
    "cc"."primary_linkedin_url" AS "linkedin_url",
    "cc"."first_name",
    "cc"."last_name",
    "cc"."display_name" AS "full_name",
    ("ci"."platform_metadata" ->> 'headline'::"text") AS "headline",
    "cc"."job_title",
    "cc"."company",
    ("ci"."platform_metadata" ->> 'location'::"text") AS "location",
    "cc"."avatar_url" AS "profile_picture_url",
    "cc"."linkedin_connected_at" AS "connected_at",
    "cc"."updated_at" AS "synced_at",
    "cc"."organization_id",
    "ci"."raw_connection_data" AS "raw_data",
    "ci"."linked_account_ids"
   FROM ("public"."crm_contacts" "cc"
     JOIN "public"."crm_contact_identities" "ci" ON (("ci"."contact_id" = "cc"."id")))
  WHERE (("ci"."channel" = 'linkedin'::"text") AND ("cc"."is_linkedin_connection" = true));


ALTER VIEW "public"."linkedin_connections_view" OWNER TO "postgres";


COMMENT ON VIEW "public"."linkedin_connections_view" IS 'Backward-compatible view for accessing LinkedIn connections from CRM contacts';



