    "default_image_to_video_updated_at" timestamp with time zone,
    "default_tts_model" "text",
    "default_tts_updated_at" timestamp with time zone,
    "default_world_simulator_model" "text",
    "default_world_simulator_updated_at" timestamp with time zone,
    "user_persona" "text",
    "setup_completed" boolean DEFAULT false,
    "checklist_dismissed" boolean DEFAULT false,
    "checklist_state" "jsonb" DEFAULT '{}'::"jsonb",
    "first_generation_at" timestamp with time zone,
    "activated_at" timestamp with time zone,
    "hide_non_outreach_inbound" boolean DEFAULT false NOT NULL,
