COMMENT ON TABLE "public"."organization_settings" IS 'Multi-tenant agency system settings for each organization';



COMMENT ON COLUMN "public"."organization_settings"."default_llm_model" IS 'Default OpenRouter model selected by the organization (e.g., anthropic/claude-3.5-sonnet)';



COMMENT ON COLUMN "public"."organization_settings"."default_llm_model_updated_at" IS 'Timestamp when the default model was last updated';



COMMENT ON COLUMN "public"."organization_settings"."default_image_generator_model" IS 'Default Text-to-Image model (e.g., DALL-E, Flux)';



COMMENT ON COLUMN "public"."organization_settings"."default_image_to_video_model" IS 'Default Image-to-Video model (e.g., Runway, Pika)';



COMMENT ON COLUMN "public"."organization_settings"."default_tts_model" IS 'Default Text-to-Speech model (e.g., ElevenLabs voices)';



COMMENT ON COLUMN "public"."organization_settings"."default_world_simulator_model" IS 'Default World Simulator model for T2V (e.g., Sora, Veo)';



COMMENT ON COLUMN "public"."organization_settings"."hide_non_outreach_inbound" IS 'Opt-in: suppress reply alerts for inbound mail from addresses this org never emailed through ACA. Only safe for orgs whose outbound actually runs through ACA.';



COMMENT ON COLUMN "public"."organization_settings"."analysis_concurrency_limit" IS 'Per-org override for the analyze-company in-flight concurrency cap (analysis_concurrency_slots). NULL uses the platform default of 12. Bounded to 40 to keep a single org from reproducing the 2026-07-16 crawl4ai/OpenRouter saturation incident.';



COMMENT ON COLUMN "public"."organization_settings"."default_brand_voice_id" IS 'Brand Kit default brand voice. Used by runs and autopilots when nothing more specific is pinned. Consumers must still check organization_id on the element.';



COMMENT ON COLUMN "public"."organization_settings"."default_icp_id" IS 'Brand Kit default audience (library_icps).';



COMMENT ON COLUMN "public"."organization_settings"."default_product_id" IS 'Brand Kit default product (library_products).';



COMMENT ON COLUMN "public"."organization_settings"."default_character_id" IS 'Brand Kit default person (library_characters): face and voice for images and video.';



