ALTER TABLE "public"."organizations" OWNER TO "postgres";


COMMENT ON COLUMN "public"."organizations"."inbox_visibility_mode" IS 'Controls which conversations team members can see: all = everyone sees all, assigned_only = members see only assigned to them + unassigned, own_accounts_only = members see conversations from their accounts + assigned to them + unassigned. Admins/owners always bypass.';



COMMENT ON COLUMN "public"."organizations"."network_status" IS 'ACA Network access: none, pending (applied), approved, rejected, suspended. Changes only through request_network_access / review_network_access.';



COMMENT ON COLUMN "public"."organizations"."network_only" IS 'True for a self-hosted ACA install that uses only network services (no $67 hosted plan).';



COMMENT ON COLUMN "public"."organizations"."network_billing_ready_at" IS 'When a default card was saved for network usage billing (Stripe setup-mode checkout).';



