    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "subscription_id" "uuid" NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "list_building_job_id" "uuid",
    "status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "contacts_added" integer DEFAULT 0 NOT NULL,
    "contacts_skipped" integer DEFAULT 0 NOT NULL,
    "errors" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "started_at" timestamp with time zone,
    "finished_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "apify_runs" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "poll_lock_until" timestamp with time zone,
    CONSTRAINT "pack_refresh_jobs_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'running'::"text", 'completed'::"text", 'failed'::"text", 'cancelled'::"text"])))
);


ALTER TABLE "public"."pack_refresh_jobs" OWNER TO "postgres";


COMMENT ON COLUMN "public"."pack_refresh_jobs"."apify_runs" IS 'Array of Apify run records: [{run_id, dataset_id, signal_type, module_key, status, started_at, finished_at, error, items_processed}]. status: pending|succeeded|failed|webhook_received. The webhook handler appends results in-place.';



COMMENT ON COLUMN "public"."pack_refresh_jobs"."poll_lock_until" IS 'Set by list-building-apify-poller before processing this job''s apify_runs. Other concurrent invocations skip jobs whose lock has not expired. Prevents the same dataset from being double-processed when run-completion takes longer than the 2-min poll interval — which would otherwise insert duplicate signal_activity_log rows and double-charge the daily_cap.';



CREATE TABLE IF NOT EXISTS "public"."pack_subscriptions" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "pack_key" "text" NOT NULL,
    "tier" "text" NOT NULL,
    "status" "text" DEFAULT 'active'::"text" NOT NULL,
    "config" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "lead_list_id" "uuid",
    "refresh_cadence" "text" DEFAULT 'daily'::"text" NOT NULL,
    "next_refresh_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "last_refreshed_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "icp_product_id" "uuid",
    "min_icp_score" integer DEFAULT 70,
    "review_band" integer DEFAULT 10,
    "destination_type" "text",
    "destination_id" "uuid",
    "daily_cap" integer DEFAULT 50,
    "weekly_cap" integer DEFAULT 200,
    "signal_types" "text"[] DEFAULT ARRAY[]::"text"[],
    "stale_after_days" integer DEFAULT 7,
    "icp_id" "uuid",
    "name" "text",
    "smart_list_id" "uuid",
    "deleted_at" timestamp with time zone,
    "refresh_interval_minutes" integer,
    "is_public" boolean DEFAULT false NOT NULL,
    "public_share_token" "text",
    "public_published_at" timestamp with time zone,
    CONSTRAINT "pack_subscriptions_custom_interval_required" CHECK ((("refresh_cadence" <> 'custom'::"text") OR (("refresh_interval_minutes" IS NOT NULL) AND ("refresh_interval_minutes" >= 60)))),
    CONSTRAINT "pack_subscriptions_daily_cap_check" CHECK ((("daily_cap" IS NULL) OR ("daily_cap" > 0))),
    CONSTRAINT "pack_subscriptions_destination_type_check" CHECK ((("destination_type" IS NULL) OR ("destination_type" = ANY (ARRAY['campaign'::"text", 'sequence'::"text", 'holding'::"text"])))),
    CONSTRAINT "pack_subscriptions_interval_minutes_positive" CHECK ((("refresh_interval_minutes" IS NULL) OR ("refresh_interval_minutes" >= 60))),
    CONSTRAINT "pack_subscriptions_min_icp_score_check" CHECK ((("min_icp_score" IS NULL) OR (("min_icp_score" >= 0) AND ("min_icp_score" <= 100)))),
    CONSTRAINT "pack_subscriptions_refresh_cadence_check" CHECK (("refresh_cadence" = ANY (ARRAY['daily'::"text", 'weekly'::"text", 'monthly'::"text", 'custom'::"text"]))),
    CONSTRAINT "pack_subscriptions_review_band_check" CHECK ((("review_band" IS NULL) OR (("review_band" >= 0) AND ("review_band" <= 50)))),
    CONSTRAINT "pack_subscriptions_stale_after_days_check" CHECK ((("stale_after_days" IS NULL) OR ("stale_after_days" > 0))),
    CONSTRAINT "pack_subscriptions_status_check" CHECK (("status" = ANY (ARRAY['active'::"text", 'paused'::"text", 'cancelled'::"text", 'deleted'::"text"]))),
    CONSTRAINT "pack_subscriptions_tier_check" CHECK (("tier" = ANY (ARRAY['signal'::"text", 'trade'::"text", 'pro_services'::"text"]))),
    CONSTRAINT "pack_subscriptions_weekly_cap_check" CHECK ((("weekly_cap" IS NULL) OR ("weekly_cap" > 0)))
);


ALTER TABLE "public"."pack_subscriptions" OWNER TO "postgres";


COMMENT ON COLUMN "public"."pack_subscriptions"."icp_product_id" IS 'Optional product whose ICP fit drives signal-record scoring. Null = no ICP filter, all signals enroll.';



COMMENT ON COLUMN "public"."pack_subscriptions"."review_band" IS 'Score points BELOW min_icp_score that route to signal_review_queue instead of auto-dropping. 0 = no review queue.';



COMMENT ON COLUMN "public"."pack_subscriptions"."destination_type" IS '''campaign'' (linkedin_campaigns), ''sequence'' (email_sequences), or ''holding'' (lead_lists). Null = leads stay on the pack''s lead_list only.';



COMMENT ON COLUMN "public"."pack_subscriptions"."smart_list_id" IS 'Auto-created smart list (lead_lists.is_smart=TRUE) whose filter targets this signal''s discovery_metadata. Campaigns and email sequences point at this list to receive the matched leads via enroll_smart_list_into_active_campaigns().';



COMMENT ON COLUMN "public"."pack_subscriptions"."deleted_at" IS 'Soft-delete tombstone. When non-null, the signal is hidden from the UI and pack-refresh cron skips it. Smart list (smart_list_id) and lead list (lead_list_id) remain live so previously-found contacts stay accessible and any campaigns wired to those lists keep working.';



COMMENT ON COLUMN "public"."pack_subscriptions"."public_share_token" IS 'Stable opaque token used by public read-only signal RPCs. Never exposes organization-scoped private tables directly.';



