);


ALTER TABLE "public"."public_signals" OWNER TO "postgres";


COMMENT ON TABLE "public"."public_signals" IS 'Source of truth for the public /signals marketing feed. Pushed via MCP/CLI/scraper. published=false hides a row. People join from public_signal_people by lower(company_name).';



CREATE OR REPLACE VIEW "public"."public_signal_eligible_people" AS
 WITH "company_domain" AS MATERIALIZED (
         SELECT DISTINCT ON (("lower"("s"."company_name"))) "lower"("s"."company_name") AS "company_key",
            "s"."domain"
           FROM "public"."public_signals" "s"
          WHERE "s"."published"
          ORDER BY ("lower"("s"."company_name")), "s"."signal_date" DESC, "s"."quality_score" DESC, "s"."created_at" DESC
        ), "senior_people" AS MATERIALIZED (
         SELECT "pe"."id",
            "pe"."company_key",
            "pe"."company_linkedin_url",
            "pe"."domain",
            "pe"."full_name",
            "pe"."title",
            "pe"."linkedin_url",
            "pe"."photo_url",
            "pe"."seniority_rank",
            "pe"."source",
            "pe"."enriched_at",
            "pe"."email",
            "pe"."email_status"
           FROM "public"."public_signal_people" "pe"
          WHERE "public"."signal_person_is_eligible"("pe"."linkedin_url", "pe"."title")
        ), "eligible" AS (
         SELECT "lower"("pe"."company_key") AS "company_key",
            "pe"."id" AS "person_id",
            "pe"."full_name",
            "pe"."title",
            "pe"."linkedin_url",
            "pe"."photo_url",
            "pe"."email",
            "pe"."email_status",
            "pe"."seniority_rank",
            "pe"."enriched_at",
            "pe"."domain" AS "person_domain",
            "cd"."domain" AS "company_domain",
            "row_number"() OVER (PARTITION BY ("lower"("pe"."company_key")), ("lower"("btrim"("pe"."full_name"))) ORDER BY (NULLIF("pe"."email", ''::"text") IS NOT NULL) DESC, ("pe"."linkedin_url" !~* '/in/ACw'::"text") DESC, "pe"."seniority_rank" DESC NULLS LAST, "pe"."enriched_at" DESC) AS "dup_rank"
           FROM ("senior_people" "pe"
             JOIN "company_domain" "cd" ON (("cd"."company_key" = "lower"("pe"."company_key"))))
          WHERE ("public"."signal_domain_agrees"("pe"."domain", "cd"."domain") AND (NOT (EXISTS ( SELECT 1
                   FROM "public"."public_signal_people_takedowns" "td"
                  WHERE ((("td"."scope" = 'company'::"text") AND ("lower"("td"."company_key") = "lower"("pe"."company_key"))) OR (("td"."scope" = 'person'::"text") AND ("td"."linkedin_url" = "pe"."linkedin_url")))))))
        )
 SELECT "company_key",
    "person_id",
    "full_name",
    "title",
    "linkedin_url",
    "photo_url",
    "email",
    "email_status",
    "seniority_rank",
    "enriched_at",
    "person_domain",
    "company_domain",
    "row_number"() OVER (PARTITION BY "company_key" ORDER BY "seniority_rank" DESC NULLS LAST, ("photo_url" IS NOT NULL) DESC, "enriched_at" DESC) AS "person_rank",
    "count"(*) OVER (PARTITION BY "company_key") AS "company_people_count"
   FROM "eligible"
  WHERE ("dup_rank" = 1);


ALTER VIEW "public"."public_signal_eligible_people" OWNER TO "postgres";


COMMENT ON VIEW "public"."public_signal_eligible_people" IS 'Single source of truth for WHO is an eligible decision-maker on a published signal: company-domain gate, seniority + URL eligibility, takedowns, same-person dedupe. Uncapped -- callers that enroll use their own cap. Never query public_signal_people directly.';



