CREATE OR REPLACE VIEW "public"."public_signal_visible_people" AS
 SELECT "company_key",
    "person_id",
    "full_name",
    "title",
    "linkedin_url",
    "photo_url",
    "email",
    "email_status",
    "seniority_rank",
    "enriched_at",
    "person_domain",
    "company_domain",
    "person_rank",
    LEAST("company_people_count", (8)::bigint) AS "company_people_count"
   FROM "public"."public_signal_eligible_people"
  WHERE ("person_rank" <= 8);


