    "event_cluster_key" "text" GENERATED ALWAYS AS (COALESCE(NULLIF(("data" ->> 'event_cluster_key'::"text"), ''::"text"), NULLIF(("data" ->> 'signal_dedup_key'::"text"), ''::"text"), NULLIF(("data" ->> 'evidence_url'::"text"), ''::"text"), ((NULLIF(("data" ->> 'company_name'::"text"), ''::"text") || '|'::"text") || COALESCE(("data" ->> 'signal_date'::"text"), ''::"text")))) STORED
);


