CREATE POLICY "Admins can create invitations" ON "public"."invitations" FOR INSERT TO "authenticated" WITH CHECK ("public"."can_manage_client_org"("organization_id", ARRAY['owner'::"text", 'admin'::"text"]));



CREATE POLICY "Admins can delete invitations" ON "public"."invitations" FOR DELETE TO "authenticated" USING ("public"."can_manage_client_org"("organization_id", ARRAY['owner'::"text", 'admin'::"text"]));



CREATE POLICY "Admins can delete members" ON "public"."organization_members" FOR DELETE USING (("public"."check_org_membership"("organization_id", ARRAY['owner'::"text", 'admin'::"text"]) OR "public"."is_super_admin"(( SELECT "auth"."uid"() AS "uid"))));



CREATE POLICY "Admins can delete their organization's branding" ON "public"."organization_branding" FOR DELETE USING (("organization_id" IN ( SELECT "organization_members"."organization_id"
   FROM "public"."organization_members"
  WHERE (("organization_members"."user_id" = "auth"."uid"()) AND ("organization_members"."role" = ANY (ARRAY['owner'::"text", 'admin'::"text"]))))));



CREATE POLICY "Admins can insert members" ON "public"."organization_members" FOR INSERT WITH CHECK (("public"."check_org_membership"("organization_id", ARRAY['owner'::"text", 'admin'::"text"]) OR "public"."is_super_admin"(( SELECT "auth"."uid"() AS "uid"))));



CREATE POLICY "Admins can insert their organization's branding" ON "public"."organization_branding" FOR INSERT WITH CHECK (("organization_id" IN ( SELECT "organization_members"."organization_id"
   FROM "public"."organization_members"
  WHERE (("organization_members"."user_id" = "auth"."uid"()) AND ("organization_members"."role" = ANY (ARRAY['owner'::"text", 'admin'::"text"]))))));



CREATE POLICY "Admins can manage calendar accounts" ON "public"."calendar_accounts" USING (("organization_id" IN ( SELECT "organization_members"."organization_id"
   FROM "public"."organization_members"
  WHERE (("organization_members"."user_id" = "auth"."uid"()) AND ("organization_members"."role" = ANY (ARRAY['owner'::"text", 'admin'::"text"]))))));



CREATE POLICY "Admins can manage calendar preferences" ON "public"."calendar_preferences" USING (("organization_id" IN ( SELECT "organization_members"."organization_id"
   FROM "public"."organization_members"
  WHERE (("organization_members"."user_id" = "auth"."uid"()) AND ("organization_members"."role" = ANY (ARRAY['owner'::"text", 'admin'::"text"]))))));



CREATE POLICY "Admins can manage meeting templates" ON "public"."meeting_templates" USING (("organization_id" IN ( SELECT "organization_members"."organization_id"
   FROM "public"."organization_members"
  WHERE (("organization_members"."user_id" = "auth"."uid"()) AND ("organization_members"."role" = ANY (ARRAY['owner'::"text", 'admin'::"text"]))))));



CREATE POLICY "Admins can manage their organization's domains" ON "public"."organization_domains" USING (("organization_id" IN ( SELECT "organization_members"."organization_id"
   FROM "public"."organization_members"
